"""
Auto-converted tinyllama_programs.py (TinyLlama-1.1B).
Signature: (sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]
22 layers x 32 heads = 704 programs. L5H20 missing from source — stub added.
embedding_similarity replaced with character-overlap approximation.
"""
import numpy as np
from transformers import PreTrainedTokenizerBase
from typing import Tuple

_nlp = None
def _get_nlp():
    global _nlp
    if _nlp is None:
        import spacy
        _nlp = spacy.load("en_core_web_sm")
    return _nlp

def spacy_parse(sentence: str):
    return _get_nlp()(sentence)

def _align_to_spacy(sentence: str, tokens: list) -> list:
    doc = _get_nlp()(sentence)
    spans, pos = [], 0
    for t in tokens:
        clean = t.lstrip("\u0120").lstrip("##").lstrip()
        span_len = max(len(clean), 1)
        spans.append((pos, pos + span_len))
        pos += span_len
    alignment = []
    for gs, ge in spans:
        overlapping = [si for si, st in enumerate(doc)
                       if st.idx < ge and st.idx + len(st.text) > gs]
        alignment.append(overlapping)
    return alignment

def _char_sim(a: str, b: str) -> float:
    """Character-overlap similarity as embedding_similarity proxy."""
    sa, sb = set(a.lower()), set(b.lower())
    return len(sa & sb) / max(len(sa | sb), 1)

def make_row_stochastic(matrix: np.ndarray) -> np.ndarray:
    matrix = np.clip(matrix, 0, None)
    row_sums = matrix.sum(axis=1, keepdims=True)
    row_sums[row_sums == 0] = 1.0
    return matrix / row_sums

def apply_causal_mask(matrix: np.ndarray) -> np.ndarray:
    n = matrix.shape[0]
    return matrix * np.tril(np.ones((n, n)))


def prog_L0H0(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Local attention head with semantic similarity, punctuation focus, and sentence-initial boosting."""
    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L0H0", np.zeros((n_empty, n_empty))

    # Initialize attention matrix
    attention = np.zeros((n, n))

    # Get spacy alignment for linguistic features
    spacy_alignment = _align_to_spacy(sentence, tokens)
    doc = spacy_parse(sentence)

    for i in range(n):
        current_token = tokens[i].strip()

        # Strong self-attention for punctuation, especially quotes
        if current_token in ['"', "'", "!", "?", ".", ","]:
            attention[i, i] = 0.8
            if current_token == '"':
                attention[i, i] = 0.9
        else:
            attention[i, i] = 0.3

        # Previous token attention with decay
        for j in range(max(0, i-5), i):
            prev_token = tokens[j].strip()

            # Distance-based weight
            distance = i - j
            base_weight = 0.6 / (distance ** 0.8)

            # Boost for punctuation targets
            if prev_token in ['"', "'", ".", "!", "?", ",", "\n"]:
                base_weight *= 2.0

            # Boost for semantic similarity
            sim = _char_sim(tokens[i], tokens[j])
            if sim > 0.7:
                base_weight *= (1 + sim)
            elif sim > 0.5:
                base_weight *= (1 + 0.5 * sim)

            # Special patterns for sentence boundaries
            if prev_token == "\n" or j == 0:
                base_weight *= 1.5

            attention[i, j] += base_weight

        # Attention to semantically similar tokens throughout the sequence
        for j in range(i):
            if j >= max(0, i-5):  # Skip already processed recent tokens
                continue

            sim = _char_sim(tokens[i], tokens[j])
            if sim > 0.6:
                attention[i, j] += 0.3 * sim

            # Special attention to first tokens of sentences
            if j == 0 or (j > 0 and tokens[j-1].strip() == "\n"):
                attention[i, j] += 0.2

        # NEW: Boost attention to very early tokens, especially the first token
        if i > 5:  # Only for tokens far from the beginning
            # Strong boost for the very first token
            if n > 0:
                attention[i, 0] += 0.4

            # Moderate boost for other early tokens (indices 1-3)
            for early_idx in range(1, min(4, i)):
                attention[i, early_idx] += 0.2

        # Additional attention patterns for specific constructions
        if spacy_alignment[i]:
            spacy_idx = spacy_alignment[i][0]
            if spacy_idx < len(doc):
                spacy_token = doc[spacy_idx]

                # Verbs attend to their subjects
                if spacy_token.pos_ == "VERB":
                    for j in range(i):
                        if spacy_alignment[j]:
                            j_spacy = spacy_alignment[j][0]
                            if j_spacy < len(doc) and doc[j_spacy].dep_ in ["nsubj", "nsubjpass"]:
                                attention[i, j] += 0.4

                # Pronouns attend to potential antecedents
                if spacy_token.pos_ == "PRON":
                    for j in range(max(0, i-10), i):
                        if spacy_alignment[j]:
                            j_spacy = spacy_alignment[j][0]
                            if j_spacy < len(doc) and doc[j_spacy].pos_ in ["NOUN", "PROPN"]:
                                attention[i, j] += 0.3

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L0H0", attention



def prog_L0H1(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Local context and semantic similarity attention with recency bias and newline boundary tracking."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L0H1", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    for i in range(n):
        for j in range(i + 1):  # Causal mask
            weight = 0.0

            # Strong attention to immediate previous token
            if j == i - 1:
                weight += 0.4

            # Self-attention baseline
            if i == j:
                weight += 0.15

            # First token attention
            if j == 0:
                weight += 0.05

            # Semantic similarity component
            if i != j:
                sim = _char_sim(tokens[i], tokens[j])
                if sim > 0.5:
                    weight += 0.3 * sim
                elif sim > 0.2:
                    weight += 0.15 * sim

            # Recency decay for non-adjacent tokens
            if j < i - 1:
                distance = i - j
                decay = 1.0 / (1.0 + 0.5 * distance)
                weight *= decay

            # Punctuation and boundary tokens get slight boost
            if tokens[j] in ['.', ',', '\n', '!', '?']:
                weight += 0.02

            # Special case: newline tokens attending to previous newlines
            if tokens[i] == '\n' and tokens[j] == '\n' and i != j:
                # Strong attention from newlines to earlier newlines
                distance = i - j
                newline_weight = 0.8 / (1.0 + 0.1 * distance)
                weight += newline_weight

            attention[i, j] = weight

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L0H1", attention



def prog_L0H10(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Structural boundary attention with backward semantic connections and phrase-initial focus."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L0H10", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Get spacy alignment for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        # Strong self-attention baseline
        attention[i, i] = 0.3

        # Very strong attention to newlines
        for j in range(i + 1):
            if tokens[j] == '\n':
                attention[i, j] += 0.4

        # Strong attention to punctuation
        for j in range(i + 1):
            if tokens[j] in [',', '.', '!', '?', ';', ':']:
                attention[i, j] += 0.2

        # Strong attention to sentence/quote boundaries
        for j in range(i + 1):
            if tokens[j] in ['"', "'", '."', '!"', '?"']:
                attention[i, j] += 0.25

        # Backward attention with recency bias
        for j in range(max(0, i - 10), i):
            distance = i - j
            recency_weight = 1.0 / (1.0 + distance * 0.3)

            # Semantic similarity boost
            sim = _char_sim(tokens[i], tokens[j])
            if sim > 0.3:
                attention[i, j] += 0.15 * recency_weight * sim
            else:
                attention[i, j] += 0.05 * recency_weight

        # Special attention to first token
        if i > 0:
            attention[i, 0] += 0.1

        # NEW: Strong attention to phrase/clause beginnings
        # Look for tokens that start after major boundaries (newlines, sentence endings, commas)
        for j in range(i):
            is_phrase_start = False

            # Check if this token starts after a major boundary
            if j == 0:
                is_phrase_start = True
            elif j > 0:
                prev_token = tokens[j-1]
                if prev_token in ['\n', '.', '!', '?', ';', ':', ',', '"', "'", '."', '!"', '?"']:
                    is_phrase_start = True

            # If this is a phrase start, give it strong attention
            if is_phrase_start:
                distance = i - j
                # Stronger weight for phrase beginnings, less decay with distance
                phrase_weight = 0.3 / (1.0 + distance * 0.1)
                attention[i, j] += phrase_weight

        # Boost attention for tokens that are verbs or important content words
        if token_to_spacy[i]:
            spacy_idx = token_to_spacy[i][0]
            if spacy_idx < len(doc):
                spacy_token = doc[spacy_idx]
                if spacy_token.pos_ in ['VERB', 'NOUN', 'PROPN']:
                    # Look back for related content
                    for j in range(max(0, i - 8), i):
                        if token_to_spacy[j] and token_to_spacy[j][0] < len(doc):
                            other_spacy = doc[token_to_spacy[j][0]]
                            if other_spacy.pos_ in ['VERB', 'NOUN', 'PROPN']:
                                sim = _char_sim(tokens[i], tokens[j])
                                if sim > 0.2:
                                    attention[i, j] += 0.1 * sim

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L0H10", attention



def prog_L0H11(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Local morphological attention head focusing on word boundaries and token prefixes."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        token = tokens[i]

        # Strong self-attention baseline
        attention[i, i] = 0.5

        # Check if this token is a suffix of a word
        is_suffix = False
        if i > 0:
            # Check if current token could be a suffix by looking at embedding similarity
            # and if it doesn't start with a space/punctuation
            prev_token = tokens[i-1]
            if (not token.startswith(' ') and not token.startswith('\n') and 
                len(token) <= 4 and token.isalpha()):
                # Strong attention from suffix to prefix
                attention[i, i-1] = 0.8
                attention[i, i] = 0.2
                is_suffix = True

        if not is_suffix:
            # Regular token behavior

            # Attention to immediately previous token
            if i > 0:
                attention[i, i-1] = 0.3

            # Attention to nearby tokens with semantic similarity
            for j in range(max(0, i-3), i):
                if j != i-1:  # Already handled above
                    sim = _char_sim(tokens[i], tokens[j])
                    if sim > 0.5:
                        attention[i, j] = 0.2 * sim
                    else:
                        attention[i, j] = 0.05

            # Special handling for punctuation
            if token.strip() in '.,!?"':
                # Punctuation attends strongly to other punctuation
                for j in range(i):
                    if tokens[j].strip() in '.,!?"':
                        attention[i, j] = 0.4
                    elif j == i-1:
                        attention[i, j] = 0.2
                    else:
                        attention[i, j] = 0.05

            # Newlines attend to previous content
            elif token == '\n':
                for j in range(i):
                    if j == i-1:
                        attention[i, j] = 0.3
                    else:
                        attention[i, j] = 0.02

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L0H11", attention



def prog_L0H12(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Structural boundary and syntactic relation attention with enhanced period self-attention."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L0H12", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        # Self-attention baseline with enhanced period attention
        if tokens[i] == '.':
            attention[i, i] = 0.6  # Much higher self-attention for periods
        else:
            attention[i, i] = 0.1

        # Strong attention to newlines
        for j in range(i + 1):
            if tokens[j] == '\n':
                attention[i, j] += 0.8

        # First token attention
        if i > 0:
            attention[i, 0] += 0.2

        # Previous token attention
        if i > 0:
            attention[i, i-1] += 0.3

        # Syntactic relations via spacy
        if token_to_spacy[i]:
            spacy_i = token_to_spacy[i][0]
            if spacy_i < len(doc):
                current_token = doc[spacy_i]

                # Attend to head
                if current_token.head != current_token:
                    head_idx = current_token.head.i
                    for j in range(i + 1):
                        if j < len(token_to_spacy) and token_to_spacy[j] and head_idx in token_to_spacy[j]:
                            attention[i, j] += 0.5

                # Attend to children
                for child in current_token.children:
                    child_idx = child.i
                    for j in range(i + 1):
                        if j < len(token_to_spacy) and token_to_spacy[j] and child_idx in token_to_spacy[j]:
                            attention[i, j] += 0.3

        # Semantic similarity boost
        for j in range(i + 1):
            if i != j:
                sim = _char_sim(tokens[i], tokens[j])
                if sim > 0.5:
                    attention[i, j] += sim * 0.2

        # Boost attention to sentence beginnings (tokens after periods/newlines)
        for j in range(i):
            if j > 0 and (tokens[j-1] == '.' or tokens[j-1] == '\n'):
                attention[i, j] += 0.3

        # Boost for conjunctions and prepositions
        if token_to_spacy[i]:
            spacy_i = token_to_spacy[i][0]
            if spacy_i < len(doc):
                current_token = doc[spacy_i]
                if current_token.pos_ in ['CCONJ', 'SCONJ', 'ADP']:
                    for j in range(i + 1):
                        if j != i:
                            attention[i, j] += 0.1

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L0H12", attention



def prog_L0H13(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Punctuation and clause boundary attention with local context bias."""
    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L0H13", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    # Define punctuation and boundary tokens
    punctuation_chars = {'.', ',', '!', '?', ';', ':', '\n'}
    quote_chars = {'"', "'", '"', '"', "'", "'"}

    for i in range(n):
        # Self-attention baseline
        attention[i, i] = 0.1

        # Strong attention to punctuation marks
        for j in range(i + 1):
            token_j = tokens[j].strip()

            # Very high attention to punctuation
            if token_j in punctuation_chars:
                if token_j == '\n':
                    attention[i, j] += 0.4
                elif token_j == '.':
                    attention[i, j] += 0.3
                elif token_j == ',':
                    attention[i, j] += 0.2
                else:
                    attention[i, j] += 0.25

            # Attention to quotes and sentence boundaries
            if token_j in quote_chars:
                attention[i, j] += 0.15

            # First token attention
            if j == 0:
                attention[i, j] += 0.08

        # Local context patterns
        for j in range(max(0, i - 5), i + 1):
            # Recent token bias
            distance = i - j
            if distance <= 3:
                attention[i, j] += 0.05 * (4 - distance) / 4

            # Spacy-based syntactic relationships
            if token_to_spacy[i] and token_to_spacy[j]:
                spacy_i = token_to_spacy[i][0] if token_to_spacy[i] else None
                spacy_j = token_to_spacy[j][0] if token_to_spacy[j] else None

                if spacy_i is not None and spacy_j is not None and spacy_i < len(doc) and spacy_j < len(doc):
                    tok_i = doc[spacy_i]
                    tok_j = doc[spacy_j]

                    # Attention between verbs and their subjects/objects
                    if tok_i.pos_ == 'VERB' and tok_j.dep_ in ['nsubj', 'dobj', 'iobj']:
                        attention[i, j] += 0.08

                    # Attention to function words
                    if tok_j.pos_ in ['DET', 'PREP', 'CONJ', 'AUX']:
                        attention[i, j] += 0.06

                    # Attention between related content words
                    if tok_i.pos_ in ['NOUN', 'VERB', 'ADJ'] and tok_j.pos_ in ['NOUN', 'VERB', 'ADJ']:
                        sim = _char_sim(tokens[i], tokens[j])
                        if sim > 0.3:
                            attention[i, j] += 0.1 * sim

        # Special patterns for certain constructions
        token_i = tokens[i].strip().lower()
        for j in range(i + 1):
            token_j = tokens[j].strip().lower()

            # Attention patterns for specific linguistic constructions
            if token_to_spacy[i] and token_to_spacy[j]:
                spacy_i_idx = token_to_spacy[i][0] if token_to_spacy[i] else None
                spacy_j_idx = token_to_spacy[j][0] if token_to_spacy[j] else None

                if (spacy_i_idx is not None and spacy_j_idx is not None and 
                    spacy_i_idx < len(doc) and spacy_j_idx < len(doc)):

                    tok_i_spacy = doc[spacy_i_idx]
                    tok_j_spacy = doc[spacy_j_idx]

                    # Enhanced attention for clause boundaries
                    if tok_j_spacy.dep_ in ['mark', 'cc'] or tok_j_spacy.pos_ == 'SCONJ':
                        attention[i, j] += 0.12

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L0H13", attention



def prog_L0H14(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Punctuation-to-content attention with semantic similarity and recency bias."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L0H14", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        token_i = tokens[i].strip()

        # Get spacy info for token i
        spacy_indices_i = token_to_spacy[i]
        is_punct_i = len(spacy_indices_i) > 0 and all(doc[idx].is_punct for idx in spacy_indices_i)
        is_content_i = len(spacy_indices_i) > 0 and any(doc[idx].pos_ in ['NOUN', 'VERB', 'ADJ', 'ADV'] for idx in spacy_indices_i)

        for j in range(i + 1):  # Causal mask
            token_j = tokens[j].strip()

            # Get spacy info for token j
            spacy_indices_j = token_to_spacy[j]
            is_content_j = len(spacy_indices_j) > 0 and any(doc[idx].pos_ in ['NOUN', 'VERB', 'ADJ', 'ADV'] for idx in spacy_indices_j)
            is_punct_j = len(spacy_indices_j) > 0 and all(doc[idx].is_punct for idx in spacy_indices_j)

            weight = 0.0

            # Strong self-attention
            if i == j:
                weight += 0.1

            # Punctuation attending to nearby content words
            if is_punct_i and is_content_j:
                distance = i - j
                if distance <= 5:
                    weight += 0.3 * np.exp(-distance * 0.2)

            # Content words attending to similar content words
            if is_content_i and is_content_j and i != j:
                sim = _char_sim(tokens[i], tokens[j])
                if sim > 0.7:  # High similarity threshold
                    weight += 0.2 * sim

            # Recency bias - stronger attention to recent tokens
            if i != j:
                distance = i - j
                recency_weight = np.exp(-distance * 0.15)
                weight += 0.05 * recency_weight

            # Newline and sentence boundary attention
            if token_j == '\n' or (is_punct_j and token_j in '.!?'):
                weight += 0.1

            # Special handling for specific punctuation patterns
            if token_i in '.,;:' and is_content_j:
                distance = i - j
                if distance <= 3:
                    weight += 0.2

            # Boost attention between similar non-content tokens
            if not is_content_i and not is_content_j and i != j:
                sim = _char_sim(tokens[i], tokens[j])
                if sim > 0.8:
                    weight += 0.15

            attention[i, j] = weight

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L0H14", attention



def prog_L0H15(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Paragraph boundary and structural punctuation attention head with enhanced quotation focus."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    for i in range(n):
        token_i = tokens[i]

        # Base self-attention
        attention[i, i] = 0.3

        # Strong attention to newlines
        for j in range(i + 1):
            if tokens[j] == '\n':
                attention[i, j] += 0.4

        # Attention to sentence-ending punctuation
        for j in range(i + 1):
            if tokens[j] in ['.', '!', '?']:
                attention[i, j] += 0.2

        # Attention to commas and other structural punctuation
        for j in range(i + 1):
            if tokens[j] in [',', ';', ':']:
                attention[i, j] += 0.15

        # Previous token attention (recency bias)
        if i > 0:
            attention[i, i-1] += 0.25

        # Slight attention to quotation marks
        for j in range(i + 1):
            if '"' in tokens[j] or "'" in tokens[j]:
                attention[i, j] += 0.1

        # Extra attention from certain tokens to specific structural elements
        # Tokens after newlines tend to attend strongly to the newline
        if i > 0 and tokens[i-1] == '\n':
            attention[i, i-1] += 0.3

        # SPECIAL CASE: Much stronger self-attention for quotation marks
        if '"' in token_i or "'" in token_i:
            attention[i, i] += 0.4

        # Add some uniform background attention
        for j in range(i + 1):
            attention[i, j] += 0.05

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L0H15", attention



def prog_L0H16(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Local syntactic and semantic attention head with self-attention bias."""
    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L0H16", np.zeros((n_empty, n_empty))

    # Initialize attention matrix
    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        # Strong self-attention baseline
        attention[i, i] = 1.0

        # Get spacy tokens aligned to current token
        spacy_indices = token_to_spacy[i]

        for j in range(i):
            score = 0.0

            # Position-based recency bias (stronger for recent tokens)
            distance = i - j
            if distance <= 3:
                score += 0.3 / distance
            elif distance <= 10:
                score += 0.1 / distance
            else:
                score += 0.05 / distance

            # Semantic similarity bonus
            sim = _char_sim(tokens[i], tokens[j])
            if sim > 0.3:
                score += sim * 0.5

            # Syntactic patterns
            if spacy_indices:
                current_spacy = doc[spacy_indices[0]]

                # Check if current token is a function word that should attend to nearby content
                if current_spacy.pos_ in ['ADP', 'DET', 'AUX'] and distance <= 5:
                    target_spacy_indices = token_to_spacy[j]
                    if target_spacy_indices:
                        target_spacy = doc[target_spacy_indices[0]]
                        if target_spacy.pos_ in ['NOUN', 'VERB', 'ADJ', 'PROPN']:
                            score += 0.8

                # Verb attending to its subject/object
                if current_spacy.pos_ == 'VERB':
                    target_spacy_indices = token_to_spacy[j]
                    if target_spacy_indices:
                        target_spacy = doc[target_spacy_indices[0]]
                        if target_spacy.dep_ in ['nsubj', 'dobj', 'nmod']:
                            score += 0.6

                # Content words attending to related content words
                if current_spacy.pos_ in ['NOUN', 'VERB', 'ADJ'] and distance <= 8:
                    target_spacy_indices = token_to_spacy[j]
                    if target_spacy_indices:
                        target_spacy = doc[target_spacy_indices[0]]
                        if target_spacy.pos_ in ['NOUN', 'VERB', 'ADJ']:
                            score += 0.4

            # Special handling for punctuation and newlines
            if tokens[i] in ['.', '!', '?', ',']:
                # Punctuation attends to nearby sentence content
                if distance <= 3:
                    score += 0.3

            if tokens[i] == '\n':
                # Newlines attend to sentence boundaries
                if tokens[j] in ['.', '!', '?'] or j == 0:
                    score += 0.4

            attention[i, j] = score

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L0H16", attention



def prog_L0H17(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Previous-token attention with semantic similarity enhancement."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L0H17", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    for i in range(n):
        # Base attention distribution
        for j in range(i + 1):  # Causal mask
            # Strong attention to previous token
            if j == i - 1 and i > 0:
                attention[i, j] = 0.4
            # Self-attention
            elif j == i:
                attention[i, j] = 0.3
            # First token attention (especially for newlines and start of segments)
            elif j == 0 and tokens[i] in ['\n', ' ']:
                attention[i, j] = 0.2
            # Punctuation tends to attend to previous punctuation
            elif tokens[i] in ['.', ',', '!', '?'] and tokens[j] in ['.', ',', '!', '?']:
                attention[i, j] = 0.15
            else:
                # Base semantic similarity component
                sim = _char_sim(tokens[i], tokens[j])
                if sim > 0.7:  # High similarity threshold
                    attention[i, j] = 0.2 * sim
                elif sim > 0.5:  # Medium similarity
                    attention[i, j] = 0.1 * sim
                else:
                    attention[i, j] = 0.05

        # Additional patterns for specific cases
        if i >= 2:
            # Attention to tokens 2 positions back for certain contexts
            attention[i, i-2] += 0.1

        # Enhance attention based on embedding similarity to highly attended positions
        for j in range(i + 1):
            if j == i - 1 or j == i:  # Already have high base attention
                continue
            sim = _char_sim(tokens[i], tokens[j])
            if sim > 0.6:
                attention[i, j] += 0.15 * sim

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L0H17", attention



def prog_L0H18(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Punctuation-anchored attention with enhanced local dependencies and quote handling."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L0H18", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        for j in range(i + 1):  # Causal mask
            weight = 0.0

            # Base self-attention
            if i == j:
                weight += 0.02

            # Strong attention to punctuation (periods, commas, newlines)
            if tokens[j] in ['.', ',', '\n', '!', '?', ';', ':']:
                weight += 0.15
                # Extra boost for periods and newlines
                if tokens[j] in ['.', '\n']:
                    weight += 0.05

            # Recency bias - attend more to recent tokens
            distance = i - j
            if distance <= 5:
                weight += 0.03 * (6 - distance) / 6

            # Enhanced immediate predecessor attention for function words
            if distance == 1 and token_to_spacy[j] and token_to_spacy[j][0] < len(doc):
                spacy_j = doc[token_to_spacy[j][0]]
                if spacy_j.pos_ in ['DET', 'ADP', 'PREP', 'PART']:
                    weight += 0.12

            # Quote handling - tokens inside quotes attend strongly to opening quote
            if distance <= 15:  # Within reasonable quote distance
                if "'" in tokens[j] or '"' in tokens[j]:
                    # Check if we're inside a quote by looking for closing quote ahead
                    in_quote = False
                    for k in range(j + 1, min(i + 5, n)):  # Look ahead reasonably
                        if "'" in tokens[k] or '"' in tokens[k]:
                            in_quote = True
                            break
                    if in_quote:
                        weight += 0.15

            # Semantic similarity boost
            sim = _char_sim(tokens[i], tokens[j])
            if sim > 0.3:
                weight += 0.08 * sim

            # Syntactic relationships via spacy
            if token_to_spacy[i] and token_to_spacy[j]:
                spacy_i = token_to_spacy[i][0] if token_to_spacy[i] else None
                spacy_j = token_to_spacy[j][0] if token_to_spacy[j] else None

                if spacy_i is not None and spacy_j is not None and spacy_i < len(doc) and spacy_j < len(doc):
                    tok_i = doc[spacy_i]
                    tok_j = doc[spacy_j]

                    # Head-dependent relationships
                    if tok_j.head == tok_i or tok_i.head == tok_j:
                        weight += 0.06

                    # Same syntactic role
                    if tok_i.dep_ == tok_j.dep_ and tok_i.dep_ in ['nsubj', 'dobj', 'pobj']:
                        weight += 0.03

                    # Function words to content words
                    if tok_j.pos_ in ['DET', 'PREP', 'ADP'] and tok_i.pos_ in ['NOUN', 'VERB', 'ADJ']:
                        weight += 0.04

            # Special boost for whitespace tokens to content words
            if tokens[j].strip() == '' and i > j:
                weight += 0.02

            # Reduce distant punctuation attention to prevent over-prediction
            if tokens[j] in ['.', '\n'] and distance > 10:
                weight *= 0.5

            attention[i, j] = weight

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L0H18", attention



def prog_L0H19(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Previous-token attention head with syntactic, semantic, and discourse boundary enhancements."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L0H19", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    # Identify sentence/section start tokens
    sentence_starts = set()
    for i in range(n):
        token_i = tokens[i].strip()
        # First token is always a sentence start
        if i == 0:
            sentence_starts.add(i)
        # Token after sentence-ending punctuation
        elif i > 0 and tokens[i-1].strip() in ['.', '!', '?', '\n']:
            sentence_starts.add(i)
        # Common narrative beginnings
        if token_to_spacy[i]:
            spacy_i = doc[token_to_spacy[i][0]]
            if (spacy_i.text.lower() in ['once', 'then', 'he', 'she', 'they', 'it'] and 
                i > 0 and tokens[i-1].strip() in ['.', '\n', '?', '!']):
                sentence_starts.add(i)

    for i in range(n):
        # Strong attention to immediate predecessor
        if i > 0:
            attention[i, i-1] = 0.4

        # Self-attention
        attention[i, i] = 0.2

        # Attention to punctuation and sentence boundaries
        for j in range(i+1):
            token_j = tokens[j].strip()
            if token_j in ['.', '!', '?', '\n', ',', ';']:
                attention[i, j] += 0.15

        # Attention to first token
        if i > 0:
            attention[i, 0] += 0.1

        # NEW: Strong attention to sentence/section starts for punctuation and later tokens
        token_i = tokens[i].strip()
        if token_i in [',', ';', '.', '!', '?'] or i > 5:  # Punctuation or tokens well into the sequence
            for start_idx in sentence_starts:
                if start_idx < i:  # Causal constraint
                    # Strong boost for punctuation attending to sentence starts
                    if token_i in [',', ';']:
                        attention[i, start_idx] += 0.6
                    # Moderate boost for other tokens to discourse boundaries
                    else:
                        attention[i, start_idx] += 0.2

        # Syntactic and semantic relationships
        if token_to_spacy[i]:
            spacy_i = doc[token_to_spacy[i][0]]

            for j in range(i):
                if token_to_spacy[j]:
                    spacy_j = doc[token_to_spacy[j][0]]

                    # Syntactic relationships
                    if spacy_j in spacy_i.ancestors or spacy_i in spacy_j.ancestors:
                        attention[i, j] += 0.1

                    # Articles/determiners to nouns
                    if (spacy_j.pos_ in ['DET', 'ADP'] and 
                        spacy_i.pos_ in ['NOUN', 'PROPN', 'ADJ']):
                        attention[i, j] += 0.12

                    # Auxiliary verbs to main verbs
                    if (spacy_j.pos_ == 'AUX' and spacy_i.pos_ == 'VERB'):
                        attention[i, j] += 0.1

                    # Modifiers to heads
                    if spacy_j.head == spacy_i or spacy_i.head == spacy_j:
                        attention[i, j] += 0.08

        # Semantic similarity
        for j in range(i):
            sim = _char_sim(tokens[i], tokens[j])
            if sim > 0.7:  # High similarity threshold
                attention[i, j] += 0.15 * sim
            elif sim > 0.5:  # Medium similarity
                attention[i, j] += 0.08 * sim

        # Boost attention for repeated or similar tokens
        for j in range(i):
            if tokens[i].strip().lower() == tokens[j].strip().lower():
                attention[i, j] += 0.2

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L0H19", attention



def prog_L0H2(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Semantic similarity attention with local positional bias and newline aggregation."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L0H2", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Get spacy alignment for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        for j in range(i + 1):  # Causal mask
            weight = 0.0

            # Special case: newline tokens attend strongly to sentence boundaries and previous newlines
            if tokens[i] == '\n':
                if tokens[j] in ['.', '!', '?', '"', "'", '\n']:
                    # Very strong attention to sentence boundaries and previous newlines
                    weight += 0.8
                elif j > 0 and tokens[j-1] in ['.', '!', '?', '"', "'"]:
                    # Strong attention to tokens right after sentence boundaries
                    weight += 0.4
                else:
                    # Reduced baseline for other tokens when attending from newline
                    weight += 0.005
            else:
                # Original logic for non-newline tokens

                # Strong self-attention
                if i == j:
                    weight += 0.3

                # Adjacent token attention
                elif i == j + 1:
                    weight += 0.2

                # Semantic similarity component
                sim = _char_sim(tokens[i], tokens[j])
                if sim > 0.3:
                    weight += sim * 0.4

                # Distance decay for non-adjacent tokens
                if j < i - 1:
                    distance = i - j
                    decay = 1.0 / (1 + distance * 0.1)
                    weight *= decay

                # Boost for syntactically related tokens
                if token_to_spacy[i] and token_to_spacy[j]:
                    spacy_i = doc[token_to_spacy[i][0]]
                    spacy_j = doc[token_to_spacy[j][0]]

                    # Head-dependent relationships
                    if spacy_j.head == spacy_i or spacy_i.head == spacy_j:
                        weight += 0.15

                    # Same syntactic role
                    if spacy_i.dep_ == spacy_j.dep_ and spacy_i.dep_ in ['nsubj', 'dobj', 'pobj']:
                        weight += 0.1

                # Small baseline attention
                weight += 0.01

            attention[i, j] = weight

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L0H2", attention



def prog_L0H20(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Semantic similarity attention with punctuation and positional biases."""
    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L0H20", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    for i in range(n):
        for j in range(i + 1):  # Only attend to previous tokens (causal)
            # Base similarity score
            sim_score = _char_sim(tokens[i], tokens[j])

            # Self-attention boost
            if i == j:
                attention[i, j] = 0.5 + sim_score * 0.3
            else:
                # Start with semantic similarity
                score = sim_score * 0.2

                # Boost for punctuation tokens
                if tokens[j].strip() in ['.', ',', '!', '?', '\n']:
                    score += 0.15

                # Boost for nearby tokens (recency bias)
                distance = i - j
                if distance == 1:
                    score += 0.1
                elif distance <= 3:
                    score += 0.05

                # Small boost for first token
                if j == 0:
                    score += 0.03

                # Boost for tokens that are semantically very similar
                if sim_score > 0.7:
                    score += 0.1

                attention[i, j] = max(0.01, score)

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L0H20", attention



def prog_L0H21(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Punctuation and local context attention head with boundary detection."""
    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        # Get spacy tokens for current position
        spacy_indices = token_to_spacy[i]
        current_token = tokens[i].strip()

        for j in range(i + 1):  # Only attend to previous positions (causal)
            target_token = tokens[j].strip()
            weight = 0.0

            # Strong attention to punctuation, especially periods and commas
            if target_token in ['.', ',', '!', '?', ';', ':']:
                if target_token == '.':
                    weight += 0.15
                elif target_token == ',':
                    weight += 0.12
                else:
                    weight += 0.08

            # Attention to newlines (sentence boundaries)
            if target_token == '\n':
                weight += 0.10

            # Previous token attention (local context)
            if j == i - 1:
                weight += 0.08

            # Self-attention
            if i == j:
                weight += 0.06

            # Attention to tokens 2-3 positions back
            if j == i - 2:
                weight += 0.04
            elif j == i - 3:
                weight += 0.03

            # Attention to first token of sentence/document
            if j == 0:
                weight += 0.05

            # Check for semantic similarity using embeddings
            if i != j:
                sim = _char_sim(tokens[i], tokens[j])
                if sim > 0.7:
                    weight += 0.06 * sim
                elif sim > 0.5:
                    weight += 0.03 * sim

            # Boost attention to certain structural tokens
            if target_token in ['"', "'", '(', ')', '[', ']']:
                weight += 0.05

            # Look for spacy features if available
            if spacy_indices:
                spacy_token = doc[spacy_indices[0]]
                target_spacy = None

                # Find corresponding spacy token for target
                target_spacy_indices = token_to_spacy[j] if j < len(token_to_spacy) else []
                if target_spacy_indices:
                    target_spacy = doc[target_spacy_indices[0]]

                if target_spacy:
                    # Attention to sentence starts
                    if target_spacy.is_sent_start:
                        weight += 0.04

                    # Attention to verbs and auxiliary verbs
                    if target_spacy.pos_ in ['VERB', 'AUX']:
                        weight += 0.02

                    # Attention to determiners and pronouns
                    if target_spacy.pos_ in ['DET', 'PRON']:
                        weight += 0.015

            # Distance decay for longer distances
            distance = i - j
            if distance > 3:
                weight *= max(0.3, 1.0 - distance * 0.05)

            attention[i, j] = max(0.01, weight)  # Minimum attention

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L0H21", attention



def prog_L0H22(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary and structure attention with emphasis on periods, newlines, and sentence beginnings."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L0H22", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Get spacy alignment for linguistic features
    spacy_alignment = _align_to_spacy(sentence, tokens)
    doc = spacy_parse(sentence)

    for i in range(n):
        for j in range(i + 1):  # Causal mask
            weight = 0.0

            # Strong attention to sentence boundaries (periods, newlines)
            if tokens[j] in ['.', '\n', '!', '?']:
                weight += 0.15

            # High attention to first token of document
            if j == 0:
                weight += 0.08

            # Self-attention boost
            if i == j:
                weight += 0.05

            # Attention to sentence beginnings (tokens after periods/newlines)
            if j > 0 and tokens[j-1] in ['.', '\n', '!', '?']:
                weight += 0.10

            # Recency bias - prefer recent tokens
            distance = i - j
            if distance <= 5:
                weight += 0.04 * (6 - distance) / 6

            # Punctuation attracts attention
            if tokens[j] in [',', ':', ';', '"', "'", '(', ')', '-']:
                weight += 0.03

            # Use spacy features when available
            if spacy_alignment[i] and spacy_alignment[j]:
                i_spacy = spacy_alignment[i][0] if len(spacy_alignment[i]) > 0 else None
                j_spacy = spacy_alignment[j][0] if len(spacy_alignment[j]) > 0 else None

                if i_spacy is not None and j_spacy is not None and i_spacy < len(doc) and j_spacy < len(doc):
                    i_tok = doc[i_spacy]
                    j_tok = doc[j_spacy]

                    # Syntactic dependencies - modifiers to heads
                    if j_tok.head == i_tok:
                        weight += 0.06
                    if i_tok.head == j_tok:
                        weight += 0.04

                    # Function words (determiners, prepositions) get attention
                    if j_tok.pos_ in ['DET', 'ADP', 'AUX', 'CCONJ']:
                        weight += 0.02

            # Semantic similarity boost
            sim = _char_sim(tokens[i], tokens[j])
            if sim > 0.5:
                weight += 0.03 * sim

            # Base attention for all valid positions
            weight += 0.01

            attention[i, j] = weight

    # Normalize and apply causal mask
    attention = make_row_stochastic(attention)
    attention = apply_causal_mask(attention)

    return "prog_L0H22", attention



def prog_L0H23(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Local syntactic-semantic attention with enhanced adjective-noun and compound relationships."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L0H23", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    alignment = _align_to_spacy(sentence, tokens)

    for i in range(n):
        # Strong self-attention baseline
        attention[i, i] = 0.3

        # Get spacy tokens aligned to current token
        spacy_indices = alignment[i] if i < len(alignment) else []
        current_spacy = doc[spacy_indices[0]] if spacy_indices else None

        # Check if current token is punctuation
        is_punct = tokens[i].strip() in ".,!?;:\n" or (current_spacy and current_spacy.is_punct)
        is_newline = tokens[i].strip() == "\n"

        for j in range(i + 1):  # Only attend to previous tokens (causal)
            if i == j:
                continue

            # Get spacy info for target token
            target_spacy_indices = alignment[j] if j < len(alignment) else []
            target_spacy = doc[target_spacy_indices[0]] if target_spacy_indices else None

            # Distance-based decay
            distance = i - j
            distance_weight = 1.0 / (1.0 + 0.1 * distance)

            # NEW: Enhanced attention for strong local semantic relationships
            if current_spacy and target_spacy and distance <= 4:
                # Adjective-noun relationships
                if current_spacy.pos_ == "NOUN" and target_spacy.pos_ == "ADJ" and distance <= 2:
                    attention[i, j] += 0.25 * distance_weight

                # Compound word parts (high semantic similarity at close distance)
                sim = _char_sim(tokens[i], tokens[j])
                if distance == 1 and sim > 0.4:
                    attention[i, j] += 0.2 * sim
                elif distance <= 3 and sim > 0.6:
                    attention[i, j] += 0.15 * sim * distance_weight

                # Verb-object relationships
                if current_spacy.pos_ in ["NOUN", "PRON"] and target_spacy.pos_ == "VERB" and distance <= 3:
                    attention[i, j] += 0.1 * distance_weight

            # High attention to nearby punctuation
            if tokens[j].strip() in ".,!?;:\n":
                if distance <= 5:
                    attention[i, j] += 0.15 * distance_weight

            # High attention FROM punctuation to nearby content
            if is_punct and distance <= 3:
                if target_spacy and target_spacy.pos_ in ["NOUN", "VERB", "ADJ"]:
                    attention[i, j] += 0.12 * distance_weight

            # Newlines attend strongly to previous sentence elements
            if is_newline and distance <= 8:
                attention[i, j] += 0.08 * distance_weight

            # Function words attend to their heads/content
            if current_spacy and current_spacy.pos_ in ["DET", "PREP", "ADP", "AUX"]:
                if target_spacy and target_spacy.pos_ in ["NOUN", "VERB"]:
                    if distance <= 3:
                        attention[i, j] += 0.08 * distance_weight

            # Content words attend to nearby related content
            if current_spacy and target_spacy:
                if current_spacy.pos_ in ["NOUN", "VERB"] and target_spacy.pos_ in ["NOUN", "VERB"]:
                    if distance <= 4:
                        sim = _char_sim(tokens[i], tokens[j])
                        if sim > 0.3:
                            attention[i, j] += 0.06 * sim * distance_weight

            # Verbs attend to their subjects/objects
            if current_spacy and current_spacy.pos_ == "VERB":
                if target_spacy and target_spacy.pos_ in ["NOUN", "PRON"]:
                    if distance <= 5:
                        attention[i, j] += 0.05 * distance_weight

            # General recency bias for all tokens
            if distance <= 2:
                attention[i, j] += 0.03 * distance_weight

            # Special attention to first token
            if j == 0 and distance > 0:
                attention[i, j] += 0.02

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L0H23", attention



def prog_L0H24(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Self-attention with sentence boundary and punctuation focus."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L0H24", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        for j in range(i + 1):  # Causal mask
            weight = 0.0

            # Strong self-attention
            if i == j:
                weight += 0.3

            # Attention to punctuation (comma, period, newline)
            if tokens[j] in [',', '.', '\n', '!', '?', ';']:
                weight += 0.15

            # Attention to first token of sentence/segment
            if j == 0:
                weight += 0.1

            # Attention to tokens after newlines (sentence starts)
            if j > 0 and tokens[j-1] == '\n':
                weight += 0.12

            # Recency bias - closer tokens get more attention
            distance = i - j
            if distance > 0:
                recency_weight = 0.05 / (1 + distance * 0.1)
                weight += recency_weight

            # Semantic similarity boost
            if i != j and j < len(tokens):
                sim = _char_sim(tokens[i], tokens[j])
                if sim > 0.3:
                    weight += 0.08 * sim

            # Small boost for function words and determiners
            if token_to_spacy[j]:
                spacy_idx = token_to_spacy[j][0]
                if spacy_idx < len(doc):
                    spacy_token = doc[spacy_idx]
                    if spacy_token.pos_ in ['DET', 'ADP', 'CONJ', 'CCONJ']:
                        weight += 0.05

            # Boost attention from tokens to nearby punctuation
            if j < i and tokens[j] in [',', '.', '\n']:
                if i - j <= 3:
                    weight += 0.08

            attention[i, j] = weight

    # Add small baseline attention to avoid zero rows
    attention += 0.01

    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L0H24", attention



def prog_L0H25(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Structural boundary attention head focusing on punctuation, positional cues, and cross-sentence connections."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L0H25", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        for j in range(i + 1):  # Causal mask
            weight = 0.0

            # Base self-attention
            if i == j:
                weight += 0.02

            # Strong attention to punctuation marks
            if tokens[j] in ['.', ',', '!', '?', ';', ':']:
                weight += 0.08

            # Very strong attention to newlines and empty strings
            if tokens[j] in ['\n', '']:
                weight += 0.12

            # Attention to sentence boundaries (periods followed by space/newline)
            if j < n - 1 and tokens[j] == '.' and (j == n - 1 or tokens[j + 1] in ['\n', ' ']):
                weight += 0.06

            # Positional bias - slight preference for recent tokens
            distance = i - j
            if distance <= 5:
                weight += 0.03 * (6 - distance) / 6

            # First token bias
            if j == 0:
                weight += 0.04

            # Attention between tokens with high embedding similarity
            sim = _char_sim(tokens[i], tokens[j])
            if sim > 0.7:
                weight += 0.05 * sim

            # Boost for quotation marks and dialogue markers
            if tokens[j] in ['"', "'", ',"', '."']:
                weight += 0.05

            # Special handling for certain structural patterns
            if tokens[j].startswith('said') or tokens[j] in ['Once', 'The', 'They']:
                weight += 0.02

            # Small boost for function words at sentence starts
            spacy_indices = token_to_spacy[j] if j < len(token_to_spacy) else []
            if spacy_indices:
                spacy_token = doc[spacy_indices[0]]
                if spacy_token.pos_ in ['DET', 'PRON', 'ADP'] and j > 0 and tokens[j-1] in ['\n', '.']:
                    weight += 0.03

            # NEW: Enhanced cross-newline attention to content words
            # If current token i follows a newline, boost attention to earlier content words
            if i > 0 and tokens[i-1] == '\n' and j < i-1:
                # Get spacy features for target token j
                spacy_indices_j = token_to_spacy[j] if j < len(token_to_spacy) else []
                if spacy_indices_j:
                    spacy_token_j = doc[spacy_indices_j[0]]
                    # Boost attention to content words (nouns, verbs, adjectives, adverbs)
                    if spacy_token_j.pos_ in ['NOUN', 'VERB', 'ADJ', 'ADV', 'PROPN']:
                        # Stronger boost for tokens from previous sentences
                        prev_newline_distance = 0
                        for k in range(j+1, i):
                            if tokens[k] == '\n':
                                prev_newline_distance = i - k
                                break
                        if prev_newline_distance > 0:
                            weight += 0.06 * (1.0 / max(1, prev_newline_distance))

            attention[i, j] = weight

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L0H25", attention



def prog_L0H26(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Attention head focusing on local syntactic dependencies and argument structure with moderate self-attention."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    # Get spacy parsing for syntactic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        # Moderate self-attention baseline (reduced from 0.5)
        attention[i, i] = 0.3

        # High attention to newline characters
        for j in range(i + 1):
            if tokens[j] == '\n':
                attention[i, j] += 0.3

        # Moderate attention to punctuation
        for j in range(i + 1):
            if tokens[j] in ['.', ',', '!', '?', ';', ':']:
                attention[i, j] += 0.15

        # Enhanced syntactic dependency component
        if token_to_spacy[i]:  # If token aligns to spacy tokens
            spacy_i = token_to_spacy[i][0]  # Take first aligned spacy token
            spacy_token_i = doc[spacy_i]

            for j in range(i + 1):
                if j != i and token_to_spacy[j]:  # Skip self and ensure spacy alignment
                    spacy_j = token_to_spacy[j][0]
                    spacy_token_j = doc[spacy_j]

                    # Strong attention for direct syntactic dependencies
                    if (spacy_token_i.head == spacy_token_j or 
                        spacy_token_j.head == spacy_token_i):
                        attention[i, j] += 0.25

                    # Strong attention for tokens in same clause/phrase (distance <= 3)
                    elif abs(spacy_i - spacy_j) <= 3:
                        # Check for argument-head relationships
                        if (spacy_token_i.dep_ in ['nsubj', 'dobj', 'pobj', 'nmod'] or
                            spacy_token_j.dep_ in ['nsubj', 'dobj', 'pobj', 'nmod']):
                            attention[i, j] += 0.2

        # Semantic similarity component
        for j in range(i + 1):
            if j != i:  # Skip self (already handled)
                sim = _char_sim(tokens[i], tokens[j])
                if sim > 0.5:  # High similarity threshold
                    attention[i, j] += 0.2 * sim
                elif sim > 0.3:  # Moderate similarity
                    attention[i, j] += 0.1 * sim

        # Positional bias - slight preference for recent tokens
        for j in range(max(0, i-5), i):
            attention[i, j] += 0.05 * (1.0 - (i - j) / 6.0)

        # Special attention to first token
        if i > 0:
            attention[i, 0] += 0.08

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L0H26", attention



def prog_L0H27(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Attention to semantically related previous tokens and structural markers."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L0H27", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Get spacy analysis for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        for j in range(i + 1):  # Only attend to previous tokens and self
            weight = 0.0

            # Base self-attention
            if i == j:
                weight += 0.02

            # Strong attention to first token
            if j == 0:
                weight += 0.025

            # Attention to punctuation and structural markers
            token_j = tokens[j].strip()
            if token_j in ['.', ',', '\n', '!', '?', ':', ';']:
                weight += 0.03
            elif token_j.startswith('\n'):
                weight += 0.02

            # Semantic similarity boost
            sim = _char_sim(tokens[i], tokens[j])
            if sim > 0.3:
                weight += 0.04 * sim

            # Positional decay (prefer more recent tokens)
            distance = i - j
            if distance > 0:
                decay = 1.0 / (1.0 + 0.02 * distance)
                weight *= decay

            # Boost for content words using spacy features
            if token_to_spacy[j]:
                spacy_idx = token_to_spacy[j][0]
                if spacy_idx < len(doc):
                    spacy_token = doc[spacy_idx]
                    if spacy_token.pos_ in ['NOUN', 'VERB', 'ADJ', 'ADV']:
                        weight += 0.015
                    if spacy_token.dep_ in ['ROOT', 'nsubj', 'dobj', 'pobj']:
                        weight += 0.01

            # Special boost for certain token patterns
            if i > j:
                # Attention between related words
                if token_to_spacy[i] and token_to_spacy[j]:
                    i_spacy = token_to_spacy[i][0] if token_to_spacy[i] else -1
                    j_spacy = token_to_spacy[j][0] if token_to_spacy[j] else -1

                    if i_spacy < len(doc) and j_spacy < len(doc) and i_spacy >= 0 and j_spacy >= 0:
                        i_tok = doc[i_spacy]
                        j_tok = doc[j_spacy]

                        # Syntactic dependencies
                        if j_tok in i_tok.ancestors or i_tok in j_tok.ancestors:
                            weight += 0.02

                        # Named entities
                        if i_tok.ent_type_ and j_tok.ent_type_ and i_tok.ent_type_ == j_tok.ent_type_:
                            weight += 0.015

            attention[i, j] = weight

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L0H27", attention



def prog_L0H28(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Structural delimiter attention head focusing on newlines, punctuation, and sentence boundaries with function word attention."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L0H28", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        for j in range(i + 1):  # Causal mask
            weight = 0.0

            # Very high attention to newlines
            if tokens[j].strip() == '\n' or tokens[j] == '\n':
                weight += 0.25

            # High attention to punctuation marks
            if tokens[j].strip() in ['.', ',', '"', '!', '?', ';"', '."', '!"']:
                weight += 0.15

            # Medium attention to empty/whitespace tokens that often precede content
            if tokens[j].strip() == '' and j > 0:
                weight += 0.08

            # Self-attention
            if i == j:
                weight += 0.05

            # Attention to first token
            if j == 0:
                weight += 0.03

            # Recency bias for recent tokens
            if i - j <= 3 and i != j:
                weight += 0.02 * (4 - (i - j)) / 4

            # Boost for tokens that start sentences/clauses
            if j < len(token_to_spacy) and token_to_spacy[j]:
                spacy_idx = token_to_spacy[j][0]
                if spacy_idx < len(doc):
                    spacy_token = doc[spacy_idx]
                    # Check if this starts a sentence
                    if spacy_token.is_sent_start or (spacy_idx > 0 and doc[spacy_idx-1].text in ['.', '!', '?']):
                        weight += 0.04

            # Small boost for content words when attending to structural elements
            if tokens[j].strip() in ['\n', '.', ','] and j < len(token_to_spacy) and token_to_spacy[i]:
                if token_to_spacy[i] and token_to_spacy[i][0] < len(doc):
                    spacy_token = doc[token_to_spacy[i][0]]
                    if spacy_token.pos_ in ['NOUN', 'VERB', 'ADJ']:
                        weight += 0.03

            # NEW: Strong attention to function words (prepositions, conjunctions, determiners)
            if j < len(token_to_spacy) and token_to_spacy[j] and i != j:
                spacy_idx = token_to_spacy[j][0]
                if spacy_idx < len(doc):
                    spacy_token = doc[spacy_idx]
                    if spacy_token.pos_ in ['ADP', 'CCONJ', 'DET', 'SCONJ']:
                        # Distance-based decay for function word attention
                        distance = i - j
                        if distance <= 10:
                            decay_factor = max(0.1, 1.0 - distance * 0.08)
                            weight += 0.25 * decay_factor

            attention[i, j] = weight

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L0H28", attention



def prog_L0H29(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Cross-paragraph attention head that connects tokens to earlier newline boundaries."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention_matrix = np.zeros((n, n))

    for i in range(n):
        current_token = tokens[i]

        # Find newline tokens before current position
        newline_indices = []
        for j in range(i):
            if tokens[j].strip() == '':  # newline or whitespace
                newline_indices.append(j)

        # Find period tokens before current position
        period_indices = []
        for j in range(i):
            if tokens[j] == '.':
                period_indices.append(j)

        # Base attention distribution
        if newline_indices:
            # Strong attention to most recent newlines, with decay
            for idx, nl_idx in enumerate(reversed(newline_indices[-3:])):  # Last 3 newlines
                weight = 0.8 * (0.6 ** idx)  # Exponential decay
                attention_matrix[i, nl_idx] = weight

        # Secondary attention to periods
        if period_indices:
            for idx, p_idx in enumerate(reversed(period_indices[-2:])):  # Last 2 periods
                weight = 0.3 * (0.5 ** idx)
                attention_matrix[i, p_idx] += weight

        # Self-attention component
        attention_matrix[i, i] = 0.2

        # Small attention to immediate previous token
        if i > 0:
            attention_matrix[i, i-1] = 0.1

        # For tokens that are newlines or periods, add self-attention boost
        if current_token.strip() == '' or current_token == '.':
            attention_matrix[i, i] += 0.4

    # Apply causal mask and normalize
    attention_matrix = apply_causal_mask(attention_matrix)
    attention_matrix = make_row_stochastic(attention_matrix)

    return "prog_L0H29", attention_matrix



def prog_L0H3(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Semantic similarity head with positional bias toward sequence starts and recent tokens, plus cross-sentence attention."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L0H3", np.zeros((n_empty, n_empty))

    attention_matrix = np.zeros((n, n))

    # Parse sentence for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        for j in range(i + 1):  # Causal mask
            weight = 0.0

            # Base self-attention (reduced from original)
            if i == j:
                weight += 0.01  # Reduced from 0.02

            # Strong attention to first token (often empty after newlines)
            if j == 0 or (j > 0 and tokens[j-1] == '\n' and tokens[j] == ''):
                weight += 0.05

            # Attention to newlines and sentence boundaries
            if tokens[j] in ['\n', '.', '!', '?']:
                weight += 0.01

            # Semantic similarity boost
            similarity = _char_sim(tokens[i], tokens[j])
            if similarity > 0.3:
                weight += similarity * 0.08

            # Positional recency bias (stronger for recent tokens)
            distance = i - j
            if distance <= 5:
                recency_boost = 0.02 * (6 - distance) / 6
                weight += recency_boost

            # NEW: Cross-sentence attention boost
            # Look for sentence boundaries between i and j
            sentence_boundaries = 0
            for k in range(j, i):
                if tokens[k] in ['.', '!', '?', '\n']:
                    sentence_boundaries += 1

            # If there are sentence boundaries, boost attention to semantically important earlier tokens
            if sentence_boundaries > 0:
                # Boost attention to content words from earlier sentences
                if token_to_spacy[j] and len(token_to_spacy[j]) > 0:
                    spacy_j = doc[token_to_spacy[j][0]]
                    if spacy_j.pos_ in ['NOUN', 'VERB', 'ADJ', 'PROPN']:
                        # Stronger boost for more sentence boundaries (longer distance)
                        cross_sentence_boost = 0.03 * min(sentence_boundaries, 3)
                        weight += cross_sentence_boost

            # Special boost for tokens that are linguistically related
            if token_to_spacy[i] and token_to_spacy[j]:
                spacy_i = doc[token_to_spacy[i][0]]
                spacy_j = doc[token_to_spacy[j][0]]

                # Verb-object relationships
                if (spacy_i.dep_ in ['dobj', 'obj'] and spacy_j.pos_ == 'VERB') or \
                   (spacy_j.dep_ in ['dobj', 'obj'] and spacy_i.pos_ == 'VERB'):
                    weight += 0.015

                # Noun-modifier relationships
                if (spacy_i.dep_ == 'amod' and spacy_j.pos_ == 'NOUN') or \
                   (spacy_j.dep_ == 'amod' and spacy_i.pos_ == 'NOUN'):
                    weight += 0.01

                # Subject-verb relationships
                if (spacy_i.dep_ in ['nsubj', 'nsubjpass'] and spacy_j.pos_ == 'VERB') or \
                   (spacy_j.dep_ in ['nsubj', 'nsubjpass'] and spacy_i.pos_ == 'VERB'):
                    weight += 0.01

            # Extra attention to function words and common patterns
            if tokens[j] in ['and', 'the', 'a', 'an', 'of', 'to', 'in', 'on', 'at', 'with']:
                weight += 0.005

            # Boost for punctuation attention
            if tokens[j] in [',', ';', ':', '"', "'", '(', ')']:
                weight += 0.008

            attention_matrix[i, j] = weight

    # Add small uniform noise to avoid zero rows
    attention_matrix += 0.001

    attention_matrix = apply_causal_mask(attention_matrix)
    attention_matrix = make_row_stochastic(attention_matrix)

    return "prog_L0H3", attention_matrix



def prog_L0H30(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Structural delimiter attention head with enhanced backward attention to function words and early content."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention_matrix = np.zeros((n, n))

    # Get spacy alignment for linguistic features
    spacy_alignment = _align_to_spacy(sentence, tokens)
    doc = spacy_parse(sentence)

    for i in range(n):
        current_token = tokens[i]

        for j in range(i + 1):  # Only attend to current and previous tokens (causal)
            target_token = tokens[j]
            weight = 0.0

            # Strong attention to structural tokens
            if target_token in ['\n', '.', ',', '"', "'", '!', '?', ';', ':']:
                if target_token == '\n':
                    weight += 0.15  # Very high for newlines
                elif target_token == '.':
                    weight += 0.12  # High for periods
                elif target_token in [',', '"', "'"]:
                    weight += 0.08  # Medium-high for commas and quotes
                else:
                    weight += 0.05  # Lower for other punctuation

            # NEW: Enhanced attention to function words and early content words
            if j < len(spacy_alignment) and spacy_alignment[j]:
                spacy_indices = spacy_alignment[j]
                for spacy_idx in spacy_indices:
                    if spacy_idx < len(doc):
                        spacy_token = doc[spacy_idx]
                        # Function words (articles, prepositions, conjunctions)
                        if spacy_token.pos_ in ['DET', 'ADP', 'CCONJ', 'SCONJ']:
                            weight += 0.10
                        # Early content words get boosted attention
                        elif j <= 5 and spacy_token.pos_ in ['NOUN', 'VERB', 'ADJ', 'ADV']:
                            weight += 0.06

            # Moderate attention to first token
            if j == 0:
                weight += 0.04

            # Self-attention baseline (reduced to prevent over-prediction)
            if i == j:
                weight += 0.02

            # Small recency bias for recent tokens
            if i - j <= 3 and j > 0:
                weight += 0.02 / (1 + (i - j))

            # Boost for tokens that are whitespace or empty
            if target_token.strip() == '' or target_token.isspace():
                weight += 0.06

            attention_matrix[i, j] = weight

    # Apply causal mask and normalize
    attention_matrix = apply_causal_mask(attention_matrix)
    attention_matrix = make_row_stochastic(attention_matrix)

    return "prog_L0H30", attention_matrix



def prog_L0H31(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Semantic similarity head with structural boundary attention and content word focus."""
    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L0H31", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        for j in range(i + 1):  # Causal mask
            weight = 0.0

            # Strong attention to newlines and sentence boundaries
            if tokens[j] == '\n' or tokens[j] == '.':
                weight += 0.15

            # Self-attention baseline
            if i == j:
                weight += 0.02

            # Semantic similarity component
            sim = _char_sim(tokens[i], tokens[j])
            if sim > 0.3:  # Threshold for meaningful similarity
                weight += sim * 0.12

            # Syntactic relationship boost
            if token_to_spacy[i] and token_to_spacy[j]:
                spacy_i = token_to_spacy[i][0]
                spacy_j = token_to_spacy[j][0]

                if spacy_i < len(doc) and spacy_j < len(doc):
                    tok_i = doc[spacy_i]
                    tok_j = doc[spacy_j]

                    # Head-dependent relationships
                    if tok_i.head == tok_j or tok_j.head == tok_i:
                        weight += 0.08

                    # Same phrase or clause
                    if abs(spacy_i - spacy_j) <= 3:
                        weight += 0.03

                    # NEW: Content word attention boost
                    if tok_j.pos_ in ['NOUN', 'ADJ', 'VERB'] and not tok_j.is_stop:
                        # Boost attention to semantically important content words
                        weight += 0.12

                        # Extra boost for adjectives and important nouns
                        if tok_j.pos_ == 'ADJ' or (tok_j.pos_ == 'NOUN' and len(tok_j.text) > 3):
                            weight += 0.08

            # Position-based decay
            distance = i - j
            if distance > 0:
                weight *= (0.95 ** distance)

            # Special boost for first token
            if j == 0:
                weight += 0.05

            attention[i, j] = weight

    # Normalize and apply causal mask
    attention = make_row_stochastic(attention)
    attention = apply_causal_mask(attention)

    return "prog_L0H31", attention



def prog_L0H4(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Mixed pattern head: strong previous-token attention with content-based matching for semantically similar tokens."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        # Strong previous-token attention (main pattern)
        if i > 0:
            attention[i, i - 1] = 0.8

        # Self-attention baseline
        attention[i, i] = 0.1

        # Content-based attention for semantically similar tokens
        for j in range(i):
            if j == i - 1:  # Already handled above
                continue

            # High similarity bonus
            sim = _char_sim(tokens[i], tokens[j])
            if sim > 0.7:
                attention[i, j] += 0.4
            elif sim > 0.5:
                attention[i, j] += 0.2
            elif sim > 0.3:
                attention[i, j] += 0.1

            # Linguistic feature bonuses
            if token_to_spacy[i] and token_to_spacy[j]:
                i_spacy_tokens = [doc[idx] for idx in token_to_spacy[i] if idx < len(doc)]
                j_spacy_tokens = [doc[idx] for idx in token_to_spacy[j] if idx < len(doc)]

                if i_spacy_tokens and j_spacy_tokens:
                    i_token = i_spacy_tokens[0]
                    j_token = j_spacy_tokens[0]

                    # Verb-to-subject/object patterns
                    if i_token.pos_ == "VERB" and j_token.pos_ in ["NOUN", "PRON"]:
                        attention[i, j] += 0.15

                    # Noun-to-determiner patterns
                    if i_token.pos_ == "NOUN" and j_token.pos_ == "DET":
                        attention[i, j] += 0.12

                    # Adjective-to-noun patterns
                    if i_token.pos_ == "ADJ" and j_token.pos_ == "NOUN":
                        attention[i, j] += 0.1

            # Distance decay for non-adjacent tokens
            distance = i - j
            if distance > 1:
                decay_factor = 1.0 / (1.0 + 0.1 * (distance - 1))
                attention[i, j] *= decay_factor

        # Special token handling
        token_str = tokens[i].strip()

        # Enhanced punctuation attention to content words
        if token_str in [".", "!", "?", ",", ";"]:
            for j in range(i):
                if token_to_spacy[j]:
                    j_spacy_tokens = [doc[idx] for idx in token_to_spacy[j] if idx < len(doc)]
                    if j_spacy_tokens and j_spacy_tokens[0].pos_ in ["NOUN", "VERB", "ADJ"]:
                        # Much stronger attention for punctuation to content words
                        distance = i - j
                        if distance <= 3:
                            attention[i, j] += 0.4  # Strong boost for recent content
                        elif distance <= 6:
                            attention[i, j] += 0.3  # Medium boost for nearby content
                        else:
                            attention[i, j] += 0.15  # Smaller boost for distant content

        # Whitespace/newline tokens attend broadly to recent content
        if token_str in ["\n", " ", ""]:
            for j in range(max(0, i - 5), i):
                attention[i, j] += 0.05

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L0H4", attention



def prog_L0H5(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Previous-token attention with enhanced semantic similarity for distant tokens."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L0H5", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    for i in range(n):
        for j in range(i + 1):  # Causal mask
            weight = 0.0

            # Self-attention
            if i == j:
                weight += 0.3

            # First token attention
            elif j == 0:
                weight += 0.15

            # Previous token attention (strongest for immediate predecessor)
            elif j == i - 1:
                weight += 0.25
            elif j == i - 2 and i >= 2:
                weight += 0.15
            elif j == i - 3 and i >= 3:
                weight += 0.1

            # Semantic similarity component
            if i != j:
                sim = _char_sim(tokens[i], tokens[j])
                if sim > 0.5:
                    weight += 0.2 * sim
                elif sim > 0.3:
                    weight += 0.1 * sim

            # Enhanced attention for high semantic similarity at medium distances
            if i != j and 4 <= i - j <= 10:
                sim = _char_sim(tokens[i], tokens[j])
                if sim > 0.4:
                    # Strong boost for semantically similar tokens at medium distance
                    weight += 0.3 * sim

            # Distance decay for non-adjacent tokens
            if j < i - 3:
                distance = i - j
                decay = 1.0 / (distance * 0.5)
                weight *= decay

            # Boost for punctuation attending to content words
            if tokens[i] in ['.', ',', '!', '?', ';', ':'] and j < i - 1:
                # Check if j is a content word by looking at token characteristics
                if len(tokens[j]) > 2 and not tokens[j].isspace():
                    weight += 0.05

            attention[i, j] = weight

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L0H5", attention



def prog_L0H6(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Semantic similarity attention with punctuation-to-punctuation boost and reduced self-attention."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L0H6", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    for i in range(n):
        for j in range(i + 1):  # Causal mask
            # Base similarity score
            sim = _char_sim(tokens[i], tokens[j])

            # Reduced self-attention bias
            if i == j:
                attention[i, j] = 0.3 + sim
            else:
                # Distance decay
                distance = i - j
                decay = 0.8 ** distance

                # Boost for high similarity
                sim_boost = 1.0 + max(0, sim - 0.3) * 2.0

                # Special handling for punctuation
                is_punct_i = tokens[i].strip() in ".,!?;:\n"
                is_punct_j = tokens[j].strip() in ".,!?;:\n"

                if is_punct_i or is_punct_j:
                    punct_boost = 1.2
                else:
                    punct_boost = 1.0

                # Strong boost for punctuation-to-punctuation attention
                if is_punct_i and is_punct_j:
                    punct_to_punct_boost = 8.0
                else:
                    punct_to_punct_boost = 1.0

                # First token attention
                first_token_boost = 1.3 if j == 0 else 1.0

                attention[i, j] = decay * sim_boost * punct_boost * punct_to_punct_boost * first_token_boost

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L0H6", attention



def prog_L0H7(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Semantic similarity and positional attention head with enhanced content word self-attention."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L0H7", np.zeros((n_empty, n_empty)).reshape(0, 0)

    # Initialize attention matrix
    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        # Self-attention baseline, stronger for special tokens
        token = tokens[i]
        if token.strip() in ['', '\n'] or token in ['.', ',', '!', '?', ';', ':']:
            attention[i, i] = 1.0
        else:
            # Enhanced self-attention for content words
            base_self_attention = 0.1
            if token_to_spacy[i]:
                spacy_i = token_to_spacy[i][0]
                if spacy_i < len(doc):
                    tok_i = doc[spacy_i]
                    # Boost self-attention for nouns, proper nouns, and other content words
                    if tok_i.pos_ in ['NOUN', 'PROPN', 'VERB', 'ADJ'] and len(token.strip()) > 2:
                        base_self_attention = 0.4
            attention[i, i] = base_self_attention

        # Attention to previous tokens
        for j in range(i):
            weight = 0.0

            # Base positional decay
            distance = i - j
            positional_weight = 0.5 / (1 + 0.1 * distance)

            # Semantic similarity component
            similarity = _char_sim(tokens[i], tokens[j])
            similarity_weight = max(0, similarity) * 0.4

            # Special token attention
            if tokens[j].strip() in ['', '\n'] or tokens[j] in ['.', ',', '!', '?', ';', ':']:
                special_weight = 0.3
            else:
                special_weight = 0.0

            # Syntactic relationship boost
            syntactic_weight = 0.0
            if token_to_spacy[i] and token_to_spacy[j]:
                spacy_i = token_to_spacy[i][0]
                spacy_j = token_to_spacy[j][0]

                if spacy_i < len(doc) and spacy_j < len(doc):
                    tok_i = doc[spacy_i]
                    tok_j = doc[spacy_j]

                    # Check for syntactic dependencies
                    if tok_j in [anc for anc in tok_i.ancestors]:
                        syntactic_weight = 0.2
                    elif tok_i in [anc for anc in tok_j.ancestors]:
                        syntactic_weight = 0.15
                    elif tok_i.head == tok_j.head and tok_i.head != tok_i:
                        syntactic_weight = 0.1

            # Modified first token attention - reduce for punctuation
            first_token_weight = 0.0
            if j == 0:
                # Reduce attention to first token if it's punctuation
                if tokens[j] in [',', '.', '!', '?', ';', ':', '"', "'"] or tokens[j].strip() == '':
                    first_token_weight = 0.05
                else:
                    first_token_weight = 0.2

            weight = positional_weight + similarity_weight + special_weight + syntactic_weight + first_token_weight
            attention[i, j] = weight

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L0H7", attention



def prog_L0H8(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Local attention head with subword completion - tokens attend to earlier parts of the same word."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L0H8", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        token_i = tokens[i].strip()

        # Self-attention baseline
        attention[i, i] = 0.3

        # Strong attention to immediately preceding token
        if i > 0:
            attention[i, i-1] = 0.4

        # Moderate attention to tokens 2-3 positions back
        if i > 1:
            attention[i, i-2] = 0.15
        if i > 2:
            attention[i, i-3] = 0.08

        # NEW: Subword completion - detect when current token continues a word started by earlier tokens
        if i > 0:
            # Check if current token and previous tokens form a continuous word
            # by reconstructing the text and checking for word boundaries
            current_text = ''.join(tokens[max(0, i-3):i+1])

            # Look for word-internal connections using character-level analysis
            for j in range(max(0, i-3), i):
                # Check if tokens j through i might be parts of the same word
                partial_word = ''.join(tokens[j:i+1])

                # Strong boost if this looks like subword completion
                if (len(partial_word) > 1 and 
                    not any(c.isspace() or c in '.,!?";:' for c in partial_word) and
                    not tokens[j].strip() in [' ', '\n', '']):

                    # Stronger boost for immediately adjacent subword parts
                    if j == i - 1:
                        attention[i, j] += 0.3
                    # Moderate boost for nearby subword parts
                    elif j >= i - 2:
                        attention[i, j] += 0.2

        # Punctuation gets high attention to nearby content
        if token_i in ['.', ',', '!', '?', '"', "'", ';', ':']:
            for j in range(max(0, i-5), i):
                other_token = tokens[j].strip()
                if other_token not in ['.', ',', '!', '?', '"', "'", ';', ':', ' ', '\n', '']:
                    attention[i, j] += 0.3

        # Syntactic relationships via spacy
        if token_to_spacy[i]:
            spacy_idx = token_to_spacy[i][0]
            if spacy_idx < len(doc):
                spacy_token = doc[spacy_idx]

                # Attend to syntactic head
                if spacy_token.head != spacy_token:
                    head_idx = spacy_token.head.i
                    for j in range(i):
                        if j < len(token_to_spacy) and token_to_spacy[j] and head_idx in token_to_spacy[j]:
                            attention[i, j] += 0.25

                # Modifiers attend to their heads
                if spacy_token.dep_ in ['amod', 'advmod', 'det', 'poss']:
                    head_idx = spacy_token.head.i
                    for j in range(i):
                        if j < len(token_to_spacy) and token_to_spacy[j] and head_idx in token_to_spacy[j]:
                            attention[i, j] += 0.3

                # Subjects and objects attend to verbs
                if spacy_token.dep_ in ['nsubj', 'dobj', 'pobj']:
                    head_idx = spacy_token.head.i
                    for j in range(i):
                        if j < len(token_to_spacy) and token_to_spacy[j] and head_idx in token_to_spacy[j]:
                            attention[i, j] += 0.2

        # Semantic similarity boost
        for j in range(i):
            sim = _char_sim(tokens[i], tokens[j])
            if sim > 0.6:  # High similarity threshold
                attention[i, j] += 0.25 * sim
            elif sim > 0.3:  # Moderate similarity
                attention[i, j] += 0.1 * sim

        # Special patterns for common tokens
        if token_i in [' ', '\n', '']:
            # Whitespace tokens attend to nearby content
            for j in range(max(0, i-3), i):
                if tokens[j].strip() not in [' ', '\n', '', '.', ',']:
                    attention[i, j] += 0.2

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L0H8", attention



def prog_L0H9(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Previous-token attention with semantic similarity boosting and enhanced self-attention for important tokens."""
    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L0H9", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Get spacy alignment for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        for j in range(i + 1):  # Only attend to previous tokens and self
            if i == j:
                # Enhanced self-attention for important tokens
                base_self_attention = 0.1

                # Check if token is punctuation or newline
                if tokens[i].strip() in ['.', ',', '!', '?', ';', ':', '\n'] or tokens[i] == '\n':
                    base_self_attention = 0.7
                # Check if token is a content word using spacy
                elif token_to_spacy[i]:
                    spacy_indices = token_to_spacy[i]
                    for spacy_idx in spacy_indices:
                        if spacy_idx < len(doc):
                            spacy_token = doc[spacy_idx]
                            # Boost self-attention for content words (nouns, verbs, adjectives, adverbs)
                            if spacy_token.pos_ in ['NOUN', 'VERB', 'ADJ', 'ADV', 'PROPN']:
                                base_self_attention = max(base_self_attention, 0.4)

                attention[i, j] = base_self_attention
            else:
                # Distance-based decay (stronger for recent tokens)
                distance = i - j
                recency_weight = np.exp(-distance * 0.3)

                # Semantic similarity boost (reduced to avoid over-prediction)
                sim = _char_sim(tokens[i], tokens[j])
                similarity_weight = max(0, sim) * 1.0  # Reduced from 2.0

                # Position bias (slight preference for earlier positions)
                position_weight = 1.0 / (j + 1) * 0.2

                # Combine factors
                attention[i, j] = recency_weight + similarity_weight + position_weight

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L0H9", attention



def prog_L10H0(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Attention head that focuses on structural markers and has strong first-token attention."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention_matrix = np.zeros((n, n))

    for i in range(n):
        # Find structural markers within the causal window
        period_indices = []
        newline_indices = []
        first_token_idx = 0

        for j in range(i + 1):  # Only look at tokens up to position i
            if tokens[j].strip() == '.':
                period_indices.append(j)
            elif tokens[j].strip() == '\n' or '\n' in tokens[j]:
                newline_indices.append(j)

        # Base attention distribution
        base_attention = 0.1

        # Strong attention to periods
        for p_idx in period_indices:
            attention_matrix[i, p_idx] += 0.4

        # Strong attention to newlines  
        for n_idx in newline_indices:
            attention_matrix[i, n_idx] += 0.35

        # Enhanced first token attention - much stronger for distant tokens
        if i > 0:
            # Scale first token attention based on distance - more distant tokens attend more strongly
            first_token_boost = 0.15 + min(0.6, 0.05 * i)  # Scales from 0.15 to 0.75
            attention_matrix[i, first_token_idx] += first_token_boost

        # Reduced self-attention for non-structural tokens
        if not (tokens[i].strip() in ['.', '\n'] or '\n' in tokens[i]):
            attention_matrix[i, i] += 0.05  # Much lower self-attention
        else:
            attention_matrix[i, i] += 0.2  # Keep higher self-attention for structural tokens

        # Small baseline attention to all accessible tokens
        for j in range(i + 1):
            attention_matrix[i, j] += base_attention / (i + 1)

    # Apply causal mask and normalize
    attention_matrix = apply_causal_mask(attention_matrix)
    attention_matrix = make_row_stochastic(attention_matrix)

    return "prog_L10H0", attention_matrix



def prog_L10H1(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary and first-token detection head with strong attention to sentence starts and ends."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L10H1", np.zeros((n_empty, n_empty)).reshape(0, 0)

    attention = np.zeros((n, n))

    # Find sentence boundary tokens (periods, newlines, exclamation marks, question marks)
    boundary_tokens = set()
    first_content_tokens = set()

    # Identify boundary tokens and first content tokens
    for i, token in enumerate(tokens):
        token_stripped = token.strip()
        if token_stripped in ['.', '!', '?', '\n']:
            boundary_tokens.add(i)
        elif i == 0 or (i > 0 and tokens[i-1].strip() in ['\n', '.', '!', '?']):
            # This is a first token or follows a sentence boundary
            if token_stripped and not token_stripped.isspace():
                first_content_tokens.add(i)

    # If no explicit boundaries found, treat position 0 as special
    if not boundary_tokens and not first_content_tokens:
        first_content_tokens.add(0)

    for i in range(n):
        for j in range(i + 1):  # Causal mask
            weight = 0.1  # Base attention

            # Very strong self-attention for first content tokens
            if i in first_content_tokens and i == j:
                weight = 1.0

            # Strong attention from nearby tokens to first content tokens
            elif j in first_content_tokens and abs(i - j) <= 3:
                weight = 0.9 - 0.1 * abs(i - j)

            # Strong attention to boundary tokens (periods, newlines)
            elif j in boundary_tokens:
                # Distance-based decay for boundary attention
                distance = i - j
                if distance <= 5:
                    weight = 0.6 - 0.05 * distance
                else:
                    weight = 0.3 - 0.02 * (distance - 5)
                weight = max(weight, 0.1)

            # Self-attention for boundary tokens
            elif i in boundary_tokens and i == j:
                weight = 0.6

            # Moderate attention within sentence based on content
            else:
                # Use spacy to get POS information
                doc = spacy_parse(sentence)
                token_to_spacy = _align_to_spacy(sentence, tokens)

                # Get spacy tokens for current positions
                spacy_indices_i = token_to_spacy[i] if i < len(token_to_spacy) else []
                spacy_indices_j = token_to_spacy[j] if j < len(token_to_spacy) else []

                # Boost attention for content words (NOUN, VERB, ADJ, ADV)
                content_pos = {'NOUN', 'VERB', 'ADJ', 'ADV', 'PROPN'}

                is_content_i = any(doc[idx].pos_ in content_pos for idx in spacy_indices_i if idx < len(doc))
                is_content_j = any(doc[idx].pos_ in content_pos for idx in spacy_indices_j if idx < len(doc))

                if is_content_i and is_content_j:
                    weight = 0.25
                elif is_content_j:
                    weight = 0.2

                # Small distance penalty
                distance = i - j
                weight = weight * (0.9 ** distance)

            attention[i, j] = weight

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L10H1", attention



def prog_L10H10(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary and positional attention head with strong first-token attention."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L10H10", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        # Strong self-attention for first token
        if i == 0:
            attention[i, i] = 1.0
            continue

        # Base positional decay (attend more to recent tokens)
        for j in range(i + 1):
            distance = i - j
            attention[i, j] = max(0.01, 0.1 * np.exp(-0.3 * distance))

        # NEW: Strong attention back to first token for all positions
        attention[i, 0] += 0.4

        # Strong boost for sentence-ending punctuation
        for j in range(i + 1):
            token_j = tokens[j].strip()
            if token_j in ['.', '!', '?']:
                attention[i, j] += 0.3
            elif token_j == '\n':
                attention[i, j] += 0.25

        # Moderate boost for other punctuation
        for j in range(i + 1):
            token_j = tokens[j].strip()
            if token_j in [',', ';', ':', '"', "'", '"', '"']:
                attention[i, j] += 0.1

        # Syntactic relationships - heads and modifiers
        if token_to_spacy[i]:
            spacy_i = token_to_spacy[i][0]
            if spacy_i < len(doc):
                spacy_token_i = doc[spacy_i]

                # Attend to syntactic head
                if spacy_token_i.head != spacy_token_i:
                    for j in range(i + 1):
                        if token_to_spacy[j] and spacy_token_i.head.i in token_to_spacy[j]:
                            attention[i, j] += 0.15

                # Attend to direct children
                for child in spacy_token_i.children:
                    for j in range(i + 1):
                        if token_to_spacy[j] and child.i in token_to_spacy[j]:
                            attention[i, j] += 0.08

        # Small boost for similar tokens (semantic similarity)
        for j in range(i):
            sim = _char_sim(tokens[i], tokens[j])
            if sim > 0.7:
                attention[i, j] += 0.05 * sim

        # Adjacent token boost
        if i > 0:
            attention[i, i-1] += 0.05

        # Reduced self-attention boost to counter over-prediction
        attention[i, i] += 0.05

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L10H10", attention



def prog_L10H11(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Structural boundary attention head focusing on newlines, periods, and first tokens."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        token = tokens[i].strip()

        # Base self-attention
        attention[i, i] = 0.05

        # Strong attention to newlines
        for j in range(i + 1):
            if tokens[j].strip() == '\n' or tokens[j] == '\n':
                attention[i, j] += 0.4

        # Strong attention to periods
        for j in range(i + 1):
            if tokens[j].strip() == '.' or tokens[j] == '.':
                attention[i, j] += 0.3

        # Strong attention to first token (if not whitespace/punctuation)
        if n > 0 and tokens[0].strip() and tokens[0] not in ['.', ',', '\n', ' ']:
            attention[i, 0] += 0.2

        # Local syntactic attention - attend to previous few tokens with decay
        for j in range(max(0, i - 3), i):
            decay = 1.0 / (i - j + 1)
            attention[i, j] += 0.1 * decay

        # Special case: if current token follows punctuation, attend to it
        if i > 0 and tokens[i-1].strip() in ['.', ',', '!', '?', '\n']:
            attention[i, i-1] += 0.15

        # Attend to tokens with high embedding similarity
        for j in range(i):
            sim = _char_sim(tokens[i], tokens[j])
            if sim > 0.7:
                attention[i, j] += 0.1 * sim

        # Additional attention for function words to content words
        if len(token_to_spacy[i]) > 0:
            spacy_idx = token_to_spacy[i][0]
            if spacy_idx < len(doc):
                spacy_token = doc[spacy_idx]
                if spacy_token.pos_ in ['DET', 'ADP', 'PRON']:
                    # Function words attend more to nearby content words
                    for j in range(max(0, i - 5), i):
                        if len(token_to_spacy[j]) > 0:
                            j_spacy_idx = token_to_spacy[j][0]
                            if j_spacy_idx < len(doc):
                                j_spacy_token = doc[j_spacy_idx]
                                if j_spacy_token.pos_ in ['NOUN', 'VERB', 'ADJ']:
                                    attention[i, j] += 0.08

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L10H11", attention



def prog_L10H12(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Cross-sentence structural attention head focusing on sentence boundaries and inter-sentence dependencies."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L10H12", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    # Identify sentence boundary tokens (periods, newlines)
    sentence_boundaries = []
    for i, token in enumerate(tokens):
        if token.strip() in ['.', '\n']:
            sentence_boundaries.append(i)

    for i in range(n):
        # Base attention distribution
        weights = np.zeros(n)

        # Strong attention to sentence boundaries
        for boundary_idx in sentence_boundaries:
            if boundary_idx <= i:
                weights[boundary_idx] += 0.3

        # Strong attention to first token
        if i > 0:
            weights[0] += 0.4

        # Self-attention for sentence boundary tokens
        if i in sentence_boundaries:
            weights[i] += 0.5

        # Attention to previous tokens with decay
        for j in range(max(0, i-5), i):
            decay = 0.8 ** (i - j)
            weights[j] += 0.1 * decay

        # Cross-sentence attention - tokens early in new sentences attend to previous sentence boundaries
        if i < len(token_to_spacy) and token_to_spacy[i]:
            spacy_token = doc[token_to_spacy[i][0]]
            if spacy_token.is_sent_start or (spacy_token.i < 3 and spacy_token.sent.start == spacy_token.i):
                # This token is at the start of a sentence
                for boundary_idx in sentence_boundaries:
                    if boundary_idx < i:
                        weights[boundary_idx] += 0.2

        # Syntactic attention within sentences
        if i < len(token_to_spacy) and token_to_spacy[i]:
            current_spacy = doc[token_to_spacy[i][0]]

            for j in range(i):
                if j < len(token_to_spacy) and token_to_spacy[j]:
                    target_spacy = doc[token_to_spacy[j][0]]

                    # Same sentence relationships
                    if current_spacy.sent == target_spacy.sent:
                        # Attend to syntactic heads
                        if target_spacy == current_spacy.head:
                            weights[j] += 0.15

                        # Attend to subjects and objects
                        if target_spacy.dep_ in ['nsubj', 'dobj', 'pobj']:
                            weights[j] += 0.1

        # Semantic similarity boost
        for j in range(i):
            sim = _char_sim(tokens[i], tokens[j])
            if sim > 0.3:
                weights[j] += 0.05 * sim

        # Ensure non-zero weights
        if weights.sum() == 0:
            if i > 0:
                weights[i-1] = 1.0
            else:
                weights[i] = 1.0

        attention[i] = weights

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L10H12", attention



def prog_L10H13(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary and structural marker attention head."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L10H13", np.zeros((n_empty, n_empty))

    # Initialize attention matrix
    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        token = tokens[i]

        # Very high self-attention for first token
        if i == 0:
            attention[i, i] = 1.0
            continue

        # Strong attention to sentence boundaries (newlines and periods)
        for j in range(i + 1):
            target_token = tokens[j]

            # High attention to newlines
            if target_token.strip() == '' and '\n' in target_token:
                attention[i, j] += 0.4

            # High attention to periods
            elif target_token.strip() == '.':
                attention[i, j] += 0.3

            # Moderate attention to first token
            elif j == 0:
                attention[i, j] += 0.2

        # Add positional decay
        for j in range(i + 1):
            if j < i:
                distance = i - j
                attention[i, j] += 0.1 / (1 + distance * 0.1)

        # Self-attention baseline
        attention[i, i] += 0.05

        # Get spacy information for current token
        if token_to_spacy[i]:
            spacy_idx = token_to_spacy[i][0]
            if spacy_idx < len(doc):
                spacy_token = doc[spacy_idx]

                # If token is a verb or noun, attend more to sentence starts
                if spacy_token.pos_ in ['VERB', 'NOUN', 'PROPN']:
                    for j in range(i + 1):
                        if tokens[j].strip() == '' and '\n' in tokens[j]:
                            attention[i, j] += 0.1
                        elif j == 0:
                            attention[i, j] += 0.1

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L10H13", attention



def prog_L10H14(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Attention head that focuses on sentence boundaries (periods, newlines) and first token with very strong first-token attention."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L10H14", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Find important boundary tokens
    boundary_tokens = []
    first_token_idx = 0

    for i, token in enumerate(tokens):
        if token.strip() in ['.', '\n']:
            boundary_tokens.append(i)

    for i in range(n):
        token = tokens[i].strip()

        # Base attention distribution
        for j in range(i + 1):  # causal mask
            if j == first_token_idx:
                # Much stronger attention to first token - this was too low
                attention[i, j] = 0.6
            elif j in boundary_tokens:
                # Reduced attention to periods and newlines 
                attention[i, j] = 0.2
            elif j == i:
                # Self attention baseline
                attention[i, j] = 0.1
            elif i - j <= 3:
                # Some local attention
                attention[i, j] = 0.05
            else:
                # Minimal distant attention
                attention[i, j] = 0.01

        # Reduce the boundary boost for non-boundary tokens
        if token not in ['.', '\n', '']:
            for boundary_idx in boundary_tokens:
                if boundary_idx <= i:
                    attention[i, boundary_idx] *= 1.2  # Reduced from 2.0

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L10H14", attention



def prog_L10H15(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary and document structure attention with local context."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L10H15", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Find sentence boundary tokens (periods and newlines)
    boundary_tokens = []
    for i, token in enumerate(tokens):
        if token.strip() in ['.', '\n']:
            boundary_tokens.append(i)

    # Get spacy alignment for linguistic features
    spacy_alignment = _align_to_spacy(sentence, tokens)
    doc = spacy_parse(sentence)

    for i in range(n):
        # Base uniform attention to all previous tokens
        for j in range(i + 1):
            attention[i, j] = 0.01

        # Strong attention to sentence boundaries
        for boundary_idx in boundary_tokens:
            if boundary_idx <= i:
                # First sentence boundary gets highest weight
                if boundary_idx == (boundary_tokens[0] if boundary_tokens else -1):
                    attention[i, boundary_idx] += 0.4
                else:
                    attention[i, boundary_idx] += 0.2

        # Strong attention to first token
        if i > 0:
            attention[i, 0] += 0.3

        # Self-attention
        attention[i, i] += 0.1

        # Local syntactic attention using spacy
        if i < len(spacy_alignment) and spacy_alignment[i]:
            spacy_idx = spacy_alignment[i][0]
            if spacy_idx < len(doc):
                spacy_token = doc[spacy_idx]

                # Attend to syntactic head
                if spacy_token.head != spacy_token:
                    head_spacy_idx = spacy_token.head.i
                    # Find corresponding token index
                    for k in range(min(i + 1, len(spacy_alignment))):
                        if k < len(spacy_alignment) and head_spacy_idx in spacy_alignment[k]:
                            attention[i, k] += 0.15
                            break

                # Attend to children (modifiers, etc.)
                for child in spacy_token.children:
                    child_spacy_idx = child.i
                    for k in range(min(i + 1, len(spacy_alignment))):
                        if k < len(spacy_alignment) and child_spacy_idx in spacy_alignment[k]:
                            attention[i, k] += 0.08
                            break

        # Recency bias - slight preference for recent tokens
        for j in range(max(0, i - 5), i):
            attention[i, j] += 0.02 * (1.0 - (i - j) / 6.0)

        # Semantic similarity boost
        for j in range(i):
            if _char_sim(tokens[i], tokens[j]) > 0.7:
                attention[i, j] += 0.1

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L10H15", attention



def prog_L10H16(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary and semantic content attention head with strong beginning-of-sequence attention."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    # Get spacy parse and alignment
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)
    spacy_to_token = align_spacy_to_tokens(sentence)

    for i in range(n):
        # Strong attention to sentence boundaries and structural tokens
        for j in range(i + 1):
            token = tokens[j].strip()

            # High attention to periods and newlines
            if token in ['.', '\n']:
                attention[i, j] = 0.15
            # Moderate attention to first tokens and commas
            elif j == 0 or token == ',':
                attention[i, j] = 0.08
            # Self-attention baseline
            elif i == j:
                attention[i, j] = 0.05
            else:
                attention[i, j] = 0.01

        # Add very strong attention to the first token for all later tokens
        if i > 0:
            attention[i, 0] += 0.4  # Boost attention to first token

        # Reduce self-attention to compensate for the strong first-token attention
        if i > 0:
            attention[i, i] *= 0.3  # Reduce self-attention weight

        # Add semantic similarity bonus for content words
        spacy_indices = token_to_spacy[i]
        if spacy_indices:
            spacy_token = doc[spacy_indices[0]]

            # If current token is a content word, look for related tokens
            if spacy_token.pos_ in ['NOUN', 'VERB', 'ADJ', 'PROPN']:
                for j in range(i + 1):
                    j_spacy_indices = token_to_spacy[j]
                    if j_spacy_indices:
                        j_spacy_token = doc[j_spacy_indices[0]]

                        # Boost attention between semantically similar content words
                        if j_spacy_token.pos_ in ['NOUN', 'VERB', 'ADJ', 'PROPN']:
                            similarity = _char_sim(tokens[i], tokens[j])
                            if similarity > 0.3:
                                attention[i, j] += similarity * 0.1

                        # Special boost for subject-verb and verb-object relationships
                        if (spacy_token.dep_ in ['nsubj', 'dobj'] and 
                            j_spacy_token == spacy_token.head):
                            attention[i, j] += 0.05
                        elif (j_spacy_token.dep_ in ['nsubj', 'dobj'] and 
                              spacy_token == j_spacy_token.head):
                            attention[i, j] += 0.05

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L10H16", attention



def prog_L10H17(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Attention head that focuses on paragraph boundaries (newlines, periods) and first tokens."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L10H17", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        weights = np.zeros(n)

        # Strong attention to newlines and periods
        for j in range(i + 1):
            if tokens[j].strip() == '\n':
                weights[j] += 0.4
            elif tokens[j].strip() == '.':
                weights[j] += 0.3

        # High attention to first token
        if i > 0:
            weights[0] += 0.2

        # Self-attention
        weights[i] += 0.1

        # Attention based on semantic similarity
        for j in range(i + 1):
            if i != j:
                sim = _char_sim(tokens[i], tokens[j])
                if sim > 0.3:  # Threshold for semantic similarity
                    weights[j] += 0.15 * sim

        # Attention to previous token (recency)
        if i > 0:
            weights[i - 1] += 0.1

        # Small uniform attention to all previous tokens
        for j in range(i + 1):
            weights[j] += 0.01

        # Normalize
        if weights.sum() > 0:
            weights = weights / weights.sum()
        else:
            weights[i] = 1.0

        attention[i] = weights

    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L10H17", attention



def prog_L10H18(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary attention head with strong beginning-of-sequence focus."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L10H18", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    alignment = _align_to_spacy(sentence, tokens)

    # Identify sentence-ending punctuation tokens
    sentence_endings = []
    for i, token in enumerate(tokens):
        if token.strip() in ['.', '!', '?']:
            sentence_endings.append(i)

    # Identify newline tokens
    newlines = []
    for i, token in enumerate(tokens):
        if token.strip() == '' and '\n' in token:
            newlines.append(i)

    for i in range(n):
        token = tokens[i]

        # Self-attention baseline
        attention[i, i] = 0.02

        # Strong attention to sentence-ending punctuation
        for end_idx in sentence_endings:
            if end_idx <= i:
                # Distance-based decay
                distance = i - end_idx
                if distance == 0:
                    attention[i, i] = 0.1
                elif distance <= 5:
                    attention[i, end_idx] = 0.15 - 0.02 * distance
                else:
                    attention[i, end_idx] = 0.05

        # Attention to newlines (sentence boundaries)
        for nl_idx in newlines:
            if nl_idx <= i:
                distance = i - nl_idx
                if distance <= 3:
                    attention[i, nl_idx] = 0.08 - 0.01 * distance
                else:
                    attention[i, nl_idx] = 0.03

        # Special handling for first token - ENHANCED
        if i > 0:
            # Strong beginning-of-sequence attention pattern
            if i <= 5:
                attention[i, 0] = 0.15 - 0.02 * i
            elif i <= 15:
                attention[i, 0] = 0.08 - 0.003 * (i - 5)
            else:
                attention[i, 0] = 0.05

        # Syntactic relationships within sentences
        if alignment[i]:
            spacy_idx = alignment[i][0]
            if spacy_idx < len(doc):
                spacy_token = doc[spacy_idx]

                # Attention to syntactic head
                if spacy_token.head != spacy_token:
                    for j in range(i):
                        if j < len(alignment) and alignment[j]:
                            if alignment[j][0] < len(doc) and doc[alignment[j][0]] == spacy_token.head:
                                attention[i, j] += 0.04

                # Attention between related tokens (children/dependents)
                for child in spacy_token.children:
                    for j in range(i):
                        if j < len(alignment) and alignment[j]:
                            if alignment[j][0] < len(doc) and doc[alignment[j][0]] == child:
                                attention[i, j] += 0.03

        # Embedding similarity for related words
        for j in range(i):
            if j < i - 1:  # Skip adjacent tokens
                sim = _char_sim(tokens[i], tokens[j])
                if sim > 0.7:
                    attention[i, j] += 0.04 * sim

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L10H18", attention



def prog_L10H19(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary and punctuation attention head with strong beginning-of-sentence bias."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L10H19", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        token = tokens[i]

        # Strong self-attention for first token
        if i == 0:
            attention[i, i] = 1.0
            continue

        # Identify punctuation and boundaries
        is_newline = token.strip() == '' and '\n' in token
        is_period = token.strip() == '.'
        is_comma = token.strip() == ','
        is_punct = token.strip() in '.,!?:;'

        for j in range(i + 1):  # Causal mask
            target_token = tokens[j]
            target_is_newline = target_token.strip() == '' and '\n' in target_token
            target_is_period = target_token.strip() == '.'
            target_is_punct = target_token.strip() in '.,!?:;'

            weight = 0.0

            # High attention to newlines and periods from most tokens
            if target_is_newline:
                weight += 0.15
            elif target_is_period:
                weight += 0.12
            elif target_is_punct:
                weight += 0.05

            # First token gets attention
            if j == 0:
                weight += 0.08

            # Self-attention
            if i == j:
                weight += 0.03

            # Recency bias - closer tokens get more attention
            distance = i - j
            if distance <= 3:
                weight += 0.02 * (4 - distance) / 4

            # Special patterns for punctuation tokens
            if is_newline or is_period or is_comma:
                if target_is_newline or target_is_period:
                    weight += 0.08
                if j == 0:
                    weight += 0.05

            # Boost attention between similar tokens using embeddings
            if i != j:
                sim = _char_sim(tokens[i], tokens[j])
                if sim > 0.7:
                    weight += 0.03 * sim

            # NEW: Strong bias toward beginning of sentence for distant tokens
            if distance > 5 and j == 0:
                weight += 0.25

            # NEW: Reduce attention to immediately adjacent punctuation
            if distance == 1 and (target_is_newline or target_is_period):
                weight *= 0.4

            # Positional decay
            if distance > 0:
                decay = 1.0 / (1.0 + 0.1 * distance)
                weight *= decay

            attention[i, j] = weight

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L10H19", attention



def prog_L10H2(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Structural boundary attention with enhanced first-token focus: tokens attend strongly to sentence delimiters and the sentence-initial token."""
    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    # Get spacy analysis for first token linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    # Check if first token is a semantically important sentence starter
    first_token_important = False
    if len(token_to_spacy[0]) > 0:
        first_spacy_token = doc[token_to_spacy[0][0]]
        if first_spacy_token.pos_ in ['VERB', 'AUX', 'CCONJ', 'SCONJ']:
            first_token_important = True

    # Find structural boundary tokens (newlines and periods)
    boundary_indices = []
    for i, token in enumerate(tokens):
        if token.strip() in ['\n', '.']:
            boundary_indices.append(i)

    for i in range(n):
        # Strong self-attention for first token
        if i == 0:
            attention[i, i] = 1.0
            continue

        # For other tokens, distribute attention
        for j in range(i + 1):  # Causal mask
            if j == i:
                # Moderate self-attention
                attention[i, j] = 0.3
            elif j in boundary_indices:
                # High attention to structural boundaries
                if tokens[j].strip() == '\n':
                    attention[i, j] = 0.8
                elif tokens[j].strip() == '.':
                    attention[i, j] = 0.6
            elif j == 0:
                # Enhanced attention to first token if it's semantically important
                if first_token_important:
                    attention[i, j] = 0.8
                else:
                    # Default attention to first token
                    attention[i, j] = 0.4
            else:
                # Low baseline attention to other tokens
                attention[i, j] = 0.2

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L10H2", attention



def prog_L10H20(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Attention head with very strong first-token attention and reduced self-attention on boundaries."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L10H20", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        token_i = tokens[i]

        # Strong self-attention for first token or tokens at sentence boundaries
        if i == 0 or token_i in ['\n', '.', '!', '?']:
            attention[i, i] = 1.0

        # High attention to sentence boundary markers (newlines and periods)
        for j in range(i + 1):
            token_j = tokens[j]

            # Very high attention to newlines and periods
            if token_j in ['\n', '.']:
                attention[i, j] += 0.3

            # Strong attention to first token
            if j == 0:
                attention[i, j] += 0.2

            # Local semantic similarity for nearby tokens
            if abs(i - j) <= 3 and i != j:
                sim = _char_sim(tokens[i], tokens[j])
                if sim > 0.5:  # High semantic similarity
                    attention[i, j] += 0.4 * sim

            # Moderate attention to punctuation
            if token_j in [',', ':', ';', '"', "'", '!', '?']:
                attention[i, j] += 0.1

            # Check for syntactic relationships via spacy
            if token_to_spacy[i] and token_to_spacy[j]:
                spacy_i = doc[token_to_spacy[i][0]]
                spacy_j = doc[token_to_spacy[j][0]]

                # Attention between syntactically related tokens
                if spacy_j in spacy_i.ancestors or spacy_i in spacy_j.ancestors:
                    attention[i, j] += 0.15

                # Attention from modifiers to heads
                if spacy_i.head == spacy_j:
                    attention[i, j] += 0.1

    # Special case: Much stronger first-token attention for tokens beyond position 2
    for i in range(3, n):
        attention[i, 0] += 0.6  # Boost first-token attention significantly

    # Special case: Reduce self-attention for boundary markers that aren't first token
    for i in range(1, n):
        token_i = tokens[i]
        if token_i in ['\n', '.', '!', '?']:
            attention[i, i] *= 0.3  # Reduce excessive self-attention

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L10H20", attention



def prog_L10H21(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Mixed attention head with strong sentence-initial focus, punctuation attention, and syntactic patterns."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    if n == 0:
        return "prog_L10H21", attention

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    alignment = _align_to_spacy(sentence, tokens)

    for i in range(n):
        # Strong self-attention baseline
        attention[i, i] = 1.0

        # High attention to punctuation marks, especially periods and newlines
        for j in range(i + 1):
            if tokens[j].strip() in ['.', '\n', ',', '!', '?']:
                if tokens[j].strip() == '.':
                    attention[i, j] += 2.0
                elif tokens[j].strip() == '\n':
                    attention[i, j] += 1.5
                else:
                    attention[i, j] += 0.8

        # Strong attention to first token - much higher than original
        if n > 0:
            attention[i, 0] += 2.0

        # Positional patterns - attend to recent tokens with decay
        for j in range(max(0, i - 3), i):
            distance = i - j
            attention[i, j] += 0.3 / distance

        # Syntactic relationships through spacy alignment
        if alignment[i]:
            spacy_idx = alignment[i][0]
            if spacy_idx < len(doc):
                spacy_token = doc[spacy_idx]

                # Attend to syntactic head
                if spacy_token.head != spacy_token:
                    for k in range(i + 1):
                        if alignment[k] and len(alignment[k]) > 0:
                            head_idx = alignment[k][0]
                            if head_idx < len(doc) and doc[head_idx] == spacy_token.head:
                                attention[i, k] += 0.4

                # Attend to children in dependency tree
                for child in spacy_token.children:
                    for k in range(i + 1):
                        if alignment[k] and len(alignment[k]) > 0:
                            child_idx = alignment[k][0]
                            if child_idx < len(doc) and doc[child_idx] == child:
                                attention[i, k] += 0.3

        # Semantic similarity boost
        for j in range(i + 1):
            sim = _char_sim(tokens[i], tokens[j])
            if sim > 0.7:
                attention[i, j] += 0.2 * sim

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L10H21", attention



def prog_L10H22(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary attention head with positional decay."""
    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L10H22", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Get spacy alignment for linguistic features
    token_to_spacy = _align_to_spacy(sentence, tokens)
    doc = spacy_parse(sentence)

    for i in range(n):
        for j in range(i + 1):  # Causal mask: j <= i
            weight = 0.0

            # Strong attention to sentence boundaries
            if tokens[j] in ['.', '\n']:
                if tokens[j] == '.':
                    weight += 0.2
                elif tokens[j] == '\n':
                    weight += 0.25

            # Self-attention baseline
            if i == j:
                weight += 0.05

            # First token attention (moderate)
            if j == 0:
                weight += 0.08

            # Recency bias - stronger for recent tokens
            distance = i - j
            if distance <= 5:
                weight += 0.03 * (6 - distance) / 6

            # Boost for tokens that are start of sentences or clauses
            if token_to_spacy[j]:
                spacy_idx = token_to_spacy[j][0]
                if spacy_idx < len(doc):
                    spacy_token = doc[spacy_idx]
                    if spacy_token.is_sent_start or (spacy_token.i > 0 and doc[spacy_token.i - 1].text in ['.', '\n']):
                        weight += 0.05

            # Small boost for punctuation in general
            if len(tokens[j]) == 1 and not tokens[j].isalnum():
                weight += 0.02

            # Add small random component to break ties
            weight += 0.001 * (hash(str(i) + str(j)) % 100) / 100

            attention[i, j] = weight

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L10H22", attention



def prog_L10H23(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Attends strongly to the first token (beginning-of-sequence) and moderately to punctuation."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L10H23", np.zeros((n_empty, n_empty))

    # Initialize attention matrix
    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        # Self-attention baseline
        attention[i, i] = 0.1

        for j in range(i):  # Only attend to previous tokens (causal)
            score = 0.0

            # Strong attention to punctuation marks
            if tokens[j] in ['.', ',', '!', '?', ';', ':']:
                score += 0.4

            # Strong attention to newlines (sentence boundaries)
            if '\n' in tokens[j]:
                score += 0.5

            # Attention based on embedding similarity
            sim = _char_sim(tokens[i], tokens[j])
            if sim > 0.5:
                score += 0.3 * sim

            # Boost attention to tokens that are important parts of speech
            if token_to_spacy[j]:
                spacy_idx = token_to_spacy[j][0]
                if spacy_idx < len(doc):
                    spacy_token = doc[spacy_idx]
                    # Important POS tags get boost
                    if spacy_token.pos_ in ['NOUN', 'VERB', 'PROPN']:
                        score += 0.2
                    # Named entities get boost
                    if spacy_token.ent_type_:
                        score += 0.15

            # Distance decay - closer tokens get slight preference
            distance = i - j
            if distance <= 5:
                score += 0.1 * (5 - distance) / 5

            # Special boost for first token - MUCH stronger than original
            if j == 0:
                score += 0.6  # Increased from 0.2 to 0.6

            attention[i, j] = score

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L10H23", attention



def prog_L10H24(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Structural boundary attention head focusing on first tokens, newlines, and sentence breaks."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L10H24", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        # Very high attention to first token (position 0)
        if i > 0:
            attention[i, 0] = 0.8

        # High attention to newlines and periods
        for j in range(i + 1):
            if tokens[j].strip() == '\n':
                attention[i, j] += 0.3
            elif tokens[j].strip() in ['.', '!', '?']:
                attention[i, j] += 0.25

        # Moderate attention to syntactically related tokens
        if token_to_spacy[i]:
            spacy_idx = token_to_spacy[i][0]
            if spacy_idx < len(doc):
                spacy_token = doc[spacy_idx]

                # Look for head dependencies
                if spacy_token.head != spacy_token:
                    head_token = spacy_token.head
                    for j in range(i + 1):
                        if token_to_spacy[j] and head_token.i in token_to_spacy[j]:
                            attention[i, j] += 0.1

        # Some recency bias for recent tokens
        for j in range(max(0, i - 5), i + 1):
            if j < i:
                recency_weight = 0.05 * (1.0 / (i - j + 1))
                attention[i, j] += recency_weight

        # Self-attention baseline
        attention[i, i] += 0.1

        # Small uniform distribution as baseline
        for j in range(i + 1):
            attention[i, j] += 0.01

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L10H24", attention



def prog_L10H25(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Structural boundary attention with strong first-token bias: focuses on newlines, periods, and especially the first token with distance decay."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L10H25", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    for i in range(n):
        for j in range(i + 1):  # Causal mask
            # Base attention with distance decay
            distance = i - j
            base_attention = 0.01 * (0.8 ** distance)

            # Strong boost for structural tokens
            if tokens[j] == '\n':
                base_attention += 0.3
            elif tokens[j] == '.':
                base_attention += 0.2

            # Boost for first token - this is the key addition
            if j == 0:
                base_attention += 0.1
                # Additional strong first-token bias that doesn't decay with distance
                base_attention += 0.25

            # Self-attention boost
            if i == j:
                base_attention += 0.05

            # Additional boost for tokens that are parts of structural markers
            if '.' in tokens[j] or '\n' in tokens[j]:
                base_attention += 0.15

            attention[i, j] = base_attention

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L10H25", attention



def prog_L10H26(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Discourse boundary attention with strong beginning-of-sequence focus."""
    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L10H26", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        for j in range(i + 1):  # causal mask
            weight = 0.0

            # Strong attention to punctuation marks, especially sentence boundaries
            if tokens[j] in [".", "\n", "!", "?", ";", ":"]:
                if tokens[j] in [".", "\n"]:
                    weight += 0.3  # Very high for major boundaries
                else:
                    weight += 0.15  # Medium for other punctuation

                # Distance decay for punctuation
                distance = i - j
                if distance > 0:
                    weight *= np.exp(-distance / 20.0)

            # Medium attention to commas and quotes
            elif tokens[j] in [",", '"', "'", "!", "?"]:
                weight += 0.08
                distance = i - j
                if distance > 0:
                    weight *= np.exp(-distance / 15.0)

            # Attention based on syntactic relationships
            if token_to_spacy[i] and token_to_spacy[j]:
                spacy_i = doc[token_to_spacy[i][0]]
                spacy_j = doc[token_to_spacy[j][0]]

                # Attention to syntactic heads
                if spacy_j in spacy_i.ancestors:
                    weight += 0.05

                # Attention to function words and determiners
                if spacy_j.pos_ in ["DET", "PREP", "ADP", "AUX"]:
                    weight += 0.03

                # Attention to verbs from their arguments
                if spacy_i.pos_ in ["NOUN", "PRON"] and spacy_j.pos_ == "VERB":
                    weight += 0.04

            # Semantic similarity boost
            sim = _char_sim(tokens[i], tokens[j])
            if sim > 0.7:
                weight += 0.06 * sim

            # Strong beginning-of-sequence attention - NEW PATTERN
            if j == 0 and i > 0:
                # Very strong attention to first token from all later positions
                base_first_token_weight = 0.25
                # Slight decay with distance but much slower than punctuation
                distance_factor = np.exp(-i / 50.0)
                weight += base_first_token_weight * distance_factor

            # Self-attention - reduce from original to balance with first-token attention
            if i == j:
                if i == 0:
                    weight += 0.02  # Keep original for first token
                else:
                    weight += 0.01  # Reduce for other positions

            # First token attention (original logic, but reduced since handled above)
            elif j == 0:
                weight += 0.02  # Reduced from 0.05

            # Recency bias for nearby tokens
            if i - j <= 3 and i != j and j != 0:  # Don't double-count first token
                weight += 0.02 * (4 - (i - j)) / 4

            attention[i, j] = weight

    # Normalize and apply constraints
    attention = make_row_stochastic(attention)
    attention = apply_causal_mask(attention)

    return "prog_L10H26", attention



def prog_L10H27(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary and discourse structure head that attends to newlines, periods, and first tokens."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        token = tokens[i].strip()

        # High self-attention for pronouns and some function words
        spacy_indices = token_to_spacy[i]
        is_pronoun = False
        if spacy_indices:
            spacy_token = doc[spacy_indices[0]]
            if spacy_token.pos_ == "PRON":
                is_pronoun = True

        if is_pronoun:
            attention[i, i] = 0.8

        # Strong attention to newlines
        for j in range(i + 1):
            if tokens[j].strip() == "\n":
                attention[i, j] = 0.4

        # Attention to periods
        for j in range(i + 1):
            if tokens[j].strip() == ".":
                attention[i, j] = 0.3

        # Attention to first token
        if n > 0:
            attention[i, 0] = 0.2

        # Lower attention to nearby tokens
        for j in range(max(0, i-5), i):
            if tokens[j].strip() not in ["\n", ".", ""]:
                attention[i, j] = 0.1

        # Special attention patterns for empty tokens
        if token == "":
            # Empty tokens attend strongly to previous structural elements
            for j in range(i):
                if tokens[j].strip() in ["\n", "."]:
                    attention[i, j] = 0.5
                elif j == 0:
                    attention[i, j] = 0.3

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L10H27", attention



def prog_L10H28(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """First-token attention head with structural marker detection."""
    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    for i in range(n):
        for j in range(i + 1):  # Causal mask
            weight = 0.0

            # Strong attention to first token from all positions
            if j == 0 and i > 0:
                weight += 0.7

            # Strong attention to newlines and periods as structural markers
            if tokens[j] == '\n':
                weight += 0.4
            elif tokens[j] == '.':
                weight += 0.3

            # Self-attention boost, especially for first tokens
            if i == j:
                if i == 0:  # First token gets very high self-attention
                    weight += 0.6
                else:
                    weight += 0.1

            # Attention to tokens that start sentences/clauses (after newlines or periods)
            if j > 0 and (tokens[j-1] == '\n' or tokens[j-1] == '.'):
                weight += 0.2

            # Attention to tokens immediately after structural markers
            if j > 1 and (tokens[j-2] == '\n' or tokens[j-2] == '.'):
                weight += 0.15

            # General positional bias - slight preference for earlier tokens
            position_bias = 0.05 * (1.0 - (j / max(i, 1)))
            weight += position_bias

            # Small baseline attention
            weight += 0.02

            attention[i, j] = weight

    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L10H28", attention



def prog_L10H29(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Structural attention head with strong document-boundary focus from all tokens."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention_matrix = np.zeros((n, n))

    # Find structural tokens
    first_token_idx = 0
    newline_indices = [i for i, tok in enumerate(tokens) if tok.strip() == '']
    period_indices = [i for i, tok in enumerate(tokens) if tok.strip() == '.']

    for i in range(n):
        current_token = tokens[i].strip()

        # Very strong attention from early tokens to first token
        if i <= 5:  # Early tokens
            attention_matrix[i, first_token_idx] = 0.9

        # Strong attention to newlines from most tokens
        for nl_idx in newline_indices:
            if nl_idx <= i:  # Respect causal mask
                attention_matrix[i, nl_idx] = 0.4

        # Moderate attention to periods
        for period_idx in period_indices:
            if period_idx <= i:  # Respect causal mask
                attention_matrix[i, period_idx] = 0.2

        # Self-attention for special tokens
        if current_token in ['', '.', ',']:
            attention_matrix[i, i] = 0.3

        # Some recency bias for content tokens
        if i > 0 and current_token not in ['', '.', ',']:
            attention_matrix[i, i-1] = 0.1

        # Enhanced first-token attention for later tokens
        if i > 5 and attention_matrix[i, first_token_idx] == 0:
            # Stronger baseline attention to first token for later tokens
            attention_matrix[i, first_token_idx] = 0.35

        # Baseline attention to first token for all tokens
        if attention_matrix[i, first_token_idx] == 0:
            attention_matrix[i, first_token_idx] = 0.15

    # Apply causal mask and normalize
    attention_matrix = apply_causal_mask(attention_matrix)
    attention_matrix = make_row_stochastic(attention_matrix)

    return "prog_L10H29", attention_matrix



def prog_L10H3(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Document structure attention head focusing on first tokens and line breaks."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention_matrix = np.zeros((n, n))

    # Find first token and newline positions
    first_token_idx = 0
    newline_indices = [i for i, token in enumerate(tokens) if token == '\n']
    period_indices = [i for i, token in enumerate(tokens) if token == '.']

    for i in range(n):
        current_token = tokens[i]

        # Very high attention to first token (especially for early tokens)
        if i < 5:  # First few tokens attend very strongly to first token
            attention_matrix[i, first_token_idx] = 0.9
        else:
            attention_matrix[i, first_token_idx] = 0.3

        # High attention to previous newlines
        for nl_idx in newline_indices:
            if nl_idx < i:  # Can only attend to previous tokens
                # Closer newlines get higher attention
                distance = i - nl_idx
                if distance <= 10:
                    attention_matrix[i, nl_idx] = 0.5 / (1 + distance * 0.1)
                else:
                    attention_matrix[i, nl_idx] = 0.2

        # Moderate attention to periods (sentence boundaries)
        for period_idx in period_indices:
            if period_idx < i:
                distance = i - period_idx
                if distance <= 5:
                    attention_matrix[i, period_idx] = 0.3 / (1 + distance * 0.1)
                else:
                    attention_matrix[i, period_idx] = 0.15

        # Self-attention for punctuation
        if current_token in ['.', '!', '?']:
            attention_matrix[i, i] = 0.4
        else:
            attention_matrix[i, i] = 0.1

        # Special case: tokens immediately after newlines get boosted attention to the newline
        if i > 0 and tokens[i-1] == '\n':
            attention_matrix[i, i-1] = 0.6

    # Apply causal mask and normalize
    attention_matrix = apply_causal_mask(attention_matrix)
    attention_matrix = make_row_stochastic(attention_matrix)

    return "prog_L10H3", attention_matrix



def prog_L10H30(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Attention to structurally important early tokens and sentence boundaries."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L10H30", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Parse with spacy to get linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        # Strong attention to first few tokens
        for j in range(min(i + 1, 3)):
            if j == 0:
                attention[i, j] += 0.4  # Very strong attention to first token
            elif j == 1:
                attention[i, j] += 0.2  # Strong attention to second token
            else:
                attention[i, j] += 0.1

        # Strong attention to punctuation, especially sentence boundaries
        for j in range(i + 1):
            token = tokens[j].strip()
            if token in ['.', '!', '?']:
                attention[i, j] += 0.25
            elif token == '\n':
                attention[i, j] += 0.3
            elif token in [',', ';', ':']:
                attention[i, j] += 0.1

        # Self-attention
        attention[i, i] += 0.05

        # Moderate attention to recent tokens (recency bias)
        for j in range(max(0, i - 3), i):
            distance = i - j
            attention[i, j] += 0.1 / distance

        # Attention to tokens that start new sentences or paragraphs
        for j in range(i + 1):
            if j < len(token_to_spacy) and token_to_spacy[j]:
                spacy_indices = token_to_spacy[j]
                if spacy_indices:
                    spacy_token = doc[spacy_indices[0]]
                    # Check if this starts a sentence
                    if spacy_token.is_sent_start:
                        attention[i, j] += 0.15
                    # Check if this is a proper noun or important content word at sentence start
                    if spacy_token.pos_ in ['PROPN', 'NOUN'] and spacy_token.is_sent_start:
                        attention[i, j] += 0.1

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L10H30", attention



def prog_L10H31(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Structural boundary attention head that focuses on sentence delimiters, first tokens, and cross-sentence newline attention."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L10H31", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Identify boundary tokens (periods and newlines)
    boundary_tokens = []
    for i, token in enumerate(tokens):
        if token.strip() in ['.', '\n']:
            boundary_tokens.append(i)

    # Find sentence/section starts (tokens after boundaries or at beginning)
    section_starts = [0]  # First token is always a section start
    for boundary_idx in boundary_tokens:
        if boundary_idx + 1 < n:
            # Skip empty string tokens as section starts
            next_token = tokens[boundary_idx + 1].strip()
            if next_token != '':
                section_starts.append(boundary_idx + 1)

    for i in range(n):
        current_token = tokens[i].strip()

        # Self-attention baseline
        attention[i, i] = 0.1

        # Strong attention to boundary tokens (periods and newlines)
        for boundary_idx in boundary_tokens:
            if boundary_idx <= i:
                if current_token in ['.', '\n']:
                    attention[i, boundary_idx] = 0.4
                else:
                    attention[i, boundary_idx] = 0.3

        # NEW: Cross-sentence attention to newlines - tokens attend to earlier newlines
        for j in range(i):
            if tokens[j].strip() == '\n':
                # Stronger attention to newlines from later tokens
                attention[i, j] = 0.35

        # Find the section start for current token
        current_section_start = 0
        for start_idx in section_starts:
            if start_idx <= i:
                current_section_start = start_idx
            else:
                break

        # High attention to section start
        if current_section_start != i:
            attention[i, current_section_start] = 0.25

        # Local context attention (previous few tokens)
        for j in range(max(0, i-3), i):
            if tokens[j].strip() not in ['.', '\n']:
                distance_decay = 0.05 * (1.0 / (i - j))
                attention[i, j] += distance_decay

        # Special handling for boundary tokens themselves
        if current_token in ['.', '\n']:
            # Strong self-attention for boundaries
            attention[i, i] = 0.5

            # Moderate attention to other boundaries
            for other_boundary in boundary_tokens:
                if other_boundary < i:
                    attention[i, other_boundary] = 0.2

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L10H31", attention



def prog_L10H4(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Structural delimiter attention with enhanced first-token attention for content words."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L10H4", np.zeros((n_empty, n_empty)).reshape(0, 0)

    attention = np.zeros((n, n))

    # Check if first token should receive enhanced attention
    doc = spacy_parse(sentence)
    alignment = _align_to_spacy(sentence, tokens)

    # Determine if first token is a content word that should get strong attention
    first_token_enhanced = False
    if len(alignment[0]) > 0:
        first_spacy_idx = alignment[0][0]
        if first_spacy_idx < len(doc):
            first_spacy_token = doc[first_spacy_idx]
            # Enhanced attention if first token is a content word (NOUN, VERB, ADJ, ADV)
            if first_spacy_token.pos_ in ['NOUN', 'VERB', 'ADJ', 'ADV']:
                first_token_enhanced = True

    for i in range(n):
        # Very strong self-attention for first token
        if i == 0:
            attention[i, i] = 1.0
            continue

        # Find structural delimiters (newlines and periods)
        newline_indices = []
        period_indices = []

        for j in range(i + 1):  # Only consider positions up to i (causal)
            token = tokens[j].strip()
            if '\n' in tokens[j]:
                newline_indices.append(j)
            elif token == '.' or token.endswith('.'):
                period_indices.append(j)

        # Strong attention to newlines, especially the first one
        newline_weight = 0.4
        for idx, j in enumerate(newline_indices):
            # First newline gets strongest weight, others decay
            weight = newline_weight * (0.9 ** idx)
            attention[i, j] = weight

        # Moderate attention to periods
        period_weight = 0.35
        for idx, j in enumerate(period_indices):
            # Don't double-count if already counted as newline
            if j not in newline_indices:
                weight = period_weight * (0.9 ** idx)
                attention[i, j] = weight

        # Enhanced attention to first token if it's a content word
        if first_token_enhanced and 0 not in newline_indices and 0 not in period_indices:
            attention[i, 0] = 0.3  # Much stronger than original 0.1
        # Small attention to first token if it hasn't been covered (original logic)
        elif 0 not in newline_indices and 0 not in period_indices:
            attention[i, 0] = 0.1

        # Fill remaining attention somewhat randomly across available positions
        current_sum = attention[i].sum()
        if current_sum < 1.0:
            remaining = 1.0 - current_sum
            # Distribute remaining attention with slight recency bias
            for j in range(i + 1):
                if attention[i, j] == 0:
                    # Slight bias toward more recent tokens
                    bias = 1.0 + 0.1 * (i - j) / max(1, i)
                    attention[i, j] = remaining * bias / (i + 1)

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L10H4", attention



def prog_L10H5(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Attention head that focuses strongly on the first token with minimal self-attention."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L10H5", np.zeros((n_empty, n_empty))

    attention_matrix = np.zeros((n, n))

    # Find structural boundary tokens
    newline_indices = [i for i, token in enumerate(tokens) if token.strip() == '\n']
    period_indices = [i for i, token in enumerate(tokens) if token.strip() == '.']
    first_token_idx = 0

    for i in range(n):
        # Initialize with small baseline attention
        for j in range(i + 1):  # Only attend to previous tokens (causal)
            attention_matrix[i, j] = 0.1

        # Much stronger attention to first token - this was the main issue
        if i > 5:  # For tokens beyond position 5, give massive attention to first token
            attention_matrix[i, first_token_idx] += 1.2  # Increased from 0.8
        else:
            attention_matrix[i, first_token_idx] += 0.8

        # Strong attention to newline tokens
        for nl_idx in newline_indices:
            if nl_idx <= i:
                attention_matrix[i, nl_idx] += 0.6

        # Strong attention to period tokens  
        for p_idx in period_indices:
            if p_idx <= i:
                attention_matrix[i, p_idx] += 0.5

        # Reduce self-attention significantly - this was over-predicted
        if i > 0:  # Don't boost self-attention for non-first tokens
            attention_matrix[i, i] += 0.1  # Reduced from 0.3
        else:
            attention_matrix[i, i] += 0.3  # Keep original for first token

        # Slight recency bias - closer tokens get slightly more attention
        for j in range(max(0, i-5), i):
            distance = i - j
            attention_matrix[i, j] += 0.1 / (distance + 1)

    # Apply causal mask and normalize
    attention_matrix = apply_causal_mask(attention_matrix)
    attention_matrix = make_row_stochastic(attention_matrix)

    return "prog_L10H5", attention_matrix



def prog_L10H6(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Structural boundary attention head focusing on newlines, periods, and first tokens."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L10H6", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Find structural markers
    first_token_idx = 0
    newline_indices = [i for i, token in enumerate(tokens) if token.strip() == '\n']
    period_indices = [i for i, token in enumerate(tokens) if token.strip() == '.']

    for i in range(n):
        # Strong self-attention for first token
        if i == 0:
            attention[i, i] = 1.0
            continue

        # For other tokens, distribute attention to structural markers
        weights = np.zeros(i + 1)  # Can only attend to previous tokens (causal)

        # Base attention to first token
        weights[first_token_idx] = 0.3

        # Strong attention to newlines
        for nl_idx in newline_indices:
            if nl_idx <= i:
                weights[nl_idx] = 0.4

        # Moderate attention to periods
        for p_idx in period_indices:
            if p_idx <= i:
                weights[p_idx] = 0.2

        # Small attention to immediately previous token
        if i > 0:
            weights[i-1] = 0.1

        # Self attention
        weights[i] = 0.05

        # Normalize
        if weights.sum() > 0:
            weights = weights / weights.sum()
            attention[i, :i+1] = weights
        else:
            attention[i, i] = 1.0

    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L10H6", attention



def prog_L10H7(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary attention head: attends to first token and sentence-ending punctuation."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L10H7", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Find sentence-ending punctuation (periods)
    period_indices = []
    for i, token in enumerate(tokens):
        if token.strip() == '.':
            period_indices.append(i)

    for i in range(n):
        current_token = tokens[i].strip()

        # Self-attention for special tokens (periods and first token)
        if i == 0 or current_token == '.':
            attention[i, i] = 1.0

        # First token gets maximum attention from most other tokens
        elif i > 0:
            attention[i, 0] = 0.6  # Base attention to first token

            # Additional attention to sentence-ending periods
            for period_idx in period_indices:
                if period_idx < i:  # Causal constraint
                    attention[i, period_idx] = 0.35

            # Small self-attention
            attention[i, i] = 0.05

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L10H7", attention



def prog_L10H8(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Boundary-aware syntactic attention with strong early token bias and semantic similarity."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L10H8", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        # Strong self-attention for first token
        if i == 0:
            attention[i, i] = 1.0
            continue

        # Base attention distribution
        for j in range(i + 1):  # Causal mask

            # High attention to boundary markers
            if tokens[j] in ['\n', '.', '!', '?']:
                attention[i, j] += 0.3

            # Moderate attention to punctuation
            elif tokens[j] in [',', ';', ':', '"', "'", '(', ')']:
                attention[i, j] += 0.1

            # Self-attention boost
            if i == j:
                attention[i, j] += 0.1

            # Recent token bias (exponential decay)
            distance = i - j
            if distance <= 3:
                attention[i, j] += 0.1 * (0.7 ** distance)

            # Strong early token bias - attend back to very early positions
            if j <= 2 and i > 5:  # For tokens beyond position 5, boost attention to first 3 tokens
                early_boost = 0.4 * (1.0 / (j + 1))  # Stronger boost for earlier positions
                attention[i, j] += early_boost

            # Semantic similarity boost
            sim = _char_sim(tokens[i], tokens[j])
            if sim > 0.5:
                attention[i, j] += 0.2 * sim

            # Syntactic relationship boost
            if token_to_spacy[i] and token_to_spacy[j]:
                spacy_i = token_to_spacy[i][0] if token_to_spacy[i] else None
                spacy_j = token_to_spacy[j][0] if token_to_spacy[j] else None

                if spacy_i is not None and spacy_j is not None and spacy_i < len(doc) and spacy_j < len(doc):
                    tok_i = doc[spacy_i]
                    tok_j = doc[spacy_j]

                    # Head-dependent relationships
                    if tok_i.head == tok_j or tok_j.head == tok_i:
                        attention[i, j] += 0.15

                    # Same syntactic role
                    if tok_i.dep_ == tok_j.dep_ and tok_i.dep_ in ['nsubj', 'dobj', 'pobj']:
                        attention[i, j] += 0.1

                    # Verb-object relationships
                    if (tok_i.pos_ == 'VERB' and tok_j.dep_ == 'dobj') or (tok_j.pos_ == 'VERB' and tok_i.dep_ == 'dobj'):
                        attention[i, j] += 0.1

            # Small random baseline
            attention[i, j] += 0.01

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L10H8", attention



def prog_L10H9(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Structural boundary attention head focusing on newlines and sentence endings."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention_matrix = np.zeros((n, n))

    # Find structural markers
    newline_indices = [i for i, token in enumerate(tokens) if token.strip() == '\n']
    period_indices = [i for i, token in enumerate(tokens) if token.strip() in ['.', '!', '?']]

    for i in range(n):
        current_token = tokens[i].strip()

        # Base attention distribution
        for j in range(i + 1):  # Causal mask
            # High attention to newlines and periods
            if j in newline_indices:
                attention_matrix[i, j] = 0.4
            elif j in period_indices:
                attention_matrix[i, j] = 0.25
            # Self-attention
            elif i == j:
                attention_matrix[i, j] = 0.1
            # Previous token attention
            elif j == i - 1:
                attention_matrix[i, j] = 0.08
            # Embedding similarity bonus
            elif _char_sim(tokens[i], tokens[j]) > 0.7:
                attention_matrix[i, j] = 0.06
            else:
                attention_matrix[i, j] = 0.02

        # Special handling for structural tokens themselves
        if current_token == '\n':
            # Newlines attend strongly to previous periods
            for j in period_indices:
                if j < i:
                    attention_matrix[i, j] = 0.5
        elif current_token in ['.', '!', '?']:
            # Periods attend to previous newlines and self
            for j in newline_indices:
                if j < i:
                    attention_matrix[i, j] = 0.3
            attention_matrix[i, i] = 0.2

        # First token gets some extra attention from all tokens
        if len(tokens) > 0:
            attention_matrix[i, 0] += 0.05

    # Normalize and apply causal mask
    attention_matrix = apply_causal_mask(attention_matrix)
    attention_matrix = make_row_stochastic(attention_matrix)

    return "prog_L10H9", attention_matrix



def prog_L11H0(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Structural boundary detection head with enhanced long-range attention to text beginnings and major boundaries."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        token = tokens[i]

        # Strong self-attention for first token
        if i == 0:
            attention[i, i] = 1.0
            continue

        # Base attention distribution
        for j in range(i + 1):  # Causal mask
            target_token = tokens[j]

            # High attention to punctuation marks
            if target_token in ['.', '!', '?', ',', ';', ':', '"', "'", '(', ')', '[', ']']:
                attention[i, j] = 0.3

            # High attention to newlines and whitespace
            elif target_token.strip() == '' or '\n' in target_token:
                attention[i, j] = 0.25

            # Moderate attention to first token
            elif j == 0:
                attention[i, j] = 0.15

            # Self-attention
            elif i == j:
                attention[i, j] = 0.1

            # Check for sentence boundaries using spacy
            elif token_to_spacy[j]:
                spacy_idx = token_to_spacy[j][0]
                if spacy_idx < len(doc):
                    spacy_token = doc[spacy_idx]
                    # Sentence start tokens get higher attention
                    if spacy_token.sent.start == spacy_idx:
                        attention[i, j] = 0.2
                    # End of sentence tokens
                    elif spacy_token.sent.end - 1 == spacy_idx:
                        attention[i, j] = 0.18
                    else:
                        attention[i, j] = 0.05
            else:
                attention[i, j] = 0.05

        # Add positional decay
        for j in range(i + 1):
            distance = i - j
            if distance > 0:
                attention[i, j] *= np.exp(-0.1 * distance)

        # ENHANCEMENT: Long-range attention to text beginnings and major structural boundaries
        # This counteracts excessive decay for important structural positions
        if i > 10:  # Only for tokens far from the beginning
            for j in range(min(i, 5)):  # First few tokens
                target_token = tokens[j]
                # Boost attention to very early tokens, especially structural ones
                if j == 0 or target_token.strip() == '' or '\n' in target_token:
                    attention[i, j] *= 3.0  # Strong boost to counteract decay
                elif target_token in ['.', '!', '?']:
                    attention[i, j] *= 2.5

            # Also boost attention to major sentence boundaries within the sequence
            for j in range(i):
                target_token = tokens[j]
                if target_token in ['.', '!', '?'] and j < i - 5:  # Distant sentence boundaries
                    attention[i, j] *= 2.0

        # Boost attention for tokens that are syntactically important
        if token_to_spacy[i]:
            spacy_idx = token_to_spacy[i][0]
            if spacy_idx < len(doc):
                spacy_token = doc[spacy_idx]
                # If current token is a verb, attend more to subjects/objects
                if spacy_token.pos_ in ['VERB', 'AUX']:
                    for j in range(i):
                        if token_to_spacy[j]:
                            target_spacy_idx = token_to_spacy[j][0]
                            if target_spacy_idx < len(doc):
                                target_spacy = doc[target_spacy_idx]
                                if target_spacy.dep_ in ['nsubj', 'dobj', 'pobj']:
                                    attention[i, j] *= 1.5

    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L11H0", attention



def prog_L11H1(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary and structural marker attention head with strong beginning-of-sequence attention."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L11H1", np.zeros((n_empty, n_empty))

    # Initialize attention matrix
    attention = np.zeros((n, n))

    # Parse sentence with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        for j in range(i + 1):  # Causal mask: only attend to j <= i

            # Base attention score
            score = 0.01

            # Strong attention to first token (beginning-of-sequence bias)
            if j == 0 and i > 0:
                # Very strong attention to first token, especially from later positions
                distance_from_start = i
                if distance_from_start <= 10:
                    score += 0.7 * (1.0 - distance_from_start * 0.05)
                else:
                    score += 0.3

            # Strong attention to sentence-ending punctuation
            elif tokens[j] in ['.', '!', '?']:
                score += 0.4

            # Strong attention to newlines (structural markers)
            elif tokens[j] == '\n':
                score += 0.3

            # Self-attention (reduced to avoid over-prediction)
            elif i == j:
                score += 0.03

            # Attention to commas and other punctuation
            elif tokens[j] in [',', ';', ':', '"', "'", '(', ')']:
                score += 0.08

            # Distance-based decay for nearby tokens
            if j != 0:  # Skip distance decay for first token (already handled above)
                distance = i - j
                if distance <= 5:
                    score += 0.03 * (1.0 / (1 + distance * 0.5))

            # Boost for tokens that are structurally important
            if token_to_spacy[j]:
                spacy_idx = token_to_spacy[j][0]
                if spacy_idx < len(doc):
                    spacy_token = doc[spacy_idx]
                    # Boost for sentence roots and important syntactic roles
                    if spacy_token.dep_ in ['ROOT', 'nsubj', 'dobj']:
                        score += 0.05

            attention[i, j] = score

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L11H1", attention



def prog_L11H10(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary and first-token anchoring with local syntactic attention."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L11H10", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        # Base attention distribution
        base_weights = np.zeros(i + 1)

        # Strong attention to sentence boundaries (periods, newlines)
        for j in range(i + 1):
            token = tokens[j].strip()
            if token in ['.', '\n']:
                base_weights[j] += 3.0

        # Strong attention to first token
        if i > 0:
            base_weights[0] += 2.0

        # Moderate attention to recent tokens (recency bias)
        for j in range(max(0, i - 5), i + 1):
            base_weights[j] += 0.5 * (1.0 / (i - j + 1))

        # Local syntactic attention
        if token_to_spacy[i]:
            spacy_idx = token_to_spacy[i][0]
            if spacy_idx < len(doc):
                spacy_token = doc[spacy_idx]

                # Attention to syntactic head
                if spacy_token.head != spacy_token:
                    for j in range(i + 1):
                        if token_to_spacy[j] and any(head_idx in token_to_spacy[j] 
                                                   for head_idx in range(len(doc)) 
                                                   if head_idx < len(doc) and doc[head_idx] == spacy_token.head):
                            base_weights[j] += 0.8

                # Articles and determiners attend to their noun
                if spacy_token.pos_ in ['DET', 'ART']:
                    for child in spacy_token.children:
                        if child.pos_ in ['NOUN', 'PROPN']:
                            for j in range(i + 1):
                                if token_to_spacy[j] and any(child_idx in token_to_spacy[j]
                                                           for child_idx in range(len(doc))
                                                           if child_idx < len(doc) and doc[child_idx] == child):
                                    base_weights[j] += 1.0

        # Content similarity boost
        for j in range(i + 1):
            if i != j:
                sim = _char_sim(tokens[i], tokens[j])
                if sim > 0.5:
                    base_weights[j] += 0.5 * sim

        # Self-attention baseline
        base_weights[i] += 0.2

        # Ensure non-zero weights
        if np.sum(base_weights) == 0:
            base_weights[i] = 1.0

        attention[i, :i + 1] = base_weights

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L11H10", attention



def prog_L11H11(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Boundary token attention head with strong first-token anchoring - attends to delimiters and strongly to sequence start."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention_matrix = np.zeros((n, n))

    # Identify boundary tokens (newlines, periods, and other sentence delimiters)
    boundary_indices = []
    for i, token in enumerate(tokens):
        if token.strip() in ['\n', '.', '!', '?', ';']:
            boundary_indices.append(i)

    for i in range(n):
        # Very strong attention to the first token from all later positions
        if i > 0:
            attention_matrix[i, 0] = 0.6

        # Strong attention to boundary tokens
        for boundary_idx in boundary_indices:
            if boundary_idx <= i:  # Causal constraint
                if boundary_idx == 0:
                    # Don't double-count first token if it's also a boundary
                    continue
                attention_matrix[i, boundary_idx] = 0.3

        # Moderate attention to semantically similar tokens
        for j in range(i + 1):
            if j not in boundary_indices and j != 0:
                sim = _char_sim(tokens[i], tokens[j])
                if sim > 0.5:  # Threshold for semantic similarity
                    attention_matrix[i, j] += 0.05

        # Light recency bias - higher attention to recent tokens
        for j in range(max(0, i - 5), i + 1):
            if j not in boundary_indices and j != 0:
                recency_weight = 0.02 * (1 + j - max(0, i - 5))
                attention_matrix[i, j] += recency_weight

        # Self-attention baseline
        attention_matrix[i, i] += 0.01

    # Apply causal mask and normalize
    attention_matrix = apply_causal_mask(attention_matrix)
    attention_matrix = make_row_stochastic(attention_matrix)

    return "prog_L11H11", attention_matrix



def prog_L11H12(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Structural delimiter attention head with strong preference for sentence-initial tokens."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L11H12", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Find structural delimiter tokens
    delimiters = []
    for i, token in enumerate(tokens):
        if token.strip() in ['.', '\n', '!', '?']:
            delimiters.append(i)

    # Identify sentence-initial token (usually position 0)
    sentence_initial = 0 if n > 0 else None

    for i in range(n):
        # Very strong attention to sentence-initial token
        if sentence_initial is not None and sentence_initial <= i:
            attention[i, sentence_initial] = 0.6

        # Strong attention to structural delimiters (but less than sentence-initial)
        for delimiter_idx in delimiters:
            if delimiter_idx <= i:  # Causal constraint
                # Reduce delimiter attention if sentence-initial already handled
                base_weight = 0.2 if sentence_initial is not None else 0.3
                if tokens[delimiter_idx].strip() == '\n':
                    attention[i, delimiter_idx] = base_weight + 0.1
                elif tokens[delimiter_idx].strip() in ['.', '!', '?']:
                    attention[i, delimiter_idx] = base_weight

        # Self-attention for delimiter tokens themselves
        if i in delimiters:
            attention[i, i] = 0.5

        # Moderate attention to previous few tokens
        for j in range(max(0, i-3), i):
            if j not in delimiters and j != sentence_initial:
                attention[i, j] = 0.05

        # Weak attention to semantically similar tokens
        for j in range(i):
            if j not in delimiters and i not in delimiters and j != sentence_initial:
                sim = _char_sim(tokens[i], tokens[j])
                if sim > 0.7:  # High similarity threshold
                    attention[i, j] += 0.04

        # Base attention to first token if it exists and not already handled
        if i > 0 and sentence_initial != 0:
            attention[i, 0] = 0.02

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L11H12", attention



def prog_L11H13(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Boundary and structure-aware attention with local semantic relationships."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L11H13", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    # Identify boundary tokens (periods, newlines, first token)
    boundary_tokens = set()
    boundary_tokens.add(0)  # First token

    for i, token in enumerate(tokens):
        if token.strip() in ['.', '\n', '!', '?']:
            boundary_tokens.add(i)

    for i in range(n):
        # Strong attention to boundary tokens
        for boundary_idx in boundary_tokens:
            if boundary_idx <= i:
                if boundary_idx == 0:  # First token gets extra weight
                    attention[i, boundary_idx] = 0.6
                elif tokens[boundary_idx].strip() == '\n':  # Newlines get high weight
                    attention[i, boundary_idx] = 0.4
                else:  # Other boundaries (periods, etc.)
                    attention[i, boundary_idx] = 0.3

        # Self-attention
        attention[i, i] = 0.2

        # Local context attention based on linguistic features
        if token_to_spacy[i]:
            spacy_idx = token_to_spacy[i][0]
            if spacy_idx < len(doc):
                spacy_token = doc[spacy_idx]

                # Look for syntactic relationships in nearby tokens
                for j in range(max(0, i-5), i):
                    if token_to_spacy[j] and token_to_spacy[j][0] < len(doc):
                        other_spacy = doc[token_to_spacy[j][0]]

                        # Dependency relationships
                        if (other_spacy == spacy_token.head or 
                            spacy_token == other_spacy.head):
                            attention[i, j] += 0.15

                        # Similar POS tags
                        if spacy_token.pos_ == other_spacy.pos_ and spacy_token.pos_ in ['NOUN', 'VERB', 'ADJ']:
                            attention[i, j] += 0.1

                        # Semantic similarity
                        sim = _char_sim(tokens[i], tokens[j])
                        if sim > 0.7:
                            attention[i, j] += 0.1 * sim

        # Recent token bias (previous few tokens)
        for j in range(max(0, i-3), i):
            attention[i, j] += 0.05

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L11H13", attention



def prog_L11H14(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Attention head combining structural boundaries (newlines, periods, first token) with semantic similarity, with strong preference for newlines."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        # Base attention to self
        attention[i, i] = 0.1

        # Strong attention to newlines and periods
        for j in range(i + 1):
            token_text = tokens[j].strip()
            # Check for newlines more robustly - look for actual newline character
            if '\n' in tokens[j]:
                attention[i, j] += 0.6  # Much stronger for newlines
            elif token_text == '.':
                attention[i, j] += 0.15  # Reduced for periods

        # Strong attention to first token (position 0)
        if i > 0:
            attention[i, 0] += 0.25

        # Semantic similarity component
        for j in range(i + 1):
            if i != j:
                sim = _char_sim(tokens[i], tokens[j])
                if sim > 0.5:  # High semantic similarity
                    attention[i, j] += 0.15 * sim

        # Syntactic relationships via spacy
        if token_to_spacy[i]:
            spacy_idx = token_to_spacy[i][0]
            if spacy_idx < len(doc):
                spacy_token = doc[spacy_idx]

                # Attention from adjectives to their head nouns
                if spacy_token.pos_ == 'ADJ' and spacy_token.head != spacy_token:
                    head_idx = spacy_token.head.i
                    for j in range(i + 1):
                        if token_to_spacy[j] and head_idx in token_to_spacy[j]:
                            attention[i, j] += 0.2

                # Attention to modifying adjectives
                for child in spacy_token.children:
                    if child.dep_ == 'amod':
                        child_idx = child.i
                        for j in range(i + 1):
                            if token_to_spacy[j] and child_idx in token_to_spacy[j]:
                                attention[i, j] += 0.15

        # Local previous token attention
        if i > 0:
            attention[i, i-1] += 0.08

        # Recency bias for recent tokens
        for j in range(max(0, i-5), i):
            distance = i - j
            if distance > 0:
                attention[i, j] += 0.05 / distance

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L11H14", attention



def prog_L11H15(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Structural boundary attention head focusing on newlines, periods, and first tokens."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L11H15", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    for i in range(n):
        scores = np.zeros(i + 1)  # Can only attend to tokens j <= i

        for j in range(i + 1):
            # Base score starts low
            score = 0.01

            # Very high attention to newlines
            if tokens[j].strip() == '' or '\n' in tokens[j]:
                score += 3.0

            # High attention to periods and sentence endings
            if '.' in tokens[j] or tokens[j] in ['.', '."', '.\'']:
                score += 2.0

            # Strong attention to first token
            if j == 0:
                score += 1.5

            # Self-attention boost
            if i == j:
                score += 0.3

            # Recency bias - prefer recent tokens
            distance = i - j
            if distance > 0:
                recency_bonus = max(0, 0.5 - 0.05 * distance)
                score += recency_bonus

            # Semantic similarity boost
            if i != j:
                sim = _char_sim(tokens[i], tokens[j])
                if sim > 0.3:
                    score += sim * 0.5

            # Special boost for certain punctuation patterns
            if tokens[j] in [',', '"', '?"', ',"']:
                score += 0.3

            scores[j] = score

        # Normalize to create probability distribution
        if scores.sum() > 0:
            attention[i, :i+1] = scores / scores.sum()
        else:
            # Fallback to uniform distribution
            attention[i, :i+1] = 1.0 / (i + 1)

    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L11H15", attention



def prog_L11H16(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary and structural attention head with focus on newlines and periods."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L11H16", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Parse sentence for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        # Initialize weights
        weights = np.zeros(n)

        # Strong attention to newlines and periods - FIXED: check all previous tokens
        for j in range(i + 1):
            if tokens[j].strip() == '\n':
                weights[j] += 3.0
            elif tokens[j].strip() == '.':
                weights[j] += 2.5

        # Reduce excessive self-attention for certain token types
        self_attention_boost = 0.5
        if token_to_spacy[i]:
            spacy_i = token_to_spacy[i][0]
            if spacy_i < len(doc):
                pos = doc[spacy_i].pos_
                # Reduce self-attention for content words that tend to be over-predicted
                if pos in ['NOUN', 'VERB', 'ADJ']:
                    self_attention_boost = 0.2

        # Self-attention
        weights[i] += self_attention_boost

        # First token attention
        if i > 0:
            weights[0] += 1.0

        # Attention to previous token
        if i > 0:
            weights[i-1] += 0.3

        # Syntactic attention - look for dependencies
        if token_to_spacy[i]:
            spacy_i = token_to_spacy[i][0]
            if spacy_i < len(doc):
                spacy_token = doc[spacy_i]

                # Attend to syntactic head
                if spacy_token.head != spacy_token:
                    head_idx = spacy_token.head.i
                    for j in range(i + 1):
                        if token_to_spacy[j] and head_idx in token_to_spacy[j]:
                            weights[j] += 0.4
                            break

                # Attend to modifiers
                for child in spacy_token.children:
                    child_idx = child.i
                    for j in range(i + 1):
                        if token_to_spacy[j] and child_idx in token_to_spacy[j]:
                            weights[j] += 0.2
                            break

        # Semantic similarity boost
        for j in range(i + 1):
            if i != j:
                sim = _char_sim(tokens[i], tokens[j])
                if sim > 0.7:
                    weights[j] += 0.3 * sim

        # Position-based decay
        for j in range(i + 1):
            distance = i - j
            if distance > 0:
                weights[j] *= (0.9 ** min(distance, 10))

        # Special boost for conjunctions and prepositions
        if token_to_spacy[i]:
            spacy_i = token_to_spacy[i][0]
            if spacy_i < len(doc):
                pos = doc[spacy_i].pos_
                if pos in ['CCONJ', 'ADP']:
                    # Look for related content words
                    for j in range(i + 1):
                        if token_to_spacy[j]:
                            spacy_j = token_to_spacy[j][0]
                            if spacy_j < len(doc) and doc[spacy_j].pos_ in ['NOUN', 'VERB', 'ADJ']:
                                weights[j] += 0.3

        attention[i] = weights

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L11H16", attention



def prog_L11H17(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Attention head that focuses on sentence boundaries (newlines, periods) and first token with semantic similarity."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention_matrix = np.zeros((n, n))

    for i in range(n):
        scores = np.zeros(i + 1)  # Only attend to tokens up to position i

        # Find boundary tokens (newlines and periods)
        boundary_indices = []
        for j in range(i + 1):
            token = tokens[j].strip()
            if token == '\n' or token == '.':
                boundary_indices.append(j)

        # High attention to boundary tokens
        if boundary_indices:
            for j in boundary_indices:
                scores[j] = 0.4

        # Strong attention to first token
        if i >= 0:
            scores[0] += 0.3

        # Moderate self-attention
        scores[i] += 0.2

        # Add semantic similarity component for remaining positions
        for j in range(i + 1):
            if j not in boundary_indices and j != 0 and j != i:
                sim = _char_sim(tokens[i], tokens[j])
                if sim > 0.5:  # Only boost if reasonably similar
                    scores[j] += 0.1 * sim

        # Add small baseline attention to all positions
        for j in range(i + 1):
            scores[j] += 0.01

        # Normalize
        if scores.sum() > 0:
            scores = scores / scores.sum()

        attention_matrix[i, :i+1] = scores

    attention_matrix = apply_causal_mask(attention_matrix)
    attention_matrix = make_row_stochastic(attention_matrix)

    return "prog_L11H17", attention_matrix



def prog_L11H18(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Attention to sentence/section boundary markers with strong first-token reference for salient initial tokens."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention_matrix = np.zeros((n, n))

    # Find positions of structural markers (newlines and periods)
    boundary_positions = []
    for i, token in enumerate(tokens):
        if token.strip() in ['\n', '.']:
            boundary_positions.append(i)

    # Check if first token is salient (content word, not just punctuation/whitespace)
    first_token_is_salient = False
    if n > 0:
        first_token = tokens[0].strip()
        if first_token and first_token not in [',', '.', '!', '?', ';', ':', '\n', ' ', '']:
            # Use spacy to check if it's a content word
            spacy_alignment = _align_to_spacy(sentence, tokens)
            if spacy_alignment[0]:  # First token aligns to some spacy token
                doc = spacy_parse(sentence)
                first_spacy_idx = spacy_alignment[0][0]
                if first_spacy_idx < len(doc):
                    spacy_token = doc[first_spacy_idx]
                    # Salient if it's a proper noun, noun, verb, or adjective
                    if spacy_token.pos_ in ['PROPN', 'NOUN', 'VERB', 'ADJ']:
                        first_token_is_salient = True

    for i in range(n):
        # Self-attention baseline
        attention_matrix[i, i] = 0.1

        # Strong attention to boundary markers
        for boundary_pos in boundary_positions:
            if boundary_pos <= i:
                # Distance-based decay from boundary marker
                distance = i - boundary_pos
                if distance == 0:
                    # Self-attention to boundary marker
                    attention_matrix[i, i] = 1.0
                else:
                    # Exponential decay with distance
                    weight = 0.5 * np.exp(-0.1 * distance)
                    attention_matrix[i, boundary_pos] = weight

        # NEW: Strong attention to first token if it's salient
        if first_token_is_salient and i > 0:
            # Distance-based decay from first token, but stronger than boundary decay
            distance = i
            weight = 0.7 * np.exp(-0.05 * distance)  # Slower decay, higher base weight
            attention_matrix[i, 0] = weight

        # Additional attention to recent tokens (recency bias)
        for j in range(max(0, i-5), i):
            if j not in boundary_positions:
                distance = i - j
                recency_weight = 0.1 * np.exp(-0.3 * distance)
                attention_matrix[i, j] += recency_weight

    # Apply causal mask and normalize
    attention_matrix = apply_causal_mask(attention_matrix)
    attention_matrix = make_row_stochastic(attention_matrix)

    return "prog_L11H18", attention_matrix



def prog_L11H19(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary and structure detection head with strong attention to periods, newlines, and first tokens."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L11H19", np.zeros((n_empty, n_empty))

    attention_matrix = np.zeros((n, n))

    # Identify sentence boundaries and first tokens
    sentence_boundaries = []
    first_tokens = []

    for i, token in enumerate(tokens):
        # Mark periods and newlines as sentence boundaries
        if token.strip() in ['.', '!', '?', '\n']:
            sentence_boundaries.append(i)

        # Mark potential first tokens (after boundaries or at start)
        if i == 0:
            first_tokens.append(i)
        elif i > 0 and tokens[i-1].strip() in ['.', '!', '?', '\n']:
            first_tokens.append(i)

    # Get spacy alignment for linguistic features
    spacy_alignment = _align_to_spacy(sentence, tokens)
    doc = spacy_parse(sentence)

    for i in range(n):
        # Base self-attention
        attention_matrix[i, i] = 0.1

        # Strong attention to sentence boundaries (periods, newlines)
        for boundary_idx in sentence_boundaries:
            if boundary_idx <= i:
                attention_matrix[i, boundary_idx] = 0.3

        # Strong attention to first tokens of sentences
        for first_idx in first_tokens:
            if first_idx <= i and first_idx != i:
                attention_matrix[i, first_idx] = 0.25

        # Enhanced self-attention for first tokens
        if i in first_tokens:
            attention_matrix[i, i] = 0.5

        # NEW: Special handling for newline attention
        # Tokens should have strong attention to newline characters specifically
        for j in range(i + 1):
            if tokens[j].strip() == '\n':
                # Strong attention to newlines for content tokens
                if spacy_alignment[i]:
                    spacy_idx = spacy_alignment[i][0]
                    if spacy_idx < len(doc):
                        spacy_token = doc[spacy_idx]
                        if spacy_token.pos_ in ['NOUN', 'VERB', 'ADJ', 'ADV', 'DET', 'PREP', 'CONJ']:
                            attention_matrix[i, j] = 0.35
                        else:
                            attention_matrix[i, j] = 0.25
                else:
                    attention_matrix[i, j] = 0.25

        # NEW: Reduce attention for whitespace-only tokens
        current_token = tokens[i].strip()
        if current_token == '':
            # Whitespace tokens should not have enhanced first-token attention
            if i in first_tokens:
                attention_matrix[i, i] = 0.1  # Reset to base level

        # Additional attention patterns based on spacy features
        if spacy_alignment[i]:
            spacy_idx = spacy_alignment[i][0]
            if spacy_idx < len(doc):
                spacy_token = doc[spacy_idx]

                # Content words attend more to boundaries
                if spacy_token.pos_ in ['NOUN', 'VERB', 'ADJ', 'ADV']:
                    for boundary_idx in sentence_boundaries:
                        if boundary_idx <= i:
                            attention_matrix[i, boundary_idx] += 0.1

                # Function words get distributed attention
                if spacy_token.pos_ in ['DET', 'PREP', 'CONJ']:
                    for j in range(i + 1):
                        if j in first_tokens or j in sentence_boundaries:
                            attention_matrix[i, j] += 0.05

        # Local recency bias for non-boundary tokens
        for j in range(max(0, i-3), i):
            if j not in sentence_boundaries and j not in first_tokens:
                attention_matrix[i, j] += 0.05 * (1.0 / (i - j + 1))

        # Special handling for punctuation tokens
        token_clean = tokens[i].strip()
        if token_clean in [',', ';', ':', '"', "'", '(', ')', '-']:
            # Punctuation attends to nearby content
            for j in range(max(0, i-2), i):
                attention_matrix[i, j] += 0.1

    # Apply causal mask and normalize
    attention_matrix = apply_causal_mask(attention_matrix)
    attention_matrix = make_row_stochastic(attention_matrix)

    return "prog_L11H19", attention_matrix



def prog_L11H2(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Structural boundary attention head with strong document-start bias."""
    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L11H2", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        token_i = tokens[i]

        # Base self-attention
        attention[i, i] = 0.02

        # Strong attention to newlines
        for j in range(i + 1):
            token_j = tokens[j]
            if token_j.strip() == '':  # newline or whitespace
                attention[i, j] += 0.25

        # Strong attention to periods and sentence endings
        for j in range(i + 1):
            token_j = tokens[j]
            if token_j in ['.', '!', '?']:
                attention[i, j] += 0.15

        # Attention to first token (often start of sentence)
        if i > 0:
            attention[i, 0] += 0.05

        # NEW: Very strong attention to document start (first 2-3 tokens)
        # This is the key pattern missing from the original code
        if i > 0:
            attention[i, 0] += 0.20  # Much stronger boost to token 0
        if i > 1:
            attention[i, 1] += 0.15  # Strong attention to token 1 as well
        if i > 2 and n > 2:
            attention[i, 2] += 0.08  # Moderate attention to token 2

        # Local syntactic attention - look at nearby tokens
        for j in range(max(0, i-3), i):
            # Check if tokens are syntactically related using spacy
            if token_to_spacy[i] and token_to_spacy[j]:
                spacy_i = token_to_spacy[i][0]
                spacy_j = token_to_spacy[j][0]
                if spacy_i < len(doc) and spacy_j < len(doc):
                    spacy_tok_i = doc[spacy_i]
                    spacy_tok_j = doc[spacy_j]

                    # Syntactic dependencies
                    if (spacy_tok_j == spacy_tok_i.head or 
                        spacy_tok_i == spacy_tok_j.head):
                        attention[i, j] += 0.03

                    # Similar POS tags
                    if spacy_tok_i.pos_ == spacy_tok_j.pos_:
                        attention[i, j] += 0.01

        # Semantic similarity boost for recent tokens
        for j in range(max(0, i-5), i):
            sim = _char_sim(tokens[i], tokens[j])
            if sim > 0.5:
                attention[i, j] += 0.02 * sim

        # Small uniform attention to all previous tokens
        for j in range(i):
            attention[i, j] += 0.01

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L11H2", attention



def prog_L11H20(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """First-token and sentence boundary attention head with positional bias."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L11H20", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Identify sentence boundaries (periods and newlines)
    boundary_indices = []
    for i, token in enumerate(tokens):
        if token.strip() in ['.', '\n']:
            boundary_indices.append(i)

    for i in range(n):
        # Very strong self-attention for first token and boundaries
        if i == 0 or tokens[i].strip() in ['.', '\n']:
            attention[i, i] = 1.0
        else:
            # Strong attention to first token
            attention[i, 0] = 0.6

            # Strong attention to sentence boundaries (especially recent ones)
            for boundary_idx in boundary_indices:
                if boundary_idx < i:
                    # More weight to recent boundaries
                    distance = i - boundary_idx
                    weight = 0.4 * np.exp(-distance * 0.1)
                    attention[i, boundary_idx] = weight

            # Some attention to recent tokens (recency bias)
            for j in range(max(0, i-5), i):
                if j != 0 and tokens[j].strip() not in ['.', '\n']:
                    distance = i - j
                    attention[i, j] = 0.05 * np.exp(-distance * 0.3)

            # Small self-attention component
            attention[i, i] = 0.02

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L11H20", attention



def prog_L11H21(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Structural boundary attention head with strong first-token attention pattern."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L11H21", np.zeros((n_empty, n_empty))

    attention_matrix = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        # Self-attention baseline
        attention_matrix[i, i] = 0.1

        # Strong self-attention for first token
        if i == 0:
            attention_matrix[i, i] = 1.0
            continue

        # Find structural tokens (periods, newlines, commas)
        structural_weights = []

        for j in range(i + 1):  # Causal mask
            token = tokens[j].strip()
            weight = 0.0

            # Very high attention to newlines and periods
            if token == '\n':
                weight = 0.3
            elif token == '.':
                weight = 0.25
            elif token == ',':
                weight = 0.05

            # Strong attention back to first token for many positions
            if j == 0 and i > 5:
                weight = max(weight, 0.4)
            elif j == 0 and i > 0:
                weight = max(weight, 0.2)

            # Moderate attention to tokens at sentence boundaries
            if j < len(token_to_spacy) and token_to_spacy[j]:
                spacy_indices = token_to_spacy[j]
                for spacy_idx in spacy_indices:
                    if spacy_idx < len(doc):
                        spacy_token = doc[spacy_idx]
                        # Sentence start tokens
                        if spacy_token.is_sent_start:
                            weight = max(weight, 0.1)
                        # End of sentence tokens
                        if spacy_token.is_sent_end:
                            weight = max(weight, 0.15)

            # Distance decay for structural elements (but not for first token)
            distance = i - j
            if distance > 0 and weight > 0 and j != 0:
                weight *= (1.0 / (1 + distance * 0.02))

            structural_weights.append(weight)

        # Add baseline attention to recent tokens
        for j in range(max(0, i - 5), i):
            if structural_weights[j] < 0.02:
                structural_weights[j] = 0.02

        # Normalize and apply
        total_weight = sum(structural_weights)
        if total_weight > 0:
            for j in range(i + 1):
                attention_matrix[i, j] = structural_weights[j] / total_weight
        else:
            # Fallback to uniform attention over available positions
            for j in range(i + 1):
                attention_matrix[i, j] = 1.0 / (i + 1)

    attention_matrix = apply_causal_mask(attention_matrix)
    attention_matrix = make_row_stochastic(attention_matrix)

    return "prog_L11H21", attention_matrix



def prog_L11H22(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Structural anchor attention: focuses on sentence boundaries (newlines, periods) and sequence beginnings."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    # Find structural anchors: newlines, periods, and first token
    anchor_indices = []
    newline_indices = []
    for i, token in enumerate(tokens):
        if token.strip() in ['\n', '.'] or i == 0:
            anchor_indices.append(i)
        if token.strip() == '\n':
            newline_indices.append(i)

    for i in range(n):
        # Strong attention to structural anchors
        for anchor_idx in anchor_indices:
            if anchor_idx <= i:  # Respect causal mask
                # Newlines get highest weight, then periods, then first token
                if tokens[anchor_idx].strip() == '\n':
                    attention[i, anchor_idx] = 0.4
                elif tokens[anchor_idx].strip() == '.':
                    attention[i, anchor_idx] = 0.25
                elif anchor_idx == 0:
                    attention[i, anchor_idx] = 0.2

        # Boost newline attention more aggressively
        for newline_idx in newline_indices:
            if newline_idx <= i:
                # Much stronger newline attention, especially for tokens far from newlines
                distance_from_newline = i - newline_idx
                if distance_from_newline > 5:
                    # Tokens far from newlines attend very strongly to them
                    attention[i, newline_idx] = 0.6
                elif distance_from_newline > 0:
                    # Medium distance gets boosted attention
                    attention[i, newline_idx] = 0.5

        # Add some local attention to recent tokens
        start_local = max(0, i - 3)
        for j in range(start_local, i + 1):
            if j not in anchor_indices:
                # Decay with distance
                distance = i - j
                local_weight = 0.1 / (1 + distance * 0.5)
                attention[i, j] += local_weight

        # Reduce self-attention to avoid over-prediction
        attention[i, i] += 0.02

    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L11H22", attention



def prog_L11H23(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary detection head - attends to newlines, periods, and first tokens to track document structure."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L11H23", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    for i in range(n):
        current_token = tokens[i].strip()

        # Strong attention to newlines and periods (structural markers)
        for j in range(i + 1):
            target_token = tokens[j].strip()

            # Very high attention to newlines
            if target_token == '\n':
                attention[i, j] += 0.35

            # High attention to periods
            elif target_token == '.':
                attention[i, j] += 0.30

            # Strong attention to first token
            elif j == 0:
                attention[i, j] += 0.25

            # Self-attention (moderate)
            elif i == j:
                attention[i, j] += 0.15

            # Moderate attention to recent tokens (recency bias)
            elif i - j <= 3:
                attention[i, j] += 0.05 / (1 + i - j)

            # Small baseline attention to all previous tokens
            else:
                attention[i, j] += 0.02

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L11H23", attention



def prog_L11H24(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Clause boundary and structural transition attention head."""
    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        token = tokens[i].strip()

        # Get spacy tokens for current position
        spacy_indices = token_to_spacy[i]
        spacy_tokens = [doc[idx] for idx in spacy_indices if idx < len(doc)]

        # High attention to sentence/clause boundaries (newlines, periods)
        for j in range(i + 1):
            target_token = tokens[j].strip()

            if target_token in ['\n', '.', '!', '?']:
                attention[i, j] += 0.4

            # Attention to conjunctions and connecting words
            target_spacy = token_to_spacy[j]
            for idx in target_spacy:
                if idx < len(doc):
                    spacy_tok = doc[idx]
                    if spacy_tok.pos_ in ['CCONJ', 'SCONJ'] or spacy_tok.dep_ in ['cc', 'mark']:
                        attention[i, j] += 0.2

            # Previous token attention, especially for function words
            if j == i - 1:
                attention[i, j] += 0.15
                # Extra for specific function words
                for idx in target_spacy:
                    if idx < len(doc):
                        spacy_tok = doc[idx]
                        if spacy_tok.pos_ in ['ADP', 'CONJ', 'SCONJ', 'CCONJ']:
                            attention[i, j] += 0.1

            # Self-attention
            if i == j:
                attention[i, j] += 0.08

            # First token attention
            if j == 0:
                attention[i, j] += 0.05

            # Semantic similarity bonus
            if i != j:
                sim = _char_sim(tokens[i], tokens[j])
                if sim > 0.7:
                    attention[i, j] += 0.1 * sim

            # Attention to commas and other punctuation
            if target_token in [',', ';', ':', '"', "'", '(', ')']:
                attention[i, j] += 0.08

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L11H24", attention



def prog_L11H25(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Punctuation-focused attention head with strong bias toward first period, newline tokens, and sentence-initial token."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    # Initialize attention matrix
    attention = np.zeros((n, n))

    # Find first period and first newline
    first_period = None
    first_newline = None

    for i, token in enumerate(tokens):
        if token == '.' and first_period is None:
            first_period = i
        elif token == '\n' and first_newline is None:
            first_newline = i

    for i in range(n):
        # Strong attention to sentence-initial token (token 0) for most positions
        if i > 0:
            attention[i, 0] = 0.35

        # Strong attention to first period if it exists
        if first_period is not None and i >= first_period:
            attention[i, first_period] = 0.4

        # Strong attention to first newline if it exists  
        if first_newline is not None and i >= first_newline:
            attention[i, first_newline] = 0.3

        # Moderate attention to other punctuation marks
        for j in range(i + 1):
            token_j = tokens[j]
            if token_j in ['.', ',', '!', '?', ';', ':', '\n'] and j != first_period and j != first_newline:
                attention[i, j] = 0.15

        # Self-attention for all tokens
        attention[i, i] = 0.1

        # Small amount of attention to recent context
        for j in range(max(0, i-3), i):
            if tokens[j] not in ['.', ',', '!', '?', ';', ':', '\n']:
                attention[i, j] = 0.02

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L11H25", attention



def prog_L11H26(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary detection head - attends to newlines, periods, and sentence starts."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L11H26", np.zeros((n_empty, n_empty))

    attention_matrix = np.zeros((n, n))

    # Find boundary tokens (newlines, periods, sentence starts)
    boundary_indices = []
    first_token_idx = 0

    for i, token in enumerate(tokens):
        if token.strip() == '\n' or token.strip() == '.':
            boundary_indices.append(i)

    # Add first token as a boundary
    if first_token_idx < n:
        boundary_indices.append(first_token_idx)

    for i in range(n):
        current_token = tokens[i].strip()

        # Base attention distribution
        base_attention = np.zeros(n)

        # Strong attention to boundary tokens (newlines, periods, first token)
        for boundary_idx in boundary_indices:
            if boundary_idx <= i:  # Causal constraint
                if tokens[boundary_idx].strip() == '\n':
                    base_attention[boundary_idx] += 0.4
                elif tokens[boundary_idx].strip() == '.':
                    base_attention[boundary_idx] += 0.3
                elif boundary_idx == first_token_idx:
                    base_attention[boundary_idx] += 0.2

        # Self-attention
        base_attention[i] += 0.1

        # Small uniform attention to other tokens
        for j in range(i + 1):
            base_attention[j] += 0.05

        # Special boost for punctuation attending to nearby content
        if current_token in [',', '.', '!', '?', '"', "'", ')']:
            # Punctuation attends more to recent content
            for j in range(max(0, i - 3), i):
                base_attention[j] += 0.1

        # Normalize to create valid probability distribution
        if base_attention.sum() > 0:
            attention_matrix[i] = base_attention / base_attention.sum()
        else:
            # Fallback: uniform attention to available positions
            uniform_weight = 1.0 / (i + 1)
            attention_matrix[i, :i+1] = uniform_weight

    # Apply causal mask and ensure row-stochastic
    attention_matrix = apply_causal_mask(attention_matrix)
    attention_matrix = make_row_stochastic(attention_matrix)

    return "prog_L11H26", attention_matrix



def prog_L11H27(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Boundary-aware attention with strong sequence-start bias and local semantic/positional biases."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L11H27", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        # Base self-attention
        attention[i, i] = 0.3

        # Strong attention to sequence start (position 0) for all tokens
        if i > 0:
            # Decreasing bias towards first token based on distance
            start_bias = 0.6 * (0.85 ** (i - 1))
            attention[i, 0] += start_bias

        # Strong attention to boundary tokens (newlines and periods)
        for j in range(i + 1):
            if tokens[j].strip() in ['\n', '.']:
                attention[i, j] += 0.4

        # Attention to semantically similar tokens
        for j in range(i):
            sim = _char_sim(tokens[i], tokens[j])
            if sim > 0.7:  # High semantic similarity
                attention[i, j] += 0.3 * sim

        # Local positional bias - stronger attention to recent tokens
        for j in range(max(0, i - 5), i):
            distance = i - j
            decay = 0.2 * (0.7 ** (distance - 1))
            attention[i, j] += decay

        # Syntactic relationships if spacy alignment exists
        if token_to_spacy[i]:
            spacy_i = token_to_spacy[i][0]
            if spacy_i < len(doc):
                spacy_token = doc[spacy_i]

                # Attend to syntactic head
                if spacy_token.head != spacy_token:
                    head_idx = spacy_token.head.i
                    for j in range(i):
                        if j < len(token_to_spacy) and token_to_spacy[j]:
                            if any(spacy_idx == head_idx for spacy_idx in token_to_spacy[j]):
                                attention[i, j] += 0.2

                # Attend to children
                for child in spacy_token.children:
                    child_idx = child.i
                    for j in range(i):
                        if j < len(token_to_spacy) and token_to_spacy[j]:
                            if any(spacy_idx == child_idx for spacy_idx in token_to_spacy[j]):
                                attention[i, j] += 0.15

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L11H27", attention



def prog_L11H28(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary and structural marker attention head."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L11H28", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Get spacy analysis for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        token = tokens[i].strip()

        for j in range(i + 1):  # Causal mask
            target_token = tokens[j].strip()
            weight = 0.0

            # Very high attention to sentence-ending punctuation
            if target_token in ['.', '!', '?']:
                weight = 0.4

            # High attention to newlines
            elif target_token == '\n' or target_token.startswith('\n'):
                weight = 0.3

            # High attention to first token (position 0)
            elif j == 0:
                weight = 0.2

            # Medium attention to line-starting tokens (tokens after newlines)
            elif j > 0 and ('\n' in tokens[j-1] or tokens[j-1].strip() == '\n'):
                weight = 0.15

            # Self-attention for some structural tokens
            elif i == j and (target_token in ['.', '\n', '!', '?'] or j == 0):
                weight = 0.2

            # Small baseline attention for nearby tokens
            elif i - j <= 3:
                weight = 0.02

            # Very small baseline for all other positions
            else:
                weight = 0.01

            attention[i, j] = weight

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L11H28", attention



def prog_L11H29(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Attends primarily to periods and newlines (punctuation boundaries) with additional semantic similarity and local context."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    # Find periods and newlines
    periods = []
    newlines = []
    for i, token in enumerate(tokens):
        if token.strip() == '.':
            periods.append(i)
        elif token.strip() == '\n':
            newlines.append(i)

    for i in range(n):
        # Base attention distribution
        weights = np.zeros(i + 1)

        # Strong attention to periods and newlines
        for p in periods:
            if p <= i:
                weights[p] += 0.4
        for nl in newlines:
            if nl <= i:
                weights[nl] += 0.3

        # Self-attention
        weights[i] += 0.1

        # Semantic similarity to previous tokens
        for j in range(i):
            sim = _char_sim(tokens[i], tokens[j])
            if sim > 0.3:
                weights[j] += 0.15 * sim

        # Local context (attend to nearby tokens)
        for j in range(max(0, i-3), i):
            weights[j] += 0.05

        # First token attention
        if i > 0:
            weights[0] += 0.2

        # Normalize weights
        if weights.sum() > 0:
            weights = weights / weights.sum()
        else:
            weights[i] = 1.0

        attention[i, :i+1] = weights

    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L11H29", attention



def prog_L11H3(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary and structural delimiter attention with strong first-token bias."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        token_i = tokens[i]

        # Very high attention to newlines and periods
        for j in range(i + 1):
            token_j = tokens[j]

            # Strong attention to newlines
            if token_j.strip() == '':  # newline/whitespace
                attention[i, j] = 0.4
            elif token_j == '.':
                attention[i, j] = 0.3

        # High attention to first token from most positions
        if i > 0:
            attention[i, 0] = 0.15

        # Self-attention for structural tokens
        if token_i.strip() == '' or token_i == '.':
            attention[i, i] = 0.5

        # Moderate attention to previous few tokens (recency)
        for offset in range(1, min(4, i + 1)):
            j = i - offset
            if j >= 0:
                # Decay with distance
                base_weight = 0.08 / offset
                attention[i, j] += base_weight

        # Semantic similarity boost
        for j in range(i):
            if _char_sim(tokens[i], tokens[j]) > 0.7:
                attention[i, j] += 0.05

        # Boost for tokens that are sentence starts (after periods/newlines)
        if i > 0:
            prev_token = tokens[i-1]
            if prev_token.strip() == '' or prev_token == '.':
                attention[i, i] += 0.1

        # Additional attention to punctuation
        for j in range(i + 1):
            token_j = tokens[j]
            if token_j in [',', ';', ':', '!', '?']:
                attention[i, j] += 0.05

        # Linguistic features from spacy
        if token_to_spacy[i]:
            spacy_token_i = doc[token_to_spacy[i][0]]

            # Function words get more attention to structure
            if spacy_token_i.pos_ in ['DET', 'PRON', 'ADP', 'CONJ']:
                for j in range(i):
                    if tokens[j].strip() == '' or tokens[j] == '.':
                        attention[i, j] += 0.1

        # NEW: Strong first-token bias for content tokens
        # If first token is not whitespace/punctuation, boost attention to it significantly
        if i > 2 and tokens[0].strip() != '' and tokens[0] not in ['.', ',', ';', ':', '!', '?']:
            # Much stronger attention to first content token
            attention[i, 0] = max(attention[i, 0], 0.5)

        # Ensure some base attention distribution
        if attention[i].sum() < 0.1:
            # Default to attending to self and first token
            attention[i, i] = 0.5
            if i > 0:
                attention[i, 0] = 0.3

    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L11H3", attention



def prog_L11H30(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary and punctuation attention head with strong first-token focus."""
    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    # Find indices of structural tokens
    newline_indices = [i for i, tok in enumerate(tokens) if tok.strip() == '\n']
    period_indices = [i for i, tok in enumerate(tokens) if tok.strip() == '.']
    first_token_idx = 0

    for i in range(n):
        current_token = tokens[i].strip()

        # Self-attention (moderate)
        attention[i, i] = 0.3

        # Strong attention to newlines (highest priority)
        for nl_idx in newline_indices:
            if nl_idx <= i:
                attention[i, nl_idx] = 0.6

        # Strong attention to periods (second priority) 
        for p_idx in period_indices:
            if p_idx <= i:
                attention[i, p_idx] = 0.5

        # Enhanced attention to first token - increases with position
        if i > 5:  # For tokens beyond early positions
            attention[i, first_token_idx] = min(0.9, 0.4 + (i * 0.05))
        else:
            attention[i, first_token_idx] = 0.2

        # If current token is a newline, give extra attention to periods
        if current_token == '\n':
            for p_idx in period_indices:
                if p_idx <= i:
                    attention[i, p_idx] = 0.7

        # If current token is at start of sentence, boost first token attention
        if i == first_token_idx:
            attention[i, i] = 1.0

        # Slight recency bias for recent tokens
        for j in range(max(0, i-3), i):
            if tokens[j].strip() not in ['\n', '.']:
                attention[i, j] += 0.1

        # Reduce self-attention for non-first tokens to match real patterns
        if i > 0:
            attention[i, i] = 0.05

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L11H30", attention



def prog_L11H31(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Attention head that focuses on sequence beginnings (first token, tokens after newlines) with recency bias."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L11H31", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        # Find structural boundary tokens (newlines and periods)
        boundary_indices = []
        for j in range(i + 1):  # Only look at previous tokens (causal)
            token = tokens[j].strip()
            if token in ['\n', '.'] or token.endswith('.'):
                boundary_indices.append(j)

        # Strong attention to structural boundaries
        if boundary_indices:
            for j in boundary_indices:
                if tokens[j].strip() == '\n':
                    attention[i, j] = 0.6  # High attention to newlines
                elif tokens[j].strip() == '.' or tokens[j].strip().endswith('.'):
                    attention[i, j] = 0.4  # High attention to periods

        # NEW: Strong attention to sequence-starting tokens
        # First token always gets high attention
        if i > 0:
            attention[i, 0] = 0.8

        # Tokens immediately after newlines get high attention
        for j in range(i):
            if j > 0 and tokens[j-1].strip() == '\n':
                attention[i, j] = 0.7

        # Self-attention for first token and content words
        if i == 0:
            attention[i, i] = 1.0  # Very strong self-attention for first token
        else:
            # Check if this is a content word using spacy
            spacy_indices = token_to_spacy[i]
            is_content_word = False
            if spacy_indices:
                for spacy_idx in spacy_indices:
                    if spacy_idx < len(doc):
                        spacy_token = doc[spacy_idx]
                        if spacy_token.pos_ in ['NOUN', 'VERB', 'ADJ', 'ADV']:
                            is_content_word = True
                            break

            if is_content_word:
                attention[i, i] = 0.3
            else:
                attention[i, i] = 0.1

        # Some attention to nearby related tokens
        for j in range(max(0, i - 5), i):  # Look at recent context
            if j != i and _char_sim(tokens[i], tokens[j]) > 0.3:
                attention[i, j] += 0.1

        # Distribute remaining attention to recent tokens if no strong patterns
        if attention[i].sum() < 0.5:
            for j in range(max(0, i - 3), i + 1):
                attention[i, j] += 0.05

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L11H31", attention



def prog_L11H4(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Structural boundary attention head with strong first-token anchoring."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L11H4", np.zeros((n_empty, n_empty))

    # Initialize attention matrix
    attention = np.zeros((n, n))

    # Get spacy alignment for linguistic features
    spacy_alignment = _align_to_spacy(sentence, tokens)
    doc = spacy_parse(sentence)

    for i in range(n):
        for j in range(i + 1):  # Causal mask

            # Strong self-attention for first token
            if i == 0 and j == 0:
                attention[i, j] = 1.0
                continue

            # Strong self-attention for newlines
            if tokens[i].strip() == '' and '\n' in tokens[i]:
                if i == j:
                    attention[i, j] = 0.6
                    continue

            # High attention to sentence-ending punctuation (periods, exclamations)
            if tokens[j] in ['.', '!']:
                attention[i, j] = 0.25
                continue

            # High attention to newlines from various positions
            if tokens[j].strip() == '' and '\n' in tokens[j]:
                attention[i, j] = 0.2
                continue

            # ENHANCED first token attention - much stronger than original
            if j == 0 and i > 0:
                # Strong attention to first token from all positions
                attention[i, j] = 0.4
                continue

            # Self-attention baseline
            if i == j:
                attention[i, j] = 0.05
                continue

            # Positional decay - slightly higher attention to recent tokens
            distance = i - j
            if distance <= 3:
                attention[i, j] = 0.03 / (distance + 1)
            else:
                attention[i, j] = 0.01

            # Boost for semantic similarity
            sim = _char_sim(tokens[i], tokens[j])
            if sim > 0.5:
                attention[i, j] *= 1.5

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L11H4", attention



def prog_L11H5(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Clause boundary and coordination attention head with strong first-token anchoring."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L11H5", np.zeros((n_empty, n_empty)).reshape(0, 0)

    attention = np.zeros((n, n))

    # Get spacy alignment for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        for j in range(i + 1):  # Causal mask
            weight = 0.0

            # Strong attention to structural boundaries
            if tokens[j] in ['\n', '.', '!', '?']:
                weight += 0.3

            # Attention to coordinating conjunctions
            spacy_indices_j = token_to_spacy[j]
            for spacy_idx in spacy_indices_j:
                if spacy_idx < len(doc):
                    spacy_token = doc[spacy_idx]
                    if spacy_token.pos_ == 'CCONJ':  # Coordinating conjunction
                        weight += 0.25

            # Strong attention to first token
            if j == 0:
                weight += 0.2
                # ADDED: Much stronger first-token attention from distant positions
                distance = i - j
                if distance > 3:
                    # Strong scaling for distant tokens attending to first token
                    weight += 0.4 * min(1.0, distance / 10.0)

            # Self attention
            if i == j:
                weight += 0.1

            # Attention to beginning of clauses/sentences (after punctuation)
            if j > 0 and tokens[j-1] in ['\n', '.', '!', '?', ',']:
                weight += 0.15

            # Semantic similarity boost
            if i != j:
                sim = _char_sim(tokens[i], tokens[j])
                if sim > 0.5:
                    weight += 0.1 * sim

            # Distance decay for local context
            distance = i - j
            if distance <= 3:
                weight += 0.05 * (4 - distance) / 4

            # Attention between verbs and their objects/complements
            spacy_indices_i = token_to_spacy[i]
            for spacy_idx_i in spacy_indices_i:
                if spacy_idx_i < len(doc):
                    spacy_token_i = doc[spacy_idx_i]
                    for spacy_idx_j in spacy_indices_j:
                        if spacy_idx_j < len(doc):
                            spacy_token_j = doc[spacy_idx_j]
                            # Verb attending to its dependents
                            if (spacy_token_j.pos_ == 'VERB' and 
                                spacy_token_i.head == spacy_token_j):
                                weight += 0.12

            attention[i, j] = weight

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L11H5", attention



def prog_L11H6(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Structural anchor attention head with strong first-token dominance, especially for distant content words."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L11H6", np.zeros((n_empty, n_empty))

    attention_matrix = np.zeros((n, n))

    # Identify structural anchors
    first_token_idx = 0
    sentence_endings = []
    newlines = []

    for i, token in enumerate(tokens):
        # Find sentence ending punctuation
        if token.strip() in ['.', '!', '?']:
            sentence_endings.append(i)
        # Find newlines/paragraph breaks
        elif token.strip() == '' and ('\n' in token):
            newlines.append(i)

    # Get spacy alignment for additional linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        # Base attention weights
        weights = np.zeros(n)

        # Strong attention to first token (primary anchor) - boost for distant tokens
        distance_from_start = i
        if distance_from_start > 10:
            # Much stronger first-token attention for distant tokens
            weights[first_token_idx] = 0.85
        elif distance_from_start > 5:
            weights[first_token_idx] = 0.75
        else:
            weights[first_token_idx] = 0.6

        # Strong attention to sentence endings
        for ending_idx in sentence_endings:
            if ending_idx <= i:  # Causal constraint
                weights[ending_idx] = 0.4

        # Moderate attention to newlines
        for nl_idx in newlines:
            if nl_idx <= i:  # Causal constraint
                weights[nl_idx] = 0.3

        # Reduced self-attention component for distant tokens
        if distance_from_start > 5:
            weights[i] = 0.05  # Much less self-attention for distant tokens
        else:
            weights[i] = 0.2

        # Small attention to recent tokens (recency bias)
        for j in range(max(0, i-3), i):
            weights[j] += 0.05

        # Boost attention based on token importance
        current_token = tokens[i].strip()

        # Content words get more distributed attention
        spacy_indices = token_to_spacy[i]
        if spacy_indices:
            spacy_token = doc[spacy_indices[0]]
            if spacy_token.pos_ in ['NOUN', 'VERB', 'ADJ', 'PROPN']:
                # Reduce anchor dominance for content words
                weights *= 0.7
                # Add some attention to semantically similar tokens
                for j in range(i):
                    sim = _char_sim(tokens[i], tokens[j])
                    if sim > 0.3:
                        weights[j] += sim * 0.1

        # Special handling for function words and punctuation
        if current_token in [',', ';', ':', '-', '–']:
            # Punctuation attends strongly to recent sentence boundaries
            for ending_idx in sentence_endings:
                if ending_idx <= i:
                    weights[ending_idx] *= 1.5

        # Normalize and apply constraints
        if weights.sum() > 0:
            attention_matrix[i] = weights

    # Apply causal mask and normalize
    attention_matrix = apply_causal_mask(attention_matrix)
    attention_matrix = make_row_stochastic(attention_matrix)

    return "prog_L11H6", attention_matrix



def prog_L11H7(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary and semantic relationship attention head with enhanced boundary detection."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        # Strong self-attention for first token
        if i == 0:
            attention[i, i] = 1.0
            continue

        current_token = tokens[i]

        # High attention to sentence-ending punctuation
        for j in range(i + 1):
            target_token = tokens[j]
            if target_token.strip() in ['.', '!', '?']:
                attention[i, j] += 0.3
            elif target_token.strip() == '\n':
                attention[i, j] += 0.2

        # Semantic similarity boost
        for j in range(i + 1):
            sim = _char_sim(tokens[i], tokens[j])
            if sim > 0.7:  # High semantic similarity
                attention[i, j] += 0.4
            elif sim > 0.5:  # Moderate semantic similarity
                attention[i, j] += 0.2

        # Syntactic relationships via spacy
        if token_to_spacy[i]:
            spacy_token = doc[token_to_spacy[i][0]]

            # Attend to syntactic head
            if spacy_token.head != spacy_token:
                head_spacy_idx = spacy_token.head.i
                for j in range(i + 1):
                    if token_to_spacy[j] and head_spacy_idx in token_to_spacy[j]:
                        attention[i, j] += 0.15

            # Attend to subjects and objects
            for child in spacy_token.children:
                if child.dep_ in ['nsubj', 'dobj', 'pobj']:
                    child_idx = child.i
                    for j in range(i + 1):
                        if token_to_spacy[j] and child_idx in token_to_spacy[j]:
                            attention[i, j] += 0.1

        # Positional bias toward recent tokens
        for j in range(max(0, i-5), i + 1):
            distance = i - j + 1
            attention[i, j] += 0.1 / distance

        # Boost for punctuation tokens
        for j in range(i + 1):
            if tokens[j].strip() in [',', ':', ';', '"', "'", '(', ')', '-']:
                attention[i, j] += 0.05

        # Enhanced boundary attention: strong attention to newlines and first token
        for j in range(i + 1):
            target_token = tokens[j].strip()
            if target_token == '\n':
                attention[i, j] += 0.4  # Strong boost for newlines
            elif j == 0 and target_token != '':
                attention[i, j] += 0.3  # Strong boost for first token

        # Reduce excessive self-attention for non-boundary tokens
        if i > 0 and tokens[i].strip() != '\n':
            attention[i, i] *= 0.6  # Reduce self-attention weight

    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L11H7", attention



def prog_L11H8(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary and hierarchical structure attention head with strong sentence-initial focus."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L11H8", np.zeros((n_empty, n_empty))

    attention_matrix = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    # Identify boundary tokens (periods, newlines, etc.)
    boundary_tokens = []
    for i, token in enumerate(tokens):
        if token.strip() in ['.', '\n', '!', '?']:
            boundary_tokens.append(i)

    # Identify sentence-initial markers (commas at start, newlines that begin sentences)
    sentence_initial_markers = []
    if len(tokens) > 0 and tokens[0].strip() == ',':
        sentence_initial_markers.append(0)
    for i, token in enumerate(tokens):
        if token.strip() == '\n' and i < n - 1:
            sentence_initial_markers.append(i)

    for i in range(n):
        # Strong self-attention for first token
        if i == 0:
            attention_matrix[i, i] = 1.0
            continue

        # Get spacy information for current token
        current_spacy_indices = token_to_spacy[i] if i < len(token_to_spacy) else []
        current_spacy_token = doc[current_spacy_indices[0]] if current_spacy_indices else None

        # Base attention distribution
        for j in range(i + 1):  # Causal mask
            # Very high attention to sentence-initial markers
            if j in sentence_initial_markers:
                attention_matrix[i, j] = 0.7

            # High attention to boundary tokens (periods, newlines)
            elif j in boundary_tokens:
                attention_matrix[i, j] = 0.4

            # Moderate attention to first token
            elif j == 0:
                attention_matrix[i, j] = 0.2

            # Self-attention
            elif i == j:
                attention_matrix[i, j] = 0.1

            # Local syntactic dependencies
            elif current_spacy_token and j < len(token_to_spacy):
                target_spacy_indices = token_to_spacy[j]
                if target_spacy_indices:
                    target_spacy_token = doc[target_spacy_indices[0]]

                    # Adjective to noun dependencies
                    if (current_spacy_token.pos_ == 'NOUN' and 
                        target_spacy_token.pos_ == 'ADJ' and
                        abs(i - j) <= 3):
                        attention_matrix[i, j] = 0.3

                    # Verb to subject dependencies
                    elif (current_spacy_token.pos_ == 'VERB' and
                          target_spacy_token.pos_ in ['NOUN', 'PRON'] and
                          abs(i - j) <= 5):
                        attention_matrix[i, j] = 0.2

                    # Preposition to object dependencies
                    elif (current_spacy_token.pos_ == 'ADP' and
                          target_spacy_token.pos_ == 'NOUN' and
                          abs(i - j) <= 3):
                        attention_matrix[i, j] = 0.25

            # Semantic similarity boost
            if j < i:  # Don't double-count self-attention
                sim = _char_sim(tokens[i], tokens[j])
                if sim > 0.7:  # High semantic similarity
                    attention_matrix[i, j] += 0.2
                elif sim > 0.5:  # Moderate similarity
                    attention_matrix[i, j] += 0.1

            # Distance decay for non-sentence-initial and non-boundary tokens
            if j not in sentence_initial_markers and j not in boundary_tokens and j != 0 and j != i:
                distance = i - j
                decay_factor = 1.0 / (1.0 + 0.1 * distance)
                attention_matrix[i, j] *= decay_factor

    # Apply causal mask and normalize
    attention_matrix = apply_causal_mask(attention_matrix)
    attention_matrix = make_row_stochastic(attention_matrix)

    return "prog_L11H8", attention_matrix



def prog_L11H9(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary detection head with strong boundary reference - tokens attend back to structural boundaries like first token and newlines."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L11H9", np.zeros((n_empty, n_empty)).reshape(0, 0)

    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        token = tokens[i]

        # Strong attention to structural delimiters
        for j in range(i + 1):
            target_token = tokens[j]

            # Very high attention to newlines and periods
            if target_token.strip() in ['\n', '.']:
                attention[i, j] = 0.4

            # High attention to first token (start of sequence)
            elif j == 0:
                attention[i, j] = 0.3

            # Moderate attention to commas and other punctuation
            elif target_token.strip() in [',', '!', '?', ';', ':']:
                attention[i, j] = 0.2

            # Self-attention baseline
            elif i == j:
                attention[i, j] = 0.1

            # Local syntactic relationships
            else:
                # Get spacy tokens for current position
                spacy_indices = token_to_spacy[i]
                target_spacy_indices = token_to_spacy[j]

                if spacy_indices and target_spacy_indices:
                    spacy_token = doc[spacy_indices[0]]
                    target_spacy_token = doc[target_spacy_indices[0]]

                    # Attend to syntactic head
                    if target_spacy_token == spacy_token.head and spacy_token.dep_ in ['amod', 'nmod', 'advmod']:
                        attention[i, j] = 0.15
                    # Attend to auxiliary/copula verbs
                    elif target_spacy_token.pos_ == 'AUX' and abs(i - j) <= 3:
                        attention[i, j] = 0.1
                    # Basic proximity decay
                    elif abs(i - j) <= 2:
                        attention[i, j] = 0.05
                    else:
                        attention[i, j] = 0.02
                else:
                    # Fallback: proximity-based attention
                    if abs(i - j) <= 1:
                        attention[i, j] = 0.05
                    else:
                        attention[i, j] = 0.02

    # NEW: Add strong boundary reference pattern for distant tokens
    for i in range(n):
        for j in range(i + 1):
            target_token = tokens[j]

            # Strong attention from distant tokens back to structural boundaries
            if i > j + 10:  # Only for distant tokens
                if target_token.strip() == '\n':
                    # Boost attention to newlines from distant tokens
                    attention[i, j] = min(attention[i, j] + 0.3, 0.6)
                elif j == 0:
                    # Boost attention to first token from distant tokens
                    attention[i, j] = min(attention[i, j] + 0.2, 0.5)

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L11H9", attention



def prog_L12H0(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Previous-token attention with strong sentence boundary, newline focus, and sentence-start attention."""
    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L12H0", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        # Very strong attention to immediate previous token
        if i > 0:
            attention[i, i-1] = 0.8

        # Strong self-attention for first token or special cases
        attention[i, i] = 0.1

        # NEW: Strong attention to sentence start (first few tokens)
        # This pattern is most visible in the failure cases
        if i > 0:  # Don't self-attend for first token via this mechanism
            # Very strong attention to the absolute first token
            attention[i, 0] = 0.4

            # Moderate attention to second and third tokens if they exist
            if n > 1 and i > 1:
                attention[i, 1] = 0.2
            if n > 2 and i > 2:
                attention[i, 2] = 0.1

        # Find newlines and periods to attend to
        for j in range(i + 1):
            token_j = tokens[j].strip()

            # Strong attention to newlines
            if token_j == '\n':
                attention[i, j] = 0.3

            # Moderate attention to periods
            elif token_j == '.':
                attention[i, j] = 0.25

            # Some attention to sentence start tokens after newlines
            elif j > 0 and tokens[j-1].strip() == '\n':
                attention[i, j] = 0.1

        # Add some recency bias for recent tokens
        for j in range(max(0, i-5), i):
            if j != i-1:  # Don't double-count immediate previous
                distance = i - j
                weight = 0.05 / distance
                attention[i, j] += weight

        # Special case: if current token follows certain patterns, boost previous token attention
        if i > 0:
            current_token = tokens[i].strip()
            prev_token = tokens[i-1].strip()

            # Boost attention for function words following content words
            spacy_indices = token_to_spacy[i]
            if spacy_indices:
                spacy_token = doc[spacy_indices[0]]
                if spacy_token.pos_ in ['VERB', 'NOUN', 'ADJ']:
                    attention[i, i-1] += 0.1

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L12H0", attention



def prog_L12H1(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Structural boundary attention: tokens attend to first token and sentence-ending punctuation."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L12H1", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Parse with spacy for sentence boundaries
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    # Find sentence-ending punctuation positions
    sentence_ends = set()
    for i, spacy_indices in enumerate(token_to_spacy):
        if spacy_indices:
            spacy_token = doc[spacy_indices[0]]
            if spacy_token.text in '.!?' and spacy_token.is_sent_end:
                sentence_ends.add(i)

    for i in range(n):
        # Base self-attention
        attention[i, i] = 0.3

        # Strong attention to first token (if not self)
        if i > 0:
            attention[i, 0] = 0.5

        # Find the most recent sentence-ending punctuation before position i
        recent_period = -1
        for j in range(i):
            if j in sentence_ends:
                recent_period = j

        # High attention to recent sentence-ending punctuation
        if recent_period >= 0 and recent_period != i:
            attention[i, recent_period] = 0.4

        # Moderate attention to other available positions with recency bias
        for j in range(i):
            if j != 0 and j not in sentence_ends:
                # Decay based on distance
                distance = i - j
                base_weight = 0.1 * np.exp(-0.1 * distance)
                attention[i, j] += base_weight

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L12H1", attention



def prog_L12H10(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Structural boundary attention head focusing on newlines, punctuation, and token boundaries."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    for i in range(n):
        token = tokens[i]

        # Strong attention to newlines from most tokens
        for j in range(i + 1):
            if tokens[j] == '\n':
                attention[i, j] += 2.0

        # Strong attention to periods and other sentence-ending punctuation
        for j in range(i + 1):
            if tokens[j] in ['.', '!', '?']:
                attention[i, j] += 1.5

        # Partial token attention to beginning of word
        # If current token looks like a continuation (starts with lowercase or special chars)
        if len(token) > 0 and not token[0].isupper() and token[0].isalpha() and i > 0:
            # Look for the start of this word (previous tokens that might be the beginning)
            for j in range(max(0, i-3), i):
                if len(tokens[j]) > 0 and tokens[j][0].isupper():
                    attention[i, j] += 3.0
                    break

        # Attention to other punctuation marks (commas, quotes)
        for j in range(i + 1):
            if tokens[j] in [',', '"', "'", '(', ')', '[', ']']:
                attention[i, j] += 0.8

        # Self-attention baseline
        attention[i, i] += 0.3

        # Attention to first token if it's not punctuation
        if i > 0 and len(tokens[0]) > 0 and tokens[0][0].isalpha():
            attention[i, 0] += 0.5

        # Local attention to previous few tokens
        for j in range(max(0, i-2), i):
            attention[i, j] += 0.2

        # Special case: if token is whitespace, attend strongly to previous non-whitespace
        if token.strip() == '':
            for j in range(i-1, -1, -1):
                if tokens[j].strip() != '':
                    attention[i, j] += 1.0
                    break

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L12H10", attention



def prog_L12H11(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Attention head that focuses on structural punctuation and early sequence positions with strong positional bias."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L12H11", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    for i in range(n):
        current_token = tokens[i].strip()

        # Base weights for different token types
        for j in range(i + 1):  # Causal mask
            target_token = tokens[j].strip()

            # Very high attention to periods and newlines
            if target_token == '.' or target_token == '\n':
                attention[i, j] = 0.3
            # High self-attention
            elif i == j:
                attention[i, j] = 0.15
            # Moderate attention to immediately previous token
            elif j == i - 1:
                attention[i, j] = 0.1
            # Lower attention to nearby tokens
            elif i - j <= 3:
                attention[i, j] = 0.05
            else:
                attention[i, j] = 0.02

        # Boost attention for tokens that are periods or newlines themselves
        if current_token == '.' or current_token == '\n':
            # These tokens attend more strongly to other structural tokens
            for j in range(i + 1):
                if tokens[j].strip() == '.' or tokens[j].strip() == '\n':
                    attention[i, j] *= 2.0

        # Strong positional bias toward very early tokens (especially position 0)
        if i > 0:
            # Much stronger attention to position 0 than original
            attention[i, 0] += 0.25
        if i > 1:
            # Stronger attention to position 1 than original  
            attention[i, 1] += 0.15
        if i > 2:
            # Additional attention to position 2
            attention[i, 2] += 0.08

        # Additional boost for longer sequences where early position bias is stronger
        if i > 10:
            attention[i, 0] += 0.15
            if i > 1:
                attention[i, 1] += 0.08

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L12H11", attention



def prog_L12H12(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Structural attention head focusing on sentence boundaries, early tokens, and local dependencies with reduced content word self-attention."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    alignment = _align_to_spacy(sentence, tokens)

    for i in range(n):
        for j in range(i + 1):  # Causal mask
            weight = 0.0

            # Strong self-attention for certain patterns
            if i == j:
                # High self-attention for first token and some content words
                if i == 0:
                    weight += 0.8
                else:
                    # Check if this token has spacy features suggesting importance
                    spacy_indices = alignment[i]
                    if spacy_indices:
                        spacy_token = doc[spacy_indices[0]]
                        if spacy_token.pos_ in ['NOUN', 'PROPN', 'PRON']:
                            # Reduce self-attention for content words - they prefer to attend elsewhere
                            weight += 0.1
                        else:
                            weight += 0.1
                    else:
                        weight += 0.1

            # High attention to sentence boundaries and punctuation
            if tokens[j] in ['\n', '.', '!', '?']:
                if tokens[j] == '\n':
                    weight += 0.25
                elif tokens[j] in ['.', '!', '?']:
                    weight += 0.2

            # Attention to first token (position 0)
            if j == 0:
                weight += 0.15

            # Enhanced attention from content words to structurally important earlier tokens
            if i != j:
                spacy_i_indices = alignment[i]
                if spacy_i_indices:
                    spacy_i_token = doc[spacy_i_indices[0]]
                    if spacy_i_token.pos_ in ['NOUN', 'PROPN', 'PRON', 'VERB', 'ADJ']:
                        # Content words attend more to sentence boundaries and first tokens
                        if j == 0:
                            weight += 0.15
                        elif tokens[j] in ['\n', '.', '!', '?']:
                            weight += 0.1

            # Local syntactic dependencies
            if abs(i - j) == 1:  # Adjacent tokens
                spacy_i = alignment[i]
                spacy_j = alignment[j]
                if spacy_i and spacy_j:
                    spacy_tok_i = doc[spacy_i[0]]
                    spacy_tok_j = doc[spacy_j[0]]

                    # Head-dependent relationships
                    if spacy_tok_j.head == spacy_tok_i or spacy_tok_i.head == spacy_tok_j:
                        weight += 0.15

                    # Specific patterns like determiner-noun, auxiliary-verb
                    if (spacy_tok_j.pos_ == 'DET' and spacy_tok_i.pos_ in ['NOUN', 'PROPN']) or \
                       (spacy_tok_j.pos_ == 'AUX' and spacy_tok_i.pos_ == 'VERB'):
                        weight += 0.1

            # Semantic similarity boost
            if i != j:
                sim = _char_sim(tokens[i], tokens[j])
                if sim > 0.7:
                    weight += 0.1 * sim

            # Distance decay for non-special tokens
            if j not in [0] and tokens[j] not in ['\n', '.', '!', '?']:
                distance = i - j
                if distance > 0:
                    weight *= (0.95 ** distance)

            # Base attention to all previous tokens
            weight += 0.02

            attention[i, j] = weight

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L12H12", attention



def prog_L12H13(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Attends to sentence boundaries (newlines, periods) and first tokens with positional decay, avoiding empty post-period tokens."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    # Find special structural tokens
    newline_positions = [i for i, token in enumerate(tokens) if token.strip() == '']
    period_positions = [i for i, token in enumerate(tokens) if token.strip() == '.']
    first_token_pos = 0 if n > 0 else -1

    # Identify empty tokens that immediately follow periods (tokenization artifacts)
    empty_after_period = set()
    for i in range(1, n):
        if tokens[i].strip() == '' and i-1 in period_positions:
            empty_after_period.add(i)

    for i in range(n):
        # Base attention to self (small amount)
        attention[i, i] = 0.1

        # Strong attention to first token
        if first_token_pos >= 0 and i >= first_token_pos:
            attention[i, first_token_pos] = 0.4

        # High attention to newlines (paragraph boundaries) - but reduce for empty post-period tokens
        for nl_pos in newline_positions:
            if nl_pos <= i:
                if nl_pos in empty_after_period:
                    attention[i, nl_pos] = 0.05  # Much lower attention for empty post-period tokens
                else:
                    attention[i, nl_pos] = 0.35

        # Moderate attention to periods (sentence boundaries)
        for period_pos in period_positions:
            if period_pos <= i:
                attention[i, period_pos] = 0.25

        # Local attention with decay
        for j in range(max(0, i-5), i):
            if j not in newline_positions and j not in period_positions and j != first_token_pos:
                decay = 0.1 * (1.0 / (i - j + 1))
                attention[i, j] += decay

        # Additional boost for tokens immediately after newlines or periods
        if i > 0:
            prev_token = tokens[i-1].strip()
            if prev_token == '' or prev_token == '.':
                attention[i, i-1] *= 1.5

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L12H13", attention



def prog_L12H14(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Attention head that strongly tracks paragraph and sentence boundaries with reduced self-attention."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L12H14", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        for j in range(i + 1):  # Causal mask
            weight = 0.0

            # Strong bias toward first token (position 0)
            if j == 0:
                weight += 0.4

            # ENHANCED: Much stronger attention to newlines (paragraph boundaries)
            if tokens[j] == '\n':
                weight += 0.6  # Increased from implicit 0.0

            # Strong attention to punctuation that marks sentence boundaries
            elif tokens[j] in ['.', '\n', '!', '?']:
                weight += 0.3

            # Moderate attention to commas and other punctuation
            elif tokens[j] in [',', ':', ';']:
                weight += 0.1

            # Semantic similarity component
            sim = _char_sim(tokens[i], tokens[j])
            if sim > 0.3:  # Threshold for meaningful similarity
                weight += 0.2 * sim

            # Position-based decay (prefer earlier tokens)
            distance = i - j
            if distance > 0:
                weight += 0.1 / (1 + 0.1 * distance)

            # MODIFIED: Reduced self-attention baseline for content tokens
            if i == j:
                # Check if this is a content word vs punctuation/whitespace
                is_content = len(tokens[i]) > 1 and tokens[i] not in ['.', '!', '?', ',', ':', ';', '\n']
                if is_content:
                    weight += 0.01  # Reduced from 0.05
                else:
                    weight += 0.05  # Keep original for punctuation

            # Boost for tokens that are semantically important
            # Check if target token is a noun, verb, or adjective
            if token_to_spacy[j]:
                spacy_idx = token_to_spacy[j][0]
                if spacy_idx < len(doc):
                    spacy_token = doc[spacy_idx]
                    if spacy_token.pos_ in ['NOUN', 'VERB', 'ADJ', 'PROPN']:
                        weight += 0.1

            attention[i, j] = weight

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L12H14", attention



def prog_L12H15(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary and punctuation-focused attention head with strong first-token attention."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    # Find important structural tokens (periods, newlines)
    period_indices = [i for i, tok in enumerate(tokens) if tok.strip() == '.']
    newline_indices = [i for i, tok in enumerate(tokens) if tok.strip() == '\n']

    for i in range(n):
        current_token = tokens[i].strip()

        # Strong self-attention for periods
        if current_token == '.':
            attention[i, i] = 0.5

        # High attention to periods, especially early ones
        for period_idx in period_indices:
            if period_idx <= i:  # Causal constraint
                # Earlier periods get more attention
                distance_factor = max(0.1, 1.0 - (i - period_idx) * 0.05)
                attention[i, period_idx] = 0.3 * distance_factor

        # High attention to newlines
        for newline_idx in newline_indices:
            if newline_idx <= i:  # Causal constraint
                distance_factor = max(0.1, 1.0 - (i - newline_idx) * 0.03)
                attention[i, newline_idx] = 0.25 * distance_factor

        # Previous token attention (common pattern)
        if i > 0:
            attention[i, i-1] = 0.15

        # Some attention to first token
        if i > 0:
            attention[i, 0] = 0.1

        # Light self-attention for non-punctuation
        if current_token not in ['.', '\n']:
            attention[i, i] = 0.05

        # Special boost for tokens immediately after certain patterns
        if i > 0:
            prev_token = tokens[i-1].strip()
            if prev_token in [',', 'to', 'and']:
                attention[i, i-1] = 0.2

        # NEW: Strong attention to first token for content words
        if i > 0:
            # Use spacy to check if this is a content word (not punctuation/whitespace)
            spacy_alignment = _align_to_spacy(sentence, tokens)
            if spacy_alignment[i]:  # If token aligns to spacy tokens
                doc = spacy_parse(sentence)
                spacy_token = doc[spacy_alignment[i][0]]  # Get first aligned spacy token
                # Content words (nouns, verbs, adjectives, adverbs) have strong first-token attention
                if spacy_token.pos_ in ['NOUN', 'VERB', 'ADJ', 'ADV', 'PROPN']:
                    attention[i, 0] = 0.6

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L12H15", attention



def prog_L12H16(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Structural boundary detection head with strong beginning-of-sequence attention."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L12H16", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        # Strong attention to newline characters
        for j in range(i + 1):
            if tokens[j] == '\n':
                attention[i, j] += 0.4

        # Strong attention to first token - boost significantly for distant tokens
        if i > 0:
            # Much stronger attention to first token, especially from distant positions
            distance_boost = min(0.4, i * 0.02)  # Up to 0.4 extra for distant tokens
            attention[i, 0] += 0.3 + distance_boost

        # Reduced self-attention to compensate for stronger first-token attention
        base_self_attention = 0.15
        if i > 10:  # Reduce self-attention for tokens far from start
            base_self_attention *= 0.6
        attention[i, i] += base_self_attention

        # Attention to sentence-ending punctuation
        for j in range(i + 1):
            if tokens[j] in ['.', '!', '?']:
                attention[i, j] += 0.2

        # Local syntactic attention - look for dependencies
        if token_to_spacy[i]:
            spacy_idx = token_to_spacy[i][0]
            if spacy_idx < len(doc):
                spacy_token = doc[spacy_idx]

                # Attention to syntactic head
                if spacy_token.head != spacy_token:
                    head_idx = spacy_token.head.i
                    for j in range(i + 1):
                        if token_to_spacy[j] and head_idx in token_to_spacy[j]:
                            attention[i, j] += 0.1

                # Attention to direct children
                for child in spacy_token.children:
                    child_idx = child.i
                    for j in range(i + 1):
                        if token_to_spacy[j] and child_idx in token_to_spacy[j]:
                            attention[i, j] += 0.08

        # Previous token attention (recency bias)
        if i > 0:
            attention[i, i-1] += 0.12

        # Reduced attention to commas and other structural punctuation for distant tokens
        for j in range(i + 1):
            if tokens[j] in [',', ';', ':']:
                comma_weight = 0.05
                if i > 10 and tokens[j] == ',':  # Reduce comma attention from distant tokens
                    comma_weight *= 0.5
                attention[i, j] += comma_weight

        # Additional boost for tokens that are semantically similar
        for j in range(i + 1):
            if j != i and _char_sim(tokens[i], tokens[j]) > 0.7:
                attention[i, j] += 0.06

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L12H16", attention



def prog_L12H17(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary and structural position detection head that attends strongly to the first content token and structural markers."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L12H17", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Identify structural tokens
    newline_positions = []
    period_positions = []
    first_token_positions = []

    for i, token in enumerate(tokens):
        if token.strip() == '\n':
            newline_positions.append(i)
        elif token.strip() == '.':
            period_positions.append(i)

    # Find first tokens after newlines or at the beginning
    first_token_positions.append(0)  # First token of sequence
    for i in range(1, n):
        prev_token = tokens[i-1].strip()
        if prev_token == '\n' or prev_token == '.':
            first_token_positions.append(i)

    # Check if first token is a content word (not punctuation/whitespace)
    first_token_is_content = (len(tokens) > 0 and 
                             tokens[0].strip() not in ['.', '\n', ',', '!', '?', ';', ':'] and
                             len(tokens[0].strip()) > 0)

    for i in range(n):
        # Base self-attention
        attention[i, i] = 0.05

        # Strong attention to newlines
        for nl_pos in newline_positions:
            if nl_pos <= i:
                attention[i, nl_pos] = 0.3

        # Strong attention to periods
        for period_pos in period_positions:
            if period_pos <= i:
                attention[i, period_pos] = 0.25

        # High attention to first tokens of sentences/paragraphs
        for first_pos in first_token_positions:
            if first_pos <= i:
                # Special case: if first token is content word, give it very high attention
                if first_pos == 0 and first_token_is_content:
                    attention[i, first_pos] = 0.65
                else:
                    attention[i, first_pos] = 0.2

        # Additional attention patterns
        current_token = tokens[i].strip()

        # If current token is structurally important, boost self-attention
        if current_token in ['\n', '.']:
            attention[i, i] = 0.4

        # Moderate attention to recent tokens (recency bias)
        for j in range(max(0, i-3), i):
            attention[i, j] += 0.02

        # Boost attention from content words to structural markers
        if i > 0 and len(current_token) > 2:  # Content words (not punctuation)
            for j in range(i):
                if tokens[j].strip() in ['\n', '.']:
                    attention[i, j] += 0.15

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L12H17", attention



def prog_L12H18(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Punctuation and newline-focused attention head with strong first-token anchoring."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    # Parse sentence to get linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    # Check if first token is a content word that should receive strong attention
    first_token_is_content = False
    if token_to_spacy[0] and len(token_to_spacy[0]) > 0:
        spacy_idx = token_to_spacy[0][0]
        if spacy_idx < len(doc):
            first_token_pos = doc[spacy_idx].pos_
            if first_token_pos in ['NOUN', 'VERB', 'ADJ', 'ADV', 'PROPN', 'PRON']:
                first_token_is_content = True

    for i in range(n):
        token = tokens[i]

        # Very strong self-attention for first token
        if i == 0:
            attention[i, i] = 1.0
            continue

        # High base attention to punctuation and newlines
        for j in range(i + 1):
            target_token = tokens[j]

            # Strong attention to periods and newlines
            if target_token.strip() in ['.', '\n']:
                attention[i, j] += 0.3

            # Medium attention to other punctuation
            elif target_token.strip() in [',', '!', '?', '"', "'", ':', ';']:
                attention[i, j] += 0.15

            # Strong attention to first token if it's a content word
            if j == 0 and first_token_is_content:
                attention[i, j] += 0.6

            # Positional decay - closer tokens get more attention
            distance = i - j
            if distance == 0:  # self-attention
                attention[i, j] += 0.05
            else:
                decay_factor = 1.0 / (1.0 + distance * 0.1)
                attention[i, j] += 0.02 * decay_factor

            # Boost attention between similar tokens
            if j < i:
                similarity = _char_sim(tokens[i], tokens[j])
                if similarity > 0.7:
                    attention[i, j] += 0.1 * similarity

            # Special handling for sentence boundary tokens
            if token_to_spacy[i] and token_to_spacy[j]:
                spacy_i = token_to_spacy[i][0] if token_to_spacy[i] else None
                spacy_j = token_to_spacy[j][0] if token_to_spacy[j] else None

                if spacy_i is not None and spacy_j is not None and spacy_i < len(doc) and spacy_j < len(doc):
                    # Boost attention to sentence beginnings and verb-related tokens
                    if doc[spacy_j].pos_ in ['VERB', 'AUX'] or doc[spacy_j].dep_ == 'ROOT':
                        attention[i, j] += 0.05

                    # Attention between tokens in different sentences
                    if doc[spacy_i].sent != doc[spacy_j].sent:
                        attention[i, j] += 0.08

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L12H18", attention



def prog_L12H19(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary attention head - focuses on periods, newlines, structural markers, and sentence beginnings."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L12H19", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Find boundary tokens (periods, newlines, exclamation marks, question marks)
    boundary_indices = []
    for i, token in enumerate(tokens):
        if token.strip() in ['.', '\n', '!', '?']:
            boundary_indices.append(i)

    for i in range(n):
        token = tokens[i]

        # Strong attention to boundary markers
        for boundary_idx in boundary_indices:
            if boundary_idx <= i:  # causal constraint
                # Higher weight for more recent boundaries
                recency_factor = 1.0 / (1 + 0.1 * (i - boundary_idx))
                attention[i, boundary_idx] = 0.4 * recency_factor

        # Strong attention to first token (sentence beginning)
        if i > 0 and tokens[0].strip() not in ['', ' ']:
            # Distance-based decay for attention to first token
            distance_factor = 1.0 / (1 + 0.05 * i)
            attention[i, 0] = 0.5 * distance_factor

        # Self-attention
        attention[i, i] = 0.1

        # Attention to immediate previous token
        if i > 0:
            attention[i, i-1] = 0.15

        # Additional attention to recent tokens (local context)
        for j in range(max(0, i-3), i):
            if j not in boundary_indices and j != 0:  # exclude first token to avoid double-counting
                attention[i, j] += 0.05

        # Special case: if current token is punctuation, attend more to preceding content
        if token.strip() in ['.', '!', '?', ',', ';']:
            for j in range(max(0, i-5), i):
                if j != 0:  # exclude first token to avoid double-counting
                    attention[i, j] += 0.1

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L12H19", attention



def prog_L12H2(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary attention with first-token bias and linguistic similarity."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L12H2", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        # Very strong attention to first token
        attention[i, 0] = 1.0

        # Strong attention to sentence-ending punctuation and newlines
        for j in range(i + 1):
            token_j = tokens[j].strip()
            if token_j in ['.', '!', '?"', '."', '!\n', '.\n']:
                attention[i, j] += 0.3
            elif token_j == '\n':
                attention[i, j] += 0.25

        # Moderate self-attention
        attention[i, i] += 0.05

        # Linguistic similarity component
        spacy_i = token_to_spacy[i]
        if spacy_i:
            spacy_tok_i = doc[spacy_i[0]]

            for j in range(i + 1):
                if j == 0 or j == i:  # Skip first token and self (already handled)
                    continue

                spacy_j = token_to_spacy[j]
                if spacy_j:
                    spacy_tok_j = doc[spacy_j[0]]

                    # Syntactic relationships
                    if (spacy_tok_j.head == spacy_tok_i or spacy_tok_i.head == spacy_tok_j or
                        spacy_tok_i.head == spacy_tok_j.head):
                        attention[i, j] += 0.02

                    # Same POS or semantic similarity
                    if spacy_tok_i.pos_ == spacy_tok_j.pos_:
                        attention[i, j] += 0.01

                # Token embedding similarity
                sim = _char_sim(tokens[i], tokens[j])
                if sim > 0.7:
                    attention[i, j] += 0.03 * sim
                elif sim > 0.5:
                    attention[i, j] += 0.01 * sim

        # Small baseline attention to all previous tokens
        for j in range(i + 1):
            attention[i, j] += 0.001

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L12H2", attention



def prog_L12H20(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Attention head that focuses on structural boundaries (newlines, periods) and first tokens."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L12H20", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Find structural boundary tokens (newlines, periods, and first token)
    boundary_indices = []
    for i, token in enumerate(tokens):
        if token.strip() in ['\n', '.'] or i == 0:
            boundary_indices.append(i)

    for i in range(n):
        # High attention to boundary tokens (newlines, periods, first token)
        for boundary_idx in boundary_indices:
            if boundary_idx <= i:  # respect causal mask
                if tokens[boundary_idx].strip() == '\n':
                    attention[i, boundary_idx] = 0.35
                elif tokens[boundary_idx].strip() == '.':
                    attention[i, boundary_idx] = 0.25
                elif boundary_idx == 0:
                    attention[i, boundary_idx] = 0.20

        # Medium attention to recent previous tokens
        for j in range(max(0, i-3), i):
            if attention[i, j] == 0:  # don't override boundary attention
                attention[i, j] = 0.08 / (i - j)

        # Small self-attention if no boundary attention
        if attention[i, i] == 0:
            attention[i, i] = 0.05

        # Small attention to other nearby tokens
        for j in range(i):
            if attention[i, j] == 0:
                attention[i, j] = 0.02

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L12H20", attention



def prog_L12H21(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Segment boundary and sentence-initial token attention head with strong newline attention."""
    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention_matrix = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    # Identify segment boundaries (periods and newlines)
    boundary_tokens = []
    newline_tokens = []
    sentence_starts = []

    for i, token in enumerate(tokens):
        if token.strip() == '.' or token.strip() == '.':
            boundary_tokens.append(i)
        if token.strip() == '\n' or token.strip().startswith('\n'):
            newline_tokens.append(i)
            # Next non-whitespace token after newline is likely sentence start
            if i + 1 < n:
                sentence_starts.append(i + 1)

    # First token is always a sentence start
    if n > 0:
        sentence_starts.append(0)

    sentence_starts = list(set(sentence_starts))
    sentence_starts.sort()

    for i in range(n):
        token = tokens[i]

        # Strong self-attention for certain tokens
        attention_matrix[i, i] = 0.1

        # MODIFIED: Much stronger attention to newlines across all positions
        for boundary_idx in newline_tokens:
            if boundary_idx <= i:
                attention_matrix[i, boundary_idx] = 0.45

        # Reduced attention to periods to avoid over-prediction
        for boundary_idx in boundary_tokens:
            if boundary_idx <= i:
                attention_matrix[i, boundary_idx] = 0.15

        # Strong attention to sentence-initial tokens
        for start_idx in sentence_starts:
            if start_idx <= i:
                attention_matrix[i, start_idx] = 0.2

        # Find which sentence this token belongs to
        current_sentence_start = 0
        for start_idx in sentence_starts:
            if start_idx <= i:
                current_sentence_start = start_idx
            else:
                break

        # Additional attention within the same sentence
        for j in range(current_sentence_start, i):
            if j in token_to_spacy and i in token_to_spacy:
                spacy_j_indices = token_to_spacy[j]
                spacy_i_indices = token_to_spacy[i]

                if spacy_j_indices and spacy_i_indices:
                    spacy_j = doc[spacy_j_indices[0]]
                    spacy_i = doc[spacy_i_indices[0]]

                    # Syntactic dependencies
                    if spacy_j in spacy_i.children or spacy_i.head == spacy_j:
                        attention_matrix[i, j] += 0.15

                    # Conjunctions attend to what they're connecting
                    if spacy_i.pos_ == 'CCONJ' and j == i - 1:
                        attention_matrix[i, j] += 0.2

        # Proximity bias - slight preference for recent tokens
        for j in range(max(0, i-5), i):
            attention_matrix[i, j] += 0.05 * (1.0 / (i - j + 1))

    # Apply causal mask and normalize
    attention_matrix = apply_causal_mask(attention_matrix)
    attention_matrix = make_row_stochastic(attention_matrix)

    return "prog_L12H21", attention_matrix



def prog_L12H22(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Attention head that focuses on sentence boundaries (newlines, periods) and first tokens with local context."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L12H22", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        # Base attention distribution
        row = np.zeros(n)

        # Strong attention to first token
        if i > 0:
            row[0] = 0.4

        # High attention to newlines and periods
        for j in range(i + 1):
            token = tokens[j].strip()
            if token == '\n':
                row[j] += 0.3
            elif token in ['.', '!', '?']:
                row[j] += 0.2

        # Self-attention
        row[i] += 0.1

        # Local attention - attend to previous few tokens
        for j in range(max(0, i - 3), i):
            row[j] += 0.05

        # Additional attention based on linguistic features
        if token_to_spacy[i]:
            spacy_idx = token_to_spacy[i][0]
            if spacy_idx < len(doc):
                spacy_token = doc[spacy_idx]

                # Verbs attend more to subjects/objects
                if spacy_token.pos_ == 'VERB':
                    for j in range(i):
                        if token_to_spacy[j]:
                            spacy_j_idx = token_to_spacy[j][0]
                            if spacy_j_idx < len(doc):
                                spacy_j = doc[spacy_j_idx]
                                if spacy_j.pos_ in ['NOUN', 'PRON']:
                                    row[j] += 0.1

                # Function words attend to content words
                if spacy_token.pos_ in ['DET', 'ADP', 'AUX']:
                    for j in range(i):
                        if token_to_spacy[j]:
                            spacy_j_idx = token_to_spacy[j][0]
                            if spacy_j_idx < len(doc):
                                spacy_j = doc[spacy_j_idx]
                                if spacy_j.pos_ in ['NOUN', 'VERB', 'ADJ']:
                                    row[j] += 0.05

        # Similarity-based attention
        for j in range(i):
            if _char_sim(tokens[i], tokens[j]) > 0.7:
                row[j] += 0.1

        attention[i] = row

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L12H22", attention



def prog_L12H23(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary detection head with strong first-token attention bias."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        # Very strong attention to first few tokens, especially token 0
        if i >= 1:
            attention[i, 0] = 0.6  # Strong first token bias
        if i >= 2:
            attention[i, 1] = 0.3  # Secondary attention to second token
        if i >= 3:
            attention[i, 2] = 0.2  # Weaker attention to third token

        # Self attention
        attention[i, i] = 0.1

        # Find sentence-ending punctuation (periods, exclamation marks)
        for j in range(i):
            if tokens[j].strip() in ['.', '!', '?"', '."']:
                attention[i, j] += 0.25

        # Attention to newlines (sentence boundaries)
        for j in range(i):
            if tokens[j].strip() == '\n' or '\\n' in tokens[j]:
                attention[i, j] += 0.2

        # Some recency bias - attend more to recent tokens
        for j in range(max(0, i-5), i):
            attention[i, j] += 0.05 * (1.0 - (i - j) / 6.0)

        # Boost attention for punctuation marks in general
        for j in range(i):
            if tokens[j].strip() in [',', ';', ':', '"', "'", '(', ')', '-']:
                attention[i, j] += 0.08

        # Additional boost for tokens that start sentences
        if token_to_spacy[i]:
            spacy_idx = token_to_spacy[i][0]
            if spacy_idx < len(doc):
                spacy_token = doc[spacy_idx]
                # If this token starts a sentence, attend more to sentence boundaries
                if spacy_token.is_sent_start:
                    for j in range(i):
                        if tokens[j].strip() in ['.', '!', '?"', '."', '\n']:
                            attention[i, j] += 0.15

    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L12H23", attention



def prog_L12H24(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Boundary and newline attention head with strong sentence-start attention."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        for j in range(i + 1):  # Causal mask
            weight = 0.0

            # Very strong attention to newlines
            if tokens[j] == '\n':
                weight += 0.4

            # Strong attention to sentence boundaries
            elif tokens[j] == '.':
                weight += 0.2

            # Much stronger attention to first token (sentence start)
            elif j == 0:
                weight += 0.15

            # Self-attention baseline (reduced to be more conservative)
            elif i == j:
                weight += 0.03

            # Previous token attention
            elif j == i - 1:
                weight += 0.03

            # Syntactic relationships via spacy
            if token_to_spacy[i] and token_to_spacy[j]:
                spacy_i = doc[token_to_spacy[i][0]]
                spacy_j = doc[token_to_spacy[j][0]]

                # Head-dependent relationships
                if spacy_i.head == spacy_j or spacy_j.head == spacy_i:
                    weight += 0.08

                # Subject-verb relationships
                if spacy_i.dep_ in ['nsubj', 'nsubjpass'] and spacy_j.pos_ == 'VERB':
                    weight += 0.06
                elif spacy_j.dep_ in ['nsubj', 'nsubjpass'] and spacy_i.pos_ == 'VERB':
                    weight += 0.06

                # Object relationships
                if spacy_i.dep_ in ['dobj', 'pobj'] and spacy_j.pos_ == 'VERB':
                    weight += 0.04
                elif spacy_j.dep_ in ['dobj', 'pobj'] and spacy_i.pos_ == 'VERB':
                    weight += 0.04

            # Embedding similarity boost for semantically similar tokens
            sim = _char_sim(tokens[i], tokens[j])
            if sim > 0.7:
                weight += 0.06 * sim
            elif sim > 0.5:
                weight += 0.03 * sim

            # Distance decay for non-special tokens
            if tokens[j] not in ['\n', '.'] and j != i and j != 0:
                distance = i - j
                if distance > 0:
                    weight *= (0.9 ** distance)

            attention[i, j] = weight

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L12H24", attention



def prog_L12H25(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary and structure detection head with semantic clustering and strong beginning-of-sequence attention."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    if n == 0:
        return "prog_L12H25", attention

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    # Identify sentence boundaries and first tokens
    sentence_boundaries = set()
    sentence_first_tokens = set()

    for i, token in enumerate(tokens):
        # Periods and newlines are sentence boundaries
        if token.strip() in ['.', '\n']:
            sentence_boundaries.add(i)
        # Empty tokens or newlines often mark sentence starts
        if token.strip() == '' or token.strip() == '\n':
            sentence_first_tokens.add(i)

    # If no clear sentence boundaries found, treat first token as sentence start
    if not sentence_first_tokens and n > 0:
        sentence_first_tokens.add(0)

    for i in range(n):
        # Strong attention to sentence boundaries (periods, newlines)
        for boundary_idx in sentence_boundaries:
            if boundary_idx <= i:
                attention[i, boundary_idx] += 0.4

        # Strong attention to sentence first tokens
        for first_idx in sentence_first_tokens:
            if first_idx <= i:
                attention[i, first_idx] += 0.3

        # NEW: Very strong attention to the absolute first token for later tokens
        if i > 5:  # Only for tokens well into the sequence
            attention[i, 0] += 0.6
        elif i > 2:  # Moderate boost for tokens early in sequence
            attention[i, 0] += 0.3

        # Self-attention
        attention[i, i] += 0.2

        # Attention to previous token
        if i > 0:
            attention[i, i-1] += 0.15

        # Semantic clustering - attend to similar tokens within local window
        window_size = min(10, i)
        for j in range(max(0, i - window_size), i):
            if j < i:
                sim = _char_sim(tokens[i], tokens[j])
                if sim > 0.5:  # High similarity threshold
                    attention[i, j] += 0.2 * sim

        # Linguistic features - attend to syntactically related tokens
        if token_to_spacy[i]:
            spacy_token = doc[token_to_spacy[i][0]]

            # Attend to head of current token
            if spacy_token.head != spacy_token:
                head_spacy_idx = spacy_token.head.i
                for j in range(i):
                    if j < len(token_to_spacy) and token_to_spacy[j]:
                        if head_spacy_idx in token_to_spacy[j]:
                            attention[i, j] += 0.1

            # Attend to dependents
            for child in spacy_token.children:
                child_spacy_idx = child.i
                for j in range(i):
                    if j < len(token_to_spacy) and token_to_spacy[j]:
                        if child_spacy_idx in token_to_spacy[j]:
                            attention[i, j] += 0.08

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L12H25", attention



def prog_L12H26(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Punctuation and sentence boundary attention with semantic similarity, including word fragment beginnings."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    for i in range(n):
        token_i = tokens[i].strip()

        for j in range(i + 1):  # Causal mask
            token_j = tokens[j].strip()

            # Strong attention to periods and newlines
            if token_j in ['.', '\n']:
                attention[i, j] += 2.0

            # High attention to first token if it's punctuation or newline
            if j == 0 and (token_j in ['.', '\n', ''] or len(token_j.strip()) == 0):
                attention[i, j] += 1.5

            # NEW: High attention to first token if it's a word fragment (contains letters)
            if j == 0 and len(token_j.strip()) > 0 and any(c.isalpha() for c in token_j):
                attention[i, j] += 1.5

            # Self-attention boost
            if i == j:
                attention[i, j] += 0.5

            # Punctuation tokens get extra attention
            if token_j in [',', '!', '?', '"', "'", ':', ';']:
                attention[i, j] += 0.8

            # Semantic similarity boost
            if i != j and len(token_i.strip()) > 0 and len(token_j.strip()) > 0:
                sim = _char_sim(tokens[i], tokens[j])
                if sim > 0.5:
                    attention[i, j] += sim * 0.6

            # Recency bias - closer tokens get more attention
            distance = i - j
            if distance > 0:
                recency_boost = 1.0 / (1.0 + 0.1 * distance)
                attention[i, j] += recency_boost * 0.3

            # Base attention for all valid positions
            attention[i, j] += 0.1

    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L12H26", attention



def prog_L12H27(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Structural separator attention with local syntax, recency bias, and first-token attraction."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L12H27", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        for j in range(i + 1):  # Causal mask
            weight = 0.0

            # Very high attention to newlines (structural separators)
            if tokens[j].strip() == '':  # newline or whitespace
                weight += 0.4

            # High attention to sentence-ending punctuation
            elif tokens[j] == '.':
                weight += 0.2

            # Self-attention for punctuation
            elif i == j and tokens[i] in ['.', ',', '"', '!', '?']:
                weight += 0.3

            # Local syntactic dependencies
            if token_to_spacy[i] and token_to_spacy[j]:
                spacy_i = token_to_spacy[i][0]
                spacy_j = token_to_spacy[j][0]

                if spacy_i < len(doc) and spacy_j < len(doc):
                    spacy_tok_i = doc[spacy_i]
                    spacy_tok_j = doc[spacy_j]

                    # Head-dependent relationships
                    if spacy_tok_i.head == spacy_tok_j or spacy_tok_j.head == spacy_tok_i:
                        weight += 0.15

                    # Adjacent tokens with strong syntactic relationship
                    if abs(i - j) == 1:
                        if spacy_tok_i.dep_ in ['aux', 'det', 'prep'] or spacy_tok_j.dep_ in ['aux', 'det', 'prep']:
                            weight += 0.1

            # Positional bias - prefer earlier tokens
            distance = i - j
            if distance > 0:
                recency_weight = 1.0 / (1.0 + distance * 0.1)
                weight *= recency_weight

            # Strong attention to first token (targeted fix for failure cases)
            if j == 0 and i > 0:
                first_token_boost = 0.3 / (1.0 + distance * 0.05)
                weight += first_token_boost

            # Embedding similarity for semantically related tokens
            sim = _char_sim(tokens[i], tokens[j])
            if sim > 0.5:
                weight += 0.05 * sim

            # Base attention for adjacent tokens
            if abs(i - j) == 1:
                weight += 0.02

            # Small self-attention baseline
            if i == j:
                weight += 0.01

            attention[i, j] = weight

    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L12H27", attention



def prog_L12H28(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Attention head that focuses on sentence boundaries and has strong attention back to the beginning of the sequence."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        token = tokens[i]

        # Very high attention to newlines and periods (sentence boundaries)
        for j in range(i + 1):
            target_token = tokens[j]

            # Strong attention to structural punctuation
            if target_token.strip() in ['.', '\n']:
                if target_token.strip() == '\n':
                    attention[i, j] = 0.3
                elif target_token.strip() == '.':
                    attention[i, j] = 0.25

            # Self-attention for first token
            if i == 0 and j == 0:
                attention[i, j] = 1.0
                continue
            elif i == j:
                attention[i, j] = 0.1

            # Strong attention back to the very beginning of the sequence
            if j == 0 and i > 0:
                # Tokens attend strongly to the first token with minimal decay
                attention[i, j] += 0.4

            # Attention based on position and linguistic features
            if len(token_to_spacy[i]) > 0 and len(token_to_spacy[j]) > 0:
                spacy_i = doc[token_to_spacy[i][0]]
                spacy_j = doc[token_to_spacy[j][0]]

                # Attention to syntactic heads and dependencies
                if spacy_j == spacy_i.head or spacy_i == spacy_j.head:
                    attention[i, j] += 0.08

                # Attention within noun phrases and verb phrases
                if spacy_i.pos_ in ['NOUN', 'PRON'] and spacy_j.pos_ in ['DET', 'ADJ']:
                    attention[i, j] += 0.06
                if spacy_i.pos_ == 'VERB' and spacy_j.pos_ in ['AUX', 'ADV']:
                    attention[i, j] += 0.06

            # Distance-based decay (prefer recent tokens), but reduced self-attention
            distance = i - j
            if distance > 0:
                decay_factor = 0.95 ** distance
                attention[i, j] *= decay_factor
                # Reduce excessive self-attention by applying stronger decay to self-attention
                if i == j:
                    attention[i, j] *= 0.5

            # Boost for embedding similarity
            sim = _char_sim(tokens[i], tokens[j])
            if sim > 0.7:
                attention[i, j] += 0.05 * sim

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L12H28", attention



def prog_L12H29(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary attention head with first-token bias and semantic similarity component."""
    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    # Find sentence boundaries (periods and newlines)
    sentence_boundaries = []
    for i, token in enumerate(tokens):
        if token.strip() in ['.', '\n']:
            sentence_boundaries.append(i)

    for i in range(n):
        # Strong attention to sentence boundaries, especially early ones
        for boundary in sentence_boundaries:
            if boundary <= i:
                # Higher weight for earlier boundaries, especially positions 4-6
                if boundary <= 6:
                    attention[i, boundary] = 0.4 - 0.03 * boundary
                else:
                    attention[i, boundary] = 0.15

        # Strong attention to first token
        attention[i, 0] = 0.25

        # Self-attention
        attention[i, i] = 0.08

        # Attention to semantically similar tokens
        for j in range(i):
            if j not in sentence_boundaries and j != 0:
                sim = _char_sim(tokens[i], tokens[j])
                if sim > 0.3:
                    attention[i, j] += 0.05 * sim

        # Small attention to recent tokens (recency bias)
        for j in range(max(0, i-5), i):
            if j not in sentence_boundaries and j != 0:
                attention[i, j] += 0.02 * (1 - (i - j) / 6)

        # Add small baseline attention to all previous tokens
        for j in range(i):
            attention[i, j] += 0.01

    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L12H29", attention



def prog_L12H3(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary and syntactic structure attention with segment-initial focus."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L12H3", np.zeros((n_empty, n_empty))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    # Initialize attention matrix
    attention = np.zeros((n, n))

    # Identify segment-initial tokens (capitalized words that start new segments)
    segment_starts = []
    for i in range(n):
        spacy_indices = token_to_spacy[i]
        if spacy_indices:
            spacy_token = doc[spacy_indices[0]]
            # Look for capitalized words that likely start new segments
            if (spacy_token.text and spacy_token.text[0].isupper() and 
                spacy_token.pos_ in ['NOUN', 'PRON', 'PROPN'] and
                i > 0):  # Not the very first token
                segment_starts.append(i)

    for i in range(n):
        # Strong self-attention baseline
        attention[i, i] = 0.1

        # Very strong attention to first token (often newline/start)
        if i > 0:
            attention[i, 0] = 0.3

        # NEW: Strong attention to recent segment-initial tokens
        for seg_start in segment_starts:
            if seg_start <= i and i - seg_start <= 15:  # Within reasonable distance
                # Stronger attention to more recent segment starts
                distance = i - seg_start
                segment_weight = 0.25 / (distance + 1) if distance <= 5 else 0.15 / (distance + 1)
                attention[i, seg_start] += segment_weight

        # Find sentence boundaries (newlines, periods) and attend strongly
        for j in range(i + 1):
            if tokens[j].strip() in ['\n', '.', '!', '?']:
                attention[i, j] += 0.2

        # Get spacy alignment for current token
        spacy_indices = token_to_spacy[i]
        if not spacy_indices:
            continue

        current_spacy = doc[spacy_indices[0]]

        # Syntactic attention patterns
        for j in range(i):
            j_spacy_indices = token_to_spacy[j]
            if not j_spacy_indices:
                continue

            target_spacy = doc[j_spacy_indices[0]]

            # Strong attention from tokens to their syntactic head
            if target_spacy == current_spacy.head and current_spacy != target_spacy:
                attention[i, j] += 0.15

            # Attention between syntactically related tokens
            if current_spacy.head == target_spacy.head and current_spacy != target_spacy:
                attention[i, j] += 0.08

            # Verbs attend to their subjects
            if (current_spacy.pos_ == 'VERB' and 
                target_spacy.dep_ in ['nsubj', 'nsubjpass']):
                attention[i, j] += 0.12

            # Nouns attend to their modifiers
            if (current_spacy.pos_ == 'NOUN' and 
                target_spacy.dep_ in ['amod', 'det'] and
                target_spacy.head == current_spacy):
                attention[i, j] += 0.1

        # Recency bias - attend more to recent tokens
        for j in range(max(0, i - 10), i):
            distance = i - j
            if distance <= 5:
                recency_weight = 0.05 / (distance + 1)
                attention[i, j] += recency_weight

        # Content word attention - attend to recent nouns and verbs
        for j in range(i):
            j_spacy_indices = token_to_spacy[j]
            if j_spacy_indices:
                target_spacy = doc[j_spacy_indices[0]]
                if target_spacy.pos_ in ['NOUN', 'VERB', 'ADJ']:
                    distance = i - j
                    content_weight = 0.04 / (distance + 1) if distance <= 8 else 0.01
                    attention[i, j] += content_weight

        # Semantic similarity boost
        for j in range(i):
            sim = _char_sim(tokens[i], tokens[j])
            if sim > 0.7:
                attention[i, j] += 0.06 * sim

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L12H3", attention



def prog_L12H30(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Punctuation and structure attention head with discourse marker detection."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L12H30", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    # Detect if early tokens are discourse markers that should receive strong attention
    discourse_boost = {}
    for pos in range(min(3, n)):  # Check first 3 tokens
        if token_to_spacy[pos]:
            for spacy_idx in token_to_spacy[pos]:
                if spacy_idx < len(doc):
                    spacy_token = doc[spacy_idx]
                    # Strong boost for discourse markers, interjections, and sentence-initial elements
                    if (spacy_token.pos_ in ['INTJ', 'PART'] or 
                        spacy_token.dep_ in ['discourse', 'intj'] or
                        (pos == 0 and spacy_token.pos_ in ['PRON', 'ADV', 'VERB'])):
                        discourse_boost[pos] = 0.4
                    # Moderate boost for other early content words
                    elif pos == 0 and spacy_token.pos_ in ['NOUN', 'PROPN']:
                        discourse_boost[pos] = 0.2

    for i in range(n):
        query_token = tokens[i].strip()

        # Self-attention (especially strong for first token)
        if i == 0:
            attention[i, i] = 1.0
        else:
            attention[i, i] = 0.15

        for j in range(i):  # Only look at previous tokens (causal)
            key_token = tokens[j].strip()

            # Very strong attention to periods
            if key_token == '.':
                attention[i, j] = 0.4

            # Strong attention to newlines
            elif key_token == '\n':
                attention[i, j] = 0.3

            # Enhanced attention to discourse markers
            elif j in discourse_boost:
                attention[i, j] = discourse_boost[j]

            # Moderate attention to first token (fallback)
            elif j == 0:
                attention[i, j] = 0.1

            else:
                # Base attention with distance decay
                distance = i - j
                base_attention = 0.05 / (1 + 0.1 * distance)

                # Add semantic similarity component
                similarity = _char_sim(tokens[i], tokens[j])
                semantic_boost = max(0, similarity) * 0.1

                # Check for linguistic relationships via spacy
                linguistic_boost = 0.0
                if token_to_spacy[i] and token_to_spacy[j]:
                    i_spacy_indices = token_to_spacy[i]
                    j_spacy_indices = token_to_spacy[j]

                    for i_idx in i_spacy_indices:
                        for j_idx in j_spacy_indices:
                            if i_idx < len(doc) and j_idx < len(doc):
                                i_tok = doc[i_idx]
                                j_tok = doc[j_idx]

                                # Boost for head-dependent relationships
                                if i_tok.head == j_tok or j_tok.head == i_tok:
                                    linguistic_boost = max(linguistic_boost, 0.08)

                                # Boost for same POS patterns
                                if i_tok.pos_ == j_tok.pos_ and i_tok.pos_ in ['NOUN', 'VERB', 'ADJ']:
                                    linguistic_boost = max(linguistic_boost, 0.05)

                attention[i, j] = base_attention + semantic_boost + linguistic_boost

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L12H30", attention



def prog_L12H31(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Attention head that combines structural boundary detection with semantic similarity matching."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        query_token = tokens[i]

        # Get spacy info for query token if available
        query_spacy_indices = token_to_spacy[i]
        query_spacy = doc[query_spacy_indices[0]] if query_spacy_indices else None

        for j in range(i + 1):  # Causal mask
            key_token = tokens[j]

            # Base attention
            base_weight = 0.01

            # Strong self-attention
            if i == j:
                base_weight += 0.3

            # High attention to sentence boundaries (newlines and periods)
            if key_token.strip() in ['\n', '.']:
                base_weight += 0.4

            # High attention to first token
            if j == 0:
                base_weight += 0.2

            # Attention to other punctuation
            if key_token.strip() in [',', '!', '?', '"', ';', ':']:
                base_weight += 0.1

            # Semantic similarity boost
            if i != j:
                sim = _char_sim(tokens[i], tokens[j])
                if sim > 0.7:
                    base_weight += 0.3
                elif sim > 0.5:
                    base_weight += 0.2
                elif sim > 0.3:
                    base_weight += 0.1

            # Recent token bias (slight preference for nearby tokens)
            if i > j and i - j <= 3:
                base_weight += 0.05 * (4 - (i - j)) / 4

            # Special patterns for certain constructions
            if query_spacy and token_to_spacy[j]:
                key_spacy = doc[token_to_spacy[j][0]]

                # Attention between related syntactic elements
                if (query_spacy.dep_ in ['nsubj', 'dobj'] and 
                    key_spacy.pos_ == 'VERB'):
                    base_weight += 0.15

                # Attention from modifiers to heads
                if (query_spacy.dep_ in ['amod', 'advmod'] and 
                    key_spacy == query_spacy.head):
                    base_weight += 0.2

            # Boost for content words attending to function words
            if (query_spacy and query_spacy.pos_ in ['NOUN', 'VERB', 'ADJ'] and
                token_to_spacy[j] and doc[token_to_spacy[j][0]].pos_ in ['DET', 'ADP', 'AUX']):
                base_weight += 0.08

            attention[i, j] = base_weight

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L12H31", attention



def prog_L12H4(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary and first-token attention head with semantic similarity."""
    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L12H4", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Get spacy alignment for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    # Identify sentence boundaries and first tokens
    sentence_boundaries = []
    first_tokens = []

    for i, token in enumerate(tokens):
        # Check for sentence boundaries (periods, newlines)
        if token.strip() in ['.', '\n']:
            sentence_boundaries.append(i)

        # Identify first tokens (start of sentence or after boundary)
        if i == 0:
            first_tokens.append(i)
        elif i > 0 and tokens[i-1].strip() in ['.', '\n']:
            first_tokens.append(i)

    for i in range(n):
        current_token = tokens[i].strip()

        # High attention to sentence boundaries
        for boundary_idx in sentence_boundaries:
            if boundary_idx <= i:
                attention[i, boundary_idx] += 0.4

        # High attention to first tokens
        for first_idx in first_tokens:
            if first_idx <= i:
                attention[i, first_idx] += 0.3

        # Self-attention
        attention[i, i] += 0.2

        # Attention to semantically similar tokens in local context
        for j in range(max(0, i-10), i):
            sim = _char_sim(tokens[i], tokens[j])
            if sim > 0.3:
                attention[i, j] += 0.15 * sim

        # Special boost for tokens immediately after newlines/periods
        if current_token in ['.', '\n']:
            attention[i, i] += 0.3

        # Boost attention from tokens to recent sentence boundaries
        for boundary_idx in sentence_boundaries:
            if boundary_idx <= i and i - boundary_idx <= 5:
                attention[i, boundary_idx] += 0.2

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L12H4", attention



def prog_L12H5(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Discourse boundary and semantic similarity attention head with strong first-token attention."""
    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L12H5", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        for j in range(i + 1):  # Causal mask
            weight = 0.01  # Base weight

            token_i = tokens[i]
            token_j = tokens[j]

            # Self-attention boost
            if i == j:
                weight += 0.1

            # Strong attention to sentence boundaries (periods and newlines)
            if token_j in ['.', '\n']:
                weight += 0.15

            # First token attention - ENHANCED
            if j == 0:
                # Much stronger boost for first token based on distance
                distance = i - j
                if distance <= 10:
                    weight += 0.4 * (0.9 ** distance)
                else:
                    weight += 0.05

            # Punctuation boundaries
            if token_j in [',', '!', '?', ';', ':']:
                weight += 0.08

            # Quote marks and special tokens
            if token_j in ['"', "'", ''', ''']:
                weight += 0.06

            # Distance decay
            distance = i - j
            if distance > 0:
                weight *= (0.85 ** distance)

            # Semantic similarity boost
            if i != j:
                similarity = _char_sim(tokens[i], tokens[j])
                if similarity > 0.5:
                    weight += 0.08 * similarity

            # Special boost for adjacent tokens
            if distance == 1:
                weight += 0.05

            # Look for linguistic relationships using spacy
            if token_to_spacy[i] and token_to_spacy[j]:
                spacy_i_indices = token_to_spacy[i]
                spacy_j_indices = token_to_spacy[j]

                for si in spacy_i_indices:
                    for sj in spacy_j_indices:
                        if si < len(doc) and sj < len(doc):
                            spacy_i_tok = doc[si]
                            spacy_j_tok = doc[sj]

                            # Dependency relationships
                            if spacy_j_tok.head == spacy_i_tok or spacy_i_tok.head == spacy_j_tok:
                                weight += 0.04

                            # Same entity type
                            if spacy_i_tok.ent_type_ and spacy_i_tok.ent_type_ == spacy_j_tok.ent_type_:
                                weight += 0.03

            attention[i, j] = weight

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L12H5", attention



def prog_L12H6(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Structural boundary attention with enhanced first-token grounding for semantically related tokens."""
    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L12H6", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    for i in range(n):
        # Strong attention to newlines and periods (structural boundaries)
        for j in range(i + 1):
            if tokens[j] == '\n':
                attention[i, j] = 0.3
            elif tokens[j] == '.':
                attention[i, j] = 0.25
            elif tokens[j] == '!':
                attention[i, j] = 0.2
            elif tokens[j] == '?':
                attention[i, j] = 0.2

        # Self-attention
        attention[i, i] += 0.1

        # Enhanced attention to first token based on semantic similarity
        if i > 0:
            base_first_attention = 0.15
            # Check semantic similarity to first token
            sim = _char_sim(tokens[i], tokens[0])
            # Boost first token attention for semantically related tokens
            if sim > 0.3:  # Semantically related
                attention[i, 0] += base_first_attention + 0.4 * sim
            else:
                attention[i, 0] += base_first_attention

        # Small recency bias to previous few tokens
        for j in range(max(0, i-3), i):
            attention[i, j] += 0.05 * (1.0 / (i - j))

        # Small uniform attention to all previous tokens
        for j in range(i):
            attention[i, j] += 0.01

    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L12H6", attention



def prog_L12H7(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Segment boundary attention: tokens attend to first tokens and newlines in their segment."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    # Find newline positions and sentence boundaries
    newline_positions = []
    first_token_positions = []

    # Identify newlines and first tokens after newlines
    for i, token in enumerate(tokens):
        if token.strip() == '\n':
            newline_positions.append(i)
            if i + 1 < n:
                first_token_positions.append(i + 1)

    # Add position 0 as a first token
    if n > 0:
        first_token_positions.append(0)

    # Find sentence-ending punctuation
    punct_positions = []
    for i, token in enumerate(tokens):
        if token.strip() in ['.', '!', '?']:
            punct_positions.append(i)

    for i in range(n):
        # Find the most recent newline before or at position i
        relevant_newline = -1
        relevant_first_token = 0

        for nl_pos in newline_positions:
            if nl_pos <= i:
                relevant_newline = nl_pos
                # Find first token after this newline
                if nl_pos + 1 < n:
                    relevant_first_token = nl_pos + 1

        # Strong attention to first token of segment
        if relevant_first_token <= i:
            attention[i, relevant_first_token] = 0.6

        # Strong attention to relevant newline
        if relevant_newline >= 0 and relevant_newline <= i:
            attention[i, relevant_newline] = 0.3

        # Moderate attention to sentence-ending punctuation in same segment
        for punct_pos in punct_positions:
            if punct_pos <= i and (relevant_newline < 0 or punct_pos > relevant_newline):
                attention[i, punct_pos] = 0.15

        # Small attention to previous token
        if i > 0:
            attention[i, i-1] = 0.05

        # Self-attention baseline
        attention[i, i] = 0.02

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L12H7", attention



def prog_L12H8(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary and punctuation-focused attention with first-token bias."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L12H8", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Parse sentence for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        # Self-attention baseline
        attention[i, i] = 0.1

        # Strong first-token attention
        attention[i, 0] = 0.4

        # Find sentence boundaries and punctuation
        for j in range(i + 1):
            token = tokens[j]

            # Very high attention to newlines and periods (sentence boundaries)
            if token in ['\n', '.']:
                attention[i, j] += 0.6

            # High attention to other punctuation
            elif token in [',', '!', '?', ';', ':']:
                attention[i, j] += 0.3

            # Moderate attention to immediate predecessor
            elif j == i - 1:
                attention[i, j] += 0.2

            # Attention to tokens at sentence/clause boundaries
            if j < len(token_to_spacy) and token_to_spacy[j]:
                spacy_indices = token_to_spacy[j]
                for spacy_idx in spacy_indices:
                    if spacy_idx < len(doc):
                        spacy_token = doc[spacy_idx]
                        # Boost attention for sentence-ending tokens
                        if spacy_token.sent_start or spacy_token.is_sent_end:
                            attention[i, j] += 0.2
                        # Boost for clause boundaries
                        if spacy_token.dep_ in ['punct', 'cc']:  # coordinating conjunctions
                            attention[i, j] += 0.1

        # Add some recency bias for recent tokens
        for j in range(max(0, i - 5), i):
            attention[i, j] += 0.05 * (1.0 - (i - j) / 6.0)

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L12H8", attention



def prog_L12H9(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Attention head that focuses on first tokens, sentence boundaries, and local context."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L12H9", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    for i in range(n):
        # Very high attention to first token
        attention[i, 0] = 0.5

        # High attention to punctuation and newlines
        for j in range(i + 1):
            token = tokens[j].strip()
            if token in ['.', '!', '?', '\n', ',', ';', ':']:
                attention[i, j] += 0.3

        # Self-attention
        attention[i, i] += 0.2

        # Previous token attention
        if i > 0:
            attention[i, i-1] += 0.15

        # Decay with distance for nearby tokens
        for j in range(max(0, i-3), i):
            if j != i-1:  # Don't double-count previous token
                distance = i - j
                attention[i, j] += 0.1 / distance

        # Small uniform attention to remaining positions
        for j in range(i + 1):
            if attention[i, j] == 0:
                attention[i, j] = 0.01

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L12H9", attention



def prog_L13H0(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary attention head with focus on periods, newlines, and first token."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L13H0", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    alignment = _align_to_spacy(sentence, tokens)

    for i in range(n):
        token = tokens[i]

        # Base weights
        weights = np.zeros(i + 1)  # Only attend to previous tokens (causal)

        # Strong attention to sentence boundaries (periods and newlines)
        for j in range(i + 1):
            target_token = tokens[j]

            # Very high attention to periods and newlines
            if target_token.strip() in ['.', '\n']:
                weights[j] += 0.3

            # High attention to first token
            if j == 0:
                weights[j] += 0.15

            # Self-attention gets moderate boost
            if i == j:
                weights[j] += 0.05

            # Recency bias - closer tokens get higher weight
            distance = i - j
            if distance <= 5:
                weights[j] += 0.1 / (1 + distance * 0.3)
            else:
                weights[j] += 0.02

            # Check for syntactic relationships using spacy alignment
            if alignment[i] and alignment[j]:
                spacy_i_tokens = [doc[idx] for idx in alignment[i] if idx < len(doc)]
                spacy_j_tokens = [doc[idx] for idx in alignment[j] if idx < len(doc)]

                for si_token in spacy_i_tokens:
                    for sj_token in spacy_j_tokens:
                        # Boost for head-dependent relationships
                        if sj_token == si_token.head or si_token == sj_token.head:
                            weights[j] += 0.05

                        # Boost for certain POS patterns
                        if si_token.pos_ in ['VERB', 'NOUN'] and sj_token.pos_ in ['DET', 'ADP']:
                            weights[j] += 0.02

        # Ensure non-zero weights
        if weights.sum() == 0:
            weights[i] = 1.0

        attention[i, :i+1] = weights

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L13H0", attention



def prog_L13H1(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Attention head focusing on structural boundaries, newlines, periods, and discourse markers."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L13H1", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        # Base attention distribution
        base_weights = np.zeros(i + 1)  # Can only attend to tokens <= i

        # Very high attention to structural markers
        for j in range(i + 1):
            token = tokens[j].strip()

            # Strong attention to newlines and periods
            if token == '\n':
                base_weights[j] += 3.0
            elif token == '.':
                base_weights[j] += 2.5

            # Attention to first token
            if j == 0:
                base_weights[j] += 1.5

            # Self attention
            if j == i:
                base_weights[j] += 0.8

        # Syntactic patterns using spacy
        if token_to_spacy[i]:
            current_spacy_idx = token_to_spacy[i][0]
            if current_spacy_idx < len(doc):
                current_token = doc[current_spacy_idx]

                # Look for conjunctions and clause markers
                for j in range(i + 1):
                    if token_to_spacy[j]:
                        target_spacy_idx = token_to_spacy[j][0]
                        if target_spacy_idx < len(doc):
                            target_token = doc[target_spacy_idx]

                            # Attend to coordinating conjunctions
                            if target_token.pos_ == 'CCONJ':
                                base_weights[j] += 1.0

                            # Attend to subordinating conjunctions
                            if target_token.pos_ == 'SCONJ':
                                base_weights[j] += 0.8

                            # Attend to commas (often clause boundaries)
                            if target_token.text == ',':
                                base_weights[j] += 0.6

                            # Attend to sentence starts (proper nouns, pronouns at start)
                            if target_token.pos_ in ['PROPN', 'PRON'] and target_spacy_idx < 3:
                                base_weights[j] += 0.5

        # Add some recency bias
        for j in range(i + 1):
            distance = i - j
            if distance <= 3:
                base_weights[j] += 0.2 / (distance + 1)

        # Look for repeated or similar content
        current_token = tokens[i].strip().lower()
        for j in range(i + 1):
            target_token = tokens[j].strip().lower()
            if len(current_token) > 2 and len(target_token) > 2:
                sim = _char_sim(tokens[i], tokens[j])
                if sim > 0.7:
                    base_weights[j] += 0.3 * sim

        # Ensure non-zero weights
        if np.sum(base_weights) == 0:
            base_weights[max(0, i-1):i+1] = 0.1

        attention[i, :i+1] = base_weights

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L13H1", attention



def prog_L13H10(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary and structural marker attention with strong first-token focus."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L13H10", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Get spacy alignment for linguistic features
    spacy_alignment = _align_to_spacy(sentence, tokens)
    doc = spacy_parse(sentence)

    # Check if first token is semantically significant (verb, noun, or proper noun)
    first_token_important = False
    if spacy_alignment[0]:
        for spacy_idx in spacy_alignment[0]:
            if spacy_idx < len(doc):
                spacy_token = doc[spacy_idx]
                if spacy_token.pos_ in ['VERB', 'NOUN', 'PROPN']:
                    first_token_important = True
                    break

    for i in range(n):
        # Reduced self-attention baseline
        attention[i, i] = 0.2

        # Very strong attention to sentence boundaries (periods, newlines)
        for j in range(i + 1):
            token_j = tokens[j].strip()
            if token_j in ['.', '\n']:
                attention[i, j] += 0.4

        # Enhanced boost for first token when it's semantically important
        if i > 0:
            if first_token_important:
                attention[i, 0] += 0.35  # Much stronger boost
            else:
                attention[i, 0] += 0.1  # Original boost

        # Add some recency bias to recent tokens
        for j in range(max(0, i - 5), i):
            attention[i, j] += 0.05 * (1.0 - (i - j) / 6.0)

        # Look for semantic similarity with recent tokens
        for j in range(max(0, i - 10), i):
            sim = _char_sim(tokens[i], tokens[j])
            if sim > 0.7:
                attention[i, j] += 0.1 * sim

        # Check for syntactic relationships via spacy
        if spacy_alignment[i]:
            spacy_i_indices = spacy_alignment[i]
            for spacy_idx in spacy_i_indices:
                if spacy_idx < len(doc):
                    spacy_token = doc[spacy_idx]

                    # Attend to syntactic head
                    if spacy_token.head != spacy_token:
                        for j in range(i):
                            if spacy_alignment[j]:
                                for spacy_j in spacy_alignment[j]:
                                    if spacy_j < len(doc) and doc[spacy_j] == spacy_token.head:
                                        attention[i, j] += 0.08

        # Boost attention to commas and quotation marks as structural markers
        for j in range(i + 1):
            token_j = tokens[j].strip()
            if token_j in [',', '"', "'", ':', ';']:
                attention[i, j] += 0.15

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L13H10", attention



def prog_L13H11(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary and early token attention with enhanced document-start bias."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L13H11", np.zeros((n_empty, n_empty))

    # Initialize attention matrix
    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        # Strong self-attention for first token
        if i == 0:
            attention[i, i] = 1.0
            continue

        # Get current token info
        current_token = tokens[i].strip()
        current_spacy_indices = token_to_spacy[i] if i < len(token_to_spacy) else []

        for j in range(i + 1):  # Only attend to previous tokens and self
            target_token = tokens[j].strip()
            target_spacy_indices = token_to_spacy[j] if j < len(token_to_spacy) else []

            weight = 0.0

            # Enhanced attention to document/sentence beginnings
            if j == 0:
                # Much stronger attention to the very first token
                weight += 0.4
            elif j == 1:
                # Strong attention to second token too
                weight += 0.2

            # Reduced attention to sentence boundaries (periods, newlines) from distant tokens
            if target_token in ['.', '\n']:
                distance = i - j
                if distance > 10:
                    weight += 0.1  # Reduced from 0.3
                else:
                    weight += 0.3

            # Reduced self-attention for most tokens
            if i == j and i > 0:
                weight += 0.02  # Reduced from 0.05

            # Attention to nearby tokens (recency bias)
            distance = i - j
            if distance <= 5:
                weight += 0.05 * (6 - distance) / 6

            # Syntactic relationships
            if current_spacy_indices and target_spacy_indices:
                for curr_idx in current_spacy_indices:
                    for targ_idx in target_spacy_indices:
                        if curr_idx < len(doc) and targ_idx < len(doc):
                            curr_spacy = doc[curr_idx]
                            targ_spacy = doc[targ_idx]

                            # Attend to syntactic head
                            if curr_spacy.head == targ_spacy:
                                weight += 0.08

                            # Attend to dependents
                            if targ_spacy.head == curr_spacy:
                                weight += 0.04

            # Token similarity
            if i != j:
                sim = _char_sim(tokens[i], tokens[j])
                if sim > 0.5:
                    weight += 0.03 * sim

            attention[i, j] = weight

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L13H11", attention



def prog_L13H12(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Attention head with adaptive self-attention: tokens vary in self-attention strength based on context."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L13H12", np.zeros((n_empty, n_empty))

    attention_matrix = np.zeros((n, n))

    # Identify structural tokens
    first_token_idx = 0
    sentence_boundaries = []
    newlines = []

    for i, token in enumerate(tokens):
        if token.strip() in ['.', '!', '?']:
            sentence_boundaries.append(i)
        elif token.strip() == '\n' or token == '\n':
            newlines.append(i)

    for i in range(n):
        token = tokens[i].strip()

        # Strong self-attention for first token
        if i == 0:
            attention_matrix[i, i] = 1.0
            continue

        # Base attention pattern
        weights = np.zeros(i + 1)

        # Adaptive self-attention based on token characteristics
        base_self_attention = 0.1

        # Increase self-attention for punctuation and structural tokens
        if token in ['.', '!', '?', ',', '\n', '"', "'", ''', ''', '™']:
            base_self_attention = 0.4
        # Increase self-attention for function words and common tokens
        elif len(token.strip()) <= 3 and token.strip().isalpha():
            base_self_attention = 0.25
        # Moderate increase for longer tokens
        elif len(token.strip()) > 6:
            base_self_attention = 0.2

        weights[i] = base_self_attention

        # Reduce other attention proportionally when self-attention is high
        remaining_weight = 1.0 - base_self_attention

        if remaining_weight > 0:
            # Scale down first token attention when self-attention is high
            first_token_weight = 0.4 * remaining_weight / 0.9
            weights[first_token_idx] = first_token_weight

            # High attention to most recent newline
            recent_newline = -1
            for nl_idx in newlines:
                if nl_idx < i:
                    recent_newline = nl_idx
            if recent_newline >= 0:
                newline_weight = 0.3 * remaining_weight / 0.9
                weights[recent_newline] += newline_weight

            # Moderate attention to recent sentence boundaries
            recent_boundary = -1
            for bound_idx in sentence_boundaries:
                if bound_idx < i:
                    recent_boundary = bound_idx
            if recent_boundary >= 0:
                boundary_weight = 0.2 * remaining_weight / 0.9
                weights[recent_boundary] += boundary_weight

            # Small attention to immediate previous token
            if i > 0:
                prev_weight = 0.05 * remaining_weight / 0.9
                weights[i-1] += prev_weight

        # Normalize to ensure valid probabilities
        if weights.sum() > 0:
            weights = weights / weights.sum()
        else:
            weights[i] = 1.0

        attention_matrix[i, :i+1] = weights

    # Apply causal mask and make row stochastic
    attention_matrix = apply_causal_mask(attention_matrix)
    attention_matrix = make_row_stochastic(attention_matrix)

    return "prog_L13H12", attention_matrix



def prog_L13H13(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary and first token attention with local context bias."""
    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L13H13", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    for i in range(n):
        for j in range(i + 1):  # causal mask
            weight = 0.0

            # Very high attention to sentence boundaries (periods and newlines)
            if tokens[j] in ['.', '\n']:
                weight += 0.4

            # High attention to first token of sequence
            if j == 0:
                weight += 0.3

            # Medium attention to immediately previous token
            if j == i - 1 and i > 0:
                weight += 0.15

            # Self-attention baseline
            if i == j:
                weight += 0.1

            # Distance decay for non-boundary tokens
            if tokens[j] not in ['.', '\n'] and j != 0:
                distance = i - j
                if distance <= 5:
                    weight += 0.1 / (1 + distance * 0.3)
                else:
                    weight += 0.05 / (1 + distance * 0.5)

            # Boost for semantic similarity
            if i != j:
                sim = _char_sim(tokens[i], tokens[j])
                if sim > 0.7:
                    weight += 0.2 * sim
                elif sim > 0.5:
                    weight += 0.1 * sim

            # Special boost for tokens that might be part of names or important phrases
            if j < i:
                try:
                    # Check if tokens are alphabetic and might be semantically related
                    if (tokens[i].strip().isalpha() and tokens[j].strip().isalpha() and 
                        len(tokens[i].strip()) > 2 and len(tokens[j].strip()) > 2):
                        sim = _char_sim(tokens[i], tokens[j])
                        if sim > 0.6:
                            weight += 0.15
                except:
                    pass

            attention[i][j] = weight

    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L13H13", attention



def prog_L13H14(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Structural boundary detection head with special attention to sentence-initial tokens."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    # Identify structural tokens
    punctuation_tokens = set()
    newline_tokens = set()

    for i, token in enumerate(tokens):
        if token.strip() == '.':
            punctuation_tokens.add(i)
        elif token.strip() == '\n':
            newline_tokens.add(i)

    # Special case: if first token is not a structural delimiter, it gets high attention
    first_token_is_content = (len(tokens) > 0 and 
                             0 not in punctuation_tokens and 
                             0 not in newline_tokens and 
                             tokens[0].strip() not in ['', ' '])

    for i in range(n):
        token = tokens[i]

        # Strong self-attention for punctuation and newlines
        if token.strip() in ['.', '\n']:
            attention[i, i] = 0.5

        # Special case: high attention to first token if it's content
        if first_token_is_content:
            if i == 0:
                attention[i, i] = 0.5  # Self-attention for first token
            else:
                attention[i, 0] += 0.4  # Strong attention to first token from others

        # High attention to newlines (paragraph boundaries)
        for nl_idx in newline_tokens:
            if nl_idx <= i:
                attention[i, nl_idx] += 0.3

        # High attention to periods (sentence boundaries)  
        for punct_idx in punctuation_tokens:
            if punct_idx <= i:
                attention[i, punct_idx] += 0.2

        # Moderate attention to recent tokens
        for j in range(max(0, i-5), i):
            if j not in newline_tokens and j not in punctuation_tokens:
                # Reduce recent token attention if first token is getting high attention
                weight = 0.05 if first_token_is_content else 0.1
                attention[i, j] += weight

        # Light attention to first few tokens (but less if first token already handled)
        for j in range(min(3, i)):
            if not first_token_is_content or j != 0:
                attention[i, j] += 0.05

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L13H14", attention



def prog_L13H15(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Local context and sentence boundary detection head with syntactic awareness and strong first-token attention."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention_matrix = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    alignment = _align_to_spacy(sentence, tokens)

    for i in range(n):
        current_token = tokens[i].strip()

        # Strong attention to sentence boundaries (newlines, periods)
        for j in range(i + 1):
            target_token = tokens[j].strip()

            # High attention to newlines and periods
            if target_token in ['\n', '.', '!', '?']:
                attention_matrix[i, j] = 0.3

            # Self-attention for important tokens
            if i == j:
                attention_matrix[i, j] = 0.1

            # Strong attention to immediately previous token
            if j == i - 1:
                attention_matrix[i, j] += 0.25

            # Attention to first token
            if j == 0 and tokens[0].strip():
                attention_matrix[i, j] += 0.15

            # Local window attention (decay with distance)
            distance = i - j
            if distance <= 5 and distance > 0:
                attention_matrix[i, j] += 0.1 / (distance + 1)

            # Semantic similarity boost
            if j < i:
                sim = _char_sim(tokens[i], tokens[j])
                if sim > 0.7:
                    attention_matrix[i, j] += 0.15 * sim

        # Add syntactic attention using spacy features
        if alignment[i]:
            spacy_idx = alignment[i][0]
            if spacy_idx < len(doc):
                spacy_token = doc[spacy_idx]

                # Verbs attend to their subjects and objects
                if spacy_token.pos_ == 'VERB':
                    for child in spacy_token.children:
                        if child.dep_ in ['nsubj', 'dobj', 'iobj']:
                            # Find corresponding token indices
                            child_char_start = child.idx
                            for k in range(i):
                                if alignment[k]:
                                    for spacy_k in alignment[k]:
                                        if spacy_k < len(doc) and doc[spacy_k].idx <= child_char_start < doc[spacy_k].idx + len(doc[spacy_k].text):
                                            attention_matrix[i, k] += 0.2

                # Nouns attend to their modifiers
                if spacy_token.pos_ in ['NOUN', 'PROPN']:
                    for child in spacy_token.children:
                        if child.dep_ in ['amod', 'det']:
                            child_char_start = child.idx
                            for k in range(i):
                                if alignment[k]:
                                    for spacy_k in alignment[k]:
                                        if spacy_k < len(doc) and doc[spacy_k].idx <= child_char_start < doc[spacy_k].idx + len(doc[spacy_k].text):
                                            attention_matrix[i, k] += 0.15

    # Special case: boost attention to first token when it's a meaningful word
    first_token = tokens[0].strip()
    if first_token and first_token not in ['\n', '.', '!', '?', ',', ';', ':', ' ', '']:
        # Check if first token corresponds to a content word in spacy
        first_is_content = False
        if alignment[0]:
            spacy_idx = alignment[0][0]
            if spacy_idx < len(doc):
                spacy_token = doc[spacy_idx]
                if spacy_token.pos_ in ['NOUN', 'PROPN', 'VERB', 'ADJ', 'ADV']:
                    first_is_content = True

        if first_is_content or len(first_token) > 2:  # Content word or substantial token
            for i in range(1, n):
                # Strong boost to first token attention, especially for distant tokens
                distance = i
                boost = 0.4 / (1 + distance * 0.1)  # Decay slowly with distance
                attention_matrix[i, 0] += boost

    # Apply causal mask and normalize
    attention_matrix = apply_causal_mask(attention_matrix)
    attention_matrix = make_row_stochastic(attention_matrix)

    return "prog_L13H15", attention_matrix



def prog_L13H16(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary and newline attention head with strong sentence-initial token bias."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L13H16", np.zeros((n_empty, n_empty))

    attention_matrix = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        token = tokens[i]

        # Base attention distribution
        for j in range(i + 1):  # Causal mask

            # Strong attention to newlines
            if tokens[j] == '\n':
                attention_matrix[i, j] = 0.3

            # Strong attention to sentence-ending punctuation
            elif tokens[j] in ['.', '!', '?']:
                attention_matrix[i, j] = 0.2

            # ENHANCED: Much stronger attention to the very first token (sentence-initial)
            elif j == 0:
                attention_matrix[i, j] = 0.4

            # Attention to commas and other punctuation
            elif tokens[j] in [',', ';', ':']:
                attention_matrix[i, j] = 0.08

            # Self-attention
            elif i == j:
                attention_matrix[i, j] = 0.05

            # Previous token attention
            elif j == i - 1:
                attention_matrix[i, j] = 0.06

            # Syntactic dependencies (if available)
            else:
                base_weight = 0.02

                # Check for syntactic relationships
                if token_to_spacy[i] and token_to_spacy[j]:
                    spacy_i = token_to_spacy[i][0]
                    spacy_j = token_to_spacy[j][0] 

                    if spacy_i < len(doc) and spacy_j < len(doc):
                        spacy_tok_i = doc[spacy_i]
                        spacy_tok_j = doc[spacy_j]

                        # Head-dependent relationships
                        if spacy_tok_i.head == spacy_tok_j or spacy_tok_j.head == spacy_tok_i:
                            base_weight = 0.04

                        # Similar embeddings
                        sim = _char_sim(tokens[i], tokens[j])
                        if sim > 0.7:
                            base_weight *= 1.5

                attention_matrix[i, j] = base_weight

        # Special case: if current token is newline, attend strongly to previous punctuation
        if token == '\n':
            for j in range(i):
                if tokens[j] in ['.', '!', '?']:
                    attention_matrix[i, j] *= 2.0

    # Apply causal mask and normalize
    attention_matrix = apply_causal_mask(attention_matrix)
    attention_matrix = make_row_stochastic(attention_matrix)

    return "prog_L13H16", attention_matrix



def prog_L13H17(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Discourse boundary and positional attention head with strong focus on sentence breaks and first tokens."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        # Base attention to self
        attention[i, i] = 0.1

        # Strong attention to first token
        attention[i, 0] = 0.3

        # Strong attention to sentence boundaries (periods and newlines)
        for j in range(i + 1):
            token = tokens[j].strip()
            if token == '\n':
                attention[i, j] += 0.4
            elif token == '.':
                attention[i, j] += 0.25
            elif token in [',', '!', '?']:
                attention[i, j] += 0.1

        # Special case: very early discourse boundaries get much stronger attention from distant tokens
        for j in range(min(3, i + 1)):  # Only check first few positions
            token = tokens[j].strip()
            if token in ['\n', '.'] and j <= 2:  # Early discourse boundary
                distance = i - j
                if distance > 5:  # For distant tokens
                    # Add significant boost that overcomes recency bias
                    attention[i, j] += 0.35

        # Recency bias - stronger attention to recent tokens
        for j in range(max(0, i - 10), i):
            distance = i - j
            recency_weight = 0.15 / (distance + 1)
            attention[i, j] += recency_weight

        # Boost attention to tokens at the start of sentences/clauses
        for j in range(i + 1):
            if j < len(token_to_spacy) and token_to_spacy[j]:
                spacy_idx = token_to_spacy[j][0]
                if spacy_idx < len(doc):
                    spacy_token = doc[spacy_idx]
                    # Check if this token starts a sentence
                    if j == 0 or (j > 0 and tokens[j-1].strip() in ['.', '\n', '!', '?']):
                        attention[i, j] += 0.15
                    # Attention to proper nouns and pronouns
                    if spacy_token.pos_ in ['PROPN', 'PRON']:
                        attention[i, j] += 0.08

        # Additional attention to semantically similar tokens
        for j in range(i + 1):
            if i != j:
                sim = _char_sim(tokens[i], tokens[j])
                if sim > 0.7:
                    attention[i, j] += 0.1 * sim

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L13H17", attention



def prog_L13H18(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Cross-sentence context integration head with enhanced sentence-initial attention."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L13H18", np.zeros((n_empty, n_empty)).reshape(0, 0)

    attention_matrix = np.zeros((n, n))

    # Find sentence boundaries (periods and newlines)
    sentence_boundaries = []
    for i, token in enumerate(tokens):
        if token.strip() in ['.', '\n']:
            sentence_boundaries.append(i)

    # Get spacy alignment for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        # Base uniform attention to all previous tokens
        for j in range(i + 1):
            attention_matrix[i, j] = 0.1

        # Strong attention to sentence boundaries
        for boundary_idx in sentence_boundaries:
            if boundary_idx <= i:
                attention_matrix[i, boundary_idx] += 2.0

        # Cross-sentence attention: attend to content from previous sentences
        current_sentence_start = 0
        for boundary_idx in sentence_boundaries:
            if boundary_idx < i:
                current_sentence_start = boundary_idx + 1

        # Attend to tokens from previous sentences with decay
        for j in range(current_sentence_start):
            if j < len(tokens):
                # Higher attention to content words from previous sentences
                if token_to_spacy[j]:
                    spacy_idx = token_to_spacy[j][0]
                    if spacy_idx < len(doc):
                        spacy_token = doc[spacy_idx]
                        if spacy_token.pos_ in ['NOUN', 'VERB', 'ADJ', 'PROPN']:
                            attention_matrix[i, j] += 1.5

                # Distance decay within previous sentences
                distance = i - j
                decay_factor = 1.0 / (1.0 + 0.1 * distance)
                attention_matrix[i, j] += 0.5 * decay_factor

        # Enhanced attention to first token - key fix for under-prediction
        if i > 0:
            # Strong attention to sentence beginning, especially for content words
            if token_to_spacy[i]:
                spacy_idx = token_to_spacy[i][0]
                if spacy_idx < len(doc):
                    spacy_token = doc[spacy_idx]
                    if spacy_token.pos_ in ['NOUN', 'VERB', 'ADJ', 'PROPN', 'PRON']:
                        attention_matrix[i, 0] += 1.5

            attention_matrix[i, 0] += 0.8

        # Self-attention boost
        attention_matrix[i, i] += 0.3

        # Semantic similarity boost for recent tokens
        for j in range(max(0, i-10), i):
            sim = _char_sim(tokens[i], tokens[j])
            if sim > 0.3:
                attention_matrix[i, j] += sim * 0.5

    # Apply causal mask and normalize
    attention_matrix = apply_causal_mask(attention_matrix)
    attention_matrix = make_row_stochastic(attention_matrix)

    return "prog_L13H18", attention_matrix



def prog_L13H19(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary and punctuation attention with strong beginning-of-sequence focus."""
    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        token_i = tokens[i]

        # Strong self-attention baseline
        attention[i, i] = 0.1

        for j in range(i + 1):  # Causal mask
            token_j = tokens[j]

            # Strong attention to the very first token from all positions
            if j == 0 and i > 0:
                attention[i, j] += 0.8

            # Very high attention to sentence-ending punctuation (reduced from original)
            elif token_j in ['.', '!', '?']:
                attention[i, j] += 1.0

            # High attention to newlines
            elif token_j == '\n':
                attention[i, j] += 1.0

            # Medium attention to other punctuation
            elif token_j in [',', ';', ':', '"', "'", '(', ')', '-']:
                attention[i, j] += 0.3

            # Semantic similarity bonus for content words
            if j != i and len(token_to_spacy[i]) > 0 and len(token_to_spacy[j]) > 0:
                spacy_i = doc[token_to_spacy[i][0]]
                spacy_j = doc[token_to_spacy[j][0]]

                # Boost for content words with semantic similarity
                if (spacy_i.pos_ in ['NOUN', 'VERB', 'ADJ', 'ADV'] and 
                    spacy_j.pos_ in ['NOUN', 'VERB', 'ADJ', 'ADV']):
                    sim = _char_sim(tokens[i], tokens[j])
                    if sim > 0.3:
                        attention[i, j] += sim * 0.4

                # Boost for syntactic relationships
                if spacy_i.head.i in token_to_spacy[j] or spacy_j.head.i in token_to_spacy[i]:
                    attention[i, j] += 0.2

            # Distance decay for non-punctuation and non-first-token
            if (token_j not in ['.', '!', '?', '\n', ',', ';', ':', '"', "'", '(', ')', '-'] 
                and j != 0):
                distance = i - j
                if distance > 0:
                    attention[i, j] *= (1.0 / (1.0 + distance * 0.1))

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L13H19", attention



def prog_L13H2(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary attention head with strong beginning-of-sequence attention."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L13H2", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        # Base self-attention
        attention[i, i] = 0.1

        # Strong attention to the first token from all positions
        if i > 0:
            attention[i, 0] = 0.6

        # Strong attention to periods and newlines
        for j in range(i + 1):
            if tokens[j].strip() in ['.', '\n']:
                attention[i, j] = 0.8

        # Medium attention to commas and other punctuation
        for j in range(i + 1):
            if tokens[j].strip() in [',', '!', '?', ';', ':']:
                attention[i, j] = 0.3

        # Attention from sentence-ending positions to sentence boundaries
        spacy_indices = token_to_spacy[i]
        if spacy_indices:
            spacy_token = doc[spacy_indices[0]]
            # If this token is at end of sentence or clause
            if spacy_token.is_sent_end or spacy_token.dep_ in ['ROOT']:
                for j in range(i + 1):
                    if tokens[j].strip() in ['.', '\n']:
                        attention[i, j] *= 2.0

        # Local attention patterns - attend to nearby tokens
        for j in range(max(0, i - 3), i):
            if tokens[j].strip() not in ['.', '\n', ',']:
                attention[i, j] += 0.15

        # Attention to pronouns and important function words
        for j in range(i + 1):
            if token_to_spacy[j]:
                spacy_token = doc[token_to_spacy[j][0]]
                if spacy_token.pos_ in ['PRON', 'DET'] or spacy_token.dep_ == 'nsubj':
                    attention[i, j] += 0.2

        # Special boost for tokens that follow sentence boundaries
        if i > 0 and tokens[i-1].strip() in ['.', '\n']:
            for j in range(i + 1):
                if tokens[j].strip() in ['.', '\n']:
                    attention[i, j] += 0.3

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L13H2", attention



def prog_L13H20(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary and structure detection head with focus on periods, newlines, and sentence starts."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention_matrix = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        # Self-attention baseline
        attention_matrix[i, i] = 0.1

        # Very high self-attention for first token
        if i == 0:
            attention_matrix[i, i] = 1.0
            continue

        # Strong attention to sentence boundaries (periods and newlines)
        for j in range(i + 1):
            token = tokens[j].strip()

            # High attention to periods
            if token == '.':
                attention_matrix[i, j] += 0.3

            # High attention to newlines
            elif token == '\n' or token.startswith('\n'):
                attention_matrix[i, j] += 0.35

            # Moderate attention to sentence start tokens (after periods/newlines)
            elif j > 0 and (tokens[j-1].strip() == '.' or tokens[j-1].strip() == '\n' or tokens[j-1].strip().startswith('\n')):
                attention_matrix[i, j] += 0.15

            # Lower attention to commas and other punctuation
            elif token in [',', '!', '?', ';', ':']:
                attention_matrix[i, j] += 0.05

        # Add some recency bias - more attention to recent tokens
        for j in range(max(0, i-5), i):
            attention_matrix[i, j] += 0.02 * (1.0 - (i - j) / 10.0)

        # Add syntactic dependencies using spacy
        if token_to_spacy[i]:
            spacy_idx = token_to_spacy[i][0]
            if spacy_idx < len(doc):
                spacy_token = doc[spacy_idx]

                # Attend to syntactic head
                if spacy_token.head != spacy_token:
                    head_idx = spacy_token.head.i
                    for j in range(i + 1):
                        if token_to_spacy[j] and head_idx in token_to_spacy[j]:
                            attention_matrix[i, j] += 0.08

    # Apply causal mask and normalize
    attention_matrix = apply_causal_mask(attention_matrix)
    attention_matrix = make_row_stochastic(attention_matrix)

    return "prog_L13H20", attention_matrix



def prog_L13H21(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Attention head that focuses on sentence boundaries, semantic relationships, and strongly on the beginning of text."""
    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        for j in range(i + 1):  # Causal mask
            weight = 0.0

            # Strong self-attention for first token
            if i == 0 and j == 0:
                weight = 1.0
            elif i == j:
                # Moderate self-attention for all tokens
                weight = 0.1
            else:
                # Strong attention to the very first token from all positions
                if j == 0:
                    # Boost attention to first token, stronger for later positions
                    weight += 0.4 + (i * 0.02)  # Increases with distance from start

                # Check if target token is sentence boundary
                if tokens[j] in ['.', '\n', '!', '?']:
                    weight += 0.3

                # Check if target is beginning of sentence/text
                if j == 0 or (j > 0 and tokens[j-1] in ['\n', '.', '!', '?']):
                    weight += 0.2

                # Semantic similarity boost
                sim = _char_sim(tokens[i], tokens[j])
                if sim > 0.3:
                    weight += sim * 0.4

                # Positional decay - prefer more recent tokens
                distance = i - j
                if distance > 0:
                    weight *= np.exp(-distance * 0.05)

                # Special attention patterns for certain relationships
                if token_to_spacy[i] and token_to_spacy[j]:
                    spacy_i_indices = token_to_spacy[i]
                    spacy_j_indices = token_to_spacy[j]

                    for si in spacy_i_indices:
                        for sj in spacy_j_indices:
                            if si < len(doc) and sj < len(doc):
                                spacy_i_token = doc[si]
                                spacy_j_token = doc[sj]

                                # Noun to modifier relationships
                                if (spacy_i_token.pos_ in ['NOUN', 'PROPN'] and 
                                    spacy_j_token.pos_ in ['ADJ', 'DET']):
                                    weight += 0.15

                                # Verb to subject/object relationships
                                if (spacy_i_token.dep_ in ['nsubj', 'dobj'] and 
                                    spacy_j_token.pos_ == 'VERB'):
                                    weight += 0.1

            attention[i, j] = weight

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L13H21", attention



def prog_L13H22(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Structural boundary and semantic similarity attention head."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L13H22", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    alignment = _align_to_spacy(sentence, tokens)

    for i in range(n):
        for j in range(i + 1):  # Causal mask
            weight = 0.0

            # High attention to structural boundaries
            if tokens[j] in ['\n', '.', '!', '?', ';']:
                weight += 0.4

            # Strong attention to first token
            if j == 0:
                weight += 0.3

            # Self-attention baseline
            if i == j:
                weight += 0.15

            # Adjacent token attention (especially previous token)
            if i == j + 1:
                weight += 0.2
            elif abs(i - j) == 1:
                weight += 0.1

            # Semantic similarity component
            sim = _char_sim(tokens[i], tokens[j])
            if sim > 0.7:
                weight += 0.3 * sim
            elif sim > 0.5:
                weight += 0.15 * sim

            # Syntactic relationships via spacy
            if alignment[i] and alignment[j]:
                spacy_i = alignment[i][0] if alignment[i] else None
                spacy_j = alignment[j][0] if alignment[j] else None

                if spacy_i is not None and spacy_j is not None and spacy_i < len(doc) and spacy_j < len(doc):
                    token_i = doc[spacy_i]
                    token_j = doc[spacy_j]

                    # Modifier relationships
                    if token_j in token_i.children or token_i in token_j.children:
                        weight += 0.2

                    # Same dependency head
                    if token_i.head == token_j.head and token_i.head != token_i:
                        weight += 0.1

            # Distance decay for non-special cases
            distance = i - j
            if distance > 0 and tokens[j] not in ['\n', '.', '!', '?'] and j != 0:
                decay = np.exp(-0.1 * distance)
                weight *= decay

            attention[i, j] = weight

    # Normalize and apply causal mask
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L13H22", attention



def prog_L13H23(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Attention head that focuses on sentence boundaries, newlines, and strong backward dependencies to sentence-initial and semantically related tokens."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L13H23", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        for j in range(i + 1):  # Causal mask

            # Perfect self-attention for first token
            if i == 0 and j == 0:
                attention[i, j] = 1.0
                continue

            # Strong attention to sentence-initial tokens (first few tokens)
            if j <= 2 and i > j + 3:
                attention[i, j] = 0.6
                continue

            # Strong attention to immediately preceding token for semantic continuity
            if j == i - 1:
                sim = _char_sim(tokens[i], tokens[j])
                if sim > 0.3:
                    attention[i, j] = 0.4
                else:
                    attention[i, j] = 0.2
                continue

            # High attention to newlines and periods
            if tokens[j] == '\n' or tokens[j] == '.':
                attention[i, j] = 0.3

            # High attention to sentence boundary punctuation
            elif tokens[j] in ['.', '!', '?']:
                attention[i, j] = 0.2

            # Semantic similarity boost
            elif j < i:
                sim = _char_sim(tokens[i], tokens[j])
                if sim > 0.7:  # High similarity threshold
                    attention[i, j] = 0.4
                elif sim > 0.5:  # Medium similarity
                    attention[i, j] = 0.2
                elif sim > 0.3:  # Low similarity
                    attention[i, j] = 0.1

            # Base attention with recency bias
            if j < i:
                distance = i - j
                base_attention = 0.05 / (1 + distance * 0.1)
                attention[i, j] += base_attention

            # Self-attention baseline
            if i == j:
                attention[i, j] += 0.1

            # Special boost for tokens at sentence starts
            if j > 0 and tokens[j-1] in ['.', '\n', '!', '?']:
                attention[i, j] *= 1.5

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L13H23", attention



def prog_L13H24(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Structural boundary and semantic similarity attention with strong sentence-initial bias."""
    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L13H24", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        for j in range(i + 1):  # Only attend to previous tokens (causal)
            weight = 0.0

            # Base recency weight - prefer recent tokens
            if i == j:
                weight += 0.15  # Reduced self-attention weight
            else:
                recency = 1.0 / (1.0 + (i - j) * 0.1)
                weight += recency * 0.2

            # Strong attention to sentence boundaries (periods, newlines)
            if tokens[j] in ['.', '\n', '!', '?']:
                weight += 0.8

            # Very strong attention to first token - this head has extreme sentence-initial bias
            if j == 0:
                # Much stronger boost for sentence-initial token, especially for later positions
                position_boost = 0.6 + (i * 0.03)  # Increases with distance from start
                weight += position_boost

            # Semantic similarity boost
            sim = _char_sim(tokens[i], tokens[j])
            if sim > 0.3:
                weight += sim * 0.4

            # Attention to punctuation and structural tokens
            if tokens[j] in [',', ':', ';', '"', "'", '(', ')', '[', ']']:
                weight += 0.3

            # Boost for tokens that are semantically related to sentence boundaries
            if len(token_to_spacy[j]) > 0:
                spacy_j = doc[token_to_spacy[j][0]]
                # Conjunctions and discourse markers
                if spacy_j.pos_ in ['CCONJ', 'SCONJ'] or spacy_j.dep_ in ['cc', 'mark']:
                    weight += 0.4
                # Sentence-initial words often get attention
                if spacy_j.is_sent_start:
                    weight += 0.3

            # Extra boost for embedding similarity with high-attention structural tokens
            for k in range(j):
                if tokens[k] in ['.', '\n'] and _char_sim(tokens[j], tokens[k]) > 0.2:
                    weight += 0.2
                    break

            attention[i, j] = weight

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L13H24", attention



def prog_L13H25(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Structural boundary detection head with strong first-token attention pattern."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    # Find structural tokens (newlines, periods, and first tokens)
    structural_tokens = set()
    for i, token in enumerate(tokens):
        if token.strip() in ['\n', '.', '!', '?']:
            structural_tokens.add(i)

    # Add first token as structural
    if n > 0:
        structural_tokens.add(0)

    for i in range(n):
        current_token = tokens[i].strip()

        # Base self-attention
        attention[i, i] = 0.3

        # Strong attention to structural tokens (newlines and periods)
        for j in structural_tokens:
            if j <= i:
                if tokens[j].strip() == '\n':
                    attention[i, j] += 0.4
                elif tokens[j].strip() in ['.', '!', '?']:
                    attention[i, j] += 0.3
                elif j == 0:  # first token
                    attention[i, j] += 0.2

        # NEW: Strong attention to first token for all tokens
        # This is the missing pattern from the failure cases
        if n > 0 and i > 0:
            # Stronger attention to first token, decaying with distance
            first_token_weight = 0.4 * (1.0 / (1 + 0.1 * i))
            attention[i, 0] += first_token_weight

        # If current token is structural, boost self-attention
        if i in structural_tokens:
            attention[i, i] += 0.3

        # Additional attention patterns for certain token types
        if current_token in [',', ';', ':']:
            # Punctuation tokens get some attention to nearby structural elements
            for j in range(max(0, i-5), i):
                if j in structural_tokens:
                    attention[i, j] += 0.1

        # Moderate attention to recent tokens (recency bias)
        for j in range(max(0, i-3), i):
            attention[i, j] += 0.05

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L13H25", attention



def prog_L13H26(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary attention head with strong beginning-of-sequence bias."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention_matrix = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        token = tokens[i]

        # Base attention weights
        for j in range(i + 1):  # Causal mask
            # Strong attention to periods and newlines
            if tokens[j] in ['.', '\n']:
                attention_matrix[i, j] += 0.5

            # Moderate attention to other punctuation
            elif tokens[j] in [',', '!', '?', ';', ':']:
                attention_matrix[i, j] += 0.2

            # Recency bias - recent tokens get higher weight
            distance = i - j
            if distance <= 5:
                attention_matrix[i, j] += 0.1 * (6 - distance) / 6

            # Sentence start tokens get attention
            if j == 0 or (j > 0 and tokens[j-1] in ['.', '\n', '!', '?']):
                attention_matrix[i, j] += 0.15

        # Strong beginning-of-sequence bias - all tokens attend heavily to token 0
        if i > 0:
            attention_matrix[i, 0] += 0.6

        # Special handling for different token types
        spacy_indices = token_to_spacy[i]
        if spacy_indices:
            spacy_token = doc[spacy_indices[0]]

            # Verbs attend more to sentence boundaries
            if spacy_token.pos_ in ['VERB']:
                for j in range(i + 1):
                    if tokens[j] in ['.', '\n']:
                        attention_matrix[i, j] += 0.2

            # Pronouns and names attend to sentence starts
            if spacy_token.pos_ in ['PRON', 'PROPN']:
                for j in range(i + 1):
                    if j == 0 or (j > 0 and tokens[j-1] in ['.', '\n']):
                        attention_matrix[i, j] += 0.1

        # Reduced self-attention baseline to avoid over-prediction
        attention_matrix[i, i] += 0.02

    # Apply causal mask and normalize
    attention_matrix = apply_causal_mask(attention_matrix)
    attention_matrix = make_row_stochastic(attention_matrix)

    return "prog_L13H26", attention_matrix



def prog_L13H27(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Punctuation and semantic similarity attention with cross-sentence patterns."""
    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L13H27", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    for i in range(n):
        token_i = tokens[i].strip()

        for j in range(i + 1):  # Causal mask
            token_j = tokens[j].strip()
            weight = 0.0

            # Strong attention to punctuation marks
            if token_j in ['.', '\n', '!', '?', ';', ':']:
                if token_j == '.' or token_j == '\n':
                    weight += 0.15
                else:
                    weight += 0.08

            # Self-attention baseline
            if i == j:
                weight += 0.03

            # Semantic similarity component
            sim = _char_sim(tokens[i], tokens[j])
            if sim > 0.3:
                weight += sim * 0.12

            # Distance decay for nearby tokens
            distance = i - j
            if distance <= 5:
                weight += max(0, 0.05 - distance * 0.01)

            # Boost for common function words attending to content
            if (token_i in ['and', 'to', 'the', 'of', 'in'] and 
                j < i - 1 and len(token_j) > 2):
                weight += 0.03

            # Special patterns for conjunctions
            if token_i == 'and' and distance == 1:
                weight += 0.08

            attention[i, j] = weight

    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L13H27", attention



def prog_L13H28(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Punctuation and boundary detection head with strong first-token attention bias."""
    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L13H28", np.zeros((n_empty, n_empty))

    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    attention = np.zeros((n, n))

    for i in range(n):
        for j in range(i + 1):  # Causal mask
            weight = 0.0

            # Strong attention to punctuation marks
            if tokens[j] in ['.', '\n', '!', '?', ',']:
                if tokens[j] in ['.', '\n']:
                    weight += 0.25  # Very high for periods and newlines
                else:
                    weight += 0.15  # High for other punctuation

            # Self-attention baseline
            if i == j:
                weight += 0.08

            # Enhanced first token attention - much stronger bias
            if j == 0:
                # Strong baseline for first token
                weight += 0.12

                # Additional strong first-token bias that decays with distance
                distance = i - j  # This is just i since j=0
                if distance <= 10:
                    # Much stronger first-token attention with slower decay
                    first_token_boost = 0.35 * (0.85 ** distance)
                    weight += first_token_boost
                else:
                    # Even distant tokens get some first-token attention
                    weight += 0.05

            # Recent token bias (exponential decay) - only for non-first tokens
            if j > 0:
                distance = i - j
                if distance <= 5:
                    recency_weight = 0.06 * (0.7 ** distance)
                    weight += recency_weight

            # Syntactic relationships using spacy
            if token_to_spacy[i] and token_to_spacy[j]:
                spacy_i = token_to_spacy[i][0] if token_to_spacy[i] else None
                spacy_j = token_to_spacy[j][0] if token_to_spacy[j] else None

                if spacy_i is not None and spacy_j is not None and spacy_i < len(doc) and spacy_j < len(doc):
                    spacy_token_i = doc[spacy_i]
                    spacy_token_j = doc[spacy_j]

                    # Modifier relationships
                    if spacy_token_j.head == spacy_token_i:
                        weight += 0.08

                    # Pronoun to recent noun
                    if spacy_token_i.pos_ == 'PRON' and spacy_token_j.pos_ in ['NOUN', 'PROPN'] and (i - j) <= 3:
                        weight += 0.06

                    # Verb to subject/object
                    if spacy_token_i.pos_ == 'VERB' and spacy_token_j.dep_ in ['nsubj', 'dobj']:
                        weight += 0.05

            # Embedding similarity for semantically related tokens
            if (i - j) <= 8:
                sim = _char_sim(tokens[i], tokens[j])
                if sim > 0.7:
                    weight += 0.04 * sim

            # Add small random baseline to avoid zeros
            weight += 0.01

            attention[i, j] = weight

    # Normalize and apply causal mask
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L13H28", attention



def prog_L13H29(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Discourse boundary and structural break detection head with emphasis on sentence/paragraph boundaries."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    alignment = _align_to_spacy(sentence, tokens)

    for i in range(n):
        token_i = tokens[i]

        # Strong attention to newlines and sentence boundaries
        for j in range(i + 1):
            token_j = tokens[j]

            # Very high attention to newlines
            if token_j == '\n':
                attention[i, j] += 0.25

            # High attention to sentence-ending punctuation
            elif token_j in ['.', '!', '?']:
                attention[i, j] += 0.15

            # Attention to commas and other punctuation marking boundaries
            elif token_j in [',', ';', ':']:
                attention[i, j] += 0.08

            # Attention to first token (beginning of discourse)
            elif j == 0:
                attention[i, j] += 0.1

            # Local attention to previous few tokens (recency)
            if i - j <= 3:
                attention[i, j] += 0.05 * (1 / (i - j + 1))

        # Find spacy tokens aligned with current LM token
        spacy_indices = alignment[i] if i < len(alignment) else []

        for spacy_idx in spacy_indices:
            if spacy_idx < len(doc):
                spacy_token = doc[spacy_idx]

                # Look for sentence/clause beginnings
                for j in range(i + 1):
                    spacy_j_indices = alignment[j] if j < len(alignment) else []
                    for spacy_j_idx in spacy_j_indices:
                        if spacy_j_idx < len(doc):
                            spacy_j_token = doc[spacy_j_idx]

                            # Attention to sentence starts
                            if spacy_j_token.is_sent_start:
                                attention[i, j] += 0.08

                            # Attention to clause boundaries (subordinating conjunctions, etc.)
                            if spacy_j_token.pos_ in ['SCONJ', 'CCONJ'] and spacy_j_token.dep_ == 'mark':
                                attention[i, j] += 0.06

        # Add semantic similarity component for structurally important words
        for j in range(i + 1):
            if tokens[j] not in ['\n', '.', ',', '!', '?', ';', ':']:
                sim = _char_sim(tokens[i], tokens[j])
                if sim > 0.7:  # High semantic similarity
                    attention[i, j] += 0.04 * sim

        # Self-attention
        attention[i, i] += 0.05

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L13H29", attention



def prog_L13H3(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary and structural anchor head with strong attention to sentence/clause beginnings."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L13H3", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Find sentence/clause beginning positions
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    sentence_starts = set()
    for i, spacy_indices in enumerate(token_to_spacy):
        if spacy_indices:
            spacy_token = doc[spacy_indices[0]]
            # Token starts a sentence if it begins with capital or follows sentence punctuation
            if (spacy_token.is_sent_start or 
                (i > 0 and any(tokens[j].strip() in ['.', '!', '?'] for j in range(max(0, i-3), i))) or
                (i == 0) or
                (i > 0 and tokens[i-1].strip() == '\n')):
                sentence_starts.add(i)

    # Always include position 0 as a sentence start
    sentence_starts.add(0)

    for i in range(n):
        current_token = tokens[i].strip()

        # Reduced self-attention for all tokens (original was too high)
        attention[i, i] = 0.15

        # High attention to periods and sentence boundaries
        for j in range(i + 1):
            target_token = tokens[j].strip()

            # Very high attention to period tokens
            if target_token == '.':
                attention[i, j] += 0.4

            # High attention to newlines, especially from later tokens
            elif target_token == '\n':
                # Stronger for tokens further from the newline
                distance_factor = min(1.0, (i - j) / 10.0)
                attention[i, j] += 0.2 + 0.1 * distance_factor

            # Strong attention to sentence/clause beginnings
            elif j in sentence_starts:
                # Very strong attention to sentence starts, especially the first token
                base_attention = 0.6 if j == 0 else 0.4
                # Decay with distance but maintain strong connection
                distance_decay = max(0.3, 1.0 - (i - j) * 0.05)
                attention[i, j] += base_attention * distance_decay

            # Small boost for punctuation
            elif target_token in [',', '!', '?', '"', "'", ':', ';']:
                attention[i, j] += 0.05

        # Additional attention based on semantic similarity
        for j in range(i + 1):
            if i != j:  # Don't double-count self-attention
                sim = _char_sim(tokens[i], tokens[j])
                if sim > 0.7:  # High semantic similarity
                    attention[i, j] += 0.1 * sim

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L13H3", attention



def prog_L13H30(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary and first-token attention head with strong newline attention."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L13H30", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        # Strong attention to first token
        attention[i, 0] = 0.4

        # Very strong attention to periods and newlines
        for j in range(i + 1):
            token_j = tokens[j].strip()
            if token_j == '.':
                attention[i, j] += 0.5
            elif token_j == '\n' or token_j.startswith('\n'):
                attention[i, j] += 0.4

        # NEW: Additional strong attention to newline tokens as structural markers
        for j in range(i + 1):
            token_j = tokens[j]
            if '\n' in token_j:
                # Boost attention to newlines significantly, especially from distant tokens
                distance = i - j + 1
                if distance > 5:
                    attention[i, j] += 0.35
                else:
                    attention[i, j] += 0.25

        # Find sentence-ending tokens and give them high attention
        for j in range(i + 1):
            if token_to_spacy[j]:
                spacy_indices = token_to_spacy[j]
                for spacy_idx in spacy_indices:
                    if spacy_idx < len(doc):
                        spacy_token = doc[spacy_idx]
                        # High attention to sentence-final punctuation
                        if spacy_token.is_sent_end or (spacy_token.pos_ == 'PUNCT' and spacy_token.text in '.!?'):
                            attention[i, j] += 0.3

        # Moderate attention to nearby tokens (recency bias)
        for j in range(max(0, i-5), i + 1):
            distance = i - j + 1
            attention[i, j] += 0.1 / distance

        # Self attention baseline
        attention[i, i] += 0.1

        # Small attention to all previous tokens as baseline
        for j in range(i + 1):
            attention[i, j] += 0.01

    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L13H30", attention



def prog_L13H31(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence structure and punctuation boundary attention head with strong beginning-of-sequence attention."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        query_token = tokens[i]

        # Get spacy info for query token
        query_spacy_indices = token_to_spacy[i]
        query_spacy_tokens = [doc[idx] for idx in query_spacy_indices if idx < len(doc)]

        for j in range(i + 1):  # Causal mask
            key_token = tokens[j]

            # Strong attention to punctuation marks (reduced from original)
            if key_token.strip() in ['.', ',', '!', '?', ';', ':']:
                attention[i, j] += 0.15  # Reduced from 0.3

            # Strong attention to newlines
            if key_token.strip() == '\n' or key_token == '\n':
                attention[i, j] += 0.25

            # Much stronger attention to the very first token
            if j == 0:
                attention[i, j] += 0.4  # Increased from 0.1

            # Moderate attention to sentence beginnings (first token after newline/start)
            elif j > 0 and (tokens[j-1].strip() == '\n' or tokens[j-1] == '\n'):
                attention[i, j] += 0.15

            # Self-attention (reduced from original)
            if i == j:
                attention[i, j] += 0.02  # Reduced from 0.05

            # Attention based on semantic similarity
            if i != j:
                sim = _char_sim(tokens[i], tokens[j])
                if sim > 0.7:
                    attention[i, j] += 0.1 * sim

            # Special attention patterns for specific structural elements
            key_spacy_indices = token_to_spacy[j]
            key_spacy_tokens = [doc[idx] for idx in key_spacy_indices if idx < len(doc)]

            # Attention to conjunctions and determiners
            if key_spacy_tokens:
                key_pos = key_spacy_tokens[0].pos_
                if key_pos in ['CCONJ', 'DET']:
                    attention[i, j] += 0.08

            # Distance-based decay for non-structural tokens (but preserve first token attention)
            distance = i - j
            if distance > 0 and not (key_token.strip() in ['.', ',', '\n'] or key_token == '\n') and j != 0:
                decay = np.exp(-distance * 0.1)
                attention[i, j] *= (0.5 + 0.5 * decay)

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L13H31", attention



def prog_L13H4(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Attention head that combines self-attention, first-token attention, and sentence boundary detection with enhanced structural awareness."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L13H4", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    # Identify sentence boundaries (periods, exclamation marks, question marks)
    sentence_ends = []
    newlines = []
    for i, token in enumerate(tokens):
        if token.strip() in ['.', '!', '?']:
            sentence_ends.append(i)
        elif token.strip() == '\n':
            newlines.append(i)

    for i in range(n):
        for j in range(i + 1):  # Causal mask
            if i == j:
                # Strong self-attention
                attention[i, j] = 1.0
            elif j == 0:
                # Enhanced attention to first token - stronger for later tokens
                base_first_attention = 0.4
                # Increase first-token attention based on position
                position_boost = min(0.3, i * 0.03)
                attention[i, j] = base_first_attention + position_boost
            elif j in sentence_ends:
                # Attention to sentence-ending punctuation
                attention[i, j] = 0.2
            elif j in newlines:
                # Enhanced attention to newline tokens - stronger for distant tokens
                base_newline_attention = 0.25
                # Boost newline attention for tokens far from the newline
                distance_boost = min(0.15, (i - j) * 0.01)
                attention[i, j] = base_newline_attention + distance_boost
            elif j == i - 1:
                # Some attention to previous token
                attention[i, j] = 0.05
            else:
                # Low baseline attention
                attention[i, j] = 0.01

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L13H4", attention



def prog_L13H5(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Discourse structure and sentence boundary attention head with strong first-token bias."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L13H5", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        token_i = tokens[i]

        # Base attention scores
        for j in range(i + 1):  # Causal mask
            token_j = tokens[j]
            score = 0.0

            # Strong first-token bias (position 0)
            if j == 0:
                score += 0.4

            # Strong attention to newlines and sentence boundaries
            if token_j.strip() == '\n':
                score += 0.3
            elif token_j.strip() in ['.', '!', '?']:
                score += 0.25

            # Self-attention baseline
            if i == j:
                score += 0.05

            # Previous token attention
            if j == i - 1:
                score += 0.15

            # Attention to tokens that are sentence/clause starters
            if j > 0 and tokens[j-1].strip() in ['\n', '.', '!', '?']:
                score += 0.2

            # Add syntactic relationships using spacy alignment
            if token_to_spacy[i] and token_to_spacy[j]:
                spacy_i = token_to_spacy[i][0] if token_to_spacy[i] else None
                spacy_j = token_to_spacy[j][0] if token_to_spacy[j] else None

                if spacy_i is not None and spacy_j is not None and spacy_i < len(doc) and spacy_j < len(doc):
                    spacy_tok_i = doc[spacy_i]
                    spacy_tok_j = doc[spacy_j]

                    # Modifier to head relationships
                    if spacy_tok_j.head == spacy_tok_i or spacy_tok_i.head == spacy_tok_j:
                        score += 0.1

                    # Named entities to their components
                    if spacy_tok_i.ent_type_ and spacy_tok_j.ent_type_ and spacy_tok_i.ent_type_ == spacy_tok_j.ent_type_:
                        score += 0.08

            # Distance decay for non-special tokens
            if j != 0 and token_j.strip() not in ['\n', '.', '!', '?']:
                distance = i - j
                if distance > 1:
                    score *= 0.9 ** (distance - 1)

            attention[i, j] = score

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L13H5", attention



def prog_L13H6(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Newline and punctuation attention head with strong first-token attention for content words."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    for i in range(n):
        query_token = tokens[i]

        for j in range(i + 1):  # causal mask
            key_token = tokens[j]

            # Very high attention to newline tokens
            if key_token.strip() == '' and '\n' in key_token:
                attention[i, j] = 10.0

            # High attention to period tokens
            elif key_token == '.':
                attention[i, j] = 5.0

            # Strong first token attention for content words
            elif j == 0:
                # Check if query token is a content word (not pure punctuation/whitespace)
                if (len(query_token.strip()) > 0 and 
                    not query_token in '.,!?;:' and 
                    query_token.strip() != ''):
                    attention[i, j] = 6.0  # Much higher than original 2.0
                else:
                    attention[i, j] = 2.0  # Keep original for non-content tokens

            # Self-attention
            elif i == j:
                attention[i, j] = 1.5

            # Semantic similarity component for content words
            else:
                # Check if both tokens are likely content words (not pure punctuation/whitespace)
                if (len(query_token.strip()) > 0 and 
                    len(key_token.strip()) > 0 and 
                    not query_token in '.,!?;:' and 
                    not key_token in '.,!?;:'):

                    sim = _char_sim(tokens[i], tokens[j])
                    if sim > 0.7:  # High semantic similarity
                        attention[i, j] = 3.0
                    elif sim > 0.5:  # Moderate semantic similarity
                        attention[i, j] = 1.0
                    else:
                        attention[i, j] = 0.1
                else:
                    attention[i, j] = 0.1

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L13H6", attention



def prog_L13H7(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Document structure attention head focusing on first content words after sentence boundaries."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L13H7", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    # Identify first content words after sentence boundaries
    first_content_words = set()

    # First token is always considered if it's a content word
    if token_to_spacy[0]:
        spacy_idx = token_to_spacy[0][0]
        if spacy_idx < len(doc) and doc[spacy_idx].pos_ in ['NOUN', 'VERB', 'ADJ', 'ADV', 'PROPN']:
            first_content_words.add(0)

    # Find first content word after each sentence boundary
    for i in range(1, n):
        # Check if previous token was a sentence boundary
        prev_is_boundary = (tokens[i-1] in ['.', '\n'] or 
                           (i >= 2 and tokens[i-2] == '.' and tokens[i-1] in [' ', '\n', '"']))

        if prev_is_boundary and token_to_spacy[i]:
            spacy_idx = token_to_spacy[i][0]
            if spacy_idx < len(doc) and doc[spacy_idx].pos_ in ['NOUN', 'VERB', 'ADJ', 'ADV', 'PROPN']:
                first_content_words.add(i)

    for i in range(n):
        # Strong attention to newlines
        for j in range(i + 1):
            if tokens[j] == '\n':
                attention[i, j] += 0.4

        # Strong attention to periods (sentence boundaries)
        for j in range(i + 1):
            if tokens[j] == '.':
                attention[i, j] += 0.3

        # High attention to first token
        if i > 0:
            attention[i, 0] += 0.2

        # NEW: Strong attention to first content words after sentence boundaries
        for j in first_content_words:
            if j <= i and j != i:  # Can't attend to future tokens or self here
                attention[i, j] += 0.35

        # Self-attention
        attention[i, i] += 0.1

        # Attention to previous token
        if i > 0:
            attention[i, i-1] += 0.08

        # Linguistic similarity attention
        if token_to_spacy[i]:
            spacy_i = token_to_spacy[i][0]
            current_token = doc[spacy_i]

            for j in range(i):
                if token_to_spacy[j]:
                    spacy_j = token_to_spacy[j][0]
                    target_token = doc[spacy_j]

                    # Syntactic relationship bonus
                    if (target_token.head == current_token or 
                        current_token.head == target_token or
                        target_token.head == current_token.head):
                        attention[i, j] += 0.06

                    # Semantic similarity bonus
                    sim = _char_sim(tokens[i], tokens[j])
                    if sim > 0.7:
                        attention[i, j] += 0.04 * sim

        # Special attention to punctuation marks
        for j in range(i + 1):
            if tokens[j] in [',', '!', '?', ';', ':']:
                attention[i, j] += 0.05

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L13H7", attention



def prog_L13H8(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary and structure detection head with focus on first tokens and punctuation."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L13H8", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        token = tokens[i]

        # Strong self-attention for first token
        if i == 0:
            attention[i, i] = 1.0
            continue

        # High attention to structural markers
        for j in range(i + 1):
            target_token = tokens[j]

            # Very high attention to newlines and periods
            if target_token.strip() in ['\n', '.']:
                attention[i, j] += 0.4

            # High attention to first token from most positions
            if j == 0:
                attention[i, j] += 0.3

            # Self-attention for punctuation
            if token.strip() in ['.', ',', '!', '?', ';', ':'] and i == j:
                attention[i, j] += 0.2

            # Moderate attention to immediate previous token
            if j == i - 1:
                attention[i, j] += 0.1

            # Attention to other punctuation marks
            if target_token.strip() in [',', '!', '?', ';', ':', '"', "'", '(', ')']:
                attention[i, j] += 0.15

            # Boost for tokens that start sentences (after periods/newlines)
            if j > 0 and j < len(tokens) - 1:
                prev_token = tokens[j-1].strip()
                if prev_token in ['.', '\n', '!', '?'] and target_token.strip():
                    attention[i, j] += 0.2

            # Small attention to content words based on embedding similarity
            if len(token_to_spacy[i]) > 0 and len(token_to_spacy[j]) > 0:
                spacy_i = token_to_spacy[i][0]
                spacy_j = token_to_spacy[j][0]
                if spacy_i < len(doc) and spacy_j < len(doc):
                    tok_i = doc[spacy_i]
                    tok_j = doc[spacy_j]
                    if tok_i.pos_ in ['NOUN', 'VERB', 'ADJ'] and tok_j.pos_ in ['NOUN', 'VERB', 'ADJ']:
                        sim = _char_sim(tokens[i], tokens[j])
                        if sim > 0.3:
                            attention[i, j] += 0.1 * sim

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L13H8", attention



def prog_L13H9(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Previous-token attention head with strong sentence-initial token attention."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L13H9", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    for i in range(n):
        # Strong attention to immediately previous token
        if i > 0:
            attention[i, i - 1] = 0.6

        # Moderate attention to tokens with high semantic similarity
        for j in range(i + 1):
            if j != i - 1:  # Don't double-count previous token
                sim = _char_sim(tokens[i], tokens[j])
                if sim > 0.7:
                    attention[i, j] += 0.3 * sim

        # Additional attention to sentence boundaries and punctuation
        for j in range(i + 1):
            token_j = tokens[j]
            if token_j in ['.', '\n', ',']:
                attention[i, j] += 0.2

        # Small baseline self-attention
        attention[i, i] += 0.05

        # Enhanced attention to first token - this is the key missing pattern
        if i > 0:
            attention[i, 0] += 0.3  # Increased from 0.1 to 0.4 total (0.1 baseline + 0.3 boost)

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L13H9", attention



def prog_L14H0(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Structural boundary attention head focusing on sentence boundaries and first tokens."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L14H0", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Parse with spacy for sentence boundaries
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    # Identify sentence boundary tokens (periods, newlines, exclamation marks, question marks)
    boundary_tokens = set()
    newline_tokens = set()
    for i, token in enumerate(tokens):
        if token.strip() in ['.', '!', '?', '\n']:
            boundary_tokens.add(i)
        if token.strip() == '\n':
            newline_tokens.add(i)

    # Identify first token (always position 0)
    first_token = 0

    for i in range(n):
        for j in range(i + 1):  # Causal mask
            weight = 0.0

            # Very high attention to first token from many positions
            if j == first_token and i != j:
                weight += 0.3

            # High attention to sentence boundaries
            if j in boundary_tokens:
                weight += 0.4

            # Special case: Strong attention to newlines from distant positions
            if j in newline_tokens and i - j > 5:
                weight += 0.6

            # Self-attention baseline
            if i == j:
                weight += 0.1

            # Local attention to previous token
            if j == i - 1:
                weight += 0.05

            # Boost attention from tokens that are part of certain linguistic patterns
            if token_to_spacy[i]:
                spacy_token = doc[token_to_spacy[i][0]]
                # Content words tend to attend more to boundaries
                if spacy_token.pos_ in ['NOUN', 'VERB', 'ADJ']:
                    if j in boundary_tokens:
                        weight += 0.2
                    elif j == first_token:
                        weight += 0.15

            # Distance decay for non-boundary attention (but not for newlines)
            if j not in boundary_tokens and j != first_token:
                distance = i - j
                if distance > 0:
                    weight *= (0.8 ** (distance - 1))

            # Reduce attention to periods that aren't newlines
            if j in boundary_tokens and tokens[j].strip() == '.' and j not in newline_tokens:
                weight *= 0.7

            attention[i, j] = weight

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L14H0", attention



def prog_L14H1(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Structural boundary detection head with self-attention, sentence-ending focus, and strong beginning-of-sequence attention."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    # Get spacy alignment for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        for j in range(i + 1):  # causal mask
            weight = 0.0

            # Strong self-attention
            if i == j:
                weight += 0.3

            # High attention to sentence-ending punctuation
            if tokens[j] in ['.', '!', '?']:
                weight += 0.4

            # High attention to line breaks/newlines
            if tokens[j] in ['\n', '\n\n']:
                weight += 0.3

            # Attention to first token of document/segments
            if j == 0:
                weight += 0.2

            # ADDED: Strong beginning-of-sequence attention - tokens attend heavily to first token
            if j == 0 and i > 0:
                # Distance-based decay for first token attention, but much stronger than original
                distance = i
                weight += 0.5 * np.exp(-distance / 15.0)

            # Attention to tokens immediately after line breaks
            if j > 0 and tokens[j-1] in ['\n', '\n\n']:
                weight += 0.15

            # Local syntactic patterns - attend to previous token
            if j == i - 1:
                weight += 0.1

            # Attend to commas (minor boundaries)
            if tokens[j] == ',':
                weight += 0.1

            # Cross-sentence attention - tokens in later sentences attend to earlier sentence endings
            if i > j + 5:  # some distance apart
                if tokens[j] in ['.', '\n']:
                    weight += 0.15

            # Boost attention for similar tokens (using embedding similarity)
            if i != j and _char_sim(tokens[i], tokens[j]) > 0.7:
                weight += 0.1

            # Special attention patterns for specific linguistic relationships
            if len(token_to_spacy[i]) > 0 and len(token_to_spacy[j]) > 0:
                spacy_i = doc[token_to_spacy[i][0]]
                spacy_j = doc[token_to_spacy[j][0]]

                # Complement relationships (that-clauses, etc.)
                if spacy_j.dep_ in ['mark', 'complm'] and j < i:
                    weight += 0.08

                # Conjunction relationships
                if spacy_j.dep_ == 'cc' and j < i:
                    weight += 0.06

            # Add small recency bias
            if j < i:
                distance = i - j
                weight += 0.05 * np.exp(-distance / 10.0)

            attention[i, j] = weight

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L14H1", attention



def prog_L14H10(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary and punctuation attention head with strong first-token focus."""
    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L14H10", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Get spacy alignment for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        token = tokens[i]

        # Reduced self-attention for certain tokens
        attention[i, i] = 0.15

        # Strong attention to sentence boundaries (periods and newlines)
        for j in range(i + 1):
            target_token = tokens[j]

            # Very high attention to periods and newlines
            if target_token.strip() in ['.', '\n']:
                attention[i, j] += 0.3

            # Medium attention to other punctuation
            elif target_token.strip() in [',', '!', '?', '"', "'", ':']:
                attention[i, j] += 0.1

            # Strong attention to first token in sentence - this is the key pattern
            if j == 0:
                attention[i, j] += 0.6

            # Distance-based decay for general content
            if j < i:
                distance = i - j
                decay = 1.0 / (1 + distance * 0.1)
                attention[i, j] += 0.05 * decay

        # Special boost for tokens that are sentence starters or follow punctuation
        if i > 0 and tokens[i-1].strip() in ['.', '\n', '!', '?']:
            attention[i, i] += 0.2

        # Boost attention to recent sentence boundaries
        for j in range(max(0, i-10), i):
            if tokens[j].strip() in ['.', '\n']:
                attention[i, j] += 0.15

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L14H10", attention



def prog_L14H11(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary and punctuation structure head with syntactic dependency attention."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L14H11", np.zeros((n_empty, n_empty))

    attention_matrix = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        token = tokens[i]

        # Strong attention to newlines and periods
        for j in range(i + 1):
            target_token = tokens[j]

            # Very high attention to newlines
            if target_token == '\n':
                attention_matrix[i, j] = 0.8
            # High attention to periods
            elif target_token == '.':
                attention_matrix[i, j] = 0.6
            # Moderate attention to other punctuation
            elif target_token in [',', '!', '?', ';', ':']:
                attention_matrix[i, j] = 0.3

        # First token after newline gets very high attention to the newline
        if i > 0 and tokens[i-1] == '\n':
            for j in range(i):
                if tokens[j] == '\n':
                    attention_matrix[i, j] = 0.9

        # Tokens immediately following punctuation attend strongly to that punctuation
        if i > 0 and tokens[i-1] in ['.', '!', '?', '\n']:
            attention_matrix[i, i-1] = 0.7

        # Self-attention baseline
        attention_matrix[i, i] = 0.1

        # Enhanced syntactic dependencies using spacy
        if token_to_spacy[i]:
            spacy_idx = token_to_spacy[i][0]
            if spacy_idx < len(doc):
                spacy_token = doc[spacy_idx]

                # Strong attention to syntactic head for verbs and content words
                if spacy_token.head != spacy_token:
                    head_token = spacy_token.head
                    for j in range(i):
                        if token_to_spacy[j] and head_token.i in token_to_spacy[j]:
                            # Higher attention for verbs to their subjects/objects
                            if spacy_token.pos_ in ['VERB', 'AUX'] or spacy_token.dep_ in ['nsubj', 'dobj', 'pobj']:
                                attention_matrix[i, j] = 0.4
                            else:
                                attention_matrix[i, j] = 0.2

                # Strong attention for auxiliary verbs and modal verbs to main verbs
                if spacy_token.pos_ in ['AUX', 'VERB'] and spacy_token.dep_ in ['aux', 'auxpass']:
                    for child in spacy_token.head.children:
                        if child.pos_ == 'VERB':
                            for j in range(i):
                                if token_to_spacy[j] and child.i in token_to_spacy[j]:
                                    attention_matrix[i, j] = 0.5

                # Enhanced modifier attention
                for child in spacy_token.children:
                    for j in range(i):
                        if token_to_spacy[j] and child.i in token_to_spacy[j]:
                            # Higher attention for important dependencies
                            if child.dep_ in ['nsubj', 'dobj', 'amod', 'advmod']:
                                attention_matrix[i, j] = 0.25
                            else:
                                attention_matrix[i, j] = 0.15

        # Reduce over-emphasis on punctuation for non-structural tokens
        if token_to_spacy[i]:
            spacy_idx = token_to_spacy[i][0]
            if spacy_idx < len(doc):
                spacy_token = doc[spacy_idx]
                # Content words should attend less strongly to distant punctuation
                if spacy_token.pos_ in ['NOUN', 'VERB', 'ADJ', 'ADV'] and i > 3:
                    for j in range(i - 3):
                        if tokens[j] in ['.', ',', '\n']:
                            attention_matrix[i, j] *= 0.5

        # Additional attention to sentence beginnings and key structural words
        for j in range(i + 1):
            target_token = tokens[j]

            # Moderate attention to first token
            if j == 0:
                attention_matrix[i, j] += 0.2

            # Some attention to tokens that start new sentences/clauses
            if j > 0 and tokens[j-1] in ['.', '\n', '!', '?']:
                attention_matrix[i, j] += 0.1

    # Apply causal mask and normalize
    attention_matrix = apply_causal_mask(attention_matrix)
    attention_matrix = make_row_stochastic(attention_matrix)

    return "prog_L14H11", attention_matrix



def prog_L14H12(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Syntactic boundary detection head with strong beginning-of-sequence attention."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        token = tokens[i]

        # Strong self-attention for punctuation
        if token.strip() in '.!?,:;':
            attention[i, i] = 0.8
        else:
            attention[i, i] = 0.1

        # High attention to sentence-ending punctuation
        for j in range(i):
            target_token = tokens[j]

            if target_token.strip() in '.!?':
                attention[i, j] = 0.3
            elif target_token.strip() == '\n':
                attention[i, j] = 0.25
            elif target_token.strip() in ',:;':
                attention[i, j] = 0.15

        # Get spacy information for current token
        spacy_indices = token_to_spacy[i]
        if spacy_indices:
            current_spacy = doc[spacy_indices[0]]

            # Look for syntactic relationships
            for j in range(i):
                target_spacy_indices = token_to_spacy[j]
                if target_spacy_indices:
                    target_spacy = doc[target_spacy_indices[0]]

                    # Attention between syntactically related tokens
                    if target_spacy.head == current_spacy or current_spacy.head == target_spacy:
                        attention[i, j] += 0.1

                    # Attention within same sentence
                    if target_spacy.sent == current_spacy.sent:
                        attention[i, j] += 0.05

        # NEW: Strong attention to beginning-of-sequence content tokens
        # Skip whitespace and find first few meaningful tokens
        for j in range(min(i, 4)):  # Look at first few positions
            target_token = tokens[j]
            if target_token.strip() and target_token.strip() not in '\n ':
                # Strong attention to early content tokens
                beginning_weight = 0.4 * (1.0 - j * 0.1)  # Decay slightly with position
                attention[i, j] += beginning_weight

        # Recency bias - higher attention to more recent tokens
        for j in range(max(0, i-5), i):
            recency_weight = 0.1 * (1.0 - (i-j)/6.0)
            attention[i, j] += recency_weight

        # Boost attention based on token similarity
        for j in range(i):
            similarity = _char_sim(tokens[i], tokens[j])
            if similarity > 0.7:
                attention[i, j] += 0.08 * similarity

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L14H12", attention



def prog_L14H13(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary and structural marker attention head."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention_matrix = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        # Get spacy tokens aligned to this position
        spacy_indices = token_to_spacy[i]
        current_token = tokens[i]

        for j in range(i + 1):  # Only attend to previous tokens (causal)
            target_token = tokens[j]

            # Base attention
            attention_weight = 0.01

            # Strong attention to sentence boundaries and structural markers
            if target_token.strip() in ['.', '!', '?', '\n']:
                attention_weight += 0.15

            # High attention to first token
            if j == 0:
                attention_weight += 0.4

            # Self-attention
            if i == j:
                attention_weight += 0.05

            # Attention to punctuation marks
            if target_token.strip() in [',', ';', ':', '"', "'", '(', ')', '-']:
                attention_weight += 0.08

            # Check for sentence endings followed by new content
            if j > 0 and tokens[j-1].strip() in ['.', '!', '?'] and target_token.strip() == '\n':
                attention_weight += 0.2

            # Attention between related content words using embedding similarity
            if (spacy_indices and len(spacy_indices) > 0 and 
                j < len(token_to_spacy) and token_to_spacy[j]):

                current_spacy = spacy_indices[0] if spacy_indices else None
                target_spacy = token_to_spacy[j][0] if token_to_spacy[j] else None

                if (current_spacy is not None and target_spacy is not None and
                    current_spacy < len(doc) and target_spacy < len(doc)):

                    current_pos = doc[current_spacy].pos_
                    target_pos = doc[target_spacy].pos_

                    # Boost attention for content words
                    if (current_pos in ['NOUN', 'VERB', 'ADJ', 'ADV'] and 
                        target_pos in ['NOUN', 'VERB', 'ADJ', 'ADV']):
                        sim = _char_sim(tokens[i], tokens[j])
                        attention_weight += max(0, sim * 0.1)

            # Recency bias - closer tokens get slightly more attention
            if i > j:
                distance = i - j
                if distance <= 5:
                    attention_weight += 0.02 / distance

            attention_matrix[i, j] = attention_weight

    # Apply causal mask and normalize
    attention_matrix = apply_causal_mask(attention_matrix)
    attention_matrix = make_row_stochastic(attention_matrix)

    return "prog_L14H13", attention_matrix



def prog_L14H14(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary detection head that attends to periods, newlines, section breaks, and segment-starting tokens."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L14H14", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    alignment = _align_to_spacy(sentence, tokens)

    # Identify segment-starting tokens (tokens that begin new contexts/quotes)
    segment_starters = set()
    for i in range(n):
        token = tokens[i].strip()

        # Check if this token starts after certain boundaries
        if i > 0:
            prev_token = tokens[i-1].strip()
            # After quotes, newlines, or sentence endings
            if (prev_token.endswith('"') or prev_token == '\n' or 
                prev_token.startswith('\n') or prev_token.endswith('.') or
                prev_token.endswith('!') or prev_token.endswith('?')):
                segment_starters.add(i)
        else:
            # First token is always a segment starter
            segment_starters.add(i)

    for i in range(n):
        token = tokens[i].strip()

        # Strong attention to periods and newlines (sentence boundaries)
        for j in range(i + 1):
            target_token = tokens[j].strip()

            # Very high attention to periods
            if target_token == '.':
                attention[i, j] += 0.3

            # High attention to newlines (section breaks)
            elif target_token == '\n' or target_token.startswith('\n'):
                attention[i, j] += 0.2

            # Moderate attention to other punctuation
            elif target_token in [',', '!', '?', ';', ':']:
                attention[i, j] += 0.1

        # NEW: Strong attention to segment-starting tokens
        for j in range(i + 1):
            if j in segment_starters:
                # Very strong attention to tokens that start new segments
                attention[i, j] += 0.4

        # Positional biases
        for j in range(i + 1):
            # Attention to first few tokens of sentence
            if j < 3:
                attention[i, j] += 0.05

            # Self-attention
            if i == j:
                attention[i, j] += 0.02

            # Recency bias for nearby tokens
            if i - j <= 5:
                attention[i, j] += 0.01 * (6 - (i - j)) / 6

        # Linguistic patterns - attend to sentence-level structures
        if i < len(alignment) and alignment[i]:
            spacy_indices = alignment[i]
            for spacy_idx in spacy_indices:
                if spacy_idx < len(doc):
                    spacy_token = doc[spacy_idx]

                    # Look for sentence-final words
                    if spacy_token.is_sent_end:
                        for j in range(i + 1):
                            if tokens[j].strip() in ['.', '\n'] or tokens[j].strip().startswith('\n'):
                                attention[i, j] += 0.15

        # Base uniform attention to avoid zero rows
        for j in range(i + 1):
            attention[i, j] += 0.001

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L14H14", attention



def prog_L14H15(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary attention head with strong first-token attention - attends strongly to periods, newlines, and especially the sentence beginning."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L14H15", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    for i in range(n):
        for j in range(i + 1):  # causal mask
            weight = 0.001  # base weight

            # Very strong attention to periods and newlines (sentence boundaries)
            if tokens[j] in ['.', '\n']:
                weight += 2.0

                # Extra boost if query is near start of sentence/paragraph
                if i < 5 or (i > 0 and tokens[i-1] == '\n'):
                    weight += 1.0

            # Strong attention to first token
            if j == 0:
                weight += 0.8

                # TARGETED FIX: Much stronger boost for first token attention
                # when query token is beyond early positions
                if i > 3:
                    weight += 2.5

            # Self-attention boost
            if i == j:
                weight += 0.3

            # Recency bias - prefer recent tokens
            distance = i - j
            if distance <= 3:
                weight += 0.2 / (distance + 1)

            # Boost for punctuation marks
            if tokens[j] in [',', '!', '?', '"', "'", ';', ':']:
                weight += 0.5

            # Special boost for whitespace tokens
            if tokens[j].strip() == '':
                weight += 0.3

            attention[i, j] = weight

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L14H15", attention



def prog_L14H16(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Structural marker attention: focuses on newlines, periods, and first tokens."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L14H16", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    for i in range(n):
        for j in range(i + 1):  # causal mask
            weight = 0.0

            # Very high attention to newline characters
            if tokens[j] == '\n':
                weight += 0.5

            # High attention to periods
            elif tokens[j] == '.':
                weight += 0.3

            # Moderate attention to first token
            elif j == 0:
                weight += 0.2

            # Small baseline attention to all previous tokens
            else:
                weight += 0.05

            # Add distance decay for non-structural tokens
            if tokens[j] not in ['\n', '.'] and j != 0:
                distance = i - j
                weight *= (1.0 / (1.0 + distance * 0.1))

            attention[i, j] = weight

    # Normalize and apply causal mask
    attention = make_row_stochastic(attention)
    attention = apply_causal_mask(attention)

    return "prog_L14H16", attention



def prog_L14H17(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Structural boundary attention head with strong first-token attraction for content words."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    # Find structural tokens
    newline_positions = [i for i, token in enumerate(tokens) if '\n' in token]
    period_positions = [i for i, token in enumerate(tokens) if '.' in token]
    first_token_pos = 0 if n > 0 else None

    # Parse for content word detection
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        current_token = tokens[i]

        # Check if current token is a content word
        is_content_word = False
        if i < len(token_to_spacy) and token_to_spacy[i]:
            spacy_idx = token_to_spacy[i][0]
            if spacy_idx < len(doc):
                current_spacy = doc[spacy_idx]
                is_content_word = current_spacy.pos_ in ['NOUN', 'VERB', 'ADJ', 'ADV']

        # Base attention distribution
        for j in range(i + 1):  # Only attend to previous tokens (causal)
            distance = i - j

            # Strong attention to newlines (reduced for distant tokens)
            if j in newline_positions:
                base_weight = 0.4
                if distance > 10:  # Reduce structural attention for distant tokens
                    base_weight *= 0.7
                attention[i, j] += base_weight

            # Strong attention to periods (reduced for distant tokens)
            elif j in period_positions:
                base_weight = 0.25
                if distance > 10:  # Reduce structural attention for distant tokens
                    base_weight *= 0.7
                attention[i, j] += base_weight

            # Enhanced attention to first token, especially for content words
            elif j == first_token_pos:
                base_weight = 0.15
                if is_content_word and distance > 5:  # Strong boost for content words attending to first token
                    base_weight *= 4.0
                attention[i, j] += base_weight

            # Self-attention
            elif i == j:
                attention[i, j] += 0.1

            # Weaker attention to other tokens with distance decay
            else:
                attention[i, j] += 0.05 / (1 + 0.1 * distance)

        # Additional boost for tokens that are structurally important themselves
        if '\n' in current_token or '.' in current_token:
            # These tokens pay extra attention to structural elements
            for j in range(i + 1):
                if j in newline_positions or j in period_positions:
                    attention[i, j] *= 1.5

        # Boost attention based on linguistic similarity for content words
        if i < len(token_to_spacy) and token_to_spacy[i]:
            spacy_idx = token_to_spacy[i][0]
            if spacy_idx < len(doc):
                current_spacy = doc[spacy_idx]

                # Content words pay more attention to related content words
                if current_spacy.pos_ in ['NOUN', 'VERB', 'ADJ', 'ADV']:
                    for j in range(i):
                        if j < len(token_to_spacy) and token_to_spacy[j]:
                            j_spacy_idx = token_to_spacy[j][0]
                            if j_spacy_idx < len(doc):
                                j_spacy = doc[j_spacy_idx]

                                # Boost for same POS or syntactic relation
                                if current_spacy.pos_ == j_spacy.pos_:
                                    attention[i, j] *= 1.2

                                # Boost for semantic similarity
                                sim = _char_sim(tokens[i], tokens[j])
                                if sim > 0.3:
                                    attention[i, j] *= (1 + sim * 0.5)

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L14H17", attention



def prog_L14H18(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Attention head focusing on sentence-initial tokens with structural boundary backup."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention_matrix = np.zeros((n, n))

    for i in range(n):
        current_token = tokens[i]

        # Very strong self-attention for first token
        if i == 0:
            attention_matrix[i, i] = 1.0
            continue

        # NEW: Strong attention to first token for all subsequent tokens
        attention_matrix[i, 0] += 0.6

        # Find newlines and periods for structural attention
        newline_positions = []
        period_positions = []

        for j in range(i + 1):  # Only look at valid positions due to causal mask
            if tokens[j] == '\n':
                newline_positions.append(j)
            elif tokens[j] == '.':
                period_positions.append(j)

        # Base attention distribution
        base_attention = 0.01  # Small baseline

        # Reduced attention to most recent newline (since first token is primary)
        if newline_positions:
            most_recent_newline = newline_positions[-1]
            attention_matrix[i, most_recent_newline] += 0.1

        # Reduced attention to most recent period
        if period_positions:
            most_recent_period = period_positions[-1]
            attention_matrix[i, most_recent_period] += 0.05

        # Self-attention
        attention_matrix[i, i] += 0.05

        # Semantic similarity component
        for j in range(i + 1):
            if j != i and j != 0:  # Don't double-count self or first token
                sim = _char_sim(tokens[i], tokens[j])
                if sim > 0.5:  # Threshold for semantic similarity
                    attention_matrix[i, j] += 0.05 * sim
                else:
                    attention_matrix[i, j] += base_attention

        # Recency bias - slight preference for recent tokens
        for j in range(max(0, i - 5), i):
            if j != 0:  # Don't add to first token (already handled)
                attention_matrix[i, j] += 0.01 * (1.0 - (i - j) / 6.0)

        # Add baseline attention to all positions except first token
        for j in range(1, i + 1):
            if j != i:  # Don't double-count self
                attention_matrix[i, j] += base_attention

    # Apply causal mask and normalize
    attention_matrix = apply_causal_mask(attention_matrix)
    attention_matrix = make_row_stochastic(attention_matrix)

    return "prog_L14H18", attention_matrix



def prog_L14H19(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Attention head that focuses on structural delimiters (newlines, periods) with local context bias."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L14H19", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        token = tokens[i].strip()

        # Find newline and period positions
        newline_positions = [j for j in range(i+1) if tokens[j].strip() == '' and j > 0 and tokens[j-1].strip() in ['.', '!', '?']]
        if not newline_positions:
            newline_positions = [j for j in range(i+1) if '\n' in tokens[j]]

        period_positions = [j for j in range(i+1) if tokens[j].strip() in ['.', '!', '?']]

        # Base attention distribution
        for j in range(i+1):  # Causal mask
            # Strong attention to newlines
            if j in newline_positions:
                attention[i, j] += 3.0

            # Strong attention to periods
            if j in period_positions:
                attention[i, j] += 2.0

            # Self-attention boost for punctuation
            if i == j and tokens[j].strip() in ['.', '!', '?', ',']:
                attention[i, j] += 2.0

            # Previous token attention
            if j == i - 1:
                attention[i, j] += 1.0

            # Attention to first token
            if j == 0:
                attention[i, j] += 0.5

            # Distance-based decay
            distance = i - j
            if distance > 0:
                attention[i, j] += 0.3 / (1 + distance * 0.1)

            # Base attention for all valid positions
            attention[i, j] += 0.1

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L14H19", attention



def prog_L14H2(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary and local syntax attention head."""
    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L14H2", np.zeros((n_empty, n_empty))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    # Initialize attention matrix
    attention = np.zeros((n, n))

    for i in range(n):
        current_token = tokens[i]

        # Get spacy alignment for current token
        spacy_indices = token_to_spacy[i]
        current_spacy = doc[spacy_indices[0]] if spacy_indices else None

        for j in range(i + 1):  # Only attend to current and previous tokens
            target_token = tokens[j]
            target_spacy_indices = token_to_spacy[j]
            target_spacy = doc[target_spacy_indices[0]] if target_spacy_indices else None

            weight = 0.0

            # High attention to sentence boundaries
            if target_token in ['.', '\n']:
                weight += 0.3

            # Self-attention for important content words
            if i == j:
                if current_spacy and current_spacy.pos_ in ['NOUN', 'VERB', 'ADJ']:
                    weight += 0.15
                else:
                    weight += 0.05

            # Local syntactic relationships
            if current_spacy and target_spacy and i != j:
                # Adjective to noun relationships
                if current_spacy.pos_ == 'ADJ' and target_spacy.pos_ == 'NOUN' and abs(i - j) <= 3:
                    weight += 0.2

                # Verb to subject relationships  
                if current_spacy.pos_ == 'VERB' and target_spacy.pos_ in ['NOUN', 'PRON'] and j < i and i - j <= 5:
                    weight += 0.15

                # Determiner/modifier relationships
                if current_spacy.pos_ in ['DET', 'ADJ'] and target_spacy.pos_ == 'NOUN' and j < i and i - j <= 2:
                    weight += 0.12

                # Preposition to object relationships
                if current_spacy.pos_ == 'ADP' and target_spacy.pos_ in ['NOUN', 'PRON'] and j < i and i - j <= 3:
                    weight += 0.1

            # Semantic similarity for content words
            if i != j and current_spacy and target_spacy:
                if (current_spacy.pos_ in ['NOUN', 'VERB', 'ADJ'] and 
                    target_spacy.pos_ in ['NOUN', 'VERB', 'ADJ']):
                    sim = _char_sim(tokens[i], tokens[j])
                    if sim > 0.7:
                        weight += 0.15 * sim

            # Proximity bonus (recency bias)
            if i != j:
                distance = i - j
                if distance <= 3:
                    weight += 0.1 * (1.0 / (distance + 1))

            # Special attention to first token
            if j == 0 and i > 0:
                weight += 0.05

            attention[i, j] = weight

        # Add small baseline attention
        for j in range(i + 1):
            attention[i, j] += 0.01

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L14H2", attention



def prog_L14H20(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary and structural marker attention head that focuses on newlines, periods, and first tokens of each sentence."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L14H20", np.zeros((n_empty, n_empty))

    attention_matrix = np.zeros((n, n))

    # Get spacy alignment for linguistic features
    token_to_spacy = _align_to_spacy(sentence, tokens)

    # Identify sentence start tokens
    sentence_starts = [0]  # First token is always a sentence start
    doc = spacy_parse(sentence)
    for i in range(n):
        spacy_indices = token_to_spacy[i]
        if spacy_indices:
            for spacy_idx in spacy_indices:
                if spacy_idx < len(doc):
                    spacy_token = doc[spacy_idx]
                    if spacy_token.is_sent_start and i not in sentence_starts:
                        sentence_starts.append(i)

    # Also consider tokens after newlines as sentence starts
    for i in range(1, n):
        if '\n' in tokens[i-1] and i not in sentence_starts:
            sentence_starts.append(i)

    for i in range(n):
        # Find structural markers (newlines, periods, first token)
        newline_indices = []
        period_indices = []
        first_token_idx = 0

        for j in range(i + 1):  # Causal mask
            token_j = tokens[j]

            # Check for newlines
            if '\n' in token_j:
                newline_indices.append(j)

            # Check for sentence-ending punctuation
            if token_j.strip() in ['.', '!', '?']:
                period_indices.append(j)

        # Base attention distribution
        for j in range(i + 1):
            token_j = tokens[j]

            # Very high attention to newlines
            if '\n' in token_j:
                attention_matrix[i, j] = 0.5

            # High attention to sentence-ending punctuation
            elif token_j.strip() in ['.', '!', '?']:
                attention_matrix[i, j] = 0.3

            # High attention to first token
            elif j == 0:
                attention_matrix[i, j] = 0.25

            # Self-attention for punctuation
            elif i == j and (token_j.strip() in ['.', '!', '?', ',', ':', ';'] or '\n' in token_j):
                attention_matrix[i, j] = 0.4

            # Moderate attention to quotation marks and other structural elements
            elif token_j.strip() in ['"', "'", '(', ')', '[', ']']:
                attention_matrix[i, j] = 0.15

            # Low baseline attention
            else:
                attention_matrix[i, j] = 0.02

        # NEW: Boost attention to sentence start tokens
        # Find the most recent sentence start for token i
        current_sentence_start = 0
        for start_idx in sentence_starts:
            if start_idx <= i:
                current_sentence_start = start_idx
            else:
                break

        # If current token is not at the very beginning, boost attention to its sentence start
        if i > 0 and current_sentence_start <= i:
            attention_matrix[i, current_sentence_start] *= 3.0

        # Boost attention if this token appears to be starting a new sentence/segment
        if i > 0:
            current_token = tokens[i]
            spacy_indices = token_to_spacy[i]

            # Check if this token starts a sentence in spacy
            if spacy_indices:
                doc = spacy_parse(sentence)
                for spacy_idx in spacy_indices:
                    if spacy_idx < len(doc):
                        spacy_token = doc[spacy_idx]
                        # If this is the start of a sentence, boost attention to structural markers
                        if spacy_token.is_sent_start:
                            for j in range(i + 1):
                                if '\n' in tokens[j] or tokens[j].strip() in ['.', '!', '?']:
                                    attention_matrix[i, j] *= 1.5

    # Apply causal mask and normalize
    attention_matrix = apply_causal_mask(attention_matrix)
    attention_matrix = make_row_stochastic(attention_matrix)

    return "prog_L14H20", attention_matrix



def prog_L14H21(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary attention head with strong beginning-of-text bias."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L14H21", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    for i in range(n):
        token = tokens[i]

        # Base attention distribution
        for j in range(i + 1):  # Only attend to previous tokens (causal)

            # Very high attention to sentence boundary markers
            if tokens[j] in ['.', '\n', '!', '?']:
                attention[i, j] += 5.0

            # High attention to beginning of text
            if j == 0:
                attention[i, j] += 3.0

            # Moderate attention to commas and other punctuation
            elif tokens[j] in [',', ':', ';']:
                attention[i, j] += 1.5

            # Self-attention baseline
            elif i == j:
                attention[i, j] += 1.0

            # Small baseline for all other tokens
            else:
                attention[i, j] += 0.1

            # Distance decay - closer tokens get slightly more attention
            distance = i - j
            if distance > 0:
                attention[i, j] *= (1.0 / (1.0 + 0.05 * distance))

        # TARGETED FIX: Boost attention to first token for content tokens
        # This addresses the strong beginning-of-text bias seen in failure cases
        if i > 0 and len(tokens[0]) > 1 and not tokens[0] in ['.', '\n', '!', '?', ',', ':', ';']:
            # Give much stronger attention to first token for all subsequent tokens
            attention[i, 0] *= 4.0

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L14H21", attention



def prog_L14H22(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Structural anchor attention: attends strongly to first token, with reduced self-attention."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L14H22", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    for i in range(n):
        # Reduced self-attention (was too high at 1.0)
        attention[i, i] = 0.1

        # Very strong attention to first token
        attention[i, 0] = 0.95

        # Find structural markers
        for j in range(i + 1):
            token_j = tokens[j]

            # High attention to newlines
            if token_j.strip() == '' and '\n' in token_j:
                attention[i, j] += 0.6

            # High attention to sentence-ending punctuation
            elif token_j == '.':
                attention[i, j] += 0.4

            # Moderate attention to other punctuation
            elif token_j in [',', '!', '?']:
                attention[i, j] += 0.2

            # Recency bias for recent tokens
            if i - j <= 3:
                attention[i, j] += 0.1 * (4 - (i - j)) / 4

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L14H22", attention



def prog_L14H23(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary and positional attention head with syntactic component and enhanced first-token attention."""
    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L14H23", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        for j in range(i + 1):  # causal mask
            weight = 0.0

            # Very strong attention to first token
            if j == 0:
                weight += 0.8

                # Enhanced first-token attention for tokens with high similarity or linguistic connection
                if i > 0:
                    # High semantic similarity to first token
                    sim_to_first = _char_sim(tokens[i], tokens[0])
                    if sim_to_first > 0.6:
                        weight += 1.5 * sim_to_first

                    # Linguistic connection via spacy
                    if token_to_spacy[i] and token_to_spacy[0]:
                        spacy_i = token_to_spacy[i][0] if token_to_spacy[i] else None
                        spacy_0 = token_to_spacy[0][0] if token_to_spacy[0] else None

                        if (spacy_i is not None and spacy_0 is not None and 
                            spacy_i < len(doc) and spacy_0 < len(doc)):
                            tok_i = doc[spacy_i]
                            tok_0 = doc[spacy_0]

                            # Same lemma or root form
                            if tok_i.lemma_ == tok_0.lemma_ and len(tok_i.lemma_) > 2:
                                weight += 1.2

                            # Part of same phrase or chunk
                            if (tok_i.sent == tok_0.sent and 
                                abs(tok_i.i - tok_0.i) <= 3):
                                weight += 0.8

            # Strong attention to sentence boundary tokens
            if tokens[j] in ['.', '\n', '!', '?']:
                weight += 0.6

            # Self-attention baseline
            if i == j:
                weight += 0.1

            # Distance decay
            distance = i - j
            if distance > 0:
                weight += 0.2 * np.exp(-0.1 * distance)

            # Syntactic relationships via spacy
            if token_to_spacy[i] and token_to_spacy[j]:
                spacy_i = token_to_spacy[i][0]
                spacy_j = token_to_spacy[j][0]

                if spacy_i < len(doc) and spacy_j < len(doc):
                    tok_i = doc[spacy_i]
                    tok_j = doc[spacy_j]

                    # Head-dependent relationships
                    if tok_j.head == tok_i or tok_i.head == tok_j:
                        weight += 0.3

                    # Same head relationships
                    if tok_i.head == tok_j.head and tok_i.head != tok_i:
                        weight += 0.2

            # Semantic similarity boost
            sim = _char_sim(tokens[i], tokens[j])
            if sim > 0.7:
                weight += 0.2 * sim

            attention[i, j] = weight

    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L14H23", attention



def prog_L14H24(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary detection head: attends to newlines, periods, and sentence starts."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention_matrix = np.zeros((n, n))

    # Find newline and period tokens
    newline_indices = []
    period_indices = []

    for i, token in enumerate(tokens):
        if token.strip() == '\n':
            newline_indices.append(i)
        elif token.strip() == '.':
            period_indices.append(i)

    # Get spacy alignment for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        # Strong self-attention for first token
        if i == 0:
            attention_matrix[i, i] = 1.0
            continue

        # Base attention to all valid positions
        for j in range(i + 1):
            attention_matrix[i, j] = 0.01

        # Strong attention to newlines
        for nl_idx in newline_indices:
            if nl_idx <= i:
                attention_matrix[i, nl_idx] += 0.4

        # Moderate attention to periods
        for p_idx in period_indices:
            if p_idx <= i:
                attention_matrix[i, p_idx] += 0.2

        # Check if current token might be start of sentence
        spacy_indices = token_to_spacy[i]
        is_sentence_start = False

        if spacy_indices:
            spacy_token = doc[spacy_indices[0]]
            # Check if this is the first token of a sentence
            if spacy_token.is_sent_start or (spacy_token.i == 0):
                is_sentence_start = True

        # If this is a sentence start, attend more to previous boundaries
        if is_sentence_start:
            for nl_idx in newline_indices:
                if nl_idx < i:
                    attention_matrix[i, nl_idx] += 0.3
            for p_idx in period_indices:
                if p_idx < i:
                    attention_matrix[i, p_idx] += 0.2

        # Slight recency bias
        if i > 0:
            attention_matrix[i, i-1] += 0.05

    attention_matrix = apply_causal_mask(attention_matrix)
    attention_matrix = make_row_stochastic(attention_matrix)

    return "prog_L14H24", attention_matrix



def prog_L14H25(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Newline and sentence boundary attention with enhanced self-attention for content words."""
    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L14H25", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Get spacy analysis for POS tagging
    doc = spacy_parse(sentence)
    alignment = _align_to_spacy(sentence, tokens)

    # Find newlines and periods for structural attention
    newline_indices = [i for i, tok in enumerate(tokens) if tok.strip() == '']
    period_indices = [i for i, tok in enumerate(tokens) if tok.strip() == '.']

    for i in range(n):
        current_token = tokens[i].strip()

        # Self-attention baseline
        attention[i, i] = 0.1

        # Enhanced self-attention for content words
        if alignment[i]:  # If token aligns to spacy tokens
            spacy_indices = alignment[i]
            for spacy_idx in spacy_indices:
                if spacy_idx < len(doc):
                    pos = doc[spacy_idx].pos_
                    # Boost self-attention for nouns, verbs, adjectives, and proper nouns
                    if pos in ['NOUN', 'VERB', 'ADJ', 'PROPN']:
                        attention[i, i] = 0.45
                        break

        # Strong attention to newlines
        for nl_idx in newline_indices:
            if nl_idx <= i:
                attention[i, nl_idx] = 0.35

        # Moderate attention to periods
        for p_idx in period_indices:
            if p_idx <= i:
                attention[i, p_idx] = 0.2

        # Adjacent token attention
        if i > 0:
            attention[i, i-1] = 0.15
        if i > 1:
            attention[i, i-2] = 0.08

        # First token attention
        attention[i, 0] = 0.12

        # Special patterns for certain tokens
        if current_token == ',':
            # Commas attend strongly to themselves
            attention[i, i] = 0.4

        # Token similarity based attention
        for j in range(i):
            if _char_sim(tokens[i], tokens[j]) > 0.7:
                attention[i, j] += 0.1

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L14H25", attention



def prog_L14H26(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Structural boundary attention head that focuses on newlines and sentence-ending punctuation."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L14H26", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Find structural tokens
    newline_indices = [i for i, t in enumerate(tokens) if t.strip() == '']
    period_indices = [i for i, t in enumerate(tokens) if t.strip() == '.']

    # Find the first token (usually gets very high attention)
    first_token_idx = 0

    for i in range(n):
        # Strong attention to first token (usually newline)
        if first_token_idx < i:  # causal constraint
            attention[i, first_token_idx] = 0.8

        # Strong attention to newlines
        for nl_idx in newline_indices:
            if nl_idx < i:  # causal constraint
                if nl_idx == first_token_idx:
                    attention[i, nl_idx] = 0.9  # Even stronger for first newline
                else:
                    attention[i, nl_idx] = 0.6

        # Moderate attention to periods
        for p_idx in period_indices:
            if p_idx < i:  # causal constraint
                attention[i, p_idx] = 0.4

        # Small amount of attention distributed to other tokens
        for j in range(i):  # causal constraint
            if j not in newline_indices and j not in period_indices and j != first_token_idx:
                # Distance-based decay for non-structural tokens
                distance = i - j
                attention[i, j] = 0.1 / (1 + 0.1 * distance)

        # Self-attention
        attention[i, i] = 0.05

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L14H26", attention



def prog_L14H27(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Boundary-aware attention head with strong beginning-of-sequence attention pattern."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention_matrix = np.zeros((n, n))

    # Find boundary tokens (newlines, periods, and similar punctuation)
    boundary_indices = []
    for i, token in enumerate(tokens):
        if token.strip() in ['\n', '.', '!', '?', ';']:
            boundary_indices.append(i)

    # Find first token of each sentence/section
    first_token_indices = [0]  # Always include very first token
    for i, token in enumerate(tokens):
        if i > 0 and tokens[i-1].strip() == '\n' and token.strip() != '':
            first_token_indices.append(i)

    for i in range(n):
        # Self-attention baseline
        attention_matrix[i, i] = 0.1

        # ADDED: Strong beginning-of-sequence attention - tokens attend heavily to the very first token
        if i > 0:  # Don't self-reinforce the first token
            attention_matrix[i, 0] += 0.6

        # Strong attention to boundary tokens (especially newlines)
        for boundary_idx in boundary_indices:
            if boundary_idx <= i:
                if tokens[boundary_idx].strip() == '\n':
                    attention_matrix[i, boundary_idx] += 0.4
                elif tokens[boundary_idx].strip() == '.':
                    attention_matrix[i, boundary_idx] += 0.3
                else:
                    attention_matrix[i, boundary_idx] += 0.2

        # Moderate attention to first tokens
        for first_idx in first_token_indices:
            if first_idx <= i and first_idx != i:
                attention_matrix[i, first_idx] += 0.15

        # Find the most recent boundary before current token
        recent_boundary = -1
        for boundary_idx in boundary_indices:
            if boundary_idx < i:
                recent_boundary = boundary_idx

        # Extra attention to the most recent boundary
        if recent_boundary >= 0:
            attention_matrix[i, recent_boundary] += 0.2

        # Add some recency bias for nearby tokens
        for j in range(max(0, i-3), i):
            attention_matrix[i, j] += 0.05

    # Apply causal mask and normalize
    attention_matrix = apply_causal_mask(attention_matrix)
    attention_matrix = make_row_stochastic(attention_matrix)

    return "prog_L14H27", attention_matrix



def prog_L14H28(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Discourse boundary attention head that focuses on sentence/paragraph starts and punctuation boundaries."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L14H28", np.zeros((n_empty, n_empty))

    attention_matrix = np.zeros((n, n))

    # Find first tokens and boundary tokens
    first_token_idx = 0
    newline_indices = []
    period_indices = []

    for i, token in enumerate(tokens):
        if token.strip() == '\n':
            newline_indices.append(i)
        elif token.strip() == '.':
            period_indices.append(i)

    # Get spacy alignment for linguistic features
    spacy_alignment = _align_to_spacy(sentence, tokens)
    doc = spacy_parse(sentence)

    for i in range(n):
        # Base uniform attention to all previous tokens
        for j in range(i + 1):
            attention_matrix[i, j] = 0.1

        # Strong attention to first token
        attention_matrix[i, first_token_idx] += 0.8

        # High attention to newlines
        for newline_idx in newline_indices:
            if newline_idx <= i:
                attention_matrix[i, newline_idx] += 0.4

        # Moderate attention to periods
        for period_idx in period_indices:
            if period_idx <= i:
                attention_matrix[i, period_idx] += 0.2

        # Self-attention for special tokens
        if tokens[i].strip() in ['\n', '.']:
            attention_matrix[i, i] += 0.3

        # Boost attention to sentence starts (tokens after periods/newlines)
        for j in range(i + 1):
            if j > 0 and (tokens[j-1].strip() in ['.', '\n']):
                # This is likely a sentence start
                attention_matrix[i, j] += 0.3

        # Additional boost for tokens that are semantically similar to first token
        if i > 0:
            sim_to_first = _char_sim(tokens[i], tokens[first_token_idx])
            if sim_to_first > 0.5:
                attention_matrix[i, first_token_idx] += 0.2

    # Apply causal mask and normalize
    attention_matrix = apply_causal_mask(attention_matrix)
    attention_matrix = make_row_stochastic(attention_matrix)

    return "prog_L14H28", attention_matrix



def prog_L14H29(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary and discourse structure head - attends primarily to first token, newlines and periods."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    # Find newline and period positions
    newline_positions = [i for i, tok in enumerate(tokens) if tok.strip() == '\n']
    period_positions = [i for i, tok in enumerate(tokens) if tok.strip() == '.']

    for i in range(n):
        current_token = tokens[i].strip()

        # Much stronger attention to first token (this was the main missing pattern)
        if i > 0:
            attention[i, 0] = 0.9

        # Reduced attention to immediately preceding token (was over-predicted)
        if i > 0:
            prev_token = tokens[i-1].strip()
            # Much more selective about when to give high previous-token attention
            sim = _char_sim(tokens[i], tokens[i-1])
            if sim > 0.85 and not (current_token.isalpha() and prev_token.isalpha()):
                attention[i, i-1] = 0.3

        # Strong attention to newlines from all following tokens
        for nl_pos in newline_positions:
            if nl_pos <= i:
                attention[i, nl_pos] = 0.6

        # Medium attention to periods
        for period_pos in period_positions:
            if period_pos <= i:
                attention[i, period_pos] = 0.3

        # Self-attention for special tokens
        if current_token in ['.', '\n']:
            attention[i, i] = 0.4

        # Boost attention to most recent newline
        recent_newlines = [pos for pos in newline_positions if pos <= i]
        if recent_newlines:
            most_recent_nl = max(recent_newlines)
            attention[i, most_recent_nl] *= 1.2

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L14H29", attention



def prog_L14H3(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary and local semantic coherence attention head with beginning-of-sequence focus."""
    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        query_token = tokens[i].strip()

        # Get spacy info for query token
        query_spacy_indices = token_to_spacy[i]
        query_spacy_tokens = [doc[idx] for idx in query_spacy_indices if idx < len(doc)]

        for j in range(i + 1):  # Causal mask
            key_token = tokens[j].strip()

            # Base attention
            base_weight = 0.01

            # NEW: Strong attention to the very first token (beginning-of-sequence bias)
            if j == 0 and i > 0:
                # Distance-based decay from first token
                distance_from_start = i
                if distance_from_start <= 10:
                    base_weight += 0.6 * (11 - distance_from_start) / 11
                else:
                    base_weight += 0.2

            # Strong attention to newlines (sentence boundaries)
            if key_token == '\n':
                base_weight += 0.4

            # Strong attention to periods (clause boundaries)
            elif key_token == '.':
                base_weight += 0.15

            # Self-attention boost (reduced from original to fix over-prediction)
            if i == j:
                base_weight += 0.05  # Reduced from 0.1

            # Recency bias (stronger for recent tokens)
            distance = i - j
            if distance <= 5:
                recency_boost = 0.05 * (6 - distance) / 6
                base_weight += recency_boost

            # Semantic similarity boost for nearby tokens
            if distance <= 10 and i != j:
                sim = _char_sim(tokens[i], tokens[j])
                if sim > 0.3:
                    base_weight += 0.1 * sim

            # Syntactic patterns using spacy
            if query_spacy_tokens and token_to_spacy[j]:
                key_spacy_indices = token_to_spacy[j]
                key_spacy_tokens = [doc[idx] for idx in key_spacy_indices if idx < len(doc)]

                for q_tok in query_spacy_tokens:
                    for k_tok in key_spacy_tokens:
                        # Verb attending to its object/complement
                        if q_tok.pos_ == 'VERB' and k_tok.dep_ in ['dobj', 'pobj', 'attr']:
                            base_weight += 0.08

                        # Noun attending to its modifiers
                        if q_tok.pos_ == 'NOUN' and k_tok.dep_ in ['amod', 'det', 'compound']:
                            base_weight += 0.06

                        # Preposition attending to its object
                        if q_tok.pos_ == 'ADP' and k_tok.dep_ == 'pobj':
                            base_weight += 0.08

                        # Head attending to dependents
                        if k_tok.head == q_tok:
                            base_weight += 0.05

            attention[i, j] = base_weight

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L14H3", attention



def prog_L14H30(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence structure attention head focusing on first tokens and boundaries."""
    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    # Find sentence boundaries and first meaningful token
    first_token_idx = 0
    boundary_indices = set()

    for i, token in enumerate(tokens):
        if token.strip() in ['.', '!', '?', '\n']:
            boundary_indices.add(i)

    for i in range(n):
        token = tokens[i]

        # Base attention distribution
        for j in range(i + 1):  # Causal mask
            if j == first_token_idx:
                # Strong attention to first token
                attention[i, j] = 0.4
            elif j in boundary_indices:
                # Moderate attention to boundaries
                attention[i, j] = 0.2
            elif j == i:
                # Self attention
                attention[i, j] = 0.1
            else:
                # Background attention
                attention[i, j] = 0.05

        # Special cases for punctuation and boundaries
        if token.strip() in ['.', '!', '?']:
            # Punctuation attends strongly to nearby boundaries
            for j in range(i + 1):
                if j in boundary_indices or j == first_token_idx:
                    attention[i, j] = 0.5
                else:
                    attention[i, j] = 0.02

        elif token.strip() == '\n':
            # Newlines attend to first token and previous boundaries
            for j in range(i + 1):
                if j == first_token_idx:
                    attention[i, j] = 0.6
                elif j in boundary_indices:
                    attention[i, j] = 0.15
                else:
                    attention[i, j] = 0.01

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L14H30", attention



def prog_L14H31(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Structural attention head focusing on document boundaries (first token, newlines, periods) with enhanced period attention."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    for i in range(n):
        for j in range(i + 1):  # causal mask
            # Base attention
            base_attention = 0.01

            # Very strong attention to first token
            if j == 0:
                base_attention += 0.8

            # Strong attention to newlines
            if tokens[j].strip() == '' and '\n' in tokens[j]:
                base_attention += 0.4

            # Enhanced attention to periods - boost from 0.25 to 0.5
            if tokens[j].strip() == '.':
                base_attention += 0.5

            # Self-attention boost
            if i == j:
                base_attention += 0.1

            # Distance decay for non-special tokens
            if j != 0 and tokens[j].strip() not in ['.', ''] and i != j:
                distance = i - j
                decay = max(0.01, 1.0 / (1 + distance * 0.1))
                base_attention *= decay

            attention[i, j] = base_attention

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L14H31", attention



def prog_L14H4(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Local attention head with semantic similarity and boundary focus."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L14H4", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    for i in range(n):
        for j in range(i + 1):  # causal mask

            # Base attention score
            score = 0.1

            # Strong self-attention
            if i == j:
                score += 1.5

            # Previous token attention
            elif j == i - 1:
                score += 0.8

            # Attention to sentence boundaries (newlines, periods)
            if tokens[j] in ['\n', '.', '!', '?']:
                score += 0.6

            # First token attention
            if j == 0:
                score += 0.4

            # Semantic similarity boost
            sim = _char_sim(tokens[i], tokens[j])
            if sim > 0.3:
                score += sim * 0.5

            # Punctuation attention patterns
            if tokens[i] in [',', ';', ':'] and j < i:
                # Commas often attend to recent content words
                if tokens[j] not in ['\n', '.', ',', ';', ':', '!', '?'] and i - j <= 3:
                    score += 0.3

            # Distance decay for non-adjacent tokens
            if j < i - 1:
                distance = i - j
                decay = max(0.1, 1.0 / (distance + 1))
                score *= decay

            attention[i, j] = score

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L14H4", attention



def prog_L14H5(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Syntactic-semantic attention head with strong first-token attraction pattern."""
    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L14H5", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        for j in range(i + 1):  # Only fill lower triangle
            weight = 0.0

            # Strong self-attention baseline
            if i == j:
                weight += 0.15

            # High attention to sentence boundaries
            if tokens[j] in ['.', '!', '?', '\n']:
                weight += 0.20

            # Positional decay for recent tokens
            if i - j <= 3 and i != j:
                decay = 0.08 / (i - j)
                weight += decay

            # NEW: Strong first-token attraction pattern
            if j == 0 and i > 0:
                # Base first-token attraction
                weight += 0.25
                # Extra boost for content words attending to first token
                if token_to_spacy[i] and token_to_spacy[i][0] < len(doc):
                    i_token = doc[token_to_spacy[i][0]]
                    if i_token.pos_ in ["NOUN", "VERB", "ADJ", "ADV"]:
                        weight += 0.15

            # Syntactic relationships via spacy
            if token_to_spacy[i] and token_to_spacy[j]:
                i_spacy_idx = token_to_spacy[i][0]
                j_spacy_idx = token_to_spacy[j][0]

                if i_spacy_idx < len(doc) and j_spacy_idx < len(doc):
                    i_token = doc[i_spacy_idx]
                    j_token = doc[j_spacy_idx]

                    # Verb-object relationships
                    if (i_token.dep_ == "dobj" and j_token == i_token.head) or \
                       (j_token.dep_ == "dobj" and i_token == j_token.head):
                        weight += 0.12

                    # Modifier relationships
                    if (i_token.dep_ in ["amod", "advmod"] and j_token == i_token.head) or \
                       (j_token.dep_ in ["amod", "advmod"] and i_token == j_token.head):
                        weight += 0.10

                    # Subject-predicate relationships
                    if (i_token.dep_ in ["nsubj", "nsubjpass"] and j_token == i_token.head) or \
                       (j_token.dep_ in ["nsubj", "nsubjpass"] and i_token == j_token.head):
                        weight += 0.08

            # Semantic similarity boost
            sim = _char_sim(tokens[i], tokens[j])
            if sim > 0.7:  # High similarity threshold
                weight += 0.15 * sim
            elif sim > 0.4:  # Moderate similarity
                weight += 0.08 * sim

            # Punctuation attention patterns
            if tokens[i] == ',' and j > 0:
                weight += 0.06

            # Small baseline for all positions
            weight += 0.02

            attention[i, j] = weight

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L14H5", attention



def prog_L14H6(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary and syntactic structure attention head with strong first-token bias."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L14H6", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        # Self-attention baseline
        attention[i, i] = 0.1

        # Strong attention to first token (sequence anchor)
        if i > 0:
            attention[i, 0] = 0.4

        # Strong attention to periods and sentence endings
        for j in range(i + 1):
            if tokens[j].strip() == '.':
                attention[i, j] = 0.4

        # Strong attention to newlines (paragraph/sentence breaks)
        for j in range(i + 1):
            if tokens[j] == '\n':
                attention[i, j] = 0.3

        # Get spacy token for current position if available
        current_spacy = None
        if token_to_spacy[i]:
            spacy_idx = token_to_spacy[i][0]
            if spacy_idx < len(doc):
                current_spacy = doc[spacy_idx]

        # Syntactic dependencies - attend to head
        if current_spacy and current_spacy.head != current_spacy:
            head_token = current_spacy.head
            # Find corresponding LM token for the head
            for j in range(i):
                if token_to_spacy[j]:
                    j_spacy_idx = token_to_spacy[j][0]
                    if j_spacy_idx < len(doc) and doc[j_spacy_idx] == head_token:
                        attention[i, j] += 0.2
                        break

        # Local attention to previous few tokens
        for offset in range(1, min(4, i + 1)):
            j = i - offset
            attention[i, j] += 0.1 / offset

        # Semantic similarity component
        for j in range(i):
            sim = _char_sim(tokens[i], tokens[j])
            if sim > 0.7:  # High similarity threshold
                attention[i, j] += 0.15 * sim

        # Special cases for function words attending to content
        if current_spacy:
            if current_spacy.pos_ in ['DET', 'PREP', 'ADP']:
                # Determiners and prepositions attend to nearby nouns
                for j in range(max(0, i-3), i):
                    if token_to_spacy[j]:
                        j_spacy_idx = token_to_spacy[j][0]
                        if j_spacy_idx < len(doc) and doc[j_spacy_idx].pos_ in ['NOUN', 'PROPN']:
                            attention[i, j] += 0.15

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L14H6", attention



def prog_L14H7(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Discourse boundary detection head with strong beginning-of-sequence attention."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        # Strong self-attention baseline
        attention[i, i] = 0.05

        # Very strong attention to newlines (discourse boundaries)
        for j in range(i + 1):
            if tokens[j].strip() == '' or '\n' in tokens[j]:
                attention[i, j] += 0.3

        # Strong attention to sentence-ending punctuation
        for j in range(i + 1):
            if tokens[j] in ['.', '!', '?']:
                attention[i, j] += 0.15

        # Attention to commas and other punctuation
        for j in range(i + 1):
            if tokens[j] in [',', ';', ':']:
                attention[i, j] += 0.05

        # Syntactic dependencies - attend to syntactic heads
        if token_to_spacy[i]:
            spacy_token = doc[token_to_spacy[i][0]]
            if spacy_token.head != spacy_token:  # Not root
                head_token = spacy_token.head
                # Find corresponding LM token for the head
                for j in range(i + 1):
                    if token_to_spacy[j] and any(head_token.i == spacy_idx for spacy_idx in token_to_spacy[j]):
                        attention[i, j] += 0.08

        # Positional decay - slight preference for recent tokens
        for j in range(i + 1):
            decay = 0.02 * (1.0 / (1.0 + (i - j) * 0.5))
            attention[i, j] += decay

        # Special attention to first token of sentence
        if i > 0:
            # Find sentence boundaries
            for j in range(i):
                if token_to_spacy[j]:
                    spacy_token = doc[token_to_spacy[j][0]]
                    if spacy_token.is_sent_start:
                        attention[i, j] += 0.06

        # Attention to quoted speech boundaries
        for j in range(i + 1):
            if tokens[j] in ['"', "'", '"', '"']:
                attention[i, j] += 0.04

        # NEW: Strong beginning-of-sequence attention pattern
        # Tokens in certain syntactic positions attend strongly to the first token
        if i > 0 and token_to_spacy[i]:
            spacy_token = doc[token_to_spacy[i][0]]
            # Check if this token is in a position that should attend to sequence start
            if (spacy_token.dep_ in ['conj', 'cc', 'advmod', 'aux', 'auxpass'] or
                spacy_token.pos_ in ['AUX', 'VERB', 'ADV'] or
                tokens[i] in [',', 'but', 'and', 'he', 'she', 'it', 'they']):
                # Strong attention to first token (index 0)
                attention[i, 0] += 0.6

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L14H7", attention



def prog_L14H8(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary and discourse structure attention head - focuses on periods, newlines, local syntax, and beginning-of-sequence."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L14H8", np.zeros((n_empty, n_empty))

    attention_matrix = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        token = tokens[i]

        # Initialize with small uniform attention
        for j in range(i + 1):
            attention_matrix[i, j] = 0.01

        # Strong attention to sentence boundaries (periods)
        for j in range(i):
            if tokens[j].strip() in ['.', '!', '?']:
                attention_matrix[i, j] += 0.25

        # Very strong attention to newlines that precede current token
        for j in range(i):
            if '\n' in tokens[j]:
                attention_matrix[i, j] += 0.35

        # Reduced self-attention (was 0.08, now 0.04)
        attention_matrix[i, i] += 0.04

        # Strong attention to the first token (beginning-of-sequence pattern)
        if i > 0:
            attention_matrix[i, 0] += 0.15

        # Local syntactic dependencies using spacy
        if token_to_spacy[i]:
            spacy_idx = token_to_spacy[i][0]
            if spacy_idx < len(doc):
                spacy_token = doc[spacy_idx]

                # Attend to syntactic head
                if spacy_token.head != spacy_token:
                    for j in range(i):
                        if token_to_spacy[j] and token_to_spacy[j][0] < len(doc):
                            if doc[token_to_spacy[j][0]] == spacy_token.head:
                                attention_matrix[i, j] += 0.06

                # Modifiers attend to their modified words
                for j in range(i):
                    if token_to_spacy[j] and token_to_spacy[j][0] < len(doc):
                        spacy_j = doc[token_to_spacy[j][0]]
                        if spacy_j in spacy_token.children and spacy_j.dep_ in ['amod', 'advmod', 'det']:
                            attention_matrix[i, j] += 0.04

        # Recency bias - closer tokens get slightly more attention
        for j in range(max(0, i-5), i):
            distance = i - j
            attention_matrix[i, j] += 0.02 / (1 + distance * 0.5)

        # Boost attention to semantically similar tokens
        for j in range(i):
            sim = _char_sim(tokens[i], tokens[j])
            if sim > 0.3:
                attention_matrix[i, j] += 0.03 * sim

    # Apply causal mask and normalize
    attention_matrix = apply_causal_mask(attention_matrix)
    attention_matrix = make_row_stochastic(attention_matrix)

    return "prog_L14H8", attention_matrix



def prog_L14H9(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary and paragraph structure attention head with strong sequence start attention."""
    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L14H9", np.zeros((n_empty, n_empty))

    attention_matrix = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        # Base attention to all previous tokens (including self)
        for j in range(i + 1):
            attention_matrix[i, j] = 0.01

        # NEW: Very strong attention to the first token of the entire sequence
        # This is the key pattern missing from the original code
        if i > 0:  # Don't boost self-attention of first token
            attention_matrix[i, 0] += 0.35

        # Strong attention to sentence boundaries (periods, newlines)
        for j in range(i + 1):
            if tokens[j] in ['.', '!', '?', '\n']:
                attention_matrix[i, j] += 0.25

        # Very strong attention to first tokens after sentence boundaries
        for j in range(i + 1):
            if j > 0 and tokens[j-1] in ['.', '!', '?', '\n']:
                # This is likely the start of a new sentence
                attention_matrix[i, j] += 0.15
            elif j == 0:
                # First token of the sequence
                attention_matrix[i, j] += 0.10

        # Moderate attention to tokens that start sentences/paragraphs
        spacy_indices = token_to_spacy[i]
        if spacy_indices:
            spacy_token = doc[spacy_indices[0]]

            # Look for sentence starts
            for j in range(i + 1):
                j_spacy_indices = token_to_spacy[j]
                if j_spacy_indices:
                    j_spacy_token = doc[j_spacy_indices[0]]

                    # If j_spacy_token is at the start of a sentence
                    if j_spacy_token.sent.start == j_spacy_token.i:
                        attention_matrix[i, j] += 0.08

        # Slight boost for syntactic dependencies
        if spacy_indices:
            spacy_token = doc[spacy_indices[0]]

            for j in range(i + 1):
                j_spacy_indices = token_to_spacy[j]
                if j_spacy_indices:
                    j_spacy_token = doc[j_spacy_indices[0]]

                    # Head-dependent relationships
                    if j_spacy_token == spacy_token.head or spacy_token == j_spacy_token.head:
                        attention_matrix[i, j] += 0.03

        # Anti-recency: reduce attention to immediately preceding tokens
        if i > 0:
            attention_matrix[i, i-1] *= 0.7
        if i > 1:
            attention_matrix[i, i-2] *= 0.8

    # Apply causal mask and normalize
    attention_matrix = apply_causal_mask(attention_matrix)
    attention_matrix = make_row_stochastic(attention_matrix)

    return "prog_L14H9", attention_matrix



def prog_L15H0(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Attention head focusing on sentence boundaries, token relationships, and strong beginning-of-sequence attention."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L15H0", np.zeros((n_empty, n_empty))

    attention_matrix = np.zeros((n, n))

    for i in range(n):
        current_token = tokens[i]

        for j in range(i + 1):  # Only attend to previous tokens (causal)
            target_token = tokens[j]
            weight = 0.0

            # Very high attention if current token is a suffix of target token
            if i > 0 and len(current_token) >= 2 and len(target_token) >= 2:
                # Check if current token could be a suffix of the previous token
                if j == i - 1 and target_token.lower() + current_token.lower() in (target_token.lower() + current_token.lower()):
                    # Use embedding similarity to check if they form a word
                    sim = _char_sim(tokens[i], tokens[j])
                    if sim > 0.3:  # Threshold for related tokens
                        weight += 0.8

            # High attention to sentence boundary markers
            if target_token in ['.', '\n', '!', '?']:
                weight += 0.3

            # Strong attention to first token - this is the key missing pattern
            if j == 0 and i > 0:
                weight += 0.6

            # Self attention
            if i == j:
                if current_token in ['.', '\n']:
                    weight += 0.5
                else:
                    weight += 0.1

            # Boost attention to recent tokens
            distance = i - j
            if distance <= 3:
                weight += 0.1 * (1.0 / (distance + 1))

            # Special handling for quotation marks and punctuation context
            if target_token in ['"', "'", ','] and distance <= 5:
                weight += 0.1

            attention_matrix[i, j] = weight

    # Apply causal mask and normalize
    attention_matrix = apply_causal_mask(attention_matrix)
    attention_matrix = make_row_stochastic(attention_matrix)

    return "prog_L15H0", attention_matrix



def prog_L15H1(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Attention head that strongly attends to newlines, periods, and the first content token, with some local dependencies."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L15H1", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Find newlines and periods
    newline_indices = [i for i, token in enumerate(tokens) if token == '\n']
    period_indices = [i for i, token in enumerate(tokens) if token == '.']

    # Find the first content token (non-punctuation, non-whitespace)
    first_content_idx = None
    for i, token in enumerate(tokens):
        if token.strip() and token not in ['.', ',', '!', '?', ':', ';', '\n']:
            first_content_idx = i
            break

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    alignment = _align_to_spacy(sentence, tokens)

    for i in range(n):
        # Strong attention to newlines and periods
        for newline_idx in newline_indices:
            if newline_idx <= i:
                attention[i, newline_idx] += 3.0

        for period_idx in period_indices:
            if period_idx <= i:
                attention[i, period_idx] += 2.0

        # Strong attention to first content token
        if first_content_idx is not None and first_content_idx <= i:
            attention[i, first_content_idx] += 2.5

        # Self-attention for newlines and periods
        if tokens[i] in ['\n', '.']:
            attention[i, i] += 4.0

        # Local dependencies - attend to previous few tokens
        for j in range(max(0, i-3), i):
            attention[i, j] += 0.5

        # Attend to sentence/clause beginnings
        # Look for tokens that start sentences (after periods or newlines)
        for j in range(i+1):
            if j > 0 and tokens[j-1] in ['.', '\n'] and tokens[j].strip():
                attention[i, j] += 1.0

        # Syntactic dependencies using spacy alignment
        if alignment[i]:  # If token aligns with spacy tokens
            for spacy_idx in alignment[i]:
                if spacy_idx < len(doc):
                    spacy_token = doc[spacy_idx]

                    # Attend to syntactic head
                    if spacy_token.head != spacy_token:
                        head_token_indices = align_spacy_to_tokens(sentence)
                        if spacy_token.head.i < len(head_token_indices):
                            for head_idx in head_token_indices[spacy_token.head.i]:
                                if head_idx <= i:
                                    attention[i, head_idx] += 0.8

        # Similarity-based attention for content words
        for j in range(i):
            sim = _char_sim(tokens[i], tokens[j])
            if sim > 0.3:  # Threshold for similar tokens
                attention[i, j] += sim * 0.5

        # Ensure some baseline attention distribution
        if attention[i, :i+1].sum() == 0:
            # Fallback: uniform attention to available positions
            for j in range(i+1):
                attention[i, j] = 1.0

    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L15H1", attention



def prog_L15H10(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary and discourse structure head with strong first-token attention."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    # Find structural tokens
    first_token_idx = 0
    newline_indices = []
    period_indices = []

    for i, token in enumerate(tokens):
        if token.strip() == '\n':
            newline_indices.append(i)
        elif token.strip() == '.':
            period_indices.append(i)

    for i in range(n):
        token = tokens[i]

        # Base self-attention
        attention[i, i] = 0.1

        # Strong attention to first token from early positions
        if i <= 5:
            attention[i, first_token_idx] = 0.8

        # NEW: Extended first-token attention for later positions
        # Strong attention to first token from positions beyond 5
        if i > 5:
            # Distance-based decay but still substantial attention
            distance = i - first_token_idx
            if distance <= 30:
                attention[i, first_token_idx] = max(0.3, 0.9 - distance * 0.02)

        # High attention to nearest newline from subsequent tokens
        if newline_indices:
            nearest_newline = None
            for nl_idx in newline_indices:
                if nl_idx < i:
                    nearest_newline = nl_idx

            if nearest_newline is not None:
                # Distance-based attention to newlines
                distance = i - nearest_newline
                if distance <= 20:
                    attention[i, nearest_newline] = max(0.3, 0.6 - distance * 0.02)

        # High attention to nearest period (reduced strength to fix over-prediction)
        if period_indices:
            nearest_period = None
            for p_idx in period_indices:
                if p_idx < i:
                    nearest_period = p_idx

            if nearest_period is not None:
                # Distance-based attention to periods (reduced)
                distance = i - nearest_period
                if distance <= 15:
                    attention[i, nearest_period] = max(0.1, 0.25 - distance * 0.015)

        # Local context attention (previous few tokens)
        for j in range(max(0, i-3), i):
            if j != i:
                attention[i, j] += 0.05

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L15H10", attention



def prog_L15H11(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Structural anchor attention with enhanced newline attention: focuses on sentence boundaries and first token."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L15H11", np.zeros((n_empty, n_empty)).reshape(0, 0)

    attention = np.zeros((n, n))

    for i in range(n):
        # Base self-attention
        attention[i, i] = 0.1

        # Strong attention to first token
        attention[i, 0] = 0.4

        # Find periods and newlines in accessible positions
        for j in range(i + 1):
            token_text = tokens[j].strip()

            # Reduced attention to periods (was 0.6, now 0.3)
            if token_text == '.':
                attention[i, j] = 0.3

            # High attention to newlines  
            elif token_text == '\n':
                attention[i, j] = 0.5

            # Medium attention to other punctuation
            elif token_text in [',', '!', '?', ';', ':']:
                attention[i, j] = 0.2

        # Enhanced newline attention: give additional strong attention to ALL previous newlines
        for j in range(i):
            if tokens[j].strip() == '\n':
                attention[i, j] = max(attention[i, j], 0.4)

        # Additional attention to recent tokens with decay
        for j in range(max(0, i-3), i):
            attention[i, j] += 0.1 * (1.0 / (i - j + 1))

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L15H11", attention



def prog_L15H12(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Structural boundary and document beginning attention head."""
    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention_matrix = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        # Base attention distribution
        base_weights = np.zeros(i + 1)  # Can only attend to j <= i

        # Very high attention to first token
        if i > 0:
            base_weights[0] = 0.4

        # High attention to newlines and periods
        for j in range(i + 1):
            token = tokens[j].strip()
            if token in ['\n', '.']:
                base_weights[j] += 0.3
            elif token in [',', '!', '?']:
                base_weights[j] += 0.15

        # Self-attention boost
        if i < len(base_weights):
            base_weights[i] += 0.1

        # Attention to tokens that are sentence/paragraph starters
        for j in range(i + 1):
            if j < len(token_to_spacy) and token_to_spacy[j]:
                spacy_indices = token_to_spacy[j]
                for spacy_idx in spacy_indices:
                    if spacy_idx < len(doc):
                        spacy_token = doc[spacy_idx]
                        # Beginning of sentence
                        if spacy_token.is_sent_start:
                            base_weights[j] += 0.2
                        # Capitalized words (often start important phrases)
                        if spacy_token.text[0].isupper() and spacy_token.pos_ in ['NOUN', 'PROPN', 'VERB']:
                            base_weights[j] += 0.1

        # Add small uniform attention to all previous tokens
        for j in range(i + 1):
            base_weights[j] += 0.05

        # Normalize and assign
        if base_weights.sum() > 0:
            base_weights = base_weights / base_weights.sum()
        attention_matrix[i, :i + 1] = base_weights

    # Apply causal mask and ensure row-stochastic
    attention_matrix = apply_causal_mask(attention_matrix)
    attention_matrix = make_row_stochastic(attention_matrix)

    return "prog_L15H12", attention_matrix



def prog_L15H13(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary and first-token reference attention head."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention_matrix = np.zeros((n, n))

    for i in range(n):
        token_i = tokens[i]

        for j in range(i + 1):  # Causal mask
            token_j = tokens[j]
            weight = 0.0

            # High attention to sentence boundaries (newlines and periods)
            if token_j in ['\n', '.']:
                weight += 0.4

            # Strong attention from first few tokens to the very first token
            if j == 0 and i < 5:
                weight += 0.5

            # NEW: Extended first-token attention for all positions
            if j == 0 and i >= 5:
                # Strong base attention to first token from any position
                weight += 0.6
                # Additional semantic similarity boost
                sim = _char_sim(tokens[i], tokens[j])
                if sim > 0.3:
                    weight += 0.2 * sim

            # Moderate attention to other punctuation
            if token_j in [',', "'", '"', ';', ':', '!', '?']:
                weight += 0.2

            # Reduced self-attention baseline to prevent over-prediction
            if i == j:
                weight += 0.05

            # Small recency bias for nearby tokens
            if i - j <= 3:
                weight += 0.05 * (4 - (i - j)) / 4

            # Base attention for all valid positions
            weight += 0.05

            attention_matrix[i, j] = weight

    # Apply causal mask and normalize
    attention_matrix = apply_causal_mask(attention_matrix)
    attention_matrix = make_row_stochastic(attention_matrix)

    return "prog_L15H13", attention_matrix



def prog_L15H14(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary attention head with strong first-token attention - attends to newlines, periods, and heavily to the first token."""
    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L15H14", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Identify landmark tokens (newlines and periods)
    newline_indices = [i for i, tok in enumerate(tokens) if tok.strip() == '\n']
    period_indices = [i for i, tok in enumerate(tokens) if tok.strip() == '.']

    for i in range(n):
        # Base attention pattern - small uniform distribution
        for j in range(i + 1):
            attention[i, j] = 0.01

        # Strong attention to newlines (highest priority)
        for nl_idx in newline_indices:
            if nl_idx <= i:
                attention[i, nl_idx] += 0.6

        # Moderate attention to periods
        for p_idx in period_indices:
            if p_idx <= i:
                attention[i, p_idx] += 0.3

        # Special case: first token gets very high self-attention
        if i == 0:
            attention[i, i] = 1.0

        # NEW: Very strong attention to the first token (index 0) from all positions
        if i > 0:
            attention[i, 0] += 0.8

        # Boost attention to immediately previous token (reduced to avoid over-prediction)
        if i > 0:
            attention[i, i-1] += 0.05

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L15H14", attention



def prog_L15H15(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Boundary token attention head - attends to first tokens, newlines, and periods."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L15H15", np.zeros((n_empty, n_empty))

    attention_matrix = np.zeros((n, n))

    for i in range(n):
        # Find first token (index 0)
        first_token_weight = 0.8

        # Find newline tokens
        newline_indices = [j for j in range(i + 1) if tokens[j].strip() == '']

        # Find period tokens  
        period_indices = [j for j in range(i + 1) if tokens[j].strip() == '.']

        # Base attention to first token
        if i > 0:
            attention_matrix[i, 0] = first_token_weight
        else:
            attention_matrix[i, 0] = 1.0  # Self-attention for first token

        # Strong attention to newlines
        for j in newline_indices:
            if j < i:  # Causal constraint
                attention_matrix[i, j] = 0.5

        # Moderate attention to periods
        for j in period_indices:
            if j < i:  # Causal constraint
                attention_matrix[i, j] = 0.35

        # Small amount of self-attention for non-first tokens
        if i > 0:
            attention_matrix[i, i] = 0.1

        # Distribute remaining attention to recent tokens
        remaining_weight = max(0.0, 1.0 - attention_matrix[i].sum())
        if remaining_weight > 0 and i > 0:
            # Exponential decay for recent tokens
            for j in range(max(0, i-5), i):
                if attention_matrix[i, j] == 0:  # Don't override existing weights
                    weight = remaining_weight * (0.7 ** (i - j - 1)) / 5
                    attention_matrix[i, j] = weight

    # Apply causal mask and normalize
    attention_matrix = apply_causal_mask(attention_matrix)
    attention_matrix = make_row_stochastic(attention_matrix)

    return "prog_L15H15", attention_matrix



def prog_L15H16(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Semantic coherence head with strong beginning-of-sequence attention pattern."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L15H16", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        # Get spacy tokens aligned to this position
        spacy_indices = token_to_spacy[i]
        current_pos = spacy_indices[0] if spacy_indices else None
        current_spacy_token = doc[current_pos] if current_pos is not None else None

        for j in range(i + 1):  # Only look at previous tokens (causal)
            token_i = tokens[i]
            token_j = tokens[j]

            base_weight = 0.01

            # Strong attention to sentence boundaries
            if token_j in ['.', '\n', '!', '?']:
                base_weight += 0.3

            # Self-attention
            if i == j:
                base_weight += 0.05

            # Attention to semantically similar tokens
            sim = _char_sim(tokens[i], tokens[j])
            if sim > 0.3:  # Threshold for semantic similarity
                base_weight += 0.15 * sim

            # Attention between content words
            spacy_j_indices = token_to_spacy[j]
            if spacy_j_indices and current_spacy_token:
                spacy_j = doc[spacy_j_indices[0]]

                # Both are content words (nouns, verbs, adjectives)
                if (current_spacy_token.pos_ in ['NOUN', 'VERB', 'ADJ'] and 
                    spacy_j.pos_ in ['NOUN', 'VERB', 'ADJ']):
                    base_weight += 0.08

                # Syntactic dependencies
                if (current_spacy_token.head == spacy_j or 
                    spacy_j.head == current_spacy_token):
                    base_weight += 0.06

            # Strong beginning-of-sequence attention pattern
            if j <= 2:  # First few tokens get strong attention
                beginning_bonus = 0.4 if j == 0 else (0.3 if j == 1 else 0.2)
                # Scale by position in sequence - later tokens attend more strongly to beginning
                position_scale = min(1.0, i / 10.0 + 0.2)
                base_weight += beginning_bonus * position_scale

            # Distance decay
            distance = i - j
            if distance > 0:
                decay = 1.0 / (1.0 + 0.1 * distance)
                base_weight *= decay

            # First token gets extra attention (original logic preserved)
            if j == 0:
                base_weight += 0.05

            attention[i, j] = base_weight

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L15H16", attention



def prog_L15H17(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary and punctuation attention with strong first-token bias."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L15H17", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        for j in range(i + 1):  # Causal mask
            weight = 0.0

            # Strong attention to newlines and periods
            if tokens[j] == '\n':
                weight += 0.25
            elif tokens[j] == '.':
                weight += 0.15

            # Self-attention for first token
            if i == 0 and j == 0:
                weight += 0.8
            elif i == j:
                weight += 0.05

            # Recency bias - attend more to recent tokens
            if i != j:
                distance = i - j
                if distance == 1:
                    weight += 0.08
                elif distance <= 3:
                    weight += 0.04
                elif distance <= 5:
                    weight += 0.02

            # Attention to commas and quotes
            if tokens[j] in [',', '"', "'", '!"', '."']:
                weight += 0.06

            # Syntactic relationships via spacy
            if token_to_spacy[i] and token_to_spacy[j]:
                spacy_i = token_to_spacy[i][0] if token_to_spacy[i] else None
                spacy_j = token_to_spacy[j][0] if token_to_spacy[j] else None

                if spacy_i is not None and spacy_j is not None and spacy_i < len(doc) and spacy_j < len(doc):
                    tok_i = doc[spacy_i]
                    tok_j = doc[spacy_j]

                    # Attention between related words
                    if tok_j.head == tok_i or tok_i.head == tok_j:
                        weight += 0.03

                    # Attention to subjects and objects
                    if tok_j.dep_ in ['nsubj', 'nsubjpass', 'dobj', 'pobj']:
                        weight += 0.02

            # Semantic similarity boost
            sim = _char_sim(tokens[i], tokens[j])
            if sim > 0.7:
                weight += 0.03 * sim

            # Strong first-token attention pattern
            if j == 0 and i > 0:
                # Add significant attention to first token from all later positions
                weight += 0.3

            # Base attention for all valid positions
            weight += 0.01

            attention[i, j] = weight

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L15H17", attention



def prog_L15H18(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """First-token and sentence boundary attention with self-attention bias."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L15H18", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        # Strong self-attention
        attention[i, i] = 1.0

        # High attention to first token
        if i > 0:
            attention[i, 0] = 0.4

        # Find sentence boundaries (periods, newlines)
        for j in range(i):
            token = tokens[j].strip()
            if token in ['.', '!', '?', '\n']:
                attention[i, j] += 0.3

        # Add attention based on linguistic similarity and position
        for j in range(i):
            if i != j:
                # Small boost for nearby tokens
                distance = i - j
                if distance <= 3:
                    attention[i, j] += 0.1 / distance

                # Boost for semantically similar tokens
                sim = _char_sim(tokens[i], tokens[j])
                if sim > 0.7:
                    attention[i, j] += 0.2 * sim

                # Small boost for function words and common structures
                if len(token_to_spacy[j]) > 0:
                    spacy_token = doc[token_to_spacy[j][0]]
                    if spacy_token.pos_ in ['DET', 'PRON', 'ADP', 'CCONJ']:
                        attention[i, j] += 0.05

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L15H18", attention



def prog_L15H19(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Structural boundary detection head with syntactic awareness, recency bias, and first-token anchoring."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        for j in range(i + 1):  # causal mask
            weight = 0.0

            # Base recency bias - closer tokens get higher weight
            distance = i - j
            if distance == 0:
                weight += 0.03  # self attention
            else:
                weight += 0.02 / (1 + distance * 0.5)

            # Strong attention to structural boundaries
            if tokens[j] in ['\n', '.', '!', '?', '"', "'", ':', ';']:
                weight += 0.15

            # Attention to first token of sentences (after newlines/periods)
            if j > 0 and tokens[j-1] in ['\n', '.', '!', '?']:
                weight += 0.12

            # Special attention from punctuation to content words
            if tokens[i] in ['.', '!', '?'] and j < i - 1:
                spacy_indices = token_to_spacy[j]
                if spacy_indices:
                    spacy_token = doc[spacy_indices[0]]
                    if spacy_token.pos_ in ['NOUN', 'VERB', 'ADJ']:
                        weight += 0.08

            # Syntactic relationships
            spacy_i = token_to_spacy[i]
            spacy_j = token_to_spacy[j]
            if spacy_i and spacy_j:
                token_i = doc[spacy_i[0]]
                token_j = doc[spacy_j[0]]

                # Head-dependent relationships
                if token_j.head == token_i or token_i.head == token_j:
                    weight += 0.06

                # Subject-verb relationships
                if token_j.dep_ in ['nsubj'] and token_i.pos_ == 'VERB':
                    weight += 0.05

                # Object relationships
                if token_j.dep_ in ['dobj', 'pobj'] and token_i.pos_ == 'VERB':
                    weight += 0.04

            # Semantic similarity boost
            if i != j:
                sim = _char_sim(tokens[i], tokens[j])
                if sim > 0.7:
                    weight += 0.04 * sim

            # Boost for quotation-related patterns
            if '"' in tokens[i] or "'" in tokens[i]:
                if tokens[j] in ['said', 'asked', 'told'] or j == 0:
                    weight += 0.08

            # NEW: Strong attention to first token, especially in narrative/quotation contexts
            if j == 0 and i > 0:
                # Base first-token attention
                first_token_boost = 0.20

                # Extra boost if first token looks like part of quotation/narrative
                if tokens[0] in ['"', "'"] or any(c.isalpha() for c in tokens[0]):
                    first_token_boost += 0.15

                # Distance decay for first token attention
                first_token_boost *= (1.0 / (1 + distance * 0.2))

                weight += first_token_boost

            attention[i, j] = weight

    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L15H19", attention



def prog_L15H2(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary and semantic coherence attention head with beginning-of-sequence focus."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L15H2", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Get spacy alignment for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    # Identify sentence boundary tokens (periods, newlines)
    boundary_tokens = set()
    for i, token in enumerate(tokens):
        if token.strip() in ['.', '\n', '!', '?']:
            boundary_tokens.add(i)

    for i in range(n):
        for j in range(i + 1):  # Causal mask
            weight = 0.0

            # Strong attention to the very first token from positions 1-4
            if j == 0 and 1 <= i <= 4:
                # Use embedding similarity to boost related tokens
                sim = _char_sim(tokens[i], tokens[j])
                if sim > 0.3:
                    weight += 0.8  # Very high attention for similar tokens
                else:
                    weight += 0.4  # Moderate attention even for dissimilar tokens

            # Very high attention to sentence boundary tokens
            if j in boundary_tokens:
                if tokens[j].strip() == '.':
                    weight += 0.25
                elif tokens[j].strip() == '\n':
                    weight += 0.30
                else:  # Other punctuation
                    weight += 0.20

            # Strong attention between semantically similar adjacent tokens
            if abs(i - j) == 1 and i > 0:
                sim = _char_sim(tokens[i], tokens[j])
                if sim > 0.7:
                    weight += 0.6
                elif sim > 0.5:
                    weight += 0.3

            # First token attention (common pattern) - reduced to avoid over-prediction
            if j == 0 and i > 5:
                weight += 0.10

            # Self-attention baseline - reduced for early tokens to avoid over-prediction
            if i == j:
                if i <= 4:
                    weight += 0.01  # Reduced self-attention for early tokens
                else:
                    weight += 0.02

            # Moderate attention to nearby punctuation
            if tokens[j].strip() in [',', '"', "'", ':', ';']:
                weight += 0.08

            # Slight recency bias for recent tokens
            if i - j <= 3 and i != j:
                weight += 0.01 * (4 - (i - j)) / 4

            # Use spacy features for additional linguistic patterns
            if token_to_spacy[i] and token_to_spacy[j]:
                spacy_i = token_to_spacy[i][0] if token_to_spacy[i] else None
                spacy_j = token_to_spacy[j][0] if token_to_spacy[j] else None

                if spacy_i is not None and spacy_j is not None and spacy_i < len(doc) and spacy_j < len(doc):
                    # Attention to sentence starts
                    if doc[spacy_j].sent.start == spacy_j and i > j + 2:
                        weight += 0.12

                    # Attention from verbs to related tokens
                    if doc[spacy_i].pos_ == 'VERB' and doc[spacy_j].pos_ in ['NOUN', 'PRON']:
                        weight += 0.05

            attention[i, j] = weight

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L15H2", attention



def prog_L15H20(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence structure head: attends strongly to first token, sentence boundaries, and local syntactic dependencies."""
    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L15H20", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Get spacy alignment for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        # Reduced self-attention baseline
        attention[i, i] = 0.15

        # Much stronger attention to first token
        attention[i, 0] += 0.5

        # Higher attention to sentence boundaries (periods, newlines)
        for j in range(i + 1):
            if tokens[j] in ['.', '\n', '!', '?']:
                attention[i, j] += 0.6

        # Recent token bias (decaying attention to previous few tokens)
        for offset in range(1, min(4, i + 1)):
            j = i - offset
            attention[i, j] += 0.1 / offset

        # Syntactic dependencies via spacy
        if token_to_spacy[i]:
            spacy_idx = token_to_spacy[i][0]
            if spacy_idx < len(doc):
                spacy_token = doc[spacy_idx]

                # Attend to syntactic head
                if spacy_token.head != spacy_token:
                    head_spacy_idx = spacy_token.head.i
                    # Find corresponding LM token
                    for j in range(i + 1):
                        if token_to_spacy[j] and head_spacy_idx in token_to_spacy[j]:
                            attention[i, j] += 0.15
                            break

                # Attend to children (especially subjects, objects)
                for child in spacy_token.children:
                    if child.dep_ in ['nsubj', 'dobj', 'amod', 'nmod']:
                        child_spacy_idx = child.i
                        for j in range(i + 1):
                            if token_to_spacy[j] and child_spacy_idx in token_to_spacy[j]:
                                attention[i, j] += 0.1
                                break

        # Semantic similarity boost for related tokens
        for j in range(i):
            sim = _char_sim(tokens[i], tokens[j])
            if sim > 0.7:
                attention[i, j] += 0.1 * sim

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L15H20", attention



def prog_L15H21(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Local sequential attention with boundary and semantic affinity patterns."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L15H21", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        current_token = tokens[i].strip()

        # Strong self-attention baseline
        attention[i, i] = 0.1

        # Strong attention to immediately previous token
        if i > 0:
            prev_token = tokens[i-1].strip()
            attention[i, i-1] = 0.4

            # Extra boost if semantically similar to previous token
            sim = _char_sim(tokens[i], tokens[i-1])
            if sim > 0.3:
                attention[i, i-1] += 0.3

        # Attention to sentence boundaries and punctuation
        for j in range(i):
            target_token = tokens[j].strip()

            # High attention to newlines and periods
            if target_token in ['\n', '.', '!', '?']:
                attention[i, j] += 0.2

            # Attention to first token
            if j == 0:
                attention[i, j] += 0.1

        # Additional patterns for adjacent tokens with semantic relationship
        if i > 0:
            # Check if current and previous tokens are semantically related
            sim = _char_sim(tokens[i], tokens[i-1])
            if sim > 0.4:
                attention[i, i-1] += 0.2

        # Look for compound words or phrases (adjacent tokens with high similarity)
        for j in range(max(0, i-3), i):
            if j != i-1:  # Already handled above
                sim = _char_sim(tokens[i], tokens[j])
                if sim > 0.5:
                    attention[i, j] += 0.15

        # Boost attention to nearby function words and punctuation
        for j in range(max(0, i-5), i):
            target_token = tokens[j].strip()
            if target_token in [',', ';', ':', '-', '(', ')', '"', "'", '``', "''", ''', ''']:
                attention[i, j] += 0.05

        # Additional attention to tokens that start sentences/clauses
        for j in range(i):
            if j > 0:
                prev_token = tokens[j-1].strip()
                if prev_token in ['\n', '.', '!', '?']:
                    attention[i, j] += 0.1

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L15H21", attention



def prog_L15H22(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence/paragraph boundary attention head focusing on segment beginnings and structural boundaries."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    # Identify structural boundary tokens (newlines and sentence-ending punctuation)
    boundary_tokens = []
    for i, token in enumerate(tokens):
        if token.strip() in ['\n', '.', '!', '?']:
            boundary_tokens.append(i)

    # Identify segment beginnings (first token and tokens after newlines)
    segment_beginnings = [0]  # First token is always a segment beginning
    for i, token in enumerate(tokens):
        if token.strip() == '\n' and i + 1 < n:
            segment_beginnings.append(i + 1)  # Token after newline

    for i in range(n):
        # Strong attention to segment beginnings (first tokens of segments)
        for j in segment_beginnings:
            if j <= i:  # causal constraint
                attention[i, j] = 0.4  # High attention to segment beginnings

        # Medium attention to boundary tokens (newlines and sentence endings)
        for j in boundary_tokens:
            if j <= i:  # causal constraint
                if tokens[j].strip() == '\n':
                    attention[i, j] = 0.2  # Medium attention to newlines
                elif tokens[j].strip() in ['.', '!', '?']:
                    attention[i, j] = 0.1  # Lower attention to sentence endings

        # Self-attention
        attention[i, i] = 0.1

        # Local context attention (previous few tokens)
        for j in range(max(0, i-3), i):
            if j not in boundary_tokens and j not in segment_beginnings:
                attention[i, j] = 0.05

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L15H22", attention



def prog_L15H23(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Attention head that focuses on sentence boundaries and semantically similar previous tokens."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    # Get spacy alignment for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        token = tokens[i]

        # Strong attention to first token
        if i > 0:
            attention[i, 0] = 0.6

        # Strong attention to sentence boundaries (periods, newlines)
        for j in range(i + 1):
            if tokens[j] in ['.', '\n']:
                if j == 0:
                    attention[i, j] += 0.4
                else:
                    attention[i, j] += 0.3

        # Self-attention
        attention[i, i] = 0.05

        # Get spacy features for current token
        spacy_indices = token_to_spacy[i]
        current_pos = None
        current_dep = None
        if spacy_indices:
            spacy_token = doc[spacy_indices[0]]
            current_pos = spacy_token.pos_
            current_dep = spacy_token.dep_

        # Attention to semantically similar previous tokens
        for j in range(i):
            similarity = _char_sim(tokens[i], tokens[j])
            if similarity > 0.5:
                attention[i, j] += similarity * 0.2

        # Special attention patterns for content words
        if current_pos in ['NOUN', 'VERB', 'ADJ']:
            # Look for related previous content words
            for j in range(max(0, i - 10), i):
                j_spacy_indices = token_to_spacy[j]
                if j_spacy_indices:
                    j_spacy_token = doc[j_spacy_indices[0]]
                    if j_spacy_token.pos_ in ['NOUN', 'VERB', 'ADJ']:
                        # Add attention based on semantic similarity
                        sim = _char_sim(tokens[i], tokens[j])
                        if sim > 0.3:
                            attention[i, j] += sim * 0.15

        # Attention to recent tokens with decay
        for j in range(max(0, i - 5), i):
            distance = i - j
            decay = 1.0 / (distance + 1)
            attention[i, j] += 0.02 * decay

        # Special handling for punctuation and conjunctions
        if token in [',', 'and', 'but']:
            # Attend to nearby content words
            for j in range(max(0, i - 3), i):
                j_spacy_indices = token_to_spacy[j]
                if j_spacy_indices:
                    j_spacy_token = doc[j_spacy_indices[0]]
                    if j_spacy_token.pos_ in ['NOUN', 'VERB']:
                        attention[i, j] += 0.1

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L15H23", attention



def prog_L15H24(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary and punctuation attention with strong beginning-of-sequence bias."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L15H24", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Identify structural tokens
    newline_indices = [i for i, t in enumerate(tokens) if t.strip() == '']
    period_indices = [i for i, t in enumerate(tokens) if t.strip() == '.']
    comma_indices = [i for i, t in enumerate(tokens) if t.strip() == ',']

    for i in range(n):
        # Base attention distribution
        for j in range(i + 1):  # Causal mask
            # Distance-based decay
            dist = i - j
            base_weight = 0.01 / (1 + dist * 0.1)
            attention[i, j] = base_weight

        # Strong attention to newlines
        for nl_idx in newline_indices:
            if nl_idx <= i:
                attention[i, nl_idx] += 0.3

        # Strong attention to periods
        for p_idx in period_indices:
            if p_idx <= i:
                attention[i, p_idx] += 0.2

        # Moderate attention to commas
        for c_idx in comma_indices:
            if c_idx <= i:
                attention[i, c_idx] += 0.05

        # First token attention
        if i > 0:
            attention[i, 0] += 0.1

        # Previous token attention
        if i > 0:
            attention[i, i-1] += 0.05

        # Self attention for important tokens
        current_token = tokens[i].strip()
        if current_token in ['.', '\n', ',', '!', '?']:
            attention[i, i] += 0.1

        # Special case: if current token is newline, attend strongly to previous period
        if tokens[i].strip() == '':
            for p_idx in period_indices:
                if p_idx < i:
                    attention[i, p_idx] += 0.2

        # NEW: Enhanced beginning-of-sequence attention for later tokens
        if i > 2:  # Only for tokens beyond the very beginning
            # Strong attention to first few tokens, especially the first
            if i <= n - 1:
                attention[i, 0] += 0.4  # Much stronger attention to first token
                if n > 1:
                    attention[i, 1] += 0.1  # Some attention to second token
                if n > 2:
                    attention[i, 2] += 0.05  # Weaker attention to third token

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L15H24", attention



def prog_L15H25(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """First token accumulation head with sentence boundary attention."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        # Very strong self-attention for first token
        if i == 0:
            attention[i, i] = 1.0
            continue

        # Strong attention to first token for all other tokens
        attention[i, 0] += 0.6

        # High attention to sentence boundaries (periods and newlines)
        for j in range(i + 1):
            token = tokens[j].strip()

            # Strong attention to newlines and periods
            if token == '\n':
                attention[i, j] += 0.3
            elif token == '.':
                attention[i, j] += 0.25

        # Semantic similarity component
        for j in range(i + 1):
            sim = _char_sim(tokens[i], tokens[j])
            if sim > 0.5:  # High semantic similarity
                attention[i, j] += 0.1 * sim

        # Reduced self-attention for non-first tokens
        attention[i, i] += 0.02

        # Previous token attention
        if i > 0:
            attention[i, i-1] += 0.03

        # Boost attention for certain linguistic relationships
        if token_to_spacy[i]:
            spacy_i = token_to_spacy[i][0]
            if spacy_i < len(doc):
                current_token = doc[spacy_i]

                for j in range(i):
                    if token_to_spacy[j]:
                        spacy_j = token_to_spacy[j][0]
                        if spacy_j < len(doc):
                            target_token = doc[spacy_j]

                            # Syntactic dependencies
                            if target_token == current_token.head:
                                attention[i, j] += 0.04

                            # Same POS tag
                            if current_token.pos_ == target_token.pos_ and current_token.pos_ in ['NOUN', 'VERB']:
                                attention[i, j] += 0.02

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L15H25", attention



def prog_L15H26(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Structural and semantic attention head with strong beginning-of-sentence attention pattern."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    for i in range(n):
        current_token = tokens[i].strip()

        for j in range(i + 1):  # Causal mask
            target_token = tokens[j].strip()
            weight = 0.0

            # Strong attention to newlines and sentence punctuation
            if target_token in ['\n', '.', '!', '?']:
                weight += 0.3

            # Strong attention to commas and other punctuation
            elif target_token in [',', ';', ':']:
                weight += 0.15

            # Semantic similarity boost
            if i != j:  # Don't compute similarity for self-attention
                sim = _char_sim(tokens[i], tokens[j])
                if sim > 0.3:  # Threshold for meaningful similarity
                    weight += 0.2 * sim

            # Self-attention baseline
            if i == j:
                weight += 0.1

            # Recency bias - slight preference for recent tokens
            if i > j:
                distance = i - j
                if distance <= 5:
                    weight += 0.05 / (distance + 1)

            # Enhanced first token attention - much stronger for quoted/dialog sentences
            if j == 0:
                base_first_token_weight = 0.08
                # Check if first token suggests this is quoted text or dialog
                if target_token.startswith('"') or target_token in ['Mommy', 'Daddy'] or len(target_token) > 2:
                    # Strong boost for later tokens attending to sentence-starting words
                    if i > 5:  # Tokens well into the sentence
                        base_first_token_weight += 0.4
                    elif i > 2:  # Tokens moderately into the sentence  
                        base_first_token_weight += 0.25
                    else:  # Early tokens get smaller boost
                        base_first_token_weight += 0.1
                weight += base_first_token_weight

            # Boost for immediately previous token
            if i == j + 1:
                weight += 0.1

            attention[i, j] = weight

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L15H26", attention



def prog_L15H27(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Structural boundary detection head focusing on sentence/paragraph endings with recency bias and strong first-token attention."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L15H27", np.zeros((n_empty, n_empty))

    attention_matrix = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        # Base attention distribution
        weights = np.zeros(i + 1)

        # Strong attention to structural punctuation
        for j in range(i + 1):
            token_j = tokens[j].strip()

            # Very high attention to sentence-ending punctuation
            if token_j in ['.', '!', '?']:
                weights[j] += 5.0

            # High attention to newlines and paragraph breaks
            elif token_j == '\n' or (token_j == '' and j > 0):
                weights[j] += 3.0

            # Moderate attention to other punctuation
            elif token_j in [',', ';', ':', '"', "'", '(', ')']:
                weights[j] += 1.0

        # Strong first-token bias - significantly increased
        if i > 0:
            # Much stronger first-token attention, especially for content words
            if len(token_to_spacy[i]) > 0:
                spacy_i = token_to_spacy[i][0]
                if spacy_i < len(doc):
                    token_i = doc[spacy_i]
                    # Content words have even stronger first-token bias
                    if token_i.pos_ in ['NOUN', 'VERB', 'ADJ', 'ADV', 'PRON']:
                        weights[0] += 6.0
                    else:
                        weights[0] += 4.0
                else:
                    weights[0] += 4.0
            else:
                weights[0] += 4.0

        # Self-attention
        weights[i] += 1.0

        # Recency bias - stronger for recent tokens
        for j in range(max(0, i-5), i):
            decay = 1.0 / (i - j + 1)
            weights[j] += 0.5 * decay

        # Semantic similarity boost
        for j in range(i):
            if i != j:
                sim = _char_sim(tokens[i], tokens[j])
                if sim > 0.3:
                    weights[j] += 0.8 * sim

        # Special boost for specific linguistic patterns
        if len(token_to_spacy[i]) > 0:
            spacy_i = token_to_spacy[i][0]
            if spacy_i < len(doc):
                token_i = doc[spacy_i]

                # Verbs attend more to subjects and objects
                if token_i.pos_ in ['VERB', 'AUX']:
                    for j in range(i):
                        if len(token_to_spacy[j]) > 0:
                            spacy_j = token_to_spacy[j][0]
                            if spacy_j < len(doc):
                                token_j = doc[spacy_j]
                                if token_j.dep_ in ['nsubj', 'dobj', 'iobj']:
                                    weights[j] += 0.3

                # Pronouns attend to potential antecedents
                if token_i.pos_ == 'PRON':
                    for j in range(i):
                        if len(token_to_spacy[j]) > 0:
                            spacy_j = token_to_spacy[j][0]
                            if spacy_j < len(doc):
                                token_j = doc[spacy_j]
                                if token_j.pos_ in ['NOUN', 'PROPN']:
                                    weights[j] += 0.2

        # Ensure minimum attention distribution
        if np.sum(weights) == 0:
            weights[i] = 1.0

        attention_matrix[i, :i+1] = weights

    # Apply causal mask and normalize
    attention_matrix = apply_causal_mask(attention_matrix)
    attention_matrix = make_row_stochastic(attention_matrix)

    return "prog_L15H27", attention_matrix



def prog_L15H28(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary and structural attention head with focus on periods and newlines."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L15H28", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Get spacy parse and alignment
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        token = tokens[i].strip()

        # Strong self-attention for first token
        if i == 0:
            attention[i, i] = 1.0
            continue

        weights = np.zeros(i + 1)  # Can only attend to tokens <= i

        # High attention to periods and newlines
        for j in range(i + 1):
            target_token = tokens[j].strip()
            if target_token in ['.', '\n']:
                weights[j] += 0.3

        # Moderate attention to commas and other punctuation
        for j in range(i + 1):
            target_token = tokens[j].strip()
            if target_token in [',', '!', '?', ';', ':']:
                weights[j] += 0.1

        # Self-attention baseline
        weights[i] += 0.05

        # Attention to nearby tokens (recency bias)
        for j in range(max(0, i-3), i):
            weights[j] += 0.02 * (1 + j - max(0, i-3))

        # Syntactic attention using spacy features
        if token_to_spacy[i]:
            spacy_idx = token_to_spacy[i][0]
            if spacy_idx < len(doc):
                spacy_token = doc[spacy_idx]

                # If current token is a verb, attend to its subject
                if spacy_token.pos_ in ['VERB']:
                    for child in spacy_token.children:
                        if child.dep_ in ['nsubj', 'nsubjpass']:
                            # Find corresponding tokens
                            child_start = child.idx
                            for j in range(i):
                                if j < len(token_to_spacy):
                                    for spacy_j in token_to_spacy[j]:
                                        if spacy_j < len(doc) and doc[spacy_j].idx <= child_start < doc[spacy_j].idx + len(doc[spacy_j].text):
                                            weights[j] += 0.08

                # If current token is a noun, attend to its modifiers
                if spacy_token.pos_ in ['NOUN', 'PROPN']:
                    if spacy_token.head != spacy_token:
                        head_start = spacy_token.head.idx
                        for j in range(i):
                            if j < len(token_to_spacy):
                                for spacy_j in token_to_spacy[j]:
                                    if spacy_j < len(doc) and doc[spacy_j].idx <= head_start < doc[spacy_j].idx + len(doc[spacy_j].text):
                                        weights[j] += 0.05

        # Special boost for first token
        if len(weights) > 0:
            weights[0] += 0.1

        # Normalize weights
        if weights.sum() > 0:
            attention[i, :i+1] = weights / weights.sum()
        else:
            attention[i, i] = 1.0

    # Apply causal mask and make row stochastic
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L15H28", attention



def prog_L15H29(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Attention head that focuses on sentence boundaries and discourse structure markers."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    # Find sentence boundary positions (newlines and sentence-final punctuation)
    boundary_positions = []
    for i, token in enumerate(tokens):
        if token.strip() in ['\n', '.', '!', '?'] or i == 0:
            boundary_positions.append(i)

    for i in range(n):
        # Strong attention to sentence boundaries, especially first token and newlines
        for boundary_pos in boundary_positions:
            if boundary_pos <= i:
                if boundary_pos == 0:  # First token gets strongest attention
                    attention[i, boundary_pos] += 0.6
                elif tokens[boundary_pos].strip() == '\n':  # Newlines get strong attention
                    attention[i, boundary_pos] += 0.4
                elif tokens[boundary_pos].strip() in ['.', '!', '?']:  # Sentence ends
                    attention[i, boundary_pos] += 0.2

        # Self-attention component
        attention[i, i] += 0.1

        # Some attention to immediately preceding token
        if i > 0:
            attention[i, i-1] += 0.05

        # Slight attention to tokens within same sentence segment
        current_segment_start = 0
        for boundary_pos in boundary_positions:
            if boundary_pos <= i:
                current_segment_start = boundary_pos
            else:
                break

        for j in range(current_segment_start, i):
            if j != i and j not in boundary_positions:
                attention[i, j] += 0.02

    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L15H29", attention



def prog_L15H3(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Document structure head: attends to sentence boundaries, newlines, and first tokens."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L15H3", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    for i in range(n):
        token = tokens[i]

        # Base uniform attention to valid positions
        for j in range(i + 1):
            attention[i, j] = 0.01

        # Strong attention to first token
        if i > 0:
            attention[i, 0] = 0.6
        else:
            attention[i, 0] = 1.0

        # High attention to sentence boundaries (periods and newlines)
        for j in range(i + 1):
            target_token = tokens[j].strip()
            if target_token in ['.', '\n']:
                attention[i, j] = 0.4

        # Self-attention boost for structural tokens
        current_token = token.strip()
        if current_token in ['.', '\n'] or i == 0:
            attention[i, i] = 0.5

        # Moderate attention to nearby sentence boundaries
        for j in range(max(0, i-10), i):
            target_token = tokens[j].strip()
            if target_token in ['.', '\n']:
                distance_decay = 1.0 / (i - j + 1)
                attention[i, j] += 0.2 * distance_decay

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L15H3", attention



def prog_L15H30(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Attention head combining first-token bias, sentence boundaries, and syntactic relationships."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L15H30", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        # Strong self-attention baseline
        attention[i, i] = 0.1

        # Very strong attention to first token
        if i > 0:
            attention[i, 0] = 0.4

        # Strong attention to sentence boundaries (periods, newlines)
        for j in range(i + 1):
            if tokens[j] in ['.', '\n']:
                attention[i, j] += 0.3

        # Attention to syntactically related tokens
        if token_to_spacy[i]:
            spacy_i = token_to_spacy[i][0]
            if spacy_i < len(doc):
                spacy_token = doc[spacy_i]

                # Attend to syntactic head
                if spacy_token.head != spacy_token:
                    head_idx = spacy_token.head.i
                    # Find corresponding LM token
                    for j in range(i + 1):
                        if token_to_spacy[j] and head_idx in token_to_spacy[j]:
                            attention[i, j] += 0.2

                # Attend to syntactic children
                for child in spacy_token.children:
                    child_idx = child.i
                    for j in range(i + 1):
                        if token_to_spacy[j] and child_idx in token_to_spacy[j]:
                            attention[i, j] += 0.15

        # Semantic similarity attention
        for j in range(i):
            similarity = _char_sim(tokens[i], tokens[j])
            if similarity > 0.5:
                attention[i, j] += similarity * 0.1

        # Positional bias - attend more to recent tokens
        for j in range(max(0, i - 5), i):
            recency_weight = 0.05 * (1 - (i - j) / 6)
            attention[i, j] += recency_weight

        # Punctuation tokens get extra attention
        for j in range(i + 1):
            if tokens[j] in [',', ';', ':', '!', '?']:
                attention[i, j] += 0.1

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L15H30", attention



def prog_L15H31(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary and first-token attention with strong beginning-of-sequence focus."""
    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L15H31", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        # Base self-attention
        attention[i, i] = 0.1

        # Strong attention to sentence-ending punctuation (periods)
        for j in range(i + 1):
            if tokens[j].strip() == '.':
                attention[i, j] += 0.4

        # Strong attention to first token from early positions
        if i < 10 and n > 0:
            attention[i, 0] += 0.3

        # NEW: Much stronger attention to first token from all positions
        # This appears to be a key pattern this head implements
        if n > 0 and i > 0:
            attention[i, 0] += 0.4

        # Attention to newlines
        for j in range(i + 1):
            if tokens[j].strip() == '\n':
                attention[i, j] += 0.15

        # Syntactic patterns using spacy alignment
        if token_to_spacy[i]:
            spacy_i = token_to_spacy[i][0]
            if spacy_i < len(doc):
                current_token = doc[spacy_i]

                # Pronouns attend to nearby nouns/proper nouns
                if current_token.pos_ in ['PRON']:
                    for j in range(max(0, i-10), i):
                        if token_to_spacy[j]:
                            spacy_j = token_to_spacy[j][0]
                            if spacy_j < len(doc) and doc[spacy_j].pos_ in ['NOUN', 'PROPN']:
                                attention[i, j] += 0.2

                # Verbs attend to their subjects
                if current_token.pos_ == 'VERB':
                    for child in current_token.children:
                        if child.dep_ in ['nsubj', 'nsubjpass']:
                            for j in range(i):
                                if token_to_spacy[j]:
                                    spacy_j = token_to_spacy[j][0]
                                    if spacy_j < len(doc) and doc[spacy_j] == child:
                                        attention[i, j] += 0.15

        # Positional decay for recent tokens
        for j in range(max(0, i-5), i):
            attention[i, j] += 0.05 * (1.0 / (i - j + 1))

        # Semantic similarity boost
        for j in range(i):
            sim = _char_sim(tokens[i], tokens[j])
            if sim > 0.7:
                attention[i, j] += 0.1 * sim

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L15H31", attention



def prog_L15H4(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary and punctuation attention head with strong first-token attention."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L15H4", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Get spacy parse for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        for j in range(i + 1):  # Causal mask
            weight = 0.0

            # Very strong self-attention for first token
            if i == 0 and j == 0:
                weight = 1.0

            # Strong attention from content tokens to first token
            elif j == 0 and i > 0:
                if tokens[i] not in ['\n', '.', ' ', '', '"', ',', '!', '?']:
                    # Base strong attention to first token
                    weight = 0.4
                    # Additional boost for later tokens
                    if i > 10:
                        weight = min(0.6, weight + 0.1)
                else:
                    weight = 0.1

            # Strong attention to sentence boundaries (newlines and periods)
            elif tokens[j] in ['\n', '.']:
                if i > j:  # Not self-attention to boundary
                    weight = 0.4
                elif i == j:  # Self-attention to boundary
                    weight = 0.3

            # Moderate attention from content tokens to nearby boundaries
            elif any(tokens[k] in ['\n', '.'] for k in range(max(0, j-2), min(n, j+3))):
                if tokens[i] not in ['\n', '.', ' ', '']:
                    weight = 0.15

            # Syntactic relationships using spacy
            elif token_to_spacy[i] and token_to_spacy[j]:
                spacy_i = token_to_spacy[i][0]
                spacy_j = token_to_spacy[j][0]

                if spacy_i < len(doc) and spacy_j < len(doc):
                    tok_i = doc[spacy_i]
                    tok_j = doc[spacy_j]

                    # Head-dependent relationships
                    if tok_i.head == tok_j or tok_j.head == tok_i:
                        weight = 0.1
                    # Subject-verb relationships
                    elif tok_i.dep_ == 'nsubj' and tok_j.pos_ == 'VERB':
                        weight = 0.08
                    elif tok_j.dep_ == 'nsubj' and tok_i.pos_ == 'VERB':
                        weight = 0.08

            # Embedding similarity for related tokens
            if weight < 0.05:
                sim = _char_sim(tokens[i], tokens[j])
                if sim > 0.7:
                    weight = max(weight, 0.06)
                elif sim > 0.5:
                    weight = max(weight, 0.03)

            # Small recency bias
            if j == i - 1:
                weight += 0.02

            # Very small baseline attention
            if weight == 0.0:
                weight = 0.01

            attention[i, j] = weight

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L15H4", attention



def prog_L15H5(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary and discourse structure attention with punctuation-specific self-attention."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L15H5", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Find sentence boundaries (periods, newlines) and first tokens
    sentence_boundaries = []
    first_tokens = []

    for i, token in enumerate(tokens):
        if token.strip() in ['.', '!', '?', '\n']:
            sentence_boundaries.append(i)
        # First token is always index 0, plus tokens after sentence boundaries
        if i == 0 or (i > 0 and tokens[i-1].strip() in ['.', '!', '?', '\n']):
            first_tokens.append(i)

    for i in range(n):
        current_token = tokens[i].strip()

        # Very high attention to sentence boundaries (newlines and periods)
        for boundary_idx in sentence_boundaries:
            if boundary_idx <= i:  # Causal constraint
                if current_token in ['\n']:
                    attention[i, boundary_idx] += 0.4
                else:
                    attention[i, boundary_idx] += 0.3

        # High attention to first tokens of sentences
        for first_idx in first_tokens:
            if first_idx <= i:  # Causal constraint
                attention[i, first_idx] += 0.2

        # Self-attention for sentence boundaries with punctuation-specific weights
        if current_token in ['.', '!', '?', '\n']:
            if current_token == '!':
                # Exclamation marks have much lower self-attention
                attention[i, i] += 0.05
            else:
                attention[i, i] += 0.3

        # Moderate attention to previous token
        if i > 0:
            attention[i, i-1] += 0.1

        # Some attention to nearby tokens within same sentence
        current_sentence_start = 0
        for first_idx in first_tokens:
            if first_idx <= i:
                current_sentence_start = first_idx

        # Attend to tokens in current sentence with decay
        for j in range(current_sentence_start, i):
            if j != i-1:  # Don't double-count previous token
                distance = i - j
                decay_factor = max(0.01, 0.05 / distance)
                attention[i, j] += decay_factor

        # Small boost for punctuation attending to related tokens
        if current_token in [',', ';', ':', '"', "'", '(', ')', '[', ']']:
            for j in range(max(0, i-5), i):
                attention[i, j] += 0.02

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L15H5", attention



def prog_L15H6(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary and structure attention head that focuses on periods, newlines, first tokens, and gives content words strong attention to the initial period."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L15H6", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    # Identify sentence boundaries and important structural tokens
    sentence_ends = []
    newlines = []
    first_token_idx = 0

    for i, token in enumerate(tokens):
        if token.strip() == '.' and i > 0:
            sentence_ends.append(i)
        elif token.strip() == '\n':
            newlines.append(i)

    for i in range(n):
        token = tokens[i]

        # Very high attention to sentence-ending periods
        for period_idx in sentence_ends:
            if period_idx <= i:
                distance = i - period_idx
                # Stronger for recent sentence endings
                weight = 0.6 * np.exp(-0.1 * distance)
                attention[i, period_idx] += weight

        # High attention to newlines
        for nl_idx in newlines:
            if nl_idx <= i:
                distance = i - nl_idx
                weight = 0.5 * np.exp(-0.05 * distance)
                attention[i, nl_idx] += weight

        # Special attention from word-beginning tokens to first token
        if len(token_to_spacy[i]) > 0:
            spacy_token = doc[token_to_spacy[i][0]]
            # Check if this is the start of a word
            if token.strip() and not token.startswith(' ') and i > 0:
                prev_token = tokens[i-1]
                if prev_token.endswith(' ') or prev_token.strip() in ['.', '\n', ',']:
                    attention[i, first_token_idx] += 0.8

        # NEW: Strong attention from content words to the first period (if it exists)
        if len(sentence_ends) > 0 and sentence_ends[0] < i:
            first_period_idx = sentence_ends[0]
            # Check if this token corresponds to a content word
            if len(token_to_spacy[i]) > 0:
                spacy_token = doc[token_to_spacy[i][0]]
                # Content words: NOUN, VERB, ADJ, ADV (but not function words)
                if spacy_token.pos_ in ['NOUN', 'VERB', 'ADJ', 'ADV']:
                    # Strong attention to the first period, decaying with distance
                    distance = i - first_period_idx
                    weight = 0.7 * np.exp(-0.08 * distance)
                    attention[i, first_period_idx] += weight

        # Moderate attention to recent tokens in same sentence
        for j in range(max(0, i-10), i):
            if j not in sentence_ends and j not in newlines:
                distance = i - j
                weight = 0.15 * np.exp(-0.3 * distance)
                attention[i, j] += weight

        # Self-attention for important tokens
        if token.strip() in ['.', '\n'] or i == first_token_idx:
            attention[i, i] += 0.4
        else:
            attention[i, i] += 0.1

        # Small baseline attention to all previous tokens
        for j in range(i):
            attention[i, j] += 0.05

    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L15H6", attention



def prog_L15H7(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence structure attention: focuses on first token and sentence boundaries (periods, newlines)."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L15H7", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Find structural positions
    first_token_idx = 0
    period_indices = []
    newline_indices = []

    for i, token in enumerate(tokens):
        if token.strip() == '.':
            period_indices.append(i)
        elif token.strip() == '\n':
            newline_indices.append(i)

    for i in range(n):
        current_token = tokens[i].strip()

        # Self-attention for structural tokens
        if current_token in ['.', '\n'] or i == first_token_idx:
            attention[i, i] = 0.6

        # Strong attention to first token
        if i != first_token_idx:
            attention[i, first_token_idx] = 0.4

        # Strong attention to periods
        for p_idx in period_indices:
            if i != p_idx and p_idx <= i:
                attention[i, p_idx] = 0.35

        # Strong attention to newlines
        for n_idx in newline_indices:
            if i != n_idx and n_idx <= i:
                attention[i, n_idx] = 0.37

        # Moderate attention to recent tokens (recency bias)
        for j in range(max(0, i-5), i):
            if j != first_token_idx and tokens[j].strip() not in ['.', '\n']:
                attention[i, j] += 0.1 * (1.0 / (i - j + 1))

        # Small baseline attention to all previous tokens
        for j in range(i):
            if attention[i, j] == 0:
                attention[i, j] = 0.05

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L15H7", attention



def prog_L15H8(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary and structural attention head focusing on newlines, periods, and first tokens."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L15H8", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        # Strong attention to newlines and periods
        for j in range(i + 1):
            if tokens[j].strip() == '\n':
                attention[i, j] = 5.0
            elif tokens[j].strip() == '.':
                attention[i, j] = 3.0

        # High attention to first token
        if n > 0:
            attention[i, 0] += 2.0

        # Self-attention baseline
        attention[i, i] += 0.5

        # Moderate attention to recent tokens (recency bias)
        for j in range(max(0, i - 3), i):
            attention[i, j] += 1.0 / (i - j)

        # Additional attention based on token properties
        for j in range(i + 1):
            # Boost attention to tokens that are sentence starts or important punctuation
            if j < len(token_to_spacy) and token_to_spacy[j]:
                spacy_idx = token_to_spacy[j][0]
                if spacy_idx < len(doc):
                    spacy_token = doc[spacy_idx]

                    # Sentence starts get extra attention
                    if spacy_token.is_sent_start:
                        attention[i, j] += 1.5

                    # Important POS tags get moderate boost
                    if spacy_token.pos_ in ['VERB', 'NOUN', 'PROPN']:
                        attention[i, j] += 0.3

            # Semantic similarity bonus (small effect)
            if i != j:
                sim = _char_sim(tokens[i], tokens[j])
                if sim > 0.7:
                    attention[i, j] += 0.5 * sim

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L15H8", attention



def prog_L15H9(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Punctuation anchor attention with enhanced first-token focus for certain sentence starters."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    # Find anchor tokens (newlines, periods, first tokens)
    anchor_indices = []
    for i, token in enumerate(tokens):
        if token in ['\n', '.'] or i == 0:
            anchor_indices.append(i)

    # Check if first token should receive enhanced attention
    enhanced_first_token = False
    if n > 0:
        # Use spacy to analyze the first token
        spacy_alignment = _align_to_spacy(sentence, tokens)
        if spacy_alignment and len(spacy_alignment[0]) > 0:
            doc = spacy_parse(sentence)
            first_spacy_idx = spacy_alignment[0][0]
            if first_spacy_idx < len(doc):
                first_spacy_token = doc[first_spacy_idx]
                # Enhanced attention if first token is a proper noun, person name, or coordinating conjunction
                if (first_spacy_token.pos_ in ['PROPN'] or 
                    first_spacy_token.ent_type_ == 'PERSON' or
                    (first_spacy_token.pos_ == 'CCONJ' and first_spacy_token.text.lower() in ['and'])):
                    enhanced_first_token = True

    for i in range(n):
        # Base uniform attention to all previous tokens
        for j in range(i + 1):
            attention[i, j] = 0.1

        # Strong attention to anchor tokens (newlines, periods, first token)
        for anchor_idx in anchor_indices:
            if anchor_idx <= i:
                if tokens[anchor_idx] == '\n':
                    attention[i, anchor_idx] = 0.8
                elif tokens[anchor_idx] == '.':
                    attention[i, anchor_idx] = 0.6
                elif anchor_idx == 0:
                    # Enhanced attention for certain first tokens
                    if enhanced_first_token:
                        attention[i, anchor_idx] = 0.9
                    else:
                        attention[i, anchor_idx] = 0.4

        # Moderate attention to immediate previous token
        if i > 0:
            attention[i, i-1] += 0.2

        # Small self-attention boost
        attention[i, i] += 0.1

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L15H9", attention



def prog_L16H0(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary and structural marker attention head with strong first-token attention."""
    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    # Parse with spacy for sentence boundary detection
    doc = spacy_parse(sentence)
    alignment = _align_to_spacy(sentence, tokens)

    # Identify sentence-ending periods and newlines
    sentence_ends = set()
    newlines = set()
    first_token = 0

    for i, token in enumerate(tokens):
        if token.strip() == '.':
            # Check if this period ends a sentence by looking at spacy alignment
            spacy_indices = alignment[i] if i < len(alignment) else []
            for spacy_idx in spacy_indices:
                if spacy_idx < len(doc):
                    spacy_token = doc[spacy_idx]
                    # Check if this is at the end of a sentence
                    if spacy_token.text == '.' and spacy_token.i == len(spacy_token.sent) - 1:
                        sentence_ends.add(i)
        elif token.strip() == '\n':
            newlines.add(i)

    for i in range(n):
        # Base attention pattern
        for j in range(i + 1):  # causal mask
            # Strong attention to sentence-ending periods
            if j in sentence_ends:
                attention[i, j] = 0.3
            # Strong attention to newlines
            elif j in newlines:
                attention[i, j] = 0.25
            # Enhanced attention to first token - much stronger than original
            elif j == first_token:
                # Scale first token attention based on distance
                if i <= 5:
                    attention[i, j] = 0.4  # Very strong for nearby tokens
                elif i <= 15:
                    attention[i, j] = 0.35  # Strong for medium distance
                else:
                    attention[i, j] = 0.3  # Still strong for far tokens
            # Self-attention baseline
            elif i == j:
                attention[i, j] = 0.05
            # Recency bias for nearby tokens
            elif i - j <= 3:
                attention[i, j] = 0.02 * (4 - (i - j)) / 4
            else:
                attention[i, j] = 0.01

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L16H0", attention



def prog_L16H1(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary and clause structure attention head with strong beginning-of-sequence attention."""
    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    if n == 0:
        return "prog_L16H1", attention

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    # Identify sentence boundaries and newlines
    sentence_boundaries = []
    newline_positions = []

    for i, token in enumerate(tokens):
        if token.strip() == '\n':
            newline_positions.append(i)
        elif token.strip() in ['.', '!', '?']:
            sentence_boundaries.append(i)

    for i in range(n):
        # Strong self-attention baseline
        attention[i, i] = 0.3

        # High attention to newlines
        for nl_pos in newline_positions:
            if nl_pos <= i:
                attention[i, nl_pos] = 1.0

        # High attention to sentence boundaries
        for sb_pos in sentence_boundaries:
            if sb_pos <= i:
                attention[i, sb_pos] = 0.8

        # Find the start of current sentence/clause for this token
        current_sent_start = 0
        for boundary in sentence_boundaries + newline_positions:
            if boundary < i:
                current_sent_start = boundary + 1
            else:
                break

        # Strong attention to beginning of current sentence
        if current_sent_start <= i:
            for j in range(current_sent_start, min(current_sent_start + 3, i + 1)):
                attention[i, j] += 0.5

        # Get spacy features for syntactic relationships
        if i < len(token_to_spacy) and token_to_spacy[i]:
            spacy_idx = token_to_spacy[i][0]
            if spacy_idx < len(doc):
                spacy_token = doc[spacy_idx]

                # Pronouns attend to their head/parent
                if spacy_token.pos_ == 'PRON' and spacy_token.head != spacy_token:
                    # Find corresponding token position for the head
                    head_start = spacy_token.head.idx
                    for j in range(i):
                        char_pos = sum(len(tokens[k]) for k in range(j))
                        if abs(char_pos - head_start) < 3:  # approximate alignment
                            attention[i, j] += 0.4
                            break

        # Positional decay - attend to recent previous tokens
        for j in range(max(0, i - 5), i):
            distance = i - j
            attention[i, j] += 0.2 / (distance + 1)

        # Enhanced attention to first token - this is the key missing pattern
        if i > 0:
            # Much stronger attention to the very first token
            attention[i, 0] += 0.6

        # Comma attention - attend to previous significant tokens
        if i > 0 and tokens[i].strip() == ',':
            for j in range(max(0, i - 3), i):
                if tokens[j].strip() not in [',', '.', '\n']:
                    attention[i, j] += 0.4

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L16H1", attention



def prog_L16H10(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary attention with strong focus on periods, newlines, semantic similarity, and first token."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L16H10", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        for j in range(i + 1):  # Causal mask
            weight = 0.0

            # Strong self-attention for punctuation
            if i == j and tokens[i].strip() in ['.', '\n', ',']:
                weight += 0.6

            # High attention from all tokens to periods and newlines
            if tokens[j].strip() in ['.', '\n']:
                weight += 0.3
                # Extra boost if it's a sentence-ending period
                if tokens[j].strip() == '.':
                    weight += 0.2

            # Strong attention to the first token (beginning-of-sequence pattern)
            if j == 0:
                weight += 0.4

            # Semantic similarity boost
            if i != j:
                sim = _char_sim(tokens[i], tokens[j])
                if sim > 0.3:
                    weight += 0.1 * sim

            # Positional bias - preference for recent tokens
            if i != j:
                distance = i - j
                if distance <= 5:
                    weight += 0.05 * (6 - distance) / 6
                else:
                    weight += 0.01

            # Small boost for function words attending to content words
            if len(token_to_spacy[i]) > 0 and len(token_to_spacy[j]) > 0:
                spacy_i = doc[token_to_spacy[i][0]]
                spacy_j = doc[token_to_spacy[j][0]]

                if spacy_i.pos_ in ['DET', 'PRON', 'ADP'] and spacy_j.pos_ in ['NOUN', 'VERB', 'ADJ']:
                    weight += 0.05

            # Base attention level
            weight += 0.02

            attention[i, j] = weight

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L16H10", attention



def prog_L16H11(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary attention head that strongly attends to newlines with reduced period focus."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    if n == 0:
        return "prog_L16H11", attention

    # Find periods and newlines - prioritize newlines over periods
    periods = [i for i, token in enumerate(tokens) if token.strip() == '.']
    newlines = [i for i, token in enumerate(tokens) if token.strip() == '\n']
    punctuation = periods + newlines

    # Find the first newline (primary boundary) and first period (secondary)
    first_newline = newlines[0] if newlines else None
    first_period = periods[0] if periods else None

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        # Strong attention to first newline - this is the primary pattern
        if first_newline is not None and i != first_newline:
            attention[i, first_newline] = 0.6

        # Reduced attention to first period if no newline exists
        if first_period is not None and i != first_period and first_newline is None:
            attention[i, first_period] = 0.15

        # High attention to all newlines for tokens that come after them
        for nl_idx in newlines:
            if nl_idx < i:
                attention[i, nl_idx] = 0.4

        # Strong self-attention for punctuation
        if tokens[i].strip() in ['.', '\n']:
            attention[i, i] = 0.4

        # Moderate self-attention for other tokens
        attention[i, i] += 0.02

        # Add syntactic and semantic relationships
        spacy_indices = token_to_spacy[i]
        if spacy_indices:
            spacy_token = doc[spacy_indices[0]]

            # Look for syntactic heads and dependents
            for j in range(i):
                j_spacy_indices = token_to_spacy[j]
                if j_spacy_indices:
                    j_spacy_token = doc[j_spacy_indices[0]]

                    # Attend to syntactic head
                    if j_spacy_token == spacy_token.head and j != i:
                        attention[i, j] += 0.04

                    # Attend to syntactic children
                    if spacy_token in j_spacy_token.children:
                        attention[i, j] += 0.03

                    # Semantic similarity boost
                    sim = _char_sim(tokens[i], tokens[j])
                    if sim > 0.7:
                        attention[i, j] += 0.02 * sim

        # Small attention to recent previous tokens
        for j in range(max(0, i-3), i):
            attention[i, j] += 0.01 / (i - j)

        # Extra attention to nearby punctuation
        for j in range(i):
            if tokens[j].strip() in ['.', ',', '\n'] and i - j <= 5:
                attention[i, j] += 0.05

    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L16H11", attention



def prog_L16H12(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Attention head focusing on sentence boundaries, newlines, and structural punctuation with strong beginning-of-sequence attention."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        for j in range(i + 1):  # Causal mask
            weight = 0.0

            # Strong attention to newline tokens
            if tokens[j].strip() == '':
                weight += 0.3

            # Attention to sentence-initial tokens (first token after newline or start)
            if j == 0:
                weight += 0.15
            elif j > 0 and tokens[j-1].strip() == '':
                weight += 0.15

            # Attention to punctuation marks
            if tokens[j] in ['.', ',', '!', '?', ';', ':', '"', "'", ')"', '."', '!"', '?"']:
                weight += 0.12

            # Self-attention baseline
            if i == j:
                weight += 0.05

            # Attention to previous token
            if j == i - 1:
                weight += 0.08

            # NEW: Strong attention to sequence beginning from content words
            if j == 0 and i > 0:
                # Check if current token is a content word
                if token_to_spacy[i]:
                    spacy_token = doc[token_to_spacy[i][0]]
                    if spacy_token.pos_ in ['NOUN', 'VERB', 'ADJ', 'ADV', 'PROPN']:
                        # Strong boost for content words attending to sequence start
                        weight += 0.4
                else:
                    # Fallback for tokens without spacy alignment - use length as proxy for content
                    if len(tokens[i].strip()) > 2:
                        weight += 0.2

            # Attention based on spacy features if available
            if token_to_spacy[j]:
                spacy_token = doc[token_to_spacy[j][0]]

                # Attention to sentence starts
                if spacy_token.is_sent_start:
                    weight += 0.1

                # Attention to proper nouns and named entities
                if spacy_token.pos_ == 'PROPN' or spacy_token.ent_type_:
                    weight += 0.06

                # Attention to verbs and important content words
                if spacy_token.pos_ in ['VERB', 'NOUN']:
                    weight += 0.04

            # Distance decay for non-special tokens
            distance = i - j
            if distance > 0:
                decay = 1.0 / (1 + 0.1 * distance)
                weight *= decay

            # Semantic similarity boost for related tokens
            if i != j:
                sim = _char_sim(tokens[i], tokens[j])
                if sim > 0.7:
                    weight += 0.05 * sim

            attention[i, j] = weight

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L16H12", attention



def prog_L16H13(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Attention head focusing on document structure, sentence boundaries, and punctuation markers with strong first-token attention."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L16H13", np.zeros((n_empty, n_empty))

    # Initialize attention matrix
    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        token = tokens[i].strip()

        # Strong self-attention for first token
        if i == 0:
            attention[i, i] = 1.0
            continue

        # High attention to structural markers
        for j in range(i + 1):
            target_token = tokens[j].strip()

            # Very high attention to newlines and periods
            if target_token in ['\n', '.']:
                attention[i, j] += 0.4

            # High attention to other punctuation
            elif target_token in [',', '!', '?', '"', "'", ':', ';']:
                attention[i, j] += 0.2

            # Much stronger attention to first token - this was the key issue
            elif j == 0:
                attention[i, j] += 0.5  # Increased from 0.15 to 0.5

            # Reduced self-attention to compensate
            elif i == j:
                attention[i, j] += 0.05  # Reduced from 0.1 to 0.05

        # Add linguistic-based attention
        if token_to_spacy[i]:
            spacy_i = token_to_spacy[i][0]
            spacy_token = doc[spacy_i]

            # If current token is a verb or noun, attend to sentence start
            if spacy_token.pos_ in ['VERB', 'NOUN']:
                for j in range(i):
                    if token_to_spacy[j] and doc[token_to_spacy[j][0]].is_sent_start:
                        attention[i, j] += 0.1

            # If current token ends a sentence, boost attention to punctuation
            if spacy_token.is_sent_end or spacy_token.pos_ == 'PUNCT':
                for j in range(i):
                    if tokens[j].strip() in ['\n', '.', '!', '?']:
                        attention[i, j] += 0.2

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L16H13", attention



def prog_L16H14(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Attention head that focuses on sentence boundaries and early tokens with syntactic awareness, with strong newline preference."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L16H14", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        # Strong self-attention for first token
        if i == 0:
            attention[i, i] = 1.0
            continue

        # Initialize base attention pattern
        for j in range(i + 1):
            # Base positional decay
            pos_weight = 0.01 * (1.0 / (i - j + 1))

            # Boost for specific token types
            token_j = tokens[j].strip()

            # Much stronger attention to newlines - this is the key pattern
            if token_j == '\n':
                pos_weight += 0.8  # Much higher than original 0.3
            elif token_j == '.':
                # Reduce period attention to compensate for over-prediction
                pos_weight += 0.1  # Reduced from 0.3
            elif token_j == ',' or token_j == '!' or token_j == '?':
                pos_weight += 0.1

            # Boost for first token
            if j == 0:
                pos_weight += 0.2

            # Self-attention boost
            if i == j:
                pos_weight += 0.05

            # Syntactic relationships via spacy
            if token_to_spacy[i] and token_to_spacy[j]:
                spacy_i = token_to_spacy[i][0] if token_to_spacy[i] else None
                spacy_j = token_to_spacy[j][0] if token_to_spacy[j] else None

                if spacy_i is not None and spacy_j is not None and spacy_i < len(doc) and spacy_j < len(doc):
                    spacy_tok_i = doc[spacy_i]
                    spacy_tok_j = doc[spacy_j]

                    # Head-dependent relationships
                    if spacy_tok_i.head == spacy_tok_j or spacy_tok_j.head == spacy_tok_i:
                        pos_weight += 0.05

                    # Semantic similarity boost
                    sim = _char_sim(tokens[i], tokens[j])
                    if sim > 0.5:
                        pos_weight += 0.03 * sim

            attention[i, j] = pos_weight

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L16H14", attention



def prog_L16H15(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Attention head with strong first-token attention, plus self-attention, punctuation focus, and local context."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L16H15", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    for i in range(n):
        for j in range(i + 1):  # causal mask
            weight = 0.0

            # Strong self-attention
            if i == j:
                weight += 0.3

            # High attention to newlines and periods
            if tokens[j] in ['\n', '.']:
                weight += 0.4

            # Attention to immediately previous token
            if j == i - 1:
                weight += 0.2

            # Attention to nearby tokens (within 3 positions)
            if 0 < i - j <= 3:
                weight += 0.1 * (4 - (i - j)) / 4

            # Semantic similarity boost
            if i != j:
                sim = _char_sim(tokens[i], tokens[j])
                if sim > 0.3:  # threshold for meaningful similarity
                    weight += 0.15 * sim

            # Small attention to comma and other punctuation
            if tokens[j] in [',', '!', '?', '"', "'", ';', ':']:
                weight += 0.1

            # NEW: Strong attention to the first token from all later positions
            if j == 0 and i > 0:
                # Get spacy analysis to check if first token is a proper noun or sentence start
                doc = spacy_parse(sentence)
                token_to_spacy = _align_to_spacy(sentence, tokens)

                if len(token_to_spacy) > 0 and len(token_to_spacy[0]) > 0:
                    first_spacy_idx = token_to_spacy[0][0]
                    first_spacy_token = doc[first_spacy_idx]

                    # Strong boost if first token is proper noun or starts sentence
                    if first_spacy_token.pos_ == "PROPN" or first_spacy_token.is_sent_start:
                        weight += 0.5
                    else:
                        weight += 0.2  # Moderate boost for other first tokens
                else:
                    # Fallback if alignment fails
                    weight += 0.3

            # Distance decay for non-punctuation tokens
            if tokens[j] not in ['\n', '.', ',', '!', '?', '"', "'", ';', ':']:
                distance = i - j
                if distance > 0:
                    weight *= (1.0 / (1.0 + 0.1 * distance))

            attention[i, j] = weight

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L16H15", attention



def prog_L16H16(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Attention head that focuses on punctuation marks and sentence/clause beginnings."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention_matrix = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    # Identify sentence/clause beginnings
    sentence_starts = [0]  # First token is always a sentence start
    for i in range(1, n):
        token = tokens[i].strip()
        prev_token = tokens[i-1].strip()

        # After sentence-ending punctuation
        if prev_token in ['.', '!', '?'] and token and token[0].isupper():
            sentence_starts.append(i)
        # After newlines followed by uppercase
        elif prev_token == '' or '\n' in prev_token:
            if token and token[0].isupper():
                sentence_starts.append(i)
        # After quotation marks starting new sentences
        elif prev_token in ['"', "'"] and token and token[0].isupper():
            sentence_starts.append(i)

    for i in range(n):
        query_token = tokens[i]

        # Self-attention baseline
        attention_matrix[i, i] = 0.1

        # Strong attention to punctuation marks, especially periods and newlines
        for j in range(i + 1):
            key_token = tokens[j]

            # Very high attention to newlines
            if key_token.strip() == '' or '\n' in key_token:
                attention_matrix[i, j] += 0.4

            # High attention to periods
            elif key_token.strip() == '.':
                attention_matrix[i, j] += 0.3

            # Moderate attention to other punctuation
            elif key_token.strip() in [',', '!', '?', '"', "'", ':', ';']:
                attention_matrix[i, j] += 0.15

            # NEW: Strong attention to sentence/clause beginnings
            if j in sentence_starts and j < i:
                # Find which sentence start this token belongs to
                current_sentence_start = max([s for s in sentence_starts if s <= i])
                if j == current_sentence_start:
                    attention_matrix[i, j] += 0.4  # Strong attention to own sentence start
                else:
                    attention_matrix[i, j] += 0.15  # Moderate attention to other sentence starts

            # Special attention patterns for certain token types
            if len(token_to_spacy[i]) > 0:
                spacy_query = doc[token_to_spacy[i][0]]

                # Verbs attend more to sentence boundaries
                if spacy_query.pos_ == 'VERB':
                    if key_token.strip() in ['.', '\n'] or '\n' in key_token:
                        attention_matrix[i, j] += 0.2

                # Conjunctions and connecting words attend to punctuation
                if spacy_query.pos_ in ['CCONJ', 'SCONJ'] or spacy_query.text.lower() in ['and', 'but', 'so', 'then']:
                    if key_token.strip() in ['.', ',', '\n'] or '\n' in key_token:
                        attention_matrix[i, j] += 0.15

            # Distance-based decay for non-punctuation tokens
            if key_token.strip() not in ['.', ',', '!', '?', '"', "'", ':', ';'] and '\n' not in key_token:
                distance = i - j
                if distance > 0:
                    attention_matrix[i, j] += 0.02 / (1 + distance * 0.1)

            # First token attention (especially for sentence starters)
            if j == 0 and i > 5:
                attention_matrix[i, j] += 0.05

    # Apply causal mask and normalize
    attention_matrix = apply_causal_mask(attention_matrix)
    attention_matrix = make_row_stochastic(attention_matrix)

    return "prog_L16H16", attention_matrix



def prog_L16H17(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Structural boundary attention: focuses on sentence/paragraph boundaries and sequence start."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L16H17", np.zeros((n_empty, n_empty)).reshape(0, 0)

    attention = np.zeros((n, n))

    # Get spacy alignment for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        # Strong attention to structural boundaries
        for j in range(i + 1):  # causal mask
            weight = 0.0

            # Very high attention to newlines and periods
            if tokens[j].strip() == '\n':
                weight += 0.4
            elif tokens[j].strip() == '.':
                weight += 0.3

            # High attention to first token
            if j == 0:
                weight += 0.2

            # Self-attention baseline
            if i == j:
                weight += 0.05

            # Local syntactic attention - attend to nearby function words
            if token_to_spacy[j]:
                spacy_idx = token_to_spacy[j][0]
                if spacy_idx < len(doc):
                    spacy_token = doc[spacy_idx]
                    if spacy_token.pos_ in ['ADP', 'DET', 'CONJ', 'CCONJ']:
                        if abs(i - j) <= 3:
                            weight += 0.1

            # Distance decay for non-structural tokens
            if tokens[j].strip() not in ['\n', '.'] and j != 0:
                distance = i - j
                if distance > 0:
                    weight *= (0.7 ** (distance / 5.0))

            # Boost attention between semantically similar tokens
            if i != j:
                sim = _char_sim(tokens[i], tokens[j])
                if sim > 0.5:
                    weight += 0.1 * sim

            attention[i, j] = weight

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L16H17", attention



def prog_L16H18(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary attention head with special focus on sequence-initial token."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L16H18", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        token_i = tokens[i]

        # Strong self-attention for punctuation
        if token_i in ['.', '!', '?', '\n', ',']:
            attention[i, i] = 1.0

        # High attention to periods and newlines from all positions
        for j in range(i + 1):
            token_j = tokens[j]

            # SPECIAL CASE: Very high attention to the first token of the sequence
            if j == 0:
                attention[i, j] = 0.7

            # Very high attention to sentence-ending punctuation
            elif token_j in ['.', '!', '?']:
                attention[i, j] = 0.4

            # High attention to newlines (sentence boundaries)
            elif token_j == '\n':
                attention[i, j] = 0.35

            # Moderate attention to first tokens of sentences
            elif j > 0 and tokens[j-1] in ['\n', '.', '!', '?']:
                attention[i, j] = 0.1

            # Some attention to commas and other punctuation
            elif token_j in [',', ':', ';']:
                attention[i, j] = 0.05

            # Base attention for other tokens
            else:
                attention[i, j] = 0.01

        # Boost self-attention if not already set high
        if tokens[i] not in ['.', '!', '?', '\n', ',']:
            attention[i, i] = max(attention[i, i], 0.02)

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L16H18", attention



def prog_L16H19(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """First-token attention head - strongly attends to sequence beginnings with boundary token awareness."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention_matrix = np.zeros((n, n))

    # Find boundary tokens (periods and newlines)
    boundary_indices = []
    for i, token in enumerate(tokens):
        if token.strip() in ['.', '\n']:
            boundary_indices.append(i)

    for i in range(n):
        # Base attention distribution
        row = np.zeros(n)

        # Very strong attention to first token (this is the main pattern we missed)
        if i > 0:
            row[0] = 0.7  # Much higher than original 0.05

        # Moderate attention to boundary tokens (periods and newlines) 
        for boundary_idx in boundary_indices:
            if boundary_idx <= i and boundary_idx != 0:  # Don't override first token attention
                if tokens[boundary_idx].strip() == '\n':
                    row[boundary_idx] = 0.2  # Reduced from 0.4
                elif tokens[boundary_idx].strip() == '.':
                    row[boundary_idx] = 0.15  # Reduced from 0.3

        # Reduced self-attention to avoid over-prediction
        row[i] = 0.05  # Reduced from 0.1

        # Add some recency bias for recent tokens
        for j in range(max(0, i-5), i):
            if row[j] == 0:  # Don't override boundary or first token attention
                row[j] = 0.01 * (1.0 / (i - j + 1))  # Reduced from 0.02

        # Normalize to ensure we have some attention somewhere
        if row.sum() == 0:
            row[i] = 1.0

        attention_matrix[i] = row

    # Apply causal mask and normalize
    attention_matrix = apply_causal_mask(attention_matrix)
    attention_matrix = make_row_stochastic(attention_matrix)

    return "prog_L16H19", attention_matrix



def prog_L16H2(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Structural boundary and recency attention head with enhanced first-token bias."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        # Base attention distribution
        base_weights = np.zeros(i + 1)  # Only attend to previous tokens and self

        # Strong attention to structural markers
        for j in range(i + 1):
            token_j = tokens[j].strip()

            # Very high attention to first token
            if j == 0:
                base_weights[j] = 0.8

            # High attention to sentence boundaries
            elif token_j in ['.', '!', '?']:
                base_weights[j] = 0.4

            # High attention to newlines
            elif token_j == '\n':
                base_weights[j] = 0.3

            # Moderate attention to other punctuation
            elif token_j in [',', ';', ':']:
                base_weights[j] = 0.15

            # Self-attention
            elif j == i:
                base_weights[j] = 0.1

        # Add recency bias - exponential decay
        for j in range(i + 1):
            distance = i - j
            if distance > 0:
                decay_factor = 0.95 ** distance
                base_weights[j] *= decay_factor

        # Enhanced first-token bias for distant tokens
        if i > 5:  # Only for tokens that are reasonably far from start
            if 0 <= i:  # Ensure first token is in range
                # Boost first token attention based on distance
                distance_boost = min(0.4, 0.05 * (i - 5))
                base_weights[0] += distance_boost

        # Add syntactic relationships
        if token_to_spacy[i]:
            spacy_i = token_to_spacy[i][0]
            if spacy_i < len(doc):
                spacy_token_i = doc[spacy_i]

                # Pronouns attend to nearby nouns
                if spacy_token_i.pos_ in ['PRON']:
                    for j in range(max(0, i-10), i):
                        if token_to_spacy[j]:
                            spacy_j = token_to_spacy[j][0]
                            if spacy_j < len(doc) and doc[spacy_j].pos_ in ['NOUN', 'PROPN']:
                                base_weights[j] += 0.2

                # Verbs attend to their subjects
                elif spacy_token_i.pos_ == 'VERB':
                    for j in range(max(0, i-5), i):
                        if token_to_spacy[j]:
                            spacy_j = token_to_spacy[j][0]
                            if spacy_j < len(doc):
                                if doc[spacy_j].dep_ in ['nsubj', 'nsubjpass']:
                                    base_weights[j] += 0.15

        # Add semantic similarity boost for recent tokens
        for j in range(max(0, i-5), i):
            if j < i and _char_sim(tokens[i], tokens[j]) > 0.7:
                base_weights[j] += 0.1

        # Special boost for tokens that end sentences attending to sentence starts
        token_i = tokens[i].strip()
        if token_i in ['.', '!', '?']:
            # Find start of current sentence
            for j in range(i-1, -1, -1):
                if tokens[j].strip() in ['.', '!', '?', '\n'] or j == 0:
                    if j < i-1:  # Don't boost immediate predecessor
                        sentence_start = j + 1 if j > 0 else j
                        if sentence_start < i:
                            base_weights[sentence_start] += 0.2
                    break

        # Ensure minimum attention values
        base_weights = np.maximum(base_weights, 0.01)

        attention[i, :i+1] = base_weights

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L16H2", attention



def prog_L16H20(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Structural boundary attention with strong first-token focus: focuses on newlines, periods, and strongly on the first token."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    # Find structural delimiter positions
    newline_positions = []
    period_positions = []
    first_token_pos = 0 if n > 0 else None

    for i, token in enumerate(tokens):
        if token.strip() == '\n':
            newline_positions.append(i)
        elif token.strip() == '.':
            period_positions.append(i)

    for i in range(n):
        # Default small self-attention
        attention[i, i] = 0.1

        # Strong attention to newlines (primary pattern)
        for newline_pos in newline_positions:
            if newline_pos <= i:  # Causal constraint
                # Distance decay from newline
                distance = i - newline_pos
                if distance == 0:
                    weight = 0.4  # Self-attention to newline
                else:
                    weight = 0.6 / (1 + 0.1 * distance)  # Decay with distance
                attention[i, newline_pos] += weight

        # Moderate attention to periods (secondary pattern)
        for period_pos in period_positions:
            if period_pos <= i:  # Causal constraint
                distance = i - period_pos
                if distance == 0:
                    weight = 0.2  # Self-attention to period
                else:
                    weight = 0.3 / (1 + 0.2 * distance)  # Decay with distance
                attention[i, period_pos] += weight

        # Strong attention to first token (major pattern observed in failures)
        if first_token_pos is not None and first_token_pos <= i:
            if i == first_token_pos:
                # Don't override self-attention for first token
                pass
            else:
                # Strong attention to first token with distance decay
                distance = i - first_token_pos
                weight = 0.8 / (1 + 0.05 * distance)  # Stronger base weight, slower decay
                attention[i, first_token_pos] += weight

        # Small uniform attention to recent tokens
        for j in range(max(0, i-5), i):
            attention[i, j] += 0.02

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L16H20", attention



def prog_L16H21(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Attention head combining sentence boundary detection with strong beginning-of-sequence bias and local syntax."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L16H21", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    # Identify sentence boundary tokens (newlines and periods)
    boundary_tokens = set()
    for i, token in enumerate(tokens):
        if token.strip() in ['\n', '.', '!', '?']:
            boundary_tokens.add(i)

    for i in range(n):
        # Base positional decay (attend more to recent tokens)
        for j in range(i + 1):
            distance = i - j
            if distance == 0:
                # Self-attention baseline
                attention[i, j] = 1.0
            else:
                # Exponential decay with distance
                attention[i, j] = 0.3 * np.exp(-0.1 * distance)

        # Strong self-attention for first token
        if i == 0:
            attention[i, i] = 5.0

        # Strong beginning-of-sequence bias - boost attention to very early tokens
        if i > 2:  # Only for tokens beyond the first few positions
            for j in range(min(3, i + 1)):  # First 3 tokens (positions 0, 1, 2)
                # Strong boost for position 0, moderate for positions 1-2
                if j == 0:
                    attention[i, j] += 2.5
                else:
                    attention[i, j] += 1.0

        # High attention to sentence boundaries
        for boundary_idx in boundary_tokens:
            if boundary_idx <= i:
                # Boost attention to boundary tokens
                attention[i, boundary_idx] += 2.0

        # Syntactic dependencies using spacy alignment
        if token_to_spacy[i]:
            spacy_idx = token_to_spacy[i][0]
            if spacy_idx < len(doc):
                spacy_token = doc[spacy_idx]

                # Attend to syntactic head
                if spacy_token.head != spacy_token:
                    head_spacy_idx = spacy_token.head.i
                    # Find corresponding token indices
                    for j in range(i + 1):
                        if token_to_spacy[j] and head_spacy_idx in token_to_spacy[j]:
                            attention[i, j] += 1.5

                # Attend to dependents
                for child in spacy_token.children:
                    child_spacy_idx = child.i
                    for j in range(i + 1):
                        if token_to_spacy[j] and child_spacy_idx in token_to_spacy[j]:
                            attention[i, j] += 0.8

        # Semantic similarity boost
        for j in range(i):
            sim = _char_sim(tokens[i], tokens[j])
            if sim > 0.7:  # High similarity threshold
                attention[i, j] += 1.0 * sim

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L16H21", attention



def prog_L16H22(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary detection head with strong attention to sentence-initial fragments."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L16H22", np.zeros((n_empty, n_empty))

    attention_matrix = np.zeros((n, n))

    # Get spacy alignment for linguistic features
    token_to_spacy = _align_to_spacy(sentence, tokens)
    doc = spacy_parse(sentence)

    # Detect if first token is a sentence fragment (incomplete word)
    first_token_is_fragment = False
    if len(tokens) > 0:
        first_token = tokens[0].strip()
        # Check if first token looks like a fragment (starts with lowercase, short, etc.)
        if len(first_token) <= 3 and first_token.islower():
            first_token_is_fragment = True

    for i in range(n):
        token = tokens[i]

        # Base attention distribution
        base_weights = np.zeros(i + 1)  # Can only attend to positions <= i

        # Strong attention to sentence-ending punctuation and newlines
        for j in range(i + 1):
            key_token = tokens[j]

            # Very high attention to periods and newlines
            if key_token.strip() == '.' or key_token == '\n':
                base_weights[j] += 3.0

            # High attention to other punctuation marks that end sentences
            elif key_token.strip() in ['!', '?', '."', ".'", '!"', "!'", '?"', "?'"]:
                base_weights[j] += 2.5

            # Moderate attention to commas and other punctuation
            elif key_token.strip() in [',', ';', ':', '"', "'", '(', ')', '[', ']']:
                base_weights[j] += 1.0

        # SPECIAL CASE: Strong attention to sentence-initial fragments
        if first_token_is_fragment and i > 0:
            # Add very strong attention to the first token for most subsequent tokens
            base_weights[0] += 8.0

        # Get spacy info for current token
        spacy_indices = token_to_spacy[i] if i < len(token_to_spacy) else []
        is_content_word = False
        if spacy_indices:
            spacy_token = doc[spacy_indices[0]]
            # Content words (nouns, verbs, adjectives, adverbs) attend more strongly
            if spacy_token.pos_ in ['NOUN', 'VERB', 'ADJ', 'ADV', 'PROPN']:
                is_content_word = True

        # Content words have stronger attention to sentence boundaries
        if is_content_word:
            base_weights *= 1.5

        # Add positional bias - slight preference for recent tokens
        for j in range(i + 1):
            distance = i - j
            if distance == 0:
                base_weights[j] += 0.5  # Self-attention
            else:
                # Decay with distance, but sentence boundaries override this
                decay = 0.1 / (1 + distance * 0.1)
                base_weights[j] += decay

        # Special case: first token of sentences tends to attend strongly to previous sentence end
        if i > 0:
            # Check if this might be start of sentence
            prev_tokens = tokens[max(0, i-3):i]
            if any(t.strip() in ['.', '\n', '!', '?'] for t in prev_tokens):
                # Find the most recent sentence boundary
                for j in range(i-1, -1, -1):
                    if tokens[j].strip() in ['.', '\n', '!', '?']:
                        base_weights[j] += 2.0
                        break

        # Normalize and set
        if base_weights.sum() > 0:
            base_weights = base_weights / base_weights.sum()
        else:
            base_weights = np.ones(i + 1) / (i + 1)

        attention_matrix[i, :i+1] = base_weights

    # Apply causal mask and ensure row stochastic
    attention_matrix = apply_causal_mask(attention_matrix)
    attention_matrix = make_row_stochastic(attention_matrix)

    return "prog_L16H22", attention_matrix



def prog_L16H23(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Document structure attention head focusing on newlines, first tokens, and sentence boundaries."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L16H23", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    alignment = _align_to_spacy(sentence, tokens)

    for i in range(n):
        # Strong attention to newline characters
        for j in range(i + 1):
            if tokens[j].strip() == '\n':
                attention[i, j] = 0.45

        # Strong attention to first token
        if n > 0:
            attention[i, 0] = 0.35

        # Attention to sentence-ending punctuation
        for j in range(i + 1):
            if tokens[j].strip() in ['.', '!', '?']:
                attention[i, j] = 0.25

        # Self-attention
        attention[i, i] = 0.15

        # Some local attention to nearby tokens
        for j in range(max(0, i - 3), i):
            if j != i:
                attention[i, j] += 0.05

        # Boost attention based on token positions and structural importance
        spacy_indices = alignment[i] if i < len(alignment) else []

        for j in range(i + 1):
            # Extra attention to tokens at sentence beginnings
            j_spacy_indices = alignment[j] if j < len(alignment) else []

            for spacy_idx in j_spacy_indices:
                if spacy_idx < len(doc):
                    spacy_token = doc[spacy_idx]
                    # Boost attention to sentence-initial tokens
                    if spacy_token.is_sent_start:
                        attention[i, j] += 0.15

                    # Boost attention to tokens that start clauses or are syntactically important
                    if spacy_token.dep_ in ['ROOT', 'nsubj', 'dobj']:
                        attention[i, j] += 0.08

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L16H23", attention



def prog_L16H24(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Syntactic dependency head with sentence boundary and coreference patterns."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L16H24", np.zeros((n_empty, n_empty))

    # Initialize attention matrix
    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)
    spacy_to_tokens = align_spacy_to_tokens(sentence)

    for i in range(n):
        # Self-attention baseline
        attention[i, i] = 0.1

        # Strong attention to sentence boundaries (periods, newlines)
        for j in range(i + 1):
            if tokens[j] in ['.', '\n', '!', '?']:
                attention[i, j] += 0.3

        # Get spacy info for current token
        spacy_indices = token_to_spacy[i]
        current_spacy_tokens = [doc[idx] for idx in spacy_indices if idx < len(doc)]

        if current_spacy_tokens:
            current_token = current_spacy_tokens[0]

            # NEW: Strong syntactic dependency attention - tokens attend to their syntactic heads
            if current_token.head != current_token:  # Not root
                head_token = current_token.head
                head_token_indices = []
                for spacy_idx in range(len(doc)):
                    if doc[spacy_idx] == head_token:
                        head_token_indices = spacy_to_tokens[spacy_idx]
                        break

                # Add strong attention to syntactic head tokens
                for head_idx in head_token_indices:
                    if head_idx < i:  # Respect causal mask
                        attention[i, head_idx] += 0.4

            # Pronoun resolution - pronouns attend to potential antecedents
            if current_token.pos_ == 'PRON':
                for j in range(i):
                    j_spacy_indices = token_to_spacy[j]
                    j_spacy_tokens = [doc[idx] for idx in j_spacy_indices if idx < len(doc)]

                    if j_spacy_tokens:
                        j_token = j_spacy_tokens[0]
                        # Attend to nouns and proper nouns as potential antecedents
                        if j_token.pos_ in ['NOUN', 'PROPN']:
                            attention[i, j] += 0.2
                            # Boost for semantic similarity
                            sim = _char_sim(tokens[i], tokens[j])
                            if sim > 0.3:
                                attention[i, j] += 0.1

            # Verbs attend to their subjects and objects
            if current_token.pos_ == 'VERB':
                for j in range(i):
                    j_spacy_indices = token_to_spacy[j]
                    j_spacy_tokens = [doc[idx] for idx in j_spacy_indices if idx < len(doc)]

                    if j_spacy_tokens:
                        j_token = j_spacy_tokens[0]
                        if j_token.pos_ in ['NOUN', 'PROPN', 'PRON']:
                            attention[i, j] += 0.15

        # Semantic similarity boost for all tokens
        for j in range(i):
            sim = _char_sim(tokens[i], tokens[j])
            if sim > 0.4:
                attention[i, j] += 0.2 * sim

        # Positional bias - slight preference for recent tokens
        for j in range(max(0, i - 5), i):
            attention[i, j] += 0.05 * (1.0 - (i - j) / 6.0)

        # Special attention patterns for punctuation
        if tokens[i] in [',', ';', ':']:
            # Commas attend to sentence structure
            for j in range(i):
                if tokens[j] in ['.', '\n']:
                    attention[i, j] += 0.15

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L16H24", attention



def prog_L16H25(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary and segment-initial token attention head."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    # Identify sentence boundaries and segment starts
    boundary_tokens = set()
    segment_starts = set()

    for i, token in enumerate(tokens):
        # Check if token is a boundary marker
        if token.strip() in ['.', '\n', '!', '?']:
            boundary_tokens.add(i)

        # Check if token starts a segment (after boundary or at beginning)
        if i == 0:
            segment_starts.add(i)
        elif i > 0 and (i-1) in boundary_tokens:
            segment_starts.add(i)

    for i in range(n):
        for j in range(i + 1):  # Causal mask
            weight = 0.0

            # Strong attention to boundary tokens (newlines, periods)
            if j in boundary_tokens:
                weight += 0.3

            # Strong attention to segment start tokens
            if j in segment_starts:
                weight += 0.2

            # Self-attention
            if i == j:
                weight += 0.1

            # Recent token bias (attend to nearby previous tokens)
            if i > j:
                distance = i - j
                if distance <= 3:
                    weight += 0.1 / distance

            # Semantic similarity boost
            if i != j:
                sim = _char_sim(tokens[i], tokens[j])
                if sim > 0.3:
                    weight += sim * 0.15

            # Special case: tokens often attend strongly to first token
            if j == 0:
                weight += 0.15

            # Linguistic features via spacy alignment
            if token_to_spacy[i] and token_to_spacy[j]:
                spacy_i = token_to_spacy[i][0] if token_to_spacy[i] else None
                spacy_j = token_to_spacy[j][0] if token_to_spacy[j] else None

                if spacy_i is not None and spacy_j is not None and spacy_i < len(doc) and spacy_j < len(doc):
                    # Attend to pronouns and proper nouns
                    if doc[spacy_j].pos_ in ['PRON', 'PROPN']:
                        weight += 0.1

                    # Attend to verbs from nouns/pronouns
                    if doc[spacy_i].pos_ in ['NOUN', 'PRON'] and doc[spacy_j].pos_ == 'VERB':
                        weight += 0.08

            attention[i, j] = weight

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L16H25", attention



def prog_L16H26(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary and document structure attention head."""
    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    # Identify sentence boundaries and first tokens
    sentence_boundaries = []
    first_tokens = []

    for i, token in enumerate(tokens):
        # Sentence boundaries: newlines and sentence-ending punctuation
        if token.strip() in ['\n', '.', '!', '?']:
            sentence_boundaries.append(i)
        # First meaningful token (not whitespace/punct at start)
        if i == 0 or (i > 0 and tokens[i-1].strip() in ['\n', '.', '!', '?']):
            if token.strip() and token.strip() not in ['.', '!', '?', '\n']:
                first_tokens.append(i)

    # If no boundaries found, treat first token as boundary
    if not sentence_boundaries and n > 0:
        sentence_boundaries.append(0)
    if not first_tokens and n > 0:
        first_tokens.append(0)

    for i in range(n):
        token = tokens[i].strip()

        # Self-attention baseline
        attention[i, i] = 0.1

        # Strong attention to sentence boundaries (newlines, periods)
        for boundary_idx in sentence_boundaries:
            if boundary_idx <= i:
                if token in ['\n', '.', '!', '?']:
                    # Sentence boundary tokens attend strongly to other boundaries
                    attention[i, boundary_idx] = 0.4
                else:
                    # Regular tokens attend to boundaries with moderate strength
                    attention[i, boundary_idx] = 0.2

        # Attention to first tokens of sentences
        for first_idx in first_tokens:
            if first_idx <= i:
                attention[i, first_idx] = 0.15

        # Special case: very first token gets high self-attention
        if i == 0:
            attention[i, i] = 1.0

        # Add some recency bias for nearby tokens
        for j in range(max(0, i-3), i):
            if attention[i, j] < 0.05:
                attention[i, j] += 0.02

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L16H26", attention



def prog_L16H27(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary and structural marker attention head."""
    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention_matrix = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        # Get spacy tokens for current token
        spacy_indices = token_to_spacy[i]

        for j in range(i + 1):  # Causal mask
            # Strong attention to sentence-ending punctuation
            if tokens[j] in ['.', '!', '?']:
                attention_matrix[i, j] = 0.3

            # Strong attention to newlines and structural markers
            elif tokens[j] in ['\n', '\t']:
                attention_matrix[i, j] = 0.25

            # Attention to first token
            elif j == 0:
                attention_matrix[i, j] = 0.15

            # Local attention to previous few tokens
            elif i - j <= 3:
                attention_matrix[i, j] = 0.1 / (1 + i - j)

            # Base attention for other positions
            else:
                attention_matrix[i, j] = 0.02

    # Apply causal mask and normalize
    attention_matrix = apply_causal_mask(attention_matrix)
    attention_matrix = make_row_stochastic(attention_matrix)

    return "prog_L16H27", attention_matrix



def prog_L16H28(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary attention head - attends to sentence-ending punctuation, newlines, and sentence-initial tokens."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    # Identify sentence boundary markers
    sentence_ends = set()
    newlines = set()
    first_tokens = set()

    for i, token in enumerate(tokens):
        # Check for sentence-ending punctuation
        if token.strip() in ['.', '!', '?']:
            sentence_ends.add(i)
        # Check for newlines (sentence separators)
        elif '\n' in token:
            newlines.add(i)
        # Check if this is likely a sentence start (after newline or beginning)
        elif i == 0:
            first_tokens.add(i)
        elif i > 0 and '\n' in tokens[i-1]:
            first_tokens.add(i)

    # Identify sentence-initial content tokens (first non-punctuation token)
    sentence_starts = set()
    sentence_starts.add(0)  # First token is always important
    for i in range(1, n):
        # After newlines, find first non-whitespace token
        if i > 0 and '\n' in tokens[i-1]:
            sentence_starts.add(i)
        # After sentence endings, look for next content token
        elif i > 0 and tokens[i-1].strip() in ['.', '!', '?']:
            # Skip whitespace and find next meaningful token
            for j in range(i, min(i+3, n)):
                if tokens[j].strip() and not tokens[j].strip() in ['\n', ' ']:
                    sentence_starts.add(j)
                    break

    for i in range(n):
        # Reduce base self-attention to fix over-prediction
        attention[i, i] = 0.03

        # Strong attention to sentence-ending punctuation
        for end_idx in sentence_ends:
            if end_idx <= i:
                distance = i - end_idx + 1
                attention[i, end_idx] = 0.4 / distance

        # Attention to newlines (sentence boundaries)
        for nl_idx in newlines:
            if nl_idx <= i:
                distance = i - nl_idx + 1
                attention[i, nl_idx] = 0.3 / distance

        # Strong attention to sentence-initial tokens (NEW)
        for start_idx in sentence_starts:
            if start_idx <= i and start_idx != i:
                distance = i - start_idx + 1
                attention[i, start_idx] = 0.5 / (distance ** 0.3)

        # Moderate attention to first tokens of sentences
        for first_idx in first_tokens:
            if first_idx <= i and first_idx != i:
                distance = i - first_idx + 1
                attention[i, first_idx] = 0.15 / (distance ** 0.5)

        # Local attention to nearby tokens
        for j in range(max(0, i-3), i):
            if j not in sentence_ends and j not in newlines:
                attention[i, j] += 0.02

        # Additional attention based on linguistic features
        if token_to_spacy[i]:
            spacy_token = doc[token_to_spacy[i][0]]

            # Content words get stronger attention patterns
            if spacy_token.pos_ in ['NOUN', 'VERB', 'ADJ']:
                for end_idx in sentence_ends:
                    if end_idx < i:
                        attention[i, end_idx] *= 1.5

            # Function words attend more to sentence structure
            elif spacy_token.pos_ in ['ADP', 'CONJ', 'DET']:
                for nl_idx in newlines:
                    if nl_idx < i:
                        attention[i, nl_idx] *= 1.3

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L16H28", attention



def prog_L16H29(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Attention head with strong sentence-start bias and adjacent token patterns."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L16H29", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    # Identify sentence start positions (after newlines or at beginning)
    sentence_starts = [0]  # First token is always a sentence start
    for i in range(1, n):
        if i > 0 and tokens[i-1].strip() in ['\n']:
            sentence_starts.append(i)

    for i in range(n):
        # Self-attention baseline
        attention[i, i] = 0.3

        # Strong attention to sentence boundaries (periods, newlines)
        for j in range(i + 1):
            if tokens[j].strip() in ['.', '\n']:
                attention[i, j] += 0.4

        # Previous token attention (strong pattern)
        if i > 0:
            attention[i, i-1] += 0.5

        # First token bias
        if i > 0:
            attention[i, 0] += 0.2

        # NEW: Strong sentence-start bias - attend to beginning of current sentence
        current_sentence_start = 0
        for start_pos in sentence_starts:
            if start_pos <= i:
                current_sentence_start = start_pos
            else:
                break

        if i > current_sentence_start:
            # Strong attention to the start of the current sentence
            attention[i, current_sentence_start] += 0.6

        # Semantic similarity component
        for j in range(i + 1):
            sim = _char_sim(tokens[i], tokens[j])
            if sim > 0.7:  # High similarity threshold
                attention[i, j] += 0.3 * sim

        # Syntactic dependencies via spacy
        if token_to_spacy[i]:
            spacy_i = token_to_spacy[i][0]  # Take first aligned spacy token
            spacy_token = doc[spacy_i]

            # Attention to syntactic head
            if spacy_token.head != spacy_token:
                head_idx = spacy_token.head.i
                # Find corresponding LM token
                for j in range(i + 1):
                    if token_to_spacy[j] and head_idx in token_to_spacy[j]:
                        attention[i, j] += 0.3
                        break

        # Boost attention for adjacent content words
        for j in range(max(0, i-2), i):
            if token_to_spacy[j]:
                spacy_j = token_to_spacy[j][0]
                if spacy_j < len(doc):
                    spacy_tok = doc[spacy_j]
                    if spacy_tok.pos_ in ['NOUN', 'VERB', 'ADJ', 'ADV']:
                        attention[i, j] += 0.2

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L16H29", attention



def prog_L16H3(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Structural boundary detection head with emphasis on punctuation, early tokens, and document/paragraph starts."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L16H3", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        for j in range(i + 1):  # Causal mask
            weight = 0.0

            # Strong attention to punctuation, especially periods and newlines
            if tokens[j] in ['.', '\n']:
                weight += 0.3
            elif tokens[j] in [',', '!', '?']:
                weight += 0.15

            # Strong first-token bias
            if j == 0:
                weight += 0.2
            elif j < 3:  # Early tokens get some boost
                weight += 0.1

            # NEW: Strong document/paragraph start bias - tokens after newlines look back to document start
            # Find the most recent newline before token i
            recent_newline_pos = -1
            for k in range(i, -1, -1):
                if tokens[k] == '\n':
                    recent_newline_pos = k
                    break

            # If we're after a newline, boost attention to tokens at the very beginning
            if recent_newline_pos >= 0 and j <= 2:
                # Strong boost for looking back to document start from post-newline positions
                weight += 0.25

            # Attention to sentence/clause boundaries
            if token_to_spacy[j]:
                spacy_idx = token_to_spacy[j][0]
                if spacy_idx < len(doc):
                    spacy_token = doc[spacy_idx]
                    # Sentence boundaries
                    if spacy_token.is_sent_start or spacy_token.is_sent_end:
                        weight += 0.1
                    # Clause boundaries (conjunctions)
                    if spacy_token.pos_ == 'CCONJ' or spacy_token.dep_ in ['cc', 'mark']:
                        weight += 0.08

            # Self-attention baseline
            if i == j:
                weight += 0.05

            # Recency bias (closer tokens get slightly more attention)
            distance = i - j
            if distance > 0:
                weight += 0.02 / (1 + distance * 0.1)

            # Special attention patterns for specific structures
            if tokens[j].startswith('\n') and i > j:
                weight += 0.15

            # Boost for common function words at boundaries
            if token_to_spacy[j]:
                spacy_idx = token_to_spacy[j][0]
                if spacy_idx < len(doc):
                    spacy_token = doc[spacy_idx]
                    if spacy_token.pos_ in ['DET', 'ADP', 'PART'] and j < i:
                        weight += 0.03

            attention[i, j] = weight

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L16H3", attention



def prog_L16H30(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary detection head with strong document-start bias - attends heavily to first token and sentence markers."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    # Identify sentence boundary markers
    boundary_tokens = set()
    for i, token in enumerate(tokens):
        if token in [".", "!", "?", "\n"]:
            boundary_tokens.add(i)

    for i in range(n):
        # Base self-attention
        attention[i, i] = 0.1

        # Strong attention to sentence boundary markers
        for boundary_idx in boundary_tokens:
            if boundary_idx <= i:  # Causal constraint
                attention[i, boundary_idx] = 0.3

        # Attention to previous token
        if i > 0:
            attention[i, i-1] = 0.15

        # Additional attention to first token
        if i > 0:
            attention[i, 0] = 0.1

        # Boost attention for tokens that are parts of words ending sentences
        token = tokens[i]
        if any(char in token for char in ".!?"):
            for j in range(i+1):
                attention[i, j] *= 1.2

        # Special handling for quotes and commas near boundaries
        if token in ['"', "'", ",", ";"]:
            for boundary_idx in boundary_tokens:
                if boundary_idx <= i and abs(i - boundary_idx) <= 3:
                    attention[i, boundary_idx] = 0.25

    # NEW: Strong document-start bias - much higher attention to first token
    for i in range(1, n):
        attention[i, 0] = 0.4  # Much stronger than the original 0.1

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L16H30", attention



def prog_L16H31(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Attention head that focuses on sentence boundaries (periods, newlines) and first tokens, with long-range sentence-level attention."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L16H31", np.zeros((n_empty, n_empty)).reshape(0, 0)

    attention_matrix = np.zeros((n, n))

    # Parse with spacy to get linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        scores = np.zeros(i + 1)  # Only attend to previous tokens (causal)

        for j in range(i + 1):
            # Base attention score
            score = 0.01

            # Very high attention to periods and newlines
            if tokens[j].strip() in ['.', '\n']:
                score += 2.0
                # Special case: sentence boundaries get much less distance decay
                distance = i - j
                if distance > 0:
                    score *= (0.9 ** min(distance, 10))  # Cap decay for sentence boundaries
            else:
                # High attention to first token
                if j == 0:
                    score += 0.8
                    # First token also gets reduced distance decay
                    distance = i - j
                    if distance > 0:
                        score *= (0.85 ** min(distance, 8))
                else:
                    # Self-attention bonus (but reduce it to fix over-prediction)
                    if i == j:
                        score += 0.15  # Reduced from 0.3

                    # Regular distance decay for non-boundary tokens
                    distance = i - j
                    if distance > 0:
                        score *= (0.7 ** distance)

            # Semantic similarity bonus
            if i != j:
                sim = _char_sim(tokens[i], tokens[j])
                if sim > 0.3:
                    score += sim * 0.5

            # Special attention patterns for certain positions
            # Tokens near sentence boundaries get extra attention to boundaries
            if tokens[i].strip() in [',', '!', '?'] and tokens[j].strip() == '.':
                score += 1.0

            # Check if tokens share linguistic properties via spacy
            if token_to_spacy[i] and token_to_spacy[j]:
                spacy_i = doc[token_to_spacy[i][0]]
                spacy_j = doc[token_to_spacy[j][0]]

                # Verbs attending to subjects/objects
                if spacy_i.pos_ == 'VERB' and spacy_j.pos_ in ['NOUN', 'PRON']:
                    score += 0.2

                # Nouns attending to their modifiers
                if spacy_i.pos_ == 'NOUN' and spacy_j.pos_ == 'ADJ':
                    score += 0.15

            scores[j] = score

        # Normalize scores to create attention weights
        if scores.sum() > 0:
            attention_matrix[i, :i+1] = scores / scores.sum()
        else:
            attention_matrix[i, i] = 1.0  # Self-attention fallback

    # Apply causal mask and ensure row-stochastic
    attention_matrix = apply_causal_mask(attention_matrix)
    attention_matrix = make_row_stochastic(attention_matrix)

    return "prog_L16H31", attention_matrix



def prog_L16H4(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Syntactic dependency and semantic similarity attention with positional bias."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L16H4", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        # Get spacy tokens aligned with current token
        spacy_indices = token_to_spacy[i]

        for j in range(i + 1):  # Only attend to previous tokens (causal)
            weight = 0.0

            # Base positional decay
            distance = i - j
            if distance == 0:
                weight += 0.3  # Self attention
            elif distance == 1:
                weight += 0.2  # Previous token
            else:
                weight += 0.1 * (0.8 ** (distance - 1))  # Exponential decay

            # Strong attention to punctuation (periods, newlines, commas)
            if tokens[j] in [".", "\n", ",", "!", "?"]:
                weight += 0.4

            # Syntactic dependency relationships
            if spacy_indices and j < len(token_to_spacy):
                j_spacy_indices = token_to_spacy[j]

                for i_spacy in spacy_indices:
                    for j_spacy in j_spacy_indices:
                        if i_spacy < len(doc) and j_spacy < len(doc):
                            i_tok = doc[i_spacy]
                            j_tok = doc[j_spacy]

                            # Head-dependent relationships
                            if i_tok.head == j_tok or j_tok.head == i_tok:
                                weight += 0.5

                            # Verb-object relationships
                            if (i_tok.dep_ in ["dobj", "iobj"] and j_tok.pos_ == "VERB") or \
                               (j_tok.dep_ in ["dobj", "iobj"] and i_tok.pos_ == "VERB"):
                                weight += 0.4

                            # Preposition-object relationships
                            if (i_tok.dep_ == "pobj" and j_tok.pos_ == "ADP") or \
                               (j_tok.dep_ == "pobj" and i_tok.pos_ == "ADP"):
                                weight += 0.4

            # Semantic similarity boost
            similarity = _char_sim(tokens[i], tokens[j])
            if similarity > 0.7:
                weight += 0.3 * similarity
            elif similarity > 0.5:
                weight += 0.2 * similarity

            # Special patterns for specific token types
            if spacy_indices:
                for idx in spacy_indices:
                    if idx < len(doc):
                        tok = doc[idx]
                        # Pronouns attending to their antecedents
                        if tok.pos_ == "PRON" and j < i:
                            if j < len(token_to_spacy):
                                for j_idx in token_to_spacy[j]:
                                    if j_idx < len(doc) and doc[j_idx].pos_ == "NOUN":
                                        weight += 0.3

            attention[i, j] = weight

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L16H4", attention



def prog_L16H5(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary and discourse structure attention head with strong first-token attention."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        token_i = tokens[i]

        # Strong attention to sentence boundary markers (periods and newlines)
        for j in range(i + 1):
            token_j = tokens[j]

            # High attention to newlines and periods
            if token_j.strip() in ['.', '\n']:
                attention[i, j] = 0.3

            # Self-attention baseline
            if i == j:
                attention[i, j] = 0.1

            # ENHANCED: Much stronger attention to the very first token
            if j == 0:
                # Scale first token attention based on position in sequence
                # Tokens further from start attend more strongly to beginning
                first_token_strength = 0.2 + (i / max(1, n - 1)) * 0.4
                attention[i, j] = first_token_strength

        # Additional attention patterns based on position and context
        for j in range(i + 1):
            token_j = tokens[j]

            # If current token is at end of sentence/section, attend strongly to boundaries
            spacy_indices_i = token_to_spacy[i]
            if spacy_indices_i:
                spacy_token_i = doc[spacy_indices_i[0]]
                # Check if this token is near sentence end
                if (spacy_token_i.is_sent_end or 
                    (i < n - 1 and tokens[i + 1].strip() in ['.', '\n']) or
                    any(child.text in ['.', '\n'] for child in spacy_token_i.children if hasattr(child, 'children'))):
                    if token_j.strip() in ['.', '\n']:
                        attention[i, j] *= 2.0

            # Semantic similarity boost for related tokens
            if i != j and j < i:
                sim = _char_sim(tokens[i], tokens[j])
                if sim > 0.3:  # Threshold for semantic relatedness
                    attention[i, j] += 0.05 * sim

            # Boost attention to tokens that are part of the same syntactic unit
            spacy_indices_j = token_to_spacy[j]
            if spacy_indices_i and spacy_indices_j and spacy_indices_i and spacy_indices_j:
                try:
                    spacy_i = doc[spacy_indices_i[0]]
                    spacy_j = doc[spacy_indices_j[0]]

                    # If tokens are in dependency relation
                    if (spacy_j in spacy_i.ancestors or spacy_i in spacy_j.ancestors or
                        spacy_i.head == spacy_j.head):
                        attention[i, j] += 0.02
                except:
                    pass

        # Recency bias - slight preference for more recent tokens
        for j in range(max(0, i - 5), i):
            if attention[i, j] > 0:
                decay_factor = 1.0 + 0.1 * (j - max(0, i - 5)) / 5.0
                attention[i, j] *= decay_factor

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L16H5", attention



def prog_L16H6(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Semantic coherence head with strong beginning-of-sequence attention pattern."""
    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L16H6", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    alignment = _align_to_spacy(sentence, tokens)

    # Identify sentence boundary tokens (periods, newlines)
    boundary_tokens = set()
    for i, token in enumerate(tokens):
        if token.strip() in ['.', '\n']:
            boundary_tokens.add(i)

    for i in range(n):
        query_token = tokens[i]

        # Self-attention baseline
        attention[i, i] = 0.3

        # Strong attention to sentence boundaries
        for boundary_idx in boundary_tokens:
            if boundary_idx <= i:
                attention[i, boundary_idx] = 0.8

        # NEW: Strong attention to beginning-of-sequence tokens
        # Tokens in positions 0-5 get high attention from all later tokens
        if i > 5:
            for j in range(min(6, i)):
                attention[i, j] += 0.7

        # Semantic similarity attention within local context
        for j in range(i):
            sim = _char_sim(tokens[i], tokens[j])

            # Higher weight for semantically similar tokens
            if sim > 0.3:
                attention[i, j] += sim * 0.6

            # Positional decay - prefer more recent tokens
            distance = i - j
            if distance <= 10:
                positional_weight = 1.0 / (1 + distance * 0.1)
                attention[i, j] += positional_weight * 0.2

            # Boost attention to content words
            if j < len(alignment) and alignment[j]:
                spacy_indices = alignment[j]
                for spacy_idx in spacy_indices:
                    if spacy_idx < len(doc):
                        spacy_token = doc[spacy_idx]
                        if spacy_token.pos_ in ['NOUN', 'VERB', 'ADJ']:
                            attention[i, j] += 0.3

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L16H6", attention



def prog_L16H7(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary attention head with enhanced self-attention for content words."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L16H7", np.zeros((n_empty, n_empty)).reshape(0, 0)

    attention = np.zeros((n, n))

    # Parse with spacy for sentence boundaries
    doc = spacy_parse(sentence)
    alignment = _align_to_spacy(sentence, tokens)

    # Identify sentence boundary tokens (periods, newlines)
    boundary_tokens = set()
    first_tokens = set()

    for i, token in enumerate(tokens):
        # Check for sentence boundary punctuation
        if token.strip() in ['.', '!', '?'] or token == '\n':
            boundary_tokens.add(i)

        # Check if this is the first token of a sentence
        spacy_indices = alignment[i]
        for spacy_idx in spacy_indices:
            if spacy_idx < len(doc):
                spacy_token = doc[spacy_idx]
                # First token in sentence or after newline
                if spacy_token.is_sent_start or (i > 0 and tokens[i-1] == '\n'):
                    first_tokens.add(i)

    # Add first token as boundary
    if n > 0:
        first_tokens.add(0)

    # Identify content words that should have higher self-attention
    content_tokens = set()
    for i, token in enumerate(tokens):
        spacy_indices = alignment[i]
        for spacy_idx in spacy_indices:
            if spacy_idx < len(doc):
                spacy_token = doc[spacy_idx]
                # Content words: nouns, verbs, adjectives, proper nouns
                if spacy_token.pos_ in ['NOUN', 'VERB', 'ADJ', 'PROPN'] and len(token.strip()) > 2:
                    content_tokens.add(i)

    for i in range(n):
        # Base attention distribution
        for j in range(i + 1):

            # Very high attention to sentence boundaries
            if j in boundary_tokens:
                if tokens[j] == '\n':
                    attention[i, j] = 0.25  # Strong attention to newlines
                elif tokens[j].strip() in ['.', '!', '?']:
                    attention[i, j] = 0.15  # Strong attention to periods

            # High attention to first tokens of sentences
            elif j in first_tokens:
                attention[i, j] = 0.08

            # Self-attention - enhanced for content words
            elif i == j:
                if i in content_tokens:
                    attention[i, j] = 0.12  # Higher self-attention for content words
                else:
                    attention[i, j] = 0.05

            # Reduced attention to newlines from distant tokens
            elif tokens[j] == '\n' and i - j > 5:
                attention[i, j] = 0.005  # Much lower attention to distant newlines

            # Positional bias - recent tokens get more attention
            elif i - j <= 3:
                attention[i, j] = 0.03 / (1 + (i - j))

            # Base attention for other positions
            else:
                attention[i, j] = 0.01

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L16H7", attention



def prog_L16H8(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Structural attention head focusing on sentence boundaries and sequence starts."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    if n == 0:
        return "prog_L16H8", attention

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        # Strong attention to first token
        attention[i, 0] = 0.3

        # High attention to structural tokens (newlines, periods)
        for j in range(i + 1):
            token = tokens[j].strip()

            # Very high attention to newlines and periods
            if token == '\n':
                attention[i, j] = 0.4
            elif token == '.':
                attention[i, j] = 0.3
            elif token == '!':
                attention[i, j] = 0.2

        # Self-attention
        attention[i, i] += 0.1

        # Local attention to previous few tokens
        for offset in range(1, min(4, i + 1)):
            j = i - offset
            attention[i, j] += 0.05 / offset

        # Attention based on spacy features
        spacy_indices = token_to_spacy[i]
        for spacy_idx in spacy_indices:
            if spacy_idx < len(doc):
                spacy_token = doc[spacy_idx]

                # Attend to sentence start tokens
                if spacy_token.is_sent_start:
                    for j in range(i + 1):
                        if j in range(max(0, spacy_idx - 2), min(len(tokens), spacy_idx + 3)):
                            attention[i, j] += 0.1

                # Attend to proper nouns and capitalized words
                if spacy_token.pos_ == 'PROPN' or (spacy_token.text and spacy_token.text[0].isupper()):
                    for j in range(i + 1):
                        if tokens[j].strip() and tokens[j].strip()[0].isupper():
                            attention[i, j] += 0.05

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L16H8", attention



def prog_L16H9(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary attention head with strong first-token attention."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention_matrix = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        for j in range(i + 1):  # Causal mask
            weight = 0.0

            # Very strong attention to periods and newlines
            if tokens[j] in ['.', '\n']:
                if tokens[j] == '.':
                    weight = 0.25
                else:  # newline
                    weight = 0.20

            # Self-attention baseline
            elif i == j:
                weight = 0.08

            # Strong first token attention - major boost for this pattern
            elif j == 0:
                # Much stronger attention to first token based on distance
                if i <= 10:
                    weight = 0.35
                elif i <= 20:
                    weight = 0.30
                else:
                    weight = 0.25

            # Moderate attention to commas and quotes
            elif tokens[j] in [',', '"', "'", '!', '?']:
                weight = 0.05

            # Syntactic relationships using spacy
            else:
                spacy_i = token_to_spacy[i]
                spacy_j = token_to_spacy[j]

                if spacy_i and spacy_j:
                    spacy_tok_i = doc[spacy_i[0]]
                    spacy_tok_j = doc[spacy_j[0]]

                    # Attention to syntactic head
                    if spacy_tok_j == spacy_tok_i.head:
                        weight = 0.04

                    # Attention between related tokens (same dependency subtree)
                    elif spacy_tok_i.head == spacy_tok_j.head and spacy_tok_i.head != spacy_tok_i:
                        weight = 0.03

                    # Verb-object relationships
                    elif (spacy_tok_i.dep_ in ['dobj', 'pobj', 'nsubj'] and 
                          spacy_tok_j.pos_ == 'VERB'):
                        weight = 0.035

                # Semantic similarity boost
                sim = _char_sim(tokens[i], tokens[j])
                if sim > 0.5:
                    weight += 0.02 * sim

                # Distance decay for non-punctuation
                distance = i - j
                if distance > 1:
                    weight *= (0.8 ** (distance - 1))

            attention_matrix[i, j] = weight

    attention_matrix = apply_causal_mask(attention_matrix)
    attention_matrix = make_row_stochastic(attention_matrix)

    return "prog_L16H9", attention_matrix



def prog_L17H0(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Attention head that focuses on sentence boundaries and first tokens with local syntactic structure."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L17H0", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    # Identify structural tokens
    newline_indices = [i for i, tok in enumerate(tokens) if tok.strip() == '']
    period_indices = [i for i, tok in enumerate(tokens) if tok.strip() == '.']

    for i in range(n):
        # Strong self-attention for first token
        if i == 0:
            attention[i, i] = 1.0
            continue

        # Base attention distribution
        for j in range(i + 1):

            # Strong attention to first token from most positions
            if j == 0:
                attention[i, j] = 0.3

            # High attention to newlines and periods
            elif j in newline_indices:
                attention[i, j] = 0.35
            elif j in period_indices:
                attention[i, j] = 0.25

            # Local syntactic attention
            elif abs(i - j) <= 2:
                # Get spacy tokens for syntactic analysis
                spacy_i = token_to_spacy[i] if i < len(token_to_spacy) and token_to_spacy[i] else []
                spacy_j = token_to_spacy[j] if j < len(token_to_spacy) and token_to_spacy[j] else []

                syntactic_bonus = 0.0

                # Check for syntactic relationships
                if spacy_i and spacy_j:
                    for si in spacy_i:
                        for sj in spacy_j:
                            if si < len(doc) and sj < len(doc):
                                spacy_tok_i = doc[si]
                                spacy_tok_j = doc[sj]

                                # Head-dependent relationships
                                if spacy_tok_i.head == spacy_tok_j or spacy_tok_j.head == spacy_tok_i:
                                    syntactic_bonus += 0.15

                                # Modifier relationships
                                if spacy_tok_j.dep_ in ['amod', 'det', 'poss']:
                                    syntactic_bonus += 0.1

                # Embedding similarity bonus for nearby tokens
                sim = _char_sim(tokens[i], tokens[j])
                if sim > 0.7:
                    syntactic_bonus += 0.1

                # Adjacent token attention
                if j == i - 1:
                    attention[i, j] = 0.15 + syntactic_bonus
                else:
                    attention[i, j] = 0.05 + syntactic_bonus

            # Self-attention
            elif i == j:
                attention[i, j] = 0.1

            # Distant tokens get minimal attention
            else:
                attention[i, j] = 0.02

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L17H0", attention



def prog_L17H1(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary detection head - attends to sentence start tokens and structural markers."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    # Identify boundary tokens (newlines, periods, first token)
    boundary_indices = set()

    for i, token in enumerate(tokens):
        # Add newlines and periods as strong boundary markers
        if token.strip() in ['\n', '.']:
            boundary_indices.add(i)
        # Add first token
        if i == 0:
            boundary_indices.add(i)

    # Find sentence start positions (first token and tokens after newlines)
    sentence_starts = [0]  # First token is always a sentence start
    for i, token in enumerate(tokens):
        if token.strip() == '\n' and i + 1 < n:
            sentence_starts.append(i + 1)

    for i in range(n):
        current_token = tokens[i].strip()

        # Self-attention baseline
        attention[i, i] = 0.1

        # Strong attention to boundary markers (newlines and periods)
        for boundary_idx in boundary_indices:
            if boundary_idx <= i:  # Causal mask
                if tokens[boundary_idx].strip() == '\n':
                    # Very strong attention to newlines
                    attention[i, boundary_idx] = 0.4
                elif tokens[boundary_idx].strip() == '.':
                    # Strong attention to periods
                    attention[i, boundary_idx] = 0.3
                elif boundary_idx == 0:
                    # Moderate attention to first token
                    attention[i, boundary_idx] = 0.1

        # NEW: Strong attention to current sentence start
        current_sentence_start = None
        for start_pos in reversed(sentence_starts):
            if start_pos <= i:
                current_sentence_start = start_pos
                break

        if current_sentence_start is not None and current_sentence_start != i:
            # Very strong attention to the start of current sentence
            attention[i, current_sentence_start] = 0.7

        # Additional attention patterns for specific token types
        if current_token in ['\n', '.']:
            # Boundary tokens attend strongly to themselves
            attention[i, i] = 0.4

        # Distribute remaining attention to nearby tokens
        for j in range(i):
            if j not in boundary_indices and j != current_sentence_start:
                # Small baseline attention to previous tokens
                distance = i - j
                attention[i, j] += 0.05 / (1 + distance * 0.1)

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L17H1", attention



def prog_L17H10(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Structural attention head with very strong focus on first token and sentence boundaries."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L17H10", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    for i in range(n):
        for j in range(i + 1):  # Causal mask
            weight = 0.0

            # Very strong attention to first token - much higher than original
            if j == 0:
                weight += 0.8

            # Strong attention to periods
            if tokens[j].strip() == '.':
                weight += 0.35

            # Strong attention to newlines
            if tokens[j].strip() == '\n' or tokens[j] == '\n':
                weight += 0.3

            # Reduced self-attention to compensate for stronger first-token attention
            if i == j:
                weight += 0.05

            # Moderate attention to commas
            if tokens[j].strip() == ',':
                weight += 0.1

            # Small attention to other punctuation
            if tokens[j].strip() in ['!', '?', ';', ':', '"', "'", '(', ')', '[', ']']:
                weight += 0.05

            # Distance decay for nearby tokens
            distance = i - j
            if distance <= 3:
                weight += 0.02 * (4 - distance)

            # Base attention for all positions
            weight += 0.01

            attention[i, j] = weight

    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L17H10", attention



def prog_L17H11(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Mixed attention head: combines first-token bias, boundary markers, and local syntax."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L17H11", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        # Strong self-attention baseline
        attention[i, i] = 0.3

        # Very strong attention to first token
        if i > 0:
            attention[i, 0] = 0.4

        # High attention to sentence boundaries (periods, newlines)
        for j in range(i + 1):
            token_j = tokens[j].strip()
            if token_j in ['.', '\n']:
                attention[i, j] += 0.2

        # Local syntactic attention within recent context
        if len(token_to_spacy[i]) > 0:
            spacy_i_idx = token_to_spacy[i][0]
            spacy_token_i = doc[spacy_i_idx]

            # Look at recent tokens for syntactic relationships
            window_start = max(0, i - 8)
            for j in range(window_start, i):
                if len(token_to_spacy[j]) > 0:
                    spacy_j_idx = token_to_spacy[j][0]
                    spacy_token_j = doc[spacy_j_idx]

                    # Syntactic dependencies
                    if (spacy_token_i.head == spacy_token_j or 
                        spacy_token_j.head == spacy_token_i):
                        attention[i, j] += 0.15

                    # Subject-verb relationships
                    if (spacy_token_i.dep_ in ['nsubj', 'nsubjpass'] and 
                        spacy_token_j.pos_ == 'VERB'):
                        attention[i, j] += 0.1
                    elif (spacy_token_j.dep_ in ['nsubj', 'nsubjpass'] and 
                          spacy_token_i.pos_ == 'VERB'):
                        attention[i, j] += 0.1

                    # Semantic similarity boost for related content words
                    if (spacy_token_i.pos_ in ['NOUN', 'VERB', 'ADJ'] and
                        spacy_token_j.pos_ in ['NOUN', 'VERB', 'ADJ']):
                        sim = _char_sim(tokens[i], tokens[j])
                        if sim > 0.5:
                            attention[i, j] += 0.08 * sim

        # Distance decay for non-special positions
        for j in range(i):
            if tokens[j].strip() not in ['.', '\n'] and j != 0:
                distance = i - j
                decay = max(0.01, 1.0 / (1 + 0.3 * distance))
                attention[i, j] *= decay

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L17H11", attention



def prog_L17H12(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Structural boundary attention head with strong first-token attention pattern."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention_matrix = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        token_i = tokens[i]

        # Strong self-attention for first token
        if i == 0:
            attention_matrix[i, i] = 1.0
            continue

        # Initialize with small uniform attention to earlier tokens
        for j in range(i + 1):
            attention_matrix[i, j] = 0.01

        # NEW: Strong attention to first token from all subsequent tokens
        attention_matrix[i, 0] += 0.6

        # High attention to structural markers (newlines, periods, sentence boundaries)
        for j in range(i + 1):
            token_j = tokens[j]

            # Very high attention to newlines
            if token_j.strip() == '' and '\n' in token_j:
                attention_matrix[i, j] += 0.4

            # High attention to sentence-ending punctuation
            elif token_j in ['.', '!', '?']:
                attention_matrix[i, j] += 0.3

            # Moderate attention to other punctuation
            elif token_j in [',', ';', ':']:
                attention_matrix[i, j] += 0.1

        # Add positional bias - prefer recent tokens
        for j in range(i + 1):
            distance = i - j
            if distance <= 5:
                attention_matrix[i, j] += 0.05 / (distance + 1)

        # Add semantic similarity component
        for j in range(i + 1):
            sim = _char_sim(tokens[i], tokens[j])
            if sim > 0.3:  # Only boost if reasonably similar
                attention_matrix[i, j] += 0.1 * sim

        # Boost attention to tokens with similar POS tags
        if token_to_spacy[i]:
            spacy_i = doc[token_to_spacy[i][0]]
            for j in range(i + 1):
                if token_to_spacy[j]:
                    spacy_j = doc[token_to_spacy[j][0]]
                    if spacy_i.pos_ == spacy_j.pos_ and spacy_i.pos_ in ['NOUN', 'VERB', 'ADJ']:
                        attention_matrix[i, j] += 0.05

    # Apply causal mask and normalize
    attention_matrix = apply_causal_mask(attention_matrix)
    attention_matrix = make_row_stochastic(attention_matrix)

    return "prog_L17H12", attention_matrix



def prog_L17H13(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Structural boundary detection with enhanced local adjacency attention."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L17H13", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        # Base uniform attention to all previous tokens (including self)
        for j in range(i + 1):
            attention[i, j] = 0.01

        # Strong self-attention for first token
        if i == 0:
            attention[i, i] = 0.8
            continue

        # High attention to sentence boundaries (periods and newlines)
        for j in range(i + 1):
            if tokens[j] in [".", "\n"]:
                attention[i, j] += 0.3

        # Strong attention to first token from most positions
        attention[i, 0] += 0.15

        # Enhanced adjacent token attention with semantic boost
        if i > 0:
            base_adjacent = 0.1
            # Check for strong semantic relationship with previous token
            sim = _char_sim(tokens[i], tokens[i-1])
            if sim > 0.3:  # Lower threshold to catch more relationships
                base_adjacent += 0.25  # Significant boost for semantically related adjacent tokens
            attention[i, i-1] += base_adjacent

        # Syntactic dependencies
        if token_to_spacy[i]:
            spacy_i = token_to_spacy[i][0]
            spacy_token = doc[spacy_i]

            # Attend to syntactic head
            if spacy_token.head != spacy_token:
                head_idx = spacy_token.head.i
                for j in range(i + 1):
                    if j < len(token_to_spacy) and token_to_spacy[j]:
                        if head_idx in token_to_spacy[j]:
                            attention[i, j] += 0.2

            # Attend to modifiers and children
            for child in spacy_token.children:
                child_idx = child.i
                for j in range(i + 1):
                    if j < len(token_to_spacy) and token_to_spacy[j]:
                        if child_idx in token_to_spacy[j]:
                            attention[i, j] += 0.15

        # Semantic similarity boost
        for j in range(i + 1):
            if i != j:
                sim = _char_sim(tokens[i], tokens[j])
                if sim > 0.7:
                    attention[i, j] += 0.2
                elif sim > 0.5:
                    attention[i, j] += 0.1

        # Self-attention boost for punctuation
        if tokens[i] in [".", ",", "!", "?", "\n"]:
            attention[i, i] += 0.3

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L17H13", attention



def prog_L17H14(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Structural boundary attention with semantic similarity component."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L17H14", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        for j in range(i + 1):  # Causal mask
            weight = 0.0

            # Strong attention to newlines and periods
            if tokens[j].strip() == '\n':
                weight += 0.3
            elif tokens[j].strip() == '.':
                weight += 0.25

            # Strong attention to first token
            if j == 0:
                weight += 0.15

            # Self-attention baseline
            if i == j:
                weight += 0.02

            # Adjacent token attention
            if j == i - 1:
                weight += 0.05

            # Semantic similarity component
            sim = _char_sim(tokens[i], tokens[j])
            if sim > 0.7:
                weight += 0.1 * sim

            # Syntactic dependency attention
            if token_to_spacy[i] and token_to_spacy[j]:
                for spacy_i in token_to_spacy[i]:
                    for spacy_j in token_to_spacy[j]:
                        if spacy_i < len(doc) and spacy_j < len(doc):
                            spacy_token_i = doc[spacy_i]
                            spacy_token_j = doc[spacy_j]

                            # Attention between head and dependents
                            if spacy_token_j in spacy_token_i.children:
                                weight += 0.08
                            elif spacy_token_i.head == spacy_token_j:
                                weight += 0.08

            # Special attention patterns for punctuation
            if tokens[i] == ',' and j < i:
                # Commas attend to recent content words
                if token_to_spacy[j]:
                    for spacy_j in token_to_spacy[j]:
                        if spacy_j < len(doc) and doc[spacy_j].pos_ in ['NOUN', 'VERB', 'ADJ']:
                            weight += 0.05

            attention[i, j] = weight

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L17H14", attention



def prog_L17H15(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Structural boundary attention with enhanced first-token focus and refined punctuation handling."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        for j in range(i + 1):  # Causal mask
            weight = 0.0

            # Strong attention to structural boundaries
            if tokens[j] == '\n':
                weight += 0.35
            elif tokens[j] == '.':
                weight += 0.25

            # High self-attention for first token
            if i == 0 and j == 0:
                weight += 0.8

            # Self-attention baseline
            if i == j:
                weight += 0.1

            # Attention to first token from other positions - BOOSTED
            if j == 0 and i > 0:
                # Much stronger attention to first token
                weight += 0.6

            # Local syntactic attention - adjacent tokens
            if abs(i - j) == 1:
                weight += 0.08

            # Semantic similarity boost
            if i != j:
                sim = _char_sim(tokens[i], tokens[j])
                if sim > 0.7:
                    weight += 0.1

            # Special punctuation attention - but reduce self-attention
            if tokens[j] in [',', '!', '?"', '."']:
                if i != j:  # Only boost attention TO punctuation, not self-attention
                    weight += 0.1

            # Positional decay
            distance = i - j
            if distance > 0:
                decay = 1.0 / (1.0 + 0.05 * distance)
                weight *= decay

            # Boost for tokens that are close to sentence boundaries
            if token_to_spacy[j]:
                spacy_token = doc[token_to_spacy[j][0]]
                if spacy_token.is_sent_start or spacy_token.is_sent_end:
                    weight += 0.12

            # Reduce over-attention from tokens immediately following newlines
            if i > 0 and tokens[i-1] == '\n' and tokens[j] == '\n':
                weight *= 0.3

            attention[i, j] = weight

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L17H15", attention



def prog_L17H16(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Punctuation and boundary detection head with enhanced period relevance detection."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention_matrix = np.zeros((n, n))

    # Find periods and newlines
    period_indices = [i for i, token in enumerate(tokens) if token.strip() == '.']
    newline_indices = [i for i, token in enumerate(tokens) if token == '\n']

    for i in range(n):
        # Base uniform attention to all previous tokens
        for j in range(i + 1):
            attention_matrix[i, j] = 0.01

        # Strong attention to periods
        for period_idx in period_indices:
            if period_idx <= i:
                attention_matrix[i, period_idx] = 0.4

        # Strong attention to newlines
        for newline_idx in newline_indices:
            if newline_idx <= i:
                attention_matrix[i, newline_idx] = 0.5

        # Special case: if current token is a newline, attend strongly to previous period
        if tokens[i] == '\n' and period_indices:
            closest_period = None
            for period_idx in period_indices:
                if period_idx < i:
                    closest_period = period_idx
            if closest_period is not None:
                attention_matrix[i, closest_period] = 0.6

        # Very high attention to first token (position 0)
        if i > 0:
            attention_matrix[i, 0] = 0.7

        # Self-attention for punctuation
        if tokens[i] in ['.', '\n', ',', '!', '?']:
            attention_matrix[i, i] = 0.4

        # Enhanced period relevance: tokens far from recent periods attend more to distant periods
        if period_indices and i > 0:
            # Find the most recent period
            most_recent_period = None
            for period_idx in period_indices:
                if period_idx < i:
                    most_recent_period = period_idx

            # If we're far from the most recent period, boost attention to earlier periods
            if most_recent_period is not None:
                distance_from_recent = i - most_recent_period
                if distance_from_recent > 20:  # Far from recent period
                    for period_idx in period_indices:
                        if period_idx < most_recent_period:  # Earlier periods
                            # Boost attention to earlier periods when far from recent ones
                            attention_matrix[i, period_idx] = min(0.8, attention_matrix[i, period_idx] + 0.3)

    attention_matrix = apply_causal_mask(attention_matrix)
    attention_matrix = make_row_stochastic(attention_matrix)

    return "prog_L17H16", attention_matrix



def prog_L17H17(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Salient token attention with enhanced early-token anchoring behavior."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L17H17", np.zeros((n_empty, n_empty))

    attention_matrix = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    # Identify salient tokens
    salient_scores = np.zeros(n)

    for i, token in enumerate(tokens):
        # High salience for punctuation (especially periods and newlines)
        if token.strip() in ['.', '\n', '!', '?']:
            salient_scores[i] = 1.0
        elif token.strip() in [',', ';', ':']:
            salient_scores[i] = 0.5

        # High salience for first token
        if i == 0:
            salient_scores[i] = max(salient_scores[i], 0.8)

        # Content word salience based on spacy features
        spacy_indices = token_to_spacy[i]
        if spacy_indices:
            spacy_token = doc[spacy_indices[0]]

            # High salience for content words
            if spacy_token.pos_ in ['NOUN', 'VERB', 'ADJ', 'PROPN']:
                salient_scores[i] = max(salient_scores[i], 0.6)

            # Medium salience for other important POS
            elif spacy_token.pos_ in ['PRON', 'ADV', 'NUM']:
                salient_scores[i] = max(salient_scores[i], 0.3)

            # Boost for named entities
            if spacy_token.ent_type_:
                salient_scores[i] = max(salient_scores[i], 0.7)

    # Build attention matrix
    for i in range(n):
        for j in range(i + 1):  # Causal mask
            weight = 0.0

            # Base attention to salient tokens
            weight += salient_scores[j] * 0.7

            # Strong bias toward first token
            if j == 0:
                weight += 0.8

            # Enhanced early-token anchoring: tokens pay much higher attention to very early positions
            if i > 5 and j <= 2:
                weight += 1.5  # Strong boost for attention to first few tokens from later positions

            # Reduced self-attention component for better calibration
            if i == j:
                weight += 0.1  # Reduced from 0.2 to 0.1

            # Recency bias (prefer recent tokens)
            if i > 0:
                recency = 1.0 / (1.0 + (i - j))
                weight += recency * 0.3

            # Semantic similarity boost
            if j < i:
                sim = _char_sim(tokens[i], tokens[j])
                if sim > 0.5:
                    weight += sim * 0.4

            attention_matrix[i, j] = weight

    # Apply causal mask and normalize
    attention_matrix = apply_causal_mask(attention_matrix)
    attention_matrix = make_row_stochastic(attention_matrix)

    return "prog_L17H17", attention_matrix



def prog_L17H18(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary and structural marker attention head with enhanced newline focus."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L17H18", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    alignment = _align_to_spacy(sentence, tokens)

    for i in range(n):
        # Strong self-attention for first token
        if i == 0:
            attention[i, i] = 1.0
            continue

        # Initialize base attention
        for j in range(i + 1):

            # Very high attention to newlines (enhanced from original)
            if tokens[j].strip() == '\n':
                attention[i, j] = 0.7

            # High attention to periods
            elif tokens[j].strip() == '.':
                attention[i, j] = 0.3

            # Moderate attention to first token
            elif j == 0:
                attention[i, j] = 0.15

            # Check if token j starts a sentence (using spacy alignment) - reduced weight
            elif alignment[j]:
                spacy_idx = alignment[j][0]
                if spacy_idx < len(doc):
                    spacy_token = doc[spacy_idx]
                    # Reduced attention to sentence-initial tokens
                    if spacy_token.is_sent_start:
                        attention[i, j] = 0.1

            # Low baseline attention to other positions
            if attention[i, j] == 0:
                attention[i, j] = 0.02

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L17H18", attention



def prog_L17H19(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary and structural marker attention with strong first-token bias."""
    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L17H19", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        # Find sentence boundary markers (periods, newlines)
        boundary_indices = []
        for j in range(i + 1):  # causal mask
            if tokens[j] in ['.', '\n']:
                boundary_indices.append(j)

        # Base attention distribution
        for j in range(i + 1):  # causal mask
            # High attention to sentence boundaries
            if tokens[j] in ['.', '\n']:
                if tokens[j] == '\n':
                    attention[i, j] = 0.25  # Strong attention to newlines
                else:  # period
                    attention[i, j] = 0.20  # Strong attention to periods

            # Self-attention
            elif i == j:
                attention[i, j] = 0.08

            # Previous token attention
            elif j == i - 1:
                attention[i, j] = 0.05

            # Syntactic dependencies
            elif len(token_to_spacy[i]) > 0 and len(token_to_spacy[j]) > 0:
                spacy_i = token_to_spacy[i][0]
                spacy_j = token_to_spacy[j][0]

                if spacy_i < len(doc) and spacy_j < len(doc):
                    tok_i = doc[spacy_i]
                    tok_j = doc[spacy_j]

                    # Dependency relations
                    if tok_i.head == tok_j or tok_j.head == tok_i:
                        attention[i, j] = 0.04

                    # Semantic similarity for content words
                    elif tok_i.pos_ in ['NOUN', 'VERB', 'ADJ'] and tok_j.pos_ in ['NOUN', 'VERB', 'ADJ']:
                        sim = _char_sim(tokens[i], tokens[j])
                        if sim > 0.7:
                            attention[i, j] = 0.03
                        else:
                            attention[i, j] = 0.015
                    else:
                        attention[i, j] = 0.015
            else:
                attention[i, j] = 0.015

        # Strong attention to first token (much more aggressive than original)
        if i > 0:
            attention[i, 0] += 0.25

    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L17H19", attention



def prog_L17H2(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Attention to structural boundaries and first token with positional decay."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L17H2", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        # Strong self-attention for first token
        if i == 0:
            attention[i, i] = 1.0
            continue

        # Initialize with small uniform attention to all previous tokens
        for j in range(i + 1):
            attention[i, j] = 0.01

        # High attention to newline tokens
        newline_boost = 0.0
        for j in range(i):
            if tokens[j].strip() == '' and '\n' in tokens[j]:
                attention[i, j] += 0.4
                newline_boost += 0.4

        # High attention to sentence-ending punctuation
        punct_boost = 0.0
        for j in range(i):
            if tokens[j].strip() in ['.', '!', '?']:
                attention[i, j] += 0.25
                punct_boost += 0.25

        # Self-attention boost
        attention[i, i] += 0.1

        # Positional decay - stronger attention to recent tokens
        for j in range(max(0, i-5), i):
            distance = i - j
            decay = 1.0 / (1 + 0.3 * distance)
            attention[i, j] += 0.05 * decay

        # Strong attention to first token from all positions
        if i > 0:
            # Find first non-punctuation, non-whitespace token
            first_content_idx = 0
            for k in range(min(3, n)):  # Look at first few tokens only
                token_text = tokens[k].strip()
                if token_text and token_text not in ['.', '!', '?', ',', ';', ':', '"', "'", '(', ')', '[', ']']:
                    first_content_idx = k
                    break

            # Strong boost to first content token
            attention[i, first_content_idx] += 0.5

        # Syntactic relationships
        if token_to_spacy[i]:
            spacy_i = token_to_spacy[i][0]
            if spacy_i < len(doc):
                spacy_token = doc[spacy_i]

                # Prepositions attend to their objects
                if spacy_token.pos_ == 'ADP':
                    for child in spacy_token.children:
                        if child.dep_ in ['pobj', 'prep']:
                            # Find corresponding token indices
                            for k in range(len(doc)):
                                if doc[k] == child:
                                    # Find overlapping tokens
                                    for j in range(i):
                                        if token_to_spacy[j] and k in token_to_spacy[j]:
                                            attention[i, j] += 0.15

                # Verbs attend to their subjects/objects  
                if spacy_token.pos_ == 'VERB':
                    for child in spacy_token.children:
                        if child.dep_ in ['nsubj', 'dobj', 'nsubjpass']:
                            for k in range(len(doc)):
                                if doc[k] == child:
                                    for j in range(i):
                                        if token_to_spacy[j] and k in token_to_spacy[j]:
                                            attention[i, j] += 0.1

        # Adjacent token attention
        if i > 0:
            attention[i, i-1] += 0.08

        # Similarity-based attention
        for j in range(max(0, i-10), i):
            sim = _char_sim(tokens[i], tokens[j])
            if sim > 0.7:
                attention[i, j] += 0.1 * (sim - 0.7)

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L17H2", attention



def prog_L17H20(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Structural boundary attention with enhanced first-token anchoring."""
    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L17H20", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    # Identify structural boundaries
    boundary_tokens = set()
    for i, token in enumerate(tokens):
        if token.strip() in ['\n', '.', '!', '?', ';"', '."', '!"', '?"']:
            boundary_tokens.add(i)

    for i in range(n):
        # Base self-attention
        attention[i, i] = 0.1

        # Strong attention to boundary tokens (newlines, periods)
        for boundary_idx in boundary_tokens:
            if boundary_idx <= i:
                attention[i, boundary_idx] = 0.3

        # High attention to first token
        attention[i, 0] = 0.2

        # Enhanced first-token attention for structural sequences
        if i >= 2 and tokens[0].strip() in [',', '.', '!', '?', ';']:
            # If first token is punctuation, much stronger attention from later tokens
            if i >= 5:  # Only for tokens well into the sequence
                attention[i, 0] = 0.6
            elif i >= 3:
                attention[i, 0] = 0.4

        # Syntactic relationships using spacy
        if token_to_spacy[i]:
            spacy_idx = token_to_spacy[i][0]
            if spacy_idx < len(doc):
                current_spacy = doc[spacy_idx]

                # Attend to syntactic head
                if current_spacy.head != current_spacy:
                    for j in range(i):
                        if token_to_spacy[j] and token_to_spacy[j][0] < len(doc):
                            if doc[token_to_spacy[j][0]] == current_spacy.head:
                                attention[i, j] += 0.15

                # Attend to syntactic children
                for child in current_spacy.children:
                    for j in range(i):
                        if token_to_spacy[j] and token_to_spacy[j][0] < len(doc):
                            if doc[token_to_spacy[j][0]] == child:
                                attention[i, j] += 0.1

        # Semantic similarity component
        for j in range(i):
            sim = _char_sim(tokens[i], tokens[j])
            if sim > 0.7:  # High similarity threshold
                attention[i, j] += 0.2 * sim

        # Positional decay for recent tokens
        for j in range(max(0, i-5), i):
            distance = i - j
            if distance > 0:
                attention[i, j] += 0.05 / distance

        # Special handling for adjacent tokens
        if i > 0:
            attention[i, i-1] += 0.1

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L17H20", attention



def prog_L17H21(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence structure and discourse tracking head with strong beginning-of-text anchoring."""
    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L17H21", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Get spacy alignment for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    # Identify sentence boundaries and first tokens
    sentence_ends = []
    sentence_starts = [0]  # Always include position 0

    for i, token in enumerate(tokens):
        if token.strip() in ['.', '!', '?']:
            sentence_ends.append(i)
            if i + 1 < n:
                sentence_starts.append(i + 1)
        elif token.strip() == '\n':
            sentence_ends.append(i)
            sentence_starts.append(i)

    for i in range(n):
        token = tokens[i].strip()

        # Get spacy features if available
        spacy_indices = token_to_spacy[i] if i < len(token_to_spacy) else []
        spacy_token = None
        if spacy_indices:
            spacy_token = doc[spacy_indices[0]]

        # Base attention distribution
        for j in range(i + 1):  # Causal mask
            # Distance decay
            distance = i - j
            base_weight = np.exp(-0.1 * distance)

            target_token = tokens[j].strip()

            # SPECIAL CASE: Very strong attention to position 0 (beginning-of-text anchor)
            if j == 0 and i > 0:
                # Strong attention to the first token from all later positions
                attention[i, j] = base_weight * 12.0

            # Very high attention to sentence boundaries (periods, newlines)
            elif target_token in ['.', '!', '?', '\n']:
                attention[i, j] = base_weight * 8.0

            # High attention to sentence starts (first tokens)
            elif j in sentence_starts:
                attention[i, j] = base_weight * 5.0

            # Moderate attention to important content words
            elif spacy_token and j < len(token_to_spacy):
                target_spacy_indices = token_to_spacy[j]
                if target_spacy_indices:
                    target_spacy = doc[target_spacy_indices[0]]

                    # Verbs, nouns, and subjects get higher attention
                    if target_spacy.pos_ in ['VERB', 'NOUN', 'PROPN']:
                        attention[i, j] = base_weight * 2.5
                    elif target_spacy.dep_ in ['nsubj', 'ROOT']:
                        attention[i, j] = base_weight * 3.0
                    else:
                        attention[i, j] = base_weight
                else:
                    attention[i, j] = base_weight
            else:
                attention[i, j] = base_weight

            # Boost for semantic similarity
            if j != i:
                sim = _char_sim(tokens[i], tokens[j])
                if sim > 0.7:
                    attention[i, j] *= 1.5

        # Self-attention baseline
        attention[i, i] = max(attention[i, i], 0.05)

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L17H21", attention



def prog_L17H22(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Structural landmark attention: focuses on sentence boundaries, newlines, and document start."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L17H22", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Get spacy alignment for linguistic features
    spacy_alignment = _align_to_spacy(sentence, tokens)
    doc = spacy_parse(sentence)

    for i in range(n):
        # Base uniform attention to prevent zero rows
        for j in range(i + 1):
            attention[i, j] = 0.01

        # Strong attention to first token (document start)
        if n > 0:
            attention[i, 0] += 0.3

        # Strong attention to newlines and periods
        for j in range(i + 1):
            token = tokens[j].strip()
            if token in ['\n', '.', '!"', '!', '."']:
                attention[i, j] += 0.4
            elif token in [',', ':', ';']:
                attention[i, j] += 0.15

        # Self-attention boost
        attention[i, i] += 0.1

        # Special boost for tokens that are sentence/paragraph starters
        for j in range(i + 1):
            if j < len(spacy_alignment) and spacy_alignment[j]:
                spacy_idx = spacy_alignment[j][0]
                if spacy_idx < len(doc):
                    spacy_token = doc[spacy_idx]
                    # Boost attention to sentence starts
                    if spacy_token.sent.start == spacy_token:
                        attention[i, j] += 0.2

        # Decay with distance for non-structural tokens
        for j in range(i + 1):
            token = tokens[j].strip()
            if token not in ['\n', '.', '!"', '!', '."', ',', ':', ';'] and j != 0 and j != i:
                distance = i - j
                if distance > 0:
                    attention[i, j] *= (0.8 ** distance)

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L17H22", attention



def prog_L17H23(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Attention head that focuses on structural markers like newlines and periods."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    # Initialize attention matrix
    attention = np.zeros((n, n))

    # Find structural tokens (newlines and periods)
    structural_indices = []
    for i, token in enumerate(tokens):
        if token.strip() == '\n' or token.strip() == '.':
            structural_indices.append(i)

    for i in range(n):
        current_token = tokens[i].strip()

        # Self-attention baseline
        attention[i, i] = 0.1

        # High attention to newlines and periods
        for struct_idx in structural_indices:
            if struct_idx <= i:  # Causal constraint
                # Very high attention to newlines
                if tokens[struct_idx].strip() == '\n':
                    attention[i, struct_idx] = 0.4
                # Moderate attention to periods
                elif tokens[struct_idx].strip() == '.':
                    attention[i, struct_idx] = 0.2

        # Special case: periods attend very strongly to themselves
        if current_token == '.':
            attention[i, i] = 0.5

        # Add some recency bias for non-structural tokens
        for j in range(max(0, i-5), i):
            if j not in structural_indices:
                attention[i, j] += 0.05 * (1.0 - (i-j)/10.0)

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L17H23", attention



def prog_L17H24(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Previous-token and syntactic dependency attention with punctuation anchoring."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L17H24", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)
    spacy_to_token = align_spacy_to_tokens(sentence)

    # Get spacy token for each position
    def get_spacy_token(i):
        if i < len(token_to_spacy) and token_to_spacy[i]:
            return doc[token_to_spacy[i][0]]
        return None

    for i in range(n):
        token_i = tokens[i].strip()
        spacy_i = get_spacy_token(i)

        for j in range(i + 1):  # Causal mask
            token_j = tokens[j].strip()
            spacy_j = get_spacy_token(j)

            weight = 0.0

            # Self-attention baseline
            if i == j:
                weight += 0.15

            # Strong previous-token attention
            if i == j + 1:
                weight += 0.4
                # Extra boost for certain patterns
                if spacy_i and spacy_j:
                    if spacy_i.pos_ in ["VERB", "NOUN"] and spacy_j.pos_ in ["DET", "PREP", "ADP"]:
                        weight += 0.2
                    elif spacy_i.pos_ == "NOUN" and spacy_j.pos_ == "ADJ":
                        weight += 0.15

            # Punctuation anchoring - attend to nearby punctuation
            if token_j in [".", ",", "\n", "!", "?", ";", ":"]:
                distance = i - j
                if distance <= 5:
                    weight += 0.3 / (1 + distance * 0.5)
                elif distance <= 15:
                    weight += 0.15 / (1 + distance * 0.3)

            # First token attention (common pattern)
            if j == 0 and i > 5:
                weight += 0.08

            # Syntactic dependencies
            if spacy_i and spacy_j:
                # Head-dependent relationships
                if spacy_j.head == spacy_i or spacy_i.head == spacy_j:
                    weight += 0.25

                # Specific syntactic patterns
                if spacy_j.dep_ in ["det", "amod", "nmod"] and spacy_j.head == spacy_i:
                    weight += 0.2
                if spacy_i.dep_ in ["pobj", "dobj"] and spacy_i.head == spacy_j:
                    weight += 0.15

                # Coordination
                if spacy_i.dep_ == "conj" and spacy_i.head == spacy_j:
                    weight += 0.2

            # Semantic similarity boost
            if i != j:
                sim = _char_sim(tokens[i], tokens[j])
                if sim > 0.7:
                    weight += 0.15 * sim
                elif sim > 0.5:
                    weight += 0.08 * sim

            # Distance decay for general attention
            distance = i - j
            if distance > 1:
                decay = 1.0 / (1 + distance * 0.2)
                weight *= decay

            # Special handling for quotes and dialogue
            if token_j in ['"', "'", '"', '"']:
                if distance <= 10:
                    weight += 0.1

            # Boost for attending to sentence beginnings
            if j > 0 and tokens[j-1].strip() in [".", "\n"] and distance <= 8:
                weight += 0.1

            attention[i, j] = weight

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L17H24", attention



def prog_L17H25(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Attends to sentence boundaries, first tokens, and especially the sentence-initial token with positional decay."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L17H25", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Find boundary tokens (newlines and periods)
    boundary_indices = []
    first_token_indices = []

    for i, token in enumerate(tokens):
        if token.strip() in ['\n', '.']:
            boundary_indices.append(i)
        # First token after start or after boundary
        if i == 0:
            first_token_indices.append(i)
        elif i > 0 and tokens[i-1].strip() in ['\n', '.']:
            first_token_indices.append(i)

    for i in range(n):
        # Strong attention to boundary tokens (especially newlines)
        for j in boundary_indices:
            if j <= i:
                if tokens[j].strip() == '\n':
                    attention[i, j] = 0.4
                elif tokens[j].strip() == '.':
                    attention[i, j] = 0.2

        # Moderate attention to first tokens
        for j in first_token_indices:
            if j <= i and j not in boundary_indices:
                distance = i - j
                attention[i, j] = 0.15 * np.exp(-distance * 0.1)

        # Special case: very strong attention to the absolute first token (index 0)
        # from all subsequent tokens, with distance-based decay
        if i > 0 and 0 not in boundary_indices:
            distance = i
            attention[i, 0] = 0.6 * np.exp(-distance * 0.05)

        # Self-attention
        attention[i, i] = 0.1

        # Weak attention to previous token
        if i > 0:
            attention[i, i-1] = 0.05

        # Very weak distributed attention to other tokens
        for j in range(i+1):
            if attention[i, j] == 0:
                attention[i, j] = 0.01

    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L17H25", attention



def prog_L17H26(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary and discourse structure attention head."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L17H26", np.zeros((n_empty, n_empty))

    # Initialize attention matrix
    attention = np.zeros((n, n))

    # Get spacy alignment for linguistic features
    spacy_alignment = _align_to_spacy(sentence, tokens)
    doc = spacy_parse(sentence)

    for i in range(n):
        token = tokens[i]

        # Very strong attention to sentence boundary markers (periods, newlines)
        for j in range(i + 1):
            target_token = tokens[j]

            # High attention to periods and newlines
            if target_token.strip() in ['.', '!', '?']:
                attention[i, j] += 2.0
            elif target_token.strip() == '\n':
                attention[i, j] += 1.5

            # Strong attention to first token
            if j == 0:
                attention[i, j] += 1.0

            # Distance decay for general attention
            distance = i - j
            if distance == 0:  # Self-attention
                attention[i, j] += 0.3
            elif distance <= 3:  # Local context
                attention[i, j] += 0.5 / (distance + 1)
            else:  # Distant context with decay
                attention[i, j] += 0.2 / (distance + 1)

            # Boost for syntactically related tokens
            if spacy_alignment[i] and spacy_alignment[j]:
                spacy_i_indices = spacy_alignment[i]
                spacy_j_indices = spacy_alignment[j]

                for si in spacy_i_indices:
                    for sj in spacy_j_indices:
                        if si < len(doc) and sj < len(doc):
                            spacy_i_token = doc[si]
                            spacy_j_token = doc[sj]

                            # Boost for dependency relationships
                            if (spacy_i_token.head == spacy_j_token or 
                                spacy_j_token.head == spacy_i_token):
                                attention[i, j] += 0.3

                            # Boost for similar embeddings
                            sim = _char_sim(tokens[i], tokens[j])
                            if sim > 0.7:
                                attention[i, j] += 0.4 * sim

            # Special boost for punctuation attending to content words
            if token.strip() in ['.', '!', '?', ',', ';']:
                if spacy_alignment[j]:
                    for sj in spacy_alignment[j]:
                        if sj < len(doc):
                            spacy_j_token = doc[sj]
                            if spacy_j_token.pos_ in ['NOUN', 'VERB', 'ADJ']:
                                attention[i, j] += 0.5

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L17H26", attention



def prog_L17H27(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary and first-token attention with local syntactic patterns."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L17H27", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    # Identify sentence boundaries (newlines and periods)
    sentence_boundaries = set()
    for i, token in enumerate(tokens):
        if token.strip() in ['.', '\n']:
            sentence_boundaries.add(i)

    # Identify first token (usually index 0)
    first_token = 0

    for i in range(n):
        for j in range(i + 1):  # Causal mask
            weight = 0.0

            # Self-attention baseline
            if i == j:
                weight += 0.15

                # Extra self-attention for first token and punctuation
                if i == first_token or tokens[i].strip() in ['.', '\n', ',']:
                    weight += 0.3

            # Strong attention to sentence boundaries from all tokens
            if j in sentence_boundaries:
                weight += 0.25

                # Extra strong for certain positions
                if i > j and (i - j) < 20:  # Recent boundary
                    weight += 0.15

            # Strong attention to first token from many positions
            if j == first_token and i != j:
                weight += 0.2

                # Even stronger for early tokens
                if i < 10:
                    weight += 0.3

            # Local syntactic attention patterns
            if i != j and abs(i - j) <= 3:
                # Use spacy alignment for linguistic features
                i_spacy_indices = token_to_spacy[i] if i < len(token_to_spacy) else []
                j_spacy_indices = token_to_spacy[j] if j < len(token_to_spacy) else []

                if i_spacy_indices and j_spacy_indices:
                    i_spacy = i_spacy_indices[0]
                    j_spacy = j_spacy_indices[0]

                    if i_spacy < len(doc) and j_spacy < len(doc):
                        i_tok = doc[i_spacy]
                        j_tok = doc[j_spacy]

                        # Pronouns attending to recent nouns/verbs
                        if i_tok.pos_ == "PRON" and j_tok.pos_ in ["NOUN", "VERB", "PROPN"]:
                            weight += 0.15

                        # Function words attending to content words
                        if i_tok.pos_ in ["DET", "ADP"] and j_tok.pos_ in ["NOUN", "VERB"]:
                            weight += 0.1

                        # Dependency relationships
                        if i_tok.head.i == j_spacy or j_tok.head.i == i_spacy:
                            weight += 0.12

            # Embedding similarity for nearby tokens
            if i != j and abs(i - j) <= 5:
                sim = _char_sim(tokens[i], tokens[j])
                if sim > 0.5:
                    weight += 0.1 * sim

            # Distance decay for general attention
            if i != j:
                distance = i - j
                decay = 1.0 / (1.0 + 0.1 * distance)
                weight *= (0.7 + 0.3 * decay)

            attention[i, j] = weight

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L17H27", attention



def prog_L17H28(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary and structural attention head focusing on periods, newlines, and sentence-initial tokens."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        for j in range(i + 1):  # Causal mask
            weight = 0.01  # Base attention

            # Very high attention to periods and sentence boundaries
            if tokens[j].strip() in ['.', '!', '?']:
                weight += 0.5

            # High attention to newlines (sentence separators)
            if tokens[j].strip() == '' and '\n' in tokens[j]:
                weight += 0.3

            # Strong attention to first token of sentences
            # Check if j is at start or after sentence boundary
            if j == 0:
                weight += 0.2
            elif j > 0 and (tokens[j-1].strip() in ['.', '!', '?'] or '\n' in tokens[j-1]):
                weight += 0.2

            # Self-attention boost
            if i == j:
                weight += 0.1

            # Attention to tokens immediately before periods
            if j < n - 1 and tokens[j+1].strip() in ['.', '!', '?']:
                weight += 0.1

            # Boost for semantic similarity (moderate)
            if i != j:
                sim = _char_sim(tokens[i], tokens[j])
                if sim > 0.7:
                    weight += 0.15 * sim

            # Distance decay for non-structural tokens
            if not (tokens[j].strip() in ['.', '!', '?', ''] or 
                   (j == 0) or 
                   (j > 0 and (tokens[j-1].strip() in ['.', '!', '?'] or '\n' in tokens[j-1]))):
                distance = i - j
                if distance > 0:
                    weight *= (0.8 ** distance)

            attention[i, j] = weight

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L17H28", attention



def prog_L17H29(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary and structure detection head with very strong attention to sequence start token."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    # Parse with spacy for sentence boundaries
    doc = spacy_parse(sentence)
    alignment = _align_to_spacy(sentence, tokens)

    # Identify sentence boundary tokens (periods, newlines)
    boundary_tokens = set()
    first_tokens = set()

    for i, token in enumerate(tokens):
        if token.strip() in ['.', '\n']:
            boundary_tokens.add(i)

    # Find first token of each sentence
    sent_starts = []
    for sent in doc.sents:
        for j, spacy_indices in enumerate(alignment):
            if any(idx >= sent.start and idx < sent.end for idx in spacy_indices):
                first_tokens.add(j)
                sent_starts.append(j)
                break

    for i in range(n):
        token = tokens[i]

        # Very strong attention to the first token of the entire sequence
        if i > 0:
            attention[i, 0] = 0.9

        # High attention to sentence boundaries
        for boundary_idx in boundary_tokens:
            if boundary_idx <= i:
                # Stronger attention to periods than newlines
                if tokens[boundary_idx].strip() == '.':
                    attention[i, boundary_idx] = 0.4
                else:  # newline
                    attention[i, boundary_idx] = 0.3

        # Strong attention to first token of current sentence
        current_sent_start = None
        for start_idx in sorted(first_tokens):
            if start_idx <= i:
                current_sent_start = start_idx

        if current_sent_start is not None:
            attention[i, current_sent_start] = 0.5

        # Self-attention
        attention[i, i] = 0.2

        # Some attention to nearby tokens
        for j in range(max(0, i-3), i):
            if j not in boundary_tokens and j not in first_tokens:
                attention[i, j] = 0.1

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L17H29", attention



def prog_L17H3(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Structural anchor attention: focuses on sentence boundaries, first tokens, and syntactic heads with stronger early-token preference."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L17H3", np.zeros((n_empty, n_empty))

    attention_matrix = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        # Strong attention to sentence boundaries (newlines and periods)
        for j in range(i + 1):
            token = tokens[j].strip()
            if token == '\n':
                attention_matrix[i, j] += 0.35
            elif token == '.' and j > 0:
                attention_matrix[i, j] += 0.25

        # High attention to first token - boost this significantly for later tokens
        if i > 0:
            # Much stronger attention to first token, especially from later positions
            first_token_weight = 0.20 + 0.30 * min(1.0, i / 10.0)
            attention_matrix[i, 0] += first_token_weight

        # Reduced self-attention to fix over-prediction
        attention_matrix[i, i] += 0.10

        # Attention to syntactic heads and important positions
        if token_to_spacy[i]:
            spacy_idx = token_to_spacy[i][0]
            spacy_token = doc[spacy_idx]

            # If current token is a content word, attend to syntactic head
            if spacy_token.pos_ in ['NOUN', 'VERB', 'ADJ', 'ADV']:
                head = spacy_token.head
                # Find corresponding LM token for the head
                for j in range(i + 1):
                    if token_to_spacy[j]:
                        j_spacy_idx = token_to_spacy[j][0]
                        if j_spacy_idx < len(doc) and doc[j_spacy_idx] == head:
                            attention_matrix[i, j] += 0.10
                            break

        # Additional attention to tokens that are semantically similar
        for j in range(i + 1):
            if i != j:
                similarity = _char_sim(tokens[i], tokens[j])
                if similarity > 0.7:
                    attention_matrix[i, j] += 0.08 * similarity

        # Boost attention to nearby previous tokens (recency bias)
        for j in range(max(0, i - 3), i):
            attention_matrix[i, j] += 0.05 * (1.0 - (i - j) / 4.0)

    # Apply causal mask and normalize
    attention_matrix = apply_causal_mask(attention_matrix)
    attention_matrix = make_row_stochastic(attention_matrix)

    return "prog_L17H3", attention_matrix



def prog_L17H30(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary and syntactic dependency attention with positional biases."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L17H30", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)
    spacy_to_token = align_spacy_to_tokens(sentence)

    for i in range(n):
        # Strong self-attention baseline
        attention[i, i] = 0.3

        # Very high attention to first token (often newline/sentence start)
        if i > 0:
            attention[i, 0] = 1.0

        # High attention to sentence boundaries (periods, newlines)
        for j in range(i + 1):
            token_j = tokens[j].strip()
            if token_j in ['.', '!', '?', '\n']:
                attention[i, j] += 0.8

        # Syntactic dependencies - attend to heads and modifiers
        if token_to_spacy[i]:
            spacy_idx = token_to_spacy[i][0]
            if spacy_idx < len(doc):
                spacy_token = doc[spacy_idx]

                # Attend to syntactic head
                if spacy_token.head != spacy_token and spacy_token.head.i < len(doc):
                    head_spacy_idx = spacy_token.head.i
                    if head_spacy_idx < len(spacy_to_token) and spacy_to_token[head_spacy_idx]:
                        for head_token_idx in spacy_to_token[head_spacy_idx]:
                            if head_token_idx <= i:
                                attention[i, head_token_idx] += 0.4

                # Attend to children/modifiers
                for child in spacy_token.children:
                    if child.i < len(spacy_to_token) and spacy_to_token[child.i]:
                        for child_token_idx in spacy_to_token[child.i]:
                            if child_token_idx <= i:
                                attention[i, child_token_idx] += 0.3

        # Previous token attention with decay
        for j in range(max(0, i - 5), i):
            distance = i - j
            attention[i, j] += 0.2 / distance

        # Semantic similarity matching
        for j in range(i):
            sim = _char_sim(tokens[i], tokens[j])
            if sim > 0.7:  # High similarity threshold
                attention[i, j] += 0.5 * sim

        # Special pattern: attend to tokens that start phrases
        for j in range(i):
            if token_to_spacy[j]:
                spacy_j_idx = token_to_spacy[j][0]
                if spacy_j_idx < len(doc):
                    spacy_j_token = doc[spacy_j_idx]
                    # Attend more to tokens that start noun phrases or verb phrases
                    if spacy_j_token.pos_ in ['NOUN', 'VERB'] and spacy_j_token.dep_ in ['nsubj', 'ROOT', 'dobj']:
                        attention[i, j] += 0.3

    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L17H30", attention



def prog_L17H31(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Attention head focusing on structural boundaries (newlines, sentence starts) with strong global context."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L17H31", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Get spacy alignment for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        for j in range(i + 1):  # Causal mask
            weight = 0.0

            # Strong attention to first token
            if j == 0:
                weight += 0.4

            # Self-attention baseline
            if i == j:
                weight += 0.15

            # Newline and sentence boundary attention
            if tokens[j] == '\n':
                weight += 0.3
            elif tokens[j] in ['.', '!', '?']:
                weight += 0.2

            # Previous token attention (especially for function words and continuations)
            if j == i - 1:
                weight += 0.1

                # Extra weight for certain patterns
                if token_to_spacy[i]:
                    spacy_i = doc[token_to_spacy[i][0]]
                    if spacy_i.pos_ in ['DET', 'ADP', 'CONJ', 'SCONJ']:
                        weight += 0.1

            # Syntactic relationships via spacy
            if token_to_spacy[i] and token_to_spacy[j]:
                spacy_i = doc[token_to_spacy[i][0]]
                spacy_j = doc[token_to_spacy[j][0]]

                # Head-dependent relationships
                if spacy_i.head == spacy_j or spacy_j.head == spacy_i:
                    weight += 0.15

                # Noun-adjective relationships
                if (spacy_i.pos_ == 'NOUN' and spacy_j.pos_ == 'ADJ') or \
                   (spacy_j.pos_ == 'NOUN' and spacy_i.pos_ == 'ADJ'):
                    weight += 0.1

            # Semantic similarity boost
            if i != j:
                sim = _char_sim(tokens[i], tokens[j])
                if sim > 0.7:
                    weight += 0.1 * sim

            # Enhanced global context attention - tokens strongly attend to earlier structural boundaries
            if tokens[j] == '\n' and i - j > 1:
                # Much stronger attention to newlines, especially for tokens far from sentence boundaries
                distance = i - j
                if distance > 10:
                    weight += 0.5
                elif distance > 5:
                    weight += 0.3
                else:
                    weight += 0.2

            # Enhanced first token attention for tokens in later parts of text
            if j == 0 and i > 10:
                weight += 0.3

            # Distance decay
            distance = i - j
            if distance > 0:
                weight *= (0.9 ** distance)

            attention[i, j] = weight

    # Normalize and apply causal mask
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L17H31", attention



def prog_L17H4(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Attention head that focuses on sentence boundaries and gives strong attention to the sentence-initial token."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L17H4", np.zeros((n_empty, n_empty)).reshape(0, 0)

    attention = np.zeros((n, n))

    # Find boundary tokens (newlines and periods)
    boundary_indices = []
    for i, token in enumerate(tokens):
        if token.strip() in ['.', '\n']:
            boundary_indices.append(i)

    # Find first token after boundaries (sentence beginnings)
    sentence_start_indices = [0]  # First token is always a sentence start
    for i in boundary_indices:
        if i + 1 < n:
            sentence_start_indices.append(i + 1)

    for i in range(n):
        token = tokens[i].strip()

        # Strong self-attention for boundary tokens
        if token in ['.', '\n']:
            attention[i, i] = 0.4

        # High attention to newlines from most tokens
        for boundary_idx in boundary_indices:
            if boundary_idx <= i and tokens[boundary_idx].strip() == '\n':
                attention[i, boundary_idx] = 0.35

        # Attention to periods from most tokens
        for boundary_idx in boundary_indices:
            if boundary_idx <= i and tokens[boundary_idx].strip() == '.':
                attention[i, boundary_idx] = 0.25

        # Attention to sentence beginnings
        for start_idx in sentence_start_indices:
            if start_idx <= i and start_idx != i:
                attention[i, start_idx] = 0.15

        # NEW: Strong attention to the very first token from most tokens
        # This addresses the missing pattern where tokens attend heavily to position 0
        if i > 0:  # Don't modify self-attention for first token
            # Use a decay pattern - tokens closer to start attend more strongly
            first_token_attention = 0.6 * (1.0 / (1.0 + 0.1 * i))
            attention[i, 0] = max(attention[i, 0], first_token_attention)

        # Some self-attention for all tokens
        attention[i, i] += 0.1

        # Weak attention to nearby previous tokens
        for j in range(max(0, i-3), i):
            attention[i, j] += 0.05

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L17H4", attention



def prog_L17H5(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary and structural attention head with positional biases."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        # Strong self-attention for punctuation
        if tokens[i].strip() in ['.', ',', '!', '?', ';', ':']:
            attention[i, i] = 3.0

        # High attention to sentence boundaries
        for j in range(i + 1):
            # First token gets high attention
            if j == 0:
                attention[i, j] += 2.0

            # Periods and newlines get high attention
            if tokens[j].strip() in ['.', '\n']:
                attention[i, j] += 2.5

            # Self-attention boost
            if i == j:
                attention[i, j] += 1.0

            # Previous token attention
            if j == i - 1:
                attention[i, j] += 0.8

            # Syntactic dependencies using spacy
            if token_to_spacy[i] and token_to_spacy[j]:
                spacy_i_tokens = [doc[idx] for idx in token_to_spacy[i] if idx < len(doc)]
                spacy_j_tokens = [doc[idx] for idx in token_to_spacy[j] if idx < len(doc)]

                for si_tok in spacy_i_tokens:
                    for sj_tok in spacy_j_tokens:
                        # Head-dependent relationships
                        if si_tok.head == sj_tok or sj_tok.head == si_tok:
                            attention[i, j] += 0.5

                        # Conjunctions attend to their children
                        if sj_tok.dep_ == "cc" and si_tok.head == sj_tok:
                            attention[i, j] += 0.3

            # Recency decay
            distance = i - j
            if distance > 0:
                attention[i, j] *= (0.95 ** distance)

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L17H5", attention



def prog_L17H6(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Discourse boundary attention head that focuses on newlines, periods, and sentence structure."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention_matrix = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        token = tokens[i]

        # High attention to newlines and periods
        for j in range(i + 1):
            target_token = tokens[j]

            # Very high attention to newlines
            if target_token.strip() == '\n':
                attention_matrix[i, j] = 0.4

            # High attention to periods  
            elif target_token.strip() == '.':
                attention_matrix[i, j] = 0.25

            # Medium attention to self for first token
            elif i == j and i == 0:
                attention_matrix[i, j] = 1.0

            # Self-attention for some tokens
            elif i == j:
                attention_matrix[i, j] = 0.05

            # Attention to first token
            elif j == 0:
                attention_matrix[i, j] = 0.15

            # Some recency bias for recent tokens
            elif i - j <= 3:
                attention_matrix[i, j] = 0.02

            # Check for syntactic relationships using spacy
            if token_to_spacy[i] and token_to_spacy[j]:
                spacy_i = token_to_spacy[i][0] if token_to_spacy[i] else None
                spacy_j = token_to_spacy[j][0] if token_to_spacy[j] else None

                if spacy_i is not None and spacy_j is not None and spacy_i < len(doc) and spacy_j < len(doc):
                    spacy_token_i = doc[spacy_i]
                    spacy_token_j = doc[spacy_j]

                    # Attention between syntactically related tokens
                    if spacy_token_j == spacy_token_i.head or spacy_token_i.head == spacy_token_j:
                        attention_matrix[i, j] += 0.1

                    # Attention to sentence starts
                    if spacy_token_j.dep_ == 'ROOT':
                        attention_matrix[i, j] += 0.05

    # Apply causal mask and normalize
    attention_matrix = apply_causal_mask(attention_matrix)
    attention_matrix = make_row_stochastic(attention_matrix)

    return "prog_L17H6", attention_matrix



def prog_L17H7(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary and discourse structure attention head."""
    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    # Find structural markers
    first_token_idx = 0
    newline_indices = [i for i, token in enumerate(tokens) if token.strip() == '\n']
    period_indices = [i for i, token in enumerate(tokens) if token.strip() == '.']

    for i in range(n):
        # Strong attention to first token (observed weight ~0.3-0.4)
        if i != first_token_idx:
            attention[i, first_token_idx] = 0.35

        # Strong attention to newlines (observed weight ~0.3-0.4)
        for nl_idx in newline_indices:
            if nl_idx < i:  # causal constraint
                attention[i, nl_idx] = 0.35

        # Moderate attention to periods (observed weight ~0.25-0.3)
        for period_idx in period_indices:
            if period_idx < i:  # causal constraint
                attention[i, period_idx] = 0.27

        # Self-attention for some tokens
        attention[i, i] = 0.05

        # Attention to recent tokens (positional bias)
        for j in range(max(0, i-5), i):
            if j != first_token_idx and j not in newline_indices and j not in period_indices:
                distance = i - j
                attention[i, j] = 0.08 / distance

        # Small baseline attention to all previous tokens
        for j in range(i):
            if attention[i, j] == 0:  # only if not already assigned
                attention[i, j] = 0.01

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L17H7", attention



def prog_L17H8(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Discourse boundary head with strong attention to newlines and structural markers."""
    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention_matrix = np.zeros((n, n))

    # Find structural tokens (newlines, periods, first token)
    structural_indices = set()
    newline_indices = set()
    for i, token in enumerate(tokens):
        if token.strip() == '\n':
            structural_indices.add(i)
            newline_indices.add(i)
        elif token.strip() == '.' or i == 0:
            structural_indices.add(i)

    # Parse with spacy for additional linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        # Base attention to structural tokens
        for j in structural_indices:
            if j <= i:
                if tokens[j] == '\n':
                    attention_matrix[i, j] = 0.4
                elif tokens[j] == '.':
                    attention_matrix[i, j] = 0.3
                elif j == 0:
                    attention_matrix[i, j] = 0.2

        # NEW: Strong attention to newlines from all tokens
        for j in newline_indices:
            if j <= i:
                # Much stronger attention to newlines than original
                attention_matrix[i, j] = 0.6

        # Reduced self-attention for structural tokens (was causing over-prediction)
        if i in structural_indices:
            if i in newline_indices:
                attention_matrix[i, i] = 0.3  # Reduced from 0.5
            else:
                attention_matrix[i, i] = 0.2  # Reduced from 0.5

        # Additional patterns
        for j in range(i + 1):
            # Attend to recent tokens with decay
            if i - j <= 3:
                attention_matrix[i, j] += 0.1 * (1.0 / (i - j + 1))

            # Reduced semantic similarity boost (was causing over-prediction)
            if j < i:
                sim = _char_sim(tokens[i], tokens[j])
                if sim > 0.8:  # Higher threshold
                    attention_matrix[i, j] += 0.2 * sim  # Reduced from 0.3

            # Spacy-based syntactic patterns
            if token_to_spacy[i] and token_to_spacy[j]:
                spacy_i = doc[token_to_spacy[i][0]]
                spacy_j = doc[token_to_spacy[j][0]]

                # Attend to sentence start tokens
                if spacy_j.sent.start == token_to_spacy[j][0]:
                    attention_matrix[i, j] += 0.2

                # Attend to syntactic heads
                if spacy_j == spacy_i.head:
                    attention_matrix[i, j] += 0.15

    # Apply causal mask and normalize
    attention_matrix = apply_causal_mask(attention_matrix)
    attention_matrix = make_row_stochastic(attention_matrix)

    return "prog_L17H8", attention_matrix



def prog_L17H9(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary and punctuation tracking head with local syntactic attention."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L17H9", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        # Self-attention baseline
        attention[i, i] = 0.1

        # Strong attention to punctuation marks, especially sentence enders
        for j in range(i + 1):
            token_j = tokens[j].strip()

            # Very high attention to periods and newlines
            if token_j in ['.', '\n']:
                attention[i, j] += 0.4
            # High attention to commas and other punctuation
            elif token_j in [',', '!', '?', ';', ':']:
                attention[i, j] += 0.2

            # Attention to first token
            if j == 0:
                attention[i, j] += 0.15

        # Recent token bias (attend to immediately preceding tokens)
        if i > 0:
            attention[i, i-1] += 0.2
        if i > 1:
            attention[i, i-2] += 0.1

        # Syntactic dependencies using spacy alignment
        spacy_indices_i = token_to_spacy[i]
        if spacy_indices_i:
            spacy_token_i = doc[spacy_indices_i[0]]

            # Attend to syntactic head
            if spacy_token_i.head != spacy_token_i:
                head_token = spacy_token_i.head
                for j in range(i + 1):
                    spacy_indices_j = token_to_spacy[j]
                    if spacy_indices_j and head_token.i in spacy_indices_j:
                        attention[i, j] += 0.15

            # Attend to subjects and objects for verbs
            if spacy_token_i.pos_ == "VERB":
                for child in spacy_token_i.children:
                    if child.dep_ in ["nsubj", "dobj", "iobj"]:
                        for j in range(i + 1):
                            spacy_indices_j = token_to_spacy[j]
                            if spacy_indices_j and child.i in spacy_indices_j:
                                attention[i, j] += 0.12

        # Semantic similarity boost for highly similar tokens
        for j in range(i):
            sim = _char_sim(tokens[i], tokens[j])
            if sim > 0.8:
                attention[i, j] += 0.1 * sim

    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L17H9", attention



def prog_L18H0(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """First-token and segment delimiter attention head with strong first-token bias."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    # Find first token and delimiter positions
    first_token_idx = 0
    delimiter_indices = []

    for i, token in enumerate(tokens):
        # Check for sentence/segment delimiters
        if token.strip() in ['.', '\n', '!', '?'] or token.strip() == '':
            delimiter_indices.append(i)

    for i in range(n):
        current_token = tokens[i].strip()

        # Much weaker self-attention for punctuation and delimiters
        if current_token in ['.', '\n', '!', '?', ','] or current_token == '':
            attention[i, i] = 0.1  # Reduced from 0.6

        # Much stronger attention to first token for non-punctuation tokens
        if i > 0 and current_token not in ['.', '\n', '!', '?'] and current_token != '':
            attention[i, first_token_idx] = 0.8  # Increased from 0.4

        # Attention to nearest previous delimiter
        prev_delimiter = -1
        for delim_idx in delimiter_indices:
            if delim_idx < i:
                prev_delimiter = delim_idx
            else:
                break

        if prev_delimiter >= 0 and i != prev_delimiter:
            attention[i, prev_delimiter] = 0.1  # Reduced from 0.3

        # Moderate attention to recent tokens (recency bias)
        for j in range(max(0, i-3), i):
            if j != first_token_idx and j != prev_delimiter:
                distance = i - j
                weight = 0.05 / distance if distance > 0 else 0.0  # Reduced from 0.1
                attention[i, j] = weight

        # Small baseline attention to all previous tokens
        for j in range(i):
            if attention[i, j] == 0:
                attention[i, j] = 0.01

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L18H0", attention



def prog_L18H1(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Structural boundary attention head with strong first-token attention pattern."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L18H1", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Get spacy alignment for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        for j in range(i + 1):  # Causal mask
            weight = 0.0

            # Very strong self-attention for first few tokens
            if i == j and i < 3:
                weight = 0.9
            # Strong attention to newlines
            elif tokens[j] == '\n':
                weight = 0.35
            # Strong attention to periods
            elif tokens[j] == '.':
                weight = 0.25
            # NEW: Strong attention to first token from all positions
            elif j == 0 and i >= 5:
                weight = 0.4
            # Moderate attention to first token from early positions
            elif j == 0 and i < 5:
                weight = 0.6
            # Self-attention baseline
            elif i == j:
                weight = 0.1
            # Previous token attention
            elif j == i - 1:
                weight = 0.05
            # Attention to proper nouns and important content words
            else:
                if token_to_spacy[j]:
                    spacy_token = doc[token_to_spacy[j][0]]
                    if spacy_token.pos_ in ['PROPN', 'NOUN'] or spacy_token.ent_type_:
                        weight = 0.03
                    else:
                        weight = 0.01
                else:
                    weight = 0.01

            attention[i, j] = weight

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L18H1", attention



def prog_L18H10(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Structural boundary and local dependency attention head."""
    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention_matrix = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        token = tokens[i]

        # Strong self-attention for structural tokens
        if token in ['.', '!', '?', '\n', ',']:
            attention_matrix[i, i] = 0.8
        else:
            attention_matrix[i, i] = 0.1

        # High attention to newlines from most tokens
        for j in range(i + 1):
            if tokens[j] == '\n':
                attention_matrix[i, j] = 0.4

        # High attention to punctuation marks
        for j in range(i + 1):
            if tokens[j] in ['.', '!', '?']:
                attention_matrix[i, j] = 0.3

        # Attention to first token
        if i > 0:
            attention_matrix[i, 0] = 0.2

        # Local dependencies - attend to previous tokens with decay
        for j in range(max(0, i - 3), i):
            if j < i:
                decay = 1.0 / (i - j + 1)
                attention_matrix[i, j] += 0.1 * decay

        # Special patterns for specific relationships
        if i > 0:
            # Check for modifier relationships using spacy
            if token_to_spacy[i] and token_to_spacy[i-1]:
                spacy_i = token_to_spacy[i][0] if token_to_spacy[i] else None
                spacy_prev = token_to_spacy[i-1][0] if token_to_spacy[i-1] else None

                if spacy_i is not None and spacy_prev is not None:
                    if spacy_i < len(doc) and spacy_prev < len(doc):
                        curr_token_spacy = doc[spacy_i]
                        prev_token_spacy = doc[spacy_prev]

                        # Strong attention for certain dependency relationships
                        if (hasattr(curr_token_spacy, 'head') and 
                            curr_token_spacy.head == prev_token_spacy):
                            attention_matrix[i, i-1] += 0.5

        # Boost attention based on semantic similarity to key structural positions
        for j in range(i + 1):
            if tokens[j] in ['\n', '.', ','] and j != i:
                # Boost content words attending to structural markers
                if token_to_spacy[i]:
                    spacy_idx = token_to_spacy[i][0] if token_to_spacy[i] else None
                    if spacy_idx is not None and spacy_idx < len(doc):
                        spacy_token = doc[spacy_idx]
                        if spacy_token.pos_ in ['NOUN', 'VERB', 'ADJ', 'ADV']:
                            attention_matrix[i, j] += 0.2

    # Apply causal mask and normalize
    attention_matrix = apply_causal_mask(attention_matrix)
    attention_matrix = make_row_stochastic(attention_matrix)

    return "prog_L18H10", attention_matrix



def prog_L18H11(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """First-token attention head with self-attention on boundaries and positional decay."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L18H11", np.zeros((n_empty, n_empty)).reshape(0, 0)

    attention_matrix = np.zeros((n, n))

    for i in range(n):
        # Strong attention to first token
        attention_matrix[i, 0] = 0.8

        # Self-attention, especially for punctuation and newlines
        token = tokens[i].strip()
        if token in ['.', '\n', '!', '?', ','] or i == 0:
            attention_matrix[i, i] = 0.6
        else:
            attention_matrix[i, i] = 0.1

        # Moderate attention to sentence boundary markers
        for j in range(i + 1):
            if tokens[j].strip() in ['.', '\n']:
                attention_matrix[i, j] += 0.3

        # Slight attention to recent tokens with decay
        for j in range(max(0, i - 5), i):
            if j != 0:  # Don't double-count first token
                decay = 0.1 * (1.0 - (i - j) / 10.0)
                attention_matrix[i, j] += decay

        # Small boost for similar tokens
        for j in range(i):
            sim = _char_sim(tokens[i], tokens[j])
            if sim > 0.7:
                attention_matrix[i, j] += 0.05

    # Apply causal mask and normalize
    attention_matrix = apply_causal_mask(attention_matrix)
    attention_matrix = make_row_stochastic(attention_matrix)

    return "prog_L18H11", attention_matrix



def prog_L18H12(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Structural boundary attention head with enhanced local semantic dependencies."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention_matrix = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        token_i = tokens[i]

        # Perfect self-attention for first token
        if i == 0:
            attention_matrix[i, i] = 1.0
            continue

        # Base attention distribution
        for j in range(i + 1):  # Causal mask
            token_j = tokens[j]

            # High attention to newlines
            if token_j == '\n':
                attention_matrix[i, j] = 0.4

            # High attention to sentence-ending punctuation
            elif token_j in ['.', '!', '?']:
                attention_matrix[i, j] = 0.25

            # Moderate attention to other punctuation
            elif token_j in [',', ';', ':']:
                attention_matrix[i, j] = 0.15

            # Self-attention boost
            elif i == j:
                attention_matrix[i, j] = 0.1

            # Attention to first token
            elif j == 0:
                attention_matrix[i, j] = 0.2

            # Semantic similarity component
            else:
                sim = _char_sim(tokens[i], tokens[j])
                if sim > 0.7:
                    attention_matrix[i, j] = 0.15
                elif sim > 0.5:
                    attention_matrix[i, j] = 0.08
                else:
                    attention_matrix[i, j] = 0.02

                # Boost for recent tokens
                if i - j <= 3:
                    attention_matrix[i, j] *= 1.5

        # Enhanced local semantic dependency detection
        if i > 0:
            # Get spacy info for current token
            spacy_indices_i = token_to_spacy[i] if i < len(token_to_spacy) else []

            # Check for strong local dependencies (adjacent tokens with high similarity or functional relationships)
            for j in range(max(0, i-2), i):
                spacy_indices_j = token_to_spacy[j] if j < len(token_to_spacy) else []

                # High semantic similarity between adjacent tokens
                sim = _char_sim(tokens[i], tokens[j])
                if sim > 0.6 and i - j <= 2:
                    attention_matrix[i, j] = max(attention_matrix[i, j], 0.3)

                # Functional word relationships (pronouns, determiners, auxiliary verbs)
                if spacy_indices_i and spacy_indices_j:
                    for si in spacy_indices_i:
                        for sj in spacy_indices_j:
                            if si < len(doc) and sj < len(doc):
                                token_i_spacy = doc[si]
                                token_j_spacy = doc[sj]

                                # Pronoun attending to nearby content
                                if (token_i_spacy.pos_ in ['PRON'] and 
                                    token_j_spacy.pos_ in ['NOUN', 'VERB'] and 
                                    i - j == 1):
                                    attention_matrix[i, j] = max(attention_matrix[i, j], 0.4)

                                # Auxiliary/modal verbs attending to main verbs
                                elif (token_i_spacy.pos_ in ['AUX', 'VERB'] and 
                                      token_j_spacy.pos_ in ['VERB'] and 
                                      i - j <= 2):
                                    attention_matrix[i, j] = max(attention_matrix[i, j], 0.25)

        # Special case: if current token is punctuation, attend more to nearby content
        if token_i in ['.', ',', '!', '?', ';', ':']:
            for j in range(max(0, i-5), i):
                if tokens[j] not in ['.', ',', '!', '?', ';', ':', '\n']:
                    attention_matrix[i, j] *= 2.0

    # Apply causal mask and normalize
    attention_matrix = apply_causal_mask(attention_matrix)
    attention_matrix = make_row_stochastic(attention_matrix)

    return "prog_L18H12", attention_matrix



def prog_L18H13(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Structural boundary attention head with semantic similarity component."""
    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L18H13", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    alignment = _align_to_spacy(sentence, tokens)

    # Identify special tokens
    first_token_idx = 0
    newline_indices = [i for i, token in enumerate(tokens) if token.strip() == '\n']
    period_indices = [i for i, token in enumerate(tokens) if token.strip() == '.']

    for i in range(n):
        for j in range(i + 1):  # Causal mask
            weight = 0.0

            # Strong self-attention for first token
            if i == j == first_token_idx:
                weight += 1.0

            # Strong self-attention for periods and newlines
            elif i == j and (tokens[i].strip() in ['.', '\n']):
                weight += 0.5

            # High attention to newlines from most tokens
            elif j in newline_indices:
                weight += 0.35

            # High attention to periods from many tokens
            elif j in period_indices:
                weight += 0.3

            # Strong attention to first token from early tokens
            elif j == first_token_idx and i <= 5:
                weight += 0.4

            # Moderate attention to first token from later tokens
            elif j == first_token_idx:
                weight += 0.2

            # Semantic similarity component
            if i != j:
                sim = _char_sim(tokens[i], tokens[j])
                if sim > 0.7:
                    weight += 0.15 * sim
                elif sim > 0.5:
                    weight += 0.1 * sim

            # Small self-attention baseline
            if i == j:
                weight += 0.02

            # Positional decay for nearby tokens
            if i != j and i - j <= 3:
                weight += 0.05 * (1.0 / (1 + (i - j)))

            attention[i, j] = weight

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L18H13", attention



def prog_L18H14(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary detection head - attends strongly to sentence-initial tokens."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L18H14", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Get spacy alignment for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        # Base attention values
        for j in range(i + 1):  # Only look at previous tokens (causal)

            # Very high attention to newlines
            if tokens[j].strip() == '':  # newline or whitespace
                if '\n' in tokens[j]:
                    attention[i, j] = 0.6
                else:
                    attention[i, j] = 0.1

            # High attention to periods and sentence-ending punctuation
            elif tokens[j].strip() in ['.', '!', '?']:
                attention[i, j] = 0.4

            # VERY HIGH attention to the absolute first token (sentence-initial)
            elif j == 0:
                attention[i, j] = 0.8

            # Check if token j is at start of sentence (after punctuation/newline)
            elif j > 0 and (tokens[j-1].strip() in ['.', '!', '?'] or '\n' in tokens[j-1]):
                attention[i, j] = 0.25

            # Small baseline attention to other tokens
            else:
                attention[i, j] = 0.05

        # Self-attention gets moderate weight
        attention[i, i] = 0.2

        # Boost attention to recent tokens slightly
        recent_boost = max(0, i - 5)
        for j in range(recent_boost, i):
            attention[i, j] *= 1.2

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L18H14", attention



def prog_L18H15(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """First-token and newline attention head with positional biases."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L18H15", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    for i in range(n):
        # Strong bias toward first few tokens (especially token 0)
        if i >= 0:
            attention[i, 0] = 5.0  # Very strong attention to first token
        if i >= 1:
            attention[i, 1] = 3.0  # Strong attention to second token
        if i >= 2:
            attention[i, 2] = 2.0  # Moderate attention to third token
        if i >= 3:
            attention[i, 3] = 1.5  # Some attention to fourth token

        # Strong attention to newline tokens
        for j in range(i + 1):
            if tokens[j].strip() == '':  # Newline or whitespace
                attention[i, j] += 4.0

        # Moderate attention to period tokens
        for j in range(i + 1):
            if tokens[j] == '.':
                attention[i, j] += 2.0

        # Self-attention for special tokens
        if tokens[i] == '.' or tokens[i].strip() == '':
            attention[i, i] += 1.0

        # Recency bias - higher attention to recent tokens
        for j in range(max(0, i - 5), i + 1):
            distance = i - j
            if distance <= 5:
                attention[i, j] += 0.5 * (1.0 / (distance + 1))

        # Small uniform baseline attention
        for j in range(i + 1):
            attention[i, j] += 0.1

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L18H15", attention



def prog_L18H16(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Boundary marker attention head focusing on newlines, periods, and first token."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    # Find boundary tokens (newlines and periods)
    newline_indices = []
    period_indices = []

    for i, token in enumerate(tokens):
        if token.strip() == '\n':
            newline_indices.append(i)
        elif token.strip() == '.':
            period_indices.append(i)

    for i in range(n):
        # Strong attention to first token (especially from early tokens)
        attention[i, 0] = 0.8 if i < 5 else 0.3

        # Very high attention to newlines
        for newline_idx in newline_indices:
            if newline_idx <= i:
                attention[i, newline_idx] = 0.6

        # High attention to periods
        for period_idx in period_indices:
            if period_idx <= i:
                attention[i, period_idx] = 0.4

        # Some self-attention
        attention[i, i] = 0.2

        # Light attention to recent tokens
        for j in range(max(0, i-3), i):
            if j not in newline_indices and j not in period_indices and j != 0:
                attention[i, j] = 0.1

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L18H16", attention



def prog_L18H17(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary and first-token attention head with strong sentence-start attention."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L18H17", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Find sentence boundary markers
    boundary_indices = []
    for i, token in enumerate(tokens):
        if i == 0:  # First token is always a boundary
            boundary_indices.append(i)
        elif token.strip() in ['.', '\n'] or token.startswith('\n'):
            boundary_indices.append(i)

    for i in range(n):
        # Find the most recent boundary token at or before position i
        recent_boundary = -1
        for boundary_idx in boundary_indices:
            if boundary_idx <= i:
                recent_boundary = boundary_idx
            else:
                break

        if recent_boundary != -1:
            # Strong attention to the most recent boundary token
            attention[i, recent_boundary] = 1.0

        # NEW: Additional strong attention to the very first token (sentence start)
        # This captures the pattern where many tokens attend back to the sentence beginning
        if i > 0:  # Don't double-count self-attention for token 0
            attention[i, 0] += 0.8

        # Additional moderate attention to period tokens
        for j in range(i + 1):
            if tokens[j].strip() == '.':
                attention[i, j] += 0.3

        # Self-attention for punctuation and boundaries
        if tokens[i].strip() in ['.', '\n', ','] or tokens[i].startswith('\n'):
            attention[i, i] += 0.5

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L18H17", attention



def prog_L18H18(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary attention head with strong bias toward newlines and periods."""
    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L18H18", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        # Strong attention to newlines and sentence boundaries
        for j in range(i + 1):
            if tokens[j].strip() == '\n':
                attention[i, j] = 0.4
            elif tokens[j] in ['.', '!', '?', '."', '!"', '?"']:
                attention[i, j] = 0.3
            elif j == 0:  # First token gets moderate attention
                attention[i, j] = 0.2

        # Add syntactic relationships using spacy
        if token_to_spacy[i]:
            spacy_idx = token_to_spacy[i][0]
            if spacy_idx < len(doc):
                spacy_token = doc[spacy_idx]

                # Attend to syntactic head
                if spacy_token.head != spacy_token:
                    head_token = spacy_token.head
                    for j in range(i + 1):
                        if token_to_spacy[j] and head_token.i in [doc[k].i for k in token_to_spacy[j]]:
                            attention[i, j] += 0.1

                # Attend to previous token for certain POS tags
                if i > 0 and spacy_token.pos_ in ['VERB', 'NOUN', 'ADJ']:
                    attention[i, i-1] += 0.08

        # Self attention for all tokens
        attention[i, i] += 0.05

        # Small boost for tokens with high embedding similarity
        for j in range(i):
            sim = _char_sim(tokens[i], tokens[j])
            if sim > 0.7:
                attention[i, j] += 0.05 * sim

    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L18H18", attention



def prog_L18H19(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary and structural marker attention head with global structural attention."""
    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention_matrix = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        # Strong self-attention for first token
        if i == 0:
            attention_matrix[i, i] = 1.0
            continue

        weights = np.zeros(i + 1)  # Can only attend to tokens <= i

        # High attention to newlines and sentence-ending punctuation
        for j in range(i + 1):
            token = tokens[j]
            if token.strip() == '\n':
                weights[j] += 0.3
            elif token.strip() in ['.', '!', '?']:
                weights[j] += 0.2

        # Moderate attention to sentence beginnings (tokens after newlines/periods)
        for j in range(i + 1):
            if j > 0 and (tokens[j-1].strip() == '\n' or tokens[j-1].strip() in ['.', '!', '?']):
                weights[j] += 0.1

        # NEW: Global structural attention to early important tokens
        # Strong attention to very early structural markers (first few tokens)
        for j in range(min(5, i + 1)):
            token = tokens[j]
            # Early newlines get very high attention from throughout the sequence
            if token.strip() == '\n' and j <= 3:
                weights[j] += 0.4
            # Early punctuation and structural markers
            elif token.strip() in ['.', '!', '?', '"'] and j <= 3:
                weights[j] += 0.3
            # Very first few content tokens (often sentence starts)
            elif j <= 2:
                weights[j] += 0.2

        # Local syntactic dependencies using spacy
        if token_to_spacy[i]:
            spacy_idx = token_to_spacy[i][0]
            if spacy_idx < len(doc):
                spacy_token = doc[spacy_idx]

                # Attend to syntactic head
                if spacy_token.head != spacy_token:
                    head_idx = spacy_token.head.i
                    # Find corresponding token indices
                    for j in range(i + 1):
                        if token_to_spacy[j] and head_idx in token_to_spacy[j]:
                            weights[j] += 0.15

                # Attend to direct children
                for child in spacy_token.children:
                    child_idx = child.i
                    for j in range(i + 1):
                        if token_to_spacy[j] and child_idx in token_to_spacy[j]:
                            weights[j] += 0.1

        # Slight recency bias
        for j in range(i + 1):
            distance = i - j
            if distance <= 3:
                weights[j] += 0.05 * (4 - distance) / 4

        # Self-attention baseline
        weights[i] += 0.05

        # Normalize
        if weights.sum() > 0:
            weights = weights / weights.sum()
        else:
            weights[i] = 1.0

        attention_matrix[i, :i+1] = weights

    return "prog_L18H19", make_row_stochastic(apply_causal_mask(attention_matrix))



def prog_L18H2(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Structural boundary attention head - attends to newlines and sentence boundaries."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L18H2", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Find structural markers
    newline_indices = []
    period_indices = []

    for i, token in enumerate(tokens):
        if token.strip() == '\n':
            newline_indices.append(i)
        elif token.strip() == '.':
            period_indices.append(i)

    for i in range(n):
        # Strong self-attention for first token
        if i == 0:
            attention[i, i] = 1.0
            continue

        # Base attention distribution
        for j in range(i + 1):  # Causal mask
            if j in newline_indices:
                # Very high attention to newlines
                attention[i, j] = 0.35
            elif j in period_indices:
                # Moderate attention to periods
                attention[i, j] = 0.25
            elif j == i:
                # Some self-attention for structural tokens
                if tokens[i].strip() in ['.', '\n']:
                    attention[i, j] = 0.4
                else:
                    attention[i, j] = 0.05
            else:
                # Low baseline attention
                attention[i, j] = 0.02

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L18H2", attention



def prog_L18H20(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Structural boundary attention head focusing on first token and discourse markers."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L18H20", np.zeros((n_empty, n_empty))

    attention_matrix = np.zeros((n, n))

    # Find newline and period positions
    newline_positions = [i for i, token in enumerate(tokens) if token == '\n']
    period_positions = [i for i, token in enumerate(tokens) if token == '.']

    for i in range(n):
        current_token = tokens[i]

        # Base attention distribution
        for j in range(i + 1):  # Causal mask
            if j == 0:
                # Much higher attention to first token (main fix)
                attention_matrix[i, j] = 0.8
            elif j in newline_positions:
                # Reduced attention to newlines (secondary fix)
                attention_matrix[i, j] = 0.2
            elif j in period_positions:
                # High attention to periods
                attention_matrix[i, j] = 0.4
            else:
                # Base attention with recency bias
                distance = i - j
                attention_matrix[i, j] = 0.1 * np.exp(-0.2 * distance)

        # Add semantic similarity boost
        for j in range(i + 1):
            if j != i and tokens[j] not in ['\n', '.']:
                similarity = _char_sim(tokens[i], tokens[j])
                if similarity > 0.5:  # Threshold for semantic relatedness
                    attention_matrix[i, j] += 0.2 * similarity

        # Special case: punctuation tokens get extra attention to structural elements
        if current_token in [',', '"', "'", '!', '?', ';', ':']:
            for j in range(i + 1):
                if j in newline_positions:
                    attention_matrix[i, j] *= 1.5
                elif j in period_positions:
                    attention_matrix[i, j] *= 1.3

    # Apply causal mask and normalize
    attention_matrix = apply_causal_mask(attention_matrix)
    attention_matrix = make_row_stochastic(attention_matrix)

    return "prog_L18H20", attention_matrix



def prog_L18H21(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Structural anchor attention: focuses on first tokens, newlines, and sentence boundaries."""
    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L18H21", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    for i in range(n):
        for j in range(i + 1):  # Causal mask
            weight = 0.0

            # Very strong attention to first token
            if j == 0:
                weight += 0.8

            # Strong attention to newlines
            elif tokens[j] == '\n':
                weight += 0.4

            # Strong attention to periods
            elif tokens[j] == '.':
                weight += 0.3

            # Self-attention for punctuation
            elif i == j and tokens[i] in ['.', '\n', "'", '"', '!', '?', ',']:
                weight += 0.4

            # Moderate self-attention for other tokens
            elif i == j:
                weight += 0.1

            # Small baseline attention
            else:
                weight += 0.02

            attention[i, j] = weight

    attention = make_row_stochastic(attention)
    attention = apply_causal_mask(attention)

    return "prog_L18H21", attention



def prog_L18H22(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Boundary-aware positional attention head with strong first-token bias for punctuation starts."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention_matrix = np.zeros((n, n))

    # Find boundary tokens (newlines and periods)
    boundary_indices = []
    for i, token in enumerate(tokens):
        if token.strip() in ['.', '\n']:
            boundary_indices.append(i)

    # Check if first token is punctuation (comma, period, etc.)
    first_token_is_punct = tokens[0].strip() in [',', '.', '!', '?', ';', ':']

    for i in range(n):
        # First token always attends to itself maximally
        if i == 0:
            attention_matrix[i, 0] = 1.0
            continue

        # Base positional decay - prefer earlier tokens
        for j in range(i + 1):
            distance = i - j
            attention_matrix[i, j] = 0.1 / (1 + distance * 0.5)

        # Strong boost for boundary tokens
        for boundary_idx in boundary_indices:
            if boundary_idx <= i:
                # Very strong attention to boundaries
                attention_matrix[i, boundary_idx] = 0.4

        # Extra boost for first token from all positions
        if i > 0:
            attention_matrix[i, 0] = 0.3

        # SPECIAL CASE: Extremely strong attention to first token when it's punctuation
        if first_token_is_punct and i > 0:
            attention_matrix[i, 0] = 0.8

        # Self-attention gets moderate weight
        attention_matrix[i, i] = 0.05

        # Special handling for tokens immediately after boundaries
        for boundary_idx in boundary_indices:
            if boundary_idx < i <= boundary_idx + 5:  # Within 5 tokens of boundary
                attention_matrix[i, boundary_idx] *= 1.5  # Boost boundary attention

    # Apply causal mask and normalize
    attention_matrix = apply_causal_mask(attention_matrix)
    attention_matrix = make_row_stochastic(attention_matrix)

    return "prog_L18H22", attention_matrix



def prog_L18H23(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Structural boundary attention head with strong content word self-attention."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L18H23", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Get spacy analysis for POS tags
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    # Find newlines and sentence boundaries
    newline_indices = []
    period_indices = []
    for i, token in enumerate(tokens):
        if token.strip() == '\n':
            newline_indices.append(i)
        elif token.strip() in ['.', '!', '?']:
            period_indices.append(i)

    for i in range(n):
        # Determine if this token is a content word (noun, verb, adjective)
        is_content_word = False
        if i < len(token_to_spacy) and token_to_spacy[i]:
            spacy_indices = token_to_spacy[i]
            for spacy_idx in spacy_indices:
                if spacy_idx < len(doc):
                    pos = doc[spacy_idx].pos_
                    if pos in ['NOUN', 'VERB', 'ADJ', 'PROPN']:
                        is_content_word = True
                        break

        # Strong self-attention for content words, base for others
        if is_content_word:
            attention[i, i] = 0.5
        else:
            attention[i, i] = 0.1

        # Strong attention to first token
        attention[i, 0] = 0.3

        # Very strong attention to newlines
        for nl_idx in newline_indices:
            if nl_idx <= i:
                attention[i, nl_idx] = 0.5

        # Moderate attention to periods/sentence boundaries
        for p_idx in period_indices:
            if p_idx <= i:
                attention[i, p_idx] = 0.2

        # Local attention to previous few tokens with decay
        for j in range(max(0, i-3), i):
            distance = i - j
            attention[i, j] += 0.1 / distance

        # Special cases for certain patterns
        token = tokens[i].strip()

        # Tokens right after newlines get extra attention to the newline
        if i > 0 and tokens[i-1].strip() == '\n':
            for nl_idx in newline_indices:
                if nl_idx <= i:
                    attention[i, nl_idx] += 0.2

        # Compound word parts attend strongly to their prefix
        if i > 0 and len(tokens[i]) > 2 and len(tokens[i-1]) > 1:
            # Check if this looks like a word continuation
            prev_token = tokens[i-1].strip()
            curr_token = tokens[i].strip()
            if prev_token.isalpha() and curr_token.isalpha() and not curr_token[0].isupper():
                attention[i, i-1] += 0.4

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L18H23", attention



def prog_L18H24(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Head that attends strongly to early sentence boundaries (newlines/periods) from most tokens."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    if n == 0:
        return "prog_L18H24", attention

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        token = tokens[i].strip()

        # Strong attention to newlines and periods (sentence boundaries)
        for j in range(i + 1):
            target_token = tokens[j].strip()
            if target_token in ['\n', '.']:
                attention[i, j] = 0.3

        # NEW: Much stronger global attention to early sentence boundaries
        # This captures the pattern where tokens throughout the sentence attend back to early \n
        for j in range(min(i + 1, 5)):  # Look at first few positions only
            target_token = tokens[j].strip()
            if target_token in ['\n', '.']:
                # Much stronger attention, especially for tokens further in the sentence
                distance_boost = min(0.4, i * 0.02)  # Increases with distance from boundary
                attention[i, j] = 0.5 + distance_boost

        # Strong self-attention for first token
        if i == 0:
            attention[i, i] = 0.5

        # Local dependencies - attend to previous token
        if i > 0:
            attention[i, i-1] = 0.2

        # Syntactic dependencies using spacy
        if token_to_spacy[i]:
            spacy_idx = token_to_spacy[i][0]
            if spacy_idx < len(doc):
                spacy_token = doc[spacy_idx]

                # If this token is a determiner, preposition, or auxiliary, attend to nearby content words
                if spacy_token.pos_ in ['DET', 'ADP', 'AUX']:
                    for j in range(max(0, i-3), i):
                        if j < i:
                            attention[i, j] += 0.1

                # If this token is a noun or verb, attend to its syntactic head
                if spacy_token.pos_ in ['NOUN', 'VERB'] and spacy_token.head != spacy_token:
                    head_text = spacy_token.head.text
                    for j in range(i):
                        if _char_sim(tokens[i], tokens[j]) > 0.7:
                            attention[i, j] += 0.15

        # Content words get some self-attention
        if token_to_spacy[i]:
            spacy_idx = token_to_spacy[i][0]
            if spacy_idx < len(doc):
                spacy_token = doc[spacy_idx]
                if spacy_token.pos_ in ['NOUN', 'VERB', 'ADJ']:
                    attention[i, i] += 0.1

        # Special case: tokens that are parts of compound words attend to their components
        if i > 0:
            sim = _char_sim(tokens[i], tokens[i-1])
            if sim > 0.6:
                attention[i, i-1] += 0.2

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L18H24", attention



def prog_L18H25(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Structural boundary attention head focusing on newlines, periods, local syntax, and first-token attention."""
    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        for j in range(i + 1):  # Causal mask
            weight = 0.0

            # Strong self-attention for punctuation
            if i == j and tokens[i].strip() in '.,!?;:\n':
                weight += 0.4

            # High attention to newlines from most tokens
            if tokens[j].strip() == '\n':
                weight += 0.3

            # High attention to periods from most tokens  
            if tokens[j].strip() == '.':
                weight += 0.25

            # NEW: Strong attention back to first token from content words
            if j == 0 and i > 2:
                if token_to_spacy[i]:
                    spacy_i = doc[token_to_spacy[i][0]]
                    if spacy_i.pos_ in ['NOUN', 'VERB', 'ADJ', 'PROPN']:
                        weight += 0.4
                    else:
                        weight += 0.15

            # NEW: Enhanced self-attention for important content words
            if i == j and token_to_spacy[i]:
                spacy_i = doc[token_to_spacy[i][0]]
                if spacy_i.pos_ in ['NOUN', 'VERB', 'PROPN'] and len(tokens[i].strip()) > 2:
                    weight += 0.3

            # Local syntactic dependencies - attend to previous token
            if j == i - 1:
                weight += 0.1

                # Boost for certain syntactic patterns
                if token_to_spacy[i] and token_to_spacy[j]:
                    spacy_i = doc[token_to_spacy[i][0]]
                    spacy_j = doc[token_to_spacy[j][0]]

                    # Noun attending to adjective
                    if spacy_i.pos_ == 'NOUN' and spacy_j.pos_ == 'ADJ':
                        weight += 0.15

                    # Verb attending to auxiliary or modal
                    if spacy_i.pos_ == 'VERB' and spacy_j.pos_ in ['AUX', 'MODAL']:
                        weight += 0.1

                    # General syntactic head relationship
                    if spacy_j.head == spacy_i:
                        weight += 0.1

            # NEW: Attention to syntactically related words
            if i != j and token_to_spacy[i] and token_to_spacy[j]:
                spacy_i = doc[token_to_spacy[i][0]]
                spacy_j = doc[token_to_spacy[j][0]]

                # Direct syntactic dependency
                if spacy_j.head == spacy_i or spacy_i.head == spacy_j:
                    weight += 0.2

            # Moderate attention to first token
            if j == 0:
                weight += 0.05

            # Small baseline attention
            weight += 0.01

            attention[i, j] = weight

    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L18H25", attention



def prog_L18H26(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary attention: focuses on periods, line breaks, and structural markers."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L18H26", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        # Strong self-attention for structural tokens
        if tokens[i].strip() in ['.', '\n', '!', '?']:
            attention[i, i] = 1.0
        else:
            # Find structural tokens to attend to
            structural_weights = []

            # Look for periods and line breaks in previous positions
            for j in range(i + 1):
                weight = 0.0

                if tokens[j].strip() in ['.', '\n']:
                    # Strong attention to sentence/paragraph boundaries
                    if tokens[j].strip() == '.':
                        weight = 0.4
                    elif tokens[j].strip() == '\n':
                        weight = 0.3

                    # Boost for recent structural tokens
                    distance = i - j
                    if distance <= 5:
                        weight *= 1.5

                elif tokens[j].strip() in ['!', '?']:
                    weight = 0.2

                # Self-attention
                elif i == j:
                    weight = 0.1

                # Recency bias for recent tokens
                elif i - j <= 3:
                    weight = 0.05

                # Small attention to content words
                else:
                    spacy_indices = token_to_spacy[j]
                    if spacy_indices:
                        spacy_token = doc[spacy_indices[0]]
                        if spacy_token.pos_ in ['NOUN', 'VERB', 'ADJ']:
                            weight = 0.02
                        else:
                            weight = 0.01
                    else:
                        weight = 0.01

                structural_weights.append(weight)

            # Normalize and assign
            total = sum(structural_weights)
            if total > 0:
                for j, weight in enumerate(structural_weights):
                    attention[i, j] = weight / total
            else:
                # Fallback to uniform over available positions
                for j in range(i + 1):
                    attention[i, j] = 1.0 / (i + 1)

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L18H26", attention



def prog_L18H27(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Structural boundary attention with strong focus on sentence-initial content tokens."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    # Find the first content token (non-punctuation, non-whitespace)
    first_content_idx = 0
    for idx, token in enumerate(tokens):
        if token not in ['.', ',', '!', '?', ':', ';', '\n', ' ', '"', "'"] and token.strip():
            first_content_idx = idx
            break

    for i in range(n):
        token_i = tokens[i]

        # Strong self-attention for certain structural tokens
        if token_i in ['\n', '.', '!', '?', ':', ';'] or i == 0:
            attention[i, i] = 0.8
        else:
            attention[i, i] = 0.1

        # High attention to newlines and sentence-ending punctuation
        for j in range(i):
            token_j = tokens[j]

            # Very strong attention to first content token
            if j == first_content_idx and i > first_content_idx:
                distance = i - j
                attention[i, j] = 0.6 / (1 + 0.05 * distance)
            # Very high attention to newlines and periods
            elif token_j in ['\n']:
                attention[i, j] = 0.4
            elif token_j in ['.', '!', '?']:
                attention[i, j] = 0.3
            elif token_j in [',', ';', ':']:
                attention[i, j] = 0.15
            else:
                # Base attention with recency bias
                distance = i - j
                base_weight = 0.05 / (1 + 0.1 * distance)

                # Boost for first few tokens
                if j < 3:
                    base_weight *= 2.0

                # Small boost for embedding similarity
                sim = _char_sim(tokens[i], tokens[j])
                if sim > 0.5:
                    base_weight *= (1 + sim)

                attention[i, j] = base_weight

    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L18H27", attention



def prog_L18H28(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary and first-token attention with self-attention bias."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L18H28", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Find first period and first newline
    first_period = None
    first_newline = None

    for i, token in enumerate(tokens):
        if token.strip() == '.' and first_period is None:
            first_period = i
        if token.strip() == '\n' and first_newline is None:
            first_newline = i

    for i in range(n):
        # Self-attention baseline
        attention[i, i] = 0.15

        # Strong attention to first token
        attention[i, 0] = 0.25

        # Strong attention to first period if it exists
        if first_period is not None and first_period <= i:
            attention[i, first_period] = 0.35

        # Strong attention to first newline if it exists  
        if first_newline is not None and first_newline <= i:
            attention[i, first_newline] = 0.30

        # Moderate attention to other periods and newlines
        for j in range(i + 1):
            token_j = tokens[j].strip()
            if token_j == '.' and j != first_period:
                attention[i, j] = 0.08
            elif token_j == '\n' and j != first_newline:
                attention[i, j] = 0.08

        # Small attention to recent tokens (recency bias)
        for j in range(max(0, i-5), i):
            if attention[i, j] < 0.1:  # Don't override higher values
                attention[i, j] = max(attention[i, j], 0.02 * (1.0 / (i - j + 1)))

    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L18H28", attention



def prog_L18H29(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Attention head focusing on sentence boundaries, newlines, structural discourse markers, and document beginning."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        token = tokens[i]

        # Strong self-attention for first token
        if i == 0:
            attention[i, i] = 1.0
            continue

        # High attention to newlines and periods
        for j in range(i + 1):
            target_token = tokens[j]

            # Very high attention to newlines
            if target_token.strip() == '\n':
                attention[i, j] += 0.35

            # High attention to periods
            elif target_token.strip() == '.':
                attention[i, j] += 0.25

            # Moderate attention to other punctuation
            elif target_token.strip() in [',', '!', '?', ';', ':']:
                attention[i, j] += 0.1

        # Strong attention to the very first token (document beginning pattern)
        if i > 0:
            attention[i, 0] += 0.4

        # Attention to sentence-beginning tokens
        prev_newline_idx = -1
        for j in range(i):
            if tokens[j].strip() == '\n':
                prev_newline_idx = j

        # If we found a previous newline, attend to tokens right after it
        if prev_newline_idx >= 0 and prev_newline_idx + 1 < i:
            next_token_idx = prev_newline_idx + 1
            # Skip empty tokens
            while next_token_idx < i and tokens[next_token_idx].strip() == '':
                next_token_idx += 1
            if next_token_idx < i:
                attention[i, next_token_idx] += 0.15

        # Small attention to semantically similar tokens
        if token_to_spacy[i]:
            current_spacy_tokens = [doc[idx] for idx in token_to_spacy[i] if idx < len(doc)]
            for j in range(i):
                if token_to_spacy[j]:
                    target_spacy_tokens = [doc[idx] for idx in token_to_spacy[j] if idx < len(doc)]

                    # Check for semantic similarity using embeddings
                    sim = _char_sim(tokens[i], tokens[j])
                    if sim > 0.7:
                        attention[i, j] += 0.05 * sim

                    # Small boost for same POS tags
                    for curr_tok in current_spacy_tokens:
                        for targ_tok in target_spacy_tokens:
                            if curr_tok.pos_ == targ_tok.pos_ and curr_tok.pos_ in ['NOUN', 'VERB', 'ADJ']:
                                attention[i, j] += 0.02

        # Base attention to recent tokens (recency bias)
        for j in range(max(0, i - 5), i):
            attention[i, j] += 0.01 * (1.0 - (i - j) / 10.0)

        # Small self-attention
        attention[i, i] += 0.05

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L18H29", attention



def prog_L18H3(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """First-token and sentence boundary attention with positional decay."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L18H3", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        # Very strong attention to first token
        if i > 0:
            attention[i, 0] = 0.8

        # Strong attention to sentence boundaries (periods, newlines)
        for j in range(i + 1):
            token = tokens[j].strip()
            if token in ['.', '\n']:
                if i != j:  # Don't boost self-attention here
                    attention[i, j] = 0.3

        # Moderate attention to recent tokens with decay
        for j in range(max(0, i - 5), i):
            if attention[i, j] < 0.3:  # Don't override boundary attention
                distance = i - j
                attention[i, j] = max(attention[i, j], 0.05 / (distance + 1))

        # Self-attention baseline
        attention[i, i] = 0.02

        # Boost attention based on linguistic similarity for content words
        spacy_indices = token_to_spacy[i]
        if spacy_indices:
            current_spacy = doc[spacy_indices[0]]
            if current_spacy.pos_ in ['NOUN', 'VERB', 'ADJ', 'ADV']:
                for j in range(i):
                    j_spacy_indices = token_to_spacy[j]
                    if j_spacy_indices:
                        j_spacy = doc[j_spacy_indices[0]]
                        if j_spacy.pos_ in ['NOUN', 'VERB', 'ADJ', 'ADV']:
                            sim = _char_sim(tokens[i], tokens[j])
                            if sim > 0.5:
                                attention[i, j] = min(attention[i, j] + 0.1 * sim, 0.4)

    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L18H3", attention



def prog_L18H30(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Attention head combining first-token bias, newline/punctuation attention, and local context."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L18H30", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Get spacy alignment for linguistic features
    spacy_alignment = _align_to_spacy(sentence, tokens)
    doc = spacy_parse(sentence)

    for i in range(n):
        # Strong self-attention for first token
        if i == 0:
            attention[i, i] = 1.0
            continue

        # Base attention distribution
        for j in range(i + 1):  # Causal mask

            # First token gets high attention from all positions
            if j == 0:
                attention[i, j] = 0.3

            # High attention to newlines
            elif tokens[j] == '\n':
                attention[i, j] = 0.25

            # Moderate attention to sentence-ending punctuation
            elif tokens[j] in ['.', '!', '?']:
                attention[i, j] = 0.15

            # Self-attention
            elif i == j:
                attention[i, j] = 0.1

            # Local context - previous few tokens
            elif i - j <= 3:
                attention[i, j] = 0.08 * (1.0 / (i - j + 1))

            # Semantic similarity boost
            else:
                sim = _char_sim(tokens[i], tokens[j])
                if sim > 0.7:
                    attention[i, j] = 0.1 * sim
                else:
                    attention[i, j] = 0.02

        # Special case: boost attention between related words
        if spacy_alignment[i]:
            spacy_i = spacy_alignment[i][0]
            if spacy_i < len(doc):
                token_i = doc[spacy_i]

                # Look for syntactic dependencies
                for j in range(i):
                    if spacy_alignment[j]:
                        spacy_j = spacy_alignment[j][0]
                        if spacy_j < len(doc):
                            token_j = doc[spacy_j]

                            # Head-dependent relationships
                            if token_j == token_i.head or token_i == token_j.head:
                                attention[i, j] *= 1.5

                            # Similar POS tags
                            elif token_i.pos_ == token_j.pos_ and token_i.pos_ in ['NOUN', 'VERB', 'ADJ']:
                                attention[i, j] *= 1.2

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L18H30", attention



def prog_L18H31(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Boundary-focused attention head with strong beginning-of-sequence bias."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    # Identify boundary tokens (periods, newlines, and other structural punctuation)
    boundary_indices = []
    for i, token in enumerate(tokens):
        if token.strip() in [".", "\n", "!", "?", ";", ":"]:
            boundary_indices.append(i)

    for i in range(n):
        # Strong attention to boundary tokens
        for boundary_idx in boundary_indices:
            if boundary_idx <= i:  # Causal constraint
                # Higher weight for periods and newlines
                if tokens[boundary_idx].strip() in [".", "\n"]:
                    attention[i, boundary_idx] = 0.4
                else:
                    attention[i, boundary_idx] = 0.2

        # Self-attention (moderate weight)
        attention[i, i] = 0.1

        # Enhanced attention to first token with distance-based scaling
        if i > 0:
            # Strong bias toward first token, especially for tokens 2-5 positions away
            if i <= 5:
                attention[i, 0] = 0.6 + (i - 1) * 0.1  # 0.6, 0.7, 0.8, 0.9, 1.0
            else:
                attention[i, 0] = 0.3  # Reduced but still significant for distant tokens

        # Moderate attention to recent tokens (recency bias)
        for j in range(max(0, i-3), i):
            if j not in boundary_indices and j != 0:  # Skip first token (handled above)
                attention[i, j] = 0.05

        # Small baseline attention to all previous tokens
        for j in range(1, i):  # Skip first token (handled above)
            if attention[i, j] == 0:  # Only if not already set
                attention[i, j] = 0.01

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L18H31", attention



def prog_L18H4(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Structural boundary attention head focusing on newlines and periods."""
    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention_matrix = np.zeros((n, n))

    # Find structural boundary tokens (newlines and periods)
    boundary_tokens = []
    for i, token in enumerate(tokens):
        if token.strip() in ['\n', '.']:
            boundary_tokens.append(i)

    for i in range(n):
        current_token = tokens[i].strip()

        # Self-attention for boundary tokens
        if current_token in ['\n', '.']:
            attention_matrix[i, i] = 1.0
        else:
            # Strong attention to newlines, especially early ones
            newline_weight = 0.0
            for j in boundary_tokens:
                if j <= i and tokens[j].strip() == '\n':
                    # Prefer earlier newlines with distance decay
                    distance_factor = 1.0 / (1.0 + 0.1 * (i - j))
                    newline_weight += 0.4 * distance_factor

            # Moderate attention to periods
            period_weight = 0.0
            for j in boundary_tokens:
                if j <= i and tokens[j].strip() == '.':
                    distance_factor = 1.0 / (1.0 + 0.2 * (i - j))
                    period_weight += 0.2 * distance_factor

            # Distribute attention
            if boundary_tokens:
                total_boundary_weight = min(0.8, newline_weight + period_weight)
                remaining_weight = 1.0 - total_boundary_weight

                # Assign boundary attention
                for j in boundary_tokens:
                    if j <= i:
                        if tokens[j].strip() == '\n':
                            distance_factor = 1.0 / (1.0 + 0.1 * (i - j))
                            attention_matrix[i, j] += total_boundary_weight * 0.7 * distance_factor
                        elif tokens[j].strip() == '.':
                            distance_factor = 1.0 / (1.0 + 0.2 * (i - j))
                            attention_matrix[i, j] += total_boundary_weight * 0.3 * distance_factor

                # Distribute remaining weight uniformly to other positions
                other_positions = [j for j in range(i + 1) if j not in boundary_tokens]
                if other_positions:
                    uniform_weight = remaining_weight / len(other_positions)
                    for j in other_positions:
                        attention_matrix[i, j] = uniform_weight
            else:
                # No boundary tokens, uniform attention
                for j in range(i + 1):
                    attention_matrix[i, j] = 1.0 / (i + 1)

    attention_matrix = apply_causal_mask(attention_matrix)
    attention_matrix = make_row_stochastic(attention_matrix)

    return "prog_L18H4", attention_matrix



def prog_L18H5(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Structural boundary attention: tokens attend to sentence/paragraph boundaries and text start."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L18H5", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Find structural boundary tokens
    boundary_indices = set()

    # First token is always a strong boundary
    boundary_indices.add(0)

    # Find newlines, periods, and other sentence boundaries
    for i, token in enumerate(tokens):
        if token.strip() in ['\n', '.', '!', '?'] or token.startswith('\n'):
            boundary_indices.add(i)

    for i in range(n):
        # Base attention to self (small)
        attention[i, i] = 0.1

        # Strong attention to first token
        attention[i, 0] = 0.6

        # Strong attention to boundary tokens (especially newlines)
        for boundary_idx in boundary_indices:
            if boundary_idx <= i:  # Causal constraint
                if tokens[boundary_idx].strip() == '\n' or tokens[boundary_idx].startswith('\n'):
                    attention[i, boundary_idx] = 0.8
                elif tokens[boundary_idx].strip() in ['.', '!', '?']:
                    attention[i, boundary_idx] = 0.4

        # Find the most recent newline before current position
        most_recent_newline = -1
        for j in range(i-1, -1, -1):
            if tokens[j].strip() == '\n' or tokens[j].startswith('\n'):
                most_recent_newline = j
                break

        if most_recent_newline >= 0:
            # Boost attention to the most recent paragraph boundary
            attention[i, most_recent_newline] = 1.0

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L18H5", attention



def prog_L18H6(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary and first-token attention head with positional bias."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L18H6", np.zeros((n_empty, n_empty))

    # Initialize attention matrix
    attention = np.zeros((n, n))

    for i in range(n):
        # Strong attention to first token (position 0)
        attention[i, 0] = 0.8

        # Self-attention
        attention[i, i] = 0.3

        # Attention to sentence boundaries (newlines and periods)
        for j in range(i + 1):  # Causal mask
            token_j = tokens[j].strip()
            if token_j == '\n':
                attention[i, j] += 0.4
            elif token_j == '.':
                attention[i, j] += 0.3

        # Positional decay - attend more to recent tokens
        for j in range(i + 1):
            if j != 0 and j != i:  # Don't double-count first token and self
                distance = i - j
                if distance > 0:
                    decay_weight = 0.1 / (1 + 0.1 * distance)
                    attention[i, j] += decay_weight

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L18H6", attention



def prog_L18H7(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary detection head: attends to newlines, periods, and document structure markers with strong first-token attention."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    # Identify special structural tokens
    newline_positions = [i for i, token in enumerate(tokens) if '\n' in token]
    period_positions = [i for i, token in enumerate(tokens) if token.strip() == '.']

    for i in range(n):
        current_token = tokens[i]

        # Self-attention (especially strong for first token)
        if i == 0:
            attention[i, i] = 0.8  # Very strong self-attention for first token
        else:
            attention[i, i] = 0.1

        # Strong attention to newlines
        for nl_pos in newline_positions:
            if nl_pos <= i:  # Respect causal mask
                # Distance decay but still strong
                distance = i - nl_pos
                if distance == 0:
                    attention[i, nl_pos] = 0.6
                else:
                    attention[i, nl_pos] = max(0.3, 0.5 - 0.05 * distance)

        # Moderate attention to periods
        for period_pos in period_positions:
            if period_pos <= i:
                distance = i - period_pos
                if distance == 0:
                    attention[i, period_pos] = 0.4
                else:
                    attention[i, period_pos] = max(0.15, 0.35 - 0.03 * distance)

        # Enhanced attention to first token (document start)
        if i > 0:
            # Check if we're in a context where first-token attention should be stronger
            # This happens when we're far from structural markers or in certain sentence positions
            base_first_attention = 0.2

            # Boost first-token attention if we're beyond the initial few tokens
            # and not immediately after a newline/period
            if i >= 3:
                # Check distance to nearest structural marker
                min_struct_distance = float('inf')
                for struct_pos in newline_positions + period_positions:
                    if struct_pos < i:
                        min_struct_distance = min(min_struct_distance, i - struct_pos)

                # If we're reasonably far from structural markers, boost first-token attention
                if min_struct_distance >= 2:
                    boost_factor = min(2.5, 1.0 + (i - 3) * 0.15)
                    base_first_attention *= boost_factor

            attention[i, 0] = min(0.5, base_first_attention)

        # Small attention to recent tokens (recency bias)
        for j in range(max(0, i-3), i):
            if attention[i, j] == 0:  # Don't override existing weights
                attention[i, j] = 0.05 * (1.0 - (i - j) * 0.2)

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L18H7", attention



def prog_L18H8(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Structural boundary attention: focuses on newlines, periods, and first token as text anchors."""
    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention_matrix = np.zeros((n, n))

    # Find anchor tokens: newlines, periods, and first token
    anchor_indices = []
    for i, token in enumerate(tokens):
        if token.strip() in ['\n', '.'] or i == 0:
            anchor_indices.append(i)

    for i in range(n):
        current_token = tokens[i].strip()

        if current_token == '\n':
            # Newlines attend strongly to themselves
            attention_matrix[i, i] = 1.0
        elif current_token == '.':
            # Periods attend to themselves with high weight
            attention_matrix[i, i] = 0.8
            # Some attention to other anchors
            for anchor_idx in anchor_indices:
                if anchor_idx < i and anchor_idx != i:
                    attention_matrix[i, anchor_idx] = 0.1
        elif i == 0:
            # First token attends to itself
            attention_matrix[i, i] = 1.0
        else:
            # Regular tokens attend primarily to anchor tokens
            total_weight = 0.0

            # Strong attention to newlines and periods
            for anchor_idx in anchor_indices:
                if anchor_idx <= i:
                    if tokens[anchor_idx].strip() == '\n':
                        attention_matrix[i, anchor_idx] = 0.4
                        total_weight += 0.4
                    elif tokens[anchor_idx].strip() == '.':
                        attention_matrix[i, anchor_idx] = 0.3
                        total_weight += 0.3
                    elif anchor_idx == 0:
                        attention_matrix[i, anchor_idx] = 0.2
                        total_weight += 0.2

            # Small self-attention
            attention_matrix[i, i] = 0.1
            total_weight += 0.1

            # Distribute remaining weight to nearby tokens
            remaining_weight = max(0, 1.0 - total_weight)
            if remaining_weight > 0:
                nearby_count = 0
                for j in range(max(0, i-3), i):
                    if j not in anchor_indices:
                        nearby_count += 1

                if nearby_count > 0:
                    nearby_weight = remaining_weight / nearby_count
                    for j in range(max(0, i-3), i):
                        if j not in anchor_indices:
                            attention_matrix[i, j] = nearby_weight

    # Apply causal mask and normalize
    attention_matrix = apply_causal_mask(attention_matrix)
    attention_matrix = make_row_stochastic(attention_matrix)

    return "prog_L18H8", attention_matrix



def prog_L18H9(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary and structural delimiter attention head."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    # Find structural tokens: newlines, periods, and first token
    newline_indices = [i for i, tok in enumerate(tokens) if tok.strip() == '\n']
    period_indices = [i for i, tok in enumerate(tokens) if tok.strip() == '.']

    for i in range(n):
        current_token = tokens[i].strip()

        # Strong self-attention for first token and structural tokens
        if i == 0 or current_token in ['\n', '.']:
            attention[i, i] = 0.8
        else:
            attention[i, i] = 0.1

        # High attention to newlines from all tokens
        for newline_idx in newline_indices:
            if newline_idx <= i:
                attention[i, newline_idx] = 0.6

        # Medium-high attention to periods, especially from nearby tokens
        for period_idx in period_indices:
            if period_idx <= i:
                # Distance-based decay for period attention
                distance = i - period_idx
                if distance == 0:
                    continue  # Already handled in self-attention
                elif distance <= 5:
                    attention[i, period_idx] = 0.4
                else:
                    attention[i, period_idx] = 0.2

        # Some attention to first token
        if i > 0:
            attention[i, 0] = 0.3

        # Small attention to immediately previous token
        if i > 0 and tokens[i-1].strip() not in ['\n', '.']:
            attention[i, i-1] = 0.15

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L18H9", attention



def prog_L19H0(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Discourse boundary attention head with strong first-token attention - attends to newlines, sentence boundaries, and especially the first token."""
    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    # Find newline and sentence boundary tokens
    newline_positions = []
    boundary_positions = []

    for i, token in enumerate(tokens):
        if '\n' in token:
            newline_positions.append(i)
        if token.strip() in ['.', '!', '?']:
            boundary_positions.append(i)

    # Get spacy alignment for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        # Strong attention to newlines
        for nl_pos in newline_positions:
            if nl_pos <= i:  # Causal constraint
                attention[i, nl_pos] = 0.4

        # Moderate attention to sentence boundaries
        for boundary_pos in boundary_positions:
            if boundary_pos <= i:
                attention[i, boundary_pos] = 0.2

        # Much stronger attention to first token - this is the key pattern
        if i > 0:
            attention[i, 0] = 0.8  # Increased from 0.1 to 0.8

        # Self-attention for special tokens
        if tokens[i].strip() in ['\n', '.', '!', '?', '', ' ']:
            attention[i, i] = 0.3

        # Small attention to nearby tokens based on linguistic features
        spacy_indices = token_to_spacy[i]
        if spacy_indices:
            spacy_token = doc[spacy_indices[0]]
            # Attend to syntactic head
            if spacy_token.head != spacy_token:
                head_spacy_idx = spacy_token.head.i
                for j in range(i):
                    if head_spacy_idx in token_to_spacy[j]:
                        attention[i, j] = 0.1
                        break

        # Add small uniform attention to previous tokens
        for j in range(i):
            attention[i, j] += 0.02

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L19H0", attention



def prog_L19H1(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Structural token attention head with strong beginning-of-sequence focus."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L19H1", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Identify structural tokens
    newline_indices = [i for i, t in enumerate(tokens) if t.strip() == '']
    period_indices = [i for i, t in enumerate(tokens) if t.strip() == '.']
    first_token_idx = 0

    for i in range(n):
        token = tokens[i].strip()

        # Enhanced attention to first token - stronger for later positions
        if i > 0:
            # Scale attention to first token based on position
            base_first_attention = 0.6
            if i > 20:  # For tokens well into the sequence
                base_first_attention = min(0.85, 0.6 + (i - 20) * 0.01)
            attention[i, first_token_idx] = base_first_attention

        # Reduced attention to newlines for later tokens to compensate for stronger first-token attention
        for nl_idx in newline_indices:
            if nl_idx <= i and nl_idx != i:
                nl_attention = 0.35
                if i > 20:  # Reduce newline attention for later tokens
                    nl_attention = max(0.15, 0.35 - (i - 20) * 0.008)
                attention[i, nl_idx] = nl_attention

        # Medium attention to periods
        for p_idx in period_indices:
            if p_idx <= i and p_idx != i:
                attention[i, p_idx] = 0.25

        # Self-attention for structural tokens
        if token == '' or token == '.':
            attention[i, i] = 0.4

        # Small baseline attention to recent tokens
        for j in range(max(0, i-5), i):
            if attention[i, j] == 0:  # Don't override structural attention
                attention[i, j] = 0.02

        # Small self-attention for non-structural tokens
        if token != '' and token != '.' and attention[i, i] == 0:
            attention[i, i] = 0.01

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L19H1", attention



def prog_L19H10(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Structural boundary attention head focusing on newlines, sentence breaks, and strong first-token attention."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L19H10", np.zeros((n_empty, n_empty))

    attention_matrix = np.zeros((n, n))

    # Get spacy alignment for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        # Strong attention to newline characters
        for j in range(i + 1):
            if tokens[j].strip() == '\n':
                attention_matrix[i, j] += 0.3

        # Self-attention (reduced slightly to compensate for stronger first-token attention)
        attention_matrix[i, i] += 0.15

        # Attention to sentence-ending punctuation
        for j in range(i + 1):
            if tokens[j].strip() in ['.', '!', '?']:
                attention_matrix[i, j] += 0.15

        # Much stronger attention to first token throughout the sequence
        if i > 0:
            attention_matrix[i, 0] += 0.4

        # Local syntactic attention - attend to previous token with decay
        for j in range(max(0, i - 3), i):
            distance = i - j
            attention_matrix[i, j] += 0.1 / distance

        # Boost attention based on spacy features
        spacy_indices = token_to_spacy[i]
        if spacy_indices:
            spacy_token = doc[spacy_indices[0]]

            # If current token is a verb, attend to nearby nouns
            if spacy_token.pos_ in ['VERB']:
                for j in range(max(0, i - 5), i):
                    j_spacy_indices = token_to_spacy[j]
                    if j_spacy_indices:
                        j_spacy_token = doc[j_spacy_indices[0]]
                        if j_spacy_token.pos_ in ['NOUN', 'PRON']:
                            attention_matrix[i, j] += 0.08

            # If current token is punctuation, attend to preceding content words
            if spacy_token.pos_ == 'PUNCT':
                for j in range(max(0, i - 3), i):
                    j_spacy_indices = token_to_spacy[j]
                    if j_spacy_indices:
                        j_spacy_token = doc[j_spacy_indices[0]]
                        if j_spacy_token.pos_ in ['NOUN', 'VERB', 'ADJ']:
                            attention_matrix[i, j] += 0.06

    # Apply causal mask and normalize
    attention_matrix = apply_causal_mask(attention_matrix)
    attention_matrix = make_row_stochastic(attention_matrix)

    return "prog_L19H10", attention_matrix



def prog_L19H11(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Structural boundary and positional anchor attention head with enhanced document structure focus."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L19H11", np.zeros((n_empty, n_empty))

    attention_matrix = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        token = tokens[i].strip()

        # Base weights
        weights = np.zeros(i + 1)  # Can only attend to positions 0 through i

        # Strong attention to sentence boundary markers (newlines and periods)
        for j in range(i + 1):
            target_token = tokens[j].strip()
            if target_token == '\n':
                weights[j] += 0.3
            elif target_token == '.':
                weights[j] += 0.25

        # Strong attention to first token
        if i > 0:
            weights[0] += 0.15

        # Self-attention
        weights[i] += 0.1

        # Special boost for tokens that are boundary markers themselves
        if token == '\n':
            weights[i] += 0.2
        elif token == '.':
            weights[i] += 0.15

        # TARGETED FIX: Much stronger attention to document structure
        # This head appears to be primarily focused on document/paragraph structure
        for j in range(i + 1):
            target_token = tokens[j].strip()
            # Greatly boost attention to newlines (paragraph boundaries)
            if target_token == '\n':
                weights[j] += 0.4  # Additional boost beyond the original 0.3
            # Significantly boost attention to the very first token (document start)
            elif j == 0 and i > 5:  # Only for tokens well into the document
                weights[j] += 0.3  # Additional boost beyond the original 0.15

        # Local syntactic dependencies using spacy alignment
        if token_to_spacy[i]:
            spacy_idx = token_to_spacy[i][0]
            if spacy_idx < len(doc):
                spacy_token = doc[spacy_idx]

                # Attend to syntactic head
                if spacy_token.head != spacy_token:
                    head_char_start = spacy_token.head.idx
                    # Find corresponding LM token
                    for j in range(i + 1):
                        if token_to_spacy[j]:
                            for spacy_j in token_to_spacy[j]:
                                if spacy_j < len(doc) and doc[spacy_j].idx <= head_char_start < doc[spacy_j].idx + len(doc[spacy_j].text):
                                    weights[j] += 0.08
                                    break

        # Attend to recent important tokens (recency bias with structural importance)
        for j in range(max(0, i - 10), i):
            target_token = tokens[j].strip()
            distance_factor = 1.0 / (i - j + 1)

            # Boost for content words and structural markers
            if token_to_spacy[j]:
                spacy_idx = token_to_spacy[j][0]
                if spacy_idx < len(doc):
                    spacy_token = doc[spacy_idx]
                    if spacy_token.pos_ in ['NOUN', 'VERB', 'ADJ', 'PROPN']:
                        weights[j] += 0.05 * distance_factor

        # Add small random baseline to prevent all zeros
        weights += 0.001

        # Normalize
        if weights.sum() > 0:
            weights = weights / weights.sum()

        attention_matrix[i, :i+1] = weights

    # Ensure row stochastic and causal
    attention_matrix = make_row_stochastic(attention_matrix)
    attention_matrix = apply_causal_mask(attention_matrix)

    return "prog_L19H11", attention_matrix



def prog_L19H12(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Structural boundary attention with positional bias toward sentence/paragraph breaks and strong first-token attention."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention_matrix = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        # Self-attention baseline
        attention_matrix[i, i] = 0.1

        # Strong self-attention for first token
        if i == 0:
            attention_matrix[i, i] = 1.0
            continue

        # High attention to newlines and sentence boundaries
        for j in range(i + 1):
            token = tokens[j].strip()

            # Very high attention to newlines
            if token == '\n':
                attention_matrix[i, j] = 0.3

            # High attention to periods and sentence boundaries
            elif token in ['.', '!', '?']:
                attention_matrix[i, j] = 0.15

            # Moderate attention to commas
            elif token == ',':
                attention_matrix[i, j] = 0.08

        # Attention to immediately preceding token
        if i > 0:
            attention_matrix[i, i-1] += 0.12

        # Strong attention back to the first token (new pattern)
        if i > 0:
            attention_matrix[i, 0] += 0.25

        # Syntactic relationships using spacy
        if token_to_spacy[i]:
            spacy_idx = token_to_spacy[i][0]
            if spacy_idx < len(doc):
                current_token = doc[spacy_idx]

                # Determiners attend to their head nouns
                if current_token.pos_ == 'DET':
                    head = current_token.head
                    for j in range(i + 1):
                        if token_to_spacy[j] and token_to_spacy[j][0] < len(doc):
                            if doc[token_to_spacy[j][0]] == head:
                                attention_matrix[i, j] += 0.2

                # Prepositions attend to their objects
                elif current_token.pos_ == 'ADP':
                    for child in current_token.children:
                        if child.dep_ == 'pobj':
                            for j in range(i + 1):
                                if token_to_spacy[j] and token_to_spacy[j][0] < len(doc):
                                    if doc[token_to_spacy[j][0]] == child:
                                        attention_matrix[i, j] += 0.15

    # Apply causal mask and normalize
    attention_matrix = apply_causal_mask(attention_matrix)
    attention_matrix = make_row_stochastic(attention_matrix)

    return "prog_L19H12", attention_matrix



def prog_L19H13(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Attention head focusing on local syntax and referential cohesion with reduced discourse boundary emphasis."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        token_i = tokens[i]

        # Base self-attention
        attention[i, i] = 0.1

        # Reduced attention to newlines (was 0.3, now 0.15)
        for j in range(i + 1):
            token_j = tokens[j]
            if token_j.strip() == '' and '\n' in token_j:
                attention[i, j] += 0.15

        # Reduced attention to periods (was 0.15, now 0.08)
        for j in range(i + 1):
            token_j = tokens[j]
            if token_j.strip() == '.':
                attention[i, j] += 0.08

        # First token gets some attention
        if i > 0:
            attention[i, 0] += 0.05

        # Enhanced self-attention for cohesive elements
        if token_to_spacy[i]:
            spacy_idx = token_to_spacy[i][0]
            if spacy_idx < len(doc):
                spacy_token = doc[spacy_idx]

                # Strong self-attention for pronouns and determiners (referential cohesion)
                if spacy_token.pos_ in ['PRON', 'DET']:
                    attention[i, i] += 0.4

                # Enhanced self-attention for content words
                if spacy_token.pos_ in ['NOUN', 'VERB', 'ADJ', 'ADV']:
                    attention[i, i] += 0.2

        # Local syntactic patterns
        if token_to_spacy[i]:
            spacy_idx = token_to_spacy[i][0]
            if spacy_idx < len(doc):
                spacy_token = doc[spacy_idx]

                # Prepositions attend to their objects
                if spacy_token.pos_ == 'ADP' and i > 0:
                    attention[i, i-1] += 0.2

                # Adjectives attend to their head nouns
                if spacy_token.pos_ == 'ADJ':
                    for j in range(i + 1):
                        if token_to_spacy[j]:
                            spacy_j = token_to_spacy[j][0]
                            if spacy_j < len(doc) and doc[spacy_j].pos_ == 'NOUN':
                                sim = _char_sim(tokens[i], tokens[j])
                                if sim > 0.3:
                                    attention[i, j] += 0.1

                # Verbs attend to nearby subjects/objects
                if spacy_token.pos_ == 'VERB':
                    for j in range(max(0, i-3), i):
                        if token_to_spacy[j]:
                            spacy_j = token_to_spacy[j][0]
                            if spacy_j < len(doc) and doc[spacy_j].pos_ in ['NOUN', 'PRON']:
                                attention[i, j] += 0.08

        # Recency bias for nearby tokens
        for j in range(max(0, i-2), i):
            attention[i, j] += 0.05

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L19H13", attention



def prog_L19H14(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Structural boundary attention head focusing on first tokens and newlines."""
    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L19H14", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    for i in range(n):
        # Strong self-attention for first token
        if i == 0:
            attention[i, i] = 1.0
            continue

        # Find important structural tokens to attend to
        weights = np.zeros(i + 1)  # Can only attend to previous tokens + self

        # Always attend to self with base weight
        weights[i] = 0.1

        # Strong attention to first token
        weights[0] = 0.4

        # High attention to newline characters
        for j in range(i + 1):
            if tokens[j].strip() == '\n' or tokens[j] == '\n':
                weights[j] += 0.3

        # Moderate attention to punctuation that marks sentence boundaries
        for j in range(i + 1):
            token_clean = tokens[j].strip()
            if token_clean in ['.', '!', '?', '."', '!"', '?"']:
                weights[j] += 0.15

        # Attention to previous token (recency)
        if i > 0:
            weights[i-1] += 0.05

        # Small distributed attention to other tokens
        for j in range(i + 1):
            if weights[j] == 0:
                weights[j] = 0.02

        # Normalize weights
        if weights.sum() > 0:
            weights = weights / weights.sum()

        attention[i, :i+1] = weights

    # Apply causal mask and ensure row stochastic
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L19H14", attention



def prog_L19H15(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Structural boundary attention with enhanced self-attention for content words and reduced newline over-attention."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L19H15", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    alignment = _align_to_spacy(sentence, tokens)
    doc = spacy_parse(sentence)

    for i in range(n):
        token = tokens[i]

        # Enhanced self-attention logic
        if i == 0:
            attention[i, i] = 1.0
        elif token.strip() in ['.', '!', '?']:
            attention[i, i] = 0.3
        else:
            # Check if this token corresponds to content words that should have higher self-attention
            base_self_attention = 0.15
            if alignment[i]:  # If token aligns with spacy tokens
                for spacy_idx in alignment[i]:
                    if spacy_idx < len(doc):
                        spacy_token = doc[spacy_idx]
                        # Boost self-attention for certain POS tags and linguistic features
                        if (spacy_token.pos_ in ['NOUN', 'VERB', 'PROPN', 'ADJ'] or 
                            spacy_token.dep_ in ['ROOT', 'nsubj', 'dobj'] or
                            len(token.strip()) > 3):  # Longer tokens often get more self-attention
                            base_self_attention = 0.4
                            break
            attention[i, i] = base_self_attention

        # Attention to previous tokens
        for j in range(i):
            target_token = tokens[j]

            # Reduced attention to newlines (was 0.35, now 0.2)
            if target_token == '\n' or target_token.startswith('\n'):
                attention[i, j] = 0.2
            # High attention to first token if it's not current token
            elif j == 0 and i > 0:
                attention[i, j] = 0.25
            # Moderate attention to sentence-ending punctuation
            elif target_token.strip() in ['.', '!', '?']:
                attention[i, j] = 0.15
            # Some attention based on embedding similarity
            elif _char_sim(tokens[i], tokens[j]) > 0.7:
                attention[i, j] = 0.1
            # Recency bias - slight attention to recent tokens
            elif i - j <= 3:
                attention[i, j] = 0.05
            else:
                attention[i, j] = 0.02

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L19H15", attention



def prog_L19H16(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """First-token attention head with sentence boundary and self-attention components."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L19H16", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        # Strong bias toward first token
        attention[i, 0] = 0.8

        # Self-attention
        attention[i, i] = 0.3

        # Attention to sentence boundaries (periods, newlines)
        for j in range(i + 1):
            token_text = tokens[j].strip()
            if token_text in ['.', '\n']:
                attention[i, j] += 0.4

        # Additional first-token boost for certain positions
        if i > 0:
            # Tokens early in sentence get extra first-token weight
            if i < 5:
                attention[i, 0] += 0.3

            # Content words get stronger first-token attention
            spacy_indices = token_to_spacy[i]
            if spacy_indices:
                spacy_token = doc[spacy_indices[0]]
                if spacy_token.pos_ in ['NOUN', 'VERB', 'ADJ', 'ADV']:
                    attention[i, 0] += 0.2

        # Enhanced self-attention for certain token types
        spacy_indices = token_to_spacy[i]
        if spacy_indices:
            spacy_token = doc[spacy_indices[0]]
            # Boost self-attention for content words and certain punctuation
            if (spacy_token.pos_ in ['NOUN', 'VERB', 'ADJ', 'ADV'] or 
                tokens[i].strip() in ['"', "'", '!', '?']):
                attention[i, i] += 0.4

        # Special handling for tokens after newlines - reduce first-token bias and boost newline attention
        if i > 0:
            # Find the most recent newline before position i
            recent_newline = -1
            for j in range(i - 1, -1, -1):
                if tokens[j].strip() == '\n':
                    recent_newline = j
                    break

            # If we're within a few tokens after a newline, reduce first-token attention and boost newline attention
            if recent_newline >= 0 and (i - recent_newline) <= 5:
                attention[i, 0] *= 0.3  # Significantly reduce first-token attention
                attention[i, recent_newline] += 0.5  # Boost attention to the newline

        # Slight recency bias for nearby tokens
        for j in range(max(0, i - 3), i):
            attention[i, j] += 0.1 * (1.0 - (i - j) / 4.0)

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L19H16", attention



def prog_L19H17(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """First-token and newline attention with strong positional bias."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    # Find first token and newline positions
    first_token_idx = 0
    newline_indices = [i for i, token in enumerate(tokens) if token == '\n']

    for i in range(n):
        # Self-attention baseline
        attention[i, i] = 0.1

        # Strong attention to first token from most positions
        if i != first_token_idx:
            attention[i, first_token_idx] = 0.4

        # Strong attention to newlines from later positions
        for newline_idx in newline_indices:
            if i > newline_idx:
                attention[i, newline_idx] = 0.35

        # Distance-based decay for nearby tokens
        for j in range(max(0, i-3), i):
            if j != first_token_idx and tokens[j] != '\n':
                decay = 0.15 / (i - j)
                attention[i, j] = max(attention[i, j], decay)

        # Special patterns for specific sequences
        if i > 0:
            # Previous token attention for certain cases
            prev_token = tokens[i-1]
            if prev_token in ['.', '!', '?']:
                attention[i, i-1] = 0.2

            # Look for consecutive word patterns
            if i >= 3:
                # Strong attention between related consecutive tokens
                for j in range(max(0, i-2), i):
                    sim = _char_sim(tokens[i], tokens[j])
                    if sim > 0.7:  # High similarity threshold
                        attention[i, j] = 0.25

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L19H17", attention



def prog_L19H18(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Head that combines self-attention, strong first-token anchoring, and local syntactic dependencies."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L19H18", np.zeros((n_empty, n_empty))

    # Initialize attention matrix
    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    # Identify special positions: first token and newlines
    first_token_idx = 0
    newline_indices = [i for i, token in enumerate(tokens) if token.strip() == '\n' or token == '\n']

    for i in range(n):
        query_token = tokens[i]

        # Moderate self-attention (reduced from 1.0)
        attention[i, i] = 0.6

        # Very high attention to first token for most positions
        if i != first_token_idx:
            # Boost first-token attention significantly for positions beyond early tokens
            if i > 3:
                attention[i, first_token_idx] = 1.2
            else:
                attention[i, first_token_idx] = 0.8

        # High attention to newlines
        for nl_idx in newline_indices:
            if nl_idx <= i:
                attention[i, nl_idx] = 0.7

        # Get spacy token info for query
        query_spacy_indices = token_to_spacy[i]

        # Look for syntactic dependencies and local relationships
        for j in range(i):
            key_token = tokens[j]
            key_spacy_indices = token_to_spacy[j]

            # Base attention for all previous positions
            attention[i, j] = 0.1

            # Boost for recent positions
            if i - j <= 3:
                attention[i, j] += 0.15

            # Boost for embedding similarity (related words)
            sim = _char_sim(tokens[i], tokens[j])
            if sim > 0.3:
                attention[i, j] += 0.3 * sim

            # Boost for punctuation
            if key_token.strip() in ['.', ',', '!', '?']:
                attention[i, j] += 0.2

            # Syntactic relationships
            if query_spacy_indices and key_spacy_indices:
                for q_idx in query_spacy_indices:
                    if q_idx < len(doc):
                        query_spacy = doc[q_idx]
                        for k_idx in key_spacy_indices:
                            if k_idx < len(doc):
                                key_spacy = doc[k_idx]

                                # Head-dependent relationships
                                if query_spacy.head == key_spacy or key_spacy.head == query_spacy:
                                    attention[i, j] += 0.4

                                # Modifier relationships
                                if key_spacy in query_spacy.children or query_spacy in key_spacy.children:
                                    attention[i, j] += 0.3

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L19H18", attention



def prog_L19H19(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Structural attention head focusing on sentence beginnings, newlines, and punctuation with broad first-token attention."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    # Find structural tokens
    first_token_idx = 0
    newline_indices = []
    punct_indices = []

    for i, token in enumerate(tokens):
        if token.strip() == '\n':
            newline_indices.append(i)
        elif token.strip() in ['.', ',', '!', '?', ';', ':']:
            punct_indices.append(i)

    for i in range(n):
        current_token = tokens[i].strip()

        # Self-attention baseline
        attention[i, i] = 0.1

        # Very high attention to first token from early tokens (positions 1-3)
        if i <= 3 and i > 0:
            attention[i, first_token_idx] = 0.9

        # NEW: Broader first-token attention pattern for many tokens
        # This captures the missing pattern from the worst examples
        if i > 3 and i < n:
            # Get spacy analysis for linguistic features
            doc = spacy_parse(sentence)
            token_to_spacy = _align_to_spacy(sentence, tokens)

            # Apply first-token attention for content words and function words
            if token_to_spacy[i]:  # If token aligns to spacy tokens
                spacy_idx = token_to_spacy[i][0]
                if spacy_idx < len(doc):
                    spacy_token = doc[spacy_idx]
                    # Apply to various POS types that show this pattern
                    if spacy_token.pos_ in ['NOUN', 'VERB', 'ADJ', 'ADV', 'PRON', 'DET', 'ADP', 'PART']:
                        attention[i, first_token_idx] = 0.7

        # Strong attention to newlines from most tokens
        for nl_idx in newline_indices:
            if nl_idx <= i:
                if current_token == '\n':
                    # Newlines attend strongly to themselves
                    attention[i, nl_idx] = 0.32
                else:
                    # Other tokens attend to newlines with moderate strength
                    attention[i, nl_idx] = 0.28

        # Attention to punctuation
        for punct_idx in punct_indices:
            if punct_idx <= i:
                # Moderate attention to punctuation
                attention[i, punct_idx] = 0.15

                # Special case: newlines attend more strongly to preceding punctuation
                if current_token == '\n' and punct_idx == i - 1:
                    attention[i, punct_idx] = 0.28

        # Special case for punctuation tokens attending to themselves
        if current_token in ['.', ',', '!', '?', ';', ':']:
            attention[i, i] = 0.35

        # Special case for newline tokens attending to themselves
        if current_token == '\n':
            attention[i, i] = 0.32

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L19H19", attention



def prog_L19H2(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Boundary marker attention with strong first-token focus and cumulative newline attention."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    # Find boundary markers
    newline_indices = [i for i, token in enumerate(tokens) if token.strip() == '\n']
    period_indices = [i for i, token in enumerate(tokens) if token.strip() == '.']

    for i in range(n):
        # Very strong attention to first token (increased from 0.3)
        if i > 0:
            attention[i, 0] = 0.6

        # Moderate attention to ALL previous newlines (not just recent ones)
        for nl_idx in newline_indices:
            if nl_idx <= i and nl_idx > 0:  # Causal constraint, skip first token newlines
                attention[i, nl_idx] = 0.15

        # Reduced attention to periods to avoid over-prediction
        for period_idx in period_indices:
            if period_idx <= i and period_idx > 0:  # Causal constraint, skip first token periods
                attention[i, period_idx] = 0.1

        # Reduced self-attention baseline
        attention[i, i] = 0.05

        # Small uniform attention to recent tokens (recency bias) - reduced strength
        for j in range(max(0, i-5), i):
            if tokens[j].strip() not in ['\n', '.'] and j > 0:  # Don't double-count boundaries or first token
                attention[i, j] += 0.02

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L19H2", attention



def prog_L19H20(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Structural boundary detection head with verb-enhanced attention: attends to sentence/paragraph boundaries and sentence-initial tokens, with stronger patterns for verbs."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L19H20", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        token = tokens[i]

        # Very strong self-attention for first token
        if i == 0:
            attention[i, i] = 1.0
            continue

        # Check if this token is a verb (for enhanced attention patterns)
        is_verb = False
        if token_to_spacy[i]:
            spacy_indices = token_to_spacy[i]
            for spacy_idx in spacy_indices:
                if spacy_idx < len(doc):
                    spacy_token = doc[spacy_idx]
                    if spacy_token.pos_ == 'VERB':
                        is_verb = True
                        break

        # Adjust boundary attention weights based on token type
        boundary_multiplier = 2.0 if is_verb else 0.7

        # High attention to sentence boundaries (periods) - enhanced for verbs
        period_weight = 0.0
        for j in range(i + 1):
            if tokens[j] in ['.', '!', '?']:
                base_weight = 0.6 * boundary_multiplier
                attention[i, j] += base_weight
                period_weight += base_weight

        # High attention to paragraph breaks (newlines) - enhanced for verbs  
        newline_weight = 0.0
        for j in range(i + 1):
            if tokens[j] == '\n':
                base_weight = 0.4 * boundary_multiplier
                attention[i, j] += base_weight
                newline_weight += base_weight

        # Attention to sentence-initial tokens (tokens after periods/newlines)
        sentence_start_weight = 0.0
        for j in range(i + 1):
            if j == 0:  # First token
                attention[i, j] += 0.3
                sentence_start_weight += 0.3
            elif j > 0 and tokens[j-1] in ['.', '!', '?', '\n']:
                attention[i, j] += 0.2
                sentence_start_weight += 0.2

        # Enhanced self-attention for verbs
        self_boost = 0.4 if is_verb else 0.2
        attention[i, i] += self_boost

        # Recency bias for nearby tokens
        for j in range(max(0, i-5), i):
            distance = i - j
            weight = 0.1 / (distance + 1)
            attention[i, j] += weight

        # Special handling for tokens right after boundaries
        if i > 0 and (tokens[i-1] == '\n' or tokens[i-1] in ['.', '!', '?']):
            # This token is sentence-initial, attend strongly to the boundary
            attention[i, i-1] += 0.5
            attention[i, i] += 0.3

        # Boost attention between consecutive structural tokens
        if token == '\n' and i > 0:
            for j in range(i):
                if tokens[j] in ['.', '!', '?']:
                    attention[i, j] += 0.2

        # Empty strings often attend to nearby periods
        if token.strip() == '' and i > 0:
            for j in range(i):
                if tokens[j] in ['.', '!', '?']:
                    attention[i, j] += 0.4

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L19H20", attention



def prog_L19H21(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Previous-token attention with strong first-token and boundary bias."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L19H21", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        # Strong self-attention for first token
        if i == 0:
            attention[i, i] = 1.0
            continue

        # Base attention to previous token - reduced from 0.4
        attention[i, i-1] = 0.25

        # Self-attention
        attention[i, i] = 0.2

        # Strong attention to first token - increased significantly
        attention[i, 0] += 0.35

        # Attention to sentence boundaries (periods, newlines, etc.)
        for j in range(i):
            token_j = tokens[j].strip()
            if token_j in ['.', '\n', '!', '?']:
                attention[i, j] += 0.15

        # Get spacy info for current token
        spacy_indices_i = token_to_spacy[i]
        if spacy_indices_i:
            spacy_tok_i = doc[spacy_indices_i[0]]

            # Syntactic dependencies
            for j in range(i):
                spacy_indices_j = token_to_spacy[j]
                if spacy_indices_j:
                    spacy_tok_j = doc[spacy_indices_j[0]]

                    # Attend to syntactic head
                    if spacy_tok_i.head == spacy_tok_j:
                        attention[i, j] += 0.15

                    # Modifiers attend to their targets
                    if (spacy_tok_j.head == spacy_tok_i and 
                        spacy_tok_j.dep_ in ['amod', 'det', 'poss']):
                        attention[i, j] += 0.12

        # Distance decay for nearby tokens
        for j in range(max(0, i-3), i-1):
            distance = i - j
            decay = 0.05 / distance
            attention[i, j] += decay

        # Semantic similarity boost
        for j in range(i):
            sim = _char_sim(tokens[i], tokens[j])
            if sim > 0.7:
                attention[i, j] += 0.08 * sim

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L19H21", attention



def prog_L19H22(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Discourse boundary and syntactic dependency head with embedding similarity."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L19H22", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        # Strong self-attention for first token
        if i == 0:
            attention[i, i] = 1.0
            continue

        # Base attention distribution
        for j in range(i + 1):  # causal mask
            # High attention to line breaks and sentence boundaries
            if tokens[j] == '\n':
                attention[i, j] += 0.3
            elif tokens[j] in ['.', '!', '?']:
                attention[i, j] += 0.25

            # Attention to first token
            if j == 0:
                attention[i, j] += 0.2

            # Local syntactic dependencies
            if token_to_spacy[i] and token_to_spacy[j]:
                spacy_i = token_to_spacy[i][0]
                spacy_j = token_to_spacy[j][0]

                if spacy_i < len(doc) and spacy_j < len(doc):
                    tok_i = doc[spacy_i]
                    tok_j = doc[spacy_j]

                    # Pronoun to antecedent patterns
                    if tok_i.pos_ == 'PRON' and tok_j.pos_ in ['NOUN', 'PROPN']:
                        attention[i, j] += 0.15

                    # Verb to subject patterns
                    if tok_i.pos_ == 'VERB' and tok_j.dep_ in ['nsubj', 'nsubjpass']:
                        attention[i, j] += 0.12

                    # Determiner/adjective to noun
                    if tok_i.pos_ in ['DET', 'ADJ'] and tok_j.pos_ in ['NOUN', 'PROPN']:
                        attention[i, j] += 0.1

            # Embedding similarity boost
            sim = _char_sim(tokens[i], tokens[j])
            if sim > 0.7:
                attention[i, j] += 0.2 * sim
            elif sim > 0.5:
                attention[i, j] += 0.1 * sim

            # Recency bias
            distance = i - j
            if distance <= 3:
                attention[i, j] += 0.05 * (4 - distance) / 4

            # Small base attention to prevent zeros
            attention[i, j] += 0.01

    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L19H22", attention



def prog_L19H23(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Attention head with strong self-attention for content words and refined local dependencies."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L19H23", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    # Identify sentence boundaries and first tokens
    sentence_boundaries = []
    first_token_positions = [0]  # First token of entire sequence

    for i, token in enumerate(tokens):
        if token.strip() in ['.', '!', '?']:
            sentence_boundaries.append(i)
            if i + 1 < n:
                first_token_positions.append(i + 1)
        elif token == '\n' and i + 1 < n:
            first_token_positions.append(i + 1)

    for i in range(n):
        for j in range(i + 1):  # Causal mask
            weight = 0.01  # Base attention

            # Strong self-attention for first tokens
            if i == j and i in first_token_positions:
                weight = 1.0

            # Enhanced self-attention for content words
            elif i == j:
                if i < len(token_to_spacy) and token_to_spacy[i]:
                    spacy_token = doc[token_to_spacy[i][0]]
                    # Strong self-attention for nouns, verbs, adjectives, proper nouns
                    if spacy_token.pos_ in ['NOUN', 'VERB', 'ADJ', 'PROPN']:
                        weight = 0.4
                    # Moderate self-attention for pronouns and adverbs
                    elif spacy_token.pos_ in ['PRON', 'ADV']:
                        weight = 0.2

            # High attention from early tokens to first token
            elif j == 0 and i < 5:
                weight = 0.8

            # Attention to sentence boundaries and newlines
            elif tokens[j] in ['.', '\n'] or j in sentence_boundaries:
                if i > j:
                    weight = 0.25

            # Attention to first tokens from later positions
            elif j in first_token_positions and i > j:
                distance = i - j
                weight = max(0.15, 0.3 / (1 + distance * 0.1))

            # Local syntactic dependencies (reduced strength)
            elif abs(i - j) == 1:
                # Adjacent token relationships
                if i < len(token_to_spacy) and j < len(token_to_spacy):
                    spacy_i = token_to_spacy[i]
                    spacy_j = token_to_spacy[j]

                    if spacy_i and spacy_j:
                        spacy_token_i = doc[spacy_i[0]]
                        spacy_token_j = doc[spacy_j[0]]

                        # Check for syntactic relationships (reduced weight)
                        if (spacy_token_i.head == spacy_token_j or 
                            spacy_token_j.head == spacy_token_i):
                            weight = max(weight, 0.08)

                        # Semantic similarity boost (reduced)
                        sim = _char_sim(tokens[i], tokens[j])
                        if sim > 0.7:
                            weight = max(weight, 0.1)

            # Embedding similarity for distant tokens (reduced threshold)
            elif i - j > 1:
                sim = _char_sim(tokens[i], tokens[j])
                if sim > 0.8:
                    weight = max(weight, 0.05)

            attention[i, j] = weight

    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L19H23", attention



def prog_L19H24(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary and beginning-of-sentence attention with local syntactic patterns."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L19H24", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    # Identify newline tokens and sentence starts
    newline_indices = []
    sentence_starts = []

    for i, token in enumerate(tokens):
        if '\n' in token:
            newline_indices.append(i)

        # Check if this token starts a sentence (after newline or beginning)
        if i == 0:
            sentence_starts.append(i)
        elif i-1 in newline_indices or (i > 0 and '\n' in tokens[i-1]):
            # Find first non-whitespace token after newline
            if token.strip():
                sentence_starts.append(i)

    for i in range(n):
        # Base attention distribution
        for j in range(i + 1):  # Causal mask

            # Strong attention to newline characters
            if j in newline_indices:
                attention[i, j] += 0.4

            # Strong attention to sentence start tokens
            if j in sentence_starts:
                attention[i, j] += 0.3

            # Self-attention
            if i == j:
                attention[i, j] += 0.2

            # Previous token attention
            if j == i - 1:
                attention[i, j] += 0.15

            # Recency bias (decay with distance)
            distance = i - j
            if distance > 0:
                recency_weight = 0.1 * np.exp(-distance / 5.0)
                attention[i, j] += recency_weight

            # Syntactic relationships via spacy
            if token_to_spacy[i] and token_to_spacy[j]:
                spacy_i = token_to_spacy[i][0]
                spacy_j = token_to_spacy[j][0]

                if spacy_i < len(doc) and spacy_j < len(doc):
                    spacy_tok_i = doc[spacy_i]
                    spacy_tok_j = doc[spacy_j]

                    # Modifier to head relationships
                    if spacy_tok_j == spacy_tok_i.head:
                        attention[i, j] += 0.1

                    # Determiner to noun
                    if spacy_tok_i.dep_ == "det" and spacy_tok_j.pos_ == "NOUN":
                        attention[i, j] += 0.1

            # Punctuation patterns
            if tokens[j] in ['.', '!', '?']:
                attention[i, j] += 0.1

            # First token in sequence gets extra attention
            if j == 0:
                attention[i, j] += 0.2

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L19H24", attention



def prog_L19H25(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary attention head with strong first-token attention - tokens attend to newlines, sentence-ending punctuation, and strongly to the first token."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L19H25", np.zeros((n_empty, n_empty))

    attention_matrix = np.zeros((n, n))

    # Identify boundary tokens (newlines and sentence-ending punctuation)
    boundary_indices = []
    for i, token in enumerate(tokens):
        if token.strip() == '\n' or token.strip() in ['.', '!', '?']:
            boundary_indices.append(i)

    # If no boundaries found, add first token as boundary
    if not boundary_indices and n > 0:
        boundary_indices.append(0)

    for i in range(n):
        # Base attention to self
        attention_matrix[i, i] = 0.1

        # Strong attention to newlines
        for boundary_idx in boundary_indices:
            if boundary_idx <= i and tokens[boundary_idx].strip() == '\n':
                attention_matrix[i, boundary_idx] = 0.4

        # Moderate attention to sentence-ending punctuation
        for boundary_idx in boundary_indices:
            if boundary_idx <= i and tokens[boundary_idx].strip() in ['.', '!', '?']:
                attention_matrix[i, boundary_idx] = 0.2

        # Strong attention to the very first token (beginning-of-sequence)
        if i > 0:
            attention_matrix[i, 0] = 0.5

        # Small amount of attention to previous token for local context
        if i > 0:
            attention_matrix[i, i-1] = 0.05

    # Apply causal mask and normalize
    attention_matrix = apply_causal_mask(attention_matrix)
    attention_matrix = make_row_stochastic(attention_matrix)

    return "prog_L19H25", attention_matrix



def prog_L19H26(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Discourse structure attention: focuses on paragraph breaks, sentence boundaries, and text beginnings."""
    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L19H26", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        for j in range(i + 1):  # Causal mask: only attend to j <= i
            weight = 0.0

            # Very strong attention to newlines
            if tokens[j].strip() == '' and '\n' in tokens[j]:
                weight += 0.4

            # Strong attention to first token
            if j == 0:
                weight += 0.3

            # Attention to sentence-ending punctuation
            if tokens[j].strip() in ['.', '!', '?']:
                weight += 0.2

            # Self-attention boost
            if i == j:
                weight += 0.1
                # Extra boost for first token self-attention
                if i == 0:
                    weight += 0.6

            # Attention to commas and other punctuation
            if tokens[j].strip() in [',', ';', ':']:
                weight += 0.1

            # Distance decay for non-structural tokens
            if weight < 0.1:
                distance = i - j
                weight = max(0.01, 0.05 * np.exp(-0.1 * distance))

            # Boost for tokens that start sentences (based on spacy analysis)
            if token_to_spacy[j]:
                spacy_idx = token_to_spacy[j][0]
                if spacy_idx < len(doc):
                    spacy_token = doc[spacy_idx]
                    # Check if this token starts a sentence
                    if spacy_token.is_sent_start:
                        weight += 0.15

            attention[i, j] = weight

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L19H26", attention



def prog_L19H27(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Attention head with strong first-token focus, sentence boundaries, and local syntactic patterns."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L19H27", np.zeros((n_empty, n_empty))

    # Initialize attention matrix
    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        # Strong self-attention baseline
        attention[i, i] = 0.3

        # High attention to sentence boundaries (newlines and periods)
        for j in range(i + 1):
            if tokens[j] in ['\n', '.', '!', '?']:
                attention[i, j] += 0.4

        # Special boost for first token - much stronger than original
        if i > 0:
            # Progressive increase in first-token attention with distance
            first_token_boost = 0.2 + min(0.4, i * 0.02)  # Increases with position
            attention[i, 0] += first_token_boost

        # Local syntactic patterns
        if token_to_spacy[i]:
            spacy_idx = token_to_spacy[i][0]
            if spacy_idx < len(doc):
                spacy_token = doc[spacy_idx]

                # If this is an adjective, attend to its head noun
                if spacy_token.pos_ in ['ADJ'] and spacy_token.head != spacy_token:
                    head_char_start = spacy_token.head.idx
                    # Find corresponding LM token
                    for j in range(i):
                        if token_to_spacy[j]:
                            j_spacy_idx = token_to_spacy[j][0]
                            if j_spacy_idx < len(doc) and doc[j_spacy_idx].idx <= head_char_start < doc[j_spacy_idx].idx + len(doc[j_spacy_idx].text):
                                attention[i, j] += 0.3

                # If this is a determiner or preposition, attend to following content words
                if spacy_token.pos_ in ['DET', 'ADP'] and i > 0:
                    for j in range(max(0, i-3), i):
                        if token_to_spacy[j]:
                            j_spacy_idx = token_to_spacy[j][0]
                            if j_spacy_idx < len(doc) and doc[j_spacy_idx].pos_ in ['NOUN', 'VERB', 'ADJ']:
                                attention[i, j] += 0.2

        # Attend to immediately previous token with moderate weight
        if i > 0:
            attention[i, i-1] += 0.15

        # Attend to tokens with high embedding similarity
        for j in range(i):
            sim = _char_sim(tokens[i], tokens[j])
            if sim > 0.7:
                attention[i, j] += 0.2 * sim

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L19H27", attention



def prog_L19H28(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Structural attention head with strong beginning-of-sequence focus and punctuation tracking."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L19H28", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    alignment = _align_to_spacy(sentence, tokens)

    for i in range(n):
        token = tokens[i]

        # Strong self-attention for first token
        if i == 0:
            attention[i, i] = 1.0
            continue

        # TARGETED FIX: Strong attention to first token for all positions
        # This is the main pattern missing from the original code
        attention[i, 0] = 0.6

        # Find newline positions
        newline_positions = [j for j in range(i + 1) if tokens[j].strip() == '']

        # Strong attention to newlines
        for j in newline_positions:
            attention[i, j] = 0.4

        # Strong attention to punctuation (periods, quotes, commas)
        for j in range(i + 1):
            if tokens[j] in ['.', '"', "'", ',', '!', '?']:
                attention[i, j] = 0.2

        # Reduced self-attention to compensate for first-token attention
        attention[i, i] = 0.08

        # Attention to previous token
        if i > 0:
            attention[i, i-1] = 0.1

        # Syntactic attention using spacy
        if alignment[i]:
            spacy_idx = alignment[i][0]
            if spacy_idx < len(doc):
                spacy_token = doc[spacy_idx]

                # Attention to syntactic head
                if spacy_token.head != spacy_token:
                    head_token_idx = None
                    head_char_start = spacy_token.head.idx

                    # Find corresponding token index
                    char_pos = 0
                    for j in range(i + 1):
                        if char_pos <= head_char_start < char_pos + len(tokens[j]):
                            head_token_idx = j
                            break
                        char_pos += len(tokens[j])

                    if head_token_idx is not None:
                        attention[i, head_token_idx] = 0.08

                # Attention to tokens with similar POS tags
                for j in range(i):
                    if alignment[j]:
                        other_spacy_idx = alignment[j][0]
                        if other_spacy_idx < len(doc):
                            other_token = doc[other_spacy_idx]
                            if spacy_token.pos_ == other_token.pos_ and spacy_token.pos_ in ['NOUN', 'VERB']:
                                attention[i, j] = 0.05

        # Positional decay for early tokens
        for j in range(min(i, 5)):
            attention[i, j] += 0.03 * (1.0 / (i - j + 1))

        # Semantic similarity boost
        for j in range(i):
            sim = _char_sim(tokens[i], tokens[j])
            if sim > 0.7:
                attention[i, j] += 0.1 * sim

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L19H28", attention



def prog_L19H29(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Structural boundary attention head focusing on newlines, punctuation, sentence starts, and content word beginnings."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L19H29", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Check if first token is a content word using spacy
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)
    first_token_is_content = False
    if len(token_to_spacy) > 0 and len(token_to_spacy[0]) > 0:
        first_spacy_idx = token_to_spacy[0][0]
        if first_spacy_idx < len(doc):
            first_spacy_token = doc[first_spacy_idx]
            # Content words: nouns, verbs, adjectives, adverbs
            if first_spacy_token.pos_ in ['NOUN', 'VERB', 'ADJ', 'ADV', 'PROPN']:
                first_token_is_content = True

    for i in range(n):
        token = tokens[i]

        # High self-attention for first token
        if i == 0:
            attention[i, i] = 1.0
            continue

        # Find newlines and punctuation for structural attention
        newline_indices = [j for j in range(i + 1) if tokens[j].strip() == '\n' or tokens[j] == '\n']
        punct_indices = [j for j in range(i + 1) if tokens[j].strip() in '.!?,;:']

        # Strong attention to newlines
        for j in newline_indices:
            attention[i, j] = 0.4

        # Moderate attention to punctuation
        for j in punct_indices:
            attention[i, j] = 0.2

        # Self-attention baseline
        attention[i, i] = 0.1

        # Small attention to recent tokens (recency bias)
        for j in range(max(0, i - 3), i):
            if j not in newline_indices and j not in punct_indices:
                attention[i, j] = 0.05

        # Special case: if no structural tokens found, attend to beginning of sequence
        if not newline_indices and not punct_indices and i > 0:
            if first_token_is_content:
                # Strong attention to content word beginnings
                attention[i, 0] = 0.8
            else:
                attention[i, 0] = 0.3

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L19H29", attention



def prog_L19H3(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Previous-token attention head with strong first-token bias and sentence boundary attention."""
    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L19H3", np.zeros((n_empty, n_empty))
    if n == 1:
        return "prog_L19H3", np.array([[1.0]])

    attention = np.zeros((n, n))

    for i in range(n):
        # Base attention to previous token (reduced from original)
        if i > 0:
            attention[i, i-1] = 0.25

        # Self-attention (moderate)
        attention[i, i] = 0.2

        # Strong attention to sentence boundaries and first token
        for j in range(i+1):
            token_j = tokens[j].strip()

            # First token gets very high attention (increased significantly)
            if j == 0:
                attention[i, j] += 0.6

            # Sentence boundaries (periods, newlines) get high attention
            if token_j in ['.', '\n', '!', '?']:
                attention[i, j] += 0.4

            # Commas get moderate attention
            elif token_j in [',', ';', ':']:
                attention[i, j] += 0.1

        # Use spacy for syntactic patterns
        doc = spacy_parse(sentence)
        token_to_spacy = _align_to_spacy(sentence, tokens)

        if i < len(token_to_spacy) and token_to_spacy[i]:
            spacy_idx = token_to_spacy[i][0]
            if spacy_idx < len(doc):
                spacy_token = doc[spacy_idx]

                # Verbs attend to their subjects
                if spacy_token.pos_ in ['VERB', 'AUX']:
                    for child in spacy_token.children:
                        if child.dep_ in ['nsubj', 'nsubjpass']:
                            child_tokens = align_spacy_to_tokens(sentence)
                            if child.i < len(child_tokens):
                                for tok_idx in child_tokens[child.i]:
                                    if tok_idx <= i:
                                        attention[i, tok_idx] += 0.15

                # Pronouns attend to potential antecedents
                if spacy_token.pos_ == 'PRON':
                    for j in range(max(0, i-10), i):
                        if j < len(token_to_spacy) and token_to_spacy[j]:
                            j_spacy_idx = token_to_spacy[j][0]
                            if j_spacy_idx < len(doc):
                                j_spacy_token = doc[j_spacy_idx]
                                if j_spacy_token.pos_ in ['NOUN', 'PROPN']:
                                    attention[i, j] += 0.1

        # Add some embedding similarity bias for nearby tokens
        for j in range(max(0, i-5), i):
            sim = _char_sim(tokens[i], tokens[j])
            if sim > 0.7:
                attention[i, j] += 0.1 * sim

    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L19H3", attention



def prog_L19H30(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """First-token and sentence boundary attention head."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L19H30", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Find sentence boundary tokens (periods, newlines, exclamation marks, question marks)
    boundary_tokens = set()
    for i, token in enumerate(tokens):
        if token.strip() in ['.', '!', '?', '\n']:
            boundary_tokens.add(i)

    for i in range(n):
        # Very strong attention to first token
        attention[i, 0] = 1.0

        # Strong attention to sentence boundaries
        for boundary_idx in boundary_tokens:
            if boundary_idx <= i:  # respect causal mask
                attention[i, boundary_idx] = 0.3

        # Medium attention to previous few tokens (recency bias)
        for j in range(max(0, i-5), i):
            attention[i, j] = 0.1 * (1.0 / (i - j))

        # Small self-attention
        attention[i, i] = 0.05

    # Apply causal mask
    attention = apply_causal_mask(attention)

    # Normalize to make row stochastic
    attention = make_row_stochastic(attention)

    return "prog_L19H30", attention



def prog_L19H31(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Structural attention head focusing on sentence boundaries, first tokens, and syntactic dependencies with strong newline attention."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L19H31", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        token_i = tokens[i]

        # Strong attention to first token
        attention[i, 0] = 0.4

        # Strong self-attention
        attention[i, i] = 0.3

        # High attention to sentence boundaries and punctuation
        for j in range(i + 1):
            token_j = tokens[j]
            if token_j in ['.', '!', '?', '"', "'", ',', '\n']:
                attention[i, j] += 0.2

        # Special case: Much stronger attention to newline characters
        for j in range(i + 1):
            if tokens[j] == '\n':
                attention[i, j] += 0.25  # Additional boost for newlines

        # Attention based on syntactic relationships
        if token_to_spacy[i]:
            spacy_i = doc[token_to_spacy[i][0]]

            for j in range(i + 1):
                if token_to_spacy[j]:
                    spacy_j = doc[token_to_spacy[j][0]]

                    # Attention between syntactically related tokens
                    if spacy_j == spacy_i.head or spacy_i == spacy_j.head:
                        attention[i, j] += 0.15

                    # Attention within same syntactic phrase
                    if spacy_i.head == spacy_j.head and spacy_i.head != spacy_i:
                        attention[i, j] += 0.1

        # Recency bias - attend more to recent tokens
        for j in range(max(0, i - 5), i):
            attention[i, j] += 0.1 * (1.0 - (i - j) / 6.0)

        # Additional attention to tokens with high embedding similarity
        for j in range(i + 1):
            if i != j:
                sim = _char_sim(tokens[i], tokens[j])
                if sim > 0.7:
                    attention[i, j] += 0.1 * sim

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L19H31", attention



def prog_L19H4(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Structural boundary attention head that focuses on sentence beginnings, newlines and sentence endings."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention_matrix = np.zeros((n, n))

    # Find newlines and periods
    newline_indices = []
    period_indices = []

    for i, token in enumerate(tokens):
        if token.strip() == '\n':
            newline_indices.append(i)
        elif token.strip() == '.':
            period_indices.append(i)

    for i in range(n):
        # Strong attention to the first token (beginning of sentence)
        if i > 0:  # Don't apply to first token itself
            attention_matrix[i, 0] = 0.6

        # Strong attention to all newlines
        for newline_idx in newline_indices:
            if newline_idx <= i:  # causal constraint
                attention_matrix[i, newline_idx] = 0.4

        # Moderate attention to periods
        for period_idx in period_indices:
            if period_idx <= i:  # causal constraint
                attention_matrix[i, period_idx] = 0.15

        # Self-attention for newlines
        if i in newline_indices:
            attention_matrix[i, i] = 0.3

        # Small uniform attention to all other previous tokens
        for j in range(i + 1):
            if j not in newline_indices and j not in period_indices and j != 0:
                attention_matrix[i, j] = 0.02

    # Apply causal mask and normalize
    attention_matrix = apply_causal_mask(attention_matrix)
    attention_matrix = make_row_stochastic(attention_matrix)

    return "prog_L19H4", attention_matrix



def prog_L19H5(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary and discourse structure attention head."""
    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L19H5", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        # Strong self-attention for first token
        if i == 0:
            attention[i, i] = 1.0
            continue

        # Initialize base attention
        base_weight = 0.01

        for j in range(i + 1):  # Causal mask
            weight = base_weight

            # High attention to sentence boundaries (newlines and periods)
            if tokens[j] in ['\n', '.', '!', '?']:
                weight += 0.3

            # Strong self-attention for certain tokens
            if i == j:
                # Check if this token has special properties
                spacy_indices = token_to_spacy[i]
                is_special = False

                if spacy_indices:
                    spacy_token = doc[spacy_indices[0]]
                    # Self-attention for content words and certain function words
                    if spacy_token.pos_ in ['NOUN', 'VERB', 'ADJ', 'ADV'] or spacy_token.text.lower() in ['your']:
                        is_special = True

                if is_special or tokens[i] in ['your']:
                    weight += 0.2
                else:
                    weight += 0.05

            # Attention to first token from most positions
            if j == 0 and i > 0:
                weight += 0.15

            # Local syntactic dependencies
            if i != j and token_to_spacy[i] and token_to_spacy[j]:
                spacy_i = doc[token_to_spacy[i][0]]
                spacy_j = doc[token_to_spacy[j][0]]

                # Modifiers attend to their heads
                if spacy_i.head == spacy_j or spacy_j.head == spacy_i:
                    weight += 0.1

                # Special patterns for adjacent words
                if abs(i - j) == 1:
                    # Adjacent content words
                    if spacy_i.pos_ in ['NOUN', 'VERB', 'ADJ'] and spacy_j.pos_ in ['NOUN', 'VERB', 'ADJ']:
                        weight += 0.08

            # Proximity bonus (closer tokens get slightly higher attention)
            if i != j:
                distance = i - j
                if distance <= 3:
                    weight += 0.02 / distance

            # Embedding similarity bonus
            if i != j:
                sim = _char_sim(tokens[i], tokens[j])
                if sim > 0.7:
                    weight += 0.05 * sim

            attention[i, j] = weight

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L19H5", attention



def prog_L19H6(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Document structure head: attends to paragraph breaks, sentence boundaries, and the first token."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L19H6", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    for i in range(n):
        # Very high attention to first token from all positions
        if n > 0:
            attention[i, 0] = 1.0

        # High attention to sentence boundaries (periods)
        for j in range(i + 1):
            token_j = tokens[j].strip()
            if token_j in ['.', '!', '?']:
                attention[i, j] += 0.3

        # High attention to paragraph breaks (newlines)
        for j in range(i + 1):
            token_j = tokens[j].strip()
            if token_j == '\n' or (len(tokens[j]) > 0 and '\n' in tokens[j]):
                attention[i, j] += 0.4

        # Some self-attention
        attention[i, i] += 0.1

        # Small attention to recent tokens
        for j in range(max(0, i - 3), i):
            attention[i, j] += 0.05

        # Special boost for tokens immediately after structural elements
        if i > 0:
            prev_token = tokens[i-1].strip()
            if prev_token in ['.', '\n'] or '\n' in tokens[i-1]:
                for j in range(i):
                    if tokens[j].strip() in ['.', '\n'] or '\n' in tokens[j]:
                        attention[i, j] += 0.2

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L19H6", attention



def prog_L19H7(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Structural boundary attention: focuses on newlines, sentence endings, and first tokens."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    # Find structural tokens
    newline_indices = []
    period_indices = []

    for i, token in enumerate(tokens):
        if token.strip() == '\n':
            newline_indices.append(i)
        elif token.strip() == '.':
            period_indices.append(i)

    # Main attention pattern
    for i in range(n):
        # Strong attention to newlines, especially the first one
        for j in newline_indices:
            if j <= i:
                if len(newline_indices) > 0 and j == newline_indices[0]:
                    # Very strong attention to first newline
                    attention[i, j] = 0.4
                else:
                    # Moderate attention to other newlines
                    attention[i, j] = 0.2

        # Moderate attention to periods
        for j in period_indices:
            if j <= i:
                attention[i, j] = 0.15

        # Strong attention to first token if it's not whitespace
        if len(tokens) > 0 and tokens[0].strip():
            attention[i, 0] = 0.25

        # Self-attention for newlines
        if i in newline_indices:
            attention[i, i] = 0.3

        # Weak baseline attention to nearby tokens
        for j in range(max(0, i-3), i+1):
            if attention[i, j] == 0:  # Don't overwrite existing attention
                attention[i, j] = 0.02

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L19H7", attention



def prog_L19H8(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Structural token attention head with strong first-token bias for content words."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L19H8", np.zeros((n_empty, n_empty))

    attention_matrix = np.zeros((n, n))

    # Get linguistic features for content word detection
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        for j in range(i + 1):  # Causal mask: j <= i
            weight = 0.0

            # Very high attention to newline tokens
            if tokens[j].strip() == '\n' or tokens[j] == '\n':
                weight += 3.0

            # High attention to periods and sentence boundaries
            elif tokens[j] == '.':
                weight += 1.5

            # Self-attention
            elif i == j:
                weight += 0.8

            # First token attention - BOOSTED for content words
            elif j == 0:
                # Check if current token i is a content word
                is_content_word = False
                if token_to_spacy[i]:  # Has spacy alignment
                    spacy_idx = token_to_spacy[i][0]
                    if spacy_idx < len(doc):
                        spacy_token = doc[spacy_idx]
                        # Content words: nouns, verbs, adjectives, adverbs
                        if spacy_token.pos_ in ['NOUN', 'VERB', 'ADJ', 'ADV', 'PROPN']:
                            is_content_word = True

                if is_content_word:
                    weight += 2.0  # Much higher attention for content words to first token
                else:
                    weight += 0.6  # Original weight for other tokens

            # Recency bias - closer tokens get higher attention
            else:
                distance = i - j
                if distance <= 3:
                    weight += 0.4 / (distance + 1)
                elif distance <= 10:
                    weight += 0.2 / (distance + 1)
                else:
                    weight += 0.1 / (distance + 1)

            # Small boost for punctuation
            if tokens[j] in [',', '!', '?', ';', ':']:
                weight += 0.3

            # Boost for tokens that are whitespace or contain whitespace
            if tokens[j].isspace() or '\n' in tokens[j]:
                weight += 1.0

            attention_matrix[i, j] = weight

    # Apply causal mask and normalize
    attention_matrix = apply_causal_mask(attention_matrix)
    attention_matrix = make_row_stochastic(attention_matrix)

    return "prog_L19H8", attention_matrix



def prog_L19H9(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Boundary marker attention head focusing on first tokens, newlines, and periods."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L19H9", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    for i in range(n):
        # Base uniform distribution over valid positions
        for j in range(i + 1):
            attention[i, j] = 0.01

        # Strong attention to first token
        if n > 0:
            attention[i, 0] += 0.4

        # Strong self-attention
        attention[i, i] += 0.3

        # High attention to newlines
        for j in range(i + 1):
            if tokens[j] == '\n':
                attention[i, j] += 0.25

        # Moderate attention to periods
        for j in range(i + 1):
            if tokens[j] == '.':
                attention[i, j] += 0.15

        # Attention to immediately previous token
        if i > 0:
            attention[i, i-1] += 0.1

        # Special boost for tokens right after newlines attending to the newline
        if i > 0 and tokens[i-1] == '\n':
            attention[i, i-1] += 0.2

    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L19H9", attention



def prog_L1H0(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Punctuation and structural marker attention sink head with content word similarity boost."""
    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L1H0", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        # Base attention distribution
        base_weights = np.zeros(i + 1)  # Can only attend to previous tokens + self

        # Strong attention to punctuation tokens (periods, empty strings, newlines)
        for j in range(i + 1):
            token_j = tokens[j].strip()

            # Very high attention to periods
            if token_j == '.':
                base_weights[j] += 2.0

            # High attention to empty strings (sentence boundaries)
            elif token_j == '':
                base_weights[j] += 1.5

            # High attention to newlines
            elif token_j == '\n':
                base_weights[j] += 1.2

            # Medium attention to other punctuation
            elif token_j in [',', '!', '?', '"', "'", '-']:
                base_weights[j] += 0.5

        # Self-attention boost
        base_weights[i] += 0.3

        # Local attention (previous token)
        if i > 0:
            base_weights[i-1] += 0.2

        # NEW: Content word similarity boost
        if i < len(token_to_spacy) and token_to_spacy[i]:
            # Check if current token is a content word
            spacy_indices = token_to_spacy[i]
            current_is_content = False
            for spacy_idx in spacy_indices:
                if spacy_idx < len(doc):
                    spacy_token = doc[spacy_idx]
                    if spacy_token.pos_ in ['NOUN', 'VERB', 'ADJ', 'ADV'] and not spacy_token.is_stop:
                        current_is_content = True
                        break

            if current_is_content:
                # Look for similar content words in previous positions
                for j in range(i):
                    if j < len(token_to_spacy) and token_to_spacy[j]:
                        spacy_indices_j = token_to_spacy[j]
                        target_is_content = False
                        for spacy_idx_j in spacy_indices_j:
                            if spacy_idx_j < len(doc):
                                spacy_token_j = doc[spacy_idx_j]
                                if spacy_token_j.pos_ in ['NOUN', 'VERB', 'ADJ', 'ADV'] and not spacy_token_j.is_stop:
                                    target_is_content = True
                                    break

                        if target_is_content:
                            # Check embedding similarity
                            similarity = _char_sim(tokens[i], tokens[j])
                            if similarity > 0.3:  # Threshold for semantic similarity
                                base_weights[j] += similarity * 1.0
                            # Also boost attention to immediately preceding content words
                            elif j == i - 1:
                                base_weights[j] += 0.4

        # Add some attention to content words if no strong punctuation
        if base_weights.sum() < 1.0:
            for j in range(i + 1):
                if j < len(token_to_spacy) and token_to_spacy[j]:
                    spacy_indices = token_to_spacy[j]
                    for spacy_idx in spacy_indices:
                        if spacy_idx < len(doc):
                            spacy_token = doc[spacy_idx]
                            # Attention to nouns, verbs, and adjectives
                            if spacy_token.pos_ in ['NOUN', 'VERB', 'ADJ']:
                                base_weights[j] += 0.1

        # Distance decay for very long sequences
        for j in range(i + 1):
            distance = i - j
            if distance > 5:
                base_weights[j] *= 0.8

        # Ensure minimum attention for immediate context
        if base_weights.sum() == 0:
            base_weights[i] = 1.0

        # Add small random component to break ties
        base_weights += np.random.uniform(0, 0.01, len(base_weights))

        attention[i, :i+1] = base_weights

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L1H0", attention



def prog_L1H1(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary attention head that focuses on periods and newlines as structural anchors."""
    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L1H1", np.zeros((n_empty, n_empty))

    attention_matrix = np.zeros((n, n))

    # Find periods and newlines
    periods = [i for i, token in enumerate(tokens) if token.strip() == '.']
    newlines = [i for i, token in enumerate(tokens) if token.strip() == '\n']

    for i in range(n):
        # Reduced self-attention to match real patterns better
        attention_matrix[i, i] = 0.05

        # Strong attention to periods, especially earlier ones
        for p_idx in periods:
            if p_idx <= i:
                # Distance decay for periods
                distance = i - p_idx + 1
                weight = 0.6 / (distance ** 0.5)
                attention_matrix[i, p_idx] += weight

        # Strong attention to newlines - this was missing in original
        for n_idx in newlines:
            if n_idx <= i:
                # Distance decay for newlines, similar strength to periods
                distance = i - n_idx + 1
                weight = 0.7 / (distance ** 0.5)
                attention_matrix[i, n_idx] += weight

        # Attention to semantically similar tokens
        for j in range(i):
            if j != i:
                similarity = _char_sim(tokens[i], tokens[j])
                if similarity > 0.7:
                    attention_matrix[i, j] += 0.3 * similarity
                elif similarity > 0.5:
                    attention_matrix[i, j] += 0.1 * similarity

        # Small recency bias - attend slightly more to recent tokens
        for j in range(max(0, i-5), i):
            attention_matrix[i, j] += 0.05 / (i - j + 1)

    # Apply causal mask and normalize
    attention_matrix = apply_causal_mask(attention_matrix)
    attention_matrix = make_row_stochastic(attention_matrix)

    return "prog_L1H1", attention_matrix



def prog_L1H10(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary and structural marker attention with syntactic components."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L1H10", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        # Base self-attention
        attention[i, i] = 0.1

        # Strong attention to punctuation and structural markers
        for j in range(i + 1):
            token = tokens[j].strip()

            # Very high attention to periods and newlines
            if token == '.':
                attention[i, j] += 0.4
            elif token == '\n':
                attention[i, j] += 0.3
            elif token in [',', '!', '?', ';', ':']:
                attention[i, j] += 0.15
            elif token.startswith('"') or token.endswith('"'):
                attention[i, j] += 0.1

        # Syntactic relationships using spacy
        if token_to_spacy[i]:
            spacy_idx = token_to_spacy[i][0]
            if spacy_idx < len(doc):
                spacy_token = doc[spacy_idx]

                # Attend to syntactic head
                if spacy_token.head != spacy_token:
                    head_token_indices = align_spacy_to_tokens(sentence)[spacy_token.head.i]
                    for head_idx in head_token_indices:
                        if head_idx <= i:
                            attention[i, head_idx] += 0.08

                # Special attention patterns for certain POS types
                if spacy_token.pos_ in ['NOUN', 'VERB']:
                    # Look for related tokens nearby
                    for j in range(max(0, i-5), i):
                        if token_to_spacy[j]:
                            other_spacy_idx = token_to_spacy[j][0]
                            if other_spacy_idx < len(doc):
                                other_token = doc[other_spacy_idx]
                                if other_token.pos_ in ['ADJ', 'DET', 'ADP']:
                                    attention[i, j] += 0.05

        # Distance-based decay with emphasis on sentence starts
        for j in range(i):
            distance = i - j
            # Exponential decay
            decay = np.exp(-distance / 8.0)
            attention[i, j] += decay * 0.02

            # Extra attention to tokens near sentence boundaries
            prev_tokens = tokens[max(0, j-2):j+3]
            if any(t.strip() in ['.', '\n', '!', '?'] for t in prev_tokens):
                attention[i, j] += 0.05

        # Special attention to first few tokens
        if i > 0:
            attention[i, 0] += 0.03
        if i > 1:
            attention[i, 1] += 0.02

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L1H10", attention



def prog_L1H11(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Period and newline attention head with sentence boundary focus."""
    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        # Perfect self-attention for first token
        if i == 0:
            attention[i, i] = 1.0
            continue

        # Find periods and newlines
        period_indices = []
        newline_indices = []
        for j in range(i + 1):
            if tokens[j].strip() in ['.', '!', '?']:
                period_indices.append(j)
            elif tokens[j] in ['\n', ' \n', '\n ']:
                newline_indices.append(j)

        # Base attention: very high to periods, high to newlines
        for j in range(i + 1):
            if j in period_indices:
                attention[i, j] = 0.5
            elif j in newline_indices:
                attention[i, j] = 0.3
            else:
                # Recency bias for other tokens
                distance = i - j
                attention[i, j] = 0.05 / (1 + distance * 0.5)

        # Boost attention to most recent period/newline
        if period_indices:
            most_recent_period = max(period_indices)
            attention[i, most_recent_period] *= 2.0
        if newline_indices:
            most_recent_newline = max(newline_indices)
            attention[i, most_recent_newline] *= 1.5

        # Local syntactic patterns
        if token_to_spacy[i]:
            spacy_token = doc[token_to_spacy[i][0]]

            # Prepositions attend more to their objects
            if spacy_token.pos_ == 'ADP':
                for j in range(max(0, i-3), i+1):
                    if token_to_spacy[j]:
                        target_spacy = doc[token_to_spacy[j][0]]
                        if target_spacy.pos_ in ['NOUN', 'PROPN'] and j < i:
                            attention[i, j] *= 2.0

            # Determiners and adjectives attend to nearby nouns
            if spacy_token.pos_ in ['DET', 'ADJ']:
                for j in range(max(0, i-2), i+1):
                    if token_to_spacy[j]:
                        target_spacy = doc[token_to_spacy[j][0]]
                        if target_spacy.pos_ in ['NOUN', 'PROPN']:
                            attention[i, j] *= 1.5

    return "prog_L1H11", make_row_stochastic(apply_causal_mask(attention))



def prog_L1H12(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary attention head - focuses on the first major sentence boundary (periods, newlines)."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L1H12", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Find sentence-ending punctuation and newlines
    boundary_tokens = []
    for i, token in enumerate(tokens):
        if token.strip() in ['.', '!', '?'] or '\n' in token:
            boundary_tokens.append(i)

    # Find the first period specifically
    first_period = None
    for i, token in enumerate(tokens):
        if token.strip() == '.':
            first_period = i
            break

    # Find the first significant newline (not immediately following punctuation)
    first_major_newline = None
    for i, token in enumerate(tokens):
        if '\n' in token:
            # Check if this newline is significant (not just after punctuation)
            if i == 0 or not (tokens[i-1].strip() in ['.', '!', '?']):
                first_major_newline = i
                break
            # Or if it's the first newline after some content
            elif i > 3:  # Allow newlines after some content to be significant
                first_major_newline = i
                break

    for i in range(n):
        # Base self-attention
        attention[i, i] = 0.1

        # Strong attention to sentence boundaries, especially first period and first major newline
        for boundary_idx in boundary_tokens:
            if boundary_idx <= i:
                if boundary_idx == first_period:
                    # Very strong attention to first period
                    attention[i, boundary_idx] = 0.6
                elif boundary_idx == first_major_newline and first_major_newline is not None:
                    # Very strong attention to first major newline
                    attention[i, boundary_idx] = 0.6
                elif tokens[boundary_idx].strip() == '.':
                    # Strong attention to other periods
                    attention[i, boundary_idx] = 0.4
                elif '\n' in tokens[boundary_idx]:
                    # Moderate attention to other newlines
                    attention[i, boundary_idx] = 0.3

        # Positional decay - slight preference for earlier tokens
        for j in range(i):
            if j not in boundary_tokens:
                distance = i - j
                decay_weight = max(0.02, 0.08 / (1 + 0.1 * distance))
                attention[i, j] += decay_weight

        # Small boost for tokens at start of sequence
        if i > 0:
            attention[i, 0] += 0.05

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L1H12", attention



def prog_L1H13(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Attention head that focuses on sentence boundaries, punctuation, and early tokens."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L1H13", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        # Strong self-attention for all tokens
        attention[i, i] = 0.3

        # High attention to punctuation marks, especially periods and newlines
        for j in range(i + 1):
            token_j = tokens[j].strip()

            # Very high attention to newlines and periods
            if token_j == '\n':
                attention[i, j] += 0.4
            elif token_j == '.':
                attention[i, j] += 0.3
            elif token_j in [',', '!', '?', '"', "'", ':', ';']:
                attention[i, j] += 0.15

        # Attention to early tokens in sequence (positional bias)
        for j in range(min(5, i + 1)):
            if j != i:  # Don't double-count self-attention
                attention[i, j] += 0.1 * (1.0 / (j + 1))

        # Special boost for first token
        if i > 0:
            attention[i, 0] += 0.2

        # Content word attention - higher attention to nouns, verbs, adjectives
        spacy_indices = token_to_spacy[i] if i < len(token_to_spacy) else []
        if spacy_indices:
            for spacy_idx in spacy_indices:
                if spacy_idx < len(doc):
                    spacy_token = doc[spacy_idx]
                    if spacy_token.pos_ in ['NOUN', 'VERB', 'ADJ']:
                        # Look for similar content words in previous positions
                        for j in range(i):
                            j_spacy_indices = token_to_spacy[j] if j < len(token_to_spacy) else []
                            if j_spacy_indices:
                                for j_spacy_idx in j_spacy_indices:
                                    if j_spacy_idx < len(doc):
                                        j_spacy_token = doc[j_spacy_idx]
                                        if j_spacy_token.pos_ in ['NOUN', 'VERB', 'ADJ']:
                                            sim = _char_sim(tokens[i], tokens[j])
                                            if sim > 0.3:
                                                attention[i, j] += 0.1 * sim

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L1H13", attention



def prog_L1H14(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Punctuation-focused attention head with recency bias and sentence boundary detection."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L1H14", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    for i in range(n):
        for j in range(i + 1):  # Causal mask
            weight = 0.0

            # Strong attention to period tokens
            if tokens[j] == '.':
                weight += 0.4

            # Strong attention to newline tokens
            elif tokens[j] == '\n':
                weight += 0.2

            # Self-attention
            elif i == j:
                weight += 0.1

            # Previous token attention (recency bias)
            elif j == i - 1:
                weight += 0.3

            # Two tokens back
            elif j == i - 2:
                weight += 0.15

            # General recency decay
            else:
                distance = i - j
                if distance > 0:
                    weight += 0.1 * np.exp(-0.1 * distance)

            # Boost for other punctuation
            if tokens[j] in [',', '!', '?', ':']:
                weight += 0.1

            # Small boost for sentence starters
            if j == 0:
                weight += 0.05

            # Small embedding similarity boost for non-punctuation tokens
            if j < i and tokens[j] not in ['.', '\n', ',', '!', '?', ':'] and tokens[i] not in ['.', '\n', ',', '!', '?', ':']:
                sim = _char_sim(tokens[i], tokens[j])
                if sim > 0.5:
                    weight += 0.1 * sim

            attention[i, j] = weight

    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L1H14", attention



def prog_L1H15(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Attention head focused on structural boundaries: newlines, sentence endings, and discourse markers."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L1H15", np.zeros((n_empty, n_empty))

    attention_matrix = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    # Identify sentence-ending periods for enhanced attention
    sentence_ending_periods = []
    for j in range(n):
        if tokens[j] == '.':
            # Check if this period is likely a sentence ending
            is_sentence_end = True
            if j + 1 < n and tokens[j + 1].strip() and not tokens[j + 1].strip().startswith('\n'):
                # If next non-whitespace token doesn't start new line, might not be sentence end
                spacy_indices = token_to_spacy[j + 1] if j + 1 < len(token_to_spacy) else []
                if spacy_indices:
                    next_spacy = doc[spacy_indices[0]]
                    if next_spacy.text.islower():  # lowercase suggests continuation
                        is_sentence_end = False
            if is_sentence_end:
                sentence_ending_periods.append(j)

    for i in range(n):
        # Reduced attention to whitespace/newlines (was 0.25, now 0.15)
        for j in range(i + 1):
            if tokens[j].strip() == '':  # newline or whitespace
                attention_matrix[i, j] += 0.15

        # Enhanced attention to sentence-ending punctuation
        for j in sentence_ending_periods:
            if j <= i:
                attention_matrix[i, j] += 0.30  # Increased from 0.20

        # Regular attention to other periods
        for j in range(i + 1):
            if tokens[j] == '.' and j not in sentence_ending_periods:
                attention_matrix[i, j] += 0.20

        # Moderate attention to first token
        if i > 0:
            attention_matrix[i, 0] += 0.05

        # Self-attention
        attention_matrix[i, i] += 0.03

        # Some attention to nearby tokens and syntactic relationships
        spacy_indices = token_to_spacy[i]
        if spacy_indices:
            spacy_token = doc[spacy_indices[0]]

            # Attend to syntactic head
            if spacy_token.head != spacy_token:
                head_token_idx = None
                for k in range(i + 1):
                    k_spacy = token_to_spacy[k]
                    if k_spacy and any(doc[idx] == spacy_token.head for idx in k_spacy):
                        head_token_idx = k
                        break
                if head_token_idx is not None:
                    attention_matrix[i, head_token_idx] += 0.02

        # Local attention to recent tokens
        for j in range(max(0, i-3), i):
            attention_matrix[i, j] += 0.01

        # Special attention patterns for certain punctuation
        for j in range(i + 1):
            if tokens[j] in [',', '!', '?']:
                attention_matrix[i, j] += 0.03

    # Apply causal mask and normalize
    attention_matrix = apply_causal_mask(attention_matrix)
    attention_matrix = make_row_stochastic(attention_matrix)

    return "prog_L1H15", attention_matrix



def prog_L1H16(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary and local dependency attention head."""
    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L1H16", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        # Self-attention baseline
        attention[i, i] = 0.1

        # Strong attention to sentence boundaries (periods, newlines)
        for j in range(i + 1):
            if tokens[j] in ['.', '\n']:
                attention[i, j] += 0.4

        # Very strong attention to immediately preceding token
        if i > 0:
            attention[i, i-1] += 0.3

            # Extra boost for certain patterns
            current_spacy = token_to_spacy[i]
            prev_spacy = token_to_spacy[i-1]

            if current_spacy and prev_spacy:
                curr_spacy_tok = doc[current_spacy[0]] if current_spacy else None
                prev_spacy_tok = doc[prev_spacy[0]] if prev_spacy else None

                # Boost for verb-adverb, adjective-noun, etc.
                if (curr_spacy_tok and prev_spacy_tok and
                    ((curr_spacy_tok.pos_ in ['VERB', 'AUX'] and prev_spacy_tok.pos_ == 'ADV') or
                     (curr_spacy_tok.pos_ == 'NOUN' and prev_spacy_tok.pos_ == 'ADJ') or
                     (curr_spacy_tok.pos_ in ['VERB', 'AUX'] and prev_spacy_tok.pos_ in ['VERB', 'AUX']))):
                    attention[i, i-1] += 0.2

        # Attention to first token
        if i > 0:
            attention[i, 0] += 0.05

        # Attention to commas and other punctuation
        for j in range(i + 1):
            if tokens[j] in [',', ';', ':', '-', '"', "'", '?', '!']:
                attention[i, j] += 0.08

        # Boost attention between semantically similar tokens
        for j in range(i):
            sim = _char_sim(tokens[i], tokens[j])
            if sim > 0.7:
                attention[i, j] += 0.1

        # Recency bias - closer tokens get slightly more attention
        for j in range(max(0, i-5), i):
            distance = i - j
            if distance <= 3:
                attention[i, j] += 0.02 * (4 - distance) / 4

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L1H16", attention



def prog_L1H17(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary and punctuation-focused attention head."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention_matrix = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    # Find periods and newlines
    periods = []
    newlines = []
    for i, token in enumerate(tokens):
        if token.strip() == '.':
            periods.append(i)
        elif token.strip() == '\n':
            newlines.append(i)

    for i in range(n):
        # Base self-attention
        attention_matrix[i, i] = 0.1

        # Strong attention to periods from most tokens
        for period_idx in periods:
            if period_idx <= i:
                # Distance decay from period
                distance = i - period_idx
                if distance == 0:
                    attention_matrix[i, period_idx] = 0.3
                elif distance <= 5:
                    attention_matrix[i, period_idx] = 0.4 - 0.05 * distance
                else:
                    attention_matrix[i, period_idx] = 0.15

        # First token in sentence attending to newlines
        is_sentence_start = False
        if token_to_spacy[i]:
            spacy_idx = token_to_spacy[i][0]
            if spacy_idx < len(doc):
                spacy_token = doc[spacy_idx]
                # Check if this is start of sentence
                if spacy_token.is_sent_start or (spacy_idx == 0):
                    is_sentence_start = True

        if is_sentence_start:
            for newline_idx in newlines:
                if newline_idx <= i:
                    attention_matrix[i, newline_idx] = 0.5

        # Attention to newlines from various tokens
        for newline_idx in newlines:
            if newline_idx <= i and newline_idx != i:
                distance = i - newline_idx
                if distance <= 3:
                    attention_matrix[i, newline_idx] += 0.1

        # Linguistic patterns - pronouns to nearby nouns
        if token_to_spacy[i]:
            spacy_idx = token_to_spacy[i][0]
            if spacy_idx < len(doc):
                current_token = doc[spacy_idx]
                if current_token.pos_ == 'PRON':
                    # Look for nearby nouns
                    for j in range(max(0, i-10), i):
                        if token_to_spacy[j]:
                            target_spacy_idx = token_to_spacy[j][0]
                            if target_spacy_idx < len(doc):
                                target_token = doc[target_spacy_idx]
                                if target_token.pos_ in ['NOUN', 'PROPN']:
                                    attention_matrix[i, j] += 0.15

        # Attention to previous token
        if i > 0:
            attention_matrix[i, i-1] += 0.1

        # Semantic similarity bonus
        for j in range(i):
            sim = _char_sim(tokens[i], tokens[j])
            if sim > 0.7:
                attention_matrix[i, j] += 0.1 * sim

    # Apply causal mask and normalize
    attention_matrix = apply_causal_mask(attention_matrix)
    attention_matrix = make_row_stochastic(attention_matrix)

    return "prog_L1H17", attention_matrix



def prog_L1H18(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary and structural marker attention head."""
    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L1H18", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    # Identify structural tokens (periods, newlines, etc.)
    structural_tokens = set()
    for i, token in enumerate(tokens):
        if token.strip() in ['.', '\n', '!', '?']:
            structural_tokens.add(i)

    for i in range(n):
        # Base self-attention
        attention[i, i] = 0.1

        # Strong attention to structural markers (periods, newlines)
        for j in structural_tokens:
            if j <= i:
                attention[i, j] = 0.5

        # Adjacent token attention for certain patterns
        if i > 0:
            # Check if this could be a word continuation or compound
            if _char_sim(tokens[i], tokens[i-1]) > 0.7:
                attention[i, i-1] = 0.3

        # Attention to first token in sequence
        if i > 0:
            attention[i, 0] = 0.1

        # Special attention patterns for tokens near sentence boundaries
        spacy_indices = token_to_spacy[i]
        if spacy_indices:
            spacy_token = doc[spacy_indices[0]]
            # Verbs and nouns tend to attend more to structural markers
            if spacy_token.pos_ in ['VERB', 'NOUN']:
                for j in structural_tokens:
                    if j <= i:
                        attention[i, j] *= 1.5

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L1H18", attention



def prog_L1H19(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary attention head with syntactic components."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        token_i = tokens[i]

        # Strong attention to newlines and periods (sentence boundaries)
        for j in range(i + 1):
            token_j = tokens[j]

            # Very high attention to newlines and periods
            if token_j in ['\n', '.']:
                attention[i, j] = 1.0

            # Self-attention baseline
            elif i == j:
                attention[i, j] = 0.1

            # Attention to first token
            elif j == 0:
                attention[i, j] = 0.3

            # Adjacent token attention (especially previous token)
            elif j == i - 1:
                attention[i, j] = 0.5

                # Higher if previous token is syntactically related
                if token_to_spacy[i] and token_to_spacy[j]:
                    spacy_i = doc[token_to_spacy[i][0]]
                    spacy_j = doc[token_to_spacy[j][0]]

                    # Higher attention for head-dependent relationships
                    if spacy_j.head == spacy_i or spacy_i.head == spacy_j:
                        attention[i, j] *= 1.5

                    # Higher attention for similar parts of speech
                    if spacy_i.pos_ == spacy_j.pos_ and spacy_i.pos_ in ['NOUN', 'VERB', 'ADJ']:
                        attention[i, j] *= 1.2

            # Moderate attention to commas and other punctuation
            elif token_j in [',', ':', ';', '!', '?']:
                attention[i, j] = 0.2

            # Semantic similarity component
            else:
                sim = _char_sim(tokens[i], tokens[j])
                if sim > 0.5:
                    attention[i, j] = 0.3 * sim
                else:
                    attention[i, j] = 0.05

        # Boost attention for tokens that are part of the same sentence/clause
        if token_to_spacy[i]:
            spacy_token_i = doc[token_to_spacy[i][0]]
            for j in range(i):
                if token_to_spacy[j]:
                    spacy_token_j = doc[token_to_spacy[j][0]]

                    # Same sentence component
                    if spacy_token_i.sent == spacy_token_j.sent:
                        attention[i, j] *= 1.1

    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L1H19", attention



def prog_L1H2(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Attention head that focuses on sentence boundaries (periods, newlines) and structural punctuation."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L1H2", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Find periods and newlines
    periods = [i for i, token in enumerate(tokens) if token.strip() == '.']
    newlines = [i for i, token in enumerate(tokens) if token.strip() == '\n']

    for i in range(n):
        token = tokens[i].strip()

        # Self-attention baseline
        attention[i, i] = 0.1

        # Strong attention to periods from most tokens
        for period_idx in periods:
            if period_idx <= i:  # causal constraint
                # Distance-based decay for period attention
                distance = i - period_idx
                if distance == 0:
                    attention[i, period_idx] += 0.4
                elif distance <= 5:
                    attention[i, period_idx] += 0.6 / (1 + distance * 0.3)
                else:
                    attention[i, period_idx] += 0.3 / (1 + distance * 0.1)

        # Strong attention to newlines from many tokens
        for newline_idx in newlines:
            if newline_idx <= i:  # causal constraint
                distance = i - newline_idx
                if distance == 0:
                    attention[i, newline_idx] += 0.3
                elif distance <= 10:
                    attention[i, newline_idx] += 0.4 / (1 + distance * 0.2)
                else:
                    attention[i, newline_idx] += 0.2 / (1 + distance * 0.1)

        # Attention to first token (position 0)
        if i > 0:
            attention[i, 0] += 0.1

        # Boost attention for certain punctuation and structural elements
        for j in range(i + 1):
            target_token = tokens[j].strip()

            # Additional attention to commas, quotes, and other punctuation
            if target_token in [',', '"', "'", ':', ';']:
                distance = i - j
                attention[i, j] += 0.2 / (1 + distance * 0.2)

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L1H2", attention



def prog_L1H20(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary and paragraph structure attention head."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    # Find sentence boundaries and newlines
    sentence_ends = []
    newlines = []

    for i, token in enumerate(tokens):
        if token.strip() == '.':
            sentence_ends.append(i)
        elif token.strip() == '\n' or token == '\n':
            newlines.append(i)

    # Add first token as special position
    first_token_pos = 0

    for i in range(n):
        token = tokens[i].strip()

        # Self-attention for first token
        if i == 0:
            attention[i, i] = 1.0
            continue

        # Strong attention to sentence endings and newlines
        for end_pos in sentence_ends:
            if end_pos <= i:
                attention[i, end_pos] = 0.5

        for nl_pos in newlines:
            if nl_pos <= i:
                attention[i, nl_pos] = 0.6

        # Attention to first token
        attention[i, first_token_pos] = 0.2

        # Self-attention
        attention[i, i] = 0.1

        # Higher weights for recent sentence boundaries
        if sentence_ends:
            most_recent_end = max([pos for pos in sentence_ends if pos <= i], default=-1)
            if most_recent_end >= 0:
                attention[i, most_recent_end] *= 1.5

        if newlines:
            most_recent_nl = max([pos for pos in newlines if pos <= i], default=-1)
            if most_recent_nl >= 0:
                attention[i, most_recent_nl] *= 1.2

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L1H20", attention



def prog_L1H21(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Punctuation and sentence boundary attention head."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L1H21", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        token = tokens[i].strip()

        # Strong base attention to punctuation marks
        for j in range(i + 1):
            target_token = tokens[j].strip()

            # High attention to periods, especially sentence-ending ones
            if target_token in ['.', '!', '?']:
                attention[i, j] += 0.4

            # High attention to newlines (sentence/paragraph breaks)
            elif target_token == '\n':
                attention[i, j] += 0.35

            # Moderate attention to commas
            elif target_token == ',':
                attention[i, j] += 0.25

            # Self-attention baseline
            elif i == j:
                attention[i, j] += 0.05

            # Distance decay for other tokens
            else:
                distance = i - j + 1
                attention[i, j] += 0.02 / distance

        # Boost attention based on token properties
        if token_to_spacy[i]:
            spacy_idx = token_to_spacy[i][0]
            if spacy_idx < len(doc):
                spacy_token = doc[spacy_idx]

                # Verbs attend more strongly to sentence boundaries
                if spacy_token.pos_ in ['VERB', 'AUX']:
                    for j in range(i + 1):
                        target_token = tokens[j].strip()
                        if target_token in ['.', '\n', '!', '?']:
                            attention[i, j] *= 1.3

                # Nouns also attend to punctuation
                elif spacy_token.pos_ == 'NOUN':
                    for j in range(i + 1):
                        target_token = tokens[j].strip()
                        if target_token in ['.', '\n', ',']:
                            attention[i, j] *= 1.2

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L1H21", attention



def prog_L1H22(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Punctuation-focused attention head that primarily attends to periods and newlines."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        for j in range(i + 1):  # Causal mask
            weight = 0.0

            # Very high attention to periods
            if tokens[j].strip() == '.':
                weight += 0.6

            # High attention to newlines
            elif tokens[j].strip() == '\n':
                weight += 0.4

            # Medium attention to commas
            elif tokens[j].strip() == ',':
                weight += 0.15

            # Self-attention gets a boost
            elif i == j:
                weight += 0.2

            # Attention to first token
            elif j == 0:
                weight += 0.05

            # Semantic similarity boost
            else:
                sim = _char_sim(tokens[i], tokens[j])
                if sim > 0.7:
                    weight += 0.1 * sim
                elif sim > 0.5:
                    weight += 0.05 * sim

            # Positional decay for non-punctuation
            if tokens[j].strip() not in ['.', '\n', ',']:
                distance = i - j
                if distance > 0:
                    weight *= (0.9 ** distance)

            # Base attention for all valid positions
            weight += 0.01

            attention[i, j] = weight

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L1H22", attention



def prog_L1H23(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Structural anchor attention with semantic relationship enhancement."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L1H23", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    for i in range(n):
        # High attention to periods and newlines (structural markers)
        for j in range(i + 1):
            token_j = tokens[j].strip()

            # Very high attention to periods and newlines
            if token_j == '.' or token_j == '\n':
                attention[i, j] = 0.5

            # Strong positional bias - higher attention to earlier positions
            position_weight = 0.3 * (1.0 / (j + 1))
            attention[i, j] += position_weight

            # Moderate self-attention
            if i == j:
                attention[i, j] += 0.1

            # Local attention (previous few tokens)
            if i - j <= 3 and i != j:
                attention[i, j] += 0.05

    # Add semantic relationship enhancement
    for i in range(n):
        for j in range(i):
            # Check for high semantic similarity
            sim = _char_sim(tokens[i], tokens[j])
            if sim > 0.5:  # Strong semantic relationship
                # Boost attention proportional to similarity, with distance decay
                distance_factor = 1.0 / (i - j + 1)
                boost = 0.4 * sim * distance_factor
                attention[i, j] += boost

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L1H23", attention



def prog_L1H24(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary attention: tokens attend primarily to sentence-ending periods, newlines, and newline-containing tokens."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    # Find sentence boundaries (periods followed by space/newline or at end)
    sentence_boundaries = []
    newlines = []

    for i, token in enumerate(tokens):
        if token.strip() == '.':
            # Check if this is likely a sentence-ending period
            if i == n-1 or (i < n-1 and (tokens[i+1].startswith(' ') or tokens[i+1].strip() in ['\n', '\n '])):
                sentence_boundaries.append(i)
        elif token.strip() in ['\n', '\n ']:
            newlines.append(i)
        # NEW: Also detect tokens containing newline characters
        elif '\n' in token:
            newlines.append(i)

    for i in range(n):
        token = tokens[i].strip()

        # Strong attention to sentence-ending periods
        for boundary_idx in sentence_boundaries:
            if boundary_idx <= i:  # causal constraint
                # Distance decay but strong base attention
                distance = i - boundary_idx
                if distance == 0:
                    attention[i, boundary_idx] = 0.3  # self-attention to period
                elif distance <= 5:
                    attention[i, boundary_idx] = 0.8 - 0.1 * distance
                else:
                    attention[i, boundary_idx] = 0.3 - 0.02 * distance

        # Strong attention to newlines and newline-containing tokens
        for newline_idx in newlines:
            if newline_idx <= i:  # causal constraint
                distance = i - newline_idx
                if distance == 0:
                    attention[i, newline_idx] = 0.2
                elif distance <= 8:
                    attention[i, newline_idx] = 0.4 - 0.03 * distance
                else:
                    attention[i, newline_idx] = 0.15

        # Some attention to immediately preceding token
        if i > 0:
            prev_token = tokens[i-1].strip()
            if prev_token not in ['.', '\n', '\n '] and '\n' not in prev_token:
                attention[i, i-1] = 0.15
            elif prev_token == ',':
                attention[i, i-1] = 0.25

        # Self-attention baseline
        attention[i, i] = 0.05

        # Some attention to commas
        for j in range(i+1):
            if tokens[j].strip() == ',':
                distance = i - j
                if distance <= 3:
                    attention[i, j] = 0.1 - 0.02 * distance

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L1H24", attention



def prog_L1H25(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary attention head that focuses on punctuation and early structural tokens, with distant early punctuation attention."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L1H25", np.zeros((n_empty, n_empty))

    attention_matrix = np.zeros((n, n))

    # Identify punctuation and structural tokens
    punct_tokens = set()
    newline_tokens = set()
    for i, token in enumerate(tokens):
        if token.strip() in '.!?;:,':
            punct_tokens.add(i)
        elif token.strip() == '' or '\n' in token:
            newline_tokens.add(i)

    # Identify early sentence boundary markers (periods/newlines in first ~10 positions)
    early_boundaries = set()
    for i in range(min(n, 10)):
        if i in punct_tokens and tokens[i].strip() in '.!?':
            early_boundaries.add(i)
        elif i in newline_tokens:
            early_boundaries.add(i)

    for i in range(n):
        # Strong self-attention for first token
        if i == 0:
            attention_matrix[i, i] = 1.0
        else:
            # High attention to early punctuation (positions 1-4)
            for j in range(min(i + 1, 5)):
                if j in punct_tokens or j in newline_tokens:
                    attention_matrix[i, j] = 0.6

            # Moderate attention to other punctuation and newlines
            for j in range(i + 1):
                if j in punct_tokens:
                    attention_matrix[i, j] += 0.3
                elif j in newline_tokens:
                    attention_matrix[i, j] += 0.4

            # Strong distant attention to early sentence boundaries for later tokens
            if i > 15:  # Only for tokens well into the sequence
                for j in early_boundaries:
                    if j <= i:  # Respect causal mask
                        attention_matrix[i, j] += 0.4

            # Small attention to recent tokens
            for j in range(max(0, i - 3), i + 1):
                if j not in punct_tokens and j not in newline_tokens:
                    attention_matrix[i, j] += 0.1

            # Self-attention boost
            attention_matrix[i, i] += 0.2

    attention_matrix = apply_causal_mask(attention_matrix)
    attention_matrix = make_row_stochastic(attention_matrix)

    return "prog_L1H25", attention_matrix



def prog_L1H26(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary and punctuation attention head that focuses on periods, newlines, and commas with special global attention to early newlines."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L1H26", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    for i in range(n):
        for j in range(i + 1):  # Only attend to previous/current tokens
            weight = 0.0

            # Very strong attention to periods
            if tokens[j].strip() == '.':
                weight += 0.5

            # Strong attention to newlines
            elif tokens[j].strip() == '\n' or tokens[j] == '\n':
                weight += 0.3

            # Moderate attention to commas
            elif tokens[j].strip() == ',':
                weight += 0.15

            # Self-attention baseline
            if i == j:
                weight += 0.05

            # Distance-based decay for non-punctuation
            if tokens[j] not in ['.', '\n', ','] and tokens[j].strip() not in ['.', '\n', ',']:
                distance = i - j
                if distance == 0:  # self
                    weight += 0.02
                elif distance == 1:  # previous token
                    weight += 0.015
                else:
                    weight += 0.01 / (distance + 1)

            # Boost for tokens near sentence boundaries
            if i > 0 and tokens[i-1].strip() == '.':
                if tokens[j].strip() == '.' or tokens[j] == '\n' or tokens[j].strip() == '\n':
                    weight += 0.2

            # NEW: Special global attention to early newlines
            if tokens[j].strip() == '\n' or tokens[j] == '\n':
                # Early newlines (first 20% of sequence) get strong global attention
                if j <= n * 0.2:
                    # Strong boost that decays slowly with distance from the newline
                    distance_from_newline = i - j
                    if distance_from_newline > 10:  # Only for distant tokens
                        weight += 0.4 / (1 + distance_from_newline * 0.1)

            attention[i, j] = weight

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L1H26", attention



def prog_L1H27(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary attention head - tokens attend to structural boundaries like newlines and periods."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    # Find boundary tokens (newlines and periods)
    boundary_indices = []
    for i, token in enumerate(tokens):
        if token.strip() in ['\n', '.', '."', '."']:
            boundary_indices.append(i)

    # Special case: also treat standalone newline tokens as boundaries
    for i, token in enumerate(tokens):
        if token == '\n':
            if i not in boundary_indices:
                boundary_indices.append(i)

    for i in range(n):
        current_token = tokens[i]

        # Self-attention baseline
        attention[i, i] = 0.1

        # Strong attention to boundary tokens
        for boundary_idx in boundary_indices:
            if boundary_idx <= i:  # Causal constraint
                # Distance decay for boundaries
                distance = i - boundary_idx
                if distance == 0:
                    attention[i, boundary_idx] += 0.8
                elif distance <= 3:
                    attention[i, boundary_idx] += 0.6
                elif distance <= 10:
                    attention[i, boundary_idx] += 0.4
                else:
                    attention[i, boundary_idx] += 0.2

        # Special case: if current token is a boundary, attend more to previous boundaries
        if current_token.strip() in ['\n', '.', '."', '."'] or current_token == '\n':
            for boundary_idx in boundary_indices:
                if boundary_idx < i:
                    attention[i, boundary_idx] += 0.3

        # Local attention to recent tokens
        for j in range(max(0, i-5), i):
            if j not in boundary_indices:
                attention[i, j] += 0.05

        # Attention to first token
        if i > 0:
            attention[i, 0] += 0.1

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L1H27", attention



def prog_L1H28(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary attention head - attends to periods, newlines, and sentence delimiters."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention_matrix = np.zeros((n, n))

    # Find sentence boundary markers - check both stripped and original tokens
    boundary_indices = []
    for i, token in enumerate(tokens):
        # Check stripped token for most punctuation
        if token.strip() in ['.', '!', '?']:
            boundary_indices.append(i)
        # Check original token for newlines (since strip() removes them)
        elif token in ['\n']:
            boundary_indices.append(i)

    for i in range(n):
        # Strong attention to sentence boundary markers
        for boundary_idx in boundary_indices:
            if boundary_idx <= i:  # Causal constraint
                # Distance-based decay for boundaries
                distance = i - boundary_idx
                if distance == 0:
                    weight = 0.8  # Strong self-attention for boundaries
                elif distance <= 5:
                    weight = 0.6 - 0.08 * distance
                elif distance <= 15:
                    weight = 0.3 - 0.015 * distance
                else:
                    weight = 0.05
                attention_matrix[i, boundary_idx] = max(weight, 0.05)

        # Moderate attention to commas and other punctuation
        for j in range(i + 1):
            if tokens[j].strip() in [',', ':', ';']:
                distance = i - j
                if distance <= 10:
                    weight = 0.15 - 0.01 * distance
                    attention_matrix[i, j] = max(weight, 0.02)

        # Self-attention
        attention_matrix[i, i] += 0.3

        # Small attention to recent tokens for context
        for j in range(max(0, i - 3), i):
            if attention_matrix[i, j] == 0:  # Don't overwrite existing weights
                attention_matrix[i, j] = 0.05

    # Apply causal mask and normalize
    attention_matrix = apply_causal_mask(attention_matrix)
    attention_matrix = make_row_stochastic(attention_matrix)

    return "prog_L1H28", attention_matrix



def prog_L1H29(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Structural punctuation attention with local syntactic dependencies."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L1H29", np.zeros((n_empty, n_empty)).reshape(0, 0)

    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        # Strong attention to punctuation marks, especially periods and newlines
        for j in range(i + 1):
            token_j = tokens[j].strip()

            # Very high attention to periods and newlines
            if token_j == '.':
                attention[i, j] = 3.0
            elif token_j == '\n':
                attention[i, j] = 2.0
            # Medium attention to other punctuation
            elif token_j in [',', '!', '?', ';', ':']:
                attention[i, j] = 1.5

        # Self-attention
        attention[i, i] += 0.5

        # Local syntactic dependencies
        if token_to_spacy[i]:
            spacy_i = doc[token_to_spacy[i][0]]

            # Attend to syntactic head
            if spacy_i.head != spacy_i:
                head_token_idx = None
                for j in range(i + 1):
                    if token_to_spacy[j] and spacy_i.head in [doc[idx] for idx in token_to_spacy[j]]:
                        head_token_idx = j
                        break
                if head_token_idx is not None:
                    attention[i, head_token_idx] += 1.0

            # Attend to children for certain relations
            for child in spacy_i.children:
                if child.dep_ in ['amod', 'compound', 'prt']:
                    child_token_idx = None
                    for j in range(i + 1):
                        if token_to_spacy[j] and child in [doc[idx] for idx in token_to_spacy[j]]:
                            child_token_idx = j
                            break
                    if child_token_idx is not None:
                        attention[i, child_token_idx] += 0.8

        # Attention to previous token with decay
        if i > 0:
            attention[i, i-1] += 0.3

        # Slight attention to first token
        if i > 0:
            attention[i, 0] += 0.2

        # Boost attention based on embedding similarity for nearby tokens
        for j in range(max(0, i-3), i):
            sim = _char_sim(tokens[i], tokens[j])
            if sim > 0.7:
                attention[i, j] += 0.5 * sim

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L1H29", attention



def prog_L1H3(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Boundary punctuation attention head - focuses on periods and newlines as sentence delimiters."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L1H3", np.zeros((n_empty, n_empty))

    attention_matrix = np.zeros((n, n))

    for i in range(n):
        # Find boundary punctuation tokens (periods and newlines)
        boundary_indices = []
        for j in range(i + 1):  # Causal constraint
            if tokens[j] in ['.', '\n']:
                boundary_indices.append(j)

        if boundary_indices:
            # Strong attention to boundary punctuation
            for j in boundary_indices:
                if tokens[j] == '.':
                    attention_matrix[i, j] = 0.7  # High weight for periods
                elif tokens[j] == '\n':
                    attention_matrix[i, j] = 0.4  # Medium weight for newlines

        # Add moderate attention to recent tokens (recency bias)
        recent_start = max(0, i - 3)
        for j in range(recent_start, i):
            if tokens[j] not in ['.', '\n']:
                attention_matrix[i, j] = 0.1

        # Self-attention
        attention_matrix[i, i] = 0.2

        # If no boundary punctuation found, distribute attention more broadly
        if not boundary_indices:
            # Attend to first token if available
            if i >= 0:
                attention_matrix[i, 0] = 0.5

            # Add attention to nearby tokens
            for j in range(max(0, i - 2), i):
                attention_matrix[i, j] += 0.2

    # Apply causal mask and normalize
    attention_matrix = apply_causal_mask(attention_matrix)
    attention_matrix = make_row_stochastic(attention_matrix)

    return "prog_L1H3", attention_matrix



def prog_L1H30(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary attention head - focuses on periods and newlines as sentence delimiters."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention_matrix = np.zeros((n, n))

    # Find periods and newlines
    period_indices = [i for i, token in enumerate(tokens) if token.strip() == '.']
    newline_indices = [i for i, token in enumerate(tokens) if token.strip() == '\n']

    for i in range(n):
        # Initialize with small uniform attention
        for j in range(i + 1):
            attention_matrix[i, j] = 0.01

        # Strong attention to periods
        for period_idx in period_indices:
            if period_idx <= i:
                attention_matrix[i, period_idx] = 0.55

        # Secondary attention to newlines  
        for newline_idx in newline_indices:
            if newline_idx <= i:
                attention_matrix[i, newline_idx] = 0.38

        # Self-attention for certain tokens
        if tokens[i].strip() in ['s', 'enough', 'for']:
            attention_matrix[i, i] = max(0.6, attention_matrix[i, i])

        # Special pattern for some tokens attending to previous tokens
        if i > 0:
            # Check for specific patterns like "stay" -> "and", "grow" -> "to"
            doc = spacy_parse(sentence)
            token_to_spacy = _align_to_spacy(sentence, tokens)

            if token_to_spacy[i] and token_to_spacy[i-1]:
                spacy_token = doc[token_to_spacy[i][0]]
                prev_spacy_token = doc[token_to_spacy[i-1][0]]

                # If current token is a verb and previous is a preposition/conjunction
                if (spacy_token.pos_ == 'VERB' and 
                    prev_spacy_token.pos_ in ['ADP', 'CCONJ']):
                    attention_matrix[i, i-1] = 0.6

        # Boost attention to first token for some cases
        if i > 0:
            attention_matrix[i, 0] = min(0.08, attention_matrix[i, 0])

    # Apply causal mask and normalize
    attention_matrix = apply_causal_mask(attention_matrix)
    attention_matrix = make_row_stochastic(attention_matrix)

    return "prog_L1H30", attention_matrix



def prog_L1H31(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Punctuation-focused attention head with long-range sentence boundary attention and moderate self-attention."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L1H31", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        query_token = tokens[i]

        # Find spacy tokens that align with current token
        spacy_indices = token_to_spacy[i] if i < len(token_to_spacy) else []

        for j in range(i + 1):  # Only attend to previous tokens and self
            key_token = tokens[j]

            # Strong attention to punctuation marks, especially periods and newlines
            if key_token in ['.', '\n']:
                attention[i, j] = 0.8
            elif key_token in [',', '!', '?', ';', ':']:
                attention[i, j] = 0.3

            # Self-attention boost (reduced from original)
            if i == j:
                attention[i, j] += 0.25

            # Special attention to apostrophes and quotes
            elif key_token in ["'", '"', "'", "'", """, """, "`"]:
                attention[i, j] = 0.3

            # Moderate attention to function words and common tokens
            elif len(spacy_indices) > 0:
                # Get spacy token properties if available
                spacy_token = doc[spacy_indices[0]] if spacy_indices[0] < len(doc) else None
                if spacy_token and spacy_token.pos_ in ['DET', 'PRON', 'ADP', 'CONJ', 'SCONJ']:
                    attention[i, j] += 0.1

            # Distance decay for non-punctuation tokens (preserve original logic)
            distance = i - j
            if distance > 0 and key_token not in ['.', '\n', ',']:
                decay_factor = 1.0 / (1.0 + 0.3 * distance)
                attention[i, j] *= decay_factor

            # Long-range sentence boundary attention - special case for periods/newlines
            # This overrides distance decay for sentence boundaries
            if key_token in ['.', '\n'] and distance > 5:
                attention[i, j] = max(attention[i, j], 0.4)

            # Small baseline attention
            if attention[i, j] == 0:
                attention[i, j] = 0.02

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L1H31", attention



def prog_L1H4(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Punctuation and morphological boundary attention with compound word detection."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L1H4", np.zeros((n_empty, n_empty))

    attention_matrix = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        for j in range(i + 1):  # Only attend to previous tokens (causal)
            weight = 0.0

            # Base recency bias - closer tokens get higher attention
            if i == j:
                weight += 0.1  # Self-attention baseline
            else:
                distance = i - j
                weight += 0.05 / (distance + 1)  # Inverse distance

            # Strong attention to punctuation, especially periods and newlines
            if tokens[j] in ['.', '\n', '?', '!', ',']:
                if tokens[j] in ['.', '\n']:
                    weight += 0.6  # Very strong for periods and newlines
                else:
                    weight += 0.3

                # Extra boost for attending to punctuation from far away
                if i - j > 3:
                    weight += 0.2

            # Adjacent token morphological coherence
            if i == j + 1:
                # Check if tokens might be parts of the same word
                combined = tokens[j] + tokens[i]
                # Look for common morphological patterns
                if (len(tokens[j]) >= 2 and len(tokens[i]) >= 2 and 
                    any(tokens[i].endswith(suffix) for suffix in ['ful', 'ing', 'ed', 'er', 'ly', 'tion']) or
                    any(tokens[j].endswith(prefix) for prefix in ['un', 'pre', 're', 'de']) or
                    _char_sim(tokens[i], tokens[j]) > 0.7):
                    weight += 0.5

            # NEW: Detect compound word boundaries - later parts attend to word beginnings
            if i != j and i - j <= 5:  # Look back up to 5 tokens
                # Check if current token might be a continuation of a word started at token j
                combined_text = ''.join(tokens[j:i+1])

                # Use spacy to check if the combined text forms a single word/token
                if j < len(token_to_spacy) and token_to_spacy[j] and i < len(token_to_spacy) and token_to_spacy[i]:
                    spacy_j = token_to_spacy[j]
                    spacy_i = token_to_spacy[i]

                    # If both tokens map to the same spacy token, they're part of the same word
                    if len(set(spacy_j) & set(spacy_i)) > 0:
                        weight += 0.6  # Strong compound word attention

                # Fallback: high embedding similarity suggests word parts
                elif _char_sim(tokens[i], tokens[j]) > 0.85:
                    # Additional check: combined tokens should look like a plausible word
                    if (len(combined_text) >= 3 and 
                        not any(c in combined_text for c in [' ', '.', ',', '!', '?']) and
                        combined_text.isalpha()):
                        weight += 0.5

            # Boost attention between semantically similar tokens
            if i != j:
                sim = _char_sim(tokens[i], tokens[j])
                if sim > 0.8:
                    weight += 0.3
                elif sim > 0.6:
                    weight += 0.1

            # Special attention to sentence/clause beginnings
            if j < 5:  # Early tokens get extra attention
                weight += 0.1

            # Use spacy features if available
            if j < len(token_to_spacy) and token_to_spacy[j]:
                spacy_idx = token_to_spacy[j][0]
                if spacy_idx < len(doc):
                    spacy_token = doc[spacy_idx]

                    # Boost attention to function words and determiners
                    if spacy_token.pos_ in ['DET', 'ADP', 'CONJ', 'SCONJ']:
                        weight += 0.1

                    # Boost attention to proper nouns and beginnings
                    if spacy_token.pos_ == 'PROPN' or spacy_token.is_title:
                        weight += 0.15

            attention_matrix[i, j] = weight

    # Apply causal mask and normalize
    attention_matrix = apply_causal_mask(attention_matrix)
    attention_matrix = make_row_stochastic(attention_matrix)

    return "prog_L1H4", attention_matrix



def prog_L1H5(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary detection head - attends to periods, newlines, and first tokens."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L1H5", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Find sentence-ending punctuation and structural tokens
    for i in range(n):
        for j in range(i + 1):  # Causal mask
            weight = 0.0

            # Strong attention to periods
            if tokens[j] in ['.', '."', '.\n']:
                weight += 0.6

            # Medium attention to newlines
            elif tokens[j] == '\n' or tokens[j].strip() == '':
                weight += 0.3

            # Attention to first token
            elif j == 0:
                weight += 0.1

            # Small self-attention
            elif i == j:
                weight += 0.05

            # Small attention to commas
            elif tokens[j] in [',', ',"']:
                weight += 0.05

            attention[i, j] = weight

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L1H5", attention



def prog_L1H6(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary and discourse structure attention head."""
    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        return "prog_L1H6", np.array([[]])

    attention = np.zeros((n, n))

    # Parse with spacy for sentence boundaries
    doc = spacy_parse(sentence)
    alignment = _align_to_spacy(sentence, tokens)

    # Find sentence boundary tokens (periods, exclamation marks, question marks)
    sentence_boundaries = []
    newlines = []
    for i, token in enumerate(tokens):
        token_str = token.strip()
        if token_str in ['.', '!', '?']:
            sentence_boundaries.append(i)
        elif token_str == '\n' or token_str.startswith('\n'):
            newlines.append(i)

    # Find which sentence each token belongs to
    token_sentences = [-1] * n
    current_sent = 0
    for i, token in enumerate(tokens):
        token_sentences[i] = current_sent
        if i in sentence_boundaries:
            current_sent += 1

    for i in range(n):
        # Strong attention to sentence boundary tokens within same sentence or previous sentences
        for boundary_idx in sentence_boundaries:
            if boundary_idx <= i:  # Causal constraint
                if token_sentences[boundary_idx] <= token_sentences[i]:
                    attention[i, boundary_idx] = 0.5

        # Strong attention to newlines from subsequent content
        for newline_idx in newlines:
            if newline_idx <= i:  # Causal constraint
                # Tokens after newlines attend to them strongly
                if i > newline_idx:
                    distance = i - newline_idx
                    attention[i, newline_idx] = max(0.3, 0.6 / (1 + distance * 0.1))

        # First token attention
        if i > 0:
            attention[i, 0] = 0.15

        # Self-attention
        attention[i, i] = 0.1

        # Local attention to immediate previous token
        if i > 0:
            attention[i, i-1] = 0.2

        # Some attention to function words and determiners
        if i > 0:
            for j in range(i):
                if j < len(alignment) and alignment[j]:
                    spacy_indices = alignment[j]
                    for spacy_idx in spacy_indices:
                        if spacy_idx < len(doc):
                            spacy_token = doc[spacy_idx]
                            if spacy_token.pos_ in ['DET', 'PREP', 'ADP']:
                                attention[i, j] += 0.05

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L1H6", attention



def prog_L1H7(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Punctuation anchor attention: tokens attend to earlier punctuation marks with distance-based weighting."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    # Find punctuation tokens
    punct_indices = []
    for i, token in enumerate(tokens):
        if token.strip() in ['.', ',', '\n']:
            punct_indices.append(i)

    for i in range(n):
        token = tokens[i].strip()

        if token in ['.', ',', '\n']:
            # Punctuation tokens have high self-attention
            attention[i, i] = 1.0

            # Also attend to previous punctuation with moderate weight
            for j in punct_indices:
                if j < i:
                    attention[i, j] = 0.3
        else:
            # Non-punctuation tokens attend strongly to punctuation
            if punct_indices:
                # Special case: Strong attention to very early punctuation (especially first period)
                early_punct = []
                for j in punct_indices:
                    if j < i and tokens[j].strip() == '.':
                        early_punct.append(j)

                if early_punct:
                    # Very strong attention to first period if it exists
                    first_period = early_punct[0]
                    attention[i, first_period] = 0.6

                    # Moderate attention to other early periods
                    for j in early_punct[1:]:
                        attention[i, j] = 0.2

                # Find the most recent punctuation before this token
                recent_punct = None
                for j in reversed(punct_indices):
                    if j < i:
                        recent_punct = j
                        break

                if recent_punct is not None:
                    # If recent punct is not already handled as early period
                    if tokens[recent_punct].strip() != '.' or recent_punct not in early_punct:
                        attention[i, recent_punct] = 0.4

                    # Moderate attention to other earlier punctuation
                    for j in punct_indices:
                        if j < recent_punct and j not in early_punct:
                            attention[i, j] = 0.15

            # Small amount of attention to adjacent tokens
            if i > 0:
                attention[i, i-1] = 0.1

            # Minimal self-attention
            attention[i, i] = 0.05

    # Handle tokens before any punctuation
    for i in range(n):
        if attention[i].sum() == 0:
            # If no punctuation to attend to, attend to previous tokens
            for j in range(i):
                attention[i, j] = 1.0 / max(1, i)
            if i == 0:
                attention[i, i] = 1.0

    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L1H7", attention



def prog_L1H8(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary attention: tokens attend to sentence-ending punctuation and newlines."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    # Find sentence-ending punctuation and newlines
    sentence_ends = []
    newlines = []

    for i, token in enumerate(tokens):
        if token.strip() in ['.', '!', '?']:
            sentence_ends.append(i)
        elif token.strip() == '\n':
            newlines.append(i)

    for i in range(n):
        # Find the most recent sentence ending before or at position i
        recent_sentence_end = None
        for end_pos in sentence_ends:
            if end_pos <= i:
                recent_sentence_end = end_pos
            else:
                break

        # High attention to the most recent sentence ending
        if recent_sentence_end is not None:
            attention[i, recent_sentence_end] = 0.6

        # Medium attention to newlines before position i
        for nl_pos in newlines:
            if nl_pos < i:
                attention[i, nl_pos] = 0.3

        # Small amount of self-attention
        attention[i, i] = 0.1

        # Very small attention to first token
        if i > 0:
            attention[i, 0] = 0.05

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L1H8", attention



def prog_L1H9(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary and structural marker attention head."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L1H9", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Find sentence boundaries and structural markers
    periods = []
    newlines = []

    for i, token in enumerate(tokens):
        if token.strip() == '.':
            periods.append(i)
        elif token.strip() == '\n':
            newlines.append(i)

    for i in range(n):
        # Strong self-attention for first token
        if i == 0:
            attention[i, i] = 1.0
            continue

        # High attention to periods (sentence boundaries)
        for period_idx in periods:
            if period_idx <= i:  # Causal constraint
                attention[i, period_idx] = 0.4 + 0.1 / (1 + abs(i - period_idx))

        # Strong attention to newlines (section boundaries)  
        for newline_idx in newlines:
            if newline_idx <= i:  # Causal constraint
                attention[i, newline_idx] = 0.3 + 0.2 / (1 + abs(i - newline_idx))

        # Self-attention
        attention[i, i] = 0.1

        # Weak attention to previous few tokens
        for j in range(max(0, i-3), i):
            attention[i, j] += 0.05 * (1.0 / (1 + i - j))

        # Small uniform attention to all previous tokens
        for j in range(i):
            attention[i, j] += 0.01

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L1H9", attention



def prog_L20H0(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """First-token and paragraph boundary attention head with long-range newline focus."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention_matrix = np.zeros((n, n))

    for i in range(n):
        # Always attend strongly to the first token (position 0)
        if n > 0:
            attention_matrix[i, 0] = 0.6

        # Strong self-attention for the first token
        if i == 0:
            attention_matrix[i, i] = 1.0
            continue

        # Find newline tokens that precede current position
        newline_positions = []
        for j in range(i):
            if tokens[j].strip() == '' and j > 0:  # Likely newline/whitespace
                newline_positions.append(j)

        # Special case: attend more strongly to earlier newlines in longer texts
        if newline_positions and len(tokens) > 40:
            # In longer texts, attend to the earliest significant newlines
            early_newlines = [pos for pos in newline_positions if pos < len(tokens) * 0.3]
            if early_newlines:
                for early_pos in early_newlines[:2]:  # Focus on first 1-2 early newlines
                    attention_matrix[i, early_pos] = 0.45
            else:
                # Fallback to most recent newline with reduced weight
                most_recent_newline = max(newline_positions)
                attention_matrix[i, most_recent_newline] = 0.25
        elif newline_positions:
            # Original behavior for shorter texts
            most_recent_newline = max(newline_positions)
            attention_matrix[i, most_recent_newline] = 0.4

        # Moderate attention to sentence-ending punctuation
        for j in range(i):
            if tokens[j].strip() in ['.', '!', '?']:
                attention_matrix[i, j] = 0.1

        # Small distributed attention to all previous tokens
        for j in range(i):
            attention_matrix[i, j] += 0.02

        # Slightly higher attention to immediately preceding token
        if i > 0:
            attention_matrix[i, i-1] += 0.05

    # Apply causal mask and normalize
    attention_matrix = apply_causal_mask(attention_matrix)
    attention_matrix = make_row_stochastic(attention_matrix)

    return "prog_L20H0", attention_matrix



def prog_L20H1(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary and first-token attention head with enhanced long-range connections."""
    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L20H1", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Find newline positions and first token
    newline_positions = []
    for i, token in enumerate(tokens):
        if token.strip() == '' and '\n' in token:
            newline_positions.append(i)

    for i in range(n):
        current_token = tokens[i]

        # Very strong attention to first token (position 0) - stronger for distant tokens
        if i >= 1:  # Can't attend to self if we're at position 0
            # Increase first-token attention for longer distances
            first_token_strength = 0.8 + min(0.2, 0.02 * i)
            attention[i, 0] = first_token_strength

        # Strong attention to newlines (sentence boundaries)
        for nl_pos in newline_positions:
            if nl_pos <= i:  # Causal constraint
                attention[i, nl_pos] = 0.6

        # Moderate attention to tokens immediately after newlines (sentence starts)
        for nl_pos in newline_positions:
            if nl_pos + 1 <= i and nl_pos + 1 < n:
                attention[i, nl_pos + 1] = 0.4

        # Reduced self attention - original was too high
        attention[i, i] = 0.15

        # Enhanced positional decay for other tokens - stronger decay for long sequences
        for j in range(i):
            if j != 0 and j not in newline_positions:
                # Check if j+1 is right after a newline
                is_after_newline = any(nl_pos + 1 == j for nl_pos in newline_positions)
                if not is_after_newline:
                    # Apply stronger positional decay, especially for longer distances
                    distance = i - j
                    if distance > 10:
                        # Much stronger decay for very long distances
                        decay = 0.05 / (distance * distance * 0.1)
                    else:
                        # Original decay for shorter distances
                        decay = 0.1 / (distance + 1)
                    attention[i, j] += decay

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L20H1", attention



def prog_L20H10(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Paragraph boundary and sentence-start detection head with strong newline attention."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    # Find newline positions and sentence start positions
    newline_positions = []
    sentence_starts = []

    for i, token in enumerate(tokens):
        if token.strip() == '\n':
            newline_positions.append(i)
            # Token after newline is often sentence start
            if i + 1 < n:
                sentence_starts.append(i + 1)
        elif i == 0:
            sentence_starts.append(i)

    # Get spacy alignment for linguistic features
    spacy_alignment = _align_to_spacy(sentence, tokens)
    doc = spacy_parse(sentence)

    for i in range(n):
        # Base attention to self
        attention[i, i] = 0.1

        # Strong attention to newlines from most tokens
        for nl_pos in newline_positions:
            if nl_pos <= i:
                # Distance decay from newline
                distance = i - nl_pos
                if distance == 0:
                    attention[i, nl_pos] = 1.0  # Self-attention to newline
                else:
                    attention[i, nl_pos] = max(0.2, 0.8 * np.exp(-distance * 0.1))

        # Attention to sentence starts, especially from later tokens
        for start_pos in sentence_starts:
            if start_pos <= i and start_pos != i:
                distance = i - start_pos
                # Special case for certain tokens at sentence start
                start_weight = 0.3 * np.exp(-distance * 0.05)

                # Check if current token has linguistic features that increase attention
                if i < len(spacy_alignment) and spacy_alignment[i]:
                    spacy_idx = spacy_alignment[i][0]
                    if spacy_idx < len(doc):
                        token_obj = doc[spacy_idx]
                        # Boost attention for content words
                        if token_obj.pos_ in ['NOUN', 'VERB', 'ADJ', 'ADV']:
                            start_weight *= 2.0

                attention[i, start_pos] = start_weight

        # Special high attention for first token
        if len(tokens) > 0:
            attention[i, 0] = max(attention[i, 0], 0.2)

        # Very strong self-attention for first token
        if i == 0:
            attention[i, i] = 1.0

        # Add small attention to immediate previous tokens
        for j in range(max(0, i-3), i):
            if attention[i, j] < 0.1:
                attention[i, j] = 0.05 * (1.0 / (i - j + 1))

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L20H10", attention



def prog_L20H11(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Previous-token attention with newline anchoring and semantic similarity."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L20H11", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Parse sentence for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        # Strong attention to immediate previous token
        if i > 0:
            attention[i, i-1] = 0.4

        # Self attention (moderate)
        attention[i, i] = 0.2

        # High attention to newlines from many positions
        for j in range(i + 1):
            if tokens[j] == '\n':
                attention[i, j] = 0.3

        # Attention to first token (moderate)
        if i > 0:
            attention[i, 0] = 0.15

        # Semantic similarity based attention
        for j in range(i):
            if j != i-1 and tokens[j] != '\n':  # Skip previous token and newlines already handled
                sim = _char_sim(tokens[i], tokens[j])
                if sim > 0.7:  # High semantic similarity
                    attention[i, j] += 0.2 * sim
                elif sim > 0.5:  # Moderate semantic similarity
                    attention[i, j] += 0.1 * sim

        # Special handling for punctuation attending to content words
        if tokens[i] in ['.', ',', '!', '?']:
            for j in range(max(0, i-3), i):
                if token_to_spacy[j]:
                    spacy_idx = token_to_spacy[j][0]
                    if spacy_idx < len(doc) and doc[spacy_idx].pos_ in ['NOUN', 'VERB', 'ADJ']:
                        attention[i, j] += 0.15

        # Content words attending to function words in local context
        if token_to_spacy[i]:
            spacy_idx = token_to_spacy[i][0]
            if spacy_idx < len(doc) and doc[spacy_idx].pos_ in ['NOUN', 'VERB', 'ADJ']:
                for j in range(max(0, i-5), i):
                    if token_to_spacy[j]:
                        j_spacy_idx = token_to_spacy[j][0]
                        if j_spacy_idx < len(doc) and doc[j_spacy_idx].pos_ in ['DET', 'ADP', 'PRON']:
                            attention[i, j] += 0.1

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L20H11", attention



def prog_L20H12(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Document structure attention: attends to first tokens and paragraph breaks."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    # Find first non-whitespace token
    first_token_idx = 0
    for i, token in enumerate(tokens):
        if token.strip():
            first_token_idx = i
            break

    # Find newlines and empty tokens after periods (paragraph breaks)
    paragraph_breaks = []
    for i, token in enumerate(tokens):
        if token.strip() == '' or token == '\n':
            paragraph_breaks.append(i)

    for i in range(n):
        # Self-attention (always some)
        attention[i, i] = 0.1

        # Strong attention to first token
        if i != first_token_idx:
            attention[i, first_token_idx] = 0.6
        else:
            attention[i, i] += 0.6

        # Attention to paragraph breaks
        for break_idx in paragraph_breaks:
            if break_idx <= i and break_idx != i:
                attention[i, break_idx] = 0.3

        # Moderate attention to recent tokens (recency bias)
        for j in range(max(0, i-5), i):
            if j != first_token_idx and j not in paragraph_breaks:
                attention[i, j] += 0.05 * (1.0 - (i - j) / 6.0)

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L20H12", attention



def prog_L20H13(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Structural boundary attention head - attends to first tokens and newlines."""
    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention_matrix = np.zeros((n, n))

    # Find first token and newline positions
    first_token_idx = 0
    newline_indices = []

    for i, token in enumerate(tokens):
        if token.strip() == '' or '\n' in token:
            newline_indices.append(i)

    for i in range(n):
        # High attention to first token
        attention_matrix[i, first_token_idx] = 0.8

        # Strong attention to newlines (but not from the newlines themselves to avoid self-loops)
        for nl_idx in newline_indices:
            if i != nl_idx and nl_idx <= i:  # causal constraint
                attention_matrix[i, nl_idx] = 0.4

        # Self-attention for structural tokens
        if i in newline_indices or i == first_token_idx:
            attention_matrix[i, i] = 0.6
        else:
            attention_matrix[i, i] = 0.1

        # Small uniform attention to other available tokens
        for j in range(i + 1):
            if j != first_token_idx and j not in newline_indices and j != i:
                attention_matrix[i, j] = 0.02

    # Apply causal mask and normalize
    attention_matrix = apply_causal_mask(attention_matrix)
    attention_matrix = make_row_stochastic(attention_matrix)

    return "prog_L20H13", attention_matrix



def prog_L20H14(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Structural boundary and first-token attention head."""
    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        token_i = tokens[i]
        spacy_indices_i = token_to_spacy[i]

        for j in range(i + 1):  # Causal mask
            token_j = tokens[j]

            # Strong attention to first token (sequence start)
            if j == 0 and i > 0:
                # Distance-based decay from first token
                distance_factor = max(0.3, 1.0 - (i - 1) * 0.02)
                attention[i, j] = 0.6 * distance_factor

            # Strong attention to newlines
            elif token_j.strip() == '':  # whitespace/newline tokens
                attention[i, j] = 0.4

            # Self-attention (reduced to account for first-token attention)
            elif i == j:
                if i == 0:
                    attention[i, j] = 0.15
                else:
                    attention[i, j] = 0.08  # Reduced self-attention for non-first tokens

            # Attention to punctuation (commas, periods, exclamation marks)
            elif token_j in [',', '.', '!', '?', ';', ':']:
                attention[i, j] = 0.12

            # Previous token attention
            elif j == i - 1:
                attention[i, j] = 0.08

            # Syntactic relationships using spacy
            elif spacy_indices_i and token_to_spacy[j]:
                spacy_i = spacy_indices_i[0] if spacy_indices_i else None
                spacy_j = token_to_spacy[j][0] if token_to_spacy[j] else None

                if spacy_i is not None and spacy_j is not None and spacy_i < len(doc) and spacy_j < len(doc):
                    spacy_token_i = doc[spacy_i]
                    spacy_token_j = doc[spacy_j]

                    # Head-dependent relationships
                    if spacy_token_i.head == spacy_token_j or spacy_token_j.head == spacy_token_i:
                        attention[i, j] = 0.06

                    # Same syntactic role or similar dependency
                    elif spacy_token_i.dep_ == spacy_token_j.dep_ and spacy_token_i.dep_ in ['NOUN', 'VERB', 'ADJ']:
                        attention[i, j] = 0.04

            # Semantic similarity for remaining tokens
            else:
                sim = _char_sim(tokens[i], tokens[j])
                if sim > 0.7:  # High semantic similarity
                    attention[i, j] = 0.05 * sim
                elif sim > 0.5:  # Moderate similarity
                    attention[i, j] = 0.02 * sim
                else:
                    attention[i, j] = 0.01

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L20H14", attention



def prog_L20H15(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Structural boundary detection head with dialogue start attention: attends to newlines, sentence breaks, dialogue starts, and self."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L20H15", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    # Detect if we're in a dialogue/quoted speech context
    # Look for patterns like: word + comma + quote, or quote early in sequence
    is_dialogue = False
    dialogue_start_idx = 0

    # Check if first few tokens suggest dialogue
    for i in range(min(3, n)):
        token = tokens[i].strip()
        if token in ['"', "'"] or (i == 0 and any(c in tokens[i] for c in ['"', "'"])):
            is_dialogue = True
            dialogue_start_idx = 0
            break
        if i == 1 and token in [','] and i + 1 < n and any(c in tokens[i + 1] for c in ['"', "'"]):
            is_dialogue = True
            dialogue_start_idx = 0
            break

    for i in range(n):
        token = tokens[i]

        # Very strong self-attention for first token
        if i == 0:
            attention[i, i] = 1.0
            continue

        # Special case: if in dialogue context, add strong attention to dialogue start
        if is_dialogue and i > dialogue_start_idx:
            attention[i, dialogue_start_idx] = 0.7

        # Find newline tokens - these get very high attention
        newline_indices = [j for j in range(i + 1) if tokens[j].strip() == '' and '\n' in tokens[j]]

        if newline_indices:
            # Strong attention to the most recent newline
            most_recent_newline = max(newline_indices)
            attention[i, most_recent_newline] = 0.4

            # Moderate attention to other newlines
            for nl_idx in newline_indices:
                if nl_idx != most_recent_newline:
                    attention[i, nl_idx] = 0.1

        # Self-attention
        attention[i, i] = 0.05

        # Attention to punctuation (sentence boundaries)
        for j in range(i + 1):
            if tokens[j] in ['.', '!', '?', '"', ',']:
                attention[i, j] = 0.03

        # Some attention to the beginning of sentences/paragraphs
        for j in range(i + 1):
            if j > 0 and tokens[j-1] in ['.', '!', '?'] and tokens[j].strip():
                attention[i, j] = 0.02

        # Weak attention to semantically similar tokens
        for j in range(i + 1):
            if j != i:
                sim = _char_sim(tokens[i], tokens[j])
                if sim > 0.7:  # High similarity threshold
                    attention[i, j] += 0.01

        # Small uniform attention to recent context
        context_start = max(0, i - 10)
        for j in range(context_start, i + 1):
            attention[i, j] += 0.001

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L20H15", attention



def prog_L20H16(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Attention head that focuses on newline tokens as structural markers, with enhanced first-token attention for content words."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L20H16", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Find newline tokens
    newline_positions = [i for i, token in enumerate(tokens) if token.strip() == '']

    for i in range(n):
        # Base self-attention
        attention[i, i] = 0.05

        # High attention to newlines (especially the first significant newline)
        for nl_pos in newline_positions:
            if nl_pos <= i:
                # Give higher weight to earlier newlines, especially around position 2-12
                if 2 <= nl_pos <= 12:
                    attention[i, nl_pos] = 0.6
                else:
                    attention[i, nl_pos] = 0.3

        # Enhanced attention to first token for content words
        if i > 0:
            base_first_attention = 0.15

            # Check if current token is a content word using spacy
            try:
                doc = spacy_parse(sentence)
                token_to_spacy = _align_to_spacy(sentence, tokens)

                if i < len(token_to_spacy) and token_to_spacy[i]:
                    spacy_idx = token_to_spacy[i][0]
                    if spacy_idx < len(doc):
                        spacy_token = doc[spacy_idx]

                        # Boost first-token attention for content words (NOUN, VERB, ADJ, ADV)
                        if spacy_token.pos_ in ['NOUN', 'VERB', 'ADJ', 'ADV']:
                            base_first_attention = 0.45  # Significant boost for content words
            except:
                pass

            attention[i, 0] = base_first_attention

        # Some local syntactic attention using spacy
        try:
            doc = spacy_parse(sentence)
            token_to_spacy = _align_to_spacy(sentence, tokens)
            spacy_to_token = align_spacy_to_tokens(sentence)

            if i < len(token_to_spacy) and token_to_spacy[i]:
                spacy_idx = token_to_spacy[i][0]
                if spacy_idx < len(doc):
                    spacy_token = doc[spacy_idx]

                    # Attention to syntactic head
                    if spacy_token.head != spacy_token and spacy_token.head.i < len(spacy_to_token):
                        head_tokens = spacy_to_token[spacy_token.head.i]
                        for head_tok in head_tokens:
                            if head_tok <= i:
                                attention[i, head_tok] = 0.08

                    # Attention to dependents
                    for child in spacy_token.children:
                        if child.i < len(spacy_to_token):
                            child_tokens = spacy_to_token[child.i]
                            for child_tok in child_tokens:
                                if child_tok <= i:
                                    attention[i, child_tok] = 0.04
        except:
            pass

        # Fill remaining attention more uniformly for non-newline, non-first tokens
        remaining_positions = [j for j in range(i + 1) if j not in newline_positions and j != 0]
        if remaining_positions:
            remaining_weight = max(0, 1.0 - attention[i, :].sum())
            weight_per_pos = remaining_weight / len(remaining_positions)
            for j in remaining_positions:
                attention[i, j] += weight_per_pos

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L20H16", attention



def prog_L20H17(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Structural boundary attention head with very strong sequence-start focus and selective newline attention."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    # Find newline positions
    newline_positions = []
    for i, token in enumerate(tokens):
        if token.strip() == '' and '\n' in token:
            newline_positions.append(i)

    for i in range(n):
        token = tokens[i]

        # Special case: second token attending strongly to first token
        if i == 1:
            attention[i, 0] = 0.8

        # Much stronger attention to first token for most tokens
        if i > 0:
            # Base strong attention to first token
            attention[i, 0] += 0.5

            # Additional boost for tokens further from start
            if i > 5:
                attention[i, 0] += 0.2

        # More selective attention to newlines - only for tokens close to newlines
        for nl_pos in newline_positions:
            if nl_pos <= i:  # causal constraint
                if i == nl_pos:
                    # Self-attention for newlines
                    attention[i, nl_pos] = 0.3
                elif i <= nl_pos + 3:
                    # Only tokens within 3 positions after newline attend strongly
                    attention[i, nl_pos] = 0.3
                else:
                    # Distant tokens have weaker newline attention
                    attention[i, nl_pos] = 0.1

        # Self-attention baseline
        attention[i, i] = 0.1

        # Some attention to nearby tokens
        for j in range(max(0, i-3), i):
            if j != i:
                attention[i, j] += 0.05

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L20H17", attention



def prog_L20H18(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary and beginning detector - attends to first tokens and earliest newlines."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L20H18", np.zeros((n_empty, n_empty))

    attention_matrix = np.zeros((n, n))

    # Find newline positions (sentence boundaries)
    newline_positions = []
    for i, token in enumerate(tokens):
        if token.strip() == '' and '\n' in token:
            newline_positions.append(i)

    for i in range(n):
        current_token = tokens[i].strip()

        # First few tokens (0-3) attend very strongly to first token
        if i <= 3:
            attention_matrix[i, 0] = 0.95 + 0.05 * (4 - i) / 4
            # Small residual to other tokens
            for j in range(1, i + 1):
                if j != 0:
                    attention_matrix[i, j] = 0.01
        else:
            # Find the EARLIEST newline before current token (not most recent)
            earliest_newline = None
            for nl_pos in newline_positions:
                if nl_pos < i:
                    earliest_newline = nl_pos
                    break  # Take the first one we find (earliest)

            if earliest_newline is not None:
                # Strong attention to earliest sentence boundary
                attention_matrix[i, earliest_newline] = 0.45

                # Moderate attention to first token
                attention_matrix[i, 0] = 0.15

                # Self attention
                attention_matrix[i, i] = 0.15

                # Some attention to nearby important tokens
                doc = spacy_parse(sentence)
                token_to_spacy = _align_to_spacy(sentence, tokens)

                if i < len(token_to_spacy) and token_to_spacy[i]:
                    spacy_idx = token_to_spacy[i][0]
                    if spacy_idx < len(doc):
                        spacy_token = doc[spacy_idx]

                        # Look for content words in nearby context
                        remaining_weight = 0.25
                        nearby_count = 0

                        for j in range(max(0, i - 5), i):
                            if j < len(token_to_spacy) and token_to_spacy[j]:
                                j_spacy_idx = token_to_spacy[j][0]
                                if j_spacy_idx < len(doc):
                                    j_spacy_token = doc[j_spacy_idx]
                                    if j_spacy_token.pos_ in ['NOUN', 'VERB', 'ADJ', 'PROPN']:
                                        nearby_count += 1

                        if nearby_count > 0:
                            weight_per_token = remaining_weight / nearby_count
                            for j in range(max(0, i - 5), i):
                                if j < len(token_to_spacy) and token_to_spacy[j]:
                                    j_spacy_idx = token_to_spacy[j][0]
                                    if j_spacy_idx < len(doc):
                                        j_spacy_token = doc[j_spacy_idx]
                                        if j_spacy_token.pos_ in ['NOUN', 'VERB', 'ADJ', 'PROPN']:
                                            attention_matrix[i, j] = weight_per_token
                        else:
                            # Distribute remaining weight nearby
                            for j in range(max(0, i - 3), i):
                                attention_matrix[i, j] += remaining_weight / min(3, i)

            else:
                # No newline found, attend to first token and self
                attention_matrix[i, 0] = 0.6
                attention_matrix[i, i] = 0.3
                # Small attention to recent tokens
                for j in range(max(0, i - 2), i):
                    attention_matrix[i, j] += 0.05

    # Handle special punctuation
    for i in range(n):
        if tokens[i].strip() in ['.', ',', '!', '?', ':', ';']:
            # Punctuation gets moderate self-attention and some to previous
            attention_matrix[i, i] = 0.4
            if i > 0:
                attention_matrix[i, i-1] = 0.3
            if newline_positions:
                earliest_nl = None
                for nl_pos in newline_positions:
                    if nl_pos < i:
                        earliest_nl = nl_pos
                        break
                if earliest_nl is not None:
                    attention_matrix[i, earliest_nl] = 0.3

    # Apply causal mask and normalize
    attention_matrix = apply_causal_mask(attention_matrix)
    attention_matrix = make_row_stochastic(attention_matrix)

    return "prog_L20H18", attention_matrix



def prog_L20H19(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """First-token and newline attention head with very strong positional bias over self-attention."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L20H19", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    for i in range(n):
        for j in range(i + 1):  # Causal mask: only attend to j <= i
            weight = 0.0

            # Much stronger attention to first token
            if j == 0:
                weight += 1.5

            # Strong attention to newline tokens
            if tokens[j].strip() == '' or '\n' in tokens[j]:
                weight += 0.6

            # Drastically reduced self-attention weight
            if i == j:
                weight += 0.05

            # Semantic similarity component
            sim = _char_sim(tokens[i], tokens[j])
            if sim > 0.5:
                weight += 0.4 * sim

            # Recency bias - closer tokens get slightly higher weight
            if i > 0:
                recency = 1.0 / (1.0 + 0.1 * (i - j))
                weight *= recency

            # Small base weight for all valid positions
            weight += 0.05

            attention[i, j] = weight

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L20H19", attention



def prog_L20H2(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """First token + sentence boundary attention head."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L20H2", np.zeros((n_empty, n_empty))

    # Initialize attention matrix
    attention = np.zeros((n, n))

    for i in range(n):
        for j in range(i + 1):  # Only attend to previous tokens (causal mask)

            # Very strong attention to first token (index 0)
            if j == 0:
                attention[i, j] = 1.0

            # Strong attention to newline tokens
            elif tokens[j].strip() == '' and '\n' in tokens[j]:
                attention[i, j] = 0.4

            # Medium attention to period tokens (sentence boundaries)
            elif tokens[j].strip() == '.':
                attention[i, j] = 0.03

            # Self-attention (very low)
            elif i == j:
                attention[i, j] = 0.01

            # Minimal background attention to other tokens
            else:
                attention[i, j] = 0.005

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L20H2", attention



def prog_L20H20(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Attention head focusing on first token and newlines with semantic similarity."""
    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention_matrix = np.zeros((n, n))

    # Find newline positions
    newline_positions = [i for i, token in enumerate(tokens) if token.strip() == '']

    for i in range(n):
        # Base attention distribution
        weights = np.zeros(i + 1)  # Causal mask: only attend to positions <= i

        if i == 0:
            # First token attends to itself
            weights[0] = 1.0
        else:
            # Strong bias toward first token
            weights[0] = 0.6

            # Strong attention to newlines, especially the first significant newline
            for nl_pos in newline_positions:
                if nl_pos <= i:
                    if nl_pos < 20:  # First newline gets highest weight
                        weights[nl_pos] = 0.4
                    else:
                        weights[nl_pos] = 0.2

            # Add semantic similarity component for remaining positions
            remaining_weight = 0.3
            for j in range(1, i + 1):
                if j not in newline_positions:
                    # Base positional decay
                    pos_weight = 1.0 / (i - j + 1)

                    # Semantic similarity boost
                    sim = _char_sim(tokens[i], tokens[j])
                    if sim > 0.3:  # Only boost for meaningful similarity
                        pos_weight *= (1 + sim)

                    weights[j] = remaining_weight * pos_weight

            # Normalize non-structural weights
            non_structural_sum = sum(weights[j] for j in range(1, i + 1) 
                                   if j not in newline_positions and weights[j] > 0)
            if non_structural_sum > 0:
                for j in range(1, i + 1):
                    if j not in newline_positions and weights[j] > 0:
                        weights[j] = (weights[j] / non_structural_sum) * remaining_weight

        attention_matrix[i, :len(weights)] = weights

    # Ensure proper normalization and causal masking
    attention_matrix = apply_causal_mask(attention_matrix)
    attention_matrix = make_row_stochastic(attention_matrix)

    return "prog_L20H20", attention_matrix



def prog_L20H21(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Structural boundary attention with strong beginning-of-sequence focus."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention_matrix = np.zeros((n, n))

    # Find structural tokens
    newline_indices = []
    period_indices = []
    first_token_idx = 0

    for i, token in enumerate(tokens):
        if '\n' in token:
            newline_indices.append(i)
        elif token.strip() in ['.', '!', '?']:
            period_indices.append(i)

    for i in range(n):
        # Strong attention to newlines (dominant pattern)
        for nl_idx in newline_indices:
            if nl_idx <= i:
                attention_matrix[i, nl_idx] = 0.5

        # Moderate attention to the first token (especially for early tokens)
        if i > 0:
            recency_weight = max(0.1, 1.0 / (i + 1))
            attention_matrix[i, first_token_idx] = 0.3 * recency_weight

        # Some attention to periods
        for p_idx in period_indices:
            if p_idx <= i:
                attention_matrix[i, p_idx] = 0.1

        # Self-attention for the first few tokens
        if i <= 2:
            attention_matrix[i, i] = 0.8

        # Small baseline attention to recent tokens
        for j in range(max(0, i-3), i+1):
            attention_matrix[i, j] += 0.05

    # TARGETED FIX: Strong beginning-of-sequence attention
    # Many tokens show very strong attention to the first token
    for i in range(1, n):
        # Boost attention to first token, especially for later positions
        if i >= 3:  # Beyond the early self-attention phase
            attention_matrix[i, first_token_idx] = max(attention_matrix[i, first_token_idx], 0.6)

        # Reduce over-predicted newline attention for tokens that are far from newlines
        for nl_idx in newline_indices:
            if nl_idx <= i and nl_idx > 0:  # Don't affect first token if it's a newline
                # Reduce newline attention if the token is semantically distant
                distance_from_newline = i - nl_idx
                if distance_from_newline > 5:
                    attention_matrix[i, nl_idx] *= 0.7

    # Apply causal mask and normalize
    attention_matrix = apply_causal_mask(attention_matrix)
    attention_matrix = make_row_stochastic(attention_matrix)

    return "prog_L20H21", attention_matrix



def prog_L20H22(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """First-token and newline-focused attention head with strong global first-token bias."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L20H22", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Get spacy alignment for linguistic features
    spacy_alignment = _align_to_spacy(sentence, tokens)
    doc = spacy_parse(sentence)

    for i in range(n):
        for j in range(i + 1):  # causal mask
            weight = 0.0

            # Very strong attention to first token from early positions
            if j == 0 and i <= 5:
                weight += 0.8
            elif j == 0:
                weight += 0.2

            # Enhanced first-token attention for content words at later positions
            if j == 0 and i > 5:
                # Check if current token is a content word using spacy
                is_content = False
                if spacy_alignment[i]:
                    spacy_idx = spacy_alignment[i][0]
                    if spacy_idx < len(doc):
                        spacy_token = doc[spacy_idx]
                        # Content words: nouns, verbs, adjectives, adverbs
                        if spacy_token.pos_ in ['NOUN', 'VERB', 'ADJ', 'ADV', 'PROPN']:
                            is_content = True

                if is_content:
                    weight += 0.3  # Boost first-token attention for content words

            # High attention to newline characters
            if tokens[j].strip() == '':  # newline or whitespace
                weight += 0.4

            # Attention to punctuation marks
            if tokens[j] in ['.', ',', '!', '?', ':', ';']:
                weight += 0.15

            # Self-attention for newlines and first token
            if i == j:
                if tokens[i].strip() == '' or i == 0:
                    weight += 0.3
                else:
                    weight += 0.01

            # Distance decay for non-special tokens
            if j != 0 and tokens[j].strip() != '':
                distance = i - j
                if distance > 0:
                    weight += 0.05 / (1 + distance * 0.5)

            # Small baseline attention
            weight += 0.005

            attention[i, j] = weight

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L20H22", attention



def prog_L20H23(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary hub with strong first-token attention: tokens attend to sequence start and newline boundaries."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L20H23", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Find newline tokens
    newline_indices = [i for i, token in enumerate(tokens) if token.strip() == '']

    # Parse sentence for syntactic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        # Strong self-attention for first token
        if i == 0:
            attention[i, i] = 1.0
            continue

        # Strong attention to first token for most tokens
        attention[i, 0] = 0.5

        # Find the most relevant newline (sentence boundary) for this token
        relevant_newline = None
        for nl_idx in newline_indices:
            if nl_idx < i:  # Only previous newlines due to causal mask
                relevant_newline = nl_idx

        # Moderate attention to sentence boundary newline (reduced from original)
        if relevant_newline is not None:
            attention[i, relevant_newline] = 0.2

        # Self-attention
        attention[i, i] = 0.15

        # Local syntactic attention
        spacy_indices = token_to_spacy[i]
        if spacy_indices:
            spacy_token = doc[spacy_indices[0]]

            # Attend to syntactic head
            if spacy_token.head != spacy_token and spacy_token.head.i < len(doc):
                head_token_indices = []
                for j in range(i):
                    if j < len(token_to_spacy) and spacy_token.head.i in token_to_spacy[j]:
                        head_token_indices.append(j)

                for head_idx in head_token_indices:
                    attention[i, head_idx] += 0.1

            # Attend to immediate previous token if it's syntactically related
            if i > 0:
                prev_spacy = token_to_spacy[i-1] if i-1 < len(token_to_spacy) else []
                if prev_spacy and spacy_indices:
                    prev_token = doc[prev_spacy[0]] if prev_spacy[0] < len(doc) else None
                    curr_token = doc[spacy_indices[0]]

                    if prev_token and (prev_token.dep_ in ['det', 'amod', 'compound'] or 
                                     curr_token.dep_ in ['pobj', 'dobj']):
                        attention[i, i-1] += 0.15

        # Small attention to previous token for sequence continuity
        if i > 0:
            attention[i, i-1] += 0.05

        # Punctuation gets attention from nearby tokens
        if tokens[i] in ['.', ',', '!', '?', ';', ':']:
            attention[i, max(0, i-1)] += 0.1

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L20H23", attention



def prog_L20H24(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Mixed positional attention with enhanced self-attention for boundary and whitespace tokens."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L20H24", np.zeros((n_empty, n_empty)).reshape(0, 0)

    attention = np.zeros((n, n))

    # Parse with spacy for any linguistic features we might need
    alignment = _align_to_spacy(sentence, tokens)

    for i in range(n):
        # Base attention weights
        weights = np.zeros(n)

        # Check if this token should have enhanced self-attention
        token_text = tokens[i].strip()
        is_boundary_token = (token_text == '' or '\n' in tokens[i] or 
                           token_text in ['.', ',', '!', '?', ';', ':'])

        if is_boundary_token:
            # Much stronger self-attention for boundary/whitespace tokens
            weights[i] = 3.0

            # Reduced attention to first token and newlines for these tokens
            weights[0] = 0.2

            # Minimal attention to other newlines/whitespace
            for j in range(i):
                if tokens[j].strip() == '' or '\n' in tokens[j]:
                    weights[j] = 0.1

            # Very local recency only
            for j in range(max(0, i - 2), i):
                if j != i:
                    distance = i - j
                    weight = 0.1 / distance
                    weights[j] += weight
        else:
            # Original behavior for non-boundary tokens
            # Strong self-attention
            weights[i] = 1.0

            # Strong attention to first token
            weights[0] = 0.8

            # Find newline tokens and attend to them
            for j in range(i + 1):
                if tokens[j].strip() == '' or '\n' in tokens[j]:
                    weights[j] = 0.6

            # Local recency bias - attend to recent tokens
            for j in range(max(0, i - 3), i):
                if j != i:  # Don't double-count self
                    distance = i - j
                    weight = 0.3 / distance  # Decay with distance
                    weights[j] += weight

            # Add some similarity-based attention for content words
            if alignment[i]:  # If token aligns to spacy tokens
                doc = spacy_parse(sentence)
                spacy_indices = alignment[i]

                # Check if this token corresponds to a content word
                is_content = False
                for spacy_idx in spacy_indices:
                    if spacy_idx < len(doc):
                        spacy_token = doc[spacy_idx]
                        if spacy_token.pos_ in ['NOUN', 'VERB', 'ADJ', 'ADV']:
                            is_content = True
                            break

                if is_content:
                    # Add similarity-based attention to other content words
                    for j in range(i + 1):
                        if j != i and alignment[j]:
                            sim = _char_sim(tokens[i], tokens[j])
                            if sim > 0.3:  # Only if reasonably similar
                                weights[j] += 0.2 * sim

        # Normalize and store
        if weights.sum() > 0:
            attention[i] = weights / weights.sum()
        else:
            attention[i, i] = 1.0

    # Apply causal mask and ensure row-stochastic
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L20H24", attention



def prog_L20H25(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """First-token and newline boundary attention with positional decay."""
    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L20H25", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Find first meaningful token (skip whitespace/punctuation at start)
    first_token_idx = 0
    for i, token in enumerate(tokens):
        if token.strip() and token not in [' ', '\n', '\t']:
            first_token_idx = i
            break

    # Find newline positions
    newline_positions = []
    for i, token in enumerate(tokens):
        if '\n' in token:
            newline_positions.append(i)

    for i in range(n):
        # Strong attention to first meaningful token
        if first_token_idx < i:
            attention[i, first_token_idx] += 0.6

        # Strong attention to newlines (especially the first significant newline)
        for nl_pos in newline_positions:
            if nl_pos < i:
                # First newline gets more weight
                weight = 0.5 if nl_pos == newline_positions[0] and nl_pos > 0 else 0.3
                attention[i, nl_pos] += weight

        # Self attention
        attention[i, i] += 0.3

        # Moderate attention to recent tokens with decay
        for j in range(max(0, i-5), i):
            if j != first_token_idx and j not in newline_positions:
                decay = 0.1 * (1.0 - (i - j) / 6.0)
                attention[i, j] += decay

        # Small attention to all previous tokens
        for j in range(i):
            if attention[i, j] == 0:  # Don't overwrite existing weights
                attention[i, j] += 0.02

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L20H25", attention



def prog_L20H26(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary and self-attention head with syntactic components."""
    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L20H26", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        # Strong self-attention baseline
        attention[i, i] = 1.0

        # Find sentence boundary tokens (periods, exclamation marks)
        for j in range(i + 1):
            if tokens[j] in [".", "!", "?"]:
                attention[i, j] += 0.8

        # High attention to tokens immediately after newlines
        for j in range(i + 1):
            if j > 0 and tokens[j-1] == "\n":
                attention[i, j] += 0.6

        # Attention to newlines themselves
        for j in range(i + 1):
            if tokens[j] == "\n":
                attention[i, j] += 0.4

        # Empty string tokens (often after punctuation) attend strongly to preceding punctuation
        if tokens[i] == "":
            for j in range(i):
                if tokens[j] in [".", "!", "?", ","]:
                    attention[i, j] += 1.2

        # Syntactic relationships - modifiers to heads
        if token_to_spacy[i]:
            spacy_i = token_to_spacy[i][0]
            if spacy_i < len(doc):
                spacy_token = doc[spacy_i]
                if spacy_token.head != spacy_token:  # Has a head
                    # Find the head token in the LM tokenization
                    head_char_start = spacy_token.head.idx
                    head_char_end = head_char_start + len(spacy_token.head.text)

                    # Find overlapping LM tokens
                    char_pos = 0
                    for j in range(i + 1):
                        token_start = char_pos
                        token_end = char_pos + len(tokens[j])
                        if token_start < head_char_end and token_end > head_char_start:
                            attention[i, j] += 0.3
                        char_pos = token_end

        # First token bias
        if i > 0:
            attention[i, 0] += 0.2

        # Previous token attention
        if i > 0:
            attention[i, i-1] += 0.3

        # Semantic similarity boost
        for j in range(i):
            sim = _char_sim(tokens[i], tokens[j])
            if sim > 0.7:
                attention[i, j] += 0.2 * sim

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L20H26", attention



def prog_L20H27(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """First-token and immediate context attention with reduced distant boundary effects."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L20H27", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    for i in range(n):
        token = tokens[i]

        # Strong self-attention for first token
        if i == 0:
            attention[i, i] = 1.0
            continue

        # Strong self-attention for punctuation
        if token in ['.', '!', '?', ',', ';', ':']:
            attention[i, i] = 0.8

        # High attention from early tokens to first token
        if i <= 3:
            attention[i, 0] = 0.8

        # Modified newline attention - only attend to nearby newlines
        for j in range(max(0, i - 5), i + 1):  # Only look at last 5 tokens
            if tokens[j] == '\n':
                attention[i, j] = 0.2  # Reduced from 0.4

        # Find closest preceding punctuation for sentence boundaries
        closest_punct = -1
        for j in range(i - 1, max(-1, i - 10), -1):  # Limit search window
            if tokens[j] in ['.', '!', '?', '\n']:
                closest_punct = j
                break

        if closest_punct >= 0:
            attention[i, closest_punct] = 0.15  # Reduced from 0.3

        # Local attention to adjacent tokens
        if i > 0:
            attention[i, i - 1] = 0.1

        # Self-attention baseline
        attention[i, i] = max(attention[i, i], 0.1)

        # Enhanced attention to first token from all positions
        attention[i, 0] = max(attention[i, 0], 0.1)  # Increased from 0.05

    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L20H27", attention



def prog_L20H28(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary and structural delimiter attention head - attends to newlines, periods, and sequence start."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    for i in range(n):
        current_token = tokens[i].strip()

        # Strong attention to first token (often empty string marking start)
        if n > 0:
            attention[i, 0] = 0.4

        # Self-attention
        attention[i, i] = 0.1

        # Look for structural delimiters to attend to
        for j in range(i + 1):  # Causal mask
            target_token = tokens[j].strip()

            # Very strong attention to newlines (paragraph/line breaks)
            if target_token == '\n' or target_token == '\\n':
                attention[i, j] += 0.6

            # Strong attention to sentence-ending punctuation
            elif target_token == '.' and j < i:
                attention[i, j] += 0.3

            # Moderate attention to other punctuation
            elif target_token in [',', '!', '?', ';', ':']:
                attention[i, j] += 0.1

            # Attention to quotes which often mark dialogue boundaries
            elif target_token in ['"', "'", '"', '"']:
                attention[i, j] += 0.15

        # Add some recency bias - slightly higher attention to recent tokens
        for j in range(max(0, i-5), i):
            attention[i, j] += 0.05

        # Special case: strong attention to immediately preceding period
        if i > 0 and tokens[i-1].strip() == '.':
            attention[i, i-1] += 0.5

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L20H28", attention



def prog_L20H29(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """First-token and structural boundary attention head with newline focus."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L20H29", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    for i in range(n):
        token = tokens[i]

        # Strong self-attention for first token
        if i == 0:
            attention[i, i] = 1.0
            continue

        # For tokens 1-3, very high attention to first token
        if i <= 3:
            attention[i, 0] = 0.95
            attention[i, i] = 0.05
            continue

        # Find newline tokens
        newline_positions = []
        for j in range(i + 1):  # causal mask
            if tokens[j].strip() == '' and '\n' in tokens[j]:
                newline_positions.append(j)

        # If there are newlines, attend strongly to the most recent one
        if newline_positions:
            most_recent_newline = max(newline_positions)
            attention[i, most_recent_newline] = 0.6

            # Some attention to first token
            attention[i, 0] = 0.2

            # Moderate self-attention
            attention[i, i] = 0.1

            # Small attention to other recent tokens
            for j in range(max(0, i-5), i):
                if j != most_recent_newline and j != 0:
                    attention[i, j] = 0.02
        else:
            # No newlines found - attend to first token and self
            attention[i, 0] = 0.7
            attention[i, i] = 0.2

            # Small attention to recent tokens
            for j in range(max(0, i-3), i):
                if j != 0:
                    attention[i, j] = 0.03

    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L20H29", attention



def prog_L20H3(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Attention to structural anchors: first token and line breaks with strong bias."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L20H3", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Find newline positions
    newline_positions = []
    for i, token in enumerate(tokens):
        if token.strip() == '\n':
            newline_positions.append(i)

    for i in range(n):
        # Very strong attention to first token
        attention[i, 0] = 3.0

        # Strong attention to newlines (but not from first few tokens)
        for nl_pos in newline_positions:
            if nl_pos <= i and i > 2:  # Don't attend to newlines from very early tokens
                attention[i, nl_pos] = 1.5

        # Self-attention for newlines
        if tokens[i].strip() == '\n':
            attention[i, i] = 1.0

        # Moderate attention to previous token
        if i > 0:
            attention[i, i-1] = 0.3

        # Small attention to nearby tokens
        for j in range(max(0, i-3), i):
            if j != i-1 and j != 0 and tokens[j].strip() != '\n':
                attention[i, j] = 0.1

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L20H3", attention



def prog_L20H30(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """First-token and newline boundary attention with local syntactic patterns."""
    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        # Strong self-attention for first token
        if i == 0:
            attention[i, i] = 1.0
            continue

        # Find newline tokens
        newline_indices = []
        for j in range(i + 1):
            if '\n' in tokens[j]:
                newline_indices.append(j)

        # High attention to newlines, especially the most recent one
        if newline_indices:
            for j in newline_indices:
                # More weight to recent newlines
                distance = i - j
                weight = 0.4 / (1 + distance * 0.1)
                attention[i, j] += weight

        # Strong attention to first token
        attention[i, 0] += 0.3

        # Local syntactic patterns
        if token_to_spacy[i]:
            spacy_idx = token_to_spacy[i][0]
            if spacy_idx < len(doc):
                spacy_token = doc[spacy_idx]

                # Prepositions attend to their objects
                if spacy_token.pos_ == 'ADP':
                    for j in range(max(0, i-3), i):
                        if token_to_spacy[j]:
                            sp_j = token_to_spacy[j][0]
                            if sp_j < len(doc) and doc[sp_j].pos_ in ['NOUN', 'PROPN']:
                                attention[i, j] += 0.2

                # Determiners attend to nearby nouns
                if spacy_token.pos_ == 'DET':
                    for j in range(i+1, min(n, i+3)):
                        if token_to_spacy[j]:
                            sp_j = token_to_spacy[j][0]
                            if sp_j < len(doc) and doc[sp_j].pos_ in ['NOUN', 'PROPN']:
                                attention[i, j] += 0.3

        # Punctuation gets some attention to preceding tokens
        if tokens[i] in ['.', ',', '!', '?']:
            for j in range(max(0, i-2), i):
                attention[i, j] += 0.1

        # Self-attention baseline
        attention[i, i] += 0.05

        # Some recency bias for all tokens
        for j in range(i):
            distance = i - j
            attention[i, j] += 0.02 / (1 + distance)

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L20H30", attention



def prog_L20H31(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """First-token attention head with very strong focus on sentence beginning."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L20H31", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        # Base attention vector
        att = np.zeros(n)

        # Much stronger attention to first token - this is the key pattern
        att[0] = 3.0  # Increased from 1.0 to dominate after normalization

        # Find newline tokens and give them high attention
        for j in range(i + 1):
            if tokens[j].strip() == '' and '\n' in tokens[j]:
                att[j] = 0.8

        # Reduced self-attention to allow first-token dominance
        att[i] = 0.1  # Reduced from 0.3

        # Local syntactic dependencies
        if token_to_spacy[i]:
            spacy_idx = token_to_spacy[i][0]
            if spacy_idx < len(doc):
                spacy_token = doc[spacy_idx]

                # Attend to syntactic head
                if spacy_token.head != spacy_token:
                    head_idx = spacy_token.head.i
                    # Find corresponding LM token
                    for j in range(i + 1):
                        if token_to_spacy[j] and head_idx in token_to_spacy[j]:
                            att[j] += 0.4
                            break

                # Attend to previous token for local dependencies
                if i > 0:
                    att[i - 1] += 0.2

        # Special handling for certain patterns
        # If current token looks like punctuation, attend more to previous content
        if tokens[i] in ['.', ',', '!', '?', '"', "'", ')']:
            for j in range(max(0, i - 3), i):
                if tokens[j].strip() and tokens[j] not in ['.', ',', '!', '?', '"', "'", '(', ')']:
                    att[j] += 0.3

        # Boost attention to tokens with high semantic similarity
        for j in range(i + 1):
            if j != i and _char_sim(tokens[i], tokens[j]) > 0.7:
                att[j] += 0.2

        attention[i] = att

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L20H31", attention



def prog_L20H4(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Attention head that focuses on sentence-initial tokens with distance-based decay, with reduced newline attention."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    for i in range(n):
        for j in range(i + 1):  # causal mask
            # Very high attention to first token from early positions
            if j == 0 and i < 6:
                attention[i, j] = 0.99 - 0.01 * i
            # Reduced attention to newlines from all positions
            elif tokens[j] == '\n':
                # Distance-based decay from newlines - significantly reduced
                distance = i - j
                if distance == 0:
                    attention[i, j] = 0.15  # Reduced from 0.45
                else:
                    # Much lower baseline for newline attention
                    attention[i, j] = max(0.005, 0.1 - 0.01 * distance)  # Reduced from 0.5 - 0.02 * distance
            # Enhanced attention to first token from later positions
            elif j == 0:
                # Stronger attention to first token from distant positions
                attention[i, j] = max(0.05, 0.6 - 0.01 * i)  # Enhanced from 0.4 - 0.02 * i
            # Self-attention baseline
            elif i == j:
                attention[i, j] = 0.01
            # Low baseline for other positions
            else:
                attention[i, j] = 0.005

    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L20H4", attention



def prog_L20H5(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """First-token and newline attention with semantic similarity component and enhanced first-token attention."""
    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    for i in range(n):
        # Very strong attention to first token for early positions
        if i <= 3:
            attention[i, 0] = 0.98 - i * 0.01
        else:
            attention[i, 0] = 0.02

        # Enhanced first-token attention: if first token is quote or special punctuation,
        # maintain stronger attention throughout the sequence
        first_token = tokens[0].strip()
        if first_token in ['"', "'", '`'] or (len(first_token) == 1 and not first_token.isalnum()):
            if i > 3:
                # Decay from position 4 onwards but maintain substantial attention
                decay_factor = max(0.3, 1.0 - (i - 3) * 0.05)
                attention[i, 0] = min(0.95, 0.6 * decay_factor)

        # Find newline tokens and attend to them
        for j in range(i + 1):
            if tokens[j].strip() == '':  # newline or whitespace
                if i > j + 5:  # Not too close to the newline itself
                    attention[i, j] = 0.4
                elif i > j:
                    attention[i, j] = 0.2

        # Self-attention
        attention[i, i] = 0.1

        # Semantic similarity component for remaining attention
        for j in range(i):
            if j != 0 and tokens[j].strip() != '':  # Not first token or newline
                sim = _char_sim(tokens[i], tokens[j])
                if sim > 0.7:  # High semantic similarity
                    attention[i, j] += 0.05
                elif sim > 0.5:  # Moderate semantic similarity
                    attention[i, j] += 0.02

        # Small baseline attention to recent tokens
        for j in range(max(0, i-3), i):
            if tokens[j].strip() != '' and j != 0:
                attention[i, j] += 0.01

    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)
    return "prog_L20H5", attention



def prog_L20H6(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """First token and sentence boundary attention head - attends to first token and newlines."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    # Find the first token and all newline positions
    first_token_idx = 0
    newline_indices = []
    for i, token in enumerate(tokens):
        if token.strip() == '\n':
            newline_indices.append(i)

    for i in range(n):
        # First few tokens (typically first 4-6) attend very strongly to first token
        if i <= min(3, n-1):
            attention[i, first_token_idx] = 1.0
        else:
            # Other tokens primarily attend to newlines with high weight
            total_newline_weight = 0.0
            for nl_idx in newline_indices:
                if nl_idx <= i:  # Causal constraint
                    # Stronger attention to more recent newlines
                    weight = 0.5 * (0.9 ** (i - nl_idx))
                    attention[i, nl_idx] = weight
                    total_newline_weight += weight

            # Small attention to first token
            attention[i, first_token_idx] = 0.1

            # Some attention to punctuation marks
            for j in range(i + 1):
                if tokens[j].strip() in ['.', ',', '!', '?', '"', "'", ';"', '!"']:
                    attention[i, j] += 0.05

            # Small self-attention
            attention[i, i] = 0.02

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L20H6", attention



def prog_L20H7(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Attention head that focuses on self-attention for first tokens and newline boundaries, with special handling for first-token detection."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    # Detect which token acts as the "first token" based on attention patterns
    # Look for tokens that are likely sentence beginnings (alphabetic, not whitespace)
    first_token_idx = 0
    for i in range(min(5, n)):  # Check first few tokens
        if tokens[i].strip() and tokens[i].strip()[0].isalpha():
            first_token_idx = i
            break

    for i in range(n):
        token = tokens[i]

        # Strong self-attention for all tokens, especially first token
        if i == first_token_idx:
            attention[i, i] = 1.0
        else:
            attention[i, i] = 0.1

        # Strong attention to first token from early tokens
        if i < 5 and i > first_token_idx:
            attention[i, first_token_idx] = 0.8

        # Very strong attention to the detected first token from all later tokens
        if i > first_token_idx:
            attention[i, first_token_idx] = 0.9

        # Strong attention to newlines
        for j in range(i):
            if '\n' in tokens[j]:
                attention[i, j] = 0.5

        # Moderate attention to punctuation
        for j in range(i):
            if tokens[j].strip() in ['.', ',', '!', '?', ';', ':']:
                attention[i, j] = 0.1

        # General leftward positional bias (decaying with distance)
        for j in range(i):
            if j != first_token_idx and '\n' not in tokens[j] and tokens[j].strip() not in ['.', ',', '!', '?', ';', ':']:
                distance = i - j
                attention[i, j] += 0.05 * np.exp(-0.1 * distance)

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L20H7", attention



def prog_L20H8(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Attention to first token and sentence boundaries (newlines) with local context."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L20H8", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    for i in range(n):
        # Strong attention to first token
        attention[i, 0] = 0.6

        # Strong self-attention
        attention[i, i] = 0.2

        # Find newline tokens and attend to them
        for j in range(i + 1):
            if tokens[j].strip() == '':  # newline or whitespace token
                attention[i, j] += 0.3

        # Moderate attention to recent tokens (recency bias)
        for j in range(max(0, i - 3), i):
            if j != 0:  # don't double-count first token
                distance = i - j
                weight = 0.1 / distance
                attention[i, j] += weight

        # Light attention to punctuation
        for j in range(i + 1):
            if tokens[j] in ['.', ',', '!', '?', '"', "'", ':', ';']:
                attention[i, j] += 0.05

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L20H8", attention



def prog_L20H9(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Structural boundary detection head focusing on newlines and sentence-initial tokens."""
    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention_matrix = np.zeros((n, n))

    # Parse with spacy for additional features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        for j in range(i + 1):  # Causal mask
            weight = 0.0

            # Strong self-attention for first token
            if i == 0 and j == 0:
                weight += 1.0

            # High attention to newline characters
            if tokens[j].strip() == '':  # newline or whitespace
                weight += 0.5

            # Attention to sentence-initial tokens (tokens after newlines or at start)
            if j == 0:  # Very first token
                weight += 0.3
            elif j > 0 and tokens[j-1].strip() == '':  # Token after newline
                weight += 0.3

            # Moderate attention to punctuation
            if tokens[j] in ['.', ',', '!', '?', '"', "'", ';', ':']:
                weight += 0.1

            # Small recency bias (prefer recent tokens)
            if i > 0:
                distance = i - j
                recency_weight = 0.1 * np.exp(-distance / 5.0)
                weight += recency_weight

            # Small boost for similar tokens
            if i != j:
                sim = _char_sim(tokens[i], tokens[j])
                if sim > 0.7:
                    weight += 0.05 * sim

            attention_matrix[i, j] = weight

    # Apply causal mask and normalize
    attention_matrix = apply_causal_mask(attention_matrix)
    attention_matrix = make_row_stochastic(attention_matrix)

    return "prog_L20H9", attention_matrix



def prog_L21H0(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Discourse boundary and structural attention head with strong document-initial focus."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L21H0", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        token = tokens[i]

        # Strong self-attention baseline
        attention[i, i] = 0.3

        # Very strong attention to line breaks from most tokens
        for j in range(i + 1):
            if tokens[j] == '\n':
                attention[i, j] = 1.0

        # Strong attention to sentence-ending punctuation
        for j in range(i + 1):
            if tokens[j] in ['.', '!', '?']:
                attention[i, j] += 0.4

        # High attention to first token - SIGNIFICANTLY INCREASED
        if i > 0:
            # Much stronger attention to document beginning
            attention[i, 0] = 0.6

        # Special patterns for certain token types
        spacy_indices = token_to_spacy[i]
        if spacy_indices:
            spacy_token = doc[spacy_indices[0]]

            # Punctuation tokens attend strongly to previous content tokens
            if token in [',', '.', '!', '?', '"', "'", ')']:
                for j in range(max(0, i-5), i):
                    spacy_j_indices = token_to_spacy[j]
                    if spacy_j_indices and doc[spacy_j_indices[0]].pos_ in ['NOUN', 'VERB', 'ADJ']:
                        attention[i, j] += 0.3

            # Content words attend to previous line breaks and punctuation
            if spacy_token.pos_ in ['NOUN', 'VERB', 'ADJ', 'PROPN']:
                for j in range(i):
                    if tokens[j] in ['\n', '.', '!']:
                        attention[i, j] += 0.5

        # Local recency bias - attend to recent tokens
        for j in range(max(0, i-3), i):
            attention[i, j] += 0.1 * (1.0 / (i - j + 1))

        # Special handling for quotation marks and dialogue
        if token in ['"', "'"]:
            # Attend to previous dialogue markers
            for j in range(i):
                if tokens[j] in ['"', "'", 'said', 'says']:
                    attention[i, j] += 0.2

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L21H0", attention



def prog_L21H1(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """First token and distant newline boundary attention head."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        return "prog_L21H1", np.zeros((0, 0))

    attention = np.zeros((n, n))

    # Find newline positions
    newline_positions = []
    for i, token in enumerate(tokens):
        if token.strip() == '' and '\n' in token:
            newline_positions.append(i)

    for i in range(n):
        # Very strong attention to first token for early positions
        if i <= 3:  # First few tokens
            attention[i, 0] = 0.99
            # Distribute remaining weight
            if len(newline_positions) > 0:
                closest_newline = min(newline_positions, key=lambda x: abs(x - i))
                attention[i, closest_newline] = 0.01
        else:
            # For other tokens, attend primarily to newlines
            if len(newline_positions) > 0:
                # Find the closest preceding newline
                preceding_newlines = [pos for pos in newline_positions if pos < i]
                if preceding_newlines:
                    # Special case: prefer earlier newlines over recent ones
                    # This handles the pattern where tokens attend to distant paragraph boundaries
                    if len(preceding_newlines) > 1 and i > preceding_newlines[-1] + 10:
                        # If we're far from the most recent newline, prefer earlier ones
                        closest_newline = preceding_newlines[0]  # Use first newline instead of most recent
                    else:
                        closest_newline = max(preceding_newlines)

                    attention[i, closest_newline] = 0.6

                    # Add some attention to first token
                    attention[i, 0] = 0.2

                    # Add small self-attention
                    attention[i, i] = 0.1

                    # Distribute remaining weight to nearby tokens
                    for j in range(max(0, i-5), i):
                        if j != closest_newline and j != 0:
                            attention[i, j] = 0.02
                else:
                    # No preceding newlines, attend to first token and self
                    attention[i, 0] = 0.7
                    attention[i, i] = 0.2
                    # Small uniform distribution to preceding tokens
                    for j in range(i):
                        if j != 0:
                            attention[i, j] = 0.1 / max(1, i-1)
            else:
                # No newlines in sequence, attend primarily to first token
                attention[i, 0] = 0.8
                attention[i, i] = 0.15
                # Small uniform distribution
                for j in range(i):
                    if j != 0:
                        attention[i, j] = 0.05 / max(1, i-1)

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L21H1", attention



def prog_L21H10(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Newline boundary attention head - attends to paragraph breaks, sentence starts, and strong first-token focus."""
    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    # Find newline tokens
    newline_indices = []
    for i, token in enumerate(tokens):
        if token.strip() == '' and '\n' in token:
            newline_indices.append(i)

    # Check if first token is a content word that should receive high attention
    first_token_is_content = False
    if tokens:
        # Use spacy to check if first token is a content word
        spacy_alignment = _align_to_spacy(sentence, tokens)
        if spacy_alignment[0]:  # If first token aligns to spacy tokens
            doc = spacy_parse(sentence)
            first_spacy_idx = spacy_alignment[0][0]
            if first_spacy_idx < len(doc):
                first_spacy_token = doc[first_spacy_idx]
                # Content words: NOUN, VERB, ADJ, ADV, PROPN
                if first_spacy_token.pos_ in ['NOUN', 'VERB', 'ADJ', 'ADV', 'PROPN']:
                    first_token_is_content = True

    for i in range(n):
        # Strong self-attention
        attention[i, i] = 0.3

        # Strong attention to newline tokens (primary pattern)
        if newline_indices:
            # Find the most relevant newline (usually the first major one)
            target_newline = newline_indices[0] if newline_indices else 0
            if target_newline <= i:  # Respect causal mask
                attention[i, target_newline] = 0.6

        # Enhanced attention to first token - much stronger if it's content
        if i > 0:
            if first_token_is_content:
                attention[i, 0] = 0.5  # Much higher for content words
            else:
                attention[i, 0] = 0.1  # Original weight for punctuation

        # Small residual attention distributed to recent tokens
        for j in range(max(0, i-5), i):
            if j not in [0] + newline_indices:
                attention[i, j] += 0.01

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L21H10", attention



def prog_L21H11(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Structural delimiter attention head with enhanced self-attention for content words."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention_matrix = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        query_token = tokens[i]

        # Base attention distribution
        for j in range(i + 1):  # Causal mask
            key_token = tokens[j]

            # Strong attention to newlines
            if key_token.strip() == '' and '\n' in key_token:
                attention_matrix[i, j] = 0.3

            # Attention to punctuation
            elif key_token.strip() in ['.', ',', '!', '?', ';', ':']:
                attention_matrix[i, j] = 0.15

            # Attention to first token
            elif j == 0:
                attention_matrix[i, j] = 0.1

            # Self attention
            elif i == j:
                attention_matrix[i, j] = 0.05

            # Special case: very first token gets high attention to itself
            if i == 0 and j == 0:
                attention_matrix[i, j] = 0.8

            # Additional boost for structural tokens
            if key_token.strip() in ['', '\n']:
                attention_matrix[i, j] += 0.1

            # Boost attention from content tokens to nearby structural markers
            if j < i and (key_token.strip() in ['.', ',', '\n'] or (key_token.strip() == '' and '\n' in key_token)):
                # Distance-based decay
                distance = i - j
                if distance <= 10:
                    attention_matrix[i, j] += 0.2 / (1 + distance * 0.1)

            # Small baseline attention to all previous tokens
            if j < i:
                attention_matrix[i, j] += 0.02

        # Enhanced self-attention for content words
        if i == i and len(token_to_spacy[i]) > 0:
            spacy_indices = token_to_spacy[i]
            for spacy_idx in spacy_indices:
                if spacy_idx < len(doc):
                    spacy_token = doc[spacy_idx]
                    # Boost self-attention for content words (nouns, verbs, adjectives)
                    if spacy_token.pos_ in ['NOUN', 'VERB', 'ADJ', 'PROPN']:
                        attention_matrix[i, i] = max(attention_matrix[i, i], 0.4)
                    # Also boost for words with specific patterns that show high self-attention
                    elif len(query_token.strip()) > 2 and query_token.strip().isalpha():
                        attention_matrix[i, i] = max(attention_matrix[i, i], 0.3)

    # Apply causal mask and normalize
    attention_matrix = apply_causal_mask(attention_matrix)
    attention_matrix = make_row_stochastic(attention_matrix)

    return "prog_L21H11", attention_matrix



def prog_L21H12(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """First-token and newline boundary attention head with contraction-aware self-attention."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L21H12", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    for i in range(n):
        for j in range(i + 1):  # Causal mask
            weight = 0.0

            # Strong attention to first token
            if j == 0:
                weight += 0.8

            # Strong attention to newline tokens
            if tokens[j].strip() == "" and "\n" in tokens[j]:
                weight += 0.6

            # Self-attention
            if i == j:
                weight += 0.3

            # NEW: Strong attention pattern for contractions
            # Apostrophe tokens attend strongly to adjacent word parts
            if "'" in tokens[i] and i > 0 and j == i - 1:
                # Apostrophe attends to preceding word part
                weight += 0.9
            elif "'" in tokens[j] and j > 0 and i == j + 1:
                # Token after apostrophe attends back to apostrophe
                weight += 0.6

            # Moderate attention to punctuation marks
            if tokens[j] in [".", ",", "!", "?", ":", ";"]:
                weight += 0.2

            # Small recency bias for recent tokens
            if i - j <= 3 and i != j:
                weight += 0.1 * (1 / (i - j + 1))

            # Attention to quotes and special characters
            if any(char in tokens[j] for char in ['"', "'", "'", """, """]):
                weight += 0.15

            attention[i, j] = weight

    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L21H12", attention



def prog_L21H13(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Attention head computing self-attention, first-token attention, and structural boundary attention with enhanced self-attention for structural tokens."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L21H13", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        # Check if current token is a structural boundary token
        is_structural = (tokens[i] == '' or tokens[i] == '\n' or 
                        tokens[i].strip() in ['.', '!', '?', '."', '!"', '?"'])

        if is_structural:
            # Structural tokens get much stronger self-attention and reduced first-token attention
            attention[i, i] = 0.7
            if i > 0:
                attention[i, 0] = 0.15
        else:
            # Base self-attention weight for regular tokens
            attention[i, i] = 0.3

            # Strong attention to first token for regular tokens
            if i > 0:
                attention[i, 0] = 0.4

        # High attention to newline characters
        for j in range(i + 1):
            if tokens[j] == '\n':
                attention[i, j] = 0.35

        # Moderate attention to sentence boundaries and punctuation
        for j in range(i + 1):
            token_text = tokens[j].strip()
            if token_text in ['.', '!', '?', '."', '!"', '?"']:
                attention[i, j] += 0.15
            elif token_text in [',', ';', ':']:
                attention[i, j] += 0.08

        # Additional attention based on linguistic features
        if token_to_spacy[i]:
            spacy_token = doc[token_to_spacy[i][0]]

            # If current token is a verb, attend more to previous tokens
            if spacy_token.pos_ in ['VERB', 'AUX']:
                for j in range(max(0, i-3), i):
                    attention[i, j] += 0.1

            # If current token is a pronoun, attend to recent nouns
            if spacy_token.pos_ == 'PRON':
                for j in range(max(0, i-5), i):
                    if token_to_spacy[j]:
                        spacy_j = doc[token_to_spacy[j][0]]
                        if spacy_j.pos_ in ['NOUN', 'PROPN']:
                            attention[i, j] += 0.12

        # Slight recency bias for recent tokens (reduced for structural tokens)
        if not is_structural:
            for j in range(max(0, i-3), i):
                attention[i, j] += 0.05 * (1 - (i - j) / 4)

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L21H13", attention



def prog_L21H14(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Structural boundary attention head with adaptive self-attention for certain token types."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    # Find newline positions
    newline_positions = []
    for i, token in enumerate(tokens):
        if token.strip() == '' and '\n' in token:
            newline_positions.append(i)

    for i in range(n):
        token = tokens[i]

        # Determine if this token should have high self-attention
        high_self_attention = False
        self_weight = 0.3  # default

        # Check if token corresponds to punctuation or has specific linguistic properties
        spacy_indices = token_to_spacy[i]
        if spacy_indices:
            spacy_token = doc[spacy_indices[0]]
            # Punctuation tokens often have high self-attention
            if spacy_token.pos_ == 'PUNCT':
                high_self_attention = True
                self_weight = 0.6
            # Certain other tokens like conjunctions, determiners
            elif spacy_token.pos_ in ['CCONJ', 'DET', 'ADP'] and len(token.strip()) > 0:
                high_self_attention = True
                self_weight = 0.4

        # High attention to first token
        if i > 0:
            attention[i, 0] = 0.6

        # Self-attention (adaptive based on token type)
        attention[i, i] = self_weight

        # Strong attention to newlines (but reduced if high self-attention)
        newline_weight = 0.8
        if high_self_attention:
            newline_weight = 0.4  # Reduce newline attention for high self-attention tokens

        for newline_pos in newline_positions:
            if newline_pos <= i:
                attention[i, newline_pos] = newline_weight

        # Handle contractions and adjacent tokens
        if i > 0:
            prev_token = tokens[i-1]
            # Contractions (like "don't", "couldn't")
            if token.startswith("'"):
                attention[i, i-1] = 0.9
            # Adjacent word pairs
            elif len(token) < 4 and len(prev_token) < 4:
                attention[i, i-1] = 0.4

        # Some recency bias for nearby tokens (but reduced if high self-attention)
        recency_weight = 0.1
        if high_self_attention:
            recency_weight = 0.05

        for j in range(max(0, i-3), i):
            if attention[i, j] == 0:  # Don't override existing high values
                attention[i, j] = recency_weight * (1.0 / (i - j + 1))

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L21H14", attention



def prog_L21H15(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Structural boundary and positional anchor attention head."""
    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L21H15", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Get spacy alignment for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        token_i = tokens[i]

        # Strong self-attention for all tokens
        attention[i, i] = 0.3

        # High attention to newline characters
        for j in range(i + 1):
            if tokens[j] == '\n':
                attention[i, j] += 0.4

        # High attention to first token
        if i > 0:
            attention[i, 0] += 0.3

        # Punctuation patterns
        if token_i in [',', '.', '!', '?', ';', ':']:
            # Punctuation attends to immediately preceding token
            if i > 0:
                attention[i, i-1] += 0.2

        # Special handling for quotes and similar
        if token_i in ['"', "'", '"', '"', ''', ''']:
            # Quotes attend to nearby sentence boundaries
            for j in range(max(0, i-5), i):
                if tokens[j] in ['.', '!', '?', '\n']:
                    attention[i, j] += 0.15

        # Tokens after newlines get boosted attention to the newline
        if i > 0 and tokens[i-1] == '\n':
            for j in range(i):
                if tokens[j] == '\n':
                    attention[i, j] += 0.2

        # Add some recency bias for nearby tokens
        for j in range(max(0, i-3), i):
            if j != i:
                attention[i, j] += 0.05 * (1.0 - (i - j) / 4.0)

        # Boost attention to period/sentence endings
        for j in range(i + 1):
            if tokens[j] in ['.', '!', '?']:
                attention[i, j] += 0.1

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L21H15", attention



def prog_L21H16(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Attention to all accessible sentence boundaries with distributed weights."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    # Find newline and sentence boundary tokens
    newline_indices = []
    sentence_end_indices = []

    for i, token in enumerate(tokens):
        if token.strip() == '\n':
            newline_indices.append(i)
        elif token.strip() in ['.', '!', '?']:
            sentence_end_indices.append(i)

    # Combine newlines and sentence ends as primary targets
    boundary_indices = set(newline_indices + sentence_end_indices)

    for i in range(n):
        # Self-attention (always present)
        attention[i, i] = 0.3

        # Find accessible boundaries (at or before current position)
        accessible_boundaries = [b for b in boundary_indices if b < i]

        if accessible_boundaries:
            # Distribute strong attention across all accessible boundaries
            # Most recent gets highest weight, others get substantial weight too
            recent_boundary = max(accessible_boundaries)
            attention[i, recent_boundary] = 0.4

            # Strong attention to other accessible boundaries (not just 0.1)
            for b in accessible_boundaries:
                if b != recent_boundary:
                    attention[i, b] = 0.3
        else:
            # No boundaries available - attend to first token (but less strongly)
            if i > 0:
                attention[i, 0] = 0.4

        # Weak attention to adjacent tokens for local context
        if i > 0:
            attention[i, i-1] = 0.05
        if i > 1:
            attention[i, i-2] = 0.03

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L21H16", attention



def prog_L21H17(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Structural boundary detection with positional bias and local syntax."""
    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    # Get spacy alignment for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)
    spacy_to_token = align_spacy_to_tokens(sentence)

    for i in range(n):
        # Base self-attention
        attention[i, i] = 1.0

        # Strong attention to first token
        if i > 0:
            attention[i, 0] = 3.0

        # High attention to newlines from subsequent tokens
        for j in range(i):
            if tokens[j].strip() == '' or '\n' in tokens[j]:
                attention[i, j] += 5.0

        # Strong attention to punctuation (sentence boundaries)
        for j in range(i):
            if tokens[j] in ['.', '!', '?', ',', ';', ':']:
                attention[i, j] += 2.0

        # Local syntactic attention
        if token_to_spacy[i]:
            spacy_i = token_to_spacy[i][0]
            if spacy_i < len(doc):
                spacy_tok_i = doc[spacy_i]

                # Prepositions attend to their objects
                if spacy_tok_i.pos_ == 'ADP':
                    for child in spacy_tok_i.children:
                        if child.dep_ == 'pobj':
                            child_tokens = spacy_to_token[child.i] if child.i < len(spacy_to_token) else []
                            for child_token_idx in child_tokens:
                                if child_token_idx <= i:
                                    attention[i, child_token_idx] += 3.0

                # Attend to syntactic head
                if spacy_tok_i.head.i != spacy_tok_i.i:
                    head_tokens = spacy_to_token[spacy_tok_i.head.i] if spacy_tok_i.head.i < len(spacy_to_token) else []
                    for head_token_idx in head_tokens:
                        if head_token_idx <= i:
                            attention[i, head_token_idx] += 1.5

        # Recency bias - prefer recent tokens
        for j in range(max(0, i-5), i):
            attention[i, j] += 0.5 * (1.0 - (i - j) / 10.0)

        # Token similarity boost
        for j in range(i):
            sim = _char_sim(tokens[i], tokens[j])
            if sim > 0.7:
                attention[i, j] += 1.0 * sim

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L21H17", attention



def prog_L21H18(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Attention head that focuses on text structure boundaries (newlines, periods), local context, and strong first-token attention."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L21H18", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        # Strong self-attention for first token
        if i == 0:
            attention[i, i] = 1.0
            continue

        # Initialize base attention
        for j in range(i + 1):
            token_j = tokens[j].strip()
            token_i = tokens[i].strip()

            # High attention to newlines from most tokens
            if token_j == '\n':
                attention[i, j] = 0.4

            # High attention to periods
            elif token_j == '.':
                attention[i, j] = 0.2

            # Self-attention boost
            elif i == j:
                attention[i, j] = 0.3

            # Previous token attention (especially for function words)
            elif j == i - 1:
                attention[i, j] = 0.2

                # Extra boost if current token is a function word
                if token_to_spacy[i]:
                    spacy_idx = token_to_spacy[i][0]
                    if spacy_idx < len(doc):
                        spacy_token = doc[spacy_idx]
                        if spacy_token.pos_ in ['ADP', 'DET', 'AUX', 'PART']:
                            attention[i, j] += 0.3

            # Enhanced attention to first token based on semantic similarity
            elif j == 0:
                base_first_attention = 0.15

                # Check semantic similarity to first token
                similarity = _char_sim(tokens[i], tokens[0])
                if similarity > 0.3:  # High similarity
                    attention[i, j] = base_first_attention + 0.6
                elif similarity > 0.1:  # Medium similarity  
                    attention[i, j] = base_first_attention + 0.3
                else:
                    attention[i, j] = base_first_attention

            # Small baseline attention to other tokens
            else:
                attention[i, j] = 0.05

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L21H18", attention



def prog_L21H19(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Attention head focusing on contractions, quotes, and sentence boundaries with local context."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        current_token = tokens[i]

        # Strong self-attention for all tokens
        attention[i, i] = 0.3

        # High attention to newline characters from most positions
        for j in range(i + 1):
            if tokens[j] == '\n':
                attention[i, j] = 0.4

        # High attention to first token from many positions
        if i > 0:
            attention[i, 0] = 0.2

        # Local context attention - attend to previous few tokens
        for offset in range(1, min(4, i + 1)):
            j = i - offset
            if j >= 0:
                # Stronger for immediately previous token
                weight = 0.15 / offset
                attention[i, j] += weight

        # Special attention patterns for specific token relationships
        for j in range(i):
            # Check for semantic similarity using embeddings
            similarity = _char_sim(tokens[i], tokens[j])
            if similarity > 0.7:  # High similarity
                attention[i, j] += 0.2

            # Attention to punctuation marks
            if tokens[j] in ['.', ',', '!', '?']:
                attention[i, j] += 0.1

        # Boost attention to tokens that appear to be sentence/phrase starters
        for j in range(i):
            if j == 0 or (j > 0 and tokens[j-1] in ['.', '\n']):
                attention[i, j] += 0.15

        # Special handling for contractions and quotes
        if current_token in ["'t", "'", '"', "'s", "'re", "'m", "'d", "'ll", "'ve"]:
            # Reduce self-attention for contraction/quote tokens
            attention[i, i] = 0.05

            # Strong attention to immediately adjacent tokens
            if i > 0:
                attention[i, i-1] += 0.4
            if i > 1:
                attention[i, i-2] += 0.2

            # For quote tokens, attend to nearby context more broadly
            if current_token in ['"', "'"]:
                for offset in range(1, min(6, i + 1)):
                    j = i - offset
                    if j >= 0:
                        attention[i, j] += 0.1 / offset

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L21H19", attention



def prog_L21H2(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Head that attends to adjacent tokens in phrases, sentence boundaries, and strongly to sequence start."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L21H2", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        # Self-attention baseline
        attention[i, i] = 0.1

        # Strong attention to previous token (adjacent dependencies)
        if i > 0:
            attention[i, i-1] = 0.4

        # High attention to newlines and sentence boundaries
        for j in range(i + 1):
            if tokens[j] in ['\n', '.', '!', '?']:
                attention[i, j] = max(attention[i, j], 0.3)

        # Attention within syntactic phrases
        if token_to_spacy[i]:
            spacy_idx = token_to_spacy[i][0]
            if spacy_idx < len(doc):
                spacy_token = doc[spacy_idx]

                # Attend to syntactic head
                if spacy_token.head != spacy_token:
                    head_idx = spacy_token.head.i
                    for j in range(i + 1):
                        if j < len(token_to_spacy) and token_to_spacy[j]:
                            if head_idx in token_to_spacy[j]:
                                attention[i, j] = max(attention[i, j], 0.2)

                # Attend to direct children
                for child in spacy_token.children:
                    child_idx = child.i
                    for j in range(i + 1):
                        if j < len(token_to_spacy) and token_to_spacy[j]:
                            if child_idx in token_to_spacy[j]:
                                attention[i, j] = max(attention[i, j], 0.15)

        # Strong attention to sequence start (first token)
        if i > 0:
            attention[i, 0] = max(attention[i, 0], 0.35)

        # Enhanced attention to all boundary markers with stronger weights
        for j in range(i + 1):
            if tokens[j] in ['\n', '.', '!', '?', '"', "'", '(', ')', '[', ']', '{', '}']:
                # Boost boundary marker attention more aggressively
                attention[i, j] = max(attention[i, j], 0.45)

        # Embedding similarity for semantically related tokens
        for j in range(i + 1):
            if i != j:
                sim = _char_sim(tokens[i], tokens[j])
                if sim > 0.7:  # High similarity threshold
                    attention[i, j] = max(attention[i, j], 0.2 * sim)

        # Distance decay for general attention
        for j in range(i + 1):
            if i != j:
                distance = i - j
                decay_factor = 1.0 / (1.0 + 0.1 * distance)
                attention[i, j] = max(attention[i, j], 0.05 * decay_factor)

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L21H2", attention



def prog_L21H20(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Self-attention with strong sentence-start and local positional bias."""
    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L21H20", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        # Self-attention (strong baseline)
        attention[i, i] = 1.0

        # Sentence-start tokens get high attention
        for j in range(i + 1):
            token = tokens[j]

            # Very high attention to newlines and sentence starts
            if token in ['\n', ' \n'] or (j == 0):
                attention[i, j] += 2.0

            # High attention to punctuation that ends sentences
            if token in ['.', '!', '?']:
                attention[i, j] += 1.5

            # Moderate attention to first few tokens in sentence
            if j <= 2:
                attention[i, j] += 0.8

        # Local attention - attend to previous token
        if i > 0:
            attention[i, i-1] += 1.2

        # Attend to tokens that are syntactically related
        if token_to_spacy[i]:
            spacy_idx = token_to_spacy[i][0]
            spacy_token = doc[spacy_idx]

            # Attend to syntactic head
            if spacy_token.head != spacy_token:
                head_spacy_idx = spacy_token.head.i
                for j in range(i + 1):
                    if token_to_spacy[j] and head_spacy_idx in token_to_spacy[j]:
                        attention[i, j] += 0.5

            # Special boost for certain POS patterns
            if spacy_token.pos_ in ['NOUN', 'VERB', 'ADJ']:
                # Attend more to function words
                for j in range(i):
                    if token_to_spacy[j]:
                        j_spacy_idx = token_to_spacy[j][0]
                        j_spacy_token = doc[j_spacy_idx]
                        if j_spacy_token.pos_ in ['DET', 'ADP', 'AUX']:
                            attention[i, j] += 0.3

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L21H20", attention



def prog_L21H21(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Attention head that combines first-token bias, structural markers (newlines), and semantic similarity with enhanced first-token attention."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    for i in range(n):
        for j in range(i + 1):  # causal mask
            weight = 0.0

            # Strong first-token bias - enhanced for better matching
            if j == 0:
                # Much stronger first-token bias, especially for later tokens
                if i > 10:
                    weight += 0.8  # Very strong for distant tokens
                elif i > 5:
                    weight += 0.7  # Strong for medium distance
                else:
                    weight += 0.4  # Original weight for nearby tokens

            # Self-attention bonus
            if i == j:
                weight += 0.3

            # High attention to newlines from most tokens
            if tokens[j] == '\n':
                weight += 0.5

            # Attention to punctuation (periods, exclamation marks)
            if tokens[j] in ['.', '!', '?"', '"']:
                weight += 0.2

            # Proximity bias - recent tokens get more attention
            distance = i - j
            if distance <= 5:
                weight += 0.2 * (1.0 / (distance + 1))

            # Semantic similarity bonus
            sim = _char_sim(tokens[i], tokens[j])
            if sim > 0.3:
                weight += 0.3 * sim

            # Special boost for certain patterns observed
            if j > 0 and i > j:
                # 'a' attending to 'upon', 'it' attending to previous words
                if tokens[i] in ['a', 'the'] and tokens[j-1:j+1]:
                    weight += 0.2

                # Helping patterns like 'me' -> 'helping'
                if _char_sim(tokens[i], tokens[j]) > 0.4:
                    weight += 0.2

            attention[i, j] = weight

    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L21H21", attention



def prog_L21H22(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """First-token attention head with global first-token preference and local syntactic dependencies."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L21H22", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    # Find sentence boundaries (tokens that are '\n' or start sentences)
    sentence_starts = []
    for i, token in enumerate(tokens):
        if token.strip() == '' or token == '\n':
            sentence_starts.append(i)
        elif i == 0:
            sentence_starts.append(i)

    # If no clear sentence starts, use first token
    if not sentence_starts:
        sentence_starts = [0]

    for i in range(n):
        # Find the most recent sentence start for token i
        relevant_start = 0
        for start_idx in sentence_starts:
            if start_idx <= i:
                relevant_start = start_idx
            else:
                break

        # Base attention weights
        weights = np.zeros(n)

        # Strong attention to relevant sentence start (first-token pattern)
        if relevant_start <= i:
            weights[relevant_start] = 0.6

        # NEW: Additional strong attention to the global first token (token 0)
        # This handles cases where tokens attend strongly to the very beginning
        if i > 0:  # Don't double-count for token 0 itself
            weights[0] += 0.4

        # Self-attention
        weights[i] = 0.2

        # Local syntactic dependencies
        if token_to_spacy[i]:
            spacy_idx = token_to_spacy[i][0]
            if spacy_idx < len(doc):
                spacy_token = doc[spacy_idx]

                # Attend to syntactic head
                if spacy_token.head != spacy_token and spacy_token.head.idx is not None:
                    for j in range(min(i + 1, n)):
                        if token_to_spacy[j]:
                            for spacy_j in token_to_spacy[j]:
                                if spacy_j < len(doc) and doc[spacy_j].idx == spacy_token.head.idx:
                                    weights[j] += 0.15

                # Special attention patterns for certain dependencies
                for child in spacy_token.children:
                    if child.dep_ in ['prep', 'aux', 'det']:
                        for j in range(min(i + 1, n)):
                            if token_to_spacy[j]:
                                for spacy_j in token_to_spacy[j]:
                                    if spacy_j < len(doc) and doc[spacy_j].idx == child.idx:
                                        weights[j] += 0.1

        # Previous token attention (local context)
        if i > 0:
            weights[i-1] += 0.1

        # Slight attention to semantically similar tokens using embeddings
        for j in range(i + 1):
            if j != i and j != relevant_start:
                sim = _char_sim(tokens[i], tokens[j])
                if sim > 0.7:  # High semantic similarity
                    weights[j] += 0.05 * sim

        attention[i] = weights

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L21H22", attention



def prog_L21H23(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Structural attention head with strong long-range dependencies to early tokens and newlines."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    # Get spacy parsing for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        # Base attention distribution
        weights = np.zeros(n)

        # Strong attention to newlines from all positions
        for j in range(i + 1):
            if tokens[j].strip() == "":  # newline or whitespace
                weights[j] += 0.4

        # Strong attention to first token
        if i > 0:
            weights[0] += 0.3

        # Self-attention
        weights[i] += 0.1

        # Local syntactic dependencies
        if token_to_spacy[i]:
            spacy_idx = token_to_spacy[i][0]
            if spacy_idx < len(doc):
                spacy_token = doc[spacy_idx]

                # Attend to syntactic head
                if spacy_token.head != spacy_token:
                    head_idx = spacy_token.head.i
                    # Find corresponding LM token
                    for j in range(i + 1):
                        if token_to_spacy[j] and head_idx in token_to_spacy[j]:
                            weights[j] += 0.2
                            break

                # Attend to direct children
                for child in spacy_token.children:
                    child_idx = child.i
                    for j in range(i + 1):
                        if token_to_spacy[j] and child_idx in token_to_spacy[j]:
                            weights[j] += 0.1
                            break

        # Previous token attention (recency bias)
        if i > 0:
            weights[i-1] += 0.15

        # Attention to punctuation marks
        for j in range(i + 1):
            if tokens[j] in [".", ",", "!", "?", ";"]:
                weights[j] += 0.1

        # Semantic similarity boost for recent tokens
        for j in range(max(0, i-5), i):
            sim = _char_sim(tokens[i], tokens[j])
            if sim > 0.7:
                weights[j] += 0.1 * sim

        # NEW: Enhanced long-range attention for distant tokens
        if i > 10:  # Only for tokens far from the beginning
            # Much stronger attention to first token from distant positions
            weights[0] += 0.4

            # Strong attention to early newlines (first few newlines in sequence)
            newline_count = 0
            for j in range(min(i + 1, 15)):  # Look at first ~15 tokens
                if tokens[j].strip() == "":
                    newline_count += 1
                    if newline_count <= 2:  # First two newlines get extra boost
                        weights[j] += 0.3

            # Reduce recent newline attention for distant tokens
            for j in range(max(0, i-10), i):
                if tokens[j].strip() == "":
                    weights[j] *= 0.5  # Reduce recent newline attention

        attention[i] = weights

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L21H23", attention



def prog_L21H24(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Attention to important content tokens and structural boundaries, with strong beginning-of-sequence attention."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention_matrix = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    # Identify important tokens: newlines, nouns, proper nouns, entities
    important_tokens = set()

    # Always include newlines and first token
    for i, token in enumerate(tokens):
        if token.strip() == '' or '\n' in token:  # newlines/whitespace
            important_tokens.add(i)

    if n > 0:
        important_tokens.add(0)  # first token

    # Add important content words (nouns, proper nouns, entities)
    for i, token in enumerate(tokens):
        spacy_indices = token_to_spacy[i]
        for spacy_idx in spacy_indices:
            if spacy_idx < len(doc):
                spacy_token = doc[spacy_idx]
                # Important content: nouns, proper nouns, entities
                if (spacy_token.pos_ in ['NOUN', 'PROPN'] or 
                    spacy_token.ent_type_ != '' or
                    spacy_token.dep_ == 'ROOT'):
                    important_tokens.add(i)

    # Build attention matrix
    for i in range(n):
        # Self-attention for first token
        if i == 0:
            attention_matrix[i, i] = 1.0
            continue

        # Special case: detect strong beginning-of-sequence attention pattern
        # This happens when later tokens in the sequence need to attend strongly to the first token
        strong_bos_attention = False
        if i > 10:  # Only for tokens well into the sequence
            # Check if this token is not a major content word or structural element
            is_function_word = True
            spacy_indices = token_to_spacy[i]
            for spacy_idx in spacy_indices:
                if spacy_idx < len(doc):
                    spacy_token = doc[spacy_idx]
                    if spacy_token.pos_ in ['NOUN', 'PROPN', 'VERB']:
                        is_function_word = False
                        break

            # If it's a function word later in the sequence, check for strong BOS pattern
            if is_function_word and i not in important_tokens:
                strong_bos_attention = True

        if strong_bos_attention:
            # Very strong attention to first token
            attention_matrix[i, 0] = 0.8
            # Weak attention to everything else
            for j in range(1, i + 1):
                attention_matrix[i, j] = 0.02
        else:
            # Base attention to important tokens
            base_weight = 0.1
            for j in range(i + 1):  # causal mask
                if j in important_tokens:
                    if '\n' in tokens[j] or tokens[j].strip() == '':
                        # Strong attention to newlines
                        attention_matrix[i, j] = 0.4
                    elif j == 0:
                        # Moderate attention to first token
                        attention_matrix[i, j] = 0.2
                    else:
                        # Attention to content words
                        attention_matrix[i, j] = 0.3
                else:
                    # Weak baseline attention
                    attention_matrix[i, j] = base_weight

            # Add some recency bias
            if i > 0:
                attention_matrix[i, i-1] += 0.1

            # Boost attention to semantically similar tokens
            for j in range(i):
                if j in important_tokens and i not in important_tokens:
                    sim = _char_sim(tokens[i], tokens[j])
                    if sim > 0.7:
                        attention_matrix[i, j] *= 1.5

    attention_matrix = apply_causal_mask(attention_matrix)
    attention_matrix = make_row_stochastic(attention_matrix)

    return "prog_L21H24", attention_matrix



def prog_L21H25(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Structural boundary detection head: attends to newlines, sentence boundaries, first token, and Unicode artifacts."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L21H25", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        token = tokens[i]

        # Strong self-attention
        attention[i, i] = 0.3

        # Very strong attention to first token
        attention[i, 0] = 0.4

        # Strong attention to newline characters
        for j in range(i + 1):
            if tokens[j].strip() == '' or '\n' in tokens[j]:
                attention[i, j] += 0.6

        # Strong attention to Unicode artifacts/encoding errors
        for j in range(i + 1):
            if any(ord(char) > 127 for char in tokens[j]) and len(tokens[j].strip()) > 0:
                attention[i, j] += 0.7

        # Attention to sentence boundaries (periods, question marks, exclamation marks)
        for j in range(i + 1):
            if tokens[j] in ['.', '?', '!', '."', '?"', '!"']:
                attention[i, j] += 0.2

        # Attention to commas (weaker boundary markers)
        for j in range(i + 1):
            if tokens[j] == ',':
                attention[i, j] += 0.1

        # Special attention patterns for specific structural elements
        current_spacy_indices = token_to_spacy[i]
        if current_spacy_indices:
            current_spacy_token = doc[current_spacy_indices[0]]

            # If current token is a pronoun, attend to potential antecedents
            if current_spacy_token.pos_ == 'PRON':
                for j in range(i):
                    j_spacy_indices = token_to_spacy[j]
                    if j_spacy_indices:
                        j_spacy_token = doc[j_spacy_indices[0]]
                        if j_spacy_token.pos_ in ['NOUN', 'PROPN']:
                            attention[i, j] += 0.1

            # Discourse markers and conjunctions get extra attention to boundaries
            if current_spacy_token.pos_ in ['CCONJ', 'SCONJ'] or current_spacy_token.dep_ == 'cc':
                for j in range(i + 1):
                    if tokens[j].strip() == '' or '\n' in tokens[j] or tokens[j] in ['.', ',']:
                        attention[i, j] += 0.2

        # Recency bias - slight preference for recent tokens
        for j in range(max(0, i - 5), i):
            attention[i, j] += 0.05 * (j - max(0, i - 5) + 1) / 6

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L21H25", attention



def prog_L21H26(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Multi-modal attention head with enhanced sentence-boundary and clause-beginning attention."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L21H26", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        # Self-attention baseline
        attention[i, i] = 0.3

        # First token attention
        if i > 0:
            attention[i, 0] = 0.2

        # Previous token attention (especially for compound words)
        if i > 0:
            prev_token = tokens[i-1].strip()
            curr_token = tokens[i].strip()

            # Strong attention if previous token ends with certain patterns or current starts with certain patterns
            if (len(prev_token) > 0 and prev_token[-1].isalpha() and 
                len(curr_token) > 0 and curr_token[0].isalpha()):
                attention[i, i-1] = 0.4
            else:
                attention[i, i-1] = 0.15

        # Semantic similarity attention
        for j in range(i):
            if j != i-1 and j != 0:  # Skip already handled positions
                sim = _char_sim(tokens[i], tokens[j])
                if sim > 0.5:
                    attention[i, j] = 0.2 * sim
                elif sim > 0.3:
                    attention[i, j] = 0.1 * sim

        # Syntactic relationships via spacy
        if token_to_spacy[i]:
            spacy_idx = token_to_spacy[i][0]
            if spacy_idx < len(doc):
                spacy_token = doc[spacy_idx]

                # Attention to head of current token
                if spacy_token.head != spacy_token:
                    head_char_start = spacy_token.head.idx
                    # Find corresponding LM token
                    for j in range(i):
                        if token_to_spacy[j]:
                            j_spacy_idx = token_to_spacy[j][0]
                            if j_spacy_idx < len(doc) and doc[j_spacy_idx].idx <= head_char_start < doc[j_spacy_idx].idx + len(doc[j_spacy_idx].text):
                                attention[i, j] += 0.15

                # Attention from modifiers to their heads
                for child in spacy_token.children:
                    if child.dep_ in ['amod', 'nmod', 'compound']:
                        child_char_start = child.idx
                        for j in range(i):
                            if token_to_spacy[j]:
                                j_spacy_idx = token_to_spacy[j][0]
                                if j_spacy_idx < len(doc) and doc[j_spacy_idx].idx <= child_char_start < doc[j_spacy_idx].idx + len(doc[j_spacy_idx].text):
                                    attention[i, j] += 0.1

        # Special attention to punctuation and line breaks
        for j in range(i):
            token_j = tokens[j].strip()
            if token_j in ['.', ',', '!', '?', '\n', '"', "'", ':"', '!"']:
                # Distance-based decay for punctuation
                distance = i - j
                if distance <= 5:
                    attention[i, j] += 0.1 / distance
                else:
                    attention[i, j] += 0.02

        # Boost attention for specific patterns observed in examples
        curr_token = tokens[i].strip()

        # Pattern: tokens after conjunctions attend to previous content
        if i > 0 and tokens[i-1].strip() == 'and':
            for j in range(max(0, i-10), i-1):
                attention[i, j] += 0.05

        # Pattern: quoted speech attention
        if '"' in tokens[i] or "'" in tokens[i]:
            for j in range(max(0, i-15), i):
                if any(punct in tokens[j] for punct in ['.', '!', '?', '\n']):
                    attention[i, j] += 0.08

        # NEW: Enhanced sentence/clause boundary attention
        # Find tokens that start new sentences or clauses and boost attention to them
        for j in range(i):
            token_j = tokens[j].strip()
            # Check if token j starts a new sentence/clause (after sentence-ending punctuation or quotes)
            if j > 0:
                prev_j = tokens[j-1].strip()
                if prev_j in ['.', '!', '?', '\n'] or (prev_j == '"' and j > 1 and tokens[j-2].strip() in ['.', '!', '?']):
                    # Token j likely starts a new sentence/clause
                    # Boost attention from current token to this sentence start
                    distance = i - j
                    if distance <= 10:
                        attention[i, j] += 0.3 / max(1, distance * 0.5)
                    else:
                        attention[i, j] += 0.05
            elif j == 0:
                # First token of entire sequence
                # Already handled by first token attention above, but can boost for distant tokens
                if i > 5:
                    attention[i, j] += 0.1

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L21H26", attention



def prog_L21H27(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Boundary and structure attention head with focus on sentence starts and newlines."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        # Base self-attention
        attention[i, i] = 0.1

        # Strong attention to first token
        if i > 0:
            attention[i, 0] = 0.3

        # Strong attention to newlines and sentence boundaries
        for j in range(i + 1):
            if tokens[j].strip() in ['\n', '']:
                attention[i, j] += 0.4
            elif tokens[j].strip() in ['.', '!', '?']:
                attention[i, j] += 0.2

        # Attention to immediately preceding token
        if i > 0:
            attention[i, i-1] += 0.15

        # Syntactic dependencies - verbs attend to their arguments
        spacy_indices = token_to_spacy[i]
        if spacy_indices:
            spacy_token = doc[spacy_indices[0]]

            # If current token is a verb, attend to its subject/object
            if spacy_token.pos_ in ['VERB', 'AUX']:
                for child in spacy_token.children:
                    if child.dep_ in ['nsubj', 'dobj', 'pobj']:
                        # Find corresponding token indices
                        for k in range(i):
                            k_spacy = token_to_spacy[k]
                            if k_spacy and any(idx == child.i for idx in k_spacy):
                                attention[i, k] += 0.2

            # Nouns attend to their modifiers
            if spacy_token.pos_ in ['NOUN', 'PROPN']:
                for child in spacy_token.children:
                    if child.dep_ in ['amod', 'det']:
                        for k in range(i):
                            k_spacy = token_to_spacy[k]
                            if k_spacy and any(idx == child.i for idx in k_spacy):
                                attention[i, k] += 0.15

        # Semantic similarity boost for related tokens
        for j in range(i):
            if _char_sim(tokens[i], tokens[j]) > 0.7:
                attention[i, j] += 0.1

        # Distance decay for non-special tokens
        for j in range(i):
            if tokens[j].strip() not in ['\n', '', '.', '!', '?'] and j != 0:
                distance = i - j
                decay = max(0, 1.0 - 0.1 * distance)
                attention[i, j] *= decay

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L21H27", attention



def prog_L21H28(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Attention head that focuses on sentence boundaries and structural markers like newlines and first tokens."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    # Find newline tokens and first tokens of sentences
    newline_indices = []
    first_token_indices = []

    for i, token in enumerate(tokens):
        if token.strip() == '\n':
            newline_indices.append(i)
        # First token is always at index 0
        if i == 0:
            first_token_indices.append(i)
        # Token after newline is also a "first token"
        elif i > 0 and tokens[i-1].strip() == '\n':
            first_token_indices.append(i)

    for i in range(n):
        # Strong attention to newline characters
        for nl_idx in newline_indices:
            if nl_idx <= i:  # Causal constraint
                attention[i, nl_idx] = 0.3

        # Strong attention to first tokens of sentences
        for ft_idx in first_token_indices:
            if ft_idx <= i:  # Causal constraint
                attention[i, ft_idx] = 0.2

        # Moderate attention to punctuation marks
        for j in range(i + 1):
            if tokens[j].strip() in ['.', ',', '!', '?']:
                attention[i, j] += 0.1

        # Self-attention
        attention[i, i] += 0.05

        # Small baseline attention to all previous tokens
        for j in range(i + 1):
            attention[i, j] += 0.01

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L21H28", attention



def prog_L21H29(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary detection head - attends strongly to the first token and structural markers."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L21H29", np.zeros((n_empty, n_empty))

    attention_matrix = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        token_i = tokens[i]
        spacy_indices_i = token_to_spacy[i]

        # High attention to newlines
        for j in range(i + 1):
            token_j = tokens[j]

            if token_j.strip() == '':  # Newline or whitespace
                if '\n' in token_j:
                    attention_matrix[i, j] += 0.4
                else:
                    attention_matrix[i, j] += 0.1

            # Attention to periods (sentence boundaries)
            elif token_j == '.' or token_j.endswith('.'):
                attention_matrix[i, j] += 0.2

            # First token attention - ENHANCED
            elif j == 0:
                attention_matrix[i, j] += 0.5  # Increased from 0.15 to 0.5

            # Self attention - REDUCED for newlines
            elif i == j:
                if '\n' in token_j:
                    attention_matrix[i, j] += 0.05  # Reduced from 0.1
                else:
                    attention_matrix[i, j] += 0.1

            # Syntactic relationships - prepositions to their objects
            if spacy_indices_i and j < i:
                spacy_indices_j = token_to_spacy[j]
                if spacy_indices_i and spacy_indices_j:
                    spacy_tok_i = doc[spacy_indices_i[0]] if spacy_indices_i else None
                    spacy_tok_j = doc[spacy_indices_j[0]] if spacy_indices_j else None

                    if spacy_tok_i and spacy_tok_j:
                        # Preposition attending to its object
                        if spacy_tok_i.pos_ == 'ADP' and spacy_tok_j.dep_ == 'pobj' and spacy_tok_j.head == spacy_tok_i:
                            attention_matrix[i, j] += 0.15

                        # Verbs attending to their subjects/objects
                        elif spacy_tok_i.pos_ == 'VERB' and spacy_tok_j.dep_ in ['nsubj', 'dobj'] and spacy_tok_j.head == spacy_tok_i:
                            attention_matrix[i, j] += 0.12

                        # Determiners attending to their head nouns
                        elif spacy_tok_i.pos_ == 'DET' and spacy_tok_j.pos_ == 'NOUN' and abs(i - j) <= 2:
                            attention_matrix[i, j] += 0.08

            # Local proximity bias
            if abs(i - j) == 1:
                attention_matrix[i, j] += 0.05

            # Add small baseline attention
            attention_matrix[i, j] += 0.01

    # Apply causal mask and normalize
    attention_matrix = apply_causal_mask(attention_matrix)
    attention_matrix = make_row_stochastic(attention_matrix)

    return "prog_L21H29", attention_matrix



def prog_L21H3(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Structural attention head with strong first-token focus for content and syntactic words."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    # Get spacy alignment for linguistic features
    spacy_alignment = _align_to_spacy(sentence, tokens)
    doc = spacy_parse(sentence)

    for i in range(n):
        # Strong attention to newlines
        for j in range(i + 1):
            if tokens[j].strip() == '' and '\n' in tokens[j]:
                attention[i, j] += 0.4

        # High attention to first token
        if i > 0:
            attention[i, 0] += 0.2

        # Self-attention
        attention[i, i] += 0.1

        # Enhanced first-token attention for content words and important function words
        if i > 0:
            current_spacy = []
            if i < len(spacy_alignment) and spacy_alignment[i]:
                current_spacy = [doc[idx] for idx in spacy_alignment[i] if idx < len(doc)]

            for curr_tok in current_spacy:
                # Strong first-token attention for content words
                if curr_tok.pos_ in ['NOUN', 'VERB', 'ADJ', 'ADV']:
                    attention[i, 0] += 0.5
                # Strong first-token attention for pronouns and important function words
                elif curr_tok.pos_ in ['PRON'] or curr_tok.dep_ in ['nsubj', 'dobj', 'aux']:
                    attention[i, 0] += 0.4
                # Moderate first-token attention for other function words in key positions
                elif curr_tok.pos_ in ['DET', 'ADP'] and curr_tok.dep_ in ['det', 'prep']:
                    attention[i, 0] += 0.3

        # Local dependencies - check for immediate previous token relationships
        if i > 0:
            # Get spacy tokens for current and previous positions
            current_spacy = []
            prev_spacy = []

            if i < len(spacy_alignment) and spacy_alignment[i]:
                current_spacy = [doc[idx] for idx in spacy_alignment[i] if idx < len(doc)]
            if i-1 < len(spacy_alignment) and spacy_alignment[i-1]:
                prev_spacy = [doc[idx] for idx in spacy_alignment[i-1] if idx < len(doc)]

            # Check for syntactic dependencies
            for curr_tok in current_spacy:
                for prev_tok in prev_spacy:
                    if curr_tok.head == prev_tok or prev_tok.head == curr_tok:
                        attention[i, i-1] += 0.3
                    # Function words often attend to content words
                    if (curr_tok.pos_ in ['ADP', 'DET', 'AUX'] and 
                        prev_tok.pos_ in ['NOUN', 'VERB', 'ADJ']):
                        attention[i, i-1] += 0.2

        # Attention to punctuation marks
        for j in range(i + 1):
            if tokens[j] in ['.', '!', '?', ',', ';', ':']:
                attention[i, j] += 0.1

        # Some recency bias for recent tokens
        for j in range(max(0, i-3), i):
            attention[i, j] += 0.05 * (1.0 - (i - j) / 4.0)

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L21H3", attention



def prog_L21H30(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Document structure head with strong beginning-of-document attention."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        # Strong self-attention baseline
        attention[i, i] = 0.3

        # High attention to newlines from subsequent tokens
        for j in range(i):
            if tokens[j].strip() == '':  # newline or whitespace
                attention[i, j] = 0.4

        # Attention to sentence-ending punctuation
        for j in range(i):
            if tokens[j] in ['.', '!', '?']:
                attention[i, j] = 0.2

        # ENHANCED: Much stronger attention to first token of document
        if i > 0:
            # Check if this token has strong semantic or syntactic relationship to document start
            if token_to_spacy[i]:
                spacy_idx = token_to_spacy[i][0]
                if spacy_idx < len(doc):
                    spacy_token = doc[spacy_idx]
                    # Strong attention for verbs, nouns, and content words
                    if spacy_token.pos_ in ['VERB', 'NOUN', 'ADJ', 'PROPN']:
                        attention[i, 0] = 0.4
                    else:
                        attention[i, 0] = 0.25
            else:
                attention[i, 0] = 0.25

        # Local syntactic relationships
        if token_to_spacy[i]:
            spacy_idx = token_to_spacy[i][0]
            if spacy_idx < len(doc):
                spacy_token = doc[spacy_idx]

                # Adjectives attend to their head nouns
                if spacy_token.pos_ == 'ADJ' and spacy_token.head != spacy_token:
                    for j in range(i):
                        if token_to_spacy[j]:
                            head_spacy_idx = token_to_spacy[j][0]
                            if head_spacy_idx < len(doc) and doc[head_spacy_idx] == spacy_token.head:
                                attention[i, j] = 0.15

                # Prepositions attend to their objects
                if spacy_token.pos_ == 'ADP':
                    for child in spacy_token.children:
                        if child.dep_ == 'pobj':
                            for j in range(i):
                                if token_to_spacy[j]:
                                    child_spacy_idx = token_to_spacy[j][0]
                                    if child_spacy_idx < len(doc) and doc[child_spacy_idx] == child:
                                        attention[i, j] = 0.1

        # Previous token attention for some tokens
        if i > 0:
            attention[i, i-1] = 0.05

        # Semantic similarity boost for related tokens
        for j in range(i):
            sim = _char_sim(tokens[i], tokens[j])
            if sim > 0.7:
                attention[i, j] += 0.1 * sim

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L21H30", attention



def prog_L21H31(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Structural boundary attention head with strong beginning-of-sequence attention."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L21H31", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        token = tokens[i]

        # Strong self-attention for all tokens
        attention[i, i] = 1.0

        # High attention to newline tokens
        for j in range(i + 1):
            if tokens[j].strip() == '' and '\n' in tokens[j]:
                attention[i, j] += 0.4

        # Attention to first token (position 0) - enhanced based on token properties
        if i > 0:
            base_first_attention = 0.1

            # Add strong beginning-of-sequence attention for content words and function words
            spacy_indices = token_to_spacy[i]
            if spacy_indices:
                spacy_token = doc[spacy_indices[0]]

                # Content words get much stronger attention to beginning
                if spacy_token.pos_ in ['NOUN', 'VERB', 'ADJ', 'PROPN', 'PRON', 'DET']:
                    base_first_attention += 0.4
                # Other word types get moderate boost
                elif spacy_token.pos_ in ['ADP', 'ADV', 'AUX', 'CONJ', 'CCONJ', 'SCONJ']:
                    base_first_attention += 0.2

            attention[i, 0] += base_first_attention

        # Special boost for certain token types to newlines
        spacy_indices = token_to_spacy[i]
        if spacy_indices:
            spacy_token = doc[spacy_indices[0]]

            # Content words get stronger attention to structural markers
            if spacy_token.pos_ in ['NOUN', 'VERB', 'ADJ', 'PROPN']:
                for j in range(i + 1):
                    if tokens[j].strip() == '' and '\n' in tokens[j]:
                        attention[i, j] += 0.2

            # Pronouns and determiners get moderate attention to boundaries
            if spacy_token.pos_ in ['PRON', 'DET']:
                for j in range(i + 1):
                    if tokens[j].strip() == '' and '\n' in tokens[j]:
                        attention[i, j] += 0.1

        # Some recency bias for nearby tokens
        for j in range(max(0, i - 3), i):
            attention[i, j] += 0.05 * (1.0 - (i - j) / 4.0)

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L21H31", attention



def prog_L21H4(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Structural salience attention head focusing on first tokens and newlines."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L21H4", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        # Base attention pattern
        for j in range(i + 1):  # Causal mask

            # Very strong attention to first token from all positions
            if j == 0:
                # Stronger for early positions, but still significant for later ones
                if i <= 10:
                    attention[i, j] = 5.0
                else:
                    attention[i, j] = 3.5

            # Moderate attention to newlines (reduced from original)
            elif tokens[j] == '\n':
                attention[i, j] = 1.5

            # Moderate attention to proper nouns and important content words
            elif token_to_spacy[j]:
                spacy_indices = token_to_spacy[j]
                is_important = False

                for spacy_idx in spacy_indices:
                    if spacy_idx < len(doc):
                        spacy_token = doc[spacy_idx]
                        if (spacy_token.pos_ in ['PROPN', 'NOUN'] or 
                            spacy_token.ent_type_ in ['PERSON', 'GPE', 'ORG']):
                            is_important = True
                            break

                if is_important:
                    attention[i, j] = 1.0
                else:
                    # Basic recency bias
                    distance = i - j + 1
                    attention[i, j] = 1.0 / distance

            else:
                # Basic recency bias for other tokens
                distance = i - j + 1
                attention[i, j] = 1.0 / distance

        # Self-attention boost
        attention[i, i] = max(attention[i, i], 0.5)

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L21H4", attention



def prog_L21H5(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Attention head that focuses on paragraph boundaries (newlines) and structural markers with strong beginning-of-sequence attention."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention_matrix = np.zeros((n, n))

    for i in range(n):
        current_token = tokens[i].strip()

        # Find newline tokens and sentence-ending punctuation
        newline_indices = []
        punct_indices = []

        for j in range(i + 1):  # Only look at previous tokens (causal)
            token_j = tokens[j].strip()
            if token_j == '\n':
                newline_indices.append(j)
            elif token_j in ['.', '!', '?']:
                punct_indices.append(j)

        # Base attention distribution
        for j in range(i + 1):
            # Self-attention
            if i == j:
                attention_matrix[i, j] = 0.1

            # Strong attention to newlines
            elif tokens[j].strip() == '\n':
                attention_matrix[i, j] = 0.4

            # Moderate attention to sentence-ending punctuation
            elif tokens[j].strip() in ['.', '!', '?']:
                attention_matrix[i, j] = 0.15

            # First token gets some attention
            elif j == 0:
                attention_matrix[i, j] = 0.05

            # Weak recency bias for other tokens
            else:
                recency_weight = 1.0 / (i - j + 1) if i > j else 1.0
                attention_matrix[i, j] = 0.02 * recency_weight

        # Boost attention for tokens that appear to be content words
        # (approximated by length and position)
        for j in range(i + 1):
            if len(tokens[j].strip()) > 3 and tokens[j].strip() not in ['\n', '.', '!', '?', ',', ';', ':']:
                attention_matrix[i, j] *= 1.5

        # NEW: Strong beginning-of-sequence attention pattern
        # Tokens in the middle/end of sequence attend strongly back to the first token
        if i > 5:  # Only for tokens that are reasonably far from the beginning
            attention_matrix[i, 0] = 0.5  # Much stronger attention to first token

        # NEW: Reduce over-predicted attention to punctuation from later tokens
        # Tokens that come after punctuation should have reduced attention to that punctuation
        for j in range(i):
            if tokens[j].strip() in ['.', '!', '?'] and i > j + 2:
                # Significantly reduce attention to punctuation from tokens that come much later
                attention_matrix[i, j] *= 0.1

    # Apply causal mask and normalize
    attention_matrix = apply_causal_mask(attention_matrix)
    attention_matrix = make_row_stochastic(attention_matrix)

    return "prog_L21H5", attention_matrix



def prog_L21H6(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """First-token attention head with position-dependent structural boundary scaling."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L21H6", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Find newline positions
    newline_positions = []
    for i, token in enumerate(tokens):
        if token.strip() == '' and '\n' in token:
            newline_positions.append(i)

    for i in range(n):
        # Position-dependent scaling for first token attention
        # Later positions have stronger attention to first token
        first_token_weight = 0.8 + min(0.3, i * 0.02)
        attention[i, 0] = first_token_weight

        # Enhanced newline attention with position-dependent scaling
        for nl_pos in newline_positions:
            if nl_pos <= i:  # causal constraint
                # Tokens further from newlines have stronger attention to them
                distance_from_nl = i - nl_pos
                nl_weight = 0.3 + min(0.4, distance_from_nl * 0.03)
                attention[i, nl_pos] = nl_weight

        # Small self-attention
        attention[i, i] = 0.1

        # Very small uniform attention to other positions
        for j in range(i + 1):
            if j != 0 and j not in newline_positions and j != i:
                attention[i, j] = 0.05

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L21H6", attention



def prog_L21H7(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """First-token and paragraph boundary attention head with semantic similarity component."""
    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention_matrix = np.zeros((n, n))

    for i in range(n):
        # Base attention distribution
        for j in range(i + 1):  # Causal mask
            # Very high attention to first token
            if j == 0:
                attention_matrix[i, j] = 10.0
            # High attention to newline characters (paragraph boundaries)
            elif tokens[j] == '\n':
                attention_matrix[i, j] = 5.0
            # Self-attention
            elif i == j:
                attention_matrix[i, j] = 0.5
            # Semantic similarity component
            else:
                sim = _char_sim(tokens[i], tokens[j])
                if sim > 0.7:  # High similarity threshold
                    attention_matrix[i, j] = 2.0 * sim
                elif sim > 0.5:  # Medium similarity threshold
                    attention_matrix[i, j] = 0.5 * sim
                else:
                    attention_matrix[i, j] = 0.1

    # Apply causal mask and normalize
    attention_matrix = apply_causal_mask(attention_matrix)
    attention_matrix = make_row_stochastic(attention_matrix)

    return "prog_L21H7", attention_matrix



def prog_L21H8(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Structural boundary attention: focuses on newlines, punctuation, and first token."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L21H8", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        # Strong self-attention for first token
        if i == 0:
            attention[i, i] = 1.0
            continue

        # Initialize with small uniform attention
        for j in range(i + 1):
            attention[i, j] = 0.01

        # High attention to newlines
        for j in range(i + 1):
            if tokens[j] == '\n':
                attention[i, j] += 0.3

        # High attention to punctuation (periods, exclamation marks)
        for j in range(i + 1):
            if tokens[j] in ['.', '!', '?']:
                attention[i, j] += 0.2

        # Strong attention to first token from all positions
        attention[i, 0] += 0.15

        # Moderate self-attention
        attention[i, i] += 0.1

        # Slight recency bias - more attention to recent tokens
        for j in range(max(0, i - 5), i + 1):
            distance = i - j
            if distance > 0:
                attention[i, j] += 0.05 / (1 + distance * 0.5)

        # Attention to tokens immediately before punctuation
        for j in range(i):
            if j + 1 < n and tokens[j + 1] in ['.', '!', '?', ',']:
                attention[i, j] += 0.1

        # Boost attention to tokens that are quotation marks or similar structural markers
        for j in range(i + 1):
            if tokens[j] in ['"', "'", '(', ')', '[', ']']:
                attention[i, j] += 0.1

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L21H8", attention



def prog_L21H9(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Self-attention with first-token and structural boundary (newline) attention."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L21H9", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Find newline positions
    newline_positions = [i for i in range(n) if tokens[i].strip() == '\n']

    for i in range(n):
        # Strong self-attention for all tokens
        attention[i, i] = 1.0

        # Strong first-token attention for most tokens
        if i > 0:
            attention[i, 0] = 0.4

        # Attention to newlines for tokens after them
        for nl_pos in newline_positions:
            if i > nl_pos:
                attention[i, nl_pos] = 0.3

        # Moderate attention to previous token
        if i > 0:
            attention[i, i-1] = 0.2

        # Lower attention to sentence-ending punctuation
        for j in range(i):
            if tokens[j] in ['.', '!', '?']:
                attention[i, j] = 0.1

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L21H9", attention



def prog_L2H0(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Structural attention head with strong first-token attention and reduced self-attention."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L2H0", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    for i in range(n):
        token = tokens[i]

        # Reduced self-attention for pronouns and some content words
        if i < len(tokens):
            doc = spacy_parse(sentence)
            token_to_spacy = _align_to_spacy(sentence, tokens)

            if token_to_spacy[i]:
                spacy_token = doc[token_to_spacy[i][0]]
                if spacy_token.pos_ in ['PRON', 'NOUN', 'PROPN']:
                    attention[i, i] += 0.1  # Reduced from 0.3

        # High attention to sentence boundaries (newlines and periods)
        for j in range(i + 1):
            if tokens[j] in ['\n', '.', '!', '?']:
                attention[i, j] += 0.4

        # Much stronger attention to first token of sentence
        if i > 0:
            attention[i, 0] += 0.6  # Increased from 0.2

        # Additional attention based on token similarity
        for j in range(i + 1):
            if i != j:
                sim = _char_sim(tokens[i], tokens[j])
                if sim > 0.7:
                    attention[i, j] += 0.1 * sim

        # Decay with distance for nearby tokens
        for j in range(max(0, i-3), i):
            distance = i - j
            attention[i, j] += 0.05 / (distance + 1)

    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L2H0", attention



def prog_L2H1(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary anchor attention: tokens attend strongly to nearby sentence delimiters (newlines, periods)."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L2H1", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Identify sentence boundary tokens
    boundary_tokens = set()
    for i, token in enumerate(tokens):
        if token.strip() in ['.', '!', '?', '\n']:
            boundary_tokens.add(i)

    for i in range(n):
        # Find the most recent boundary token in causal window
        recent_boundary = None
        for j in range(i + 1):  # causal window: 0 to i
            if j in boundary_tokens:
                recent_boundary = j

        if recent_boundary is not None:
            # Strong attention to most recent boundary
            attention[i, recent_boundary] = 0.7

            # Medium attention to other boundaries in window
            for j in range(i + 1):
                if j in boundary_tokens and j != recent_boundary:
                    attention[i, j] = 0.1

        # Some attention to nearby tokens
        for j in range(max(0, i-3), i + 1):
            if j not in boundary_tokens:
                distance = i - j + 1
                attention[i, j] += 0.05 / distance

        # Self attention if no boundaries found
        if recent_boundary is None:
            attention[i, i] = 0.3
            # Distribute remaining to nearby tokens
            for j in range(max(0, i-2), i + 1):
                if j != i:
                    attention[i, j] = 0.1

    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L2H1", attention



def prog_L2H10(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Attends primarily to newlines and periods, with some first-token attention."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention_matrix = np.zeros((n, n))

    for i in range(n):
        # Base attention to all previous tokens (including self)
        for j in range(i + 1):
            # Very high attention to newlines and periods
            if tokens[j] == '\n':
                attention_matrix[i, j] = 0.4
            elif tokens[j] == '.':
                attention_matrix[i, j] = 0.35
            # Moderate attention to first token
            elif j == 0:
                attention_matrix[i, j] = 0.1
            # Low baseline attention to other tokens
            else:
                attention_matrix[i, j] = 0.02

    # Apply causal mask and normalize
    attention_matrix = apply_causal_mask(attention_matrix)
    attention_matrix = make_row_stochastic(attention_matrix)

    return "prog_L2H10", attention_matrix



def prog_L2H11(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary and structure tracking head with first-token bias."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    # Identify sentence boundary markers
    boundary_markers = set()
    for i, token in enumerate(tokens):
        if token.strip() in ['.', '!', '?', '\n', '\\n']:
            boundary_markers.add(i)

    for i in range(n):
        current_token = tokens[i].strip()

        # Strong self-attention for first token
        if i == 0:
            attention[i, i] = 1.0
            continue

        # Find most recent sentence boundary
        recent_boundary = -1
        for j in range(i-1, -1, -1):
            if j in boundary_markers:
                recent_boundary = j
                break

        # Base attention distribution
        for j in range(i + 1):  # Only attend to previous positions
            token_j = tokens[j].strip()

            # Strong attention to first token
            if j == 0:
                attention[i, j] += 3.0

            # High attention to sentence boundaries (newlines, periods)
            if j in boundary_markers:
                if token_j in ['\n', '\\n']:
                    attention[i, j] += 4.0
                elif token_j in ['.', '!', '?']:
                    attention[i, j] += 3.5

            # Moderate attention to most recent boundary
            if j == recent_boundary and recent_boundary >= 0:
                attention[i, j] += 2.0

            # Small recency bias
            distance = i - j
            if distance <= 3:
                attention[i, j] += 1.0 / (distance + 1)

            # Small self-attention
            if i == j:
                attention[i, j] += 0.5

        # Boost attention for tokens that might be sentence starters
        if len(token_to_spacy[i]) > 0:
            spacy_idx = token_to_spacy[i][0]
            if spacy_idx < len(doc):
                spacy_token = doc[spacy_idx]
                # Look for sentence-initial patterns
                if spacy_token.is_sent_start or (spacy_token.pos_ in ['PROPN', 'PRON'] and spacy_token.text.istitle()):
                    # Boost attention to boundaries
                    for j in boundary_markers:
                        if j <= i:
                            attention[i, j] += 1.5

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L2H11", attention



def prog_L2H12(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Delimiter/boundary attention head focusing on newlines, periods, and first tokens."""
    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L2H12", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    for i in range(n):
        # Find delimiter tokens (newlines and periods)
        delimiter_indices = []
        first_token_idx = 0

        for j in range(i + 1):  # causal mask
            token = tokens[j].strip()
            if token == '\n' or token == '.':
                delimiter_indices.append(j)

        # Base attention distribution
        if delimiter_indices:
            # Strong attention to delimiters
            for delim_idx in delimiter_indices:
                # Stronger attention to more recent delimiters
                recency_boost = 1.0 - (i - delim_idx) * 0.1
                attention[i, delim_idx] = max(0.3, recency_boost)

        # Moderate attention to first token
        if i > 0:
            attention[i, first_token_idx] = 0.2

        # Self-attention for first token and delimiter tokens
        token_text = tokens[i].strip()
        if i == 0 or token_text == '\n' or token_text == '.':
            attention[i, i] = 0.5

        # Small baseline attention to recent tokens
        for j in range(max(0, i - 5), i):
            if attention[i, j] == 0:
                distance = i - j
                attention[i, j] = 0.05 / (distance + 1)

    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L2H12", attention



def prog_L2H13(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary and first-token attention head."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L2H13", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Identify sentence boundary tokens and first tokens
    boundary_tokens = set()
    first_tokens = set()

    for i, token in enumerate(tokens):
        # Mark punctuation and newlines as boundaries
        if token.strip() in ['.', '!', '?', '\n'] or token == '\n':
            boundary_tokens.add(i)

        # Mark first token and tokens after boundaries as first tokens
        if i == 0:
            first_tokens.add(i)
        elif i > 0 and tokens[i-1].strip() in ['.', '!', '?', '\n']:
            first_tokens.add(i)

    for i in range(n):
        # Very high attention to first token of sequence
        if 0 in first_tokens:
            attention[i, 0] = 3.0

        # High attention to sentence boundary tokens (newlines, periods)
        for j in boundary_tokens:
            if j <= i:
                attention[i, j] = 2.0

        # Medium attention to other first tokens
        for j in first_tokens:
            if j <= i and j != 0:
                attention[i, j] = 1.0

        # Self-attention baseline
        attention[i, i] = 0.5

        # Small attention to adjacent tokens
        if i > 0:
            attention[i, i-1] = 0.3

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L2H13", attention



def prog_L2H14(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary and structure detection head with strong attention to newlines, periods, and first tokens."""
    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    # Parse sentence to get linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    # Identify structural tokens
    newlines = set()
    periods = set()
    first_tokens = set()

    for i, token in enumerate(tokens):
        if token.strip() == '':  # whitespace/newline tokens
            newlines.add(i)
        elif token.strip() == '.':
            periods.add(i)

    # Find first tokens after newlines/sentence boundaries
    for i in range(n):
        if i == 0:  # very first token
            first_tokens.add(i)
        elif i > 0 and (i-1 in newlines or tokens[i-1].strip() == '.'):
            # Token after newline or period
            first_tokens.add(i)

    for i in range(n):
        for j in range(i + 1):  # causal mask
            weight = 0.01  # base weight

            # Very strong self-attention for periods
            if i == j and j in periods:
                weight = 0.6

            # Strong attention to newlines from most tokens
            elif j in newlines:
                weight = 0.45

            # Strong attention to periods from most tokens
            elif j in periods:
                weight = 0.38

            # Strong attention to first tokens
            elif j in first_tokens and i != j:
                weight = 0.25

            # Some self-attention for other tokens
            elif i == j:
                weight = 0.08

            # Moderate attention between adjacent tokens
            elif abs(i - j) == 1:
                weight = 0.15

            # Small boost for tokens that are similar
            elif j < i:
                sim = _char_sim(tokens[i], tokens[j])
                if sim > 0.5:
                    weight += 0.05

            attention[i, j] = weight

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L2H14", attention



def prog_L2H15(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Structural punctuation attention head focusing on newlines and periods with semantic similarity."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    for i in range(n):
        token_i = tokens[i].strip()

        for j in range(i + 1):  # Causal mask
            token_j = tokens[j].strip()
            weight = 0.01  # Base weight

            # Very high attention to newlines and periods
            if token_j == '\n':
                weight = 0.4
            elif token_j == '.':
                weight = 0.35

            # Self-attention gets moderate boost
            elif i == j:
                weight = 0.05

            # High attention from various tokens to first token
            elif j == 0:
                weight = 0.15

            # Moderate attention to commas
            elif token_j == ',':
                weight = 0.08

            # Semantic similarity boost
            else:
                sim = _char_sim(tokens[i], tokens[j])
                if sim > 0.7:
                    weight += 0.1 * sim
                elif sim > 0.5:
                    weight += 0.05 * sim

            # Distance decay for non-structural tokens
            if token_j not in ['\n', '.', ','] and j != 0 and i != j:
                distance = i - j
                weight *= max(0.1, 1.0 / (1.0 + 0.3 * distance))

            attention[i, j] = weight

    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L2H15", attention



def prog_L2H16(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Discourse structure head: attends to sentence boundaries (periods, newlines) and first token."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L2H16", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Find sentence boundary tokens (periods and newlines)
    boundary_indices = []
    for i, token in enumerate(tokens):
        if token.strip() in ['.', '\n']:
            boundary_indices.append(i)

    # First token index
    first_token_idx = 0

    for i in range(n):
        # Base attention to accessible positions
        for j in range(i + 1):
            # Strong attention to sentence boundaries
            if j in boundary_indices:
                if tokens[j].strip() == '\n':
                    attention[i, j] = 0.6
                elif tokens[j].strip() == '.':
                    attention[i, j] = 0.4

            # Strong attention to first token
            elif j == first_token_idx:
                attention[i, j] = 0.3

            # Moderate self-attention
            elif i == j:
                attention[i, j] = 0.2

            # Weak attention to recent tokens
            elif i - j <= 3:
                attention[i, j] = 0.1 / (1 + i - j)

            # Very weak baseline attention
            else:
                attention[i, j] = 0.05

        # Boost attention for tokens that are themselves boundaries
        if i in boundary_indices:
            # Boundary tokens attend more strongly to themselves
            attention[i, i] = 0.8

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L2H16", attention



def prog_L2H17(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary and structural punctuation attention head with sentence-opening verb attention."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L2H17", np.zeros((n_empty, n_empty))

    # Get spacy features for linguistic analysis
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    attention = np.zeros((n, n))

    # Detect if first token is a dialogue/narrative introducing verb
    first_token_is_speech_verb = False
    if n > 0 and token_to_spacy[0]:
        first_spacy_token = doc[token_to_spacy[0][0]]
        if first_spacy_token.pos_ == 'VERB' and first_spacy_token.lemma_ in ['say', 'ask', 'tell', 'call', 'shout', 'whisper', 'reply', 'answer']:
            first_token_is_speech_verb = True

    for i in range(n):
        for j in range(i + 1):  # causal mask
            weight = 0.0

            # Very high attention to newlines and periods
            if tokens[j] == '\n':
                weight += 0.4
            elif tokens[j] == '.':
                weight += 0.35

            # High attention to first token
            if j == 0:
                weight += 0.15
                # ADDED: Extra boost if first token is a speech verb
                if first_token_is_speech_verb:
                    weight += 0.25

            # Self-attention gets a small boost (reduced from original)
            if i == j:
                weight += 0.03

            # Moderate attention to other punctuation
            if tokens[j] in [',', '!', '?', '"', "'", '(', ')']:
                weight += 0.1

            # Small recency bias for recent tokens
            if i - j <= 3:
                weight += 0.02 * (4 - (i - j)) / 4

            # Base attention for all positions
            weight += 0.01

            attention[i, j] = weight

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L2H17", attention



def prog_L2H18(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary and structural marker attention head."""
    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    if n == 0:
        return "prog_L2H18", attention

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    alignment = _align_to_spacy(sentence, tokens)

    # Identify structural markers (newlines, periods)
    structural_markers = []
    for i, token in enumerate(tokens):
        if token.strip() in ['\n', '.', '!', '?']:
            structural_markers.append(i)

    # Find sentence starts (tokens after newlines or at beginning)
    sentence_starts = [0]
    for i, token in enumerate(tokens):
        if token.strip() == '\n' and i + 1 < n:
            sentence_starts.append(i + 1)

    for i in range(n):
        token = tokens[i].strip()

        # Find which sentence this token belongs to
        current_sentence_start = 0
        for start in sentence_starts:
            if start <= i:
                current_sentence_start = start
            else:
                break

        # Base attention distribution
        for j in range(i + 1):  # Causal mask
            # Strong attention to structural markers
            if j in structural_markers:
                if tokens[j].strip() == '\n':
                    attention[i, j] = 0.4
                elif tokens[j].strip() in ['.', '!', '?']:
                    attention[i, j] = 0.35

            # Strong attention to sentence start
            elif j == current_sentence_start and j != i:
                attention[i, j] = 0.2

            # Self-attention for punctuation
            elif i == j and token in ['.', '!', '?']:
                attention[i, j] = 0.6

            # Local dependencies
            elif j == i - 1:  # Previous token
                attention[i, j] = 0.1
            elif j == i:  # Self-attention
                attention[i, j] = 0.05

            # Syntactic relationships using spacy
            elif alignment[i] and alignment[j]:
                spacy_i = alignment[i][0] if alignment[i] else None
                spacy_j = alignment[j][0] if alignment[j] else None

                if spacy_i is not None and spacy_j is not None and spacy_i < len(doc) and spacy_j < len(doc):
                    spacy_token_i = doc[spacy_i]
                    spacy_token_j = doc[spacy_j]

                    # Head-dependent relationships
                    if spacy_token_i.head.i == spacy_j:
                        attention[i, j] = 0.08
                    elif spacy_token_j.head.i == spacy_i:
                        attention[i, j] = 0.06

            # Weak baseline attention
            else:
                attention[i, j] = 0.02

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L2H18", attention



def prog_L2H19(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary and discourse structure attention head."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    # Find structural tokens (newlines, periods, sentence starts)
    newline_indices = []
    period_indices = []
    sentence_start_indices = []

    for i, token in enumerate(tokens):
        if token.strip() == '\n':
            newline_indices.append(i)
        elif token.strip() == '.':
            period_indices.append(i)

        # Find sentence starts (tokens after newlines/periods or first token)
        if i == 0:
            sentence_start_indices.append(i)
        elif i > 0 and (tokens[i-1].strip() in ['\n', '.', '!', '?']):
            sentence_start_indices.append(i)

    for i in range(n):
        # Base uniform attention to all previous positions
        for j in range(i + 1):
            attention[i, j] = 0.01

        # Strong attention to newlines
        for newline_idx in newline_indices:
            if newline_idx <= i:
                attention[i, newline_idx] += 0.4

        # Strong attention to periods
        for period_idx in period_indices:
            if period_idx <= i:
                attention[i, period_idx] += 0.35

        # Moderate attention to sentence starts
        for start_idx in sentence_start_indices:
            if start_idx <= i and start_idx != i:
                attention[i, start_idx] += 0.15

        # Self-attention for structural tokens
        if tokens[i].strip() in ['.', '\n']:
            attention[i, i] += 0.3

        # Slight recency bias for recent tokens
        for j in range(max(0, i-5), i):
            attention[i, j] += 0.05 * (1.0 - (i - j) / 6.0)

        # Small boost for first few tokens
        for j in range(min(3, i + 1)):
            attention[i, j] += 0.05

    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L2H19", attention



def prog_L2H2(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Structural boundary attention: focuses on periods, newlines, and first tokens."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L2H2", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        # Base attention distribution
        for j in range(i + 1):  # Only attend to previous tokens (causal)

            # Very high attention to periods
            if tokens[j].strip() == '.':
                attention[i, j] += 0.35

            # High attention to newlines
            elif tokens[j].strip() == '\n':
                attention[i, j] += 0.35

            # Strong first-token attention, especially for early tokens
            elif j == 0:
                # Higher for tokens near beginning of sentence
                if i <= 3:
                    attention[i, j] += 0.9
                else:
                    attention[i, j] += 0.15

            # Self-attention for punctuation
            elif i == j and tokens[i].strip() in '.,!?;:':
                attention[i, j] += 0.4

            # Moderate attention to other punctuation
            elif tokens[j].strip() in ',!?;:':
                attention[i, j] += 0.1

            # Small baseline attention
            else:
                attention[i, j] += 0.02

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L2H2", attention



def prog_L2H20(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary attention head that focuses strongly on the first token, with secondary attention to periods and newlines."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L2H20", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Identify sentence boundaries and structural tokens
    periods = set()
    newlines = set()
    first_token_idx = 0

    for i, token in enumerate(tokens):
        if token.strip() == '.':
            periods.add(i)
        elif token.strip() == '\n':
            newlines.add(i)

    # Get spacy alignment for linguistic features
    try:
        doc = spacy_parse(sentence)
        token_to_spacy = _align_to_spacy(sentence, tokens)
    except:
        token_to_spacy = [[] for _ in range(n)]

    for i in range(n):
        # Strong self-attention for first token
        if i == first_token_idx:
            attention[i, i] = 1.0
            continue

        # Primary pattern: Strong attention to first token
        attention[i, first_token_idx] = 0.7
        remaining_weight = 0.3

        # Secondary attention to sentence boundaries (periods and newlines)
        boundary_weight = 0.0
        for j in range(i + 1):  # causal mask
            if j in periods:
                attention[i, j] += 0.15
                boundary_weight += 0.15
            elif j in newlines:
                attention[i, j] += 0.12
                boundary_weight += 0.12

        # Reduce remaining weight by boundary attention
        remaining_weight = max(0.0, remaining_weight - boundary_weight)

        # Distribute remaining attention with recency bias, but much reduced self-attention
        if remaining_weight > 0:
            for j in range(i + 1):
                if j not in periods and j not in newlines and j != first_token_idx:
                    if j == i:
                        # Much smaller self-attention
                        attention[i, j] += remaining_weight * 0.2
                    else:
                        # Exponential decay with distance
                        distance = i - j + 1
                        weight = remaining_weight * 0.8 * (0.7 ** distance)
                        attention[i, j] += weight

        # Boost for syntactically related tokens
        if token_to_spacy[i]:
            spacy_token = doc[token_to_spacy[i][0]]
            # Attend to syntactic head
            if spacy_token.head != spacy_token:
                for j in range(i):
                    if token_to_spacy[j] and any(doc[k] == spacy_token.head for k in token_to_spacy[j]):
                        attention[i, j] *= 1.1
                        break

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L2H20", attention



def prog_L2H21(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Structural attention head with strong focus on sentence beginnings and document structure."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        return "prog_L2H21", np.zeros((0, 0))

    attention = np.zeros((n, n))

    # Find positions of structural elements
    newline_positions = [i for i, token in enumerate(tokens) if token.strip() == '\n']
    period_positions = [i for i, token in enumerate(tokens) if token.strip() == '.']
    first_token_pos = 0

    for i in range(n):
        # Base self-attention
        attention[i, i] = 0.1

        # Strong attention to newlines
        for newline_pos in newline_positions:
            if newline_pos <= i:
                attention[i, newline_pos] = 0.4

        # Strong attention to periods  
        for period_pos in period_positions:
            if period_pos <= i:
                attention[i, period_pos] = 0.35

        # Much stronger attention to first token - this is the key pattern
        if i > 0:  # Don't modify self-attention for first token
            attention[i, first_token_pos] = 0.8

        # Local attention to previous few tokens
        for j in range(max(0, i-3), i):
            if j not in newline_positions and j not in period_positions and j != first_token_pos:
                attention[i, j] = 0.05

        # Slight boost for tokens that are syntactically important
        doc = spacy_parse(sentence)
        token_to_spacy = _align_to_spacy(sentence, tokens)

        if i < len(token_to_spacy) and token_to_spacy[i]:
            spacy_idx = token_to_spacy[i][0]
            if spacy_idx < len(doc):
                spacy_token = doc[spacy_idx]

                # Boost attention to syntactic heads
                if spacy_token.head.idx != spacy_token.idx:
                    spacy_to_token = align_spacy_to_tokens(sentence)
                    if spacy_token.head.i < len(spacy_to_token) and spacy_to_token[spacy_token.head.i]:
                        head_token_idx = spacy_to_token[spacy_token.head.i][0]
                        if head_token_idx <= i:
                            attention[i, head_token_idx] += 0.1

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L2H21", attention



def prog_L2H22(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Structural attention head focusing on sentence boundaries, newlines, periods, and first tokens with strong attention to early structural markers."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L2H22", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    for i in range(n):
        for j in range(i + 1):  # causal mask
            weight = 0.01  # base weight

            # Very high attention to first token
            if j == 0:
                weight += 0.7

            # High attention to newlines
            if tokens[j] == '\n':
                weight += 0.4

            # High attention to periods
            if tokens[j] == '.':
                weight += 0.3

            # Self-attention boost
            if i == j:
                weight += 0.2

            # Recency bias - prefer recent tokens
            distance = i - j
            if distance <= 3:
                weight += 0.15 / (distance + 1)

            # Boost for commas and other punctuation
            if tokens[j] in [',', '!', '?', ';', ':']:
                weight += 0.1

            # Small boost for embedding similarity
            if i != j:
                sim = _char_sim(tokens[i], tokens[j])
                weight += 0.05 * max(0, sim)

            # NEW: Strong attention to early structural boundaries from later positions
            if i > 10 and j <= 5:  # From tokens after position 10 to early positions
                if tokens[j] == '\n':
                    weight += 0.35  # Additional boost for early newlines
                elif tokens[j] == '.':
                    weight += 0.25  # Additional boost for early periods

            attention[i, j] = weight

    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L2H22", attention



def prog_L2H23(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary and punctuation attention with strong newline preference."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    # Find key structural tokens
    newline_indices = [i for i, token in enumerate(tokens) if token.strip() == '\n']
    period_indices = [i for i, token in enumerate(tokens) if token.strip() == '.']
    first_token_idx = 0

    for i in range(n):
        current_token = tokens[i].strip()

        if i == 0:
            # First token attends to itself
            attention[i, i] = 1.0
        else:
            # Find nearest preceding newline
            nearest_newline = None
            for n_idx in newline_indices:
                if n_idx < i:
                    nearest_newline = n_idx

            # If there's a preceding newline, it gets very strong attention
            if nearest_newline is not None:
                attention[i, nearest_newline] = 0.7
                # Reduce attention to first token when newline is present
                attention[i, first_token_idx] = 0.2
            else:
                # Base attention to first token (when no newline)
                attention[i, first_token_idx] = 0.8

            # High attention to nearest preceding period
            nearest_period = None
            for p_idx in period_indices:
                if p_idx < i:
                    nearest_period = p_idx

            if nearest_period is not None:
                if nearest_newline is not None:
                    # Reduced period attention when newline is present
                    attention[i, nearest_period] = 0.2
                else:
                    attention[i, nearest_period] = 0.6

            # Lower attention to immediately previous token
            attention[i, i-1] = 0.1

            # Very low self-attention
            attention[i, i] = 0.05

            # Special case: if current token is a space or newline after period
            if current_token == '' and i > 0 and tokens[i-1].strip() == '.':
                attention[i, i-1] = 0.7  # Strong attention to the period

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L2H23", attention



def prog_L2H24(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary and structure head: attends strongly to first tokens and structural punctuation."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L2H24", np.zeros((n_empty, n_empty))

    attention_matrix = np.zeros((n, n))

    # Find special structural tokens
    first_token_idx = 0
    newline_indices = [i for i, token in enumerate(tokens) if token.strip() == '\n']
    period_indices = [i for i, token in enumerate(tokens) if token.strip() == '.']

    for i in range(n):
        current_token = tokens[i].strip()

        # Self-attention for punctuation
        if current_token in ['.', '!', '?', ',', ';']:
            attention_matrix[i, i] = 0.6

        # Strong attention to first token from early sentence tokens (positions 1-5)
        if 1 <= i <= 5 and i != first_token_idx:
            attention_matrix[i, first_token_idx] = 0.97

        # NEW: Extended first-token attention for later positions
        # Many tokens throughout the sequence attend strongly to the first token
        if i > 5 and i != first_token_idx:
            # Strong attention to first token, with slight decay for very distant tokens
            base_weight = 0.95
            if i > 20:
                base_weight = 0.90
            attention_matrix[i, first_token_idx] = base_weight

        # Moderate attention to newlines from many positions
        for nl_idx in newline_indices:
            if nl_idx <= i and nl_idx != i:
                attention_matrix[i, nl_idx] = 0.42

        # Moderate attention to periods from many positions  
        for period_idx in period_indices:
            if period_idx <= i and period_idx != i:
                attention_matrix[i, period_idx] = 0.38

        # Special case: newlines often attend to first token
        if current_token == '\n' and first_token_idx != i:
            attention_matrix[i, first_token_idx] = 0.35

        # Low baseline attention to previous few tokens
        for j in range(max(0, i-3), i):
            if attention_matrix[i, j] < 0.1:  # Don't override higher weights
                attention_matrix[i, j] = 0.02

    # Apply causal mask and normalize
    attention_matrix = apply_causal_mask(attention_matrix)
    attention_matrix = make_row_stochastic(attention_matrix)

    return "prog_L2H24", attention_matrix



def prog_L2H25(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary attention head with context-dependent self-attention reduction."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention_matrix = np.zeros((n, n))

    # Find structural tokens
    newline_indices = []
    period_indices = []

    for i, token in enumerate(tokens):
        if token.strip() == '\n' or token == '\n':
            newline_indices.append(i)
        elif token.strip() == '.' or token == '.':
            period_indices.append(i)

    for i in range(n):
        # Base attention distribution
        base_attention = np.zeros(i + 1)  # Can only attend to previous tokens + self

        # Strong attention to newlines
        for nl_idx in newline_indices:
            if nl_idx <= i:
                base_attention[nl_idx] = 0.6

        # Moderate attention to periods  
        for p_idx in period_indices:
            if p_idx <= i:
                base_attention[p_idx] = 0.3

        # Attention to first token
        if i > 0:
            base_attention[0] = 0.2

        # Context-dependent self-attention
        if i == 0:
            base_attention[0] = 1.0
        else:
            # Reduce self-attention when there are strong structural cues available
            has_strong_structural_cues = False
            for nl_idx in newline_indices:
                if nl_idx <= i and base_attention[nl_idx] > 0:
                    has_strong_structural_cues = True
                    break
            if not has_strong_structural_cues:
                for p_idx in period_indices:
                    if p_idx <= i and base_attention[p_idx] > 0:
                        has_strong_structural_cues = True
                        break

            # Much lower self-attention when structural cues are present
            if has_strong_structural_cues:
                base_attention[i] = 0.01
            else:
                base_attention[i] = 0.1

        # Add small uniform attention to all available positions
        uniform_weight = 0.05
        for j in range(i + 1):
            base_attention[j] += uniform_weight

        # Normalize
        if base_attention.sum() > 0:
            base_attention = base_attention / base_attention.sum()
        else:
            # Fallback: uniform attention
            base_attention = np.ones(i + 1) / (i + 1)

        attention_matrix[i, :i+1] = base_attention

    attention_matrix = apply_causal_mask(attention_matrix)
    attention_matrix = make_row_stochastic(attention_matrix)

    return "prog_L2H25", attention_matrix



def prog_L2H26(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Structural boundary detection head: attends to first token, newlines, and periods with positional decay and enhanced long-range period attention."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    for i in range(n):
        # Strong attention to first token
        if n > 0:
            attention[i, 0] = 0.8

        # High attention to newline characters
        for j in range(i + 1):
            if tokens[j] == '\n':
                # Distance-based decay from newline
                distance = i - j
                attention[i, j] = max(0.4, 0.6 - 0.02 * distance)

        # Moderate attention to periods
        for j in range(i + 1):
            if tokens[j] == '.':
                distance = i - j
                attention[i, j] = max(0.2, 0.4 - 0.015 * distance)

        # Enhanced long-range period attention for tokens in later parts of sentences
        for j in range(i + 1):
            if tokens[j] == '.':
                # Check if we're in a later part of the sequence (beyond the immediate context)
                if i > j + 20:  # For tokens well beyond the period
                    # Apply stronger attention that doesn't decay as much
                    base_attention = 0.42
                    decay_rate = 0.002  # Much slower decay
                    distance = i - j
                    enhanced_attention = max(0.35, base_attention - decay_rate * distance)
                    attention[i, j] = max(attention[i, j], enhanced_attention)

        # Self-attention for first token
        if i == 0:
            attention[i, i] = 1.0

        # Small baseline attention to recent tokens
        for j in range(max(0, i - 10), i + 1):
            if attention[i, j] < 0.1:
                distance = i - j
                attention[i, j] += max(0.01, 0.05 - 0.005 * distance)

    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L2H26", attention



def prog_L2H27(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Structural boundary and segment-beginning attention head."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L2H27", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Parse with spacy to get linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        # Initialize weights
        weights = np.zeros(i + 1)  # Can only attend to tokens 0..i

        # Very high attention to punctuation that marks boundaries
        for j in range(i + 1):
            token_j = tokens[j].strip()

            # High attention to periods and newlines (structural boundaries)
            if token_j in ['.', '\n']:
                weights[j] += 1.5

            # Medium attention to other punctuation
            elif token_j in [',', '!', '?', ';', ':']:
                weights[j] += 0.8

        # High attention to first token
        if i >= 0:
            weights[0] += 1.2

        # Attention to tokens that start new segments (after newlines/periods)
        for j in range(1, i + 1):
            prev_token = tokens[j-1].strip()
            if prev_token in ['.', '\n']:
                weights[j] += 1.0

        # Self-attention component
        weights[i] += 0.3

        # Check for linguistic boundaries using spacy
        if token_to_spacy[i]:
            spacy_idx = token_to_spacy[i][0]
            if spacy_idx < len(doc):
                spacy_token = doc[spacy_idx]

                # Higher attention to sentence beginnings
                if spacy_token.is_sent_start:
                    weights[i] += 0.5

                # Look for tokens that start sentences/clauses
                for j in range(i + 1):
                    if token_to_spacy[j] and token_to_spacy[j][0] < len(doc):
                        j_spacy = doc[token_to_spacy[j][0]]
                        if j_spacy.is_sent_start or (j_spacy.dep_ == 'ROOT'):
                            weights[j] += 0.6

        # Add small baseline attention to recent tokens
        for j in range(max(0, i-5), i + 1):
            weights[j] += 0.1

        # Normalize and assign
        if weights.sum() > 0:
            attention[i, :i+1] = weights / weights.sum()
        else:
            attention[i, i] = 1.0

    # Ensure proper constraints
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L2H27", attention



def prog_L2H28(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Boundary detection head attending to sentence endings, newlines, and first token."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    # Find structural tokens
    newline_indices = []
    period_indices = []

    for i, token in enumerate(tokens):
        if token.strip() == '\n':
            newline_indices.append(i)
        elif token.strip() == '.':
            period_indices.append(i)

    for i in range(n):
        # Strong attention to first token
        if i > 0:
            attention[i, 0] = 0.3

        # Self-attention
        attention[i, i] = 0.2

        # Strong attention to newlines
        for nl_idx in newline_indices:
            if nl_idx <= i:
                attention[i, nl_idx] = 0.6

        # Strong attention to periods
        for period_idx in period_indices:
            if period_idx <= i:
                attention[i, period_idx] = 0.4

        # Distribute remaining attention to recent tokens with decay
        for j in range(max(0, i-5), i):
            if j not in newline_indices and j not in period_indices and j != 0:
                distance = i - j
                attention[i, j] = 0.1 / (distance + 1)

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L2H28", attention



def prog_L2H29(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Structural anchor attention: focuses on sentence boundaries, newlines, and first tokens."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L2H29", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Find structural tokens
    newline_indices = []
    period_indices = []
    first_token_idx = 0

    for i, token in enumerate(tokens):
        if token.strip() == '\n':
            newline_indices.append(i)
        elif token.strip() == '.':
            period_indices.append(i)

    for i in range(n):
        # Base attention to first token
        attention[i, first_token_idx] = 0.3

        # Strong attention to newlines
        for nl_idx in newline_indices:
            if nl_idx <= i:
                attention[i, nl_idx] = 0.45

        # Attention to periods
        for period_idx in period_indices:
            if period_idx <= i:
                attention[i, period_idx] = 0.35

        # Self-attention for special tokens
        if tokens[i].strip() in ['.', '\n'] or i == first_token_idx:
            attention[i, i] = 0.6
        else:
            attention[i, i] = 0.05

        # Previous token attention for regular tokens
        if i > 0 and tokens[i-1].strip() not in ['\n', '.']:
            attention[i, i-1] = 0.2

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L2H29", attention



def prog_L2H3(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Structural attention head focusing on sentence boundaries and text beginnings."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    # Find structural tokens: newlines, periods, and first token
    structural_indices = []
    for i, token in enumerate(tokens):
        if token.strip() in ['\n', '.'] or i == 0:
            structural_indices.append(i)

    for i in range(n):
        # Strong self-attention for first token
        if i == 0:
            attention[i, i] = 1.0
        else:
            # Base attention to structural tokens
            for struct_idx in structural_indices:
                if struct_idx <= i:  # Respect causal mask
                    if tokens[struct_idx].strip() == '\n':
                        # High attention to newlines
                        attention[i, struct_idx] = 0.4
                    elif tokens[struct_idx].strip() == '.':
                        # High attention to periods
                        attention[i, struct_idx] = 0.38
                    elif struct_idx == 0:
                        # Medium attention to first token
                        attention[i, struct_idx] = 0.2

            # Additional attention based on distance from structural tokens
            for j in range(i + 1):
                if j not in structural_indices:
                    # Find nearest structural token before position j
                    nearest_struct = -1
                    for struct_idx in structural_indices:
                        if struct_idx <= j:
                            nearest_struct = max(nearest_struct, struct_idx)

                    if nearest_struct >= 0:
                        # Decay based on distance from structural token
                        distance = j - nearest_struct
                        base_weight = 0.1 * np.exp(-0.2 * distance)
                        attention[i, j] = base_weight

            # Boost attention from early tokens to first token
            if i <= 5:
                attention[i, 0] = min(attention[i, 0] + 0.3, 0.95)

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L2H3", attention



def prog_L2H30(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Punctuation boundary attention head - focuses on sentence/paragraph delimiters."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention_matrix = np.zeros((n, n))

    # Find structural tokens (newlines, periods, etc.)
    structural_tokens = []
    for i, token in enumerate(tokens):
        if token.strip() in ['\n', '.', '!', '?']:
            structural_tokens.append(i)

    for i in range(n):
        current_token = tokens[i].strip()

        # Base attention distribution
        for j in range(i + 1):  # Only attend to previous tokens (causal mask)
            token_j = tokens[j].strip()

            # Very high attention to newlines and periods
            if token_j in ['\n', '.']:
                if token_j == '\n':
                    attention_matrix[i, j] = 0.4 + 0.2 * np.exp(-(i - j) / 10)
                else:  # period
                    attention_matrix[i, j] = 0.35 + 0.15 * np.exp(-(i - j) / 8)

            # Medium attention to other punctuation
            elif token_j in ['!', '?', ',', ';', ':']:
                attention_matrix[i, j] = 0.1 + 0.1 * np.exp(-(i - j) / 5)

            # Low baseline attention to content tokens
            else:
                # Slight recency bias for nearby tokens
                distance = i - j
                if distance <= 3:
                    attention_matrix[i, j] = 0.02 + 0.01 * np.exp(-distance / 2)
                else:
                    attention_matrix[i, j] = 0.01

        # If current token is structural, add self-attention
        if current_token in ['\n', '.', '!', '?']:
            attention_matrix[i, i] += 0.1

    # Apply causal mask and normalize
    attention_matrix = apply_causal_mask(attention_matrix)
    attention_matrix = make_row_stochastic(attention_matrix)

    return "prog_L2H30", attention_matrix



def prog_L2H31(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Punctuation-focused attention head that primarily attends to newlines and periods."""
    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention_matrix = np.zeros((n, n))

    # Find newline and period positions
    newline_positions = []
    period_positions = []

    for i, token in enumerate(tokens):
        if token.strip() == '\n':
            newline_positions.append(i)
        elif token.strip() == '.':
            period_positions.append(i)

    for i in range(n):
        # Self-attention (low weight)
        attention_matrix[i, i] = 0.05

        # First token attention (medium weight)
        if i > 0:
            attention_matrix[i, 0] = 0.15

        # Strong attention to newlines
        for newline_pos in newline_positions:
            if newline_pos <= i:
                attention_matrix[i, newline_pos] = 0.5

        # Medium-high attention to periods
        for period_pos in period_positions:
            if period_pos <= i:
                attention_matrix[i, period_pos] = 0.35

        # Add some recency bias for nearby tokens
        for j in range(max(0, i-3), i):
            if j not in newline_positions and j not in period_positions:
                attention_matrix[i, j] += 0.1 / (i - j + 1)

    # Apply causal mask and normalize
    attention_matrix = apply_causal_mask(attention_matrix)
    attention_matrix = make_row_stochastic(attention_matrix)

    return "prog_L2H31", attention_matrix



def prog_L2H4(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary and first-token attention head with structural focus."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention_matrix = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        token = tokens[i]

        # Very strong attention to first token
        if i == 0:
            attention_matrix[i, 0] = 1.0
        elif i == 1:
            # Second token has very high attention to first
            attention_matrix[i, 0] = 0.85
            attention_matrix[i, i] = 0.15
        else:
            # Base attention to first token
            attention_matrix[i, 0] = 0.15

            # Find sentence boundary tokens (periods, newlines)
            boundary_positions = []
            for j in range(i + 1):  # Only look at previous positions
                if tokens[j] in ['.', '\n', '!', '?']:
                    boundary_positions.append(j)

            # High attention to the most recent sentence boundary
            if boundary_positions:
                recent_boundary = max(boundary_positions)
                attention_matrix[i, recent_boundary] = 0.35

                # Also attend to earlier boundaries with decay
                for boundary_pos in boundary_positions[:-1]:
                    distance = recent_boundary - boundary_pos
                    weight = 0.1 / (1 + distance * 0.1)
                    attention_matrix[i, boundary_pos] = weight

            # Some attention to immediate previous token
            if i > 0:
                attention_matrix[i, i-1] = 0.08

            # Self-attention
            attention_matrix[i, i] = 0.05

            # Attention to tokens that are content words at sentence starts
            for j in range(i):
                if j < len(token_to_spacy) and token_to_spacy[j]:
                    spacy_indices = token_to_spacy[j]
                    for spacy_idx in spacy_indices:
                        if spacy_idx < len(doc):
                            spacy_token = doc[spacy_idx]
                            # Attend to content words near sentence boundaries
                            if spacy_token.pos_ in ['NOUN', 'VERB', 'ADJ', 'PROPN']:
                                # Check if this token is near a sentence start
                                is_near_start = (j == 0 or 
                                               (j > 0 and tokens[j-1] in ['.', '\n', '!', '?']) or
                                               (j > 1 and tokens[j-2] in ['.', '\n', '!', '?']))
                                if is_near_start:
                                    attention_matrix[i, j] += 0.05

            # Distribute remaining probability
            current_sum = attention_matrix[i].sum()
            if current_sum < 1.0:
                remaining = 1.0 - current_sum
                # Add small uniform attention to all available positions
                for j in range(i + 1):
                    attention_matrix[i, j] += remaining / (i + 1)

    # Apply causal mask and normalize
    attention_matrix = apply_causal_mask(attention_matrix)
    attention_matrix = make_row_stochastic(attention_matrix)

    return "prog_L2H4", attention_matrix



def prog_L2H5(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Structural boundary attention head focusing on sentence delimiters and first tokens."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    # Identify structural boundary tokens
    boundary_indices = []
    first_token_idx = 0 if n > 0 else -1

    for i, token in enumerate(tokens):
        # Major boundaries: periods, newlines (including whitespace-only tokens containing newlines)
        if token.strip() in ['.', '\n'] or ('\n' in token and token.strip() == ''):
            boundary_indices.append(i)

    for i in range(n):
        current_token = tokens[i].strip()

        # Very strong attention to first token (seen consistently across examples)
        if first_token_idx >= 0 and i >= first_token_idx:
            attention[i, first_token_idx] += 0.6

        # Strong attention to sentence boundary markers (periods, newlines)
        for boundary_idx in boundary_indices:
            if boundary_idx <= i:  # Causal constraint
                # Distance-based decay for boundaries
                distance = i - boundary_idx
                if distance == 0:
                    attention[i, boundary_idx] += 0.8  # Self-attention to boundaries
                elif distance <= 5:
                    attention[i, boundary_idx] += 0.5 / (1 + distance * 0.2)
                else:
                    attention[i, boundary_idx] += 0.3 / (1 + distance * 0.1)

        # Medium attention to immediately previous token
        if i > 0:
            attention[i, i-1] += 0.2

        # Self attention baseline
        attention[i, i] += 0.1

        # Additional attention based on token properties
        if current_token in ['.', '\n'] or ('\n' in tokens[i] and tokens[i].strip() == ''):
            # Boundary tokens attend more to previous boundaries
            for prev_boundary in boundary_indices:
                if prev_boundary < i:
                    attention[i, prev_boundary] += 0.3

        # Slight recency bias for non-boundary tokens
        if not (current_token in ['.', '\n'] or ('\n' in tokens[i] and tokens[i].strip() == '')):
            for j in range(max(0, i-3), i):
                attention[i, j] += 0.05 / (1 + (i - j))

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L2H5", attention



def prog_L2H6(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Attends primarily to first token and sentence boundary markers (newlines), with some recency bias."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L2H6", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    for i in range(n):
        # Strong attention to first token
        attention[i, 0] = 0.6

        # Strong attention to newline tokens (sentence boundaries)
        for j in range(i + 1):
            if tokens[j].strip() == '' and '\n' in tokens[j]:
                attention[i, j] = 0.45

        # Moderate attention to punctuation marks that end sentences
        for j in range(i + 1):
            if tokens[j].strip() in ['.', '!', '?']:
                attention[i, j] = 0.3

        # Some self-attention
        attention[i, i] = 0.1

        # Light recency bias for recent tokens
        for j in range(max(0, i - 3), i):
            attention[i, j] += 0.05

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L2H6", attention



def prog_L2H7(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Structural boundary and first-token attention head."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L2H7", np.zeros((n_empty, n_empty))

    attention_matrix = np.zeros((n, n))

    for i in range(n):
        weights = np.zeros(i + 1)  # Can only attend to positions <= i

        if i == 0:
            # First token attends to itself
            weights[0] = 1.0
        else:
            # Find structural markers and first token
            structural_positions = []

            # Always include first token
            structural_positions.append(0)

            # Find newlines and periods
            for j in range(i + 1):
                token = tokens[j].strip()
                if token in ['\n', '.']:
                    structural_positions.append(j)

            # Remove duplicates and sort
            structural_positions = sorted(list(set(structural_positions)))

            if structural_positions:
                # Distribute attention among structural positions
                base_weight = 1.0 / len(structural_positions)

                for pos in structural_positions:
                    weights[pos] = base_weight

                # Add some recency bias - closer structural markers get slightly more weight
                for j, pos in enumerate(structural_positions):
                    distance_from_current = i - pos
                    if distance_from_current > 0:
                        # Closer positions get small boost
                        recency_boost = 1.0 / (1.0 + distance_from_current * 0.1)
                        weights[pos] *= recency_boost

                # Small amount of self-attention
                if i < n:
                    weights[i] += 0.1
            else:
                # Fallback to self-attention if no structural markers found
                weights[i] = 1.0

        # Normalize to sum to 1
        if weights.sum() > 0:
            weights = weights / weights.sum()

        attention_matrix[i, :i+1] = weights

    attention_matrix = apply_causal_mask(attention_matrix)
    attention_matrix = make_row_stochastic(attention_matrix)

    return "prog_L2H7", attention_matrix



def prog_L2H8(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary attention head that focuses on newlines, periods, and discourse structure."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    # Find newlines and periods for boundary detection
    newline_indices = [i for i, token in enumerate(tokens) if token.strip() == '\n']
    period_indices = [i for i, token in enumerate(tokens) if token.strip() == '.']
    boundary_indices = set(newline_indices + period_indices)

    for i in range(n):
        token = tokens[i]

        # Strong attention to newlines (highest priority)
        for newline_idx in newline_indices:
            if newline_idx <= i:
                attention[i, newline_idx] = 0.4

        # Strong attention to periods 
        for period_idx in period_indices:
            if period_idx <= i:
                attention[i, period_idx] = 0.3

        # First token attention (discourse beginning)
        if i > 0:
            attention[i, 0] = 0.15

        # Self attention
        attention[i, i] = 0.1

        # Local context attention (previous few tokens)
        for j in range(max(0, i-3), i):
            if j not in boundary_indices:
                attention[i, j] = 0.05

        # Boost attention to content words in local context using spacy
        try:
            spacy_alignment = _align_to_spacy(sentence, tokens)
            doc = spacy_parse(sentence)

            if i < len(spacy_alignment) and spacy_alignment[i]:
                spacy_idx = spacy_alignment[i][0]
                if spacy_idx < len(doc):
                    spacy_token = doc[spacy_idx]

                    # Look for syntactic dependencies
                    for j in range(i):
                        if j < len(spacy_alignment) and spacy_alignment[j]:
                            j_spacy_idx = spacy_alignment[j][0]
                            if j_spacy_idx < len(doc):
                                j_spacy_token = doc[j_spacy_idx]

                                # Boost attention to syntactic heads
                                if (j_spacy_token == spacy_token.head or 
                                    spacy_token == j_spacy_token.head):
                                    attention[i, j] += 0.03
        except:
            pass

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L2H8", attention



def prog_L2H9(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Structural anchor attention: tokens attend strongly to sentence boundaries and first token."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L2H9", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        # Base uniform distribution over available positions
        for j in range(i + 1):
            attention[i, j] = 0.01

        # Much stronger attention to first token than original
        if i > 0:
            attention[i, 0] = 0.6  # Increased from 0.3

        # Find sentence boundary tokens (newlines and periods)
        anchor_positions = []
        newline_positions = []
        for j in range(i + 1):
            token_text = tokens[j].strip()
            if token_text == '\n':
                anchor_positions.append(j)
                newline_positions.append(j)
            elif token_text == '.':
                anchor_positions.append(j)

        # Very strong attention to most recent newline (much stronger than periods)
        if newline_positions:
            most_recent_newline = newline_positions[-1]
            attention[i, most_recent_newline] = 0.8  # Very strong for newlines

            # Moderate attention to earlier newlines
            for newline_pos in newline_positions[:-1]:
                attention[i, newline_pos] = 0.4

        # Reduced attention to periods (they were over-weighted)
        period_positions = [pos for pos in anchor_positions if pos not in newline_positions]
        if period_positions and not newline_positions:  # Only if no newlines available
            most_recent_period = period_positions[-1]
            attention[i, most_recent_period] = 0.3  # Reduced from 0.6

            # Moderate attention to earlier periods
            for period_pos in period_positions[:-1]:
                attention[i, period_pos] = 0.1  # Reduced from 0.2

        # Add some local syntactic attention
        if token_to_spacy[i]:
            spacy_idx = token_to_spacy[i][0]
            if spacy_idx < len(doc):
                spacy_token = doc[spacy_idx]

                # Attention to head of current token
                if spacy_token.head != spacy_token and spacy_token.head.i < len(doc):
                    head_spacy_idx = spacy_token.head.i
                    # Find corresponding LM token
                    for j in range(i + 1):
                        if token_to_spacy[j] and head_spacy_idx in token_to_spacy[j]:
                            attention[i, j] += 0.15
                            break

                # Adjectives attend to their modified nouns
                if spacy_token.pos_ == 'ADJ' and spacy_token.head.pos_ == 'NOUN':
                    head_spacy_idx = spacy_token.head.i
                    for j in range(i + 1):
                        if token_to_spacy[j] and head_spacy_idx in token_to_spacy[j]:
                            attention[i, j] += 0.1
                            break

        # Self-attention baseline
        attention[i, i] = max(attention[i, i], 0.05)

        # Slight recency bias for recent tokens
        for j in range(max(0, i - 3), i):
            attention[i, j] += 0.02

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L2H9", attention



def prog_L3H0(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Boundary and first-token attention head with strong early-token to first-token attention."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    for i in range(n):
        for j in range(i + 1):  # Causal mask
            weight = 0.0

            # Strong attention to newlines and periods (sentence boundaries)
            if tokens[j] == '\n':
                weight += 0.4
            elif tokens[j] == '.':
                weight += 0.3

            # Strong attention to first token, with distance-based boosting for early positions
            if j == 0:
                weight += 0.25
                # Add extra boost for early tokens attending to first token
                if i <= 10:  # Early positions get stronger first-token attention
                    distance_boost = (11 - i) * 0.05  # Decay from 0.5 to 0.05
                    weight += distance_boost

            # Moderate self-attention
            if i == j:
                weight += 0.1

            # Small attention to immediately previous token
            if i > 0 and j == i - 1:
                weight += 0.05

            # Small baseline attention to all accessible tokens
            weight += 0.02

            attention[i, j] = weight

    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L3H0", attention



def prog_L3H1(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary and structural marker attention head."""
    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    # Find periods and newlines (structural markers)
    periods = [i for i, tok in enumerate(tokens) if tok.strip() == '.']
    newlines = [i for i, tok in enumerate(tokens) if tok.strip() == '\n']

    for i in range(n):
        # Strong attention to first token
        if i > 0:
            attention[i, 0] = 0.3

        # Very strong self-attention for first token
        if i == 0:
            attention[i, i] = 1.0
            continue

        # Strong attention to sentence-ending periods
        for p_idx in periods:
            if p_idx < i:
                # Distance decay but strong base attention
                distance = i - p_idx
                attention[i, p_idx] = max(0.25, 0.4 / (1 + 0.1 * distance))

        # Strong attention to newlines
        for n_idx in newlines:
            if n_idx < i:
                distance = i - n_idx
                attention[i, n_idx] = max(0.2, 0.35 / (1 + 0.1 * distance))

        # Moderate self-attention
        attention[i, i] = 0.05

        # Light attention to recent tokens
        for j in range(max(0, i-3), i):
            if attention[i, j] == 0:  # Don't override structural attention
                attention[i, j] = 0.02 / (1 + i - j)

    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)
    return "prog_L3H1", attention



def prog_L3H10(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary and discourse structure attention head with strong focus on document start and newlines."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L3H10", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        # Very strong attention to sentence-ending punctuation
        for j in range(i + 1):
            if tokens[j].strip() in ['.', '!', '?']:
                attention[i, j] += 0.4
            elif tokens[j].strip() == '\n':
                attention[i, j] += 0.3

        # Strong attention to first token of sentence/document
        if i > 0:
            attention[i, 0] += 0.2

        # Self-attention boost for certain tokens
        attention[i, i] += 0.1

        # Local syntactic relationships using spacy
        if token_to_spacy[i]:
            spacy_i = token_to_spacy[i][0]
            if spacy_i < len(doc):
                spacy_token_i = doc[spacy_i]

                # Look for syntactic head relationships
                for j in range(i):
                    if token_to_spacy[j]:
                        spacy_j = token_to_spacy[j][0]
                        if spacy_j < len(doc):
                            spacy_token_j = doc[spacy_j]

                            # Modifier to head relationships
                            if spacy_token_i.head == spacy_token_j:
                                attention[i, j] += 0.15

                            # Adjacent word relationships
                            if abs(spacy_i - spacy_j) == 1:
                                attention[i, j] += 0.05

        # Boost attention to nearby tokens
        for j in range(max(0, i-3), i):
            attention[i, j] += 0.05 * (1.0 / (i - j + 1))

        # Semantic similarity boost
        for j in range(i):
            sim = _char_sim(tokens[i], tokens[j])
            if sim > 0.7:
                attention[i, j] += 0.1 * sim

    # Add targeted fix for missed patterns
    for i in range(n):
        # Much stronger attention to document start from all tokens
        if i > 0:
            attention[i, 0] += 0.5

        # Much stronger attention to newline tokens from subsequent tokens
        for j in range(i):
            if tokens[j].strip() == '\n':
                attention[i, j] += 0.4

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L3H10", attention



def prog_L3H11(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Structural boundary detection head - attends to newlines, periods, and first tokens."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    # Find structural markers
    newline_positions = []
    period_positions = []
    first_token_pos = 0

    for i, token in enumerate(tokens):
        if token.strip() == '\n':
            newline_positions.append(i)
        elif token.strip() == '.':
            period_positions.append(i)

    for i in range(n):
        # Strong attention to first token
        attention[i, first_token_pos] = 3.0

        # Strong attention to newlines
        for nl_pos in newline_positions:
            if nl_pos <= i:  # causal constraint
                attention[i, nl_pos] = 5.0

        # High attention to periods
        for period_pos in period_positions:
            if period_pos <= i:  # causal constraint
                # Stronger if nearby
                distance = i - period_pos
                if distance <= 10:
                    attention[i, period_pos] = 4.0 - 0.2 * distance
                else:
                    attention[i, period_pos] = 1.0

        # Self-attention
        attention[i, i] = 0.5

        # Local attention to recent tokens
        for j in range(max(0, i-5), i):
            attention[i, j] += 0.3 * (1.0 - (i-j) * 0.1)

        # Boost attention if token appears to be at sentence/phrase boundaries
        token_text = tokens[i].strip()
        if i > 0:
            prev_token = tokens[i-1].strip()
            # Tokens after periods or newlines get extra attention to those markers
            if prev_token == '.' or prev_token == '\n':
                for struct_pos in period_positions + newline_positions:
                    if struct_pos < i:
                        attention[i, struct_pos] *= 1.5

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L3H11", attention



def prog_L3H12(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary detection head - attends to line breaks, periods, and structural boundaries with preference for earlier structural markers."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    # Find positions of structural tokens
    newline_positions = []
    period_positions = []
    first_token_pos = 0 if n > 0 else -1

    for i, token in enumerate(tokens):
        if token.strip() == '' and '\n' in token:
            newline_positions.append(i)
        elif token.strip() == '.':
            period_positions.append(i)

    for i in range(n):
        # Find the most recent newline before position i
        recent_newline = -1
        for pos in newline_positions:
            if pos < i:
                recent_newline = pos
            else:
                break

        # Find the most recent period before position i
        recent_period = -1
        for pos in period_positions:
            if pos < i:
                recent_period = pos
            else:
                break

        # Special case: distribute attention across multiple previous newlines
        # with preference for earlier ones (stronger structural boundaries)
        available_newlines = [pos for pos in newline_positions if pos < i]
        if len(available_newlines) >= 2:
            # Reduce weight to most recent newline
            if recent_newline >= 0:
                attention[i, recent_newline] += 0.2

            # Give stronger attention to earlier newlines
            for idx, nl_pos in enumerate(available_newlines[:-1]):  # Exclude most recent
                # Earlier newlines get higher weights
                weight = 0.5 - (idx * 0.1)
                if weight > 0:
                    attention[i, nl_pos] += weight
        else:
            # Original behavior when fewer than 2 newlines
            if recent_newline >= 0:
                attention[i, recent_newline] += 0.6

        if recent_period >= 0:
            # Medium attention to most recent period
            attention[i, recent_period] += 0.3

        # Attention to first token (fallback)
        if first_token_pos >= 0 and first_token_pos <= i:
            attention[i, first_token_pos] += 0.2

        # Self attention
        attention[i, i] += 0.1

        # Small attention to immediate previous token
        if i > 0:
            attention[i, i-1] += 0.05

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L3H12", attention



def prog_L3H13(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary and first-token attention head."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L3H13", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Identify sentence boundaries and first tokens
    sentence_boundaries = []
    first_tokens = []

    for i, token in enumerate(tokens):
        # Mark periods and newlines as sentence boundaries
        if token.strip() in ['.', '\n']:
            sentence_boundaries.append(i)

        # Mark first token and tokens after sentence boundaries as first tokens
        if i == 0:
            first_tokens.append(i)
        elif i > 0 and tokens[i-1].strip() in ['.', '\n']:
            first_tokens.append(i)

    for i in range(n):
        # Strong self-attention for sentence boundaries
        if i in sentence_boundaries:
            attention[i, i] = 1.0
        else:
            # High attention to nearest sentence boundary (period or newline)
            boundary_weights = 0.0
            for boundary in sentence_boundaries:
                if boundary <= i:  # Causal constraint
                    # Stronger weight for more recent boundaries
                    distance = i - boundary
                    weight = 0.4 * np.exp(-distance * 0.1)
                    attention[i, boundary] += weight
                    boundary_weights += weight

            # High attention to first tokens of sentences
            first_token_weights = 0.0
            for first_tok in first_tokens:
                if first_tok <= i:  # Causal constraint
                    distance = i - first_tok
                    weight = 0.3 * np.exp(-distance * 0.05)
                    attention[i, first_tok] += weight
                    first_token_weights += weight

            # Some self-attention
            attention[i, i] = 0.1

            # Local attention to previous token
            if i > 0:
                attention[i, i-1] = 0.1

            # Small attention to other tokens
            remaining_weight = max(0, 1.0 - boundary_weights - first_token_weights - 0.1 - (0.1 if i > 0 else 0))
            if remaining_weight > 0:
                for j in range(i):
                    if j not in sentence_boundaries and j not in first_tokens and j != i-1:
                        attention[i, j] = remaining_weight / max(1, i - len(sentence_boundaries) - len([f for f in first_tokens if f <= i]))

    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L3H13", attention



def prog_L3H14(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary attention head with strong bias toward first token and punctuation."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L3H14", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        token_i = tokens[i]

        # Strong attention to first token (position 0)
        if i > 0:
            attention[i, 0] = 0.8
        else:
            attention[i, 0] = 1.0  # Self-attention for first token

        # High attention to sentence boundaries (newlines and periods)
        for j in range(i + 1):
            token_j = tokens[j]

            # Newlines get very high attention
            if token_j.strip() == '' and '\n' in token_j:
                attention[i, j] += 0.4

            # Periods get high attention
            elif token_j.strip() == '.':
                attention[i, j] += 0.35

            # Self-attention for punctuation
            elif j == i and token_j.strip() in '.,!?;:':
                attention[i, j] += 0.3

        # Local syntactic attention
        if token_to_spacy[i]:
            spacy_idx = token_to_spacy[i][0]
            spacy_token = doc[spacy_idx]

            # Attend to syntactic head
            if spacy_token.head != spacy_token:
                head_spacy_idx = spacy_token.head.i
                for j in range(i + 1):
                    if token_to_spacy[j] and head_spacy_idx in token_to_spacy[j]:
                        attention[i, j] += 0.1

            # Function words attend to content words
            if spacy_token.pos_ in ['DET', 'PREP', 'ADP', 'AUX']:
                for j in range(i + 1):
                    if token_to_spacy[j]:
                        target_spacy = token_to_spacy[j][0]
                        if doc[target_spacy].pos_ in ['NOUN', 'VERB', 'ADJ']:
                            attention[i, j] += 0.05

        # Weak self-attention for non-punctuation tokens
        if tokens[i].strip() not in '.,!?;:\n':
            attention[i, i] += 0.02

        # Small uniform attention to all previous tokens
        for j in range(i):
            attention[i, j] += 0.01

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L3H14", attention



def prog_L3H15(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Attention to sentence boundaries (newlines/periods) and first token, with stronger attention to newlines."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L3H15", np.zeros((n_empty, n_empty))

    # Initialize attention matrix
    attention = np.zeros((n, n))

    # Identify structural boundary tokens with different weights
    newline_indices = []
    period_indices = []
    for i, token in enumerate(tokens):
        if token.strip() == '\n':
            newline_indices.append(i)
        elif token.strip() == '.':
            period_indices.append(i)

    # First token index
    first_token_idx = 0

    for i in range(n):
        # Base self-attention
        attention[i, i] = 0.1

        # Very strong attention to newline tokens
        for newline_idx in newline_indices:
            if newline_idx <= i:  # Respect causal mask
                attention[i, newline_idx] = 0.5

        # Moderate attention to period tokens
        for period_idx in period_indices:
            if period_idx <= i:  # Respect causal mask
                attention[i, period_idx] = 0.15

        # Strong attention to first token
        attention[i, first_token_idx] = 0.2

        # Moderate attention to previous few tokens
        for j in range(max(0, i-3), i):
            attention[i, j] += 0.05

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L3H15", attention



def prog_L3H16(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Structural boundary attention head focusing on newlines, sentence boundaries, and first tokens."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    # Find structural boundary tokens
    newline_indices = []
    period_indices = []
    first_token_idx = 0

    for i, token in enumerate(tokens):
        if token.strip() == '\n':
            newline_indices.append(i)
        elif token.strip() == '.':
            period_indices.append(i)

    for i in range(n):
        # Base attention distribution
        base_attention = np.zeros(n)

        # Strong attention to newlines (highest priority)
        for nl_idx in newline_indices:
            if nl_idx <= i:  # causal constraint
                base_attention[nl_idx] = 0.5

        # Moderate attention to periods
        for p_idx in period_indices:
            if p_idx <= i:  # causal constraint
                base_attention[p_idx] = 0.35

        # Some attention to first token
        base_attention[first_token_idx] = 0.2

        # Small attention to self
        base_attention[i] = 0.1

        # If no structural tokens found, distribute more evenly to nearby tokens
        if len(newline_indices) == 0 and len(period_indices) == 0:
            # Attend to recent tokens with recency bias
            for j in range(max(0, i-3), i+1):
                base_attention[j] = 0.3 / (i - j + 1)

        # Normalize and store
        if base_attention.sum() > 0:
            base_attention = base_attention / base_attention.sum()
        else:
            base_attention[i] = 1.0  # fallback to self-attention

        attention[i] = base_attention

    # Apply causal mask and make row stochastic
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L3H16", attention



def prog_L3H17(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary and structural marker attention head."""
    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L3H17", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Identify boundary tokens (newlines, periods, and first token)
    boundary_indices = []
    for i, token in enumerate(tokens):
        if token.strip() in ['\n', '.', '!', '?'] or i == 0:
            boundary_indices.append(i)

    for i in range(n):
        # Base attention distribution
        for j in range(i + 1):  # causal mask
            # Distance-based decay
            distance = i - j
            base_weight = 0.01 * np.exp(-distance * 0.1)
            attention[i, j] = base_weight

        # Strong attention to boundary markers
        for boundary_idx in boundary_indices:
            if boundary_idx <= i:
                # Very high attention to newlines and periods
                if tokens[boundary_idx].strip() in ['\n', '.']:
                    attention[i, boundary_idx] = 0.4
                # High attention to first token
                elif boundary_idx == 0:
                    attention[i, boundary_idx] = 0.3

        # Special case: first few tokens attend very strongly to first token
        if i <= 3 and i > 0:
            attention[i, 0] = 0.8

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L3H17", attention



def prog_L3H18(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary attention head with strong beginning-of-sequence attention."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    # Find sentence boundary tokens (newlines and periods)
    boundary_tokens = []
    for i, token in enumerate(tokens):
        if token.strip() == '\n' or token.strip() == '.':
            boundary_tokens.append(i)

    # If we have boundary tokens, prioritize the first newline
    primary_boundary = None
    secondary_boundary = None

    for i in boundary_tokens:
        if tokens[i].strip() == '\n':
            if primary_boundary is None:
                primary_boundary = i
        elif tokens[i].strip() == '.':
            if secondary_boundary is None:
                secondary_boundary = i

    # If no newline found, use first period as primary
    if primary_boundary is None and secondary_boundary is not None:
        primary_boundary = secondary_boundary
        secondary_boundary = None

    for i in range(n):
        for j in range(i + 1):  # Causal mask
            if i == j:
                # Self-attention baseline
                attention[i, j] = 0.02
            elif primary_boundary is not None and j == primary_boundary:
                # Very strong attention to primary boundary (first newline or period)
                if i == 0:
                    attention[i, j] = 1.0  # First token case
                else:
                    attention[i, j] = 0.4
            elif secondary_boundary is not None and j == secondary_boundary:
                # Strong attention to secondary boundary
                attention[i, j] = 0.25
            elif tokens[j].strip() == '\n':
                # Moderate attention to other newlines
                attention[i, j] = 0.15
            elif tokens[j].strip() == '.':
                # Moderate attention to other periods
                attention[i, j] = 0.12
            elif j == 0:
                # Enhanced attention to first token - this is the key fix
                # Use distance-based decay for stronger beginning-of-sequence attention
                distance = i - j
                if distance <= 5:
                    attention[i, j] = 0.3
                elif distance <= 15:
                    attention[i, j] = 0.2
                else:
                    attention[i, j] = 0.15
            else:
                # Minimal attention to other tokens
                attention[i, j] = 0.01

    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L3H18", attention



def prog_L3H19(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Structural marker attention head with strong first-token attention."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    # Find structural markers (newlines and periods)
    newline_indices = []
    period_indices = []
    for i, token in enumerate(tokens):
        if '\n' in token:
            newline_indices.append(i)
        elif '.' in token:
            period_indices.append(i)

    for i in range(n):
        # Base self-attention
        attention[i, i] = 0.1

        # Strong first-token attention for most tokens - ENHANCED
        if i > 0:
            # Much stronger first-token attention, especially for later tokens
            first_token_weight = 0.6 + 0.2 * min(i / 10.0, 1.0)
            attention[i, 0] = first_token_weight

        # High attention to newlines (strongest pattern) - REDUCED to balance
        for nl_idx in newline_indices:
            if nl_idx <= i and nl_idx != 0:  # Don't double-count first token if it's a newline
                # Reduced base weight to compensate for stronger first-token attention
                distance_factor = 1.0 + 0.2 * (i - nl_idx)
                attention[i, nl_idx] = 0.25 * distance_factor

        # High attention to periods (second strongest pattern) - REDUCED to balance
        for p_idx in period_indices:
            if p_idx <= i and p_idx != 0:  # Don't double-count first token if it's a period
                # Reduced base weight to compensate for stronger first-token attention
                distance_factor = 1.0 + 0.15 * (i - p_idx)
                attention[i, p_idx] = 0.2 * distance_factor

        # Additional positional bias - attend to recent tokens
        for j in range(max(0, i-5), i):
            if j not in newline_indices and j not in period_indices:
                attention[i, j] += 0.05 * (1.0 / (i - j + 1))

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L3H19", attention



def prog_L3H2(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Structural boundary attention head focusing on punctuation and sentence boundaries."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L3H2", np.zeros((n_empty, n_empty))

    attention_matrix = np.zeros((n, n))

    # Get spacy alignment for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        # Base attention distribution
        for j in range(i + 1):  # Causal mask
            # Strong attention to punctuation marks
            if tokens[j] in ['.', '\n', '!', '?', ';', ':', ',']:
                if tokens[j] == '.':
                    attention_matrix[i, j] = 0.35
                elif tokens[j] == '\n':
                    attention_matrix[i, j] = 0.30
                elif tokens[j] in ['!', '?']:
                    attention_matrix[i, j] = 0.25
                else:
                    attention_matrix[i, j] = 0.20

            # High attention to first token
            elif j == 0:
                attention_matrix[i, j] = 0.25

            # Self-attention
            elif i == j:
                attention_matrix[i, j] = 0.15

            # Moderate attention to tokens near sentence boundaries
            elif j > 0 and tokens[j-1] in ['.', '\n', '!', '?']:
                attention_matrix[i, j] = 0.12

            # Base attention for other tokens
            else:
                # Decay with distance, but higher for structural elements
                distance = i - j
                base_attention = 0.05 / (1 + distance * 0.1)

                # Check if token has structural importance via spacy
                is_structural = False
                if token_to_spacy[j]:
                    spacy_idx = token_to_spacy[j][0]
                    if spacy_idx < len(doc):
                        spacy_token = doc[spacy_idx]
                        # Boost attention for sentence starts, conjunctions, etc.
                        if spacy_token.pos_ in ['CCONJ', 'SCONJ'] or spacy_token.is_sent_start:
                            is_structural = True

                if is_structural:
                    attention_matrix[i, j] = base_attention * 2
                else:
                    attention_matrix[i, j] = base_attention

    # Apply causal mask and normalize
    attention_matrix = apply_causal_mask(attention_matrix)
    attention_matrix = make_row_stochastic(attention_matrix)

    return "prog_L3H2", attention_matrix



def prog_L3H20(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary attention head with strong bias toward sentence-initial tokens."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        for j in range(i + 1):  # Causal mask
            weight = 0.0

            token_i = tokens[i].strip()
            token_j = tokens[j].strip()

            # Strong attention to sentence-initial token (first token)
            if j == 0:
                weight = 0.8

            # Very high attention to periods
            elif token_j == '.':
                weight = 0.4

            # High attention to newlines
            elif token_j == '\n':
                weight = 0.35

            # Medium attention to other punctuation
            elif token_j in [',', '!', '?', ';', ':']:
                weight = 0.15

            # Self-attention gets moderate weight
            elif i == j:
                weight = 0.05

            # Previous token attention
            elif j == i - 1:
                weight = 0.08

            # Distance-based decay for other tokens
            else:
                distance = i - j
                weight = max(0.01, 0.05 * np.exp(-distance / 5.0))

            # Boost for semantic similarity if tokens are content words
            if j < i and token_to_spacy[i] and token_to_spacy[j]:
                spacy_i = doc[token_to_spacy[i][0]]
                spacy_j = doc[token_to_spacy[j][0]]

                if (spacy_i.pos_ in ['NOUN', 'VERB', 'ADJ', 'ADV'] and 
                    spacy_j.pos_ in ['NOUN', 'VERB', 'ADJ', 'ADV']):
                    sim = _char_sim(tokens[i], tokens[j])
                    if sim > 0.7:
                        weight *= 1.5

            attention[i, j] = weight

    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L3H20", attention



def prog_L3H21(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Structural boundary attention head with very strong first-token attention."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L3H21", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    for i in range(n):
        # Strong attention to structural tokens (periods, newlines)
        for j in range(i + 1):
            token_j = tokens[j].strip()

            # Very high attention to newlines and periods
            if token_j == '\n':
                attention[i, j] = 0.4
            elif token_j == '.':
                attention[i, j] = 0.35

            # Much stronger first-token attention - this is the key fix
            elif j == 0:
                # Boost first-token attention significantly for tokens later in sequence
                if i >= 5:  # For tokens well into the sentence
                    attention[i, j] = 0.6  # Much higher than original 0.2
                else:
                    attention[i, j] = 0.2  # Keep original for early tokens

            # Moderate self-attention
            elif i == j:
                attention[i, j] = 0.08

            # Some attention to other punctuation
            elif token_j in [',', '!', '?']:
                attention[i, j] = 0.05

            # Base attention for other tokens
            else:
                attention[i, j] = 0.02

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L3H21", attention



def prog_L3H22(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary detection with intra-sentence attention and positional bias."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L3H22", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Find sentence boundaries (periods, newlines)
    sentence_boundaries = []
    for i, token in enumerate(tokens):
        if token.strip() in ['.', '\n']:
            sentence_boundaries.append(i)

    # Find sentence segments
    sentence_segments = []
    start = 0
    for boundary in sentence_boundaries:
        if boundary >= start:
            sentence_segments.append((start, boundary))
            start = boundary + 1
    if start < n:
        sentence_segments.append((start, n - 1))

    for i in range(n):
        # Find which sentence segment token i belongs to
        current_segment = None
        for seg_start, seg_end in sentence_segments:
            if seg_start <= i <= seg_end:
                current_segment = (seg_start, seg_end)
                break

        if current_segment is None:
            current_segment = (0, n - 1)

        seg_start, seg_end = current_segment

        for j in range(i + 1):  # Causal mask
            weight = 0.0

            # Strong attention to sentence boundaries
            if tokens[j].strip() in ['.', '\n']:
                weight += 0.35

            # Strong attention to first token in sequence
            if j == 0:
                weight += 0.4

            # Attention to first token of current sentence
            if j == seg_start and j > 0:
                weight += 0.15

            # Within same sentence segment
            if seg_start <= j <= seg_end:
                # Local attention with decay
                distance = i - j
                if distance == 0:  # Self attention
                    weight += 0.05
                elif distance <= 3:
                    weight += 0.08 * (1.0 / (distance + 1))
                else:
                    weight += 0.02 * (1.0 / (distance + 1))

                # Semantic similarity within sentence
                sim = _char_sim(tokens[i], tokens[j])
                if sim > 0.3:
                    weight += 0.1 * sim

            # Cross-sentence attention (weaker)
            else:
                distance = i - j
                weight += 0.01 * (1.0 / (distance + 1))

            attention[i, j] = weight

    # Add small uniform attention to avoid zeros
    attention += 0.01

    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L3H22", attention



def prog_L3H23(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary and structural marker attention head that focuses on periods, newlines, first tokens, and sentence-initial content words."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L3H23", np.zeros((n_empty, n_empty)).reshape(0, 0)

    attention = np.zeros((n, n))

    # Check if first token is a significant content word
    first_token_boost = 0.15  # default
    if n > 0:
        doc = spacy_parse(sentence)
        token_to_spacy = _align_to_spacy(sentence, tokens)

        if len(token_to_spacy[0]) > 0:
            first_spacy_idx = token_to_spacy[0][0]
            if first_spacy_idx < len(doc):
                first_spacy_token = doc[first_spacy_idx]
                # Boost attention to first token if it's a content word (noun, proper noun, verb, adjective)
                if first_spacy_token.pos_ in ['NOUN', 'PROPN', 'VERB', 'ADJ']:
                    first_token_boost = 0.35

    for i in range(n):
        token = tokens[i]

        # High attention to newlines and periods
        for j in range(i + 1):
            target_token = tokens[j]

            # Very high attention to newlines
            if target_token == '\n':
                attention[i, j] += 0.4

            # High attention to periods  
            elif target_token == '.':
                attention[i, j] += 0.35

            # Attention to first token (boosted if content word)
            elif j == 0:
                attention[i, j] += first_token_boost

            # Self-attention boost for punctuation
            elif i == j and token in ['.', '\n', ',', '!', '?']:
                attention[i, j] += 0.3

            # Base attention with recency bias
            else:
                # Distance-based decay
                distance = i - j
                base_weight = 0.02 + 0.03 * np.exp(-distance / 3.0)
                attention[i, j] += base_weight

                # Boost for other punctuation
                if target_token in [',', '!', '?', ';', ':']:
                    attention[i, j] += 0.08

    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L3H23", attention



def prog_L3H24(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Structural boundary attention head with distance-sensitive weighting to newlines and periods."""
    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    for i in range(n):
        token = tokens[i]

        # High attention to newlines and periods
        for j in range(i + 1):
            target_token = tokens[j]

            # Distance-sensitive attention to newlines
            if target_token.strip() == '':  # newline or whitespace
                distance = i - j
                # Increase attention based on distance from newline
                base_attention = 0.5
                distance_boost = min(0.4, distance * 0.02)  # Up to 0.4 extra for distant tokens
                attention[i, j] = base_attention + distance_boost
            # Distance-sensitive attention to periods
            elif target_token == '.':
                distance = i - j
                # Increase attention based on distance from period
                base_attention = 0.4
                distance_boost = min(0.3, distance * 0.015)  # Up to 0.3 extra for distant tokens
                attention[i, j] = base_attention + distance_boost
            # Medium attention to first token
            elif j == 0:
                attention[i, j] = 0.2
            # Reduced self-attention for punctuation (especially commas)
            elif i == j and token in ['.', ',', '!', '?']:
                if token == ',':
                    attention[i, j] = 0.2  # Much lower for commas
                else:
                    attention[i, j] = 0.6
            # Lower attention to other tokens
            else:
                attention[i, j] = 0.05

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L3H24", attention



def prog_L3H25(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary detection head with strong first-token attention: attends to newlines, sentence-ending punctuation, and especially the first token."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L3H25", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Identify structural tokens
    newline_indices = [i for i, token in enumerate(tokens) if token.strip() == '']
    period_indices = [i for i, token in enumerate(tokens) if token.strip() == '.']

    for i in range(n):
        # Base attention distribution
        row = np.zeros(n)

        # Strong attention to newlines (especially first ones after sentence breaks)
        for nl_idx in newline_indices:
            if nl_idx <= i:
                # Higher weight for earlier newlines and those that seem to mark paragraph breaks
                distance_penalty = 1.0 / (1.0 + 0.1 * (i - nl_idx))
                row[nl_idx] = 0.5 * distance_penalty

        # Strong attention to sentence-ending periods
        for period_idx in period_indices:
            if period_idx <= i:
                distance_penalty = 1.0 / (1.0 + 0.1 * (i - period_idx))
                row[period_idx] = 0.4 * distance_penalty

        # Enhanced attention to first token - much stronger than original
        if i > 0:
            # Boost first token attention significantly, especially for later tokens
            first_token_weight = 0.6 + 0.3 * min(1.0, i / 10.0)  # Ranges from 0.6 to 0.9
            row[0] = first_token_weight

        # Self-attention for punctuation and structural tokens
        current_token = tokens[i].strip()
        if current_token in ['.', ',', '!', '?', '"', "'", ''] or i == 0:
            row[i] = 0.2

        # Small residual attention to recent tokens
        for j in range(max(0, i-5), i):
            if row[j] == 0:  # Don't override existing strong attention
                row[j] = 0.05 * (1.0 - 0.1 * (i - j))

        # Ensure some attention to avoid zero rows
        if row.sum() == 0:
            if i > 0:
                row[i-1] = 1.0
            else:
                row[i] = 1.0

        attention[i] = row

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L3H25", attention



def prog_L3H26(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Structural anchor head: attends to first token, newlines, and sentence-ending punctuation with cross-sentence dependencies."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        return "prog_L3H26", np.zeros((0, 0))

    attention = np.zeros((n, n))

    # Find structural tokens
    newline_indices = [i for i, token in enumerate(tokens) if token.strip() == '']
    period_indices = [i for i, token in enumerate(tokens) if token.strip() == '.']

    # Find tokens that come after newlines (start of new sentences)
    post_newline_indices = set()
    for nl_idx in newline_indices:
        for j in range(nl_idx + 1, min(nl_idx + 10, n)):  # Look ahead up to 10 tokens
            post_newline_indices.add(j)

    for i in range(n):
        # First token gets maximum self-attention
        if i == 0:
            attention[i, 0] = 1.0
        else:
            # Strong attention to first token
            base_first_attention = 0.4

            # Boost attention to first token for post-newline tokens
            if i in post_newline_indices and len(period_indices) > 0:
                # Much stronger attention to first period for tokens after newlines
                first_period = period_indices[0]
                attention[i, first_period] += 0.6  # Strong cross-sentence attention
                attention[i, 0] += base_first_attention * 0.7  # Reduced first token attention
            else:
                attention[i, 0] = base_first_attention

            # High attention to newlines
            for nl_idx in newline_indices:
                if nl_idx <= i:
                    attention[i, nl_idx] += 0.35

            # High attention to periods
            for p_idx in period_indices:
                if p_idx <= i:
                    attention[i, p_idx] += 0.25

            # Moderate self-attention for structural tokens
            if i in newline_indices or i in period_indices:
                attention[i, i] += 0.15

            # Small residual attention to nearby tokens
            for j in range(max(0, i-3), i):
                if j not in newline_indices and j not in period_indices and j != 0:
                    attention[i, j] += 0.05

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L3H26", attention



def prog_L3H27(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Punctuation and newline attention head with positional bias and first-token attention."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention_matrix = np.zeros((n, n))

    # Find punctuation and newline tokens
    punct_indices = []
    newline_indices = []
    for i, token in enumerate(tokens):
        if token.strip() in ['.', ',', '!', '?', ';', ':']:
            punct_indices.append(i)
        elif token.strip() == '\n':
            newline_indices.append(i)

    # Get spacy analysis for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    # Check if first token is a content word
    first_token_is_content = False
    if len(token_to_spacy) > 0:
        for spacy_idx in token_to_spacy[0]:
            if spacy_idx < len(doc):
                if doc[spacy_idx].pos_ in ['NOUN', 'PROPN', 'VERB', 'ADJ', 'ADV']:
                    first_token_is_content = True
                    break

    for i in range(n):
        token = tokens[i]

        # High attention to newlines (strongest pattern)
        for newline_idx in newline_indices:
            if newline_idx <= i:
                attention_matrix[i, newline_idx] = 0.4

        # High attention to periods (second strongest)
        for punct_idx in punct_indices:
            if punct_idx <= i and tokens[punct_idx].strip() == '.':
                attention_matrix[i, punct_idx] = 0.35

        # Medium attention to other punctuation
        for punct_idx in punct_indices:
            if punct_idx <= i and tokens[punct_idx].strip() != '.':
                attention_matrix[i, punct_idx] = 0.15

        # NEW: Strong attention to first token if it's a content word
        if first_token_is_content and i > 0:
            attention_matrix[i, 0] = 0.6

        # Get spacy token info for current token
        spacy_tokens = []
        if i < len(token_to_spacy):
            for spacy_idx in token_to_spacy[i]:
                if spacy_idx < len(doc):
                    spacy_tokens.append(doc[spacy_idx])

        # Content words get higher attention to punctuation/newlines
        is_content_word = False
        for spacy_tok in spacy_tokens:
            if spacy_tok.pos_ in ['NOUN', 'VERB', 'ADJ', 'ADV']:
                is_content_word = True
                break

        if is_content_word:
            # Boost punctuation/newline attention for content words
            for newline_idx in newline_indices:
                if newline_idx <= i:
                    attention_matrix[i, newline_idx] *= 1.2
            for punct_idx in punct_indices:
                if punct_idx <= i:
                    attention_matrix[i, punct_idx] *= 1.1
            # Also boost first-token attention for content words
            if first_token_is_content and i > 0:
                attention_matrix[i, 0] *= 1.3

        # Small attention to recent tokens
        for j in range(max(0, i-5), i):
            if attention_matrix[i, j] == 0:  # Don't override punct/newline/first-token attention
                attention_matrix[i, j] = 0.02 * (1 / (i - j + 1))

        # Self-attention
        attention_matrix[i, i] = 0.01

    # Apply causal mask and normalize
    attention_matrix = apply_causal_mask(attention_matrix)
    attention_matrix = make_row_stochastic(attention_matrix)

    return "prog_L3H27", attention_matrix



def prog_L3H28(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Structural boundary attention with strong beginning-of-sequence focus."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L3H28", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Find structural tokens (newlines and periods)
    structural_tokens = []
    for i, token in enumerate(tokens):
        if token.strip() in ['\n', '.']:
            structural_tokens.append(i)

    # Find first tokens after newlines (sentence starts)
    sentence_starts = []
    for i in range(n):
        if i == 0:
            sentence_starts.append(i)
        elif tokens[i-1].strip() == '\n' and i < n:
            sentence_starts.append(i)

    # Find the first meaningful token (skip whitespace/quotes at start)
    first_meaningful = 0
    for i in range(n):
        if tokens[i].strip() and tokens[i].strip() not in ['"', "'", '`']:
            first_meaningful = i
            break

    for i in range(n):
        # Reduced base self-attention
        attention[i, i] = 0.05

        # Strong attention to structural tokens (newlines and periods)
        for struct_idx in structural_tokens:
            if struct_idx <= i:
                # Higher weight for newlines, moderate for periods
                if tokens[struct_idx].strip() == '\n':
                    attention[i, struct_idx] += 0.4
                else:  # periods
                    attention[i, struct_idx] += 0.25

        # Moderate attention to sentence starts
        for start_idx in sentence_starts:
            if start_idx <= i and start_idx != i:
                attention[i, start_idx] += 0.15

        # Strong attention to the first meaningful token of the entire sequence
        if first_meaningful <= i and first_meaningful != i:
            attention[i, first_meaningful] += 0.5

        # Small attention to immediate predecessor
        if i > 0:
            attention[i, i-1] += 0.05

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L3H28", attention



def prog_L3H29(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Attention head with extremely strong first-token bias and reduced self-attention."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L3H29", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    for i in range(n):
        for j in range(i + 1):  # Causal mask
            weight = 0.0

            # Reduced self-attention based on evaluation feedback
            if i == j:
                weight += 0.05  # Reduced from 0.3

            # Much stronger attention to first token
            if j == 0:
                # Dramatically increase first-token bias for later positions
                if i >= 3:
                    weight += 0.8  # Much higher for distant tokens
                else:
                    weight += 0.4  # Keep original for nearby tokens

            # High attention to punctuation marks
            if tokens[j] in ['.', '\n', ',']:
                weight += 0.35

            # Medium attention to nearby previous tokens
            if i != j and i - j <= 3:
                weight += 0.1 / (i - j + 1)

            # Small baseline attention
            weight += 0.01

            attention[i, j] = weight

    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L3H29", attention



def prog_L3H3(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary and structural landmark attention head with strong first-token attention."""
    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    # Identify sentence boundary tokens (periods, newlines)
    boundary_tokens = set()
    for i, token in enumerate(tokens):
        if token.strip() in ['.', '\n', '!', '?']:
            boundary_tokens.add(i)

    for i in range(n):
        # Strong self-attention for first token
        if i == 0:
            attention[i, i] = 1.0
            continue

        # Base attention distribution
        for j in range(i + 1):  # Causal mask
            # Strong attention to sentence boundaries
            if j in boundary_tokens:
                attention[i, j] = 0.3

            # Moderate attention to previous tokens with recency bias
            elif j == i - 1:
                attention[i, j] = 0.15
            elif j == i - 2:
                attention[i, j] = 0.08

            # Self-attention
            elif i == j:
                attention[i, j] = 0.05

            # Attention to content words (nouns, verbs, adjectives)
            elif token_to_spacy[j]:
                spacy_token = doc[token_to_spacy[j][0]]
                if spacy_token.pos_ in ['NOUN', 'VERB', 'ADJ', 'PROPN']:
                    attention[i, j] = 0.04
                else:
                    attention[i, j] = 0.01
            else:
                attention[i, j] = 0.01

        # Boost attention to the most recent sentence boundary
        recent_boundary = -1
        for j in range(i, -1, -1):
            if j in boundary_tokens:
                recent_boundary = j
                break

        if recent_boundary != -1:
            attention[i, recent_boundary] *= 2.0

        # NEW: Strong attention to first token, especially after sentence boundaries
        if i > 0:
            # Check if we're after a sentence boundary
            after_boundary = False
            for k in range(max(0, i-3), i):  # Look back a few tokens
                if k in boundary_tokens:
                    after_boundary = True
                    break

            if after_boundary:
                # Very strong attention to first token after sentence boundaries
                attention[i, 0] = 0.8
            else:
                # Moderate attention to first token in general
                attention[i, 0] = 0.1

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L3H3", attention



def prog_L3H30(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary detection head: attends to newlines, periods, and first tokens."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    # Identify structural tokens
    newline_indices = []
    period_indices = []
    first_token_idx = 0

    for i, token in enumerate(tokens):
        if token.strip() == '\n':
            newline_indices.append(i)
        elif token.strip() == '.':
            period_indices.append(i)

    for i in range(n):
        token = tokens[i].strip()

        # Base attention to self
        attention[i, i] = 0.02

        # Strong attention to newlines (primary structural markers)
        for newline_idx in newline_indices:
            if newline_idx <= i:
                attention[i, newline_idx] = 0.45

        # Strong attention to periods (secondary structural markers)
        for period_idx in period_indices:
            if period_idx <= i:
                attention[i, period_idx] = 0.4

        # High attention to first token (especially from early tokens)
        if first_token_idx <= i:
            if i <= 5:  # Very early tokens
                attention[i, first_token_idx] = 0.9
            else:  # Later tokens
                attention[i, first_token_idx] = 0.15

        # Special case: whitespace tokens get extra attention to nearby periods
        if token == '' or token.isspace():
            for j in range(max(0, i-3), i):
                if tokens[j].strip() == '.':
                    attention[i, j] = 0.6

        # Distribute remaining attention broadly to previous tokens
        for j in range(i):
            if attention[i, j] == 0:  # Only if not already set
                distance = i - j
                if distance <= 10:
                    attention[i, j] = max(0.01, 0.05 / (1 + distance * 0.5))
                else:
                    attention[i, j] = 0.01

    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L3H30", attention



def prog_L3H31(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Structural boundary attention head focusing on first tokens, newlines, and sentence endings."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    # Find structural positions
    first_token_idx = 0
    newline_indices = [i for i, token in enumerate(tokens) if token.strip() == '']
    period_indices = [i for i, token in enumerate(tokens) if token.strip() == '.']

    for i in range(n):
        token = tokens[i].strip()

        # Special handling for periods - attend to structural boundaries
        if token in ['.', '!', '?']:
            weights = {}

            # High attention to previous newlines
            for nl_idx in newline_indices:
                if nl_idx < i:
                    weights[nl_idx] = 0.45

            # High attention to previous periods
            for p_idx in period_indices:
                if p_idx < i:
                    weights[p_idx] = 0.42

            # Some self-attention
            weights[i] = 0.20

            # Normalize and assign
            if len(weights) > 1:  # If we have structural boundaries to attend to
                total_weight = sum(weights.values())
                for idx, weight in weights.items():
                    attention[i, idx] = weight / total_weight
            else:
                # Fallback: pure self-attention
                attention[i, i] = 1.0

        # High attention to first token for early position tokens (positions 1-3)
        elif i <= 3 and i > 0:
            attention[i, first_token_idx] = 0.98

        # For other tokens, distribute attention based on structural hierarchy
        else:
            weights = {}

            # High attention to newlines
            for nl_idx in newline_indices:
                if nl_idx <= i:
                    weights[nl_idx] = 0.45

            # Medium-high attention to periods
            for p_idx in period_indices:
                if p_idx <= i:
                    weights[p_idx] = 0.42

            # Lower attention to first token
            weights[first_token_idx] = 0.15

            # Normalize and assign
            if weights:
                total_weight = sum(weights.values())
                for idx, weight in weights.items():
                    attention[i, idx] = weight / total_weight
            else:
                # Fallback: attend to self
                attention[i, i] = 1.0

    # Apply causal mask and ensure row stochastic
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L3H31", attention



def prog_L3H4(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Boundary punctuation attention head with strong first-token attention pattern."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    # Find boundary punctuation (periods and newlines)
    boundary_indices = []
    for i, token in enumerate(tokens):
        if token.strip() in ['.', '\n']:
            boundary_indices.append(i)

    # Check if first token is a content word (not punctuation/whitespace)
    first_token_is_content = len(tokens) > 0 and tokens[0].strip() not in ['.', '\n', '', ' ']

    for i in range(n):
        token = tokens[i].strip()

        # Self-attention baseline - increased for punctuation
        if token in ['.', '\n']:
            attention[i, i] = 0.6  # Much stronger self-attention for punctuation
        else:
            attention[i, i] = 0.01

        if token in ['.', '\n']:
            # Punctuation tokens attend strongly to previous boundary punctuation
            for boundary_idx in boundary_indices:
                if boundary_idx < i:
                    # Distance decay for previous boundaries
                    distance = i - boundary_idx
                    attention[i, boundary_idx] = max(0.3, 0.8 / (1 + 0.1 * distance))

            # Also attend to first token
            if i > 0:
                attention[i, 0] = 0.15

        else:
            # Non-punctuation tokens: special case for strong first-token attention
            if first_token_is_content and i > 0:
                # Strong attention to first token
                attention[i, 0] = 0.5

                # Reduced attention to boundary punctuation to compensate
                max_boundary_attention = 0.0
                for boundary_idx in boundary_indices:
                    if boundary_idx < i:
                        distance = i - boundary_idx
                        boundary_weight = max(0.1, 0.3 / (1 + 0.05 * distance))
                        attention[i, boundary_idx] = boundary_weight
                        max_boundary_attention = max(max_boundary_attention, boundary_weight)
            else:
                # Original behavior for other cases
                max_boundary_attention = 0.0

                for boundary_idx in boundary_indices:
                    if boundary_idx < i:
                        # Stronger attention to more recent boundaries
                        distance = i - boundary_idx
                        boundary_weight = max(0.2, 0.5 / (1 + 0.05 * distance))
                        attention[i, boundary_idx] = boundary_weight
                        max_boundary_attention = max(max_boundary_attention, boundary_weight)

                # Attend to first token with moderate strength
                if i > 0:
                    attention[i, 0] = min(0.25, max_boundary_attention * 0.7)

            # Small attention to nearby previous tokens
            for j in range(max(0, i-3), i):
                if j not in boundary_indices and j != 0:
                    distance = i - j
                    attention[i, j] = max(0.01, 0.08 / (1 + 0.3 * distance))

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L3H4", attention



def prog_L3H5(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary and discourse structure attention head with strong first-token attention."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        # Get spacy alignment for current token
        spacy_indices = token_to_spacy[i]
        current_spacy_token = doc[spacy_indices[0]] if spacy_indices else None

        for j in range(i + 1):  # Causal mask
            target_token = tokens[j]
            target_spacy_indices = token_to_spacy[j]
            target_spacy_token = doc[target_spacy_indices[0]] if target_spacy_indices else None

            # Base attention
            base_weight = 0.01

            # Very strong attention to newlines and periods (sentence boundaries)
            if target_token.strip() in ['\n', '.']:
                base_weight += 0.3

            # Strong attention to other punctuation
            elif target_token.strip() in [',', '!', '?', ';', ':', '"', "'", ')']:
                base_weight += 0.15

            # Attention to first token after sentence boundaries
            if j > 0 and tokens[j-1].strip() in ['\n', '.']:
                base_weight += 0.1

            # Self-attention
            if i == j:
                base_weight += 0.05

            # Distance decay for local context
            distance = i - j
            if distance <= 3:
                base_weight += 0.02 * (4 - distance) / 4

            # Boost for tokens at start of sequence
            if j < 3:
                base_weight += 0.05 * (3 - j) / 3

            # Boost for words that are sentence/paragraph starters
            if target_spacy_token and target_spacy_token.is_sent_start:
                base_weight += 0.08

            # Slight boost for content words attending to function words
            if (current_spacy_token and target_spacy_token and
                current_spacy_token.pos_ in ['NOUN', 'VERB', 'ADJ'] and
                target_spacy_token.pos_ in ['DET', 'PREP', 'CONJ']):
                base_weight += 0.02

            # TARGETED FIX: Strong attention to first token when it's a content word
            if (j == 0 and target_spacy_token and 
                target_spacy_token.pos_ in ['NOUN', 'VERB', 'ADJ', 'PROPN'] and
                i > 2):  # Only for tokens beyond very early positions
                # Scale based on distance - stronger for later tokens
                first_token_boost = 0.4 + 0.3 * min(i / 10, 1.0)
                base_weight += first_token_boost

            attention[i, j] = base_weight

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L3H5", attention



def prog_L3H6(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary and structural anchor attention head that focuses on periods, newlines, and sentence beginnings."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    # Find structural tokens (periods, newlines, sentence beginnings)
    structural_tokens = set()
    first_content_token = None

    for i, token in enumerate(tokens):
        # Identify punctuation and whitespace
        if token.strip() in ['.', '\n', '!', '?', ';']:
            structural_tokens.add(i)
        # Find first meaningful token (not whitespace/empty)
        if first_content_token is None and token.strip():
            first_content_token = i

    # If we found a first content token, it's also structural
    if first_content_token is not None:
        structural_tokens.add(first_content_token)

    for i in range(n):
        current_token = tokens[i].strip()

        # Very high self-attention for first token and punctuation
        if i == 0 or current_token in ['.', '\n', '!', '?']:
            attention[i, i] = 0.6

        # Strong attention to structural anchors
        for struct_idx in structural_tokens:
            if struct_idx <= i:  # Causal constraint
                if struct_idx == i:
                    continue  # Already handled self-attention above

                # Distance decay from structural anchors
                distance = i - struct_idx
                base_weight = 0.3

                # Special boost for periods and newlines
                if tokens[struct_idx].strip() in ['.', '\n']:
                    base_weight = 0.35

                # First token gets extra attention
                if struct_idx == first_content_token:
                    base_weight = 0.25

                # Apply distance decay
                weight = base_weight * np.exp(-distance * 0.1)
                attention[i, struct_idx] = weight

        # Add some recency bias to recent tokens
        for j in range(max(0, i-3), i):
            if j not in structural_tokens:
                distance = i - j
                weight = 0.05 * np.exp(-distance * 0.5)
                attention[i, j] += weight

        # Small self-attention for non-structural tokens
        if attention[i, i] == 0:
            attention[i, i] = 0.02

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L3H6", attention



def prog_L3H7(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary and structural attention head that focuses on punctuation and first tokens."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention_matrix = np.zeros((n, n))

    # Identify structural tokens
    punctuation_tokens = set()
    newline_tokens = set()
    first_tokens = set([0])  # Always include absolute first token

    for i, token in enumerate(tokens):
        if token.strip() in ['.', '!', '?', ',', ';', ':']:
            punctuation_tokens.add(i)
        elif token.strip() == '\n' or token == '\n':
            newline_tokens.add(i)
            # Token after newline is often a sentence start
            if i + 1 < n:
                first_tokens.add(i + 1)

    for i in range(n):
        # Base attention distribution
        base_weights = np.zeros(i + 1)  # Only attend to previous tokens (causal)

        # Strong attention to punctuation (especially periods and newlines)
        for j in range(i + 1):
            if j in punctuation_tokens:
                if tokens[j].strip() == '.':
                    base_weights[j] = 0.35  # Very high for periods
                else:
                    base_weights[j] = 0.15  # High for other punctuation
            elif j in newline_tokens:
                base_weights[j] = 0.30  # Very high for newlines

        # High attention to first tokens
        for j in first_tokens:
            if j <= i:
                if j == 0:
                    base_weights[j] = max(base_weights[j], 0.25)  # High for absolute first
                else:
                    base_weights[j] = max(base_weights[j], 0.20)  # High for sentence starts

        # Self-attention
        base_weights[i] = max(base_weights[i], 0.08)

        # Local context attention (previous few tokens)
        for j in range(max(0, i-3), i):
            base_weights[j] = max(base_weights[j], 0.02)

        # If no strong structural attention, distribute more evenly with recency bias
        if np.sum(base_weights) < 0.3:
            for j in range(i + 1):
                distance = i - j + 1
                base_weights[j] = max(base_weights[j], 0.5 / distance)

        # Normalize
        if np.sum(base_weights) > 0:
            base_weights = base_weights / np.sum(base_weights)
        else:
            base_weights[i] = 1.0

        attention_matrix[i, :i+1] = base_weights

    # Apply causal mask and ensure row stochastic
    attention_matrix = apply_causal_mask(attention_matrix)
    attention_matrix = make_row_stochastic(attention_matrix)

    return "prog_L3H7", attention_matrix



def prog_L3H8(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Punctuation and first-token anchoring head with content similarity."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L3H8", np.zeros((n_empty, n_empty))

    attention_matrix = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        # Strong attention to periods and newlines
        period_weight = 0.0
        newline_weight = 0.0

        for j in range(i + 1):
            if tokens[j] in [".", "!"]:
                period_weight += 0.4
            elif tokens[j] == "\n":
                newline_weight += 0.35

        # Strong attention to first token (position 0)
        if i > 0:
            attention_matrix[i, 0] = 0.25
        else:
            attention_matrix[i, 0] = 1.0

        # Distribute period/newline attention
        for j in range(i + 1):
            if tokens[j] in [".", "!"]:
                attention_matrix[i, j] += period_weight / max(1, sum(1 for k in range(i + 1) if tokens[k] in [".", "!"]))
            elif tokens[j] == "\n":
                attention_matrix[i, j] += newline_weight / max(1, sum(1 for k in range(i + 1) if tokens[k] == "\n"))

        # Add content-based attention using embedding similarity
        remaining_weight = max(0.0, 1.0 - attention_matrix[i].sum())

        if remaining_weight > 0.0:
            similarities = []
            for j in range(i + 1):
                if tokens[j] not in [".", "!", "\n"] and j != 0:
                    sim = _char_sim(tokens[i], tokens[j])
                    similarities.append((j, max(0.0, sim)))
                else:
                    similarities.append((j, 0.0))

            # Add recency bias and linguistic features
            for j, base_sim in similarities:
                if base_sim > 0.0:
                    # Recency decay
                    distance = i - j
                    recency_factor = max(0.1, 1.0 / (1.0 + 0.1 * distance))

                    # Boost for linguistic relationships
                    linguistic_boost = 1.0
                    if token_to_spacy[i] and token_to_spacy[j]:
                        spacy_i = token_to_spacy[i][0] if token_to_spacy[i] else None
                        spacy_j = token_to_spacy[j][0] if token_to_spacy[j] else None

                        if spacy_i is not None and spacy_j is not None and spacy_i < len(doc) and spacy_j < len(doc):
                            tok_i = doc[spacy_i]
                            tok_j = doc[spacy_j]

                            # Boost for syntactic relationships
                            if tok_j in tok_i.ancestors or tok_i in tok_j.ancestors:
                                linguistic_boost = 1.5
                            elif tok_i.head == tok_j.head and tok_i.head != tok_i:
                                linguistic_boost = 1.3

                    final_weight = base_sim * recency_factor * linguistic_boost
                    attention_matrix[i, j] += remaining_weight * final_weight

        # Self-attention as fallback
        if attention_matrix[i].sum() < 0.1:
            attention_matrix[i, i] = 1.0

    # Apply causal mask and normalize
    attention_matrix = apply_causal_mask(attention_matrix)
    attention_matrix = make_row_stochastic(attention_matrix)

    return "prog_L3H8", attention_matrix



def prog_L3H9(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Structural boundary attention head focusing on sentence/line delimiters and positional patterns."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L3H9", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    for i in range(n):
        current_token = tokens[i].strip()

        for j in range(i + 1):  # Causal mask
            target_token = tokens[j].strip()
            weight = 0.0

            # Very strong self-attention for first token
            if i == 0 and j == 0:
                weight = 1.0

            # Strong attention to newlines from most tokens
            elif target_token == '\n':
                weight = 0.4 + 0.2 * (1.0 / (1.0 + abs(i - j)))

            # Strong attention to periods from many tokens
            elif target_token == '.':
                weight = 0.35 + 0.15 * (1.0 / (1.0 + abs(i - j)))

            # Moderate attention to first token from later tokens
            elif j == 0 and i > 0:
                weight = 0.15 + 0.1 * (1.0 / (1.0 + i * 0.1))

            # Self-attention for current token
            elif i == j:
                weight = 0.05

            # Previous token attention with decay
            elif j == i - 1:
                weight = 0.08

            # General proximity bias with small weights
            else:
                distance = i - j
                if distance <= 3:
                    weight = 0.02 / (1.0 + distance)
                else:
                    weight = 0.005

            attention[i, j] = weight

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L3H9", attention



def prog_L4H0(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary and first-token attention head with structural focus."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L4H0", np.zeros((n_empty, n_empty))

    attention_matrix = np.zeros((n, n))

    # Find sentence boundary tokens (periods, newlines, exclamation marks, question marks)
    boundary_tokens = set()
    for i, token in enumerate(tokens):
        if token.strip() in ['.', '\n', '!', '?']:
            boundary_tokens.add(i)

    for i in range(n):
        # Self-attention baseline
        attention_matrix[i, i] = 0.1

        # Strong self-attention for first token
        if i == 0:
            attention_matrix[i, i] = 1.0
            continue

        # High attention to first token from all positions
        attention_matrix[i, 0] = 0.3

        # High attention to sentence boundary tokens
        for boundary_idx in boundary_tokens:
            if boundary_idx <= i:  # Respect causal mask
                attention_matrix[i, boundary_idx] = 0.5

        # Find the most recent boundary token before position i
        recent_boundary = -1
        for boundary_idx in sorted(boundary_tokens, reverse=True):
            if boundary_idx < i:
                recent_boundary = boundary_idx
                break

        # Extra attention to most recent boundary
        if recent_boundary >= 0:
            attention_matrix[i, recent_boundary] += 0.2

        # Moderate attention to immediately preceding token
        if i > 0:
            attention_matrix[i, i-1] = 0.15

        # Small distributed attention to other accessible tokens
        for j in range(i):
            if j not in boundary_tokens and j != 0:
                attention_matrix[i, j] += 0.05

    # Apply causal mask and normalize
    attention_matrix = apply_causal_mask(attention_matrix)
    attention_matrix = make_row_stochastic(attention_matrix)

    return "prog_L4H0", attention_matrix



def prog_L4H1(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary attention head with very strong first-token attention."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L4H1", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Identify boundary tokens (newlines, periods, first token)
    boundary_indices = set()

    # Add first token
    boundary_indices.add(0)

    # Add punctuation boundaries
    for i, token in enumerate(tokens):
        if token.strip() in ['.', '\n', '!', '?']:
            boundary_indices.add(i)

    # Main attention pattern: attend strongly to boundary tokens
    for i in range(n):
        # Very strong attention to the absolute first token
        if i > 0:  # all tokens except the first attend strongly to token 0
            attention[i, 0] = 0.50  # Much higher than original 0.25

        # Strong attention to other boundary tokens (within causal mask)
        for j in boundary_indices:
            if j <= i and j != 0:  # exclude first token, already handled above
                if tokens[j].strip() == '\n':
                    attention[i, j] = 0.35  # Very high for newlines
                elif tokens[j].strip() == '.':
                    # Reduce period attention when not at sentence start
                    attention[i, j] = 0.20  # Lower than original 0.30

        # Self-attention component
        attention[i, i] += 0.05

        # Moderate attention to recent tokens (recency bias)
        for j in range(max(0, i-3), i):
            if j not in boundary_indices:
                attention[i, j] += 0.02

        # Small baseline attention to all previous tokens
        for j in range(i):
            attention[i, j] += 0.01

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L4H1", attention



def prog_L4H10(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Structural boundary attention head that attends to sentence/section delimiters."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    # Find structural boundary tokens
    boundary_indices = []
    for i, token in enumerate(tokens):
        if token.strip() in ['.', '!', '?', '\n'] or i == 0:
            boundary_indices.append(i)

    for i in range(n):
        for j in range(i + 1):  # Causal mask
            weight = 0.0

            # Strong attention to structural boundaries
            if j in boundary_indices:
                # First token gets highest attention
                if j == 0:
                    weight = 0.6
                # Newlines get high attention  
                elif tokens[j].strip() == '\n':
                    weight = 0.4
                # Periods get moderate-high attention
                elif tokens[j].strip() in ['.', '!', '?']:
                    weight = 0.35

            # Self-attention for boundary tokens themselves
            if i == j and i in boundary_indices:
                if i == 0:
                    weight = 1.0  # First token has perfect self-attention
                elif tokens[i].strip() == '.':
                    weight = 0.65
                else:
                    weight = 0.4

            # Weak baseline attention to other tokens
            elif i == j:
                weight = 0.01
            else:
                weight = max(weight, 0.01)

            attention[i, j] = weight

    attention = make_row_stochastic(attention)
    attention = apply_causal_mask(attention)

    return "prog_L4H10", attention



def prog_L4H11(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary attention head - attends to newlines, sentence-ending punctuation, and first tokens."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    # Identify structural tokens
    newline_indices = []
    sentence_end_indices = []
    first_token_indices = []

    for i, token in enumerate(tokens):
        if token.strip() == '\n':
            newline_indices.append(i)
        elif token.strip() in ['.', '!', '?']:
            sentence_end_indices.append(i)
        elif i == 0:
            first_token_indices.append(i)
        elif i > 0 and tokens[i-1].strip() == '\n':
            first_token_indices.append(i)

    # Base attention distribution
    for i in range(n):
        # High attention to newlines
        for j in newline_indices:
            if j <= i:
                attention[i, j] = 0.44

        # High attention to sentence-ending punctuation
        for j in sentence_end_indices:
            if j <= i:
                attention[i, j] = 0.40

        # Moderate attention to first tokens
        for j in first_token_indices:
            if j <= i:
                attention[i, j] = 0.25

        # Special case: first token attends strongly to itself
        if i in first_token_indices:
            attention[i, i] = 1.0

        # Low baseline attention to adjacent tokens
        if i > 0:
            attention[i, i-1] = 0.05
        attention[i, i] = max(attention[i, i], 0.02)

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L4H11", attention



def prog_L4H12(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Structural boundary attention head focusing on sentence breaks and punctuation."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L4H12", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Find structural markers (newlines, periods, commas)
    structural_indices = []
    for i, token in enumerate(tokens):
        if token.strip() in ['\n', '.', ',']:
            structural_indices.append(i)

    for i in range(n):
        token = tokens[i]

        # Strong self-attention for first token
        if i == 0:
            attention[i, i] = 1.0
        else:
            # Base attention to previous structural markers
            for struct_idx in structural_indices:
                if struct_idx < i:
                    # More recent structural markers get higher attention
                    distance = i - struct_idx
                    if distance <= 3:
                        attention[i, struct_idx] = 0.6 / (distance * 0.5 + 1)
                    else:
                        attention[i, struct_idx] = 0.4 / (distance * 0.3 + 1)

            # Self-attention for structural markers
            if token.strip() in ['\n', '.', ',']:
                attention[i, i] = 0.3

            # Weak attention to recent non-structural tokens
            for j in range(max(0, i-5), i):
                if j not in structural_indices:
                    attention[i, j] = 0.1 / (i - j + 1)

            # If no strong structural attention, distribute to nearby tokens
            if attention[i].sum() < 0.1:
                for j in range(max(0, i-3), i+1):
                    attention[i, j] = 0.2 / (abs(i-j) + 1)

    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L4H12", attention



def prog_L4H13(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Structural boundary attention with focus on newlines, periods, and local adjacency."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L4H13", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        token_i = tokens[i]

        # Strong attention to newlines and periods from most tokens
        for j in range(i + 1):
            token_j = tokens[j]

            # High attention to newlines and periods
            if token_j.strip() in ['\n', '.']:
                attention[i, j] = 0.5

            # Strong attention to first token (index 0)
            elif j == 0:
                attention[i, j] = 0.3

            # Adjacent token attention (especially i -> i-1)
            elif j == i - 1:
                attention[i, j] = 0.4

            # Self attention
            elif i == j:
                attention[i, j] = 0.2

            # Check for high similarity tokens
            elif _char_sim(tokens[i], tokens[j]) > 0.8:
                attention[i, j] = 0.3

            # Moderate attention to nearby tokens
            elif abs(i - j) <= 2:
                attention[i, j] = 0.1

            # Lower baseline attention
            else:
                attention[i, j] = 0.02

        # Boost attention for specific patterns
        # Boost attention from tokens after punctuation to the punctuation
        if i > 0 and tokens[i-1].strip() in ['.', '!', '?', '"']:
            for j in range(i):
                if tokens[j].strip() in ['\n']:
                    attention[i, j] *= 2.0

        # Special handling for quote-like tokens
        if token_i.strip().startswith('"') or token_i.strip().startswith("'"):
            for j in range(i):
                if tokens[j].strip() in ['\n', '.']:
                    attention[i, j] *= 1.5

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L4H13", attention



def prog_L4H14(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Structural delimiter attention: focuses on newlines, sentence boundaries, and first token."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L4H14", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Find structural delimiters
    newline_indices = [i for i, token in enumerate(tokens) if token.strip() == '\n']
    period_indices = [i for i, token in enumerate(tokens) if token.strip() == '.']
    first_token_idx = 0

    for i in range(n):
        row_weights = np.zeros(n)

        # Strong attention to newlines (highest priority)
        for nl_idx in newline_indices:
            if nl_idx <= i:
                row_weights[nl_idx] = 0.5

        # Moderate attention to periods
        for p_idx in period_indices:
            if p_idx <= i:
                row_weights[p_idx] += 0.3

        # Attention to first token
        row_weights[first_token_idx] += 0.25

        # Self-attention (stronger for first token)
        if i == 0:
            row_weights[i] = 1.0
        else:
            row_weights[i] += 0.1

        # Small amount of attention to recent tokens
        for j in range(max(0, i-3), i):
            if j != i:
                row_weights[j] += 0.05

        # Apply causal mask
        row_weights[i+1:] = 0

        # Normalize
        if row_weights.sum() > 0:
            row_weights = row_weights / row_weights.sum()
        else:
            row_weights[i] = 1.0

        attention[i] = row_weights

    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L4H14", attention



def prog_L4H15(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Structural boundary attention head focusing on first token and line breaks."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        # Very high attention to first token
        attention[i, 0] = 0.8

        # Strong attention to newline characters
        for j in range(i + 1):
            if tokens[j].strip() == '':  # newline or whitespace
                attention[i, j] = 0.4

        # Moderate attention to sentence-ending punctuation
        for j in range(i + 1):
            if tokens[j] in ['.', '!', '?']:
                attention[i, j] = 0.35

        # Self-attention baseline
        attention[i, i] = 0.05

        # Small attention to immediate previous token
        if i > 0:
            attention[i, i-1] = 0.1

        # Boost attention for tokens that are sentence boundaries
        spacy_indices = token_to_spacy[i]
        if spacy_indices:
            spacy_token = doc[spacy_indices[0]]
            # If this token starts a sentence, attend more to first token
            if spacy_token.is_sent_start:
                attention[i, 0] *= 1.2

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L4H15", attention



def prog_L4H16(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Attention to structural boundaries (newlines, periods) and sequence starts."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention_matrix = np.zeros((n, n))

    # Find boundary tokens (newlines and periods)
    boundary_indices = []
    for i, token in enumerate(tokens):
        if token.strip() in ['\n', '.']:
            boundary_indices.append(i)

    for i in range(n):
        # Base attention distribution
        row_attention = np.zeros(n)

        # Strong attention to first token (if not self)
        if i > 0:
            row_attention[0] = 0.3

        # Self-attention, especially strong for first token
        if i == 0:
            row_attention[i] = 0.7
        else:
            row_attention[i] = 0.1

        # High attention to boundary tokens (newlines and periods)
        for boundary_idx in boundary_indices:
            if boundary_idx <= i:  # Causal constraint
                # Distance-based attention to boundaries
                distance = i - boundary_idx
                if distance == 0:
                    # Self-attention to boundary already handled above
                    pass
                elif distance <= 10:
                    # Strong attention to recent boundaries
                    boundary_weight = 0.4 * (0.9 ** distance)
                    row_attention[boundary_idx] += boundary_weight
                else:
                    # Weaker attention to distant boundaries
                    row_attention[boundary_idx] += 0.05

        # Add small uniform attention to all previous tokens
        for j in range(i):
            row_attention[j] += 0.02

        # Normalize the attention row
        if row_attention.sum() > 0:
            attention_matrix[i] = row_attention / row_attention.sum()
        else:
            # Fallback: attend only to self
            attention_matrix[i, i] = 1.0

    # Apply causal mask and ensure row-stochastic
    attention_matrix = apply_causal_mask(attention_matrix)
    attention_matrix = make_row_stochastic(attention_matrix)

    return "prog_L4H16", attention_matrix



def prog_L4H17(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary and first-token attention head."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    # Find newline positions and the first token
    newline_positions = []
    for i, token in enumerate(tokens):
        if token.strip() == '\n':
            newline_positions.append(i)

    for i in range(n):
        # Strong attention to first token
        attention[i, 0] = 0.6

        # Strong attention to newlines (sentence boundaries)
        for newline_pos in newline_positions:
            if newline_pos <= i:  # respect causal mask
                attention[i, newline_pos] = 0.5

        # Medium attention to periods (sentence ends)
        for j in range(i + 1):
            if tokens[j].strip() == '.':
                attention[i, j] = 0.3

        # Small self-attention
        attention[i, i] = 0.1

        # Small attention to recent tokens
        for j in range(max(0, i-3), i):
            attention[i, j] += 0.05

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L4H17", attention



def prog_L4H18(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Structural boundary attention head with strong beginning-of-sequence focus."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention_matrix = np.zeros((n, n))

    # Find structural tokens (newlines and periods)
    newline_indices = [i for i, token in enumerate(tokens) if token.strip() == '\n']
    period_indices = [i for i, token in enumerate(tokens) if token.strip() == '.']

    for i in range(n):
        current_token = tokens[i]

        # Base uniform distribution over available positions
        attention_weights = np.ones(i + 1)  # Causal mask

        # Strong boost for newline tokens
        for j in newline_indices:
            if j <= i:
                attention_weights[j] *= 20.0

        # Medium boost for period tokens  
        for j in period_indices:
            if j <= i:
                attention_weights[j] *= 8.0

        # NEW: Very strong boost for first token (beginning-of-sequence attention)
        if i > 0:  # Don't boost first token attending to itself extra
            attention_weights[0] *= 25.0

        # Reduce self-attention boost to compensate for over-prediction
        attention_weights[i] *= 1.2

        # Add positional decay (slight preference for more recent tokens)
        for j in range(i + 1):
            decay_factor = 0.95 ** (i - j)
            attention_weights[j] *= decay_factor

        # Handle special case for first token
        if i == 0:
            attention_weights[0] = 1.0

        attention_matrix[i, :i+1] = attention_weights

    # Apply causal mask and normalize
    attention_matrix = apply_causal_mask(attention_matrix)
    attention_matrix = make_row_stochastic(attention_matrix)

    return "prog_L4H18", attention_matrix



def prog_L4H19(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Attention to sentence boundaries, periods, newlines, and first tokens."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L4H19", np.zeros((n_empty, n_empty))

    # Initialize attention matrix
    attention = np.zeros((n, n))

    # Get spacy alignment for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        for j in range(i + 1):  # Causal mask: j <= i
            weight = 0.0

            # Very high attention to periods
            if tokens[j].strip() == '.':
                weight += 0.4

            # High attention to newlines
            elif tokens[j].strip() == '\n':
                weight += 0.35

            # High attention to first token
            elif j == 0:
                weight += 0.3

            # Self-attention
            elif i == j:
                weight += 0.05

            # Moderate attention to other punctuation
            elif tokens[j].strip() in [',', '!', '?', ';', ':']:
                weight += 0.1

            # Some attention based on position - recency bias
            else:
                distance = i - j
                if distance <= 5:
                    weight += 0.02 / (distance + 1)
                else:
                    weight += 0.01

            # Check if target token is at sentence boundary using spacy
            if token_to_spacy[j]:
                spacy_idx = token_to_spacy[j][0]
                if spacy_idx < len(doc):
                    spacy_token = doc[spacy_idx]
                    # Boost attention to tokens that end sentences
                    if spacy_token.is_sent_end:
                        weight += 0.1

            attention[i, j] = weight

    # Normalize and apply causal mask
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L4H19", attention



def prog_L4H2(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary and structure tracking head with strong attention to periods, newlines, and first tokens."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L4H2", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        # Base self-attention
        attention[i, i] = 0.02

        # Strong attention to sentence boundaries
        for j in range(i + 1):
            token = tokens[j].strip()

            # Very strong attention to periods
            if token == '.':
                attention[i, j] += 0.35

            # Strong attention to newlines
            elif token == '\n':
                attention[i, j] += 0.32

            # Moderate attention to first token
            elif j == 0:
                attention[i, j] += 0.15

            # Some attention to commas as minor boundaries
            elif token == ',':
                attention[i, j] += 0.08

        # Additional syntactic patterns
        spacy_indices = token_to_spacy[i]
        if spacy_indices:
            spacy_token = doc[spacy_indices[0]]

            # Verbs attend to their subjects
            if spacy_token.pos_ == 'VERB':
                for j in range(i):
                    j_spacy = token_to_spacy[j]
                    if j_spacy:
                        j_token = doc[j_spacy[0]]
                        if j_token.dep_ in ['nsubj', 'nsubjpass']:
                            attention[i, j] += 0.03

            # Pronouns attend to potential antecedents
            elif spacy_token.pos_ == 'PRON':
                for j in range(max(0, i-10), i):
                    j_spacy = token_to_spacy[j]
                    if j_spacy:
                        j_token = doc[j_spacy[0]]
                        if j_token.pos_ in ['NOUN', 'PROPN']:
                            attention[i, j] += 0.02

        # Local attention to immediate context
        for j in range(max(0, i-3), i):
            attention[i, j] += 0.01

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L4H2", attention



def prog_L4H20(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Structural boundary attention head with enhanced first-token attention for content words."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L4H20", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    alignment = _align_to_spacy(sentence, tokens)

    for i in range(n):
        # Base attention distribution
        for j in range(i + 1):  # Causal mask
            # Very high attention to newlines
            if tokens[j].strip() == '' and '\n' in tokens[j]:
                attention[i, j] = 0.35
            # High attention to periods
            elif tokens[j].strip() == '.':
                attention[i, j] = 0.25
            # Enhanced first token attention for content words
            elif j == 0:
                # Check if current token is a content word
                is_content_word = False
                if alignment[i]:  # If token aligns to spacy tokens
                    for spacy_idx in alignment[i]:
                        if spacy_idx < len(doc):
                            spacy_token = doc[spacy_idx]
                            if spacy_token.pos_ in ['NOUN', 'VERB', 'ADJ', 'ADV']:
                                is_content_word = True
                                break

                # Much stronger first-token attention for content words
                if is_content_word:
                    attention[i, j] = 0.65
                else:
                    attention[i, j] = 0.15
            # Self-attention
            elif i == j:
                attention[i, j] = 0.08
            # Low baseline attention to other tokens
            else:
                attention[i, j] = 0.01

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L4H20", attention



def prog_L4H21(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Previous-token attention with strong sentence boundary emphasis and first-token anchoring."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L4H21", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    for i in range(n):
        # Self-attention baseline
        attention[i, i] = 0.1

        # Very strong attention to immediately previous token
        if i > 0:
            attention[i, i-1] = 5.0

        # Strong attention to newlines and periods from all positions
        for j in range(i + 1):
            if tokens[j].strip() in ['\n', '.']:
                attention[i, j] += 3.0

        # Moderate attention to first token from later positions
        if i > 2:
            attention[i, 0] += 1.0

        # Additional boost for tokens that are close to sentence boundaries
        for j in range(i + 1):
            # Look for tokens near newlines or periods
            is_near_boundary = False
            if j > 0 and tokens[j-1].strip() in ['\n', '.']:
                is_near_boundary = True
            if j < len(tokens) - 1 and tokens[j+1].strip() in ['\n', '.']:
                is_near_boundary = True

            if is_near_boundary:
                attention[i, j] += 0.5

        # Strong first-token anchoring pattern: detect when first token is a common connector/determiner
        if n > 3 and i > 3:  # Only for longer sequences and later positions
            first_token = tokens[0].strip().lower()
            # Check if first token is a common word that often gets strong attention
            if (first_token in ['and', 'the', 'a', 'an', 'but', 'or', 'so', ',', 'then', 'now', 'when', 'while', 'after', 'before'] or
                len(first_token) <= 3):  # Short words often get this pattern
                attention[i, 0] += 4.0  # Strong additional boost to first token

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L4H21", attention



def prog_L4H22(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Attention head focusing on sentence boundaries and sequence structure markers."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    # Identify sentence boundaries and structural tokens
    sentence_boundaries = []
    first_tokens = []

    for i, token in enumerate(tokens):
        # Sentence boundaries (periods and newlines)
        if token.strip() in ['.', '\n']:
            sentence_boundaries.append(i)
        # Track potential sentence start tokens (after boundaries or at beginning)
        if i == 0 or (i > 0 and tokens[i-1].strip() in ['.', '\n']):
            first_tokens.append(i)

    for i in range(n):
        # Strong self-attention for first token
        if i == 0:
            attention[i, i] = 0.6
        else:
            attention[i, i] = 0.05

        # High attention to sentence boundaries
        for boundary_idx in sentence_boundaries:
            if boundary_idx <= i:
                # Distance-based decay for sentence boundaries
                distance = i - boundary_idx
                if distance == 0:
                    weight = 0.4
                elif distance <= 5:
                    weight = 0.3 - 0.03 * distance
                else:
                    weight = 0.15
                attention[i, boundary_idx] += weight

        # Attention to first tokens and sentence beginnings
        for first_idx in first_tokens:
            if first_idx <= i and first_idx != i:
                distance = i - first_idx
                if distance <= 3:
                    weight = 0.2 - 0.03 * distance
                else:
                    weight = 0.1
                attention[i, first_idx] += weight

        # Special boost for first token of sequence
        if i > 0:
            attention[i, 0] += 0.15

        # Small amount of attention to recent tokens
        for j in range(max(0, i-3), i):
            if j not in sentence_boundaries and j not in first_tokens:
                attention[i, j] += 0.02

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L4H22", attention



def prog_L4H23(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary and structural marker attention head."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L4H23", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        token = tokens[i]

        # Find structural markers: first token, newlines, periods
        first_token_idx = 0
        newline_indices = [j for j in range(i + 1) if tokens[j].strip() == '']
        period_indices = [j for j in range(i + 1) if tokens[j].strip() == '.']

        # Base attention distribution
        for j in range(i + 1):  # Causal mask
            target_token = tokens[j]

            # Strong attention to first token
            if j == first_token_idx:
                attention[i, j] = 0.4

            # Strong attention to newlines
            elif target_token.strip() == '':
                attention[i, j] = 0.35

            # Strong attention to periods
            elif target_token.strip() == '.':
                attention[i, j] = 0.3

            # Self-attention for punctuation
            elif i == j and (token.strip() in '.,!?"\''):
                attention[i, j] = 0.6

            # Moderate attention to recent tokens
            elif i - j <= 3:
                attention[i, j] = 0.1 / (1 + (i - j))

            # Low baseline attention
            else:
                attention[i, j] = 0.02

        # Special boost for punctuation self-attention
        if token.strip() in '.,!?"\'':
            attention[i, i] *= 2.0

        # Boost attention to structural markers based on token properties
        spacy_indices = token_to_spacy[i]
        if spacy_indices:
            spacy_token = doc[spacy_indices[0]]

            # Content words attend more to sentence boundaries
            if spacy_token.pos_ in ['NOUN', 'VERB', 'ADJ', 'ADV']:
                # Boost first token and newline attention
                attention[i, first_token_idx] *= 1.5
                for nl_idx in newline_indices:
                    attention[i, nl_idx] *= 1.3

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L4H23", attention



def prog_L4H24(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary and first-token tracking head with positional decay."""
    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L4H24", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Find sentence boundaries (periods and newlines)
    boundaries = []
    for i, token in enumerate(tokens):
        if token.strip() in ['.', '\n']:
            boundaries.append(i)

    # Always include position 0 as the primary anchor
    if 0 not in boundaries:
        boundaries.insert(0, 0)

    for i in range(n):
        token = tokens[i]

        # Self-attention for punctuation
        if token.strip() in ['.', '\n', ',']:
            attention[i, i] = 0.6
        else:
            attention[i, i] = 0.05

        # Find the most recent boundary before or at position i
        relevant_boundaries = [b for b in boundaries if b <= i]

        if relevant_boundaries:
            # Primary attention to first token (position 0)
            first_token_weight = max(0.1, 0.95 - i * 0.02)  # Decay with distance
            if 0 <= i:
                attention[i, 0] += first_token_weight

            # Secondary attention to most recent sentence boundary
            most_recent_boundary = max(relevant_boundaries)
            if most_recent_boundary != 0 and most_recent_boundary <= i:
                boundary_weight = max(0.1, 0.4 - (i - most_recent_boundary) * 0.01)
                attention[i, most_recent_boundary] += boundary_weight

            # Distributed attention to other boundaries
            for boundary in relevant_boundaries:
                if boundary != 0 and boundary != most_recent_boundary and boundary <= i:
                    distance = i - boundary
                    boundary_weight = max(0.05, 0.2 - distance * 0.005)
                    attention[i, boundary] += boundary_weight

        # Small attention to immediate previous token for flow
        if i > 0:
            attention[i, i-1] += 0.1

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L4H24", attention



def prog_L4H25(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Attention head focusing on sentence boundaries (newlines, periods) and sentence beginnings."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L4H25", np.zeros((n_empty, n_empty))

    attention_matrix = np.zeros((n, n))

    # Identify structural tokens
    newline_indices = [i for i, token in enumerate(tokens) if token.strip() == '\n']
    period_indices = [i for i, token in enumerate(tokens) if token.strip() == '.']
    structural_indices = set(newline_indices + period_indices)

    for i in range(n):
        current_token = tokens[i].strip()

        # Self-attention (especially strong for first token and structural markers)
        if i == 0 or i in structural_indices:
            attention_matrix[i, i] = 1.0
        else:
            attention_matrix[i, i] = 0.1

        # Strong attention to newlines and periods
        for j in structural_indices:
            if j <= i and j != i:
                # Distance decay for structural markers
                distance = i - j
                if current_token == '\n':
                    weight = 0.5 / (1 + 0.1 * distance)
                elif current_token == '.':
                    weight = 0.4 / (1 + 0.1 * distance)
                else:
                    weight = 0.6 / (1 + 0.2 * distance)
                attention_matrix[i, j] = weight

        # Moderate attention to first token (position 0)
        if i > 0:
            distance = i
            first_token_weight = 0.3 / (1 + 0.3 * distance)
            attention_matrix[i, 0] = first_token_weight

        # Weak local attention to immediate context
        for j in range(max(0, i-3), i):
            if j not in structural_indices and j != 0:
                local_distance = i - j
                local_weight = 0.05 / local_distance
                attention_matrix[i, j] = local_weight

    # Apply causal mask and normalize
    attention_matrix = apply_causal_mask(attention_matrix)
    attention_matrix = make_row_stochastic(attention_matrix)

    return "prog_L4H25", attention_matrix



def prog_L4H26(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Structural delimiter attention head focusing on newlines, periods, and first token."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L4H26", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    for i in range(n):
        # Base attention distribution
        base_scores = np.zeros(i + 1)

        # Very high attention to first token
        if i > 0:
            base_scores[0] = 3.0
        else:
            base_scores[0] = 5.0  # Self-attention for first token

        # Strong attention to newlines and periods
        for j in range(i + 1):
            token = tokens[j].strip()

            if token == '\n':
                base_scores[j] += 2.5
            elif token == '.':
                base_scores[j] += 1.8
            elif token in [',', '!', '?', ';']:
                base_scores[j] += 0.5

        # Positional bias - slight preference for recent tokens
        for j in range(i + 1):
            recency_bonus = 0.3 * (j / (i + 1)) if i > 0 else 0
            base_scores[j] += recency_bonus

        # Additional boost for self-attention
        base_scores[i] += 0.2

        # Convert to probabilities
        base_scores = np.exp(base_scores)
        base_scores = base_scores / base_scores.sum()

        attention[i, :i+1] = base_scores

    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L4H26", attention



def prog_L4H27(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Hierarchical sentence boundary attention with recency-weighted boundary selection."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention_matrix = np.zeros((n, n))

    # Parse with spacy for syntactic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    # Find all sentence boundary positions
    boundary_positions = []
    for j in range(n):
        if tokens[j] in ['\n', '.']:
            boundary_positions.append(j)

    for i in range(n):
        # Base attention distribution
        for j in range(i + 1):  # Causal mask
            # Strong attention to first token
            if j == 0:
                attention_matrix[i, j] = 0.8

            # Strong attention to sentence boundaries (\n and .)
            elif tokens[j] in ['\n', '.']:
                attention_matrix[i, j] = 0.4

            # Self-attention for boundary tokens
            elif i == j and tokens[i] in ['.', '\n']:
                attention_matrix[i, j] = 0.6

            # Moderate attention to previous token (recency)
            elif j == i - 1:
                attention_matrix[i, j] = 0.2

            # Syntactic dependencies - look for head-modifier relationships
            elif token_to_spacy[i] and token_to_spacy[j]:
                spacy_i = token_to_spacy[i][0] if token_to_spacy[i] else None
                spacy_j = token_to_spacy[j][0] if token_to_spacy[j] else None

                if spacy_i is not None and spacy_j is not None and spacy_i < len(doc) and spacy_j < len(doc):
                    # Check if j is syntactic head of i
                    if doc[spacy_j] == doc[spacy_i].head:
                        attention_matrix[i, j] = 0.3

                    # Check for modifier relationships
                    elif doc[spacy_i].dep_ in ['amod', 'advmod', 'prep'] and abs(spacy_i - spacy_j) <= 2:
                        attention_matrix[i, j] = 0.15

            # Semantic similarity boost for content words
            elif _char_sim(tokens[i], tokens[j]) > 0.5:
                attention_matrix[i, j] += 0.1

            # Base attention for all other positions
            else:
                attention_matrix[i, j] = 0.05

    # NEW: Hierarchical boundary attention - boost attention to recent boundaries
    for i in range(n):
        # Find the most recent boundary before position i
        recent_boundary = None
        for boundary_pos in reversed(boundary_positions):
            if boundary_pos < i:
                recent_boundary = boundary_pos
                break

        # If we found a recent boundary and it's not the first token, boost attention to it
        if recent_boundary is not None and recent_boundary > 0:
            # Strong boost to the most recent boundary
            attention_matrix[i, recent_boundary] += 0.3

            # Moderate boost to boundaries before the recent one
            for boundary_pos in boundary_positions:
                if boundary_pos < recent_boundary:
                    attention_matrix[i, boundary_pos] += 0.15

    # Apply causal mask and normalize
    attention_matrix = apply_causal_mask(attention_matrix)
    attention_matrix = make_row_stochastic(attention_matrix)

    return "prog_L4H27", attention_matrix



def prog_L4H28(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary and punctuation attention head with strong first-token focus."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    # Find important structural tokens
    period_indices = [i for i, token in enumerate(tokens) if token.strip() == '.']
    newline_indices = [i for i, token in enumerate(tokens) if token.strip() == '\n' or '\n' in token]
    first_token_indices = [0] if n > 0 else []

    # Get spacy alignment for linguistic features
    try:
        token_to_spacy = _align_to_spacy(sentence, tokens)
        doc = spacy_parse(sentence)
    except:
        token_to_spacy = [[] for _ in range(n)]
        doc = None

    for i in range(n):
        current_token = tokens[i].strip()

        # Self-attention baseline
        attention[i, i] = 0.1

        # Strong attention to periods
        for period_idx in period_indices:
            if period_idx <= i:
                attention[i, period_idx] = 0.4

        # Very strong attention to newlines (sentence boundaries)
        for newline_idx in newline_indices:
            if newline_idx <= i:
                attention[i, newline_idx] = 0.6

        # Special case: if current token is a period, very high self-attention
        if current_token == '.':
            attention[i, i] = 0.8

        # Special case: if current token is newline, high self-attention
        if current_token == '\n' or '\n' in current_token:
            attention[i, i] = 0.5

        # Much stronger attention to first token - this head has very high first-token attention
        if len(first_token_indices) > 0:
            # Base attention to first token
            attention[i, first_token_indices[0]] = 0.2

            # Additional boost for first token attention - key pattern from failure cases
            if i > 0:  # Don't boost self-attention for first token
                attention[i, first_token_indices[0]] += 0.6  # Much higher than original 0.2

        # Additional attention based on token position and type
        if doc and i < len(token_to_spacy) and token_to_spacy[i]:
            spacy_idx = token_to_spacy[i][0]
            if spacy_idx < len(doc):
                spacy_token = doc[spacy_idx]

                # Sentence-initial tokens get extra attention to boundaries
                if spacy_token.is_sent_start:
                    for newline_idx in newline_indices:
                        if newline_idx <= i:
                            attention[i, newline_idx] += 0.2

                # Verbs and nouns attend more to structural elements
                if spacy_token.pos_ in ['VERB', 'NOUN']:
                    for period_idx in period_indices:
                        if period_idx <= i:
                            attention[i, period_idx] += 0.1

        # Local attention to recent tokens
        for j in range(max(0, i-3), i):
            attention[i, j] += 0.05

        # Boost attention for tokens that are similar to periods/boundaries
        for j in range(i + 1):
            if tokens[j].strip() in [',', '!', '?', ';', ':']:
                attention[i, j] += 0.2

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L4H28", attention



def prog_L4H29(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Structural boundary attention head that focuses on newlines and sentence endings."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    attention_matrix = np.zeros((n, n))

    # Find structural markers: newlines and sentence-ending punctuation
    structural_indices = []
    for j in range(n):
        token = tokens[j].strip()
        if token == '\n' or token == '.' or token == '!' or token == '?':
            structural_indices.append(j)

    for i in range(n):
        # Strong attention to structural markers
        for j in structural_indices:
            if j <= i:  # causal constraint
                if tokens[j].strip() == '\n':
                    attention_matrix[i, j] = 0.5
                elif tokens[j].strip() in ['.', '!', '?']:
                    attention_matrix[i, j] = 0.4

        # Special case: very high attention from tokens immediately after punctuation to that punctuation
        if i > 0 and tokens[i-1].strip() in [',', '.', '!', '?']:
            attention_matrix[i, i-1] = 0.8

        # Moderate attention to first token
        if i > 0:
            attention_matrix[i, 0] = 0.15

        # Small self-attention
        attention_matrix[i, i] = 0.05

        # Distribute remaining attention uniformly to previous tokens
        remaining_weight = max(0.0, 1.0 - attention_matrix[i].sum())
        if i > 0:
            uniform_weight = remaining_weight / i
            for j in range(i):
                if attention_matrix[i, j] == 0:
                    attention_matrix[i, j] = uniform_weight

    attention_matrix = apply_causal_mask(attention_matrix)
    attention_matrix = make_row_stochastic(attention_matrix)

    return "prog_L4H29", attention_matrix



def prog_L4H3(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary and first-token attention head."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L4H3", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    for i in range(n):
        # Base attention to first token (very strong pattern)
        attention[i, 0] = 0.6

        # Strong attention to newlines and sentence boundaries
        for j in range(i + 1):
            token_j = tokens[j].strip()

            # High attention to newlines
            if token_j == '\n':
                attention[i, j] += 0.4

            # High attention to sentence-ending punctuation
            elif token_j in ['.', '!', '?']:
                attention[i, j] += 0.3

            # Moderate attention to commas and other punctuation
            elif token_j in [',', ';', ':']:
                attention[i, j] += 0.1

        # Self-attention (moderate)
        attention[i, i] += 0.2

        # Slight attention to immediate previous token
        if i > 0:
            attention[i, i-1] += 0.1

        # Decay attention for very distant tokens (except first token and boundaries)
        for j in range(i + 1):
            if j > 0 and tokens[j].strip() not in ['\n', '.', '!', '?', ',', ';', ':']:
                distance = i - j
                if distance > 10:
                    attention[i, j] *= 0.7

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L4H3", attention



def prog_L4H30(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Structural boundary attention head focusing on line breaks, sentence endings, and text beginnings."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L4H30", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Identify structural tokens
    newline_positions = []
    period_positions = []
    first_token_pos = 0

    for i, token in enumerate(tokens):
        if token.strip() == '\n':
            newline_positions.append(i)
        elif token.strip() == '.':
            period_positions.append(i)

    # For each query token
    for i in range(n):
        token = tokens[i]

        # Strong attention to newlines
        for nl_pos in newline_positions:
            if nl_pos <= i:  # causal constraint
                attention[i, nl_pos] = 0.4

        # Strong attention to periods (sentence endings)
        for period_pos in period_positions:
            if period_pos <= i:  # causal constraint
                attention[i, period_pos] = 0.35

        # High attention to first token
        attention[i, first_token_pos] = 0.3

        # Self-attention for structural tokens
        if token.strip() in ['\n', '.']:
            attention[i, i] = 0.5
        else:
            attention[i, i] = 0.02

        # Local attention to previous few tokens with decay
        for j in range(max(0, i-3), i):
            if attention[i, j] == 0:  # don't overwrite structural attention
                distance = i - j
                attention[i, j] = 0.1 / distance

        # Special boost for certain structural patterns
        if i > 0:
            prev_token = tokens[i-1]
            # Boost attention to token right after structural boundaries
            if prev_token.strip() in ['\n', '.', ',']:
                for k in range(i):
                    if tokens[k].strip() in ['\n', '.']:
                        attention[i, k] *= 1.2

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L4H30", attention



def prog_L4H31(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary and sequence start attention head - attends to first token and sentence-ending punctuation, with strong preference for paragraph boundaries."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L4H31", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Identify sentence-ending punctuation and first token
    sentence_ends = set()
    for i, token in enumerate(tokens):
        if token.strip() in ['.', '!', '?']:
            sentence_ends.add(i)

    # Identify newlines (paragraph boundaries)
    newlines = set()
    for i, token in enumerate(tokens):
        if token.startswith('\n'):
            newlines.add(i)

    first_token_idx = 0

    for i in range(n):
        # Strong attention to first token
        if i >= first_token_idx:
            attention[i, first_token_idx] = 0.6

        # Strong attention to sentence-ending punctuation
        for end_idx in sentence_ends:
            if i > end_idx:
                attention[i, end_idx] = 0.4

        # Self-attention
        attention[i, i] = 0.1

        # Local attention to previous few tokens
        for j in range(max(0, i-3), i):
            if j not in sentence_ends and j != first_token_idx:
                attention[i, j] = 0.05

        # Enhanced attention to newlines - much stronger when newlines are present
        for j in range(i+1):
            if j in newlines and j != first_token_idx:
                # If there are newlines in the sequence, they become the dominant structural anchor
                if len(newlines) > 0:
                    attention[i, j] = 0.5
                else:
                    attention[i, j] = 0.2

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L4H31", attention



def prog_L4H4(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary and structural position attention head."""
    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        token = tokens[i]

        # Strong attention to newlines and periods
        for j in range(i + 1):
            target_token = tokens[j]

            # Very high attention to newlines and periods
            if target_token.strip() in ['.', '\n']:
                attention[i, j] = 0.4

            # High attention to first token
            elif j == 0:
                attention[i, j] = 0.2

            # Moderate attention to previous token
            elif j == i - 1:
                attention[i, j] = 0.1

            # Self attention
            elif j == i:
                attention[i, j] = 0.05

            # Check for syntactic relationships using spacy
            else:
                if token_to_spacy[i] and token_to_spacy[j]:
                    spacy_i = token_to_spacy[i][0]
                    spacy_j = token_to_spacy[j][0]

                    if spacy_i < len(doc) and spacy_j < len(doc):
                        spacy_token_i = doc[spacy_i]
                        spacy_token_j = doc[spacy_j]

                        # Attention between syntactically related tokens
                        if spacy_token_j in spacy_token_i.ancestors or spacy_token_i.head == spacy_token_j:
                            attention[i, j] = 0.08
                        # Attention to tokens in same sentence
                        elif spacy_token_i.sent == spacy_token_j.sent:
                            attention[i, j] = 0.02
                        else:
                            attention[i, j] = 0.01
                else:
                    attention[i, j] = 0.01

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L4H4", attention



def prog_L4H5(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Document structure attention head - attends to sentence/paragraph boundary tokens."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    # Identify structural tokens (periods, newlines, etc.)
    structural_tokens = []
    for i, token in enumerate(tokens):
        if token.strip() in ['.', '\n', '!', '?', ';']:
            structural_tokens.append(i)

    for i in range(n):
        current_token = tokens[i].strip()

        # Perfect self-attention for structural tokens
        if current_token in ['.', '\n', '!', '?', ';']:
            attention[i, i] = 1.0
        else:
            # Find the most relevant structural token to attend to
            best_structural = None
            best_distance = float('inf')

            # Look for closest preceding structural token
            for struct_idx in structural_tokens:
                if struct_idx <= i:
                    distance = i - struct_idx
                    if distance < best_distance:
                        best_distance = distance
                        best_structural = struct_idx

            if best_structural is not None:
                # Strong attention to the structural token
                attention[i, best_structural] = 0.7

                # Some residual attention to self
                attention[i, i] = 0.1

                # Distribute remaining attention to nearby tokens
                remaining = 0.2
                nearby_count = 0
                for j in range(max(0, i-3), i):
                    if j != best_structural:
                        nearby_count += 1

                if nearby_count > 0:
                    nearby_weight = remaining / nearby_count
                    for j in range(max(0, i-3), i):
                        if j != best_structural:
                            attention[i, j] = nearby_weight
                else:
                    attention[i, i] += remaining
            else:
                # If no structural token found, attend to self
                attention[i, i] = 1.0

    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L4H5", attention



def prog_L4H6(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary attention head with strong beginning-of-sentence attention."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    # Find important structural tokens (periods, newlines)
    period_indices = []
    newline_indices = []

    for i, token in enumerate(tokens):
        if token.strip() == '.':
            period_indices.append(i)
        elif token.strip() == '\n' or token.strip() == '':
            newline_indices.append(i)

    # Check if first token is a content word using spacy
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)
    first_token_is_content = False
    if len(token_to_spacy) > 0 and len(token_to_spacy[0]) > 0:
        first_spacy_idx = token_to_spacy[0][0]
        if first_spacy_idx < len(doc):
            first_spacy_token = doc[first_spacy_idx]
            if first_spacy_token.pos_ in ['NOUN', 'VERB', 'ADJ', 'PROPN']:
                first_token_is_content = True

    for i in range(n):
        token_i = tokens[i].strip()

        # Self-attention baseline
        attention[i, i] = 0.05

        # High attention to periods and newlines
        for period_idx in period_indices:
            if period_idx <= i:
                # Very high attention to periods, especially the first ones
                base_weight = 0.4
                if period_idx < len(tokens) * 0.3:  # Early periods get more weight
                    base_weight = 0.6
                attention[i, period_idx] = base_weight

        for newline_idx in newline_indices:
            if newline_idx <= i:
                # High attention to newlines
                base_weight = 0.35
                if newline_idx < len(tokens) * 0.3:  # Early newlines get more weight
                    base_weight = 0.45
                attention[i, newline_idx] = base_weight

        # Special case: newlines and periods attending to themselves very highly
        if token_i == '.' or token_i == '\n' or token_i == '':
            attention[i, i] = 0.8

        # TARGETED FIX: Strong attention to first token if it's content word
        if i > 0 and first_token_is_content:
            # Strong attention to first token, especially for tokens further away
            distance_factor = min(i / len(tokens), 0.8)  # Cap the boost
            attention[i, 0] = max(attention[i, 0], 0.3 + 0.4 * distance_factor)

        # Add some recency bias for nearby tokens
        for j in range(max(0, i-3), i):
            if attention[i, j] < 0.1:  # Don't override high structural attention
                attention[i, j] += 0.02 * (1.0 / (i - j + 1))

        # Boost attention to first token if it's not already high (original logic)
        if i > 0 and attention[i, 0] < 0.1:
            attention[i, 0] = 0.05

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L4H6", attention



def prog_L4H7(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary and discourse structure attention head."""
    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    # Find sentence boundary tokens (periods, newlines)
    boundary_tokens = []
    for i, token in enumerate(tokens):
        if token.strip() in ['.', '\n']:
            boundary_tokens.append(i)

    for i in range(n):
        # Strong attention to sentence boundaries (periods and newlines)
        for boundary_idx in boundary_tokens:
            if boundary_idx <= i:  # Only attend to previous boundaries
                # Stronger attention to more recent boundaries
                distance = i - boundary_idx
                weight = max(0.3, 0.6 - distance * 0.02)
                attention[i, boundary_idx] = weight

        # Strong attention to first token
        if i > 0:
            attention[i, 0] = 0.35

        # Moderate self-attention
        attention[i, i] = 0.1

        # Weak attention to immediately preceding tokens
        for j in range(max(0, i-5), i):
            if attention[i, j] == 0:  # Don't override boundary attention
                attention[i, j] = max(0.02, 0.05 - (i-j) * 0.01)

    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L4H7", attention



def prog_L4H8(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary detection head: attends strongly to first token, newlines, and periods."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L4H8", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    for i in range(n):
        for j in range(i + 1):  # Causal mask
            weight = 0.0

            # Strong attention to newline characters
            if tokens[j] == '\n':
                weight += 0.4

            # Strong attention to periods
            elif tokens[j] == '.':
                weight += 0.35

            # Much stronger attention to first token - this was the key missing pattern
            elif j == 0:
                # Increase first token attention significantly, especially for later positions
                base_first_token_weight = 0.6
                # Add distance-based boost for later tokens attending to first token
                distance_boost = min(0.3, 0.01 * i)
                weight += base_first_token_weight + distance_boost

            # Reduced self-attention to compensate for stronger first token attention
            elif i == j:
                weight += 0.05

            # Small baseline attention for all positions
            else:
                weight += 0.02

            # Add distance decay for non-structural tokens (but not first token)
            if tokens[j] not in ['\n', '.'] and j != 0:
                distance = i - j
                decay = 1.0 / (1.0 + 0.1 * distance)
                weight *= decay

            attention[i, j] = weight

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L4H8", attention



def prog_L4H9(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary and early position attention head with enhanced early boundary focus."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention_matrix = np.zeros((n, n))

    # Identify boundary tokens (newlines and periods)
    boundary_indices = []
    for i, token in enumerate(tokens):
        if token.strip() in ['.', '\n'] or token == '\n':
            boundary_indices.append(i)

    # Find the first significant newline (usually around index 1-2)
    first_newline = None
    for boundary_idx in boundary_indices:
        if tokens[boundary_idx] == '\n' and boundary_idx <= 5:  # Early newline
            first_newline = boundary_idx
            break

    for i in range(n):
        # Base attention distribution
        base_attention = np.zeros(n)

        # Strong attention to boundary tokens
        for boundary_idx in boundary_indices:
            if boundary_idx <= i:  # Causal constraint
                # Stronger attention to more recent boundaries
                distance = i - boundary_idx
                base_attention[boundary_idx] = 0.4 * np.exp(-0.1 * distance)

        # Enhanced attention to first newline for most tokens
        if first_newline is not None and first_newline <= i and i > first_newline + 3:
            # Tokens beyond early position show much stronger attention to first newline
            base_attention[first_newline] += 0.3

        # Strong attention to first few tokens
        for j in range(min(3, i + 1)):
            base_attention[j] += 0.3 * np.exp(-0.2 * j)

        # Moderate attention to recent tokens
        for j in range(max(0, i - 5), i + 1):
            if j <= i:
                recency = i - j
                base_attention[j] += 0.1 * np.exp(-0.3 * recency)

        # Self-attention
        base_attention[i] += 0.1

        # Special boost for tokens that are periods or newlines themselves
        if tokens[i].strip() in ['.', '\n'] or tokens[i] == '\n':
            # These tokens attend more strongly to boundaries
            for boundary_idx in boundary_indices:
                if boundary_idx <= i:
                    base_attention[boundary_idx] *= 1.5

        attention_matrix[i] = base_attention

    attention_matrix = apply_causal_mask(attention_matrix)
    attention_matrix = make_row_stochastic(attention_matrix)

    return "prog_L4H9", attention_matrix



def prog_L5H0(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Boundary and beginning attention head: focuses on first token, newlines, and periods."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L5H0", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    for i in range(n):
        # First token gets maximum self-attention
        if i == 0:
            attention[i, i] = 1.0
            continue

        # For other tokens, distribute attention
        scores = np.zeros(i + 1)  # Can only attend to tokens up to position i

        # Strong attention to first token
        scores[0] = 0.4

        # Find newlines and periods in the available range
        for j in range(i + 1):
            if tokens[j].strip() == '\n':
                scores[j] = 0.6
            elif tokens[j].strip() == '.':
                scores[j] = 0.5

        # Add some self-attention
        scores[i] = 0.1

        # Add small attention to recent tokens
        for j in range(max(0, i-3), i):
            scores[j] += 0.1

        # Normalize scores
        if scores.sum() > 0:
            scores = scores / scores.sum()
        else:
            scores[i] = 1.0

        attention[i, :i+1] = scores

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L5H0", attention



def prog_L5H1(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary and first-token attention head with syntactic bias."""
    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L5H1", np.zeros((n_empty, n_empty))

    # Initialize attention matrix
    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        token = tokens[i].strip()

        # High attention to sentence boundaries (periods, newlines)
        for j in range(i + 1):
            target_token = tokens[j].strip()

            # Very high attention to periods and newlines
            if target_token in ['.', '\n']:
                attention[i, j] += 0.4

            # High attention to first token
            if j == 0:
                attention[i, j] += 0.25

            # Self-attention for certain punctuation
            if i == j and target_token in ['.', ',', '\n']:
                attention[i, j] += 0.3

        # Add syntactic and positional biases
        spacy_indices = token_to_spacy[i]
        if spacy_indices:
            spacy_token = doc[spacy_indices[0]]

            # Look for syntactic dependencies
            for j in range(i + 1):
                target_spacy_indices = token_to_spacy[j]
                if target_spacy_indices:
                    target_spacy = doc[target_spacy_indices[0]]

                    # Attention to syntactic head
                    if target_spacy == spacy_token.head and target_spacy != spacy_token:
                        attention[i, j] += 0.1

                    # Attention to dependents
                    if spacy_token == target_spacy.head and spacy_token != target_spacy:
                        attention[i, j] += 0.05

        # Local recency bias (previous few tokens)
        for j in range(max(0, i - 3), i):
            attention[i, j] += 0.05 * (1.0 / (i - j + 1))

        # Slight embedding similarity boost for content words
        for j in range(i + 1):
            if i != j:
                sim = _char_sim(tokens[i], tokens[j])
                if sim > 0.7:  # High similarity threshold
                    attention[i, j] += 0.03 * sim

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L5H1", attention



def prog_L5H10(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Attention to first token and newlines with some local syntactic structure."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L5H10", np.zeros((n_empty, n_empty)).reshape(0, 0)

    attention = np.zeros((n, n))

    # Parse for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        # Strong attention to first token (position 0)
        if i > 0:
            attention[i, 0] = 0.6

        # Very strong self-attention for first token
        if i == 0:
            attention[i, i] = 1.0
            continue

        # Strong attention to newlines
        for j in range(i + 1):
            if tokens[j].strip() == '' or '\n' in tokens[j]:
                attention[i, j] = 0.45

        # Moderate attention to punctuation (especially periods)
        for j in range(i + 1):
            token_text = tokens[j].strip()
            if token_text in ['.', '!', '?']:
                attention[i, j] = max(attention[i, j], 0.35)

        # Lower attention for local syntactic relationships
        spacy_indices = token_to_spacy[i]
        if spacy_indices:
            spacy_token = doc[spacy_indices[0]]

            # Attend to syntactic head
            if spacy_token.head != spacy_token:
                for j in range(i):
                    head_spacy_idx = spacy_token.head.i
                    j_spacy_indices = token_to_spacy[j]
                    if j_spacy_indices and head_spacy_idx in j_spacy_indices:
                        attention[i, j] = max(attention[i, j], 0.08)

            # Attend to previous token (recency)
            if i > 0:
                attention[i, i-1] = max(attention[i, j], 0.05)

        # Small self-attention baseline
        attention[i, i] = max(attention[i, i], 0.02)

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L5H10", attention



def prog_L5H11(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary attention head with strong first-token attention - tokens attend to periods, newlines, and heavily to the first content token."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L5H11", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Check if first token is a content word using spacy
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    first_token_is_content = False
    if len(token_to_spacy) > 0 and len(token_to_spacy[0]) > 0:
        first_spacy_idx = token_to_spacy[0][0]
        if first_spacy_idx < len(doc):
            first_spacy_token = doc[first_spacy_idx]
            first_token_is_content = first_spacy_token.pos_ in ['NOUN', 'VERB', 'ADJ', 'ADV', 'PROPN']

    for i in range(n):
        token_i = tokens[i].strip()

        # Find the most recent period or newline that token i can attend to
        most_recent_boundary = -1
        for j in range(i + 1):  # Can only attend to j <= i
            token_j = tokens[j].strip()
            if token_j in ['.', '\n']:
                most_recent_boundary = j

        # Base attention distribution
        for j in range(i + 1):  # Causal mask
            token_j = tokens[j].strip()

            # Very strong attention to periods and newlines
            if token_j in ['.', '\n']:
                if j == most_recent_boundary:
                    attention[i, j] = 0.4  # Strongest to most recent boundary
                else:
                    attention[i, j] = 0.2  # Still strong to other boundaries

            # Strong self-attention for punctuation
            elif i == j and token_i in [',', '.', '\n', '!', '?', ';', ':']:
                attention[i, j] = 0.6

            # Strong attention to first token if it's a content word
            elif j == 0 and first_token_is_content:
                attention[i, j] = 0.45

            # Moderate attention to first token (original behavior)
            elif j == 0:
                attention[i, j] = 0.15

            # Self-attention for regular tokens
            elif i == j:
                attention[i, j] = 0.05

            # Distance-based decay for other tokens
            else:
                distance = i - j
                if distance <= 5:
                    attention[i, j] = 0.02 / (distance + 1)
                else:
                    attention[i, j] = 0.005

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L5H11", attention



def prog_L5H12(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Structural and semantic attention head with strong beginning-of-sequence bias."""
    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention_matrix = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    # Identify sentence boundary tokens
    boundary_tokens = set()
    for i, token in enumerate(tokens):
        if token.strip() in ['.', '!', '?', '\n']:
            boundary_tokens.add(i)

    for i in range(n):
        # Strong self-attention for first token
        if i == 0:
            attention_matrix[i, i] = 1.0
            continue

        # Base attention distribution
        for j in range(i + 1):  # Causal mask
            # High attention to sentence boundaries
            if j in boundary_tokens:
                attention_matrix[i, j] = 0.3

            # ENHANCED: Much stronger attention to first token from all positions
            elif j == 0:
                # Strong bias toward first token, stronger for later positions
                base_first_token_attention = 0.6 + 0.2 * min(i / 10.0, 1.0)
                attention_matrix[i, j] = base_first_token_attention

            # Reduced self-attention for early tokens to compensate
            elif i == j and i < 5:
                attention_matrix[i, j] = 0.08

            # Normal self-attention for later tokens
            elif i == j:
                attention_matrix[i, j] = 0.15

            # Semantic similarity bonus
            else:
                sim = _char_sim(tokens[i], tokens[j])
                if sim > 0.7:  # High similarity threshold
                    attention_matrix[i, j] = 0.2
                elif sim > 0.4:  # Moderate similarity
                    attention_matrix[i, j] = 0.1
                else:
                    attention_matrix[i, j] = 0.05

        # Additional boost for tokens that are linguistically related
        if token_to_spacy[i]:
            spacy_i = token_to_spacy[i][0]
            spacy_token_i = doc[spacy_i]

            for j in range(i):
                if token_to_spacy[j]:
                    spacy_j = token_to_spacy[j][0]
                    spacy_token_j = doc[spacy_j]

                    # Boost attention between related parts of speech
                    if (spacy_token_i.pos_ in ['NOUN', 'VERB', 'ADJ'] and 
                        spacy_token_j.pos_ in ['NOUN', 'VERB', 'ADJ']):
                        attention_matrix[i, j] += 0.05

                    # Boost attention for dependency relations
                    if (spacy_token_i.head == spacy_token_j or 
                        spacy_token_j.head == spacy_token_i):
                        attention_matrix[i, j] += 0.1

        # Reduced recency bias to compensate for stronger first-token attention
        for j in range(max(0, i-5), i):
            if j != 0:  # Don't double-boost first token
                attention_matrix[i, j] += 0.01

    # Apply causal mask and normalize
    attention_matrix = apply_causal_mask(attention_matrix)
    attention_matrix = make_row_stochastic(attention_matrix)

    return "prog_L5H12", attention_matrix



def prog_L5H13(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary and first-token attention with positional bias."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L5H13", np.zeros((n_empty, n_empty))

    # Initialize attention matrix
    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    # Identify sentence boundaries (periods, newlines)
    sentence_boundaries = set()
    for i, token in enumerate(tokens):
        if token.strip() in ['.', '\n']:
            sentence_boundaries.add(i)

    for i in range(n):
        # Base attention distribution with recency bias
        for j in range(i + 1):
            # Recency bias - closer tokens get higher base attention
            distance = i - j
            if distance == 0:
                attention[i, j] = 0.05  # Self-attention baseline
            else:
                attention[i, j] = 0.02 * (0.8 ** distance)

        # Strong attention to first token
        if i > 0:
            attention[i, 0] += 0.15

        # Strong attention to sentence boundaries (periods and newlines)
        for boundary_idx in sentence_boundaries:
            if boundary_idx <= i:
                attention[i, boundary_idx] += 0.25

        # Boost attention to recent sentence boundaries
        recent_boundaries = [idx for idx in sentence_boundaries if idx <= i and (i - idx) <= 5]
        for boundary_idx in recent_boundaries:
            attention[i, boundary_idx] += 0.1

        # Syntactic relationships using spacy
        if i < len(token_to_spacy) and token_to_spacy[i]:
            spacy_idx = token_to_spacy[i][0]
            if spacy_idx < len(doc):
                current_token = doc[spacy_idx]

                # Attend to syntactic head
                if current_token.head != current_token:
                    head_spacy_idx = current_token.head.i
                    # Find corresponding LM token
                    for j in range(i):
                        if j < len(token_to_spacy) and token_to_spacy[j]:
                            if head_spacy_idx in token_to_spacy[j]:
                                attention[i, j] += 0.08
                                break

                # Modifiers attend to their heads
                for child in current_token.children:
                    if child.dep_ in ['amod', 'nmod', 'compound']:
                        child_spacy_idx = child.i
                        for j in range(i):
                            if j < len(token_to_spacy) and token_to_spacy[j]:
                                if child_spacy_idx in token_to_spacy[j]:
                                    attention[i, j] += 0.06
                                    break

        # Semantic similarity boost
        for j in range(i):
            sim = _char_sim(tokens[i], tokens[j])
            if sim > 0.7:  # High similarity threshold
                attention[i, j] += 0.1 * sim

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L5H13", attention



def prog_L5H14(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Structural attention head focusing on sentence boundaries, first tokens, and semantic coherence."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L5H14", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Get spacy alignment for linguistic features
    token_to_spacy = _align_to_spacy(sentence, tokens)
    doc = spacy_parse(sentence)

    for i in range(n):
        for j in range(i + 1):  # Causal mask
            weight = 0.0

            # Strong self-attention for punctuation
            if i == j and tokens[i] in ['.', ',', '!', '?', ':', ';']:
                weight += 0.6

            # Strong self-attention for first token and tokens after sentence boundaries
            if i == j and (i == 0 or (i > 0 and tokens[i-1] in ['.', '!', '?', '\n'])):
                weight += 0.8

            # High attention to newlines from most tokens
            if tokens[j] == '\n' and i != j:
                weight += 0.4

            # Attention to first token
            if j == 0 and i > 0:
                weight += 0.3

            # Attention to periods from various tokens
            if tokens[j] == '.' and i != j:
                weight += 0.3

            # Reduce attention from newlines to periods (over-predicted pattern)
            if tokens[i] == '\n' and tokens[j] == '.' and i != j:
                weight *= 0.5

            # Semantic similarity boost for related tokens (reduced strength)
            if i != j:
                sim = _char_sim(tokens[i], tokens[j])
                if sim > 0.7:
                    weight += 0.2 * sim  # Reduced from 0.4
                elif sim > 0.5:
                    weight += 0.1 * sim  # Reduced from 0.2

            # Slight recency bias for nearby tokens
            if i != j and i - j <= 3:
                weight += 0.1 * (1.0 - (i - j) / 4.0)

            # Special boost for function words attending to content words
            if token_to_spacy[i] and token_to_spacy[j]:
                i_spacy = token_to_spacy[i][0] if token_to_spacy[i] else None
                j_spacy = token_to_spacy[j][0] if token_to_spacy[j] else None

                if i_spacy is not None and j_spacy is not None and i_spacy < len(doc) and j_spacy < len(doc):
                    i_pos = doc[i_spacy].pos_
                    j_pos = doc[j_spacy].pos_

                    # Function words attending to content words
                    if i_pos in ['DET', 'PRON', 'ADP'] and j_pos in ['NOUN', 'VERB', 'ADJ']:
                        weight += 0.15

            attention[i, j] = weight

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L5H14", attention



def prog_L5H15(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Newline and sentence boundary attention head with strong beginning-of-sequence component."""
    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention_matrix = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        # High attention to newlines
        for j in range(i + 1):
            if tokens[j] == '\n':
                attention_matrix[i, j] = 0.6

        # High attention to sentence-ending periods
        for j in range(i + 1):
            if tokens[j] == '.':
                attention_matrix[i, j] = 0.4

        # Enhanced attention to first token - especially if it's punctuation
        if i > 0:
            if tokens[0] in ['.', ',', '!', '?', '"', "'", ':']:
                # Much stronger attention to punctuation at beginning
                attention_matrix[i, 0] = 0.5
            else:
                attention_matrix[i, 0] = 0.15

        # Self-attention baseline
        attention_matrix[i, i] = 0.05

        # Semantic similarity component
        for j in range(i):
            sim = _char_sim(tokens[i], tokens[j])
            if sim > 0.7:  # High similarity threshold
                attention_matrix[i, j] += 0.2
            elif sim > 0.5:  # Moderate similarity
                attention_matrix[i, j] += 0.1

        # Additional attention to commas and quotes
        for j in range(i + 1):
            if tokens[j] in [',', '"', "'", '!', '?']:
                attention_matrix[i, j] += 0.1

        # Slight positional decay for recent tokens
        for j in range(max(0, i - 5), i):
            distance = i - j
            attention_matrix[i, j] += 0.05 / distance

    attention_matrix = apply_causal_mask(attention_matrix)
    attention_matrix = make_row_stochastic(attention_matrix)

    return "prog_L5H15", attention_matrix



def prog_L5H16(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary attention head - attends to newlines, periods, and first token."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L5H16", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    for i in range(n):
        current_token = tokens[i].strip()

        # Special handling for newlines and periods - they attend strongly to first token
        if current_token in ['\n', '.']:
            attention[i, 0] = 0.8  # Strong attention to first token
            if i > 0:
                attention[i, i] = 0.15  # Some self-attention
                # Distribute remaining attention to other boundary tokens
                for j in range(i):
                    other_token = tokens[j].strip()
                    if other_token in ['\n', '.']:
                        attention[i, j] = 0.05 / max(1, sum(1 for k in range(i) if tokens[k].strip() in ['\n', '.']))
        else:
            # Regular tokens attend primarily to newlines and periods
            boundary_positions = []
            for j in range(i + 1):  # Only look backwards (causal)
                if tokens[j].strip() in ['\n', '.']:
                    boundary_positions.append(j)

            if boundary_positions:
                # Strong attention to boundary tokens, with recency bias
                total_boundary_weight = 0.7
                for idx, pos in enumerate(reversed(boundary_positions)):
                    weight = total_boundary_weight * (0.8 ** idx)  # Recency decay
                    attention[i, pos] = weight
                    total_boundary_weight -= weight
                    if total_boundary_weight <= 0:
                        break

                # Some attention to first token
                attention[i, 0] = 0.2

                # Small amount of attention to recent tokens
                remaining_weight = max(0, 0.1)
                if remaining_weight > 0 and i > 0:
                    attention[i, i-1] = remaining_weight * 0.5
                    attention[i, i] = remaining_weight * 0.5
            else:
                # No boundary tokens seen yet - attend mainly to first token and self
                attention[i, 0] = 0.7
                if i > 0:
                    attention[i, i] = 0.2
                    attention[i, i-1] = 0.1

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L5H16", attention



def prog_L5H17(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Structural boundary attention: tokens attend to sentence breaks, paragraph breaks, and document start."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L5H17", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Find structural boundary tokens
    boundary_positions = []
    for i, token in enumerate(tokens):
        if token.strip() in ['.', '\n'] or i == 0:  # periods, newlines, first token
            boundary_positions.append(i)

    # Also detect standalone newline tokens
    newline_positions = []
    for i, token in enumerate(tokens):
        if token == '\n':  # standalone newline token
            newline_positions.append(i)

    for i in range(n):
        if i == 0:
            # First token gets perfect self-attention
            attention[i, 0] = 1.0
        else:
            # Find the most relevant boundary positions for this token
            weights = {}

            # Self-attention baseline
            if tokens[i].strip() in ['.', '\n'] or tokens[i] == '\n':
                weights[i] = 0.6  # Strong self-attention for boundaries

            # Special case: strong attention to newlines for non-boundary tokens
            if tokens[i] not in ['\n'] and not tokens[i].strip() in ['.']:
                # Find most recent newline
                recent_newline = None
                for nl_pos in reversed(newline_positions):
                    if nl_pos < i:  # Causal constraint
                        recent_newline = nl_pos
                        break

                if recent_newline is not None:
                    # Strong attention to the most recent newline
                    weights[recent_newline] = weights.get(recent_newline, 0) + 0.7

            # Attend to boundaries
            for boundary_pos in boundary_positions:
                if boundary_pos <= i:  # Causal constraint
                    if boundary_pos == 0:
                        # First token gets moderate attention
                        weights[boundary_pos] = weights.get(boundary_pos, 0) + 0.3
                    elif tokens[boundary_pos].strip() == '\n' or tokens[boundary_pos] == '\n':
                        # Strong attention to newlines (already handled above for non-boundaries)
                        if tokens[i].strip() in ['.', '\n'] or tokens[i] == '\n':
                            weights[boundary_pos] = weights.get(boundary_pos, 0) + 0.5
                    elif tokens[boundary_pos].strip() == '.':
                        # Moderate attention to periods
                        weights[boundary_pos] = weights.get(boundary_pos, 0) + 0.4

            # Add small uniform attention to recent tokens
            for j in range(max(0, i-5), i):
                weights[j] = weights.get(j, 0) + 0.05

            # Normalize and assign
            if weights:
                total_weight = sum(weights.values())
                for pos, weight in weights.items():
                    attention[i, pos] = weight / total_weight
            else:
                # Fallback: attend to self
                attention[i, i] = 1.0

    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L5H17", attention



def prog_L5H18(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Structural boundary attention head focusing on sentence/paragraph breaks and first tokens."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    # Find structural tokens (newlines, periods, first token)
    structural_indices = []
    for i, token in enumerate(tokens):
        if token.strip() in ['\n', '.', '!', '?'] or i == 0:
            structural_indices.append(i)

    for i in range(n):
        token = tokens[i]

        # Self-attention for first token
        if i == 0:
            attention[i, i] = 1.0
            continue

        # Strong attention to structural markers
        for struct_idx in structural_indices:
            if struct_idx <= i:  # Causal constraint
                if tokens[struct_idx].strip() == '\n':
                    attention[i, struct_idx] = 0.4
                elif tokens[struct_idx].strip() in ['.', '!', '?']:
                    attention[i, struct_idx] = 0.35
                elif struct_idx == 0:  # First token
                    attention[i, struct_idx] = 0.15

        # Self-attention for structural tokens
        if token.strip() in ['\n', '.', '!', '?']:
            attention[i, i] = 0.6

        # Moderate attention to previous token
        if i > 0:
            attention[i, i-1] = 0.1

        # Small attention to nearby tokens
        for j in range(max(0, i-3), i):
            if attention[i, j] == 0:  # Don't overwrite structural attention
                attention[i, j] = 0.05

    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L5H18", attention



def prog_L5H19(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Attention head that combines first-token, delimiter, and self-attention patterns."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L5H19", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    for i in range(n):
        for j in range(i + 1):  # Causal mask: j <= i
            weight = 0.0

            # Strong self-attention for first token
            if i == 0 and j == 0:
                weight = 1.0

            # Strong attention to first token from other positions
            elif j == 0 and i > 0:
                weight = 0.3

            # High attention to delimiters (periods, newlines)
            elif tokens[j].strip() in ['.', '\n']:
                if i != j:  # Not self-attention to delimiters
                    weight = 0.4
                else:  # Self-attention to delimiters
                    weight = 0.6

            # Self-attention for current token
            elif i == j:
                weight = 0.1

            # Moderate attention to recent tokens
            elif i - j <= 3:
                weight = 0.15

            # Lower baseline attention to other valid positions
            else:
                weight = 0.05

            attention[i, j] = weight

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L5H19", attention



def prog_L5H2(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Structural boundary attention: focuses on newlines, periods, and first token as document structure anchors."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L5H2", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    for i in range(n):
        # Find structural anchor tokens: newlines, periods, and first token
        newline_positions = [j for j in range(i + 1) if tokens[j].strip() == '']
        period_positions = [j for j in range(i + 1) if tokens[j].strip() == '.']

        # Strong attention to newlines (primary structural anchor)
        for j in newline_positions:
            attention[i, j] = 0.4

        # Strong attention to periods (secondary structural anchor)
        for j in period_positions:
            attention[i, j] = 0.3

        # Moderate attention to first token
        attention[i, 0] = 0.15

        # Self-attention
        attention[i, i] = 0.1

        # Small baseline attention to all previous tokens
        for j in range(i):
            if attention[i, j] == 0:  # Don't overwrite existing weights
                attention[i, j] = 0.02

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L5H2", attention



def prog_L5H21(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Structural boundary attention head focusing on newlines, periods, sequence boundaries, and strong first-token attention."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L5H21", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    for i in range(n):
        for j in range(i + 1):  # Causal mask
            token_i = tokens[i]
            token_j = tokens[j]

            weight = 0.0

            # Strong attention to newlines
            if token_j == '\n':
                weight += 0.4

            # Moderate attention to periods
            elif token_j == '.':
                weight += 0.35

            # Self-attention for first token
            elif i == j == 0:
                weight += 0.95

            # Attention from second token to first token (common pattern)
            elif i == 1 and j == 0:
                weight += 0.9

            # Strong attention to first token from distant positions
            elif j == 0 and i >= 10:
                weight += 0.85

            # Some attention to first token from other positions
            elif j == 0:
                weight += 0.15

            # Self-attention for punctuation
            elif i == j and token_i in ['.', ',', '"', "'", '?', '!']:
                weight += 0.3

            # Small baseline attention
            else:
                weight += 0.05

            attention[i, j] = weight

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L5H21", attention



def prog_L5H22(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary and structural punctuation attention head with punctuation-to-structure attention."""
    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L5H22", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    for i in range(n):
        token_i = tokens[i]

        # Very strong self-attention for punctuation
        if token_i in ['.', '!', '?', ',', ';', ':']:
            attention[i, i] = 1.0

        # Strong attention to newlines and periods
        for j in range(i + 1):
            token_j = tokens[j]

            if token_j == '\n':
                # High attention to newlines from most tokens
                if not (token_i in ['.', '!', '?', ',', ';', ':']):
                    attention[i, j] = 0.4
            elif token_j in ['.', '!', '?']:
                # High attention to sentence-ending punctuation
                if not (token_i in ['.', '!', '?', ',', ';', ':']):
                    attention[i, j] = 0.35

        # Add some attention to first token (discourse anchor)
        if i > 0 and not (token_i in ['.', '!', '?', ',', ';', ':']):
            attention[i, 0] = 0.15

        # Small amount of local attention
        if i > 0 and not (token_i in ['.', '!', '?', ',', ';', ':']):
            attention[i, i-1] = 0.08
            if i > 1:
                attention[i, i-2] = 0.05

    # Special case: punctuation tokens attend to previous structural elements
    for i in range(n):
        token_i = tokens[i]

        if token_i in ['.', '!', '?', ',', ';', ':']:
            # Reduce self-attention for punctuation
            attention[i, i] = 0.3

            # Add strong attention to previous sentence boundaries and structure
            for j in range(i):
                token_j = tokens[j]

                if token_j == '\n':
                    attention[i, j] = 0.4
                elif token_j in ['.', '!', '?']:
                    attention[i, j] = 0.35
                elif j == 0:  # First token
                    attention[i, j] = 0.15

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L5H22", attention



def prog_L5H23(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary attention head that focuses on newlines and periods, especially early ones."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention_matrix = np.zeros((n, n))

    # Find sentence boundary tokens (newlines and periods)
    boundary_tokens = []
    for i, token in enumerate(tokens):
        if token.strip() in ['\n', '.']:
            boundary_tokens.append(i)

    for i in range(n):
        # Strong attention to sentence boundaries, with preference for earlier ones
        for boundary_idx in boundary_tokens:
            if boundary_idx <= i:  # Causal constraint
                # Higher weight for earlier boundaries and newlines
                if tokens[boundary_idx].strip() == '\n':
                    weight = 0.6 / (1 + 0.1 * boundary_idx)  # Decay with position
                else:  # period
                    weight = 0.4 / (1 + 0.1 * boundary_idx)
                attention_matrix[i, boundary_idx] = weight

        # Self-attention component
        attention_matrix[i, i] = 0.1

        # Moderate attention to adjacent tokens
        if i > 0:
            attention_matrix[i, i-1] = 0.05
        if i > 1:
            attention_matrix[i, i-2] = 0.02

        # Small attention to first token if it's not a boundary
        if tokens[0].strip() not in ['\n', '.'] and i > 0:
            attention_matrix[i, 0] = 0.08

    # Apply causal mask and normalize
    attention_matrix = apply_causal_mask(attention_matrix)
    attention_matrix = make_row_stochastic(attention_matrix)

    return "prog_L5H23", attention_matrix



def prog_L5H24(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary attention head - attends strongly to first token when no nearby boundaries."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention_matrix = np.zeros((n, n))

    # Find boundary tokens (newlines, periods, and other punctuation)
    boundary_indices = []
    for i, token in enumerate(tokens):
        if token.strip() in ['\n', '.', '!', '?', ':', ';']:
            boundary_indices.append(i)

    for i in range(n):
        token = tokens[i].strip()

        # Strong self-attention for first token
        if i == 0:
            attention_matrix[i, i] = 1.0
            continue

        # High attention to boundary tokens (newlines and periods)
        for boundary_idx in boundary_indices:
            if boundary_idx <= i:  # Causal constraint
                if token == '\n':
                    attention_matrix[i, boundary_idx] = 0.4
                elif token == '.':
                    attention_matrix[i, boundary_idx] = 0.6
                else:
                    attention_matrix[i, boundary_idx] = 0.35

        # Special handling for boundary tokens themselves
        if token in ['\n', '.']:
            # Self-attention for boundary tokens
            attention_matrix[i, i] = 0.6
            # Attention to previous boundaries
            for prev_boundary in boundary_indices:
                if prev_boundary < i:
                    attention_matrix[i, prev_boundary] = 0.3

        # Enhanced first token attention when no nearby boundaries or low total attention
        if len(boundary_indices) == 0 or attention_matrix[i].sum() < 0.1:
            # Check for nearby boundaries (within 10 positions)
            nearby_boundaries = [b for b in boundary_indices if b <= i and i - b <= 10]
            if not nearby_boundaries:
                # No nearby boundaries - attend very strongly to first token
                attention_matrix[i, 0] = 0.9
                if i > 0:
                    attention_matrix[i, i-1] = 0.05  # Minimal previous token
                    attention_matrix[i, i] = 0.05    # Minimal self-attention
            else:
                attention_matrix[i, 0] = 0.5
                if i > 0:
                    attention_matrix[i, i-1] = 0.3  # Previous token fallback
                    attention_matrix[i, i] = 0.2    # Self-attention fallback

    # Apply causal mask and normalize
    attention_matrix = apply_causal_mask(attention_matrix)
    attention_matrix = make_row_stochastic(attention_matrix)

    return "prog_L5H24", attention_matrix



def prog_L5H25(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Attention head that focuses on structural boundaries (newlines and periods) with distance-based weighting."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L5H25", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Find structural boundary tokens (newlines and periods)
    boundary_indices = []
    first_token_idx = 0

    for i, token in enumerate(tokens):
        if token.strip() in ['\n', '.']:
            boundary_indices.append(i)

    for i in range(n):
        # Reduced base attention to self (was causing over-prediction)
        attention[i, i] = 0.05

        # Strong attention to first token
        attention[i, first_token_idx] = 0.3

        # Primary attention to boundary tokens (newlines and periods)
        for boundary_idx in boundary_indices:
            if boundary_idx <= i:  # Causal constraint
                # Distance-based weighting - closer boundaries get more attention
                distance = i - boundary_idx + 1
                weight = 1.0 / distance

                # Newlines get slightly higher base weight than periods
                if tokens[boundary_idx].strip() == '\n':
                    attention[i, boundary_idx] = weight * 1.2
                elif tokens[boundary_idx].strip() == '.':
                    attention[i, boundary_idx] = weight * 1.0

        # Additional attention based on distance from boundaries
        # Tokens further from boundaries attend more strongly to them
        if boundary_indices:
            # Find distance to nearest preceding boundary
            preceding_boundaries = [idx for idx in boundary_indices if idx <= i]
            if preceding_boundaries:
                nearest_boundary = max(preceding_boundaries)
                distance_from_boundary = i - nearest_boundary

                # Boost attention to boundaries based on distance
                for boundary_idx in preceding_boundaries:
                    if distance_from_boundary > 0:
                        boost = min(distance_from_boundary * 0.1, 0.5)
                        attention[i, boundary_idx] += boost

        # Special case: Strong attention to most recent newline for tokens that come after periods
        # This handles the under-prediction pattern where tokens attend to newlines
        if boundary_indices:
            preceding_newlines = [idx for idx in boundary_indices if idx <= i and tokens[idx].strip() == '\n']
            if preceding_newlines:
                most_recent_newline = max(preceding_newlines)
                # Check if there's a period between this token and the most recent newline
                periods_between = [idx for idx in boundary_indices 
                                 if most_recent_newline < idx < i and tokens[idx].strip() == '.']
                if periods_between:
                    # Strong attention to the most recent newline
                    attention[i, most_recent_newline] += 0.4

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L5H25", attention



def prog_L5H26(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary attention head with strong preference for early sentence delimiters."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        return "prog_L5H26", np.zeros((0, 0))

    attention = np.zeros((n, n))

    # Find sentence boundary tokens (periods and line breaks)
    boundary_indices = []
    for j, token in enumerate(tokens):
        if token.strip() in ['.', '\n']:
            boundary_indices.append(j)

    # Find early positional boundaries (first few tokens that are boundaries or start of content)
    early_reference_indices = []
    for j in range(min(3, n)):  # Look at first 3 positions
        token = tokens[j].strip()
        if token in ['.', '\n'] or j == 0:  # First token or early boundaries
            early_reference_indices.append(j)

    for i in range(n):
        # Extra strong attention to early reference points
        for early_idx in early_reference_indices:
            if early_idx <= i:  # Causal constraint
                # Much stronger attention to early reference tokens
                distance = i - early_idx
                if distance == 0:
                    attention[i, early_idx] = 0.6  # Strong self-attention to early references
                else:
                    # Slower decay for early references
                    attention[i, early_idx] = 0.5 * np.exp(-distance * 0.05)

        # Standard attention to other sentence boundaries
        for boundary_idx in boundary_indices:
            if boundary_idx <= i and boundary_idx not in early_reference_indices:  # Causal constraint, not already handled
                # Distance decay from boundary
                distance = i - boundary_idx
                if distance == 0:
                    attention[i, boundary_idx] = 0.4  # Self-attention to boundary
                else:
                    # Exponential decay based on distance
                    attention[i, boundary_idx] = 0.3 * np.exp(-distance * 0.1)

        # Reduced self-attention for non-early tokens
        if i not in early_reference_indices:
            attention[i, i] += 0.1

        # Local attention to previous few tokens
        for j in range(max(0, i-3), i):
            if j not in boundary_indices and j not in early_reference_indices:
                distance = i - j
                attention[i, j] += 0.08 * np.exp(-distance * 0.5)

        # Small uniform attention to other tokens
        for j in range(i + 1):
            if attention[i, j] == 0:
                attention[i, j] = 0.01

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L5H26", attention



def prog_L5H27(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary and document structure attention head with newline focus."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L5H27", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    for i in range(n):
        # Self-attention baseline
        attention[i, i] = 0.1

        # Strong attention to sentence boundaries (periods and newlines)
        for j in range(i):
            if tokens[j].strip() in ['.', '\n']:
                # Much stronger attention to newlines than periods
                if tokens[j].strip() == '\n':
                    attention[i, j] = 0.9  # Very high for newlines
                else:  # period
                    attention[i, j] = 0.4  # Reduced from 0.8

        # Strong attention to first token
        if i > 0:
            attention[i, 0] = 0.6

        # Moderate attention to recent tokens
        for j in range(max(0, i-5), i):
            if tokens[j].strip() not in ['.', '\n'] and j != 0:
                attention[i, j] = 0.05

        # Slight attention to tokens with high embedding similarity
        for j in range(i):
            if j != 0 and tokens[j].strip() not in ['.', '\n']:
                sim = _char_sim(tokens[i], tokens[j])
                if sim > 0.5:
                    attention[i, j] += 0.02 * sim

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L5H27", attention



def prog_L5H28(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Structural attention head focusing on first token and sentence boundaries."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L5H28", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    for i in range(n):
        # Very strong attention to first token
        attention[i, 0] = 10.0

        # Strong attention to sentence boundary markers
        for j in range(i + 1):
            token = tokens[j].strip()
            if token in ['.', '\n', '!', '?']:
                attention[i, j] += 5.0

        # Moderate self-attention
        attention[i, i] += 2.0

        # Weak attention to immediate context
        if i > 0:
            attention[i, i-1] += 0.5
        if i > 1:
            attention[i, i-2] += 0.3

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L5H28", attention



def prog_L5H29(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Structural token attention head - focuses on sentence beginnings, newlines and periods as discourse markers."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    # Find structural tokens (newlines and periods)
    structural_tokens = []
    for i, token in enumerate(tokens):
        if token.strip() in ['\n', '.']:
            structural_tokens.append(i)

    for i in range(n):
        # Base attention distribution
        weights = np.zeros(n)

        # Strong attention to sentence beginning (first token)
        if i > 0:  # Don't self-attend to first token with this mechanism
            weights[0] = 0.6

        # Strong attention to structural tokens (newlines and periods)
        for struct_idx in structural_tokens:
            if struct_idx <= i:  # Causal constraint
                # Higher weight for newlines, moderate for periods
                if tokens[struct_idx].strip() == '\n':
                    weights[struct_idx] = 0.4
                elif tokens[struct_idx].strip() == '.':
                    weights[struct_idx] = 0.3

        # Self-attention component
        weights[i] = 0.1

        # Local syntactic attention using spacy
        doc = spacy_parse(sentence)
        token_to_spacy = _align_to_spacy(sentence, tokens)

        if token_to_spacy[i]:  # If current token aligns to spacy tokens
            spacy_idx = token_to_spacy[i][0]
            if spacy_idx < len(doc):
                spacy_token = doc[spacy_idx]

                # Attend to syntactic head
                if spacy_token.head != spacy_token:
                    head_spacy_idx = spacy_token.head.i
                    spacy_to_token = align_spacy_to_tokens(sentence)
                    if head_spacy_idx < len(spacy_to_token) and spacy_to_token[head_spacy_idx]:
                        head_token_idx = spacy_to_token[head_spacy_idx][0]
                        if head_token_idx <= i:
                            weights[head_token_idx] += 0.05

                # Attend to immediate previous token for function words
                if spacy_token.pos_ in ['DET', 'ADP', 'CONJ', 'PRON'] and i > 0:
                    weights[i-1] += 0.03

        # Proximity decay for nearby tokens
        for j in range(max(0, i-5), i):
            if weights[j] == 0:  # Don't override structural attention
                weights[j] = 0.01 * (1.0 / (i - j + 1))

        # Normalize and apply to attention matrix
        if weights.sum() > 0:
            attention[i] = weights

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L5H29", attention



def prog_L5H3(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """First-token and sentence boundary attention head that tracks document structure."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L5H3", np.zeros((n_empty, n_empty))

    # Initialize attention matrix
    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    # Identify sentence boundaries (periods, newlines)
    sentence_boundaries = set()
    for i, token in enumerate(tokens):
        token_stripped = token.strip()
        if token_stripped in ['.', '!', '?'] or token_stripped == '\n':
            sentence_boundaries.add(i)

    for i in range(n):
        # Very strong attention to first token (position 0)
        if i > 0:
            attention[i, 0] = 0.7

        # Strong self-attention
        attention[i, i] = 0.3

        # Strong attention to sentence boundaries
        for boundary_pos in sentence_boundaries:
            if boundary_pos <= i:  # causal constraint
                # Distance decay for sentence boundaries
                distance = i - boundary_pos
                boundary_weight = 0.4 * (0.8 ** distance)
                attention[i, boundary_pos] += boundary_weight

        # Moderate attention to recent tokens with recency bias
        for j in range(max(0, i-5), i):
            if j not in sentence_boundaries and j != 0:  # avoid double-counting
                recency_weight = 0.1 * (0.7 ** (i - j - 1))
                attention[i, j] += recency_weight

        # Light syntactic attention
        if token_to_spacy[i]:
            spacy_idx = token_to_spacy[i][0]
            if spacy_idx < len(doc):
                spacy_token = doc[spacy_idx]

                # Attention to syntactic head
                if spacy_token.head != spacy_token:
                    head_spacy_idx = spacy_token.head.i
                    # Find corresponding LM token
                    for k in range(i):
                        if token_to_spacy[k] and head_spacy_idx in token_to_spacy[k]:
                            attention[i, k] += 0.05
                            break

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L5H3", attention



def prog_L5H30(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Attention to structural boundaries: first token, newlines, and periods with context-aware adjustments."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    for i in range(n):
        # Very strong attention to first token
        attention[i, 0] = 0.8

        # Strong attention to newlines and periods
        for j in range(i + 1):
            if tokens[j] == '\n':
                attention[i, j] += 0.4
            elif tokens[j] == '.':
                attention[i, j] += 0.35

        # Self-attention for punctuation
        if tokens[i] in ['.', '\n', ',']:
            attention[i, i] += 0.3

        # Small baseline attention to previous tokens with recency bias
        for j in range(i):
            if tokens[j] not in ['\n', '.']:
                recency_weight = 0.02 * (1.0 / (i - j + 1))
                attention[i, j] += recency_weight

        # Special handling for tokens after structural boundaries
        # Find the most recent newline or period before token i
        last_boundary = -1
        for j in range(i):
            if tokens[j] in ['\n', '.']:
                last_boundary = j

        # If token i comes after a structural boundary, adjust attention
        if last_boundary >= 0 and i > last_boundary:
            # Reduce first-token attention
            attention[i, 0] *= 0.6

            # Boost attention to the structural boundary
            attention[i, last_boundary] += 0.25

            # Also boost attention to other structural boundaries
            for j in range(last_boundary + 1):
                if tokens[j] in ['\n', '.'] and j != last_boundary:
                    attention[i, j] += 0.15

    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L5H30", attention



def prog_L5H31(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary detection head with strong first-token attention for early positions."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L5H31", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Identify structural tokens (periods, newlines, first token)
    structural_indices = set()

    for i, token in enumerate(tokens):
        # Add periods and newlines as structural markers
        if token.strip() in ['.', '\n']:
            structural_indices.add(i)

    # Add first token as structural
    if n > 0:
        structural_indices.add(0)

    for i in range(n):
        current_token = tokens[i].strip()

        # Base attention distribution
        for j in range(i + 1):  # Causal mask
            if j in structural_indices:
                # Strong attention to structural tokens
                if current_token in ['.', '\n']:
                    # Structural tokens attend strongly to themselves and other structural tokens
                    attention[i, j] = 0.8
                else:
                    # Regular tokens attend moderately to structural tokens
                    attention[i, j] = 0.5
            else:
                # Weak attention to non-structural tokens
                attention[i, j] = 0.1

        # Special case: very strong first-token attention for early positions
        if i <= 5 and i > 0:  # First few tokens (excluding first token itself)
            attention[i, 0] = 0.98

        # Self-attention boost
        attention[i, i] += 0.3

        # Special case: very strong attention from first token to itself
        if i == 0:
            attention[i, i] = 1.0

        # Boost attention to nearby newlines
        for j in range(max(0, i-10), i):
            if tokens[j].strip() == '\n':
                attention[i, j] *= 1.5

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L5H31", attention



def prog_L5H4(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Attention head that focuses on structural boundaries (newlines and periods) with strong first-token attention."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L5H4", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Find structural tokens (newlines and periods)
    structural_tokens = []
    for j in range(n):
        token = tokens[j].strip()
        if token == '\n' or token == '.':
            structural_tokens.append(j)

    for i in range(n):
        # Base attention to all previous tokens (small uniform)
        for j in range(i + 1):
            attention[i, j] = 0.01

        # Strong attention to structural tokens
        for j in structural_tokens:
            if j <= i:
                # Distance decay for structural tokens
                distance = i - j
                if distance == 0:
                    attention[i, j] += 0.6  # Very high self-attention for structural tokens
                else:
                    attention[i, j] += 0.4 * (0.8 ** (distance / 10))  # Decay with distance

        # Moderate self-attention for non-structural tokens
        if i not in structural_tokens:
            attention[i, i] += 0.3

        # Strong attention to first token from all positions
        if i > 0:
            attention[i, 0] += 0.5  # Much stronger than original 0.15

        # Small boost for recent tokens (recency bias)
        for j in range(max(0, i-3), i):
            attention[i, j] += 0.05

    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L5H4", attention



def prog_L5H5(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary and first-token attention head with structural focus."""
    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        # Strong attention to first token
        if n > 0:
            attention[i, 0] = 0.6

        # High attention to sentence boundaries (periods, newlines)
        for j in range(i + 1):
            token_text = tokens[j].strip()
            if token_text in ['.', '\n', '!', '?']:
                attention[i, j] += 0.4

        # Self-attention baseline
        attention[i, i] += 0.1

        # Attention to tokens at sentence starts (after periods/newlines)
        for j in range(i + 1):
            if j > 0:
                prev_token = tokens[j-1].strip()
                if prev_token in ['.', '\n', '!', '?']:
                    attention[i, j] += 0.3

        # Some recency bias for recent tokens
        for j in range(max(0, i-3), i):
            attention[i, j] += 0.1 * (1.0 - (i - j) * 0.2)

        # Slight attention to function words and common tokens
        for j in range(i + 1):
            if token_to_spacy[j]:
                spacy_idx = token_to_spacy[j][0]
                if spacy_idx < len(doc):
                    spacy_token = doc[spacy_idx]
                    if spacy_token.pos_ in ['DET', 'PRON', 'ADP', 'CONJ', 'CCONJ']:
                        attention[i, j] += 0.15

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L5H5", attention



def prog_L5H6(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary and first-token attention head."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    # Find sentence boundaries (periods and newlines)
    boundary_tokens = []
    for i, token in enumerate(tokens):
        if token.strip() in ['.', '\n']:
            boundary_tokens.append(i)

    # Find first token (usually index 0)
    first_token = 0

    for i in range(n):
        token = tokens[i]

        # High attention to sentence boundaries
        for boundary_idx in boundary_tokens:
            if boundary_idx <= i:  # Causal constraint
                attention[i, boundary_idx] = 0.4

        # High attention to first token
        if first_token <= i:
            attention[i, first_token] = 0.4

        # Moderate self-attention
        attention[i, i] = 0.1

        # Small attention to adjacent previous tokens
        if i > 0:
            attention[i, i-1] = 0.05
        if i > 1:
            attention[i, i-2] = 0.02

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L5H6", attention



def prog_L5H7(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Punctuation attractor head: tokens attend strongly to nearby periods and newlines."""
    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    for i in range(n):
        current_token = tokens[i].strip()

        # Find punctuation attractors (periods and newlines)
        period_indices = [j for j in range(i + 1) if tokens[j].strip() == '.']
        newline_indices = [j for j in range(i + 1) if tokens[j].strip() == '\n']

        if current_token == '.':
            # Periods have high self-attention
            attention[i, i] = 0.6
            # And some attention to first token
            attention[i, 0] = 0.4
        elif current_token == '\n':
            # Newlines have high self-attention
            attention[i, i] = 0.6
            # And some attention to first token
            attention[i, 0] = 0.4
        elif current_token in ['"', "'", ',', '!', '?']:
            # Other punctuation has moderate self-attention and attends to attractors
            attention[i, i] = 0.3
            if newline_indices:
                closest_newline = max(newline_indices)
                attention[i, closest_newline] = 0.4
            elif period_indices:
                closest_period = max(period_indices)
                attention[i, closest_period] = 0.4
            else:
                attention[i, 0] = 0.4
            # Some attention to first token
            attention[i, 0] += 0.3
        else:
            # Regular tokens attend strongly to punctuation attractors
            if newline_indices:
                # Prefer most recent newline
                closest_newline = max(newline_indices)
                attention[i, closest_newline] = 0.7

                # Some attention to periods too
                if period_indices:
                    closest_period = max(period_indices)
                    attention[i, closest_period] = 0.2

                # Small amount to first token
                attention[i, 0] = 0.1
            elif period_indices:
                # If no newline, attend to most recent period
                closest_period = max(period_indices)
                attention[i, closest_period] = 0.8

                # Some to first token
                attention[i, 0] = 0.2
            else:
                # No punctuation attractors found, attend to first token and self
                if i == 0:
                    attention[i, i] = 1.0
                else:
                    attention[i, 0] = 0.8
                    attention[i, i] = 0.2

    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)
    return "prog_L5H7", attention



def prog_L5H8(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary attention head that focuses on periods and newlines as sentence delimiters."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L5H8", np.zeros((n_empty, n_empty))

    attention_matrix = np.zeros((n, n))

    # Find sentence boundary tokens (periods and newlines)
    boundary_indices = []
    for i, token in enumerate(tokens):
        if token.strip() in ['.', '\n']:
            boundary_indices.append(i)

    # Find first token index (skip whitespace)
    first_token_idx = 0
    for i, token in enumerate(tokens):
        if token.strip():
            first_token_idx = i
            break

    for i in range(n):
        # Base attention to self
        attention_matrix[i, i] = 0.1

        # Strong attention to sentence boundaries (periods and newlines)
        for boundary_idx in boundary_indices:
            if boundary_idx <= i:  # Respect causal mask
                # Higher weight for closer boundaries
                distance = i - boundary_idx
                if distance == 0:
                    weight = 0.4
                else:
                    weight = 0.3 / (1 + distance * 0.1)
                attention_matrix[i, boundary_idx] += weight

        # Moderate attention to first token
        if first_token_idx <= i:
            distance = i - first_token_idx
            weight = 0.2 / (1 + distance * 0.05)
            attention_matrix[i, first_token_idx] += weight

        # Small attention to previous token (recency bias)
        if i > 0:
            attention_matrix[i, i-1] += 0.1

    # Apply causal mask and normalize
    attention_matrix = apply_causal_mask(attention_matrix)
    attention_matrix = make_row_stochastic(attention_matrix)

    return "prog_L5H8", attention_matrix



def prog_L5H9(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary attention head - attends strongly to newlines, periods, and structural markers."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        return "prog_L5H9", np.zeros((0, 0))

    attention = np.zeros((n, n))

    # Find structural boundary tokens (newlines, periods, exclamation marks)
    boundary_tokens = []
    for i, token in enumerate(tokens):
        if token.strip() in ['\n', '.', '!', '?']:
            boundary_tokens.append(i)

    for i in range(n):
        # Self-attention for first token
        if i == 0:
            attention[i, i] = 1.0
        else:
            # Strong attention to boundary tokens
            boundary_weight = 0.0
            for boundary_idx in boundary_tokens:
                if boundary_idx <= i:
                    # Prefer more recent boundaries
                    distance = i - boundary_idx
                    weight = max(0.3, 0.8 - 0.1 * distance)
                    attention[i, boundary_idx] = weight
                    boundary_weight += weight

            # Some attention to first token
            attention[i, 0] = 0.2

            # Small self-attention
            attention[i, i] = 0.1

            # Very small attention to recent tokens
            for j in range(max(0, i-3), i):
                if j not in boundary_tokens and j != 0:
                    attention[i, j] = 0.05

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L5H9", attention



def prog_L6H0(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Structural boundary attention head focusing on periods and newlines, with strong first-token attention."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    # Find structural tokens (periods and newlines)
    structural_indices = []
    for i, token in enumerate(tokens):
        if token.strip() in ['.', '\n']:
            structural_indices.append(i)

    for i in range(n):
        current_token = tokens[i]

        # Very high attention to structural tokens (periods and newlines)
        for struct_idx in structural_indices:
            if struct_idx <= i:  # causal constraint
                # Distance-based decay from structural tokens
                distance = i - struct_idx
                if distance == 0:
                    attention[i, struct_idx] = 1.0  # self-attention to structural tokens
                else:
                    attention[i, struct_idx] = 0.4 * np.exp(-0.1 * distance)

        # Strong self-attention for first token
        if i == 0:
            attention[i, i] = 1.0

        # Moderate self-attention for other tokens
        if i > 0 and i not in structural_indices:
            attention[i, i] = 0.05

        # Attention to immediately previous token
        if i > 0:
            attention[i, i-1] = 0.15

        # NEW: Strong attention to first token from all positions
        if i > 0:
            # Distance-based decay from first token, but much stronger than baseline
            distance = i
            attention[i, 0] = 0.8 * np.exp(-0.05 * distance)

        # Slight attention to tokens near structural boundaries
        for struct_idx in structural_indices:
            if struct_idx <= i:
                for offset in [-2, -1, 1, 2]:
                    neighbor_idx = struct_idx + offset
                    if 0 <= neighbor_idx <= i:
                        attention[i, neighbor_idx] = 0.08 * np.exp(-abs(offset) * 0.5)

        # Add some baseline attention to early tokens
        for j in range(min(5, i + 1)):
            attention[i, j] += 0.02

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L6H0", attention



def prog_L6H1(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Attends to first tokens and sentence boundary markers (newlines, periods)."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L6H1", np.zeros((n_empty, n_empty))

    # Initialize attention matrix
    attention = np.zeros((n, n))

    for i in range(n):
        # Strong attention to first token
        attention[i, 0] = 1.0

        # Strong attention to newlines and periods
        for j in range(i + 1):  # Causal constraint
            token = tokens[j]
            if token.strip() in ['\n', '.']:
                attention[i, j] = 0.8
            elif token.strip() == ',':
                attention[i, j] = 0.3

        # Self-attention baseline
        attention[i, i] = 0.2

        # Slight attention to previous token
        if i > 0:
            attention[i, i-1] = 0.1

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L6H1", attention



def prog_L6H10(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Structural anchor attention: attends to sentence boundaries, paragraph breaks, and sequence start."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L6H10", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        # Base attention distribution
        base_attention = np.zeros(i + 1)  # Can only attend to positions 0 through i

        # Much stronger attention to structural anchors
        for j in range(i + 1):
            token_j = tokens[j].strip()
            # Sentence boundary punctuation gets very high attention
            if token_j in [".", "!", "?", "\n"]:
                base_attention[j] += 0.7

        # Very strong attention to first token from all positions
        if i > 0:
            base_attention[0] += 0.6

        # Reduced self-attention for punctuation to fix over-prediction
        token_i = tokens[i].strip()
        if token_i in [".", "!", "?", "\n"]:
            base_attention[i] += 0.05  # Much reduced from 0.2
        elif token_i == ",":
            base_attention[i] += 0.1   # Reduced from 0.2

        # Moderate attention to tokens that start sentences
        spacy_indices = token_to_spacy[i]
        if spacy_indices:
            spacy_token = doc[spacy_indices[0]]
            # Check if this token starts a sentence
            if spacy_token.is_sent_start:
                base_attention[i] += 0.15

        # Look for tokens that might be sentence starters based on context
        for j in range(i + 1):
            if j > 0:
                prev_token = tokens[j-1].strip()
                curr_token = tokens[j].strip()
                # Token after sentence-ending punctuation
                if prev_token in [".", "!", "?", "\n"] and curr_token not in ["", " "]:
                    base_attention[j] += 0.1

        # Add some recency bias for nearby tokens
        for j in range(max(0, i-3), i + 1):
            distance = i - j
            if distance <= 3:
                base_attention[j] += 0.05 * (4 - distance) / 4

        # Small uniform attention to all positions
        for j in range(i + 1):
            base_attention[j] += 0.01

        # Normalize and assign
        if base_attention.sum() > 0:
            base_attention = base_attention / base_attention.sum()
        else:
            base_attention[i] = 1.0

        attention[i, :i+1] = base_attention

    # Apply causal mask and ensure row-stochastic
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L6H10", attention



def prog_L6H11(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary and structural marker attention head with strong sentence-initial token attention."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L6H11", np.zeros((n_empty, n_empty))

    attention_matrix = np.zeros((n, n))

    # Identify structural markers
    boundary_markers = set()
    first_tokens = set()

    for i, token in enumerate(tokens):
        # Sentence boundaries and structural punctuation
        if token.strip() in ['.', '\n', '!', '?', ';']:
            boundary_markers.add(i)

        # First token detection (non-whitespace token after boundary or start)
        if i == 0:
            first_tokens.add(i)
        elif i > 0 and tokens[i-1].strip() in ['\n', '.', '!', '?']:
            if token.strip() and not token.strip() in ['\n', '.', '!', '?', ' ']:
                first_tokens.add(i)

    # Parse with spacy for additional linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        token = tokens[i]

        # Self-attention boost for boundary markers
        if i in boundary_markers:
            attention_matrix[i, i] = 0.6

        # Strong attention to sentence boundaries
        for j in boundary_markers:
            if j <= i:
                # Distance decay from boundary markers
                distance = i - j + 1
                base_weight = 0.4 / distance if distance > 0 else 0.4
                attention_matrix[i, j] += base_weight

        # Attention to first tokens in segments
        for j in first_tokens:
            if j <= i:
                distance = i - j + 1
                base_weight = 0.2 / distance if distance > 0 else 0.2
                attention_matrix[i, j] += base_weight

        # NEW: Much stronger attention to sentence-initial tokens for content words
        # This addresses the under-prediction pattern seen in failure cases
        if token_to_spacy[i]:
            spacy_idx = token_to_spacy[i][0]
            if spacy_idx < len(doc):
                spacy_token = doc[spacy_idx]
                # Content words and other non-function words pay very strong attention to sentence starts
                if spacy_token.pos_ in ['NOUN', 'VERB', 'ADJ', 'ADV', 'PROPN', 'NUM'] or not spacy_token.is_stop:
                    for j in first_tokens:
                        if j <= i:
                            # Much stronger base weight with slower distance decay
                            distance = i - j + 1
                            if distance <= 5:
                                # Very strong attention for nearby sentence starts
                                attention_matrix[i, j] += 0.8 / distance
                            else:
                                # Still significant attention for distant sentence starts
                                attention_matrix[i, j] += 0.4 / distance

        # Moderate attention to recent tokens
        for j in range(max(0, i-3), i):
            if j not in boundary_markers and j not in first_tokens:
                distance = i - j
                attention_matrix[i, j] += 0.1 / distance

        # Additional attention for content words to structural elements
        if token_to_spacy[i]:
            spacy_idx = token_to_spacy[i][0]
            if spacy_idx < len(doc):
                spacy_token = doc[spacy_idx]
                if spacy_token.pos_ in ['NOUN', 'VERB', 'ADJ']:
                    # Content words pay extra attention to boundaries
                    for j in boundary_markers:
                        if j <= i:
                            attention_matrix[i, j] += 0.2

    # Apply causal mask and normalize
    attention_matrix = apply_causal_mask(attention_matrix)

    # Add small uniform attention to prevent zero rows
    for i in range(n):
        for j in range(i + 1):
            attention_matrix[i, j] += 0.01

    attention_matrix = make_row_stochastic(attention_matrix)

    return "prog_L6H11", attention_matrix



def prog_L6H12(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary and discourse structure attention head."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    # Find sentence boundary tokens (periods, newlines)
    boundary_tokens = []
    for i, token in enumerate(tokens):
        if token.strip() in ['.', '\n']:
            boundary_tokens.append(i)

    for i in range(n):
        current_token = tokens[i].strip()

        # Strong self-attention for first token
        if i == 0:
            attention[i, i] = 1.0
            continue

        # For newlines and empty tokens, attend strongly to previous boundaries
        if current_token == '\n' or current_token == '':
            for j in boundary_tokens:
                if j < i:
                    # Stronger attention to more recent boundaries
                    distance = i - j
                    attention[i, j] = max(0.3, 1.0 / (1 + distance * 0.1))

            # Some self-attention
            attention[i, i] = 0.1

        # For regular tokens, attend to sentence boundaries with decay
        else:
            for j in boundary_tokens:
                if j < i:
                    distance = i - j
                    # Strong attention to periods, moderate to newlines
                    if tokens[j].strip() == '.':
                        attention[i, j] = max(0.15, 0.6 / (1 + distance * 0.05))
                    elif tokens[j].strip() == '\n':
                        attention[i, j] = max(0.05, 0.3 / (1 + distance * 0.1))

            # Attention to first token
            if len(tokens) > 0:
                attention[i, 0] = 0.1

            # Small amount of self-attention
            attention[i, i] = 0.05

            # Some attention to immediately previous token
            if i > 0:
                attention[i, i-1] = 0.08

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L6H12", attention



def prog_L6H13(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Document structure head: attends strongly to first token, newlines, and sentence delimiters with enhanced period detection."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L6H13", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Identify major sentence-ending periods using spacy
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    major_periods = set()
    for i, spacy_indices in enumerate(token_to_spacy):
        if tokens[i] in ['.', '."', '."']:
            # Check if this period ends a sentence in spacy parse
            for spacy_idx in spacy_indices:
                if spacy_idx < len(doc):
                    spacy_token = doc[spacy_idx]
                    # Look for sentence boundary or period that ends a clause
                    if (spacy_token.is_sent_end or 
                        (spacy_token.text == '.' and spacy_idx + 1 < len(doc) and 
                         (doc[spacy_idx + 1].is_space or doc[spacy_idx + 1].text == '\n'))):
                        major_periods.add(i)
                        break

    for i in range(n):
        # Strong self-attention for first token
        if i == 0:
            attention[i, i] = 1.0
            continue

        # Find positions of structural tokens
        first_token_pos = 0
        newline_positions = [j for j in range(i+1) if tokens[j] == '\n']
        period_positions = [j for j in range(i+1) if tokens[j] in ['.', '."', '."']]

        # Base attention distribution
        for j in range(i+1):
            # Very high attention to first token from early positions
            if j == first_token_pos and i <= 3:
                attention[i, j] = 0.8
            elif j == first_token_pos:
                attention[i, j] = 0.3

            # High attention to newlines
            elif tokens[j] == '\n':
                attention[i, j] = 0.4

            # Enhanced attention to major periods, medium to others
            elif tokens[j] in ['.', '."', '."']:
                if j in major_periods:
                    attention[i, j] = 0.5  # Boost major sentence-ending periods
                else:
                    attention[i, j] = 0.2

            # Lower attention to other tokens
            else:
                # Slight recency bias
                distance = i - j
                if distance == 0:  # self-attention
                    attention[i, j] = 0.05
                else:
                    attention[i, j] = 0.02 / (1 + distance * 0.1)

        # Boost attention if we're near sentence boundaries
        if newline_positions:
            nearest_newline = max(newline_positions)
            for j in newline_positions:
                attention[i, j] *= 2.0

        # Boost first token attention for tokens immediately after first token
        if i <= 5:
            attention[i, first_token_pos] *= 2.0

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L6H13", attention



def prog_L6H14(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Attends strongly to first tokens and newline boundaries with enhanced beginning-of-text focus."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L6H14", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    for i in range(n):
        for j in range(i + 1):  # Causal mask
            weight = 0.0

            # Very strong attention to first token
            if j == 0:
                weight += 0.8

            # Strong attention to newline characters
            if tokens[j] == '\n':
                weight += 0.6

            # Self-attention
            if i == j:
                weight += 0.2

            # Positional decay - prefer earlier tokens
            position_decay = 0.3 * np.exp(-0.1 * (i - j))
            weight += position_decay

            # Small boost for punctuation marks
            if tokens[j] in ['.', '!', '?', ',']:
                weight += 0.1

            # Enhanced beginning-of-text attention for later positions
            # Tokens in later positions attend much more strongly to early tokens
            if i > 10 and j <= 2:
                # Strong boost for very early tokens when attending from late positions
                early_boost = 0.4 * (i / n)  # Scales with how late the attending token is
                weight += early_boost

            attention[i, j] = weight

    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L6H14", attention



def prog_L6H15(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Attends primarily to structural boundary markers (first token, periods, newlines)."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L6H15", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    for i in range(n):
        # Strong attention to first token from all positions
        attention[i, 0] = 10.0

        # Find all period tokens and give them high attention
        for j in range(i + 1):  # Only look at previous tokens due to causal mask
            if tokens[j].strip() == '.':
                attention[i, j] = 8.0
            elif tokens[j].strip() == '\n':
                attention[i, j] = 6.0

        # Self-attention
        attention[i, i] = 1.0

        # Small baseline attention to all previous tokens
        for j in range(i):
            if attention[i, j] == 0:  # Don't override higher values
                attention[i, j] = 0.1

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L6H15", attention



def prog_L6H16(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary attention head with position-dependent first-token attention."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L6H16", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        # Strong attention to newlines
        for j in range(i + 1):
            if tokens[j].strip() == '':  # newline or whitespace
                attention[i, j] += 0.4

        # Strong attention to sentence-ending punctuation
        for j in range(i + 1):
            if tokens[j].strip() in ['.', '!', '?']:
                attention[i, j] += 0.3

        # Position-dependent attention to first token
        if i > 0:
            # Increase first-token attention based on distance from start
            distance_factor = min(i / 10.0, 0.4)  # Cap at 0.4 for very long sequences
            attention[i, 0] += 0.15 + distance_factor

        # Self-attention baseline
        attention[i, i] += 0.05

        # Small attention to immediately previous token
        if i > 0:
            attention[i, i-1] += 0.08

        # Moderate attention to sentence-starting words
        spacy_indices = token_to_spacy[i] if i < len(token_to_spacy) else []
        for spacy_idx in spacy_indices:
            if spacy_idx < len(doc):
                spacy_token = doc[spacy_idx]
                # Look for tokens that start sentences
                if spacy_token.is_sent_start:
                    for j in range(i + 1):
                        if j < len(token_to_spacy):
                            j_spacy_indices = token_to_spacy[j]
                            for j_spacy_idx in j_spacy_indices:
                                if j_spacy_idx < len(doc) and doc[j_spacy_idx].is_sent_start:
                                    attention[i, j] += 0.12

        # Add small random noise to non-zero entries to break ties
        for j in range(i + 1):
            if attention[i, j] > 0:
                attention[i, j] += np.random.uniform(0, 0.01)

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L6H16", attention



def prog_L6H17(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary attention with strong first-token anchoring for sequence coherence."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    # Find newline and sentence-ending punctuation positions
    newline_positions = []
    sentence_end_positions = []

    for i, token in enumerate(tokens):
        if token.strip() == '\n':
            newline_positions.append(i)
        elif token.strip() in ['.', '!', '?']:
            sentence_end_positions.append(i)

    # Find first tokens after newlines (paragraph/section starts)
    paragraph_start_positions = []
    for newline_pos in newline_positions:
        if newline_pos + 1 < n:
            paragraph_start_positions.append(newline_pos + 1)

    for i in range(n):
        # Strong attention to first tokens after newlines
        for start_pos in paragraph_start_positions:
            if start_pos <= i:  # Causal constraint
                # Distance decay from paragraph start
                distance = i - start_pos + 1
                weight = 0.6 / (distance ** 0.3)
                attention[i, start_pos] += weight

        # Moderate attention to sentence endings
        for end_pos in sentence_end_positions:
            if end_pos <= i:  # Causal constraint
                # Distance decay from sentence end
                distance = i - end_pos + 1
                weight = 0.3 / (distance ** 0.5)
                attention[i, end_pos] += weight

        # Special case: newlines attend strongly to themselves
        if i in newline_positions:
            attention[i, i] += 0.8

        # NEW: Strong first-token anchoring
        # All tokens attend strongly to the very first token (position 0)
        if i > 0:  # Skip self-attention for position 0
            # Strong base weight with mild distance decay
            distance = i + 1
            weight = 0.8 / (distance ** 0.2)
            attention[i, 0] += weight

        # Small self-attention baseline
        attention[i, i] += 0.1

        # Very small uniform attention to all previous tokens
        for j in range(i + 1):
            attention[i, j] += 0.01

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L6H17", attention



def prog_L6H18(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Structural boundary attention head - attends to punctuation, line breaks, and sequence starts."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention_matrix = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        token = tokens[i]

        # Strong self-attention for first token
        if i == 0:
            attention_matrix[i, i] = 1.0
            continue

        # Initialize base attention weights
        weights = np.zeros(i + 1)  # Can only attend to current and previous tokens

        # High attention to punctuation marks, especially periods and newlines
        for j in range(i + 1):
            target_token = tokens[j]

            # Very high attention to periods and newlines
            if target_token in ['.', '\n']:
                weights[j] = 0.4
            # Moderate attention to other punctuation
            elif target_token in [',', ';', '!', '?', ':', '"', "'", '(', ')']:
                weights[j] = 0.2
            # Special attention to first token
            elif j == 0:
                weights[j] = 0.3
            # Lower baseline attention to content words
            else:
                weights[j] = 0.05

        # Add distance decay for non-punctuation tokens
        for j in range(i + 1):
            if tokens[j] not in ['.', '\n', ',', ';', '!', '?', ':', '"', "'", '(', ')'] and j != 0:
                distance = i - j
                decay = 1.0 / (1.0 + distance * 0.5)
                weights[j] *= decay

        # Boost attention to recent sentence boundaries
        for j in range(i + 1):
            if tokens[j] in ['.', '\n'] and (i - j) <= 5:
                weights[j] *= 1.5

        # Normalize and assign
        if weights.sum() > 0:
            weights = weights / weights.sum()
        attention_matrix[i, :i+1] = weights

    # Apply causal mask and ensure row-stochastic
    attention_matrix = apply_causal_mask(attention_matrix)
    attention_matrix = make_row_stochastic(attention_matrix)

    return "prog_L6H18", attention_matrix



def prog_L6H19(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary attention head that focuses on first tokens and recent periods."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L6H19", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Find sentence boundary tokens (newlines, periods, first token)
    sentence_boundaries = []
    for i, token in enumerate(tokens):
        if i == 0 or token.strip() in ['\n', '.']:
            sentence_boundaries.append(i)

    for i in range(n):
        # Strong attention to first token (position 0)
        if n > 0:
            attention[i, 0] = 0.8

        # Secondary attention to recent sentence boundaries (periods, newlines)
        for boundary_idx in sentence_boundaries:
            if boundary_idx <= i and boundary_idx != 0:
                # Decay based on distance
                distance = i - boundary_idx
                weight = 0.4 * np.exp(-distance * 0.1)
                attention[i, boundary_idx] += weight

        # Small residual attention to recent tokens
        for j in range(max(0, i-5), i):
            if j not in sentence_boundaries:
                attention[i, j] += 0.01

        # Tiny self-attention
        attention[i, i] += 0.005

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L6H19", attention



def prog_L6H2(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Structural boundary attention with first-token bias and local syntax."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L6H2", np.zeros((n_empty, n_empty))

    attention_matrix = np.zeros((n, n))

    # Get spacy alignment for syntactic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        # Base attention distribution
        weights = np.zeros(i + 1)  # Only attend to previous tokens (causal)

        # Strong attention to structural tokens (newlines, periods)
        for j in range(i + 1):
            if tokens[j].strip() in ['\n', '.']:
                weights[j] += 0.4
            elif tokens[j].strip() == ',':
                weights[j] += 0.15

        # Strong attention to first token
        if i > 0:
            weights[0] += 0.3

        # Self-attention
        weights[i] += 0.1

        # Local syntactic dependencies
        if token_to_spacy[i]:
            spacy_i = token_to_spacy[i][0]
            if spacy_i < len(doc):
                spacy_token = doc[spacy_i]

                # Attend to syntactic head
                if spacy_token.head != spacy_token:
                    head_idx = spacy_token.head.i
                    for j in range(i + 1):
                        if token_to_spacy[j] and head_idx in token_to_spacy[j]:
                            weights[j] += 0.1

                # Attend to previous token for certain dependencies
                if i > 0 and spacy_token.dep_ in ['compound', 'amod', 'prep']:
                    weights[i-1] += 0.08

        # Add small recency bias
        for j in range(max(0, i-3), i):
            weights[j] += 0.02 * (1.0 - (i - j) / 4.0)

        # Normalize and store
        if weights.sum() > 0:
            weights = weights / weights.sum()
        else:
            weights[i] = 1.0  # fallback to self-attention

        attention_matrix[i, :i+1] = weights

    # Ensure proper normalization and causal mask
    attention_matrix = make_row_stochastic(attention_matrix)
    attention_matrix = apply_causal_mask(attention_matrix)

    return "prog_L6H2", attention_matrix



def prog_L6H20(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Attention to text structure markers: newlines, sentence boundaries, and sequence starts."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    # Find structural tokens
    newline_indices = [i for i, token in enumerate(tokens) if token.strip() == '\n']
    punct_indices = [i for i, token in enumerate(tokens) if token.strip() in '.!?']

    for i in range(n):
        current_token = tokens[i].strip()

        # Very high attention to newlines
        for nl_idx in newline_indices:
            if nl_idx <= i:
                attention[i, nl_idx] = 0.7

        # High attention to sentence-ending punctuation
        for punct_idx in punct_indices:
            if punct_idx <= i:
                attention[i, punct_idx] = 0.4

        # Strong attention to first token
        if i > 0:
            attention[i, 0] = 0.3

        # Self-attention for structural tokens
        if current_token in ['\n', '.', '!', '?'] or i == 0:
            attention[i, i] = 0.8
        else:
            attention[i, i] = 0.05

        # Lower baseline attention to nearby tokens
        for j in range(max(0, i-5), i):
            if attention[i, j] == 0:  # Don't override structural attention
                attention[i, j] = 0.02

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L6H20", attention



def prog_L6H21(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Structural boundary attention with enhanced beginning-of-sequence focus."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L6H21", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    for i in range(n):
        token_i = tokens[i]

        # Base attention weights
        weights = np.zeros(i + 1)  # Can only attend to positions <= i

        for j in range(i + 1):
            token_j = tokens[j]

            # Strong attention to newlines
            if token_j.strip() == "":  # Newline or whitespace
                weights[j] += 0.6

            # Strong attention to periods
            elif token_j == ".":
                weights[j] += 0.4

            # Attention to first token
            elif j == 0:
                weights[j] += 0.3

            # Self-attention
            elif i == j:
                weights[j] += 0.1

            # Attention to other punctuation
            elif token_j in [",", "!", "?", ":", ";"]:
                weights[j] += 0.2

            # Small baseline attention to all positions
            weights[j] += 0.05

        # Enhanced beginning-of-sequence attention: boost first token significantly
        if len(weights) > 0:
            # If first token is a period, give it much stronger weight
            if tokens[0] == ".":
                weights[0] += 0.5
            else:
                weights[0] += 0.2

        # Normalize and set row
        if weights.sum() > 0:
            weights = weights / weights.sum()
        attention[i, :i+1] = weights

    # Apply causal mask and ensure row-stochastic
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L6H21", attention



def prog_L6H22(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary and beginning-of-sentence attention head with strong first-token focus."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L6H22", np.zeros((n_empty, n_empty))

    # Initialize attention matrix
    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    # Identify sentence boundary tokens (periods, newlines)
    boundary_tokens = set()
    first_tokens = set([0])  # Always include position 0

    for i, token in enumerate(tokens):
        # Check for sentence boundary punctuation
        if token.strip() in ['.', '\n', '!', '?']:
            boundary_tokens.add(i)
        # Check for newlines which mark sentence starts
        if token.strip() == '\n' and i + 1 < n:
            first_tokens.add(i + 1)

    # Find sentence-initial tokens after boundaries
    for i in range(1, n):
        prev_token = tokens[i-1].strip()
        if prev_token in ['.', '!', '?'] or '\n' in prev_token:
            # Look for the next non-whitespace token
            j = i
            while j < n and tokens[j].strip() in ['', '\n']:
                j += 1
            if j < n:
                first_tokens.add(j)

    for i in range(n):
        token = tokens[i]

        # NEW: Strong attention to the very first token of the sequence
        if i > 0:
            attention[i, 0] += 0.45

        # Reduced attention to newlines and periods (sentence boundaries)
        for j in boundary_tokens:
            if j <= i and j != 0:  # Don't double-count position 0
                if tokens[j].strip() == '\n':
                    attention[i, j] += 0.20
                elif tokens[j].strip() == '.':
                    attention[i, j] += 0.15
                elif tokens[j].strip() in ['!', '?']:
                    attention[i, j] += 0.12

        # Reduced attention to sentence-initial tokens (except position 0)
        for j in first_tokens:
            if j <= i and j != 0:  # Don't double-count position 0
                attention[i, j] += 0.08

        # Local syntactic attention using spacy
        if token_to_spacy[i]:
            spacy_idx = token_to_spacy[i][0]
            if spacy_idx < len(doc):
                spacy_token = doc[spacy_idx]

                # Attention to syntactic head
                if spacy_token.head != spacy_token:
                    head_char_start = spacy_token.head.idx
                    # Find corresponding LM token
                    for j in range(i):
                        if token_to_spacy[j]:
                            for spacy_j in token_to_spacy[j]:
                                if spacy_j < len(doc):
                                    if doc[spacy_j].idx <= head_char_start < doc[spacy_j].idx + len(doc[spacy_j].text):
                                        attention[i, j] += 0.08

        # Self-attention
        attention[i, i] += 0.05

        # Previous token attention
        if i > 0:
            attention[i, i-1] += 0.03

        # Reduced attention based on embedding similarity to boundary tokens
        for j in range(i):
            if j in boundary_tokens and j != 0:  # Don't double-count position 0
                sim = _char_sim(tokens[i], tokens[j])
                if sim > 0.3:
                    attention[i, j] += 0.05 * sim

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L6H22", attention



def prog_L6H23(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary attention head that focuses strongly on sentence-ending punctuation and structural boundaries."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    # Find first non-whitespace token
    first_token_idx = 0
    for i, token in enumerate(tokens):
        if token.strip():
            first_token_idx = i
            break

    for i in range(n):
        token = tokens[i]

        # Base attention to self
        attention[i, i] = 0.1

        # Find the most recent sentence-ending punctuation
        most_recent_sentence_end = -1
        for j in range(i, -1, -1):
            if tokens[j] in ['.', '!', '?']:
                most_recent_sentence_end = j
                break

        # If there's a recent sentence-ending punctuation, prioritize it
        if most_recent_sentence_end != -1:
            # Very strong attention to the most recent sentence boundary
            attention[i, most_recent_sentence_end] = 0.7
            # Reduced attention to first token when sentence boundary is available
            if first_token_idx < i:
                attention[i, first_token_idx] = 0.3
        else:
            # Original behavior when no sentence boundary is found
            # Strong attention to first meaningful token
            if first_token_idx < i:
                attention[i, first_token_idx] = 0.8

        # High attention to newlines (structural boundaries)
        for j in range(i + 1):
            if tokens[j] == '\n':
                attention[i, j] = 0.6

        # Attention to other sentence-ending punctuation (not the most recent)
        for j in range(i + 1):
            if tokens[j] in ['.', '!', '?'] and j != most_recent_sentence_end:
                attention[i, j] = 0.4

        # Special handling for tokens that are newlines themselves
        if token == '\n':
            # Newlines attend strongly to previous structural boundaries
            for j in range(i):
                if tokens[j] == '\n' or tokens[j] in ['.', '!', '?']:
                    attention[i, j] = 0.5

        # Moderate attention to immediately preceding token
        if i > 0:
            attention[i, i-1] = 0.2

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L6H23", attention



def prog_L6H24(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Structural boundary attention head focusing on sentence delimiters and positional patterns."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        for j in range(i + 1):  # Causal mask
            weight = 0.0

            # Very high attention to newlines and periods from most tokens
            if tokens[j] == '\n':
                if i > j:
                    weight += 0.35
            elif tokens[j] == '.':
                if i > j:
                    weight += 0.25

            # First token gets high attention from early positions
            if j == 0 and i <= 5:
                weight += 0.6

            # Extended first token attention - many tokens attend strongly to position 0
            if j == 0 and i > 5:
                # Strong attention to first token from later positions
                weight += 0.4

            # Self-attention baseline
            if i == j:
                weight += 0.05

            # Adjacent token attention (especially for first few tokens)
            if i == j + 1:
                weight += 0.1
                if j < 3:  # Boost for very early tokens
                    weight += 0.2

            # Attention to commas and exclamation marks
            if tokens[j] in [',', '!']:
                if i > j:
                    weight += 0.15

            # Syntactic dependency attention
            if token_to_spacy[i] and token_to_spacy[j]:
                for spacy_i in token_to_spacy[i]:
                    for spacy_j in token_to_spacy[j]:
                        if spacy_i < len(doc) and spacy_j < len(doc):
                            # Head-dependent relationships
                            if doc[spacy_j].head.i == spacy_i or doc[spacy_i].head.i == spacy_j:
                                weight += 0.08

            # Boost for certain POS patterns
            if token_to_spacy[j]:
                for spacy_j in token_to_spacy[j]:
                    if spacy_j < len(doc):
                        # Attention to verbs and important content words
                        if doc[spacy_j].pos_ in ['VERB', 'NOUN'] and i > j + 2:
                            weight += 0.05

            # Distance decay for non-structural tokens
            if tokens[j] not in ['\n', '.', ',', '!'] and j != 0:
                distance = i - j
                if distance > 1:
                    weight *= (1.0 / (1.0 + 0.1 * distance))

            attention[i, j] = weight

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L6H24", attention



def prog_L6H25(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence-boundary attention with first-token emphasis."""
    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L6H25", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Find sentence boundaries (periods and newlines) and first tokens
    sentence_boundaries = []
    first_tokens = []

    for i, token in enumerate(tokens):
        if token.strip() in ['.', '\n']:
            sentence_boundaries.append(i)

        # Identify first tokens (tokens after boundaries or at start)
        if i == 0:
            first_tokens.append(i)
        elif i > 0 and tokens[i-1].strip() in ['.', '\n']:
            first_tokens.append(i)

    for i in range(n):
        # Base self-attention
        attention[i, i] = 0.1

        # Strong attention to sentence boundaries
        for boundary_idx in sentence_boundaries:
            if boundary_idx <= i:  # causal constraint
                attention[i, boundary_idx] = 0.4

        # Strong attention to first tokens
        for first_idx in first_tokens:
            if first_idx <= i:  # causal constraint
                attention[i, first_idx] = 0.3

        # Local attention to previous few tokens
        for j in range(max(0, i-3), i):
            attention[i, j] += 0.05

        # Small boost for similar tokens
        for j in range(i):
            sim = _char_sim(tokens[i], tokens[j])
            if sim > 0.5:
                attention[i, j] += 0.1

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L6H25", attention



def prog_L6H26(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary and document structure head with strong beginning-of-sequence attention."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L6H26", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    for i in range(n):
        # Find newline and period tokens that this token can attend to
        newline_positions = []
        period_positions = []

        for j in range(i + 1):  # causal mask
            if tokens[j].strip() == '':  # newline or whitespace
                newline_positions.append(j)
            elif tokens[j] == '.':
                period_positions.append(j)

        # High attention to newlines (highest priority)
        if newline_positions:
            for pos in newline_positions:
                attention[i, pos] = 0.6

        # High attention to periods (second priority)  
        if period_positions:
            for pos in period_positions:
                attention[i, pos] = 0.4

        # Strong attention to first token when it's punctuation, moderate otherwise
        if i > 0:
            if tokens[0] in [',', '.', '!', '?', ':', ';']:
                attention[i, 0] = 0.8  # Much stronger for punctuation
            else:
                attention[i, 0] = 0.2  # Original fallback

        # Small self-attention
        attention[i, i] = 0.1

        # Small attention to previous token
        if i > 0:
            attention[i, i-1] = 0.05

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L6H26", attention



def prog_L6H27(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Attention head that focuses on sequence-initial tokens and sentence boundaries."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    # Find sequence-initial tokens (newlines, periods at start)
    initial_positions = []
    for i in range(min(3, n)):  # Check first few positions
        if tokens[i].strip() in ['\n', '.', ''] or i == 0:
            initial_positions.append(i)

    # Find sentence-ending punctuation
    sentence_end_positions = []
    for i in range(n):
        if tokens[i].strip() in ['.', '!', '?']:
            sentence_end_positions.append(i)

    for i in range(n):
        # Strong attention to sequence-initial tokens
        for init_pos in initial_positions:
            if init_pos <= i:
                attention[i, init_pos] = 0.6

        # Moderate attention to sentence-ending punctuation
        for end_pos in sentence_end_positions:
            if end_pos <= i and end_pos not in initial_positions:
                attention[i, end_pos] = 0.3

        # Small amount of self-attention
        attention[i, i] = 0.05

        # Very small attention to immediate previous token
        if i > 0:
            attention[i, i-1] = 0.02

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L6H27", attention



def prog_L6H28(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Structural boundary attention: tokens attend to sentence/paragraph boundaries (newlines, periods) and show positional biases."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L6H28", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Find structural boundary tokens (newlines and periods)
    newline_indices = [i for i, token in enumerate(tokens) if token.strip() == '\n']
    period_indices = [i for i, token in enumerate(tokens) if token.strip() == '.']

    for i in range(n):
        token = tokens[i]

        # High self-attention for first token
        if i == 0:
            attention[i, i] = 1.0
        else:
            # Strong attention to newline characters
            for nl_idx in newline_indices:
                if nl_idx <= i:
                    attention[i, nl_idx] = 0.4

            # Strong attention to periods
            for period_idx in period_indices:
                if period_idx <= i:
                    attention[i, period_idx] = 0.3

            # Attention to first token
            attention[i, 0] = 0.2

            # Some self-attention
            attention[i, i] = 0.1

            # Previous token attention
            if i > 0:
                attention[i, i-1] = 0.1

            # Special boost for certain tokens attending to their immediate context
            if i > 0 and tokens[i-1] in ['to', 'and', 'the', 'a']:
                attention[i, i-1] += 0.2

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L6H28", attention



def prog_L6H29(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Structural boundary and first-token attention with local syntactic dependencies."""
    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L6H29", np.zeros((n_empty, n_empty))

    # Initialize attention matrix
    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        token = tokens[i]

        # Strong attention to first token (seen in examples)
        if i > 0:
            attention[i, 0] = 0.4

        # High attention to newlines and periods
        for j in range(i + 1):
            target_token = tokens[j]
            if target_token.strip() in ['\n', '.']:
                attention[i, j] = 0.35

        # Local syntactic dependencies - attend to previous token if it's a function word or verb
        if i > 0:
            prev_token = tokens[i - 1]
            prev_spacy_indices = token_to_spacy[i - 1] if i - 1 < len(token_to_spacy) else []

            for spacy_idx in prev_spacy_indices:
                if spacy_idx < len(doc):
                    spacy_token = doc[spacy_idx]
                    # Attend to previous token if it's a verb, pronoun, or determiner
                    if spacy_token.pos_ in ['VERB', 'PRON', 'DET'] or spacy_token.dep_ in ['nsubj', 'aux']:
                        attention[i, i - 1] = 0.25

        # Self-attention (moderate)
        attention[i, i] = 0.15

        # Attend to conjunctions and prepositions within local window
        for j in range(max(0, i - 5), i):
            target_spacy_indices = token_to_spacy[j] if j < len(token_to_spacy) else []
            for spacy_idx in target_spacy_indices:
                if spacy_idx < len(doc):
                    spacy_token = doc[spacy_idx]
                    if spacy_token.pos_ in ['CCONJ', 'ADP'] or tokens[j].strip() in [',', 'and']:
                        attention[i, j] = 0.2

        # Boost attention for certain punctuation patterns
        for j in range(i + 1):
            if tokens[j].strip() in ['"', "'", '!', '?']:
                attention[i, j] = 0.1

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L6H29", attention



def prog_L6H3(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary attention head with strong beginning-of-document attention - tokens attend strongly to sentence delimiters and the first token."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    # Identify sentence boundary tokens (periods, newlines, exclamation, question marks)
    boundary_tokens = []
    for i, token in enumerate(tokens):
        if token.strip() in ['.', '\n', '!', '?', ';']:
            boundary_tokens.append(i)

    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        # Strong attention to sentence boundary tokens
        for boundary_idx in boundary_tokens:
            if boundary_idx <= i:  # Causal constraint
                # Distance decay for boundaries
                distance = i - boundary_idx
                if distance == 0:
                    attention[i, boundary_idx] = 1.0  # Self-attention to boundary
                elif distance <= 5:
                    attention[i, boundary_idx] = 0.8 - (distance * 0.1)
                else:
                    attention[i, boundary_idx] = 0.3

        # TARGETED FIX: Much stronger attention to first token (beginning-of-document)
        if i > 0:
            # Scale attention based on position - tokens further from start attend more strongly
            first_token_attention = min(0.9, 0.4 + (i * 0.02))
            attention[i, 0] = first_token_attention

        # Local syntactic attention
        if token_to_spacy[i]:
            spacy_idx = token_to_spacy[i][0]
            if spacy_idx < len(doc):
                spacy_token = doc[spacy_idx]

                # Attend to syntactic head
                if spacy_token.head != spacy_token and spacy_token.head.i < len(doc):
                    head_tokens = [j for j in range(i) if j in token_to_spacy and 
                                  token_to_spacy[j] and spacy_token.head.i in token_to_spacy[j]]
                    for head_idx in head_tokens:
                        attention[i, head_idx] = 0.15

                # Attend to previous token for local context
                if i > 0:
                    attention[i, i-1] = 0.1

        # Self-attention baseline
        attention[i, i] = 0.05

        # Small attention to recent tokens if no boundaries found nearby
        if not any(abs(i - b) <= 3 for b in boundary_tokens if b <= i):
            for j in range(max(0, i-3), i):
                attention[i, j] += 0.05

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L6H3", attention



def prog_L6H30(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary attention head that focuses on newlines and periods with positional bias."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention_matrix = np.zeros((n, n))

    # Find positions of sentence boundary markers
    newline_positions = []
    period_positions = []

    for i, token in enumerate(tokens):
        if token.strip() == '\n':
            newline_positions.append(i)
        elif token.strip() == '.':
            period_positions.append(i)

    for i in range(n):
        token = tokens[i]

        # Base attention distribution
        for j in range(i + 1):  # Only attend to previous tokens (causal)
            # Strong attention to newlines, with preference for earlier ones
            if j in newline_positions:
                # Earlier newlines get higher attention
                distance_factor = 1.0 / (len([pos for pos in newline_positions if pos <= j]) + 1)
                attention_matrix[i, j] = 0.4 * distance_factor

            # Strong attention to periods, with preference for earlier ones  
            elif j in period_positions:
                # Earlier periods get higher attention
                distance_factor = 1.0 / (len([pos for pos in period_positions if pos <= j]) + 1)
                attention_matrix[i, j] = 0.35 * distance_factor

            # Moderate attention to first token
            elif j == 0:
                attention_matrix[i, j] = 0.15

            # Small baseline attention to other tokens with recency bias
            else:
                recency = 1.0 / (i - j + 1)
                attention_matrix[i, j] = 0.02 * recency

    # Apply causal mask and normalize
    attention_matrix = apply_causal_mask(attention_matrix)
    attention_matrix = make_row_stochastic(attention_matrix)

    return "prog_L6H30", attention_matrix



def prog_L6H31(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Structural boundary attention head focusing on newlines, periods, and sequence start."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L6H31", np.zeros((n_empty, n_empty))

    attention_matrix = np.zeros((n, n))

    for i in range(n):
        # Strong self-attention for first token
        if i == 0:
            attention_matrix[i, i] = 1.0
            continue

        scores = np.zeros(i + 1)  # Can only attend to tokens <= i

        # High attention to newlines
        for j in range(i + 1):
            if tokens[j].strip() == '\n':
                scores[j] += 0.45

        # High attention to periods
        for j in range(i + 1):
            if tokens[j].strip() == '.':
                scores[j] += 0.4

        # Moderate attention to first token
        scores[0] += 0.15

        # Small self-attention
        scores[i] += 0.05

        # Small recency bias for recent tokens
        for j in range(max(0, i-3), i):
            scores[j] += 0.02 * (1.0 - (i - j) / 4.0)

        # Small attention to other structural markers
        for j in range(i + 1):
            token = tokens[j].strip()
            if token in [',', '!', '?', '"', "'", '(', ')', '[', ']']:
                scores[j] += 0.05

        # Normalize scores
        if scores.sum() > 0:
            attention_matrix[i, :i+1] = scores

    attention_matrix = make_row_stochastic(attention_matrix)
    attention_matrix = apply_causal_mask(attention_matrix)

    return "prog_L6H31", attention_matrix



def prog_L6H4(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary detection head with strong first-token and cross-sentence attention."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L6H4", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        for j in range(i + 1):  # causal mask
            weight = 0.0

            # Very high attention to periods and newlines
            if tokens[j] == '.' or tokens[j] == '\n':
                if i > j:  # not self
                    weight = 0.4
                else:  # self attention to punctuation
                    weight = 0.3

            # High attention between adjacent tokens, especially at sequence start
            elif j == i - 1:
                # Adjacent token attention, stronger for early positions
                position_boost = max(0, 1.0 - i * 0.05)
                weight = 0.2 + position_boost * 0.3

            # Self attention
            elif i == j:
                weight = 0.05

            # Moderate attention to first token from later positions
            elif j == 0 and i > 2:
                weight = 0.15

            # Some attention between nearby tokens (within 3 positions)
            elif abs(i - j) <= 3 and i > j:
                weight = 0.08

            # NEW: Strong attention from later tokens to first token (beyond existing rule)
            if j == 0 and i > 5:
                weight = max(weight, 0.35)

            # NEW: Boost self-attention for periods significantly
            if i == j and tokens[j] == '.':
                weight = 0.6

            # NEW: Strong cross-sentence attention to sentence boundaries
            if tokens[j] == '.' or tokens[j] == '\n':
                if i > j + 10:  # distant tokens
                    weight = max(weight, 0.4)

            # Embedding similarity boost for related tokens
            if i != j and weight > 0:
                sim = _char_sim(tokens[i], tokens[j])
                if sim > 0.7:
                    weight *= 1.5
                elif sim > 0.5:
                    weight *= 1.2

            attention[i, j] = weight

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L6H4", attention



def prog_L6H5(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary and structural punctuation attention head with strong beginning-of-text focus."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L6H5", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Get spacy alignment for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    # Find sentence-ending punctuation (periods, exclamation marks, question marks)
    sentence_end_indices = []
    for i, token in enumerate(tokens):
        if token.strip() in ['.', '!', '?']:
            sentence_end_indices.append(i)

    # Find newlines
    newline_indices = []
    for i, token in enumerate(tokens):
        if '\n' in token:
            newline_indices.append(i)

    # Find first tokens (beginning of text or after whitespace/newlines)
    first_token_indices = [0]  # First token is always a "first token"
    for i, token in enumerate(tokens):
        if i > 0 and ('\n' in tokens[i-1] or tokens[i-1].strip() == ''):
            first_token_indices.append(i)

    for i in range(n):
        current_token = tokens[i].strip()

        # Very high self-attention for certain meaningful tokens - but reduce the weight
        if len(token_to_spacy[i]) > 0:
            spacy_idx = token_to_spacy[i][0]
            if spacy_idx < len(doc):
                spacy_token = doc[spacy_idx]
                if spacy_token.pos_ in ['ADJ', 'NOUN', 'VERB'] and len(current_token) > 2:
                    attention[i, i] = 0.4  # Reduced from 0.8

        # Strong attention to sentence-ending punctuation
        for end_idx in sentence_end_indices:
            if end_idx <= i:  # Causal constraint
                attention[i, end_idx] = 0.35

        # Strong attention to newlines
        for nl_idx in newline_indices:
            if nl_idx <= i:  # Causal constraint
                attention[i, nl_idx] = 0.32

        # Moderate attention to first tokens
        for first_idx in first_token_indices:
            if first_idx <= i:  # Causal constraint
                attention[i, first_idx] = 0.15

        # NEW: Very strong attention to the absolute beginning-of-text token
        if i > 0:  # All tokens except the first can attend to token 0
            attention[i, 0] = 0.6  # Much higher than the 0.15 for other first tokens

        # Local attention to previous few tokens
        for j in range(max(0, i-3), i):
            if attention[i, j] < 0.1:  # Don't override stronger patterns
                attention[i, j] = 0.02 * (1 - (i - j) / 4)  # Decay with distance

        # Some attention to syntactically related tokens
        if len(token_to_spacy[i]) > 0:
            spacy_idx = token_to_spacy[i][0]
            if spacy_idx < len(doc):
                spacy_token = doc[spacy_idx]
                # Attention to head token
                if spacy_token.head != spacy_token:
                    for j in range(i):
                        if len(token_to_spacy[j]) > 0:
                            j_spacy_idx = token_to_spacy[j][0]
                            if j_spacy_idx < len(doc) and doc[j_spacy_idx] == spacy_token.head:
                                attention[i, j] += 0.03

        # Boost attention for semantically similar tokens
        for j in range(i):
            if _char_sim(tokens[i], tokens[j]) > 0.7:
                attention[i, j] += 0.05

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L6H5", attention



def prog_L6H6(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary and structural marker attention head with strong first-token attention."""
    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    # Identify boundary tokens (periods, newlines, and first token)
    boundary_indices = []
    for i, token in enumerate(tokens):
        if i == 0 or token.strip() in ['.', '\n', '!', '?']:
            boundary_indices.append(i)

    for i in range(n):
        # Strong self-attention for first token
        if i == 0:
            attention[i, i] = 1.0
            continue

        # High attention to boundary markers that come before current position
        boundary_attention = 0.0
        for boundary_idx in boundary_indices:
            if boundary_idx <= i:
                # Stronger attention to more recent boundaries
                distance = i - boundary_idx
                if distance == 0:  # self-attention to boundary
                    weight = 0.4
                elif distance <= 3:  # recent boundary
                    weight = 0.3 / (distance + 1)
                else:  # distant boundary
                    weight = 0.1 / (distance + 1)
                attention[i, boundary_idx] = weight
                boundary_attention += weight

        # NEW: Strong attention to the first token from most positions
        if i > 0:
            # Add substantial attention to the first token
            first_token_weight = 0.5
            attention[i, 0] = max(attention[i, 0], first_token_weight)
            boundary_attention = max(boundary_attention, first_token_weight)

        # Add some attention to recent non-boundary tokens
        remaining_attention = max(0, 1.0 - boundary_attention)
        if remaining_attention > 0:
            # Distribute remaining attention with recency bias
            for j in range(max(0, i-5), i):
                if j not in boundary_indices and j != 0:  # Skip first token since we handled it above
                    distance = i - j
                    weight = remaining_attention * 0.1 / (distance + 1)
                    attention[i, j] = weight

    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L6H6", attention



def prog_L6H7(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary and early position attention with local syntax."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L6H7", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))
    doc = spacy_parse(sentence)
    alignment = _align_to_spacy(sentence, tokens)

    for i in range(n):
        for j in range(i + 1):  # causal mask
            weight = 0.0

            # Strong attention to sentence boundaries (newlines and periods)
            if tokens[j].strip() in ['\n', '.']:
                weight += 0.3

            # High attention to first tokens
            if j == 0:
                weight += 0.2
            elif j < 3:  # early tokens
                weight += 0.1

            # Self-attention
            if i == j:
                weight += 0.05

            # Local syntactic dependencies
            if alignment[i] and alignment[j]:
                spacy_i = alignment[i][0] if alignment[i] else None
                spacy_j = alignment[j][0] if alignment[j] else None

                if spacy_i is not None and spacy_j is not None and spacy_i < len(doc) and spacy_j < len(doc):
                    tok_i = doc[spacy_i]
                    tok_j = doc[spacy_j]

                    # Dependencies between adjacent or nearby tokens
                    if abs(spacy_i - spacy_j) <= 2:
                        if tok_j.head == tok_i or tok_i.head == tok_j:
                            weight += 0.08
                        elif tok_i.dep_ in ['nsubj', 'dobj'] and tok_j.pos_ == 'VERB':
                            weight += 0.06
                        elif tok_j.pos_ == 'ADP' and tok_i.pos_ in ['NOUN', 'PRON']:
                            weight += 0.04

            # Position-based decay (prefer earlier tokens)
            position_weight = 0.02 / (i - j + 1) if i > j else 0.05
            weight += position_weight

            # Token similarity boost for nearby similar tokens
            if i != j and abs(i - j) <= 5:
                sim = _char_sim(tokens[i], tokens[j])
                if sim > 0.7:
                    weight += 0.03 * sim

            # Special boost for sentence starters after boundaries
            if j > 0 and tokens[j-1].strip() in ['\n', '.'] and j < n-1:
                weight += 0.15

            attention[i, j] = weight

    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L6H7", attention



def prog_L6H8(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary and structural marker attention head."""
    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L6H8", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Find structural markers (periods, newlines)
    structural_markers = []
    for i, token in enumerate(tokens):
        if token.strip() in ['.', '\n']:
            structural_markers.append(i)

    for i in range(n):
        token = tokens[i]

        # Self-attention for first token
        if i == 0:
            attention[i, i] = 1.0
            continue

        # Strong attention to structural markers
        for marker_idx in structural_markers:
            if marker_idx <= i:  # Causal constraint
                # Distance-based decay
                distance = i - marker_idx
                if distance == 0:
                    weight = 0.6  # Self-attention to markers
                elif distance <= 3:
                    weight = 0.4
                elif distance <= 10:
                    weight = 0.3
                else:
                    weight = 0.2
                attention[i, marker_idx] = weight

        # Moderate attention to recent tokens
        for j in range(max(0, i-5), i):
            if j not in structural_markers:
                distance = i - j
                attention[i, j] = 0.1 / distance

        # Small attention to self if not first token
        if i > 0:
            attention[i, i] = 0.05

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L6H8", attention



def prog_L6H9(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """First-token and sentence boundary attention head with positional decay."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        # Base attention weights
        weights = np.zeros(i + 1)  # Can only attend to previous tokens + self

        # Very strong attention to first token
        if i > 0:
            weights[0] = 5.0

        # Strong attention to sentence boundaries (periods and newlines)
        for j in range(i + 1):
            token_text = tokens[j].strip()
            if token_text == '.' or token_text == '\n':
                weights[j] += 4.0

        # Moderate attention to self
        weights[i] += 2.0

        # Look for syntactic relationships using spacy
        if token_to_spacy[i]:
            spacy_idx = token_to_spacy[i][0]
            if spacy_idx < len(doc):
                current_spacy_token = doc[spacy_idx]

                # Attend to syntactic head
                if current_spacy_token.head != current_spacy_token:
                    head_token = current_spacy_token.head
                    # Find corresponding LM token for the head
                    for j in range(i + 1):
                        if token_to_spacy[j] and head_token.i in token_to_spacy[j]:
                            weights[j] += 1.5
                            break

                # Attend to previous token for certain POS tags
                if current_spacy_token.pos_ in ['NOUN', 'VERB', 'ADJ'] and i > 0:
                    weights[i-1] += 1.0

        # Positional decay - earlier tokens get slight boost
        for j in range(i + 1):
            decay_factor = 1.0 / (i - j + 1) if i > j else 1.0
            weights[j] += 0.5 * decay_factor

        # Embedding similarity boost for semantically similar tokens
        for j in range(i):
            sim = _char_sim(tokens[i], tokens[j])
            if sim > 0.7:
                weights[j] += 1.0 * sim

        # Apply softmax-like transformation to create more realistic distribution
        if weights.sum() > 0:
            weights = np.exp(weights - weights.max())
            weights = weights / weights.sum()

        attention[i, :i+1] = weights

    # Ensure row stochastic and causal
    attention = make_row_stochastic(attention)
    attention = apply_causal_mask(attention)

    return "prog_L6H9", attention



def prog_L7H0(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Structural boundary attention head focusing on newlines, periods, and positional markers."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    # Find structural tokens
    newline_indices = [i for i, token in enumerate(tokens) if token.strip() == '\n']
    period_indices = [i for i, token in enumerate(tokens) if token.strip() == '.']

    for i in range(n):
        # Base attention distribution
        weights = np.zeros(n)

        # Strong attention to newline tokens (primary pattern)
        for nl_idx in newline_indices:
            if nl_idx <= i:  # causal constraint
                weights[nl_idx] += 0.4

        # Moderate attention to period tokens
        for period_idx in period_indices:
            if period_idx <= i:  # causal constraint
                weights[period_idx] += 0.2

        # Self-attention
        weights[i] += 0.1

        # First token attention
        if i > 0:
            weights[0] += 0.1

        # Add small uniform attention to all previous tokens
        for j in range(i + 1):
            weights[j] += 0.02

        # Special boost for recent tokens (recency bias)
        for j in range(max(0, i - 3), i + 1):
            weights[j] += 0.03

        attention[i] = weights

    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L7H0", attention



def prog_L7H1(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary detection head that attends to periods, newlines, and sentence-initial tokens."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    # Find sentence boundaries and structure
    sentence_ends = []
    sentence_starts = []
    newlines = []

    for i, token in enumerate(tokens):
        if token.strip() == '.':
            sentence_ends.append(i)
        elif token.strip() == '\n':
            newlines.append(i)
            if i + 1 < n:
                sentence_starts.append(i + 1)
        elif i == 0:
            sentence_starts.append(i)

    # Get spacy alignment for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        token_i = tokens[i]

        # Self attention baseline
        attention[i, i] = 0.15

        # Strong attention to sentence boundaries
        for end_idx in sentence_ends:
            if end_idx <= i:
                # Distance decay for sentence ends
                distance = i - end_idx
                if distance == 0:
                    attention[i, end_idx] = 0.4
                elif distance <= 3:
                    attention[i, end_idx] = 0.3 / (distance + 1)
                else:
                    attention[i, end_idx] = 0.1 / (distance + 1)

        # Very strong attention to newlines, especially for content words
        for nl_idx in newlines:
            if nl_idx <= i:
                distance = i - nl_idx
                base_strength = 0.5

                # Stronger for content words
                if token_to_spacy[i]:
                    spacy_token = doc[token_to_spacy[i][0]]
                    if spacy_token.pos_ in ['NOUN', 'VERB', 'ADJ', 'ADV']:
                        base_strength = 0.7

                if distance == 0:
                    attention[i, nl_idx] = base_strength
                else:
                    attention[i, nl_idx] = base_strength / (distance * 0.5 + 1)

        # Attention to sentence-initial tokens
        for start_idx in sentence_starts:
            if start_idx <= i and start_idx != i:
                distance = i - start_idx
                if distance <= 5:
                    attention[i, start_idx] = 0.2 / (distance + 1)

        # Attention to function words and determiners
        for j in range(i):
            if token_to_spacy[j]:
                spacy_token = doc[token_to_spacy[j][0]]
                if spacy_token.pos_ in ['DET', 'ADP', 'CONJ', 'CCONJ']:
                    distance = i - j
                    attention[i, j] += 0.15 / (distance + 1)

        # Small attention to previous tokens with recency bias
        for j in range(max(0, i-5), i):
            distance = i - j
            attention[i, j] += 0.05 / distance

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L7H1", attention



def prog_L7H10(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Boundary and first-token attention head with period/newline focus."""
    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L7H10", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Get spacy alignment for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        # Strong attention to sentence boundaries (periods and newlines)
        for j in range(i + 1):
            token_j = tokens[j].strip()

            # Very high attention to periods and newlines
            if token_j == '.' or token_j == '\n':
                attention[i, j] = 0.4
            # High attention to first token
            elif j == 0:
                attention[i, j] = 0.3
            # Medium attention to commas and other punctuation
            elif token_j in [',', '!', '?', ';', ':']:
                attention[i, j] = 0.15
            # Lower attention based on recency and linguistic features
            else:
                # Recency bias - closer tokens get slightly more attention
                recency_weight = 1.0 / (i - j + 1) if i != j else 0.5

                # Small boost for function words and common patterns
                base_weight = 0.02
                if token_to_spacy[j]:
                    spacy_token = doc[token_to_spacy[j][0]]
                    if spacy_token.pos_ in ['DET', 'PRON', 'ADP', 'CONJ', 'CCONJ']:
                        base_weight = 0.05

                attention[i, j] = base_weight * recency_weight

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L7H10", attention



def prog_L7H11(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Newline and sentence boundary attention with syntactic dependencies and first content token focus."""
    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L7H11", np.zeros((n_empty, n_empty))

    # Initialize attention matrix
    attention = np.zeros((n, n))

    # Get spacy parse for syntactic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    # Find first content token (not punctuation/whitespace)
    first_content_idx = None
    for idx, token in enumerate(tokens):
        if token.strip() and not token.strip() in '.,:;!?()[]{}"\'-':
            first_content_idx = idx
            break

    for i in range(n):
        token = tokens[i]

        # Strong attention to newlines and periods
        for j in range(i + 1):
            target_token = tokens[j]

            if target_token.strip() == '\n':
                attention[i, j] += 0.35
            elif target_token.strip() == '.':
                attention[i, j] += 0.25

        # Strong attention to first content token
        if first_content_idx is not None and i > first_content_idx:
            attention[i, first_content_idx] += 0.4

        # Additional syntactic attention
        if token_to_spacy[i]:
            spacy_idx = token_to_spacy[i][0]
            spacy_token = doc[spacy_idx]

            # Attend to syntactic head
            if spacy_token.head != spacy_token:
                head_spacy_idx = spacy_token.head.i
                for j in range(i + 1):
                    if j < len(token_to_spacy) and token_to_spacy[j]:
                        if head_spacy_idx in token_to_spacy[j]:
                            attention[i, j] += 0.05

            # Attend to syntactic children
            for child in spacy_token.children:
                child_spacy_idx = child.i
                for j in range(i + 1):
                    if j < len(token_to_spacy) and token_to_spacy[j]:
                        if child_spacy_idx in token_to_spacy[j]:
                            attention[i, j] += 0.03

        # Small uniform attention to all previous tokens
        for j in range(i + 1):
            attention[i, j] += 0.01

        # Boost attention to tokens with high embedding similarity
        for j in range(i):
            sim = _char_sim(tokens[i], tokens[j])
            if sim > 0.5:
                attention[i, j] += 0.02 * sim

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L7H11", attention



def prog_L7H12(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary and clause-start attention with strong first-token bias."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L7H12", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    # Identify sentence boundaries and sentence starts
    sentence_boundaries = set()
    sentence_starts = set()

    for i, token in enumerate(tokens):
        # Check for sentence boundary punctuation
        if token.strip() in ['.', '!', '?']:
            sentence_boundaries.add(i)
        # Check for newlines (also sentence boundaries)
        elif '\n' in token:
            sentence_boundaries.add(i)

        # Check if this is a sentence start
        if i == 0:
            sentence_starts.add(i)
        elif i > 0:
            prev_token = tokens[i-1]
            if '\n' in prev_token or prev_token.strip() in ['.', '!', '?']:
                sentence_starts.add(i)

    for i in range(n):
        for j in range(i + 1):  # Causal mask
            weight = 0.0

            # Self-attention baseline
            if i == j:
                weight = 0.02

            # Strong attention to sentence boundaries
            if j in sentence_boundaries:
                weight += 0.3

            # Strong attention to sentence starts
            if j in sentence_starts:
                weight += 0.2

            # Recency bias - attend more to recent tokens
            if i != j:
                distance = i - j
                if distance <= 5:
                    weight += 0.05 / (distance + 1)

            # Special case: first token gets very high self-attention
            if i == 0 and j == 0:
                weight = 1.0

            # NEW: Strong first-token attention bias
            # Tokens attend much more strongly to the very first token
            if j == 0 and i > 0:
                weight += 0.4

            # Boost attention to tokens that are linguistically important
            if token_to_spacy[j]:
                spacy_idx = token_to_spacy[j][0]
                if spacy_idx < len(doc):
                    spacy_token = doc[spacy_idx]
                    # Attention to verbs and nouns
                    if spacy_token.pos_ in ['VERB', 'NOUN']:
                        weight += 0.03
                    # Attention to subjects and objects
                    if spacy_token.dep_ in ['nsubj', 'dobj', 'ROOT']:
                        weight += 0.02

            attention[i, j] = weight

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L7H12", attention



def prog_L7H13(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary and structural punctuation attention head."""
    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L7H13", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        token = tokens[i]

        # High attention to first token
        if i > 0:
            attention[i, 0] = 0.3

        # Very high attention to sentence-ending punctuation (. ! ?)
        for j in range(i + 1):
            target_token = tokens[j]
            if target_token.strip() in ['.', '!', '?']:
                attention[i, j] = 0.4

        # High attention to paragraph breaks (\n)
        for j in range(i + 1):
            target_token = tokens[j]
            if target_token.strip() == '\n' or target_token == '\n':
                attention[i, j] = 0.35

        # Medium attention to commas and other structural punctuation
        for j in range(i + 1):
            target_token = tokens[j]
            if target_token.strip() in [',', ';', ':', '-']:
                attention[i, j] = 0.15

        # Self-attention for first token
        if i == 0:
            attention[i, i] = 0.8

        # Baseline attention distribution
        for j in range(i + 1):
            if attention[i, j] == 0:
                # Slight recency bias
                distance = i - j + 1
                attention[i, j] = 1.0 / (distance * 10)

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L7H13", attention



def prog_L7H14(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Structural boundary attention head with strong first-token attention - attends to sentence/paragraph separators, punctuation, and sentence beginnings."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    # Find structural tokens (newlines and sentence-ending punctuation)
    structural_tokens = []
    for j in range(n):
        token = tokens[j].strip()
        if token in ['\n', '.', '!', '?'] or token.endswith('.') or token.endswith('!') or token.endswith('?'):
            structural_tokens.append(j)

    for i in range(n):
        # High attention to structural boundary tokens
        for j in structural_tokens:
            if j <= i:  # Causal constraint
                # Distance-based decay for structural attention
                distance = i - j
                if distance == 0:
                    attention[i, j] = 0.6
                elif distance <= 3:
                    attention[i, j] = 0.4 - 0.1 * distance
                else:
                    attention[i, j] = max(0.1, 0.4 - 0.05 * distance)

        # Local attention patterns
        # Self-attention
        attention[i, i] += 0.1

        # Previous token attention
        if i > 0:
            attention[i, i-1] += 0.15

        # Next previous token with lower weight
        if i > 1:
            attention[i, i-2] += 0.05

        # Enhanced first token attention - boost based on distance
        if i > 0:
            distance_to_first = i
            if distance_to_first <= 10:
                attention[i, 0] += 0.35 - 0.02 * distance_to_first
            else:
                attention[i, 0] += max(0.08, 0.35 - 0.015 * distance_to_first)

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L7H14", attention



def prog_L7H15(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Structural boundary attention: focuses on sentence boundaries, newlines, and clause beginnings."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention_matrix = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    # Identify structural tokens
    newline_indices = [i for i, token in enumerate(tokens) if token.strip() == '\n']
    period_indices = [i for i, token in enumerate(tokens) if token.strip() == '.']

    # Find sentence/clause start tokens (tokens that follow newlines or start the text)
    sentence_start_indices = [0]  # First token
    for nl_idx in newline_indices:
        if nl_idx + 1 < n:
            sentence_start_indices.append(nl_idx + 1)

    for i in range(n):
        token = tokens[i].strip()

        # Base attention distribution
        base_weights = np.zeros(n)

        # Strong attention to newlines and periods
        for nl_idx in newline_indices:
            if nl_idx <= i:
                base_weights[nl_idx] = 0.4

        for period_idx in period_indices:
            if period_idx <= i:
                base_weights[period_idx] = 0.3

        # Attention to sentence/clause beginnings
        for start_idx in sentence_start_indices:
            if start_idx <= i:
                base_weights[start_idx] += 0.2

        # Self-attention for structural tokens
        if token in ['\n', '.', ',']:
            base_weights[i] = 0.5

        # Local syntactic attention using spacy
        if i < len(token_to_spacy) and token_to_spacy[i]:
            spacy_indices = token_to_spacy[i]
            for spacy_idx in spacy_indices:
                if spacy_idx < len(doc):
                    spacy_token = doc[spacy_idx]

                    # Attend to syntactic head
                    if spacy_token.head != spacy_token:
                        head_tokens = align_spacy_to_tokens(sentence)
                        if spacy_token.head.i < len(head_tokens):
                            for head_token_idx in head_tokens[spacy_token.head.i]:
                                if head_token_idx <= i:
                                    base_weights[head_token_idx] += 0.1

        # Distance decay for nearby tokens
        for j in range(max(0, i-3), i+1):
            if j < i:
                distance = i - j
                base_weights[j] += 0.05 / (distance + 1)

        # Add small self-attention
        base_weights[i] += 0.05

        # Special case: strong attention from first few tokens to the very first token
        if i < 5 and i > 0:
            base_weights[0] = max(base_weights[0], 0.3)

        attention_matrix[i] = base_weights

    # Apply causal mask and normalize
    attention_matrix = apply_causal_mask(attention_matrix)
    attention_matrix = make_row_stochastic(attention_matrix)

    return "prog_L7H15", attention_matrix



def prog_L7H16(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary and structural delimiter attention head."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L7H16", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Find important structural tokens
    period_indices = []
    newline_indices = []
    first_token_idx = 0

    for i, token in enumerate(tokens):
        if token.strip() == '.':
            period_indices.append(i)
        elif token.strip() == '\n':
            newline_indices.append(i)

    for i in range(n):
        token = tokens[i].strip()

        # Strong self-attention for first token
        if i == 0:
            attention[i, i] = 1.0
            continue

        # For other tokens, distribute attention based on patterns observed
        weights = np.zeros(i + 1)  # Can only attend to previous tokens + self

        # Base attention to self
        weights[i] = 0.1

        # High attention to newlines (strongest pattern)
        for nl_idx in newline_indices:
            if nl_idx <= i:
                weights[nl_idx] += 0.4

        # High attention to periods (second strongest pattern)
        for period_idx in period_indices:
            if period_idx <= i:
                weights[period_idx] += 0.3

        # Moderate attention to first token
        weights[0] += 0.15

        # Small recency bias for recent tokens
        for j in range(max(0, i-3), i):
            weights[j] += 0.05

        # Normalize
        if weights.sum() > 0:
            attention[i, :i+1] = weights / weights.sum()
        else:
            attention[i, i] = 1.0

    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L7H16", attention



def prog_L7H17(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Structural boundary attention with strong sentence-initial self-attention."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention_matrix = np.zeros((n, n))

    # Find structural tokens (newlines, periods, other punctuation)
    structural_indices = []
    for i, token in enumerate(tokens):
        if token.strip() in ['\n', '.', '!', '?', ';', ':']:
            structural_indices.append(i)

    for i in range(n):
        token = tokens[i]

        # Strong self-attention for sentence-initial token (position 0)
        if i == 0:
            attention_matrix[i, i] = 0.8

        # Strong attention to newline tokens
        for j in structural_indices:
            if j <= i and tokens[j].strip() == '\n':
                attention_matrix[i, j] = 0.4

        # Strong attention to period tokens  
        for j in structural_indices:
            if j <= i and tokens[j].strip() == '.':
                attention_matrix[i, j] = 0.3

        # Medium attention to other punctuation
        for j in structural_indices:
            if j <= i and tokens[j].strip() in ['!', '?', ';', ':', ',']:
                attention_matrix[i, j] = 0.15

        # Self-attention for structural tokens themselves (but not if already handled above)
        if i in structural_indices and i != 0:
            attention_matrix[i, i] = 0.25

        # Local attention to previous few tokens (recency bias)
        for j in range(max(0, i-3), i):
            if j not in structural_indices:
                attention_matrix[i, j] = 0.05 * (1.0 / (i - j))

        # Small baseline attention to all previous tokens
        for j in range(i):
            if attention_matrix[i, j] == 0:
                attention_matrix[i, j] = 0.01

    attention_matrix = apply_causal_mask(attention_matrix)
    attention_matrix = make_row_stochastic(attention_matrix)

    return "prog_L7H17", attention_matrix



def prog_L7H18(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary and discourse structure attention head."""
    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        # Strong self-attention
        attention[i, i] = 0.3

        # Strong attention to first token
        if i > 0:
            attention[i, 0] = 0.4

        # Find sentence boundaries (periods, newlines)
        sentence_boundaries = []
        for j in range(i + 1):
            if tokens[j].strip() in ['.', '\n']:
                sentence_boundaries.append(j)

        # High attention to sentence boundaries
        for boundary in sentence_boundaries:
            attention[i, boundary] = 0.6

        # Moderate attention to recent tokens with decay
        for j in range(max(0, i - 5), i):
            decay = 0.8 ** (i - j)
            attention[i, j] += 0.2 * decay

        # Syntactic attention using spacy
        if token_to_spacy[i]:
            spacy_idx = token_to_spacy[i][0]
            if spacy_idx < len(doc):
                spacy_token = doc[spacy_idx]

                # Attention to syntactic head
                if spacy_token.head != spacy_token:
                    head_text = spacy_token.head.text
                    for j in range(i):
                        if _char_sim(tokens[i], tokens[j]) > 0.7 and tokens[j].strip() in head_text:
                            attention[i, j] += 0.3

                # Attention to dependents
                for child in spacy_token.children:
                    child_text = child.text
                    for j in range(i):
                        if _char_sim(tokens[i], tokens[j]) > 0.7 and tokens[j].strip() in child_text:
                            attention[i, j] += 0.2

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L7H18", attention



def prog_L7H19(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary and syntactic structure attention with strong first-token bias."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L7H19", np.zeros((n_empty, n_empty))

    # Initialize attention matrix
    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        # Base weights for all positions
        for j in range(i + 1):
            # High attention to sentence boundaries
            if tokens[j].strip() in ['.', '\n']:
                attention[i, j] = 0.4
            # Moderate attention to first token
            elif j == 0:
                attention[i, j] = 0.3
            # Local recency bias
            elif i - j <= 3:
                attention[i, j] = 0.2 / (1 + i - j)
            else:
                attention[i, j] = 0.05

        # Strong attention to first token for content words
        if i > 2 and token_to_spacy[0]:
            spacy_0 = token_to_spacy[0][0]
            if spacy_0 < len(doc):
                first_token = doc[spacy_0]
                # If first token is a content word, boost attention to it
                if first_token.pos_ in ['NOUN', 'VERB', 'ADJ', 'ADV', 'PROPN']:
                    attention[i, 0] = 0.8

        # Modified self-attention for first few tokens (reduced from 1.0)
        if i <= 2:
            attention[i, i] = 0.6

        # Boost attention based on syntactic relationships
        if token_to_spacy[i]:
            spacy_i = token_to_spacy[i][0]
            if spacy_i < len(doc):
                current_token = doc[spacy_i]

                for j in range(i + 1):
                    if token_to_spacy[j]:
                        spacy_j = token_to_spacy[j][0]
                        if spacy_j < len(doc):
                            target_token = doc[spacy_j]

                            # Boost for syntactic head
                            if target_token == current_token.head and target_token != current_token:
                                attention[i, j] *= 2.0

                            # Boost for same syntactic phrase
                            elif (current_token.head == target_token.head and 
                                  current_token.head != current_token and
                                  abs(spacy_i - spacy_j) <= 2):
                                attention[i, j] *= 1.5

        # Additional boost for semantic similarity
        for j in range(max(0, i - 5), i):
            if _char_sim(tokens[i], tokens[j]) > 0.7:
                attention[i, j] *= 1.3

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L7H19", attention



def prog_L7H2(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary and punctuation attention head with long-range structural focus."""
    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        # Get spacy tokens aligned to this position
        spacy_indices = token_to_spacy[i] if i < len(token_to_spacy) else []

        for j in range(i + 1):  # Only attend to previous tokens (causal)
            weight = 0.0

            # Strong attention to punctuation marks
            if tokens[j] in ['.', '\n', ',', '!', '?', ';']:
                if tokens[j] in ['.', '\n']:
                    weight += 0.4  # Very strong for periods and newlines
                else:
                    weight += 0.2  # Moderate for other punctuation

            # Attention to first token and sentence beginnings
            if j == 0:
                weight += 0.1

            # Check if j is at sentence beginning (after newline or period)
            if j > 0 and tokens[j-1] in ['\n', '.']:
                weight += 0.15

            # Self-attention
            if i == j:
                weight += 0.08

            # Recency bias - stronger attention to recent tokens
            distance = i - j
            if distance <= 5:
                recency_weight = 0.1 * (6 - distance) / 6
                weight += recency_weight
            elif distance <= 15:
                recency_weight = 0.05 * (16 - distance) / 16
                weight += recency_weight

            # Boost attention between tokens in same clause/sentence
            if spacy_indices and j < len(token_to_spacy):
                j_spacy_indices = token_to_spacy[j]
                if spacy_indices and j_spacy_indices:
                    # Check if they're in the same sentence
                    i_spacy_token = doc[spacy_indices[0]] if spacy_indices else None
                    j_spacy_token = doc[j_spacy_indices[0]] if j_spacy_indices else None

                    if (i_spacy_token and j_spacy_token and 
                        i_spacy_token.sent == j_spacy_token.sent):
                        weight += 0.03

            # Special boost for function words and common patterns
            if j < len(token_to_spacy) and token_to_spacy[j]:
                j_spacy_token = doc[token_to_spacy[j][0]]
                if j_spacy_token.pos_ in ['DET', 'ADP', 'AUX', 'CCONJ']:
                    weight += 0.02

            # NEW: Long-range structural attention to distant sentence boundaries
            if tokens[j] in ['.', '\n'] and distance > 10:
                # Strong boost for attending to distant sentence boundaries
                structural_boost = 0.6 * (distance / n)  # Scale with relative distance
                weight += structural_boost

            # NEW: Reduce excessive self-attention and recent-token attention when distant boundaries exist
            has_distant_boundary = any(tokens[k] in ['.', '\n'] for k in range(max(0, i-20), i))
            if has_distant_boundary:
                if i == j:  # Reduce self-attention
                    weight *= 0.6
                elif distance <= 3:  # Reduce very recent token attention
                    weight *= 0.7

            attention[i, j] = max(weight, 0.01)  # Minimum attention

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L7H2", attention



def prog_L7H20(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary and punctuation attention head with sequence-initial token focus."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L7H20", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        token = tokens[i].strip()

        # Strong self-attention for first token
        if i == 0:
            attention[i, i] = 1.0
            continue

        weights = np.zeros(i + 1)  # Can only attend to previous tokens + self

        # Find newlines and periods to attend to
        newline_positions = []
        period_positions = []

        for j in range(i + 1):
            candidate_token = tokens[j].strip()
            if candidate_token == '\n' or candidate_token == '':
                newline_positions.append(j)
            elif candidate_token == '.':
                period_positions.append(j)

        # Base attention distribution
        for j in range(i + 1):
            candidate_token = tokens[j].strip()

            # High attention to newlines
            if candidate_token == '\n' or candidate_token == '':
                weights[j] = 0.6
            # High attention to periods  
            elif candidate_token == '.':
                weights[j] = 0.4
            # Moderate attention to other punctuation
            elif candidate_token in [',', '!', '?', ';', ':']:
                weights[j] = 0.1
            # Small attention to self
            elif j == i:
                weights[j] = 0.05
            # Very small baseline attention
            else:
                weights[j] = 0.01

        # Special boost for tokens that follow periods or newlines
        if i > 0:
            prev_token = tokens[i-1].strip()
            if prev_token == '.' or prev_token == '\n' or prev_token == '':
                # These tokens get extra attention to recent structural markers
                for pos in newline_positions:
                    if pos < i:
                        weights[pos] *= 1.5
                for pos in period_positions:
                    if pos < i:
                        weights[pos] *= 1.3

        # NEW: Boost attention to sequence-initial content tokens
        # Look for tokens that start sentences/clauses (non-punctuation, non-whitespace)
        for j in range(i + 1):
            candidate_token = tokens[j].strip()
            if candidate_token and candidate_token not in ['\n', '', '.', ',', '!', '?', ';', ':']:
                # Check if this is a sequence-initial token
                is_sequence_initial = False

                # First token is always sequence-initial
                if j == 0:
                    is_sequence_initial = True
                # Token after newline/empty token
                elif j > 0 and tokens[j-1].strip() in ['\n', '']:
                    is_sequence_initial = True
                # Token after sentence-ending punctuation
                elif j > 0 and tokens[j-1].strip() in ['.', '!', '?']:
                    is_sequence_initial = True

                if is_sequence_initial:
                    # Strong boost for sequence-initial content tokens
                    weights[j] *= 8.0

        # Apply positional decay for very distant tokens
        for j in range(i + 1):
            distance = i - j
            if distance > 10:
                weights[j] *= 0.7
            elif distance > 20:
                weights[j] *= 0.5

        attention[i, :i+1] = weights

    # Normalize and apply causal mask
    attention = make_row_stochastic(attention)
    attention = apply_causal_mask(attention)

    return "prog_L7H20", attention



def prog_L7H21(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Attends primarily to newline characters, period punctuation, and beginning-of-sequence tokens as structural boundaries."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention_matrix = np.zeros((n, n))

    # Find newline and period positions
    newline_positions = []
    period_positions = []

    for i, token in enumerate(tokens):
        if token.strip() == '\n':
            newline_positions.append(i)
        elif token.strip() == '.':
            period_positions.append(i)

    for i in range(n):
        # Start with small baseline attention to self
        attention_matrix[i, i] = 0.05

        # Strong attention to newlines (highest priority)
        for newline_pos in newline_positions:
            if newline_pos <= i:  # Causal constraint
                attention_matrix[i, newline_pos] = 0.4

        # Secondary attention to periods
        for period_pos in period_positions:
            if period_pos <= i:  # Causal constraint
                # Reduce if already attending to newline
                base_period_weight = 0.25
                if any(newline_pos <= i for newline_pos in newline_positions):
                    base_period_weight = 0.15
                attention_matrix[i, period_pos] = base_period_weight

        # NEW: Strong attention to the very first token (beginning-of-sequence)
        if i > 0:  # Only non-first tokens attend to first token
            # Stronger attention when there are no newlines/periods to attend to
            first_token_weight = 0.3
            if not any(newline_pos <= i for newline_pos in newline_positions) and not any(period_pos <= i for period_pos in period_positions):
                first_token_weight = 0.5
            attention_matrix[i, 0] = first_token_weight

        # Add some attention to recent tokens (recency bias)
        for j in range(max(0, i-3), i):
            if attention_matrix[i, j] == 0:  # Don't override boundary attention
                attention_matrix[i, j] = 0.02 * (1 / (i - j + 1))

        # Special case: first token gets some self-attention
        if i == 0:
            attention_matrix[i, i] = 0.8

    # Apply causal mask and normalize
    attention_matrix = apply_causal_mask(attention_matrix)
    attention_matrix = make_row_stochastic(attention_matrix)

    return "prog_L7H21", attention_matrix



def prog_L7H22(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary and structure head - attends to periods, newlines, and sentence-initial tokens."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        # Strong attention to sentence boundary markers (periods, newlines)
        for j in range(i + 1):
            token = tokens[j].strip()
            if token in ['.', '\n', '!', '?']:
                attention[i, j] += 0.4

        # High attention to first token of sentence/paragraph
        if i > 0:
            # Find sentence-initial tokens (tokens after periods/newlines or at start)
            for j in range(i + 1):
                if j == 0:
                    attention[i, j] += 0.3
                elif j > 0 and tokens[j-1].strip() in ['.', '\n', '!', '?']:
                    attention[i, j] += 0.3

        # Self-attention baseline
        attention[i, i] += 0.1

        # Local syntactic dependencies - prepositions to nearby tokens
        if i < len(token_to_spacy) and token_to_spacy[i]:
            spacy_idx = token_to_spacy[i][0]
            if spacy_idx < len(doc):
                spacy_token = doc[spacy_idx]
                if spacy_token.pos_ == 'ADP':  # Preposition
                    # Attend to previous token (often the object)
                    if i > 0:
                        attention[i, i-1] += 0.2

        # Boost attention based on proximity to sentence boundaries
        for j in range(i + 1):
            # Find distance to nearest sentence boundary
            dist_to_boundary = float('inf')
            for k in range(n):
                if tokens[k].strip() in ['.', '\n']:
                    dist_to_boundary = min(dist_to_boundary, abs(j - k))

            if dist_to_boundary <= 2:
                attention[i, j] += 0.1

        # Special handling for tokens that often appear near boundaries
        current_token = tokens[i].strip().lower()
        for j in range(i + 1):
            target_token = tokens[j].strip().lower()

            # Common sentence-final words attend to boundaries
            if any(word in current_token for word in ['said', 'was', 'the', 'and']):
                if target_token in ['.', '\n']:
                    attention[i, j] += 0.1

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L7H22", attention



def prog_L7H23(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary and first-token attention head that attends to structural markers."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L7H23", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    for i in range(n):
        # Very strong attention to first token
        attention[i, 0] = 0.6

        # Strong attention to sentence boundaries (newlines and periods)
        for j in range(i + 1):
            token = tokens[j].strip()
            if token == '\n':
                attention[i, j] += 0.4
            elif token == '.':
                attention[i, j] += 0.35

        # Self-attention
        attention[i, i] += 0.1

        # Local attention to previous few tokens with decay
        for offset in range(1, min(4, i + 1)):
            j = i - offset
            weight = 0.1 / offset
            attention[i, j] += weight

        # Slight attention to nearby tokens
        if i > 0:
            attention[i, i-1] += 0.05

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L7H23", attention



def prog_L7H24(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Structural boundary attention head with strong beginning-of-sequence bias."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L7H24", np.zeros((n_empty, n_empty))

    attention_matrix = np.zeros((n, n))

    # Parse with spacy to get linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        # Base attention distribution
        base_attention = np.zeros(n)

        # Strong attention to newline characters (paragraph/section breaks)
        for j in range(i + 1):
            if tokens[j].strip() == '':  # whitespace/newline tokens
                base_attention[j] += 0.45

        # Strong attention to periods (sentence endings)
        for j in range(i + 1):
            if tokens[j].strip() == '.':
                base_attention[j] += 0.4

        # Moderate attention to first token (document beginning)
        if i > 0:
            base_attention[0] += 0.15

        # Small attention to recent tokens (recency bias)
        for j in range(max(0, i - 5), i + 1):
            distance = i - j + 1
            base_attention[j] += 0.05 / distance

        # Self-attention baseline
        base_attention[i] += 0.1

        # Special case: if current token is punctuation, attend more to structural elements
        current_token = tokens[i].strip()
        if current_token in ['.', ',', '!', '?', '"', "'", ':', ';']:
            # Boost attention to newlines and periods
            for j in range(i + 1):
                if tokens[j].strip() in ['', '.']:
                    base_attention[j] *= 1.3

        # NEW: Very strong beginning-of-sequence attention for later tokens
        # This head shows dominant attention to the first token from positions beyond early sequence
        if i >= 2:
            # Strong attention to first token, scaling with distance from start
            beginning_boost = 0.6 if i >= 10 else 0.4 + (i - 2) * 0.05
            base_attention[0] += beginning_boost

        # Apply causal mask and normalize
        attention_matrix[i, :] = base_attention

    attention_matrix = apply_causal_mask(attention_matrix)
    attention_matrix = make_row_stochastic(attention_matrix)

    return "prog_L7H24", attention_matrix



def prog_L7H25(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Structural boundary attention head focusing on periods, newlines, and first tokens with enhanced newline attention."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    # Find structural tokens (periods and newlines)
    period_indices = [i for i, token in enumerate(tokens) if token.strip() == '.']
    newline_indices = [i for i, token in enumerate(tokens) if token.strip() == '\n']

    for i in range(n):
        # Base attention distribution
        weights = np.zeros(i + 1)  # Can only attend to previous tokens + self

        # Strong attention to periods
        for p_idx in period_indices:
            if p_idx <= i:
                weights[p_idx] += 0.4

        # Enhanced attention to newlines (increased from 0.35 to 0.45)
        for n_idx in newline_indices:
            if n_idx <= i:
                weights[n_idx] += 0.45

        # Moderate attention to first token if it exists and is accessible
        if i >= 0:
            weights[0] += 0.15

        # Reduced self-attention (decreased from 0.1 to 0.02)
        weights[i] += 0.02

        # Small uniform attention to remaining tokens
        for j in range(i + 1):
            weights[j] += 0.01

        # Normalize to create valid probability distribution
        if weights.sum() > 0:
            weights = weights / weights.sum()
        else:
            # Fallback: uniform attention
            weights = np.ones(i + 1) / (i + 1)

        attention[i, :i+1] = weights

    # Apply causal mask and ensure row stochastic
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L7H25", attention



def prog_L7H26(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Structural boundary attention head focusing on sentence starts and punctuation."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L7H26", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        token = tokens[i]

        # Very high attention to first token
        if i == 0:
            attention[i, 0] = 1.0
        else:
            # Strong attention to first token from all positions
            attention[i, 0] = 0.3

            # High attention to newlines and periods
            for j in range(i + 1):
                target_token = tokens[j]

                # Newline characters get very high attention
                if target_token.strip() == '' and '\n' in target_token:
                    attention[i, j] = 0.35

                # Period punctuation gets high attention
                elif target_token.strip() == '.':
                    attention[i, j] = 0.25

                # Some self-attention
                elif i == j:
                    attention[i, j] = 0.1

                # Lower attention to other structural punctuation
                elif target_token.strip() in [',', '!', '?', ';', ':']:
                    attention[i, j] = 0.05

                # Base attention to other tokens
                else:
                    attention[i, j] = 0.02

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L7H26", attention



def prog_L7H27(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary and structural marker attention head."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        token = tokens[i]

        # Strong self-attention for first token
        if i == 0:
            attention[i, i] = 1.0
            continue

        # High attention to newlines and periods from most tokens
        newline_weight = 0.0
        period_weight = 0.0

        for j in range(i + 1):
            if tokens[j] == '\n':
                newline_weight += 0.4
            elif tokens[j] == '.':
                period_weight += 0.3

        # Distribute attention
        total_structural = 0.0

        # Attention to newlines
        for j in range(i + 1):
            if tokens[j] == '\n':
                attention[i, j] = 0.4
                total_structural += 0.4

        # Attention to periods
        for j in range(i + 1):
            if tokens[j] == '.':
                attention[i, j] = 0.3
                total_structural += 0.3

        # Attention to first token
        if total_structural < 0.8:
            attention[i, 0] = 0.2
            total_structural += 0.2

        # Self-attention for remaining weight
        remaining = 1.0 - total_structural
        if remaining > 0:
            attention[i, i] = remaining

        # Add some local syntactic attention for non-structural tokens
        if token not in ['\n', '.', ','] and len(token_to_spacy[i]) > 0:
            spacy_idx = token_to_spacy[i][0]
            if spacy_idx < len(doc):
                spacy_token = doc[spacy_idx]

                # Look for head relationships
                if spacy_token.head != spacy_token:
                    head_text = spacy_token.head.text
                    for j in range(i):
                        if _char_sim(tokens[i], tokens[j]) > 0.7:
                            attention[i, j] += 0.1

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L7H27", attention



def prog_L7H28(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Attention head focusing on structural delimiters (newlines, periods) and sequence start."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    # Find structural tokens
    newline_indices = [i for i, token in enumerate(tokens) if token.strip() == '']
    period_indices = [i for i, token in enumerate(tokens) if token.strip() == '.']

    for i in range(n):
        current_token = tokens[i].strip()

        # Strong self-attention for first token
        if i == 0:
            attention[i, i] = 1.0
            continue

        # High attention to newlines, especially the most recent major newline
        for nl_idx in newline_indices:
            if nl_idx <= i:
                # Distance-based weighting, with recent newlines getting more attention
                distance = i - nl_idx
                if distance == 0:
                    attention[i, nl_idx] = 0.42
                elif distance <= 5:
                    attention[i, nl_idx] = 0.46 - 0.01 * distance
                else:
                    attention[i, nl_idx] = max(0.35, 0.50 - 0.02 * distance)

        # Moderate attention to periods
        for p_idx in period_indices:
            if p_idx <= i:
                distance = i - p_idx
                if distance <= 3:
                    attention[i, p_idx] = 0.42 - 0.02 * distance
                else:
                    attention[i, p_idx] = max(0.30, 0.45 - 0.03 * distance)

        # Lower attention to first token (unless it's self)
        if i > 0:
            attention[i, 0] = max(0.10, 0.25 - 0.02 * i)

        # Small attention to immediately previous token
        if i > 0:
            attention[i, i-1] = 0.05

        # Very small self-attention for non-first tokens
        if i > 0:
            attention[i, i] = 0.02

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L7H28", attention



def prog_L7H29(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Attention head that focuses on sentence boundaries (newlines, periods) and sentence beginnings with positional bias."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    for i in range(n):
        token_i = tokens[i]

        for j in range(i + 1):  # Causal mask
            token_j = tokens[j]

            # Base attention score
            score = 0.0

            # Strong attention to newlines and periods
            if token_j.strip() == '\n':
                score += 0.45
            elif token_j.strip() == '.':
                score += 0.35

            # NEW: Strong attention to the first token from all subsequent tokens
            if j == 0 and i > 0:
                score += 0.8

            # Self-attention boost for certain tokens
            if i == j:
                # Higher self-attention for some punctuation and content words
                if token_i.strip() in ['.', '\n'] or len(token_i.strip()) > 0:
                    score += 0.3

            # Position-based attention - slight recency bias
            distance = i - j
            if distance == 0:
                score += 0.1  # Self attention
            elif distance <= 3:
                score += 0.05 / (distance + 1)  # Recent tokens

            # Slight boost for first token
            if j == 0:
                score += 0.1

            # Small boost for punctuation marks
            if token_j.strip() in [',', '!', '?', '"', "'", ';', ':']:
                score += 0.15

            attention[i, j] = score

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L7H29", attention



def prog_L7H3(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence/paragraph boundary detection head that attends to newlines and sentence-ending punctuation."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention_matrix = np.zeros((n, n))

    for i in range(n):
        # Initialize with small uniform attention
        for j in range(i + 1):
            attention_matrix[i, j] = 0.01

        # Strong attention to newlines
        for j in range(i + 1):
            if tokens[j].strip() == "" and "\n" in tokens[j]:
                attention_matrix[i, j] += 0.5

        # Strong attention to sentence-ending punctuation
        for j in range(i + 1):
            if tokens[j].strip() in [".", "!", "?"]:
                attention_matrix[i, j] += 0.3

        # Moderate self-attention
        attention_matrix[i, i] += 0.2

        # Distance-based decay for recent tokens
        for j in range(max(0, i-5), i):
            decay = 1.0 / (1 + (i - j) * 0.5)
            attention_matrix[i, j] += 0.1 * decay

        # Special boost for first token
        if i > 0:
            attention_matrix[i, 0] += 0.05

    # Apply causal mask and normalize
    attention_matrix = apply_causal_mask(attention_matrix)
    attention_matrix = make_row_stochastic(attention_matrix)

    return "prog_L7H3", attention_matrix



def prog_L7H30(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Structural boundary attention with strong first-token focus: tokens attend to sentence delimiters and heavily to the first token."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    # Identify structural boundary tokens (periods, newlines, etc.)
    boundary_indices = []
    for i, token in enumerate(tokens):
        if token.strip() in ['.', '\n', '!', '?']:
            boundary_indices.append(i)

    for i in range(n):
        token = tokens[i].strip()

        # Self-attention for punctuation tokens
        if token in ['.', '\n', '!', '?', ',']:
            attention[i, i] = 0.7

        # Strong attention to boundary tokens (periods and newlines)
        for boundary_idx in boundary_indices:
            if boundary_idx <= i:  # Respect causal mask
                boundary_token = tokens[boundary_idx].strip()
                if boundary_token == '\n':
                    attention[i, boundary_idx] = 0.5
                elif boundary_token == '.':
                    attention[i, boundary_idx] = 0.4
                elif boundary_token in ['!', '?']:
                    attention[i, boundary_idx] = 0.3

        # STRONG attention to first token (this was the missing pattern)
        if i > 0:
            attention[i, 0] = 0.5

        # Some attention to immediately previous token
        if i > 0:
            attention[i, i-1] = 0.15

        # Small self-attention for non-punctuation
        if token not in ['.', '\n', '!', '?', ',']:
            attention[i, i] = 0.05

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L7H30", attention



def prog_L7H31(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Boundary and structural attention head focusing on sentence breaks and text beginnings."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L7H31", np.zeros((n_empty, n_empty))

    attention_matrix = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        # Base attention distribution
        weights = np.zeros(i + 1)  # Can only attend to tokens <= i

        # Strong attention to first token
        if i > 0:
            weights[0] = 0.3

        # Strong attention to newlines and periods (structural boundaries)
        for j in range(i + 1):
            token_text = tokens[j].strip()
            if token_text == '\n':
                weights[j] += 0.4
            elif token_text in ['.', '!', '?']:
                weights[j] += 0.3

        # Self-attention baseline
        weights[i] += 0.1

        # Look for syntactic relationships using spacy
        if token_to_spacy[i]:
            spacy_idx = token_to_spacy[i][0]
            if spacy_idx < len(doc):
                spacy_token = doc[spacy_idx]

                # Attend to syntactic head
                if spacy_token.head != spacy_token:
                    head_idx = spacy_token.head.i
                    for j in range(i + 1):
                        if token_to_spacy[j] and head_idx in token_to_spacy[j]:
                            weights[j] += 0.15

                # Modal verbs and auxiliaries attend to nearby content words
                if spacy_token.pos_ in ['AUX', 'MODAL'] and spacy_token.dep_ == 'aux':
                    for j in range(max(0, i-3), i):
                        if token_to_spacy[j]:
                            spacy_j = token_to_spacy[j][0]
                            if spacy_j < len(doc) and doc[spacy_j].pos_ in ['VERB', 'NOUN']:
                                weights[j] += 0.2

        # Distance-based decay for non-structural tokens
        for j in range(i + 1):
            if tokens[j].strip() not in ['\n', '.', '!', '?'] and j != 0:
                distance = i - j
                if distance > 0:
                    weights[j] += 0.05 * np.exp(-distance / 5.0)

        # Normalize weights
        if weights.sum() > 0:
            weights = weights / weights.sum()
        else:
            weights[i] = 1.0

        attention_matrix[i, :i+1] = weights

    # Apply causal mask and ensure row stochastic
    attention_matrix = apply_causal_mask(attention_matrix)
    attention_matrix = make_row_stochastic(attention_matrix)

    return "prog_L7H31", attention_matrix



def prog_L7H4(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Clause structure attention head focusing on sentence boundaries and local syntactic context."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L7H4", np.zeros((n_empty, n_empty))

    # Initialize attention matrix
    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    # Find important structural tokens (periods, newlines)
    period_indices = []
    newline_indices = []

    for i, token in enumerate(tokens):
        if token.strip() == '.':
            period_indices.append(i)
        elif token.strip() == '\n' or token.strip() == '':
            newline_indices.append(i)

    for i in range(n):
        # Self-attention baseline
        attention[i, i] = 0.1

        # Strong attention to periods and newlines
        for period_idx in period_indices:
            if period_idx <= i:
                # Distance-based decay but strong base attention
                distance = i - period_idx
                attention[i, period_idx] = max(0.3 - 0.02 * distance, 0.05)

        for newline_idx in newline_indices:
            if newline_idx <= i:
                distance = i - newline_idx
                attention[i, newline_idx] = max(0.35 - 0.02 * distance, 0.05)

        # Local context attention (previous few tokens)
        for j in range(max(0, i-5), i):
            if j not in period_indices and j not in newline_indices:
                distance = i - j
                if distance == 1:
                    # Strong attention to immediate previous token
                    attention[i, j] = 0.15
                elif distance <= 3:
                    # Moderate attention to recent tokens
                    attention[i, j] = max(0.08 - 0.02 * distance, 0.02)

        # Syntactic relationship attention using spacy
        if token_to_spacy[i]:
            spacy_token_idx = token_to_spacy[i][0]
            if spacy_token_idx < len(doc):
                spacy_token = doc[spacy_token_idx]

                # Attention to syntactic head
                if spacy_token.head != spacy_token:
                    head_token = spacy_token.head
                    # Find corresponding LM token for the head
                    for j in range(i):
                        if token_to_spacy[j] and any(
                            head_token.idx <= doc[sp_idx].idx < head_token.idx + len(head_token.text)
                            for sp_idx in token_to_spacy[j] if sp_idx < len(doc)
                        ):
                            attention[i, j] += 0.1
                            break

                # Attention between related words (high embedding similarity)
                for j in range(max(0, i-8), i):
                    sim = _char_sim(tokens[i], tokens[j])
                    if sim > 0.7:  # High similarity threshold
                        attention[i, j] += 0.08

        # First token attention for some positions
        if i > 0:
            attention[i, 0] = 0.03

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L7H4", attention



def prog_L7H5(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Detects paragraph and sentence boundaries, attending to newlines and periods."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    # Find boundary tokens (newlines and periods)
    boundary_indices = []
    for i, token in enumerate(tokens):
        if token.strip() in ['\n', '.']:
            boundary_indices.append(i)

    for i in range(n):
        current_token = tokens[i].strip()

        # Self-attention baseline
        attention[i, i] = 0.1

        # Strong attention to newlines and periods (structural boundaries)
        for boundary_idx in boundary_indices:
            if boundary_idx <= i:
                boundary_token = tokens[boundary_idx].strip()
                if boundary_token == '\n':
                    # Very strong attention to newlines
                    attention[i, boundary_idx] = 0.6
                elif boundary_token == '.':
                    # Strong attention to periods
                    attention[i, boundary_idx] = 0.4

        # Moderate attention to first token
        if i > 0:
            attention[i, 0] = 0.1

        # Add some recency bias for recent tokens
        for j in range(max(0, i-3), i):
            if j not in boundary_indices:
                attention[i, j] += 0.05

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
