def prog_L7H6(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Structural boundary attention head focusing on sentence delimiters and newlines."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention_matrix = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        # Reduced self-attention baseline for better fit
        attention_matrix[i, i] = 0.15

        # Find structural tokens to attend to
        for j in range(i + 1):  # Causal mask
            if i == j:  # Self-attention already handled
                continue

            token_j = tokens[j].strip()

            # High attention to newlines
            if token_j == '\n':
                attention_matrix[i, j] += 0.6

            # High attention to periods
            elif token_j == '.':
                attention_matrix[i, j] += 0.35

            # Moderate attention to sentence starters
            elif len(token_to_spacy[j]) > 0:
                spacy_idx = token_to_spacy[j][0]
                if spacy_idx < len(doc):
                    spacy_token = doc[spacy_idx]
                    # Check if it's at sentence beginning
                    if spacy_token.is_sent_start or (spacy_idx == 0):
                        attention_matrix[i, j] += 0.15

            # Small attention to commas and other punctuation
            elif token_j in [',', '!', '?', ';', ':']:
                attention_matrix[i, j] += 0.1

            # First token gets some attention
            elif j == 0:
                attention_matrix[i, j] += 0.05

    # Apply causal mask and normalize
    attention_matrix = apply_causal_mask(attention_matrix)
    attention_matrix = make_row_stochastic(attention_matrix)

    return "prog_L7H6", attention_matrix



def prog_L7H7(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Attends to sentence boundaries with stronger cross-sentence attention patterns."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    # Parse with spacy for sentence boundary detection
    doc = spacy_parse(sentence)
    alignment = _align_to_spacy(sentence, tokens)

    # Identify sentence boundary tokens and document start
    is_sent_boundary = np.zeros(n, dtype=bool)
    is_newline = np.zeros(n, dtype=bool)
    is_first_token = np.zeros(n, dtype=bool)

    for i, token in enumerate(tokens):
        # Check for punctuation that ends sentences
        if token.strip() in ['.', '!', '?']:
            is_sent_boundary[i] = True
        # Check for newlines
        elif token.strip() == '' and '\n' in token:
            is_newline[i] = True
        # First token
        elif i == 0:
            is_first_token[i] = True

    for i in range(n):
        # Self-attention baseline
        attention[i, i] = 0.1

        # Count sentence boundaries between current position and target
        boundaries_seen = 0
        for k in range(i):
            if is_sent_boundary[k] or is_newline[k]:
                boundaries_seen += 1

        # Strong attention to sentence-ending punctuation with cross-sentence boost
        for j in range(i + 1):
            if is_sent_boundary[j]:
                base_weight = 0.4
                # Add cross-sentence attention boost if we've crossed boundaries
                if boundaries_seen > 0:
                    cross_sentence_boost = min(0.3, boundaries_seen * 0.15)
                    attention[i, j] += base_weight + cross_sentence_boost
                else:
                    attention[i, j] += base_weight

        # Strong attention to newlines with cross-sentence boost  
        for j in range(i + 1):
            if is_newline[j]:
                base_weight = 0.3
                # Add cross-sentence attention boost if we've crossed boundaries
                if boundaries_seen > 0:
                    cross_sentence_boost = min(0.4, boundaries_seen * 0.2)
                    attention[i, j] += base_weight + cross_sentence_boost
                else:
                    attention[i, j] += base_weight

        # Moderate attention to first token
        if n > 0:
            attention[i, 0] += 0.1

        # Add some recency bias for nearby tokens
        for j in range(max(0, i-3), i):
            attention[i, j] += 0.05 * (1.0 / (i - j + 1))

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L7H7", attention



def prog_L7H8(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Attention to sentence start and structural boundaries with local context."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L7H8", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        # Initialize with small uniform distribution over available positions
        for j in range(i + 1):
            attention[i, j] = 0.01

        # Very strong attention to first token
        if i > 0:
            attention[i, 0] = 0.4
        else:
            attention[i, 0] = 0.3

        # High attention to sentence boundary markers (periods, newlines)
        for j in range(i + 1):
            token = tokens[j].strip()
            if token in ['.', '\n', '!', '?']:
                attention[i, j] += 0.25

        # Self-attention boost for boundary markers
        current_token = tokens[i].strip()
        if current_token in ['.', '\n', '!', '?']:
            attention[i, i] += 0.2

        # Moderate attention to recent tokens (recency bias)
        for j in range(max(0, i - 5), i):
            distance = i - j
            decay_factor = 0.1 / (distance + 1)
            attention[i, j] += decay_factor

        # Boost attention between tokens with high embedding similarity
        for j in range(i):
            sim = _char_sim(tokens[i], tokens[j])
            if sim > 0.7:
                attention[i, j] += 0.1 * sim

        # Boost attention to function words and common structural elements
        for j in range(i + 1):
            if len(token_to_spacy[j]) > 0:
                spacy_idx = token_to_spacy[j][0]
                if spacy_idx < len(doc):
                    spacy_token = doc[spacy_idx]
                    if spacy_token.pos_ in ['DET', 'ADP', 'CCONJ', 'SCONJ']:
                        attention[i, j] += 0.05

    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L7H8", attention



def prog_L7H9(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary attention head with strong first-token attention - attends to periods/newlines and heavily to the first token."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    # Find sentence boundary tokens (periods and newlines)
    boundary_indices = []
    for i, token in enumerate(tokens):
        if token.strip() in ['.', '\n']:
            boundary_indices.append(i)

    for i in range(n):
        current_token = tokens[i].strip()

        # High attention to sentence boundaries
        for boundary_idx in boundary_indices:
            if boundary_idx <= i:  # Respect causal mask
                # Closer boundaries get higher attention
                distance = i - boundary_idx + 1
                attention[i, boundary_idx] = 1.0 / distance

        # Strong attention to first token (new pattern detected from failures)
        if i > 0:  # All tokens except first attend to first token
            # Use spacy to check if first token is a content word
            spacy_alignment = _align_to_spacy(sentence, tokens)
            if len(spacy_alignment) > 0 and len(spacy_alignment[0]) > 0:
                doc = spacy_parse(sentence)
                first_spacy_idx = spacy_alignment[0][0]
                if first_spacy_idx < len(doc):
                    first_spacy_token = doc[first_spacy_idx]
                    # Strong attention if first token is content word (NOUN, VERB, ADJ, ADV)
                    if first_spacy_token.pos_ in ['NOUN', 'VERB', 'ADJ', 'ADV']:
                        attention[i, 0] = 0.8
                    else:
                        attention[i, 0] = 0.4
                else:
                    attention[i, 0] = 0.4
            else:
                attention[i, 0] = 0.4

        # Moderate self-attention for all tokens
        attention[i, i] = 0.3

        # Special case: if current token is a boundary, give it very high self-attention
        if current_token in ['.', '\n']:
            attention[i, i] = 1.0

        # Lower attention to first token if we haven't set it high above
        if i > 0 and attention[i, 0] < 0.4:
            attention[i, 0] = 0.1

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L7H9", attention



def prog_L8H0(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary and structural punctuation attention head with sentence-initial token attention."""
    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    # Get spacy alignment for linguistic features
    spacy_alignment = _align_to_spacy(sentence, tokens)
    doc = spacy_parse(sentence)

    # Find sentence-initial tokens (tokens that start new sentences)
    sentence_initial_tokens = set()
    sentence_initial_tokens.add(0)  # First token is always sentence-initial

    for i in range(1, n):
        # Check if previous token is sentence-ending punctuation or newline
        if i > 0 and tokens[i-1].strip() in ['.', '!', '?', '\n']:
            sentence_initial_tokens.add(i)

    for i in range(n):
        for j in range(i + 1):  # Causal mask
            weight = 0.0

            # Very strong attention to newlines and periods
            if tokens[j].strip() == '\n':
                weight += 0.35
            elif tokens[j].strip() == '.':
                weight += 0.3

            # Strong self-attention for first token
            if i == 0 and j == 0:
                weight += 0.8

            # NEW: Strong attention to sentence-initial tokens from all later tokens in the same sentence
            if j in sentence_initial_tokens and i > j:
                # Find which sentence-initial token this position i belongs to
                current_sentence_start = 0
                for start_pos in sorted(sentence_initial_tokens):
                    if start_pos <= i:
                        current_sentence_start = start_pos
                    else:
                        break

                # If j is the start of the current sentence, add strong attention
                if j == current_sentence_start:
                    weight += 0.6

            # Moderate attention to sentence-ending punctuation
            if tokens[j].strip() in ['!', '?', ';']:
                weight += 0.15

            # Attention to commas (weaker)
            if tokens[j].strip() == ',':
                weight += 0.05

            # Local syntactic dependencies
            if spacy_alignment[i] and spacy_alignment[j]:
                spacy_i = spacy_alignment[i][0] if spacy_alignment[i] else None
                spacy_j = spacy_alignment[j][0] if spacy_alignment[j] else None

                if spacy_i is not None and spacy_j is not None and spacy_i < len(doc) and spacy_j < len(doc):
                    # Dependency relations
                    if doc[spacy_j] in [child for child in doc[spacy_i].children]:
                        weight += 0.08
                    if doc[spacy_i].head == doc[spacy_j]:
                        weight += 0.08

            # Semantic similarity boost
            sim = _char_sim(tokens[i], tokens[j])
            if sim > 0.7:
                weight += 0.1 * sim

            # Position-based decay
            distance = i - j
            if distance > 0:
                weight *= (0.95 ** distance)

            # Small baseline attention
            weight += 0.01

            attention[i, j] = weight

    # Normalize and apply causal mask
    attention = make_row_stochastic(attention)
    attention = apply_causal_mask(attention)

    return "prog_L8H0", attention



def prog_L8H1(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Structural boundary attention with strong beginning-of-sequence focus."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention_matrix = np.zeros((n, n))

    for i in range(n):
        for j in range(i + 1):  # Causal mask
            weight = 0.01  # Base attention

            # Very high attention to newlines
            if tokens[j] == '\n':
                weight = 0.5

            # High attention to sentence-ending punctuation
            elif tokens[j] in ['.', '!', '?']:
                weight = 0.35

            # High attention to first token
            elif j == 0:
                weight = 0.25

            # Medium attention to commas and other punctuation
            elif tokens[j] in [',', ';', ':']:
                weight = 0.15

            # Self-attention for first few tokens
            elif i == j and i < 4:
                weight = 0.8 if i == 0 else 0.1

            # Small boost for recent tokens
            elif i - j <= 2:
                weight = 0.05

            # NEW: Strong beginning-of-sequence attention pattern
            # Tokens in later parts of the sentence attend strongly to the first token
            if j == 0 and i > 10:
                weight = max(weight, 0.6)

            attention_matrix[i, j] = weight

    # Normalize and apply causal mask
    attention_matrix = make_row_stochastic(attention_matrix)
    attention_matrix = apply_causal_mask(attention_matrix)

    return "prog_L8H1", attention_matrix



def prog_L8H10(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary and punctuation-focused attention head."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L8H10", np.zeros((n_empty, n_empty))

    attention_matrix = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        token_i = tokens[i]

        # Strong self-attention for first token
        if i == 0:
            attention_matrix[i, i] = 1.0
            continue

        # High base attention to punctuation and whitespace
        for j in range(i + 1):
            token_j = tokens[j]

            # Very high attention to periods and newlines
            if token_j in ['.', '\n']:
                attention_matrix[i, j] = 0.3
            # Moderate attention to other punctuation
            elif token_j in [',', '!', '?', ':', ';', '"', "'", '(', ')', '-']:
                attention_matrix[i, j] = 0.1
            # Base attention to all other tokens
            else:
                attention_matrix[i, j] = 0.02

        # Additional attention based on linguistic features
        spacy_indices_i = token_to_spacy[i]
        if spacy_indices_i:
            spacy_token_i = doc[spacy_indices_i[0]]

            for j in range(i + 1):
                spacy_indices_j = token_to_spacy[j]
                if spacy_indices_j:
                    spacy_token_j = doc[spacy_indices_j[0]]

                    # Boost attention between similar tokens
                    sim = _char_sim(tokens[i], tokens[j])
                    if sim > 0.7:
                        attention_matrix[i, j] += 0.05

                    # Boost attention from content words to function words
                    if (spacy_token_i.pos_ in ['NOUN', 'VERB', 'ADJ'] and 
                        spacy_token_j.pos_ in ['ADP', 'DET', 'AUX']):
                        attention_matrix[i, j] += 0.03

        # Special boost for attending to sentence start positions
        for j in range(i + 1):
            if j == 0 or (j > 0 and tokens[j-1] in ['\n', '.', '!', '?']):
                attention_matrix[i, j] += 0.05

    # Apply causal mask and normalize
    attention_matrix = apply_causal_mask(attention_matrix)
    attention_matrix = make_row_stochastic(attention_matrix)

    return "prog_L8H10", attention_matrix



def prog_L8H11(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Punctuation and early-position hub attention with positional decay."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        return "prog_L8H11", np.zeros((0, 0))

    attention = np.zeros((n, n))

    for i in range(n):
        for j in range(i + 1):  # causal mask
            weight = 0.0

            # Strong attention to punctuation tokens, especially "." and "\n"
            if tokens[j].strip() in [".", "\n"]:
                if tokens[j].strip() == ".":
                    weight += 0.25
                elif tokens[j].strip() == "\n":
                    weight += 0.30
            elif tokens[j].strip() in [",", "!", "?", ":", ";"]:
                weight += 0.15

            # Strong positional bias toward early tokens (first 15 positions)
            if j < 15:
                early_boost = 0.20 * (1.0 - j / 15.0)
                weight += early_boost

            # Additional boost for very early tokens (first 5)
            if j < 5:
                weight += 0.15 * (1.0 - j / 5.0)

            # Self-attention baseline
            if i == j:
                weight += 0.05

            # Local attention with distance decay
            distance = i - j
            if distance <= 10:
                local_weight = 0.08 * np.exp(-distance / 5.0)
                weight += local_weight

            # General recency bias
            if distance > 0:
                recency = 0.10 * np.exp(-distance / 8.0)
                weight += recency

            # Small boost for tokens that are similar (same word family)
            if i != j and _char_sim(tokens[i], tokens[j]) > 0.7:
                weight += 0.03

            attention[i, j] = weight

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L8H11", attention



def prog_L8H12(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Clause boundary and intra-clause syntactic relationship attention head."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L8H12", np.zeros((n_empty, n_empty)).reshape(0, 0)

    # Initialize attention matrix
    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        # Strong self-attention baseline
        attention[i, i] = 0.1

        # Very high attention to sentence boundaries (periods and newlines)
        for j in range(i + 1):
            if tokens[j].strip() in ['.', '\n']:
                attention[i, j] += 0.3

        # High attention to newlines specifically
        for j in range(i + 1):
            if tokens[j].strip() == '\n':
                attention[i, j] += 0.2

        # Syntactic relationship attention
        if token_to_spacy[i]:
            spacy_i = token_to_spacy[i][0]
            if spacy_i < len(doc):
                spacy_token_i = doc[spacy_i]

                # Look for syntactic dependencies
                for j in range(i + 1):
                    if token_to_spacy[j]:
                        spacy_j = token_to_spacy[j][0]
                        if spacy_j < len(doc):
                            spacy_token_j = doc[spacy_j]

                            # Head-dependent relationships
                            if spacy_token_i.head == spacy_token_j or spacy_token_j.head == spacy_token_i:
                                attention[i, j] += 0.15

                            # Special attention to adverbial modifiers and their heads
                            if spacy_token_i.dep_ == 'advmod' and spacy_token_i.head == spacy_token_j:
                                attention[i, j] += 0.2

                            # Attention between verbs and their arguments
                            if spacy_token_i.pos_ == 'VERB' and spacy_token_j.dep_ in ['nsubj', 'dobj', 'pobj']:
                                if spacy_token_j.head == spacy_token_i:
                                    attention[i, j] += 0.1

        # Semantic similarity within reasonable distance
        for j in range(max(0, i - 10), i + 1):
            if i != j:
                sim = _char_sim(tokens[i], tokens[j])
                if sim > 0.7:  # High semantic similarity
                    attention[i, j] += 0.1 * sim

        # Proximity bias with decay
        for j in range(max(0, i - 5), i):
            distance = i - j
            proximity_weight = 0.05 / (distance + 1)
            attention[i, j] += proximity_weight

        # Special attention patterns for specific constructions
        for j in range(i + 1):
            # Conjunctions attend to their conjuncts
            if token_to_spacy[i] and token_to_spacy[j]:
                if token_to_spacy[i][0] < len(doc) and token_to_spacy[j][0] < len(doc):
                    spacy_i = doc[token_to_spacy[i][0]]
                    spacy_j = doc[token_to_spacy[j][0]]

                    if spacy_i.pos_ == 'CCONJ' and spacy_j.pos_ in ['NOUN', 'VERB', 'ADJ']:
                        attention[i, j] += 0.08

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L8H12", attention



def prog_L8H13(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary attention with semantic similarity and positional bias."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L8H13", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        for j in range(i + 1):  # Causal mask
            weight = 0.0

            # Strong attention to sentence boundaries (periods and newlines)
            if tokens[j] in [".", "\n"]:
                weight += 0.25

            # Attention to first token of sentences
            if j == 0:
                weight += 0.08
            elif j > 0 and tokens[j-1] in [".", "\n"]:
                weight += 0.08

            # Self-attention baseline
            if i == j:
                weight += 0.02

            # Previous token attention
            if j == i - 1:
                weight += 0.05

            # Semantic similarity component
            sim = _char_sim(tokens[i], tokens[j])
            if sim > 0.7:
                weight += 0.04 * sim

            # Distance decay for non-boundary tokens
            if tokens[j] not in [".", "\n"] and j != 0:
                distance = i - j + 1
                weight *= (1.0 / (1.0 + 0.1 * distance))

            # Boost for punctuation and function words
            spacy_indices = token_to_spacy[j]
            if spacy_indices:
                spacy_token = doc[spacy_indices[0]]
                if spacy_token.pos_ in ["PUNCT", "DET", "ADP", "CONJ", "SCONJ"]:
                    weight += 0.03

            attention[i, j] = weight

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L8H13", attention



def prog_L8H14(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary and syntactic dependency attention head with quote/discourse boundary enhancement."""
    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L8H14", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Parse with spacy for syntactic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        # Strong attention to sentence boundaries (periods and newlines)
        for j in range(i + 1):
            if tokens[j].strip() in ['.', '\n']:
                attention[i, j] += 3.0

        # NEW: Enhanced attention to quote boundaries and discourse markers
        for j in range(i + 1):
            # Very strong attention to opening quotes
            if tokens[j].strip() in ['"', "'"] and j == 0:
                attention[i, j] += 8.0
            elif tokens[j].strip() in ['"', "'"] and j > 0:
                attention[i, j] += 6.0

            # Strong attention to sentence-initial discourse markers
            if j < 3 and token_to_spacy[j]:  # First few tokens
                spacy_j = token_to_spacy[j][0]
                if spacy_j < len(doc):
                    spacy_token = doc[spacy_j]
                    # Discourse markers and proper nouns at sentence start
                    if spacy_token.pos_ in ['PROPN', 'INTJ'] or spacy_token.dep_ in ['intj', 'discourse']:
                        attention[i, j] += 4.0

        # Self-attention baseline (reduced to compensate for new patterns)
        attention[i, i] += 0.3

        # Attention based on syntactic dependencies
        if token_to_spacy[i]:
            spacy_i = token_to_spacy[i][0]
            if spacy_i < len(doc):
                spacy_token = doc[spacy_i]

                # Attend to syntactic head
                if spacy_token.head != spacy_token:
                    head_idx = spacy_token.head.i
                    for j in range(i + 1):
                        if token_to_spacy[j] and head_idx in token_to_spacy[j]:
                            attention[i, j] += 1.0

                # Attend to children
                for child in spacy_token.children:
                    child_idx = child.i
                    for j in range(i + 1):
                        if token_to_spacy[j] and child_idx in token_to_spacy[j]:
                            attention[i, j] += 0.8

        # Semantic similarity component
        for j in range(i + 1):
            sim = _char_sim(tokens[i], tokens[j])
            if sim > 0.7:  # High similarity threshold
                attention[i, j] += sim * 0.5

        # Recency bias - attend more to recent tokens
        for j in range(max(0, i - 5), i):
            attention[i, j] += 0.3 * (1.0 - (i - j) / 6.0)

        # Special attention patterns for specific POS tags
        if token_to_spacy[i]:
            spacy_i = token_to_spacy[i][0]
            if spacy_i < len(doc):
                spacy_token = doc[spacy_i]

                # Pronouns attend to potential antecedents
                if spacy_token.pos_ == 'PRON':
                    for j in range(i):
                        if token_to_spacy[j]:
                            spacy_j = token_to_spacy[j][0]
                            if spacy_j < len(doc) and doc[spacy_j].pos_ in ['NOUN', 'PROPN']:
                                attention[i, j] += 0.6

                # Verbs attend to their subjects and objects
                if spacy_token.pos_ == 'VERB':
                    for j in range(i + 1):
                        if token_to_spacy[j]:
                            spacy_j = token_to_spacy[j][0]
                            if spacy_j < len(doc):
                                dep = doc[spacy_j].dep_
                                if dep in ['nsubj', 'dobj', 'nsubjpass']:
                                    attention[i, j] += 1.2

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L8H14", attention



def prog_L8H15(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary and semantic relationship attention head with first-token focus."""
    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L8H15", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        # Strong self-attention for first token
        if i == 0:
            attention[i, i] = 1.0
            continue

        # Initialize base attention
        for j in range(i + 1):
            # High attention to sentence boundaries (periods and newlines)
            if tokens[j] in [".", "\n"]:
                attention[i, j] = 0.3
            # Moderate attention to commas and other punctuation
            elif tokens[j] in [",", ":", ";", "!", "?"]:
                attention[i, j] = 0.1
            # Base recency bias
            else:
                distance = i - j
                attention[i, j] = 0.05 / (1 + distance * 0.1)

        # Boost attention based on semantic similarity
        for j in range(i):
            sim = _char_sim(tokens[i], tokens[j])
            if sim > 0.3:  # Semantically related tokens
                attention[i, j] += 0.2 * sim

        # Boost attention to conjunctions and connecting words
        spacy_indices = token_to_spacy[i]
        if spacy_indices:
            spacy_token = doc[spacy_indices[0]]
            if spacy_token.pos_ in ["CCONJ", "SCONJ"]:  # Conjunctions
                for j in range(i):
                    if tokens[j] not in [".", "\n", ","]:
                        attention[i, j] += 0.1

        # Look for related entities/pronouns
        if spacy_indices:
            current_spacy = doc[spacy_indices[0]]
            if current_spacy.pos_ == "PRON":
                # Pronouns attend to preceding nouns
                for j in range(i):
                    j_spacy = token_to_spacy[j]
                    if j_spacy:
                        j_token = doc[j_spacy[0]]
                        if j_token.pos_ in ["NOUN", "PROPN"]:
                            attention[i, j] += 0.15

        # Strong attention to first token for most positions
        # This captures the pattern where tokens strongly attend to sentence/utterance beginnings
        if i > 3:  # Skip very early tokens to avoid overriding existing strong patterns
            # Check if first token is likely sentence start (not just punctuation in isolation)
            first_token_boost = 0.0
            if tokens[0] in ['"', "'", "'"]:  # Quote markers
                first_token_boost = 0.4
            elif len(tokens) > 1 and tokens[0] not in [".", ",", "!", "?", ":", ";"]:  # Content word at start
                first_token_boost = 0.3
            elif tokens[0] in [",", "."]:  # Sentence boundary punctuation
                first_token_boost = 0.2

            if first_token_boost > 0:
                attention[i, 0] += first_token_boost

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L8H15", attention



def prog_L8H16(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Paragraph structure head: attends to newlines, periods, and paragraph beginnings."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    # Find newline and period positions
    newline_positions = []
    period_positions = []

    for i, token in enumerate(tokens):
        if token.strip() == '\n':
            newline_positions.append(i)
        elif token.strip() == '.':
            period_positions.append(i)

    for i in range(n):
        token = tokens[i]

        # Special case: first token gets perfect self-attention
        if i == 0:
            attention[i, i] = 1.0
            continue

        # High attention to newlines
        for nl_pos in newline_positions:
            if nl_pos <= i:
                attention[i, nl_pos] = 0.35

        # High attention to periods
        for period_pos in period_positions:
            if period_pos <= i:
                attention[i, period_pos] = 0.32

        # Strong attention to first token (paragraph beginning pattern)
        if i > 0:
            attention[i, 0] = 0.25

        # Check if current token is right after a newline (paragraph start)
        is_after_newline = False
        if i > 0 and tokens[i-1].strip() == '\n':
            is_after_newline = True

        # If we're at paragraph start, boost attention to first token
        if is_after_newline:
            attention[i, 0] = 0.4
            # Also boost attention to the newline we just passed
            attention[i, i-1] = 0.4

        # Add some local attention to nearby tokens
        for j in range(max(0, i-3), i):
            if attention[i, j] == 0:  # Don't override existing high attention
                attention[i, j] = 0.05

        # Small self-attention
        attention[i, i] = 0.02

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L8H16", attention



def prog_L8H17(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary and discourse structure attention head - tracks newlines, periods, narrative flow, and document beginnings."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L8H17", np.zeros((n_empty, n_empty)).reshape(0, 0)

    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        # Self-attention baseline
        attention[i, i] = 0.1

        # Very strong attention to newlines and periods
        for j in range(i + 1):
            if tokens[j] == '\n':
                attention[i, j] = 0.4
            elif tokens[j] == '.':
                attention[i, j] = 0.3
            elif tokens[j] == '."':
                attention[i, j] = 0.25

        # NEW: Strong attention to the first token if it's meaningful
        if i > 0:  # Don't add to self-attention
            first_token_spacy = token_to_spacy[0]
            if first_token_spacy:
                first_spacy_token = doc[first_token_spacy[0]]
                # Strong attention to first token if it's a content word or quote start
                if (first_spacy_token.pos_ in ['NOUN', 'VERB', 'ADJ', 'PROPN', 'PRON'] or 
                    tokens[0] in ['"', 'With', 'and']):
                    attention[i, 0] = 0.35

        # Moderate attention to sentence beginnings (tokens after newlines/periods)
        for j in range(i):
            if j > 0 and (tokens[j-1] == '\n' or tokens[j-1] == '.' or tokens[j-1] == '."'):
                # Get linguistic features for this token
                spacy_indices = token_to_spacy[j]
                if spacy_indices:
                    spacy_token = doc[spacy_indices[0]]
                    # Higher attention to content words at sentence start
                    if spacy_token.pos_ in ['NOUN', 'VERB', 'ADJ', 'PROPN']:
                        attention[i, j] = 0.15
                    else:
                        attention[i, j] = 0.08

        # Attention to narrative markers and discourse connectors
        spacy_indices = token_to_spacy[i]
        if spacy_indices:
            spacy_token = doc[spacy_indices[0]]
            # If current token is a verb or narrative word, attend more to sentence structure
            if spacy_token.pos_ == 'VERB' or spacy_token.lemma_ in ['say', 'think', 'look', 'know', 'want']:
                for j in range(i):
                    if tokens[j] == '\n':
                        attention[i, j] *= 1.2
                    elif tokens[j] == '.':
                        attention[i, j] *= 1.1

        # Slight recency bias for recent content
        for j in range(max(0, i-5), i):
            if tokens[j] not in ['\n', '.', '."', ',', ' ']:
                attention[i, j] += 0.02

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L8H17", attention



def prog_L8H18(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary and first-token attention with enhanced global first-token bias."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L8H18", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Find sentence boundaries (periods and newlines)
    boundaries = []
    for i, token in enumerate(tokens):
        if token.strip() in ['.', '\n']:
            boundaries.append(i)

    # Find sentence starts (tokens after boundaries or first token)
    sentence_starts = [0]
    for boundary_idx in boundaries:
        if boundary_idx + 1 < n:
            sentence_starts.append(boundary_idx + 1)

    for i in range(n):
        current_token = tokens[i].strip()

        # Strong self-attention for first token
        if i == 0:
            attention[i, i] = 1.0
            continue

        # Find which sentence this token belongs to
        current_sentence_start = 0
        for start in sentence_starts:
            if start <= i:
                current_sentence_start = start
            else:
                break

        # Base attention weights
        for j in range(i + 1):
            token_j = tokens[j].strip()

            # Very high attention to the absolute first token (global bias)
            if j == 0:
                attention[i, j] = 0.5

            # High attention to sentence boundaries
            elif token_j in ['.', '\n']:
                attention[i, j] = 0.35

            # High attention to current sentence start (first token of sentence)
            elif j == current_sentence_start:
                attention[i, j] = 0.25

            # Moderate attention to other sentence starts
            elif j in sentence_starts:
                attention[i, j] = 0.15

            # Self-attention
            elif i == j:
                attention[i, j] = 0.1

            # Recency bias for recent tokens
            elif i - j <= 3:
                attention[i, j] = 0.05

            # Low baseline attention to other tokens
            else:
                attention[i, j] = 0.02

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L8H18", attention



def prog_L8H19(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary and structural marker attention head."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    # Identify structural markers
    newlines = []
    periods = []
    first_tokens = []

    for i, token in enumerate(tokens):
        if token.strip() == '\n':
            newlines.append(i)
        elif token.strip() == '.':
            periods.append(i)
        elif i == 0 or (i > 0 and tokens[i-1].strip() == '\n'):
            first_tokens.append(i)

    for i in range(n):
        # Strong attention to newlines
        for nl_idx in newlines:
            if nl_idx <= i:
                attention[i, nl_idx] = 0.4

        # Strong attention to periods
        for period_idx in periods:
            if period_idx <= i:
                attention[i, period_idx] = 0.35

        # Medium attention to first tokens (tokens that start sentences)
        for first_idx in first_tokens:
            if first_idx <= i and first_idx not in newlines:
                attention[i, first_idx] = 0.25

        # Self-attention baseline
        attention[i, i] = 0.05

        # Small attention to recent tokens
        for j in range(max(0, i-3), i):
            if attention[i, j] == 0:  # Don't override structural attention
                attention[i, j] = 0.02

    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L8H19", attention



def prog_L8H2(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary attention head focusing on newlines, periods, and structural markers."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    for i in range(n):
        query_token = tokens[i].strip()

        # Base uniform attention to all previous tokens (including self)
        for j in range(i + 1):
            attention[i, j] = 0.01

        # Strong attention to newlines
        for j in range(i + 1):
            if tokens[j].strip() == '\n':
                attention[i, j] += 0.35

        # Strong attention to periods
        for j in range(i + 1):
            if tokens[j].strip() == '.':
                attention[i, j] += 0.25

        # High self-attention for first token and special tokens
        if i == 0 or query_token in ['.', '\n', ',']:
            attention[i, i] += 0.4

        # Enhanced attention to first token from other positions
        if i > 0:
            attention[i, 0] += 0.15

        # Slight boost for recent tokens (recency bias)
        for j in range(max(0, i-3), i):
            attention[i, j] += 0.05

        # Boost attention for punctuation marks
        for j in range(i + 1):
            punct_token = tokens[j].strip()
            if punct_token in [',', '!', '?', ':', ';', '"', "'", '-']:
                attention[i, j] += 0.1

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L8H2", attention



def prog_L8H20(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Structural boundary attention with recency bias and strong first-token attention."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L8H20", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    alignment = _align_to_spacy(sentence, tokens)

    for i in range(n):
        for j in range(i + 1):  # Only attend to previous tokens (causal)

            # Very high attention for first token self-attention
            if i == 0 and j == 0:
                attention[i, j] = 1.0
                continue

            # Strong attention to structural delimiters (newlines and periods)
            if tokens[j] in ['\n', '.']:
                attention[i, j] = 0.4
                continue

            # Base recency bias - prefer earlier tokens
            recency_weight = 1.0 / (i - j + 1) if i > j else 0.8
            attention[i, j] = 0.02 * recency_weight

            # NEW: Strong attention to first token for later positions
            if j == 0 and i > 0:
                # Check if first token is meaningful (not just punctuation/whitespace)
                first_is_meaningful = tokens[0] not in ['.', ',', '!', '?', ';', ':', '\n', ' ', '']
                if first_is_meaningful:
                    # Scale attention based on distance, but keep it strong
                    distance_decay = max(0.3, 1.0 / (i * 0.5 + 1))
                    attention[i, j] = min(0.8, 0.4 * distance_decay)

            # Boost for certain syntactic relationships
            if alignment[i] and alignment[j]:
                spacy_i = alignment[i][0]
                spacy_j = alignment[j][0]

                if spacy_i < len(doc) and spacy_j < len(doc):
                    tok_i = doc[spacy_i]
                    tok_j = doc[spacy_j]

                    # Boost for dependency relationships
                    if tok_j in tok_i.ancestors or tok_i.head == tok_j:
                        attention[i, j] *= 2.0

                    # Boost for similar tokens
                    sim = _char_sim(tokens[i], tokens[j])
                    if sim > 0.7:
                        attention[i, j] *= (1.0 + sim)

            # Additional boost for punctuation
            if tokens[j] in [',', '!', '?', ';', ':']:
                attention[i, j] *= 1.5

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L8H20", attention



def prog_L8H21(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Structural boundary attention head with long-range semantic repetition detection."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L8H21", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Get spacy alignment for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        # Base weights for different target types
        for j in range(i + 1):  # Causal mask
            weight = 0.01  # Base weight

            token_j = tokens[j].strip()

            # High attention to newlines
            if token_j == '\n':
                weight = 0.4
            # High attention to periods
            elif token_j == '.':
                weight = 0.35
            # Moderate attention to first token
            elif j == 0:
                weight = 0.25
            # Self-attention
            elif i == j:
                weight = 0.05
            # Attention to empty/whitespace tokens
            elif token_j == '' or token_j.isspace():
                weight = 0.15
            # Lower attention to punctuation
            elif token_j in [',', '!', '?', ';', ':']:
                weight = 0.08

            # Boost for sentence-initial positions (after newlines or periods)
            if j > 0:
                prev_token = tokens[j-1].strip()
                if prev_token in ['\n', '.', '!', '?']:
                    weight *= 1.5

            # Distance decay for non-special tokens
            if token_j not in ['\n', '.', ''] and j != 0 and i != j:
                distance = i - j
                weight *= np.exp(-distance * 0.1)

            # NEW: Boost for semantically similar tokens at long distances
            if i != j and token_j not in ['\n', '.', '', ',', '!', '?', ';', ':'] and not token_j.isspace():
                distance = i - j
                if distance > 10:  # Only for long distances where decay would be strong
                    similarity = _char_sim(tokens[i], tokens[j])
                    if similarity > 0.7:  # High semantic similarity
                        # Strong boost that overcomes distance decay
                        weight *= 15.0

            attention[i, j] = weight

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L8H21", attention



def prog_L8H22(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Punctuation-focused attention head with strong first-token preference and positional bias."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L8H22", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Parse sentence for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        for j in range(i + 1):  # Causal mask: j <= i
            weight = 0.0

            # Strong attention to punctuation marks
            if tokens[j] in ['.', '!', '?']:
                weight += 0.4
            elif tokens[j] in ['\n']:
                weight += 0.35
            elif tokens[j] in [',', ';', ':']:
                weight += 0.15

            # Much stronger attention to first token
            if j == 0:
                weight += 0.6

            # Reduced self-attention bonus (especially for non-punctuation)
            if i == j:
                if tokens[i] in ['.', '!', '?', ',', ';', ':', '\n']:
                    weight += 0.15  # Keep original self-attention for punctuation
                else:
                    weight += 0.05  # Reduce self-attention for content tokens

            # Positional decay - prefer recent tokens
            distance = i - j
            if distance == 0:
                position_weight = 0.1
            elif distance <= 3:
                position_weight = 0.1 / (distance + 1)
            else:
                position_weight = 0.05 / (distance + 1)

            weight += position_weight

            # Boost for tokens that are grammatically important
            if len(token_to_spacy[j]) > 0:
                spacy_idx = token_to_spacy[j][0]
                if spacy_idx < len(doc):
                    spacy_token = doc[spacy_idx]
                    if spacy_token.pos_ in ['VERB', 'NOUN', 'PROPN']:
                        weight += 0.08
                    elif spacy_token.pos_ in ['ADP', 'CONJ', 'SCONJ']:
                        weight += 0.05

            # Small boost for similar tokens
            if i != j:
                sim = _char_sim(tokens[i], tokens[j])
                if sim > 0.3:
                    weight += 0.05 * sim

            attention[i, j] = weight

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L8H22", attention



def prog_L8H23(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Attention head that focuses on sentence boundaries (newlines/periods) with semantic similarity patterns and sequence-start attention."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L8H23", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Parse sentence for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        for j in range(i + 1):  # Causal mask: j <= i
            weight = 0.0

            # Very high attention to newlines and periods
            if tokens[j] in ['\n', '.']:
                weight += 0.4

            # Strong self-attention for first token
            if i == j and i == 0:
                weight += 0.6

            # Moderate self-attention for other tokens
            elif i == j:
                weight += 0.1

            # NEW: Strong attention to sequence-initial token from all positions
            if j == 0 and i > 0:
                weight += 0.3

            # Attention based on embedding similarity
            sim = _char_sim(tokens[i], tokens[j])
            if sim > 0.3:  # Only for reasonably similar tokens
                weight += 0.2 * sim

            # Additional boost for punctuation boundaries
            if tokens[j] in [',', '!', '?', ';', ':']:
                weight += 0.1

            # Small positional bias - slightly prefer recent tokens
            if i > j:
                recency_factor = 1.0 / (1.0 + 0.1 * (i - j))
                weight *= recency_factor

            # Boost for tokens at sentence/clause boundaries
            if j < len(token_to_spacy) and token_to_spacy[j]:
                spacy_idx = token_to_spacy[j][0]
                if spacy_idx < len(doc):
                    spacy_token = doc[spacy_idx]
                    if spacy_token.is_sent_start or spacy_token.dep_ == 'ROOT':
                        weight += 0.15

            attention[i, j] = max(weight, 0.01)  # Minimum attention

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L8H23", attention



def prog_L8H24(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence/paragraph boundary attention head that focuses on newlines, periods, and strongly attends to the first token."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention_matrix = np.zeros((n, n))

    # Find boundary tokens (newlines and periods)
    boundary_indices = []
    for i, token in enumerate(tokens):
        if token.strip() in ['\n', '.']:
            boundary_indices.append(i)

    for i in range(n):
        token = tokens[i]

        # High self-attention for first token
        if i == 0:
            attention_matrix[i, i] = 0.6

        # Strong attention to boundary tokens (newlines and periods)
        for boundary_idx in boundary_indices:
            if boundary_idx <= i:  # Causal constraint
                if token.strip() == '\n':
                    attention_matrix[i, boundary_idx] = 0.4
                elif token.strip() == '.':
                    attention_matrix[i, boundary_idx] = 0.3
                else:
                    attention_matrix[i, boundary_idx] = 0.35

        # Very strong attention to the first token (beginning of sequence)
        if i > 0:
            attention_matrix[i, 0] = 0.6

        # Self-attention for punctuation
        if token.strip() in ['.', ',', '!', '?']:
            attention_matrix[i, i] = 0.5

        # Moderate attention to previous token
        if i > 0:
            attention_matrix[i, i-1] = 0.15

        # Small uniform attention to all previous tokens
        for j in range(i):
            if attention_matrix[i, j] == 0:  # Only if not already set
                attention_matrix[i, j] = 0.02

    # Apply causal mask and normalize
    attention_matrix = apply_causal_mask(attention_matrix)
    attention_matrix = make_row_stochastic(attention_matrix)

    return "prog_L8H24", attention_matrix



def prog_L8H25(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Contextual boundary and semantic relation attention head."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L8H25", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        # Base attention distribution
        base_weights = np.zeros(i + 1)

        # Strong attention to sentence boundaries (periods and newlines)
        for j in range(i + 1):
            token = tokens[j].strip()
            if token in ['.', '\n']:
                base_weights[j] += 3.0

        # High semantic similarity attention
        for j in range(i):
            sim = _char_sim(tokens[i], tokens[j])
            if sim > 0.3:  # High similarity threshold
                base_weights[j] += 2.0 * sim

        # First token attention for many positions
        if i > 0:
            base_weights[0] += 1.0

        # Self attention
        base_weights[i] += 0.5

        # Recent token bias
        if i > 0:
            base_weights[i-1] += 0.3

        # Special boost for tokens that are parts of compound words or phrases
        current_token = tokens[i].strip()
        for j in range(max(0, i-5), i):
            prev_token = tokens[j].strip()
            # Check if current token could be continuation of previous
            if len(current_token) > 0 and len(prev_token) > 0:
                if (current_token.isalpha() and prev_token.isalpha() and 
                    _char_sim(tokens[i], tokens[j]) > 0.2):
                    base_weights[j] += 1.0

        # Apply linguistic features through spacy alignment
        if token_to_spacy[i]:
            spacy_idx = token_to_spacy[i][0]
            if spacy_idx < len(doc):
                spacy_token = doc[spacy_idx]

                # Verbs attend to their subjects/objects
                if spacy_token.pos_ == 'VERB':
                    for j in range(i):
                        if token_to_spacy[j]:
                            j_spacy_idx = token_to_spacy[j][0]
                            if j_spacy_idx < len(doc):
                                j_spacy_token = doc[j_spacy_idx]
                                if j_spacy_token.pos_ == 'NOUN' or j_spacy_token.pos_ == 'PRON':
                                    base_weights[j] += 0.8

                # Content words attend to sentence beginnings
                if spacy_token.pos_ in ['NOUN', 'VERB', 'ADJ', 'ADV']:
                    for j in range(min(3, i + 1)):  # First few tokens
                        base_weights[j] += 0.5

        # Normalize and add small uniform distribution
        if np.sum(base_weights) > 0:
            base_weights = base_weights / np.sum(base_weights)
        else:
            base_weights = np.ones(i + 1) / (i + 1)

        # Mix with uniform for stability
        uniform = np.ones(i + 1) / (i + 1)
        final_weights = 0.85 * base_weights + 0.15 * uniform

        attention[i, :i+1] = final_weights

    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L8H25", attention



def prog_L8H26(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Attention head that focuses on sentence boundaries (periods, newlines) with syntactic structure awareness and strong first-token attention."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L8H26", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        # Strong attention to sentence boundary markers
        for j in range(i + 1):
            if tokens[j].strip() in ['.', '\n']:
                if tokens[j].strip() == '.':
                    attention[i][j] = 0.25
                else:  # newline
                    attention[i][j] = 0.3

        # Self-attention for first token
        if i == 0:
            attention[i][i] = 0.8

        # Strong attention from all tokens to the first token
        if i > 0:
            attention[i][0] = 0.4

        # Moderate attention to syntactically important positions
        spacy_indices = token_to_spacy[i]
        if spacy_indices:
            spacy_token = doc[spacy_indices[0]]

            # Attention to sentence root and main verbs
            for j in range(i + 1):
                j_spacy_indices = token_to_spacy[j]
                if j_spacy_indices:
                    j_spacy_token = doc[j_spacy_indices[0]]

                    if j_spacy_token.dep_ == 'ROOT' or j_spacy_token.pos_ == 'VERB':
                        attention[i][j] += 0.08

                    # Attention to determiners and function words
                    if j_spacy_token.pos_ in ['DET', 'ADP', 'PRON']:
                        attention[i][j] += 0.04

        # Positional bias - some attention to recent tokens
        for j in range(max(0, i - 3), i + 1):
            if tokens[j].strip() not in ['.', '\n']:
                distance_weight = 0.02 / (i - j + 1)
                attention[i][j] += distance_weight

        # Small attention to semantically similar tokens
        for j in range(i + 1):
            if i != j:
                similarity = _char_sim(tokens[i], tokens[j])
                if similarity > 0.7:
                    attention[i][j] += 0.03 * similarity

    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L8H26", attention



def prog_L8H27(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Attention to structural boundaries (newlines, periods) and sequence-initial tokens with very strong first-token focus."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention_matrix = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        for j in range(i + 1):  # Only attend to previous tokens (causal)
            weight = 0.0

            # Very strong attention to the first token from all positions
            if j == 0:
                # Much stronger boost - the real attention is often 0.4-0.9+
                weight += 0.8

            # High attention to newline characters
            elif tokens[j].strip() == '' and '\n' in tokens[j]:
                weight += 0.35

            # High attention to period tokens
            elif tokens[j] == '.':
                weight += 0.32

            # Strong attention from any token to very early tokens (1-2)
            elif j <= 2:
                weight += 0.15

            # Medium attention to comma tokens
            elif tokens[j] == ',':
                weight += 0.1

            # Local syntactic attention - adjacent tokens
            if abs(i - j) == 1:
                weight += 0.05

            # Self-attention baseline
            if i == j:
                weight += 0.02

            # Small boost for tokens that are linguistically similar
            if i != j:
                sim = _char_sim(tokens[i], tokens[j])
                if sim > 0.7:
                    weight += 0.03

            # Boost for attending to tokens at sentence boundaries
            if j > 0 and j < n-1:
                if tokens[j-1] == '.' or ('\n' in tokens[j-1]):
                    weight += 0.08

            attention_matrix[i, j] = weight

    # Apply causal mask and normalize
    attention_matrix = apply_causal_mask(attention_matrix)
    attention_matrix = make_row_stochastic(attention_matrix)

    return "prog_L8H27", attention_matrix



def prog_L8H28(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Structural boundary attention head with emphasis on sentence breaks and punctuation."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L8H28", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Identify structural tokens (newlines, periods, sentence boundaries)
    newline_indices = [i for i, token in enumerate(tokens) if token.strip() == '\n']
    period_indices = [i for i, token in enumerate(tokens) if token.strip() == '.']

    for i in range(n):
        current_token = tokens[i].strip()

        # Strong self-attention for first token
        if i == 0:
            attention[i, i] = 1.0
            continue

        # High attention to newlines and periods
        for nl_idx in newline_indices:
            if nl_idx <= i:
                attention[i, nl_idx] = 0.3

        for period_idx in period_indices:
            if period_idx <= i:
                attention[i, period_idx] = 0.25

        # Special attention for compound tokens (attend to previous token if similar)
        if i > 0:
            similarity = _char_sim(tokens[i], tokens[i-1])
            if similarity > 0.7:  # High similarity suggests compound word
                attention[i, i-1] = 0.8

        # Moderate self-attention
        attention[i, i] = 0.1

        # Small recency bias to recent tokens
        for j in range(max(0, i-3), i):
            if attention[i, j] == 0:  # Don't override existing weights
                attention[i, j] = 0.05 * (1.0 - (i - j) / 4.0)

        # Attention to first token
        if i > 0:
            attention[i, 0] = 0.15

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L8H28", attention



def prog_L8H29(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Structural boundary attention with first-token and sentence-end focus."""
    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L8H29", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    for i in range(n):
        # Base attention weights
        weights = np.zeros(i + 1)  # Only attend to previous tokens (causal)

        # Strong attention to first token
        if i > 0:
            weights[0] = 0.8

        # High attention to newlines
        for j in range(i + 1):
            if tokens[j].strip() == '':  # Newline or whitespace
                weights[j] += 0.6

        # Moderate attention to periods
        for j in range(i + 1):
            if tokens[j] == '.':
                weights[j] += 0.4

        # Self-attention
        weights[i] += 0.3

        # Recency bias - closer tokens get higher weight
        for j in range(i + 1):
            distance = i - j
            if distance > 0:
                weights[j] += 0.1 / (1 + distance * 0.5)

        # Special case for first token attending to itself
        if i == 0:
            weights[0] = 1.0

        # Normalize to avoid zero rows
        if weights.sum() == 0:
            weights[i] = 1.0

        attention[i, :i+1] = weights

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L8H29", attention



def prog_L8H3(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Structural token attention head focusing on early structural tokens (newlines, periods) with position-based preferences."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L8H3", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        # Very high attention to first token
        if n > 0:
            attention[i, 0] = 5.0

        # High attention to structural tokens (newlines, periods)
        for j in range(i + 1):
            if tokens[j].strip() == '' and '\n' in tokens[j]:  # newline tokens
                attention[i, j] += 4.0
            elif tokens[j] == '.':
                attention[i, j] += 3.0

        # Self-attention for punctuation
        if tokens[i] in ['.', ',', '!', '?'] or '\n' in tokens[i]:
            attention[i, i] += 2.0

        # Syntactic dependencies
        if token_to_spacy[i]:
            spacy_idx = token_to_spacy[i][0]
            if spacy_idx < len(doc):
                spacy_token = doc[spacy_idx]

                # Attention to syntactic head
                if spacy_token.head != spacy_token:
                    head_token = spacy_token.head
                    for j in range(i + 1):
                        if token_to_spacy[j] and head_token.i in token_to_spacy[j]:
                            attention[i, j] += 1.5

                # Special patterns for specific dependencies
                if spacy_token.dep_ in ['dobj', 'prep', 'aux']:
                    # Look for nearby related tokens
                    for j in range(max(0, i-3), i):
                        if token_to_spacy[j]:
                            j_spacy_idx = token_to_spacy[j][0]
                            if j_spacy_idx < len(doc):
                                j_spacy_token = doc[j_spacy_idx]
                                if j_spacy_token.dep_ in ['ROOT', 'nsubj', 'verb']:
                                    attention[i, j] += 1.0

        # Position-based attention with decay
        for j in range(i + 1):
            distance = i - j
            if distance > 0:
                attention[i, j] += 0.3 / (1 + 0.1 * distance)

        # Embedding similarity boost for related tokens
        for j in range(i + 1):
            if i != j:
                sim = _char_sim(tokens[i], tokens[j])
                if sim > 0.7:
                    attention[i, j] += 0.5 * sim

        # NEW: Enhanced attention to early structural tokens
        # This addresses the under-prediction of attention to early newlines/periods
        for j in range(min(10, i + 1)):  # Focus on first 10 positions
            is_structural = (tokens[j].strip() == '' and '\n' in tokens[j]) or tokens[j] == '.'
            if is_structural and j < 5:  # Very early structural tokens get extra boost
                attention[i, j] += 2.0
            elif is_structural:  # Other early structural tokens get moderate boost
                attention[i, j] += 1.0

        # NEW: Reduce excessive self-attention for structural tokens
        # This addresses the over-prediction of self-attention
        if tokens[i] in ['.'] or ('\n' in tokens[i] and tokens[i].strip() == ''):
            attention[i, i] *= 0.3  # Reduce self-attention for structural tokens

        # NEW: Reduce excessive attention to first token from non-early positions
        # This addresses over-prediction to position 0
        if i > 15:  # For tokens far from the beginning
            attention[i, 0] *= 0.7

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L8H3", attention



def prog_L8H30(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary attention head that focuses on periods, newlines, and structural markers."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    # Identify boundary tokens (periods, newlines, other punctuation)
    boundary_indices = []
    for i, token in enumerate(tokens):
        if token.strip() in ['.', '\n', '!', '?', ';', ':']:
            boundary_indices.append(i)

    for i in range(n):
        # Base self-attention
        attention[i, i] = 0.1

        # Strong attention to boundary tokens
        for boundary_idx in boundary_indices:
            if boundary_idx <= i:  # Causal mask
                # Closer boundaries get more attention
                distance = i - boundary_idx
                if distance == 0:
                    # Self-attention to boundary tokens
                    attention[i, boundary_idx] = 0.6
                elif distance <= 5:
                    attention[i, boundary_idx] = 0.4 / (1 + distance * 0.1)
                else:
                    attention[i, boundary_idx] = 0.2 / (1 + distance * 0.05)

        # Additional attention to first token if no boundaries found nearby
        if i > 0 and len([b for b in boundary_indices if b <= i and i - b <= 3]) == 0:
            attention[i, 0] = 0.3

        # Local attention to recent tokens
        for j in range(max(0, i-3), i):
            if j not in boundary_indices:
                attention[i, j] += 0.05 / (1 + (i - j))

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L8H30", attention



def prog_L8H31(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary detection head with strong beginning-of-sequence bias - attends strongly to periods, newlines, and especially the first token."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    # Identify punctuation and boundary tokens
    punctuation_tokens = set()
    for i, token in enumerate(tokens):
        stripped = token.strip()
        if stripped in ['.', '!', '?', '\n', ';', ':', ',']:
            punctuation_tokens.add(i)

    for i in range(n):
        # Base attention distribution
        for j in range(i + 1):  # Causal mask
            # Strong attention to punctuation marks, especially periods and newlines
            if j in punctuation_tokens:
                token_j = tokens[j].strip()
                if token_j == '.':
                    attention[i, j] = 0.4
                elif token_j == '\n':
                    attention[i, j] = 0.35
                elif token_j in ['!', '?']:
                    attention[i, j] = 0.3
                elif token_j in [';', ':', ',']:
                    attention[i, j] = 0.2
                else:
                    attention[i, j] = 0.1

            # Much stronger attention to first token, increasing with distance
            elif j == 0:
                # Strong beginning-of-sequence bias that grows with position
                if i <= 5:
                    attention[i, j] = 0.15
                elif i <= 10:
                    attention[i, j] = 0.4
                else:
                    attention[i, j] = min(0.9, 0.3 + 0.05 * i)

            # Self attention
            elif i == j:
                attention[i, j] = 0.05

            # Weak baseline attention to other tokens
            else:
                attention[i, j] = 0.02

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L8H31", attention



def prog_L8H4(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Boundary detection head with strong first-token attention - attends to sentence starts and meaningful boundaries."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    # Find all newline token positions
    newline_positions = []
    for i, token in enumerate(tokens):
        if token.strip() == '\n' or token == '\n':
            newline_positions.append(i)

    # Parse with spacy to identify sentence boundaries
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    # Identify tokens that start sentences (after true boundaries)
    sentence_start_tokens = set()
    for i, spacy_indices in enumerate(token_to_spacy):
        if spacy_indices:
            spacy_token = doc[spacy_indices[0]]
            # First token of a new sentence
            if spacy_token.is_sent_start:
                sentence_start_tokens.add(i)

    for i in range(n):
        token = tokens[i]

        # Very strong attention to the first token from all positions
        if i > 0:
            attention[i, 0] = 0.6

        # High attention to newlines only if they mark true sentence boundaries
        for nl_pos in newline_positions:
            if nl_pos <= i:  # respect causal mask
                # Check if this newline is followed by a sentence start
                is_boundary_newline = False
                if nl_pos + 1 < n and (nl_pos + 1) in sentence_start_tokens:
                    is_boundary_newline = True
                elif nl_pos == 0:  # newline at start
                    is_boundary_newline = True

                if is_boundary_newline:
                    attention[i, nl_pos] = 0.4
                else:
                    attention[i, nl_pos] = 0.1  # reduced attention to mid-sentence newlines

        # Medium attention to period tokens (sentence boundaries)
        for j in range(i + 1):
            if tokens[j].strip() == '.' or tokens[j] == '.':
                attention[i, j] = 0.15

        # Self-attention for first token
        if i == 0:
            attention[i, i] = 0.8

        # Some recency bias for recent tokens
        for j in range(max(0, i - 3), i):
            if j not in newline_positions:
                attention[i, j] += 0.05

        # Small uniform attention to all previous tokens
        for j in range(i + 1):
            attention[i, j] += 0.01

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L8H4", attention



def prog_L8H5(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """First-token and sentence boundary attention head with local context."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L8H5", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    for i in range(n):
        # Strong attention to first token
        if i > 0:
            attention[i, 0] = 0.8
        else:
            attention[i, 0] = 1.0

        # Strong attention to newline characters
        for j in range(i + 1):
            if tokens[j].strip() == '' or '\n' in tokens[j]:
                attention[i, j] += 1.5

        # Moderate attention to periods
        for j in range(i + 1):
            if '.' in tokens[j]:
                attention[i, j] += 0.8

        # Self-attention
        attention[i, i] += 0.3

        # Local context (previous few tokens)
        for j in range(max(0, i - 3), i):
            attention[i, j] += 0.2

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L8H5", attention



def prog_L8H6(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Attention head that focuses on structural boundaries like newlines and sentence endings."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention_matrix = np.zeros((n, n))

    # Find structural boundary tokens
    newline_indices = []
    period_indices = []

    for i, token in enumerate(tokens):
        if token.strip() == '\n':
            newline_indices.append(i)
        elif token.strip() in ['.', '!', '?']:
            period_indices.append(i)

    for i in range(n):
        # Base self-attention
        attention_matrix[i, i] = 0.1

        # Strong attention to newlines from all tokens
        for newline_idx in newline_indices:
            if newline_idx <= i:
                attention_matrix[i, newline_idx] = 0.4

        # Strong attention to periods from all tokens  
        for period_idx in period_indices:
            if period_idx <= i:
                attention_matrix[i, period_idx] = 0.3

        # Moderate attention to first token
        if i > 0:
            attention_matrix[i, 0] = 0.15

        # Some attention to recent tokens (recency bias)
        for j in range(max(0, i-3), i):
            if attention_matrix[i, j] == 0:  # Don't override structural attention
                attention_matrix[i, j] = 0.05 * (1.0 / (i - j + 1))

    # Apply causal mask and normalize
    attention_matrix = apply_causal_mask(attention_matrix)
    attention_matrix = make_row_stochastic(attention_matrix)

    return "prog_L8H6", attention_matrix



def prog_L8H7(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Structural boundary attention head focusing on sentence breaks, punctuation, local syntax, and sentence-initial tokens."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    # Identify sentence-initial content tokens (first non-punctuation token after boundaries)
    sentence_start_tokens = set()
    for i in range(n):
        if i == 0:
            sentence_start_tokens.add(i)
        elif i > 0 and tokens[i-1].strip() in ['.', '\n', '!', '?']:
            # Find first non-punctuation, non-whitespace token
            for j in range(i, n):
                token_j = tokens[j].strip()
                if token_j and token_j not in ['.', '!', '?', ',', ';', ':', '"', "'", '(', ')', '[', ']', ' ', '']:
                    sentence_start_tokens.add(j)
                    break

    for i in range(n):
        # Very strong self-attention for first token
        if i == 0:
            attention[i, i] = 1.0
            continue

        # Strong attention to structural markers
        for j in range(i + 1):
            token_j = tokens[j].strip()
            token_i = tokens[i].strip()

            # High attention to newlines
            if token_j == '\n':
                attention[i, j] += 0.4

            # High attention to sentence-ending punctuation
            elif token_j == '.':
                attention[i, j] += 0.35

            # Strong attention to sentence-initial content tokens
            elif j in sentence_start_tokens and j != i:
                attention[i, j] += 0.3

            # Self-attention bonus (reduced to balance over-prediction)
            elif i == j:
                attention[i, j] += 0.08

            # First token gets extra attention
            elif j == 0:
                attention[i, j] += 0.15

            # Local syntactic relationships using spacy
            if token_to_spacy[i] and token_to_spacy[j]:
                spacy_i = doc[token_to_spacy[i][0]]
                spacy_j = doc[token_to_spacy[j][0]]

                # Preposition to object relationship
                if spacy_j.pos_ == 'ADP' and spacy_i.head == spacy_j:
                    attention[i, j] += 0.2

                # Modifier relationships
                if spacy_i.head == spacy_j and j < i:
                    attention[i, j] += 0.1

                # Article to noun
                if spacy_j.pos_ == 'DET' and spacy_i.pos_ == 'NOUN' and abs(i - j) <= 3:
                    attention[i, j] += 0.15

            # Distance decay
            distance = i - j
            if distance > 0:
                attention[i, j] *= (0.9 ** min(distance, 10))

            # Small baseline attention
            attention[i, j] += 0.02

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L8H7", attention



def prog_L8H8(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary and punctuation anchor attention head with sentence-start anchoring."""
    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    # Find periods and newlines - these are key anchor points
    periods = [i for i, token in enumerate(tokens) if token.strip() == '.']
    newlines = [i for i, token in enumerate(tokens) if token.strip() == '\n']
    anchors = set(periods + newlines)

    for i in range(n):
        current_token = tokens[i].strip()

        # Self-attention baseline
        attention[i, i] = 0.1

        # Strong attention to periods and newlines
        for anchor in anchors:
            if anchor <= i:
                # Distance-based decay from anchors
                distance = i - anchor + 1
                if current_token in ['.', '\n']:
                    # Punctuation tokens attend strongly to other punctuation
                    attention[i, anchor] = 0.8 / distance
                else:
                    # Regular tokens attend to nearest anchors
                    attention[i, anchor] = 0.4 / distance

        # Additional attention to immediately previous token
        if i > 0:
            attention[i, i-1] += 0.2

        # Boost attention for punctuation tokens
        if current_token == '.':
            attention[i, i] = 0.5

        # Special case: newlines attend strongly to the most recent period
        if current_token == '\n' and periods:
            recent_periods = [p for p in periods if p < i]
            if recent_periods:
                most_recent_period = max(recent_periods)
                attention[i, most_recent_period] = 0.6

        # NEW: Strong attention to sentence-start tokens (first token and tokens after sentence boundaries)
        sentence_starts = [0]  # First token is always a sentence start
        for j in range(len(tokens)):
            token = tokens[j].strip()
            if token in ['.', '!', '?'] and j + 1 < len(tokens):
                # Next token after sentence-ending punctuation is a sentence start
                next_idx = j + 1
                # Skip whitespace tokens to find the actual content token
                while next_idx < len(tokens) and tokens[next_idx].strip() in ['', '\n']:
                    next_idx += 1
                if next_idx < len(tokens):
                    sentence_starts.append(next_idx)

        # Apply sentence-start attention
        for start_idx in sentence_starts:
            if start_idx <= i:
                distance = i - start_idx + 1
                # Strong attention to sentence starts, with distance decay
                attention[i, start_idx] = 0.8 / distance

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L8H8", attention



def prog_L8H9(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Attention head that focuses on sentence boundary markers (periods, newlines) with strong first-token fallback."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    for i in range(n):
        # Find the most recent period or newline before or at position i
        best_anchor = -1
        for j in range(i + 1):  # j <= i for causal mask
            if tokens[j].strip() in ['.', '\n']:
                best_anchor = j

        if best_anchor >= 0:
            # Strong attention to the best anchor token
            attention[i, best_anchor] = 0.7

            # Some self-attention
            attention[i, i] = 0.2

            # Distribute remaining weight to other recent tokens
            remaining_weight = 0.1
            recent_tokens = max(0, i - 5)
            for j in range(recent_tokens, i):
                if j != best_anchor:
                    attention[i, j] = remaining_weight / max(1, i - recent_tokens)
        else:
            # No anchor found - strong attention to first token with minimal self-attention
            if i > 0:
                attention[i, 0] = 0.9  # Much stronger focus on first token
                attention[i, i] = 0.1  # Minimal self-attention
            else:
                # For the first token itself, use self-attention
                attention[i, i] = 1.0

    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L8H9", attention



def prog_L9H0(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary and structure detection head - attends to newlines, periods, and sentence beginnings."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    # Find sentence boundary tokens (newlines and periods)
    boundary_tokens = []
    first_after_boundary = []

    for i, token in enumerate(tokens):
        if token.strip() == '\n':
            boundary_tokens.append(i)
            if i + 1 < n:
                first_after_boundary.append(i + 1)
        elif token.strip() == '.':
            boundary_tokens.append(i)
            if i + 1 < n:
                first_after_boundary.append(i + 1)

    # Also consider position 0 as a sentence start
    if n > 0:
        first_after_boundary.append(0)

    for i in range(n):
        # Find the most recent boundary token before position i
        recent_boundary = -1
        for b in boundary_tokens:
            if b < i:
                recent_boundary = b

        # Find the most recent sentence start at or before position i
        recent_start = -1
        for s in first_after_boundary:
            if s <= i:
                recent_start = s

        # Base attention distribution
        for j in range(i + 1):  # Causal mask
            # High attention to recent boundary tokens
            if j in boundary_tokens and (recent_boundary == -1 or j >= recent_boundary - 2):
                attention[i, j] += 0.4

            # High attention to recent sentence starts
            if j in first_after_boundary and (recent_start == -1 or j >= recent_start - 1):
                attention[i, j] += 0.3

            # Moderate self-attention
            if i == j:
                attention[i, j] += 0.1

            # Small attention to immediate previous token
            if j == i - 1:
                attention[i, j] += 0.05

            # Small baseline attention to all previous tokens
            attention[i, j] += 0.02

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L9H0", attention



def prog_L9H1(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Attention head that focuses on sentence boundaries and has strong first-token attention that increases with distance."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    # Find structural tokens: newlines, periods, and first token
    newline_indices = []
    period_indices = []

    for i, token in enumerate(tokens):
        if token.strip() == '\n':
            newline_indices.append(i)
        elif token.strip() == '.':
            period_indices.append(i)

    first_token_idx = 0

    for i in range(n):
        # Strong attention to newlines
        for nl_idx in newline_indices:
            if nl_idx <= i:
                attention[i, nl_idx] = 0.5

        # Strong attention to periods
        for period_idx in period_indices:
            if period_idx <= i:
                attention[i, period_idx] = 0.3

        # Enhanced first token attention - increases with distance
        if first_token_idx <= i:
            # Base attention increases significantly with position
            if i >= 10:
                attention[i, first_token_idx] = 0.9
            elif i >= 5:
                attention[i, first_token_idx] = 0.6
            else:
                attention[i, first_token_idx] = 0.2

        # Small amount of self-attention
        attention[i, i] = 0.05

        # Small attention to immediate previous token
        if i > 0:
            attention[i, i-1] = 0.1

        # Add some random noise to nearby tokens for diversity
        for j in range(max(0, i-3), i):
            if j not in newline_indices and j not in period_indices and j != first_token_idx:
                attention[i, j] += 0.02

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L9H1", attention



def prog_L9H10(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary and punctuation attention head with strong attention to sequence start."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L9H10", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        # Initialize with small uniform attention to all previous positions
        for j in range(i + 1):
            attention[i, j] = 0.01

        # Strong attention to newlines
        for j in range(i + 1):
            if tokens[j].strip() == '':  # newline or whitespace
                attention[i, j] += 0.35

        # Strong attention to sentence-ending punctuation
        for j in range(i + 1):
            if tokens[j] in ['.', '!', '?']:
                attention[i, j] += 0.25

        # Moderate attention to commas and other punctuation
        for j in range(i + 1):
            if tokens[j] in [',', ':', ';', '"', "'", '(', ')']:
                attention[i, j] += 0.15

        # Self-attention boost
        attention[i, i] += 0.05

        # Attention to immediate previous token
        if i > 0:
            attention[i, i-1] += 0.08

        # Strong attention to the very first token of the sequence
        if n > 0:
            attention[i, 0] += 0.5

        # Boost attention to first token of sentences
        spacy_indices = token_to_spacy[i]
        if spacy_indices:
            spacy_token = doc[spacy_indices[0]]
            # If this token starts a sentence (follows punctuation or is first)
            if (spacy_token.sent.start == spacy_token or 
                (spacy_token.i > 0 and doc[spacy_token.i-1].text in '.!?')):
                for j in range(i + 1):
                    if tokens[j].strip() and not tokens[j] in '.,!?;:':
                        attention[i, j] += 0.1

        # Boost for tokens that are semantically similar (using embedding similarity)
        for j in range(max(0, i-10), i):  # Look back up to 10 tokens
            sim = _char_sim(tokens[i], tokens[j])
            if sim > 0.7:  # High similarity threshold
                attention[i, j] += 0.1 * sim

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L9H10", attention



def prog_L9H11(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary and structure tracking head with strong first-token attention."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    # Find the first content token (skip punctuation and whitespace)
    first_content_token = 0
    for idx, token in enumerate(tokens):
        if token not in ['.', ',', '\n', '"', "'", '!', '?', ':', ';', '-', '(', ')', ' ']:
            first_content_token = idx
            break

    for i in range(n):
        token_i = tokens[i]

        # Strong attention to structural markers (periods and newlines)
        for j in range(i + 1):
            token_j = tokens[j]

            # NEW: Very strong attention to first content token from all later tokens
            if j == first_content_token and i > first_content_token:
                # Use spacy features to determine if this should be a strong connection
                if token_to_spacy[i] and token_to_spacy[j]:
                    spacy_i_indices = token_to_spacy[i]
                    spacy_j_indices = token_to_spacy[j]
                    if spacy_i_indices and spacy_j_indices:
                        spacy_i = spacy_i_indices[0]
                        spacy_j = spacy_j_indices[0]
                        if spacy_i < len(doc) and spacy_j < len(doc):
                            # Strong attention if the tokens are semantically related or if token_i is a content word
                            spacy_token_i = doc[spacy_i]
                            if spacy_token_i.pos_ in ['NOUN', 'VERB', 'ADJ', 'PRON', 'PROPN']:
                                attention[i, j] = 2.5
                            else:
                                attention[i, j] = 1.5
                else:
                    # Fallback: moderate attention to first content token
                    attention[i, j] = 1.0

            # Very high attention to periods and newlines
            elif token_j in ['.', '\n']:
                if j == 0:  # First token period/newline gets extra weight
                    attention[i, j] = 3.0
                else:
                    attention[i, j] = 2.0

            # High attention from structural tokens to themselves
            elif token_i in ['.', '\n'] and j == i:
                attention[i, j] = 2.5

            # Medium attention to tokens immediately following newlines
            elif j > 0 and tokens[j-1] == '\n':
                attention[i, j] = 1.0

            # Local syntactic attention using spacy
            elif token_to_spacy[i] and token_to_spacy[j]:
                spacy_i = token_to_spacy[i][0]
                spacy_j = token_to_spacy[j][0] 

                if spacy_i < len(doc) and spacy_j < len(doc):
                    spacy_token_i = doc[spacy_i]
                    spacy_token_j = doc[spacy_j]

                    # Modifier to head relationships
                    if spacy_token_j in spacy_token_i.children:
                        attention[i, j] = 0.8
                    elif spacy_token_i.head == spacy_token_j:
                        attention[i, j] = 0.8

            # Positional decay - earlier tokens get more attention
            distance = i - j
            if distance > 0:
                position_weight = 1.0 / (1 + distance * 0.1)
                attention[i, j] += position_weight * 0.3

            # Self-attention baseline
            if i == j:
                attention[i, j] += 0.2

            # Embedding similarity boost for related tokens
            if j < i:
                sim = _char_sim(tokens[i], tokens[j])
                if sim > 0.7:  # High similarity threshold
                    attention[i, j] += sim * 0.5

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L9H11", attention



def prog_L9H12(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary and discourse structure attention with cross-sentence discourse anchoring."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L9H12", np.zeros((n_empty, n_empty))

    attention_matrix = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    # Find sentence boundaries (newlines and periods)
    sentence_boundaries = []
    for j in range(n):
        if tokens[j] in ['\n', '.']:
            sentence_boundaries.append(j)

    for i in range(n):
        # Initialize with small uniform attention to all previous tokens
        for j in range(i + 1):
            attention_matrix[i, j] = 0.01

        # Strong attention to first token (discourse anchor)
        if i > 0:
            attention_matrix[i, 0] = 0.3

        # Very strong attention to sentence boundaries (newlines and periods)
        for j in range(i + 1):
            if tokens[j] in ['\n', '.']:
                attention_matrix[i, j] = 0.4

        # NEW: Cross-sentence discourse anchoring
        # Tokens after sentence boundaries get boosted attention to early discourse markers
        current_sentence_start = 0
        for boundary_idx in sentence_boundaries:
            if boundary_idx < i:
                current_sentence_start = boundary_idx + 1

        # If we're not in the first sentence, boost attention to discourse anchors
        if current_sentence_start > 0:
            # Strong attention to first token across sentences
            attention_matrix[i, 0] = 0.5

            # Enhanced attention to all previous sentence boundaries
            for boundary_idx in sentence_boundaries:
                if boundary_idx < i:
                    attention_matrix[i, boundary_idx] = 0.6

        # Self-attention boost
        attention_matrix[i, i] = 0.1

        # Local syntactic dependencies using spacy
        if token_to_spacy[i]:
            spacy_idx = token_to_spacy[i][0]
            if spacy_idx < len(doc):
                spacy_token = doc[spacy_idx]

                # Attend to syntactic head
                if spacy_token.head != spacy_token:
                    head_idx = spacy_token.head.i
                    # Find corresponding LM token
                    for j in range(i + 1):
                        if token_to_spacy[j] and head_idx in token_to_spacy[j]:
                            attention_matrix[i, j] += 0.15
                            break

                # Attend to direct children
                for child in spacy_token.children:
                    child_idx = child.i
                    for j in range(i + 1):
                        if token_to_spacy[j] and child_idx in token_to_spacy[j]:
                            attention_matrix[i, j] += 0.08
                            break

        # Boost attention to previous token (local context)
        if i > 0:
            attention_matrix[i, i-1] += 0.1

        # Special boost for punctuation marks
        for j in range(i + 1):
            if tokens[j] in [',', ';', ':', '!', '?', '"', "'", '-']:
                attention_matrix[i, j] += 0.05

    # Apply causal mask and normalize
    attention_matrix = apply_causal_mask(attention_matrix)
    attention_matrix = make_row_stochastic(attention_matrix)

    return "prog_L9H12", attention_matrix



def prog_L9H13(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary and first-token attention head with enhanced first-token focus."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L9H13", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    # Identify sentence boundaries and first tokens
    sentence_boundaries = set()
    first_tokens = set()

    for i, token in enumerate(tokens):
        # Mark punctuation as sentence boundaries
        if token.strip() in ['.', '!', '?', '\n']:
            sentence_boundaries.add(i)
        # Mark first token
        if i == 0:
            first_tokens.add(i)

    for i in range(n):
        token = tokens[i]

        # Strong self-attention for first tokens and boundaries
        if i in first_tokens or i in sentence_boundaries:
            attention[i, i] = 1.0

        # High attention from first token to itself
        if i == 0:
            attention[i, i] = 1.0
        else:
            # Enhanced attention to first token (much stronger than original)
            if 0 in first_tokens:
                # Strong, persistent attention to the first token
                distance = i - 0
                weight = 0.8 * np.exp(-0.02 * distance)
                attention[i, 0] = weight

            # Attention to sentence boundaries (reduced to avoid over-prediction)
            for boundary_idx in sentence_boundaries:
                if boundary_idx <= i and boundary_idx != 0:  # Don't double-count first token
                    # Distance decay from boundaries (reduced weight)
                    distance = i - boundary_idx
                    weight = 0.15 * np.exp(-0.1 * distance)
                    attention[i, boundary_idx] = weight

            # Attention to other first tokens (keep original for multi-sentence)
            for first_idx in first_tokens:
                if first_idx <= i and first_idx != 0:  # Already handled first token above
                    distance = i - first_idx
                    weight = 0.4 * np.exp(-0.05 * distance)
                    attention[i, first_idx] = weight

            # Local attention to nearby tokens
            for j in range(max(0, i-3), i):
                if j not in sentence_boundaries and j not in first_tokens:
                    distance = i - j
                    weight = 0.1 * np.exp(-0.3 * distance)
                    attention[i, j] = weight

            # Moderate self-attention
            attention[i, i] = 0.1

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L9H13", attention



def prog_L9H14(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Structural punctuation attention head with strong bias toward newlines, periods, and sentence beginning."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L9H14", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        # Find structural punctuation tokens (newlines and periods)
        newline_positions = [j for j in range(i + 1) if tokens[j].strip() == '']
        period_positions = [j for j in range(i + 1) if tokens[j] == '.']

        # Strong attention to newlines
        for j in newline_positions:
            attention[i, j] += 5.0

        # Strong attention to periods  
        for j in period_positions:
            attention[i, j] += 3.0

        # Self-attention
        attention[i, i] += 1.0

        # Local syntactic attention - attend to previous few tokens
        for j in range(max(0, i - 3), i):
            attention[i, j] += 0.5

        # Very strong attention to first token - much stronger than original
        if i > 0:
            attention[i, 0] += 6.0

        # Attend to tokens with similar POS tags
        if token_to_spacy[i]:
            spacy_i = token_to_spacy[i][0]
            if spacy_i < len(doc):
                pos_i = doc[spacy_i].pos_
                for j in range(i + 1):
                    if token_to_spacy[j]:
                        spacy_j = token_to_spacy[j][0]
                        if spacy_j < len(doc) and doc[spacy_j].pos_ == pos_i:
                            attention[i, j] += 0.3

        # Boost attention to semantically similar tokens
        for j in range(i + 1):
            sim = _char_sim(tokens[i], tokens[j])
            if sim > 0.7:
                attention[i, j] += sim * 0.5

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L9H14", attention



def prog_L9H15(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Structural anchor head: attends to sentence boundaries and first tokens with local syntax."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L9H15", np.zeros((n_empty, n_empty))

    attention_matrix = np.zeros((n, n))

    # Get spacy alignment for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    # Identify special tokens
    first_token_idx = 0
    period_indices = []
    newline_indices = []

    for i, token in enumerate(tokens):
        if token.strip() == '.':
            period_indices.append(i)
        elif token.strip() == '\n':
            newline_indices.append(i)

    for i in range(n):
        # Base attention distribution
        base_attention = np.zeros(n)

        # Strong attention to first token from most positions
        if first_token_idx < i:
            base_attention[first_token_idx] = 0.3

        # Strong attention to periods from most positions  
        for period_idx in period_indices:
            if period_idx < i:
                base_attention[period_idx] += 0.25

        # Strong attention to newlines, especially from tokens after sentence boundaries
        for newline_idx in newline_indices:
            if newline_idx < i:
                # Higher weight if this token appears to be at start of new sentence
                distance_from_newline = i - newline_idx
                if distance_from_newline <= 5:  # Close to newline
                    base_attention[newline_idx] += 0.4 - 0.05 * distance_from_newline
                else:
                    base_attention[newline_idx] += 0.15

        # Self-attention
        base_attention[i] = 0.1

        # Local syntactic patterns using spacy
        if token_to_spacy[i]:
            spacy_token = doc[token_to_spacy[i][0]]

            # Attend to syntactic head
            if spacy_token.head != spacy_token and spacy_token.head.i < len(doc):
                for j in range(i):
                    if j < len(token_to_spacy) and token_to_spacy[j]:
                        if any(spacy_idx == spacy_token.head.i for spacy_idx in token_to_spacy[j]):
                            base_attention[j] += 0.15

            # Prepositions attend to their objects
            if spacy_token.pos_ == 'ADP':
                for child in spacy_token.children:
                    if child.dep_ == 'pobj':
                        for j in range(i):
                            if j < len(token_to_spacy) and token_to_spacy[j]:
                                if any(spacy_idx == child.i for spacy_idx in token_to_spacy[j]):
                                    base_attention[j] += 0.2

            # Attend to previous token with moderate weight
            if i > 0:
                base_attention[i-1] += 0.1

        # Add small amount of embedding similarity for nearby tokens
        for j in range(max(0, i-3), i):
            sim = _char_sim(tokens[i], tokens[j])
            if sim > 0.3:
                base_attention[j] += 0.05 * sim

        # Normalize and store
        attention_matrix[i] = base_attention

    # Apply causal mask and normalize
    attention_matrix = apply_causal_mask(attention_matrix)
    attention_matrix = make_row_stochastic(attention_matrix)

    return "prog_L9H15", attention_matrix



def prog_L9H16(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary and document structure attention with enhanced first-token focus across sentences."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L9H16", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        token = tokens[i]

        # Strong attention to newlines and periods (sentence boundaries)
        for j in range(i + 1):
            if tokens[j] in ['\n', '.', '!', '?']:
                if tokens[j] == '\n':
                    # Reduce newline attention for distant tokens
                    distance = i - j
                    if distance > 10:
                        attention[i, j] += 0.2  # Reduced from 0.4
                    else:
                        attention[i, j] += 0.4
                else:  # periods and other sentence enders
                    attention[i, j] += 0.3

        # Enhanced first token attention - stronger for tokens after sentence boundaries
        if n > 0:
            base_first_token_attention = 0.15
            # Check if token i comes after a newline (indicating start of new sentence/paragraph)
            crosses_newline = False
            for k in range(i):
                if tokens[k] == '\n':
                    crosses_newline = True
                    break

            if crosses_newline:
                attention[i, 0] += 0.25  # Boosted attention to first token
            else:
                attention[i, 0] += base_first_token_attention

        # Moderate self-attention
        attention[i, i] += 0.1

        # Local syntactic attention using spacy
        if token_to_spacy[i]:
            spacy_idx = token_to_spacy[i][0]
            if spacy_idx < len(doc):
                spacy_token = doc[spacy_idx]

                # Attend to syntactic head
                if spacy_token.head != spacy_token:
                    head_token_idx = None
                    for k in range(i):
                        if token_to_spacy[k] and spacy_token.head.i in token_to_spacy[k]:
                            head_token_idx = k
                            break
                    if head_token_idx is not None:
                        attention[i, head_token_idx] += 0.08

                # Attend to direct children
                for child in spacy_token.children:
                    child_token_idx = None
                    for k in range(i):
                        if token_to_spacy[k] and child.i in token_to_spacy[k]:
                            child_token_idx = k
                            break
                    if child_token_idx is not None:
                        attention[i, child_token_idx] += 0.06

        # Previous token attention with recency bias
        if i > 0:
            attention[i, i-1] += 0.08
        if i > 1:
            attention[i, i-2] += 0.04

        # Semantic similarity attention for nearby tokens
        for j in range(max(0, i-5), i):
            if i != j:
                sim = _char_sim(tokens[i], tokens[j])
                if sim > 0.7:  # High similarity threshold
                    attention[i, j] += 0.05 * sim

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L9H16", attention



def prog_L9H17(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Attends primarily to structural markers (newlines, periods) with strong first-token attention."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L9H17", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        for j in range(i + 1):  # causal mask
            weight = 0.0

            # Very high attention to newlines
            if tokens[j] == '\n':
                weight += 0.3

            # High attention to periods
            elif tokens[j] == '.':
                weight += 0.2

            # Moderate attention based on semantic similarity
            sim = _char_sim(tokens[i], tokens[j])
            if sim > 0.5:
                weight += 0.1 * sim

            # Self-attention baseline
            if i == j:
                weight += 0.05

            # Small attention to recent tokens
            if i - j <= 3 and i != j:
                weight += 0.02 * (4 - (i - j)) / 4

            # Boost for first token - significantly increased
            if j == 0:
                weight += 0.15  # Increased from 0.03 to handle strong first-token attention

            # Additional boost for commas and quotes
            if tokens[j] in [',', '"', "'", '."']:
                weight += 0.05

            attention[i, j] = weight

    # Normalize and apply causal mask
    attention = make_row_stochastic(attention)
    attention = apply_causal_mask(attention)

    return "prog_L9H17", attention



def prog_L9H18(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary and discourse structure head - attends to newlines, periods, and structural markers."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        token = tokens[i]

        # Very high attention to newlines
        for j in range(i + 1):
            if tokens[j] == '\n':
                attention[i, j] += 0.4

        # High attention to sentence-ending punctuation
        for j in range(i + 1):
            if tokens[j] in ['.', '!', '?']:
                attention[i, j] += 0.25

        # Self-attention for punctuation and newlines
        if token in ['.', '!', '?', '\n', ',']:
            attention[i, i] += 0.3

        # Attention to coordinating conjunctions and discourse markers
        for j in range(i + 1):
            if j in token_to_spacy[j if j < len(token_to_spacy) else -1]:
                spacy_indices = token_to_spacy[j]
                for spacy_idx in spacy_indices:
                    if spacy_idx < len(doc):
                        spacy_token = doc[spacy_idx]
                        if spacy_token.pos_ == 'CCONJ' or spacy_token.text.lower() in ['but', 'and', 'or']:
                            attention[i, j] += 0.15

        # Some attention to nearby previous tokens (recency)
        for j in range(max(0, i-3), i):
            attention[i, j] += 0.05 * (1 + j - max(0, i-3))

        # Moderate attention to sentence starters
        for j in range(i + 1):
            if j < len(token_to_spacy):
                spacy_indices = token_to_spacy[j]
                for spacy_idx in spacy_indices:
                    if spacy_idx < len(doc):
                        spacy_token = doc[spacy_idx]
                        if spacy_token.is_sent_start:
                            attention[i, j] += 0.1

        # Boost attention from certain token types to structural elements
        if i < len(token_to_spacy):
            spacy_indices = token_to_spacy[i]
            for spacy_idx in spacy_indices:
                if spacy_idx < len(doc):
                    spacy_token = doc[spacy_idx]
                    if spacy_token.pos_ in ['VERB', 'NOUN', 'PRON']:
                        # These content words pay extra attention to boundaries
                        for j in range(i + 1):
                            if tokens[j] in ['\n', '.', '!', '?']:
                                attention[i, j] += 0.1

        # Small uniform attention to all previous tokens
        for j in range(i + 1):
            attention[i, j] += 0.01

    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)
    return "prog_L9H18", attention



def prog_L9H19(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Discourse boundary attention with semantic similarity and positional bias."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        return "prog_L9H19", np.zeros((0, 0))

    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    # Identify sentence/paragraph boundaries
    boundary_tokens = set()
    first_tokens = set()

    for i, token in enumerate(tokens):
        # Boundary tokens: newlines, periods, sentence starts
        if token.strip() in ['.', '\n'] or (i == 0):
            boundary_tokens.add(i)

        # Find first token after boundaries
        if i > 0 and tokens[i-1].strip() in ['.', '\n']:
            first_tokens.add(i)
        if i == 0:
            first_tokens.add(i)

    for i in range(n):
        for j in range(i + 1):  # Causal mask
            weight = 0.0

            # Strong attention to boundary tokens (periods, newlines)
            if j in boundary_tokens:
                if tokens[j].strip() == '\n':
                    weight += 0.35
                elif tokens[j].strip() == '.':
                    weight += 0.30

            # Strong attention from tokens to first tokens of sentences
            if j in first_tokens and i != j:
                weight += 0.25

            # Self-attention, especially for boundary tokens
            if i == j:
                if i in boundary_tokens:
                    weight += 0.35
                else:
                    weight += 0.02

            # Semantic similarity component
            if i != j:
                sim = _char_sim(tokens[i], tokens[j])
                if sim > 0.5:
                    weight += 0.15 * sim

            # Positional bias - prefer recent tokens
            if i != j:
                distance = i - j
                if distance <= 3:
                    weight += 0.05 * (4 - distance) / 4

            # Special attention patterns for specific linguistic contexts
            if i < len(token_to_spacy) and j < len(token_to_spacy):
                if token_to_spacy[i] and token_to_spacy[j]:
                    spacy_i = doc[token_to_spacy[i][0]]
                    spacy_j = doc[token_to_spacy[j][0]]

                    # Attention between pronouns and their antecedents
                    if spacy_i.pos_ == 'PRON' and spacy_j.pos_ in ['NOUN', 'PROPN']:
                        weight += 0.08

                    # Attention from verbs to their subjects/objects
                    if spacy_i.pos_ == 'VERB' and spacy_j.dep_ in ['nsubj', 'dobj']:
                        weight += 0.06

            attention[i, j] = weight

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L9H19", attention



def prog_L9H2(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Structural boundary detection head with global attention to initial punctuation markers."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L9H2", np.zeros((n_empty, n_empty))

    attention_matrix = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        token = tokens[i]

        # Strong self-attention for first tokens and important punctuation
        if i == 0 or token.strip() in ['.', '\n', '!', '?']:
            attention_matrix[i, i] = 0.8

        # High attention to structural punctuation
        for j in range(i + 1):
            target_token = tokens[j]

            # Very high attention to periods and newlines
            if target_token.strip() in ['.', '\n']:
                # Especially strong from tokens near sentence boundaries
                if i > j and (i - j) < 20:  # Within reasonable distance
                    attention_matrix[i, j] += 0.4 * (1.0 / (1 + 0.1 * (i - j)))

            # Moderate attention to other punctuation
            elif target_token.strip() in [',', '!', '?', ';', ':']:
                if i > j and (i - j) < 10:
                    attention_matrix[i, j] += 0.1 * (1.0 / (1 + 0.2 * (i - j)))

        # Special case: Global attention to initial structural markers
        if i > 2:  # Only for tokens beyond the first few positions
            for j in range(min(3, i)):  # Look at first 3 tokens
                target_token = tokens[j]
                # Strong global attention to initial commas and newlines
                if target_token.strip() in [',', '\n']:
                    # Add significant attention regardless of distance
                    attention_matrix[i, j] += 0.3 * (1.0 / (1 + 0.05 * (i - j)))

        # Content word relationships using spacy
        if token_to_spacy[i]:
            spacy_token = doc[token_to_spacy[i][0]]

            # Attention to syntactic heads and dependencies
            for j in range(i):
                if token_to_spacy[j]:
                    target_spacy = doc[token_to_spacy[j][0]]

                    # Attention between syntactically related words
                    if (target_spacy == spacy_token.head or 
                        spacy_token == target_spacy.head or
                        target_spacy.head == spacy_token.head):
                        attention_matrix[i, j] += 0.1

                    # Semantic similarity boost
                    sim = _char_sim(tokens[i], tokens[j])
                    if sim > 0.7:
                        attention_matrix[i, j] += 0.05 * sim

        # Recency bias - slight attention to recent tokens
        for j in range(max(0, i - 5), i):
            if tokens[j].strip() not in ['.', '\n', ',']:
                attention_matrix[i, j] += 0.02 * (1.0 / (1 + (i - j)))

    # Apply causal mask and normalize
    attention_matrix = apply_causal_mask(attention_matrix)
    attention_matrix = make_row_stochastic(attention_matrix)

    return "prog_L9H2", attention_matrix



def prog_L9H20(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Attention head that focuses on sentence boundaries and semantically related tokens within local contexts, with strong beginning-of-sequence attention."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        for j in range(i + 1):  # Causal mask
            weight = 0.0

            # Strong attention to sentence-ending punctuation and line breaks
            if tokens[j] in ['.', '!', '?']:
                weight += 0.15
            elif tokens[j] == '\n':
                weight += 0.20

            # Self-attention baseline
            if i == j:
                weight += 0.02

            # First token attention - significantly boosted based on distance
            if j == 0:
                weight += 0.05
                # Add strong additional boost for distant tokens attending to position 0
                distance = i - j
                if distance > 10:
                    weight += 0.25
                elif distance > 5:
                    weight += 0.15
                elif distance > 2:
                    weight += 0.08

            # Semantic similarity boost for nearby tokens
            if abs(i - j) <= 10 and i != j:
                sim = _char_sim(tokens[i], tokens[j])
                if sim > 0.3:
                    weight += sim * 0.08

            # Syntactic relationships via spacy
            if token_to_spacy[i] and token_to_spacy[j]:
                spacy_i_indices = token_to_spacy[i]
                spacy_j_indices = token_to_spacy[j]

                for si in spacy_i_indices:
                    for sj in spacy_j_indices:
                        if si < len(doc) and sj < len(doc):
                            spacy_i_tok = doc[si]
                            spacy_j_tok = doc[sj]

                            # Head-dependent relationships
                            if spacy_i_tok.head == spacy_j_tok or spacy_j_tok.head == spacy_i_tok:
                                weight += 0.04

                            # Same sentence boost
                            if spacy_i_tok.sent == spacy_j_tok.sent and abs(i - j) > 1:
                                weight += 0.02

            # Distance decay
            distance = i - j
            if distance > 0:
                weight *= (0.95 ** distance)

            # Special boost for recent tokens (1-3 positions back)
            if 1 <= distance <= 3:
                weight += 0.03

            attention[i, j] = weight

    # Normalize and apply causal mask
    attention = make_row_stochastic(attention)
    attention = apply_causal_mask(attention)

    return "prog_L9H20", attention



def prog_L9H21(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Discourse boundary attention: attends to sentence boundaries and beginnings."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L9H21", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Identify boundary tokens (periods, newlines, first token)
    boundary_tokens = set()
    sentence_start_tokens = set()

    # First token is always a sentence start
    if n > 0:
        sentence_start_tokens.add(0)
        boundary_tokens.add(0)

    for i in range(n):
        token = tokens[i].strip()

        # Mark periods and newlines as boundaries
        if token in ['.', '\n']:
            boundary_tokens.add(i)

        # Mark tokens after periods/newlines as sentence starts
        if i > 0:
            prev_token = tokens[i-1].strip()
            if prev_token in ['.', '\n']:
                sentence_start_tokens.add(i)
                boundary_tokens.add(i)

    for i in range(n):
        # Base attention pattern
        for j in range(i + 1):  # Causal mask
            if j in boundary_tokens:
                # Strong attention to boundary tokens
                if tokens[j].strip() == '\n':
                    attention[i, j] = 0.25
                elif tokens[j].strip() == '.':
                    attention[i, j] = 0.2
                elif j in sentence_start_tokens:
                    # Reduce attention to tokens after boundaries - they're getting too much
                    attention[i, j] = 0.08
                else:
                    attention[i, j] = 0.1
            else:
                # Lower baseline attention
                attention[i, j] = 0.02

        # Self-attention boost
        attention[i, i] = max(attention[i, i], 0.05)

        # Extra boost for attending to most recent boundary
        most_recent_boundary = -1
        for j in range(i, -1, -1):
            if j in boundary_tokens:
                most_recent_boundary = j
                break

        if most_recent_boundary >= 0:
            # Don't boost sentence start tokens as much
            if most_recent_boundary in sentence_start_tokens and tokens[most_recent_boundary].strip() not in ['.', '\n']:
                attention[i, most_recent_boundary] *= 1.2
            else:
                attention[i, most_recent_boundary] *= 1.5

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L9H21", attention



def prog_L9H22(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Attention head that focuses on structural boundaries with distance-based first-token attention."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention_matrix = np.zeros((n, n))

    # Find structural boundary tokens
    newline_indices = []
    sentence_end_indices = []
    first_token_idx = 0

    for i, token in enumerate(tokens):
        if token.strip() == '\n':
            newline_indices.append(i)
        elif token.strip() in ['.', '!', '?']:
            sentence_end_indices.append(i)

    for i in range(n):
        # Base attention distribution
        attention_weights = np.zeros(n)

        # Strong attention to newlines
        for nl_idx in newline_indices:
            if nl_idx <= i:
                attention_weights[nl_idx] = 0.4

        # Strong attention to sentence endings
        for se_idx in sentence_end_indices:
            if se_idx <= i:
                attention_weights[se_idx] = 0.3

        # Distance-based attention to first token - stronger for tokens further away
        if i > 0:
            # Scale first token attention based on position (0.2 to 0.8 range)
            first_token_weight = 0.2 + (i / n) * 0.6
            attention_weights[first_token_idx] = first_token_weight
        else:
            attention_weights[first_token_idx] = 0.2

        # Reduced self-attention for better balance
        attention_weights[i] = 0.10

        # Moderate attention to immediately preceding token
        if i > 0:
            attention_weights[i-1] = 0.08

        # Small uniform attention to other tokens
        for j in range(i + 1):
            if attention_weights[j] == 0:
                attention_weights[j] = 0.01

        # Boost attention if current token is at a boundary
        current_token = tokens[i].strip()
        if current_token == '\n':
            # Newlines attend strongly to previous structural elements
            for nl_idx in newline_indices:
                if nl_idx < i:
                    attention_weights[nl_idx] *= 1.5
            for se_idx in sentence_end_indices:
                if se_idx < i:
                    attention_weights[se_idx] *= 1.2
        elif current_token in ['.', '!', '?']:
            # Sentence endings attend to newlines and first token
            for nl_idx in newline_indices:
                if nl_idx <= i:
                    attention_weights[nl_idx] *= 1.3
            attention_weights[first_token_idx] *= 1.2

        attention_matrix[i] = attention_weights

    # Apply causal mask and normalize
    attention_matrix = apply_causal_mask(attention_matrix)
    attention_matrix = make_row_stochastic(attention_matrix)

    return "prog_L9H22", attention_matrix



def prog_L9H23(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Structural boundary attention with strong beginning-of-sequence focus."""
    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L9H23", np.zeros((n_empty, n_empty))

    # Initialize attention matrix
    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    # Identify boundary tokens (punctuation, newlines, whitespace)
    boundary_tokens = set()
    for i, token in enumerate(tokens):
        if token.strip() in ['.', ',', '!', '?', ';', ':', '\n'] or token.isspace():
            boundary_tokens.add(i)

    # Find first non-boundary token (often gets high attention)
    first_content_token = 0
    for i, token in enumerate(tokens):
        if not (token.isspace() or token.strip() in ['.', ',', '!', '?', ';', ':']):
            first_content_token = i
            break

    for i in range(n):
        for j in range(i + 1):  # Causal mask
            weight = 0.0

            # Base self-attention
            if i == j:
                weight += 0.05

            # Strong attention to boundary tokens (especially newlines and periods)
            if j in boundary_tokens:
                if tokens[j] == '\n':
                    weight += 0.25
                elif tokens[j].strip() in ['.', ',']:
                    weight += 0.15

            # ENHANCED: Much stronger attention to first content token
            if j == first_content_token and i != j:
                # Strong baseline attention to first content token
                weight += 0.4

                # Additional boost for tokens far from the beginning
                distance = i - j
                if distance > 10:
                    weight += 0.3
                elif distance > 5:
                    weight += 0.2

            # Semantic similarity boost
            if i != j:
                sim = _char_sim(tokens[i], tokens[j])
                if sim > 0.7:
                    weight += 0.15 * sim
                elif sim > 0.5:
                    weight += 0.08 * sim

            # Adjacent token attention (especially for compound words/phrases)
            if abs(i - j) == 1:
                weight += 0.05

            # Syntactic relationships using spacy
            if token_to_spacy[i] and token_to_spacy[j]:
                spacy_i = token_to_spacy[i][0] if token_to_spacy[i] else None
                spacy_j = token_to_spacy[j][0] if token_to_spacy[j] else None

                if spacy_i is not None and spacy_j is not None:
                    spacy_token_i = doc[spacy_i]
                    spacy_token_j = doc[spacy_j]

                    # Head-dependent relationships
                    if spacy_token_i.head == spacy_token_j or spacy_token_j.head == spacy_token_i:
                        weight += 0.1

                    # Modifier relationships
                    if spacy_token_j.dep_ in ['amod', 'nmod', 'compound'] and spacy_token_j.head == spacy_token_i:
                        weight += 0.08

            # Distance decay for non-boundary tokens (but not for first content token)
            if j not in boundary_tokens and i != j and j != first_content_token:
                distance = i - j
                decay = 1.0 / (1.0 + 0.1 * distance)
                weight *= decay

            # Special boost for certain patterns
            # Pronouns attending to previous nouns
            if token_to_spacy[i] and token_to_spacy[j]:
                spacy_i_idx = token_to_spacy[i][0] if token_to_spacy[i] else None
                spacy_j_idx = token_to_spacy[j][0] if token_to_spacy[j] else None

                if spacy_i_idx is not None and spacy_j_idx is not None:
                    spacy_i_token = doc[spacy_i_idx]
                    spacy_j_token = doc[spacy_j_idx]

                    if spacy_i_token.pos_ == 'PRON' and spacy_j_token.pos_ in ['NOUN', 'PROPN']:
                        weight += 0.06

            attention[i, j] = weight

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L9H23", attention



def prog_L9H24(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Structural boundary detection head focusing on sentence breaks and punctuation."""
    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L9H24", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    alignment = _align_to_spacy(sentence, tokens)

    for i in range(n):
        token = tokens[i]

        # Strong self-attention for first token
        if i == 0:
            attention[i, i] = 1.0
            continue

        # High attention to structural markers
        for j in range(i + 1):
            target_token = tokens[j]

            # Very high attention to newlines and periods
            if target_token.strip() in ['\n', '.']:
                attention[i, j] += 0.3

            # High attention to first token
            if j == 0:
                attention[i, j] += 0.2

            # Attention to sentence boundaries
            if alignment[j]:
                spacy_idx = alignment[j][0]
                if spacy_idx < len(doc):
                    spacy_token = doc[spacy_idx]

                    # Sentence start tokens
                    if spacy_token.is_sent_start:
                        attention[i, j] += 0.15

                    # Punctuation marks
                    if spacy_token.pos_ == 'PUNCT':
                        attention[i, j] += 0.1

            # Positional decay - prefer earlier tokens
            position_weight = 0.05 / (i - j + 1)
            attention[i, j] += position_weight

            # Small self-attention
            if i == j:
                attention[i, j] += 0.05

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L9H24", attention



def prog_L9H25(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Discourse boundary detection with local semantic clustering around sentence breaks, plus strong attention to sentence-initial tokens."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L9H25", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Identify discourse boundary tokens (newlines and sentence-ending punctuation)
    boundary_tokens = set()
    for i, token in enumerate(tokens):
        if token.strip() in ['\n', '.', '!', '?']:
            boundary_tokens.add(i)

    for i in range(n):
        # Base self-attention
        attention[i, i] = 0.3

        # Strong attention to discourse boundaries
        for boundary_idx in boundary_tokens:
            if boundary_idx <= i:
                # Distance decay for boundaries
                distance = i - boundary_idx
                if distance == 0:
                    attention[i, boundary_idx] += 0.6
                elif distance <= 3:
                    attention[i, boundary_idx] += 0.4 / (distance + 1)
                else:
                    attention[i, boundary_idx] += 0.2 / (distance + 1)

        # Local semantic similarity attention
        for j in range(max(0, i-5), i):
            if j not in boundary_tokens:
                sim = _char_sim(tokens[i], tokens[j])
                if sim > 0.5:
                    attention[i, j] += 0.3 * sim
                elif sim > 0.3:
                    attention[i, j] += 0.15 * sim

        # Recency bias for recent non-boundary tokens
        for j in range(max(0, i-3), i):
            if j not in boundary_tokens:
                distance = i - j
                attention[i, j] += 0.1 / distance

        # Special boost for immediately previous token
        if i > 0:
            attention[i, i-1] += 0.2

        # NEW: Strong attention to sentence-initial token (first token)
        if i > 0:
            # Strong base attention to the very first token
            attention[i, 0] += 0.4
            # Additional decay based on distance from start
            if i <= 10:
                attention[i, 0] += 0.3 / (i + 1)
            else:
                attention[i, 0] += 0.1 / (i + 1)

    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L9H25", attention



def prog_L9H26(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Structural and syntactic attention head with strong attention to sequence beginning."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L9H26", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    # Identify structural tokens (punctuation, whitespace)
    structural_tokens = []
    first_tokens = []

    for i, token in enumerate(tokens):
        if token.strip() in ['.',  '!', '?', '\n']:
            structural_tokens.append(i)
        # First token or token after newline
        if i == 0 or (i > 0 and tokens[i-1].strip() == '\n'):
            first_tokens.append(i)

    for i in range(n):
        # Base uniform attention to avoid zeros
        for j in range(i + 1):
            attention[i, j] = 0.01

        # Strong attention to structural tokens (periods, newlines)
        for struct_idx in structural_tokens:
            if struct_idx <= i:
                attention[i, struct_idx] += 0.3

        # Attention to first tokens
        for first_idx in first_tokens:
            if first_idx <= i:
                attention[i, first_idx] += 0.2

        # NEW: Strong attention to the very first token of the sequence
        if i > 0:
            attention[i, 0] += 0.4

        # Syntactic attention based on spacy dependencies
        if token_to_spacy[i]:
            spacy_idx = token_to_spacy[i][0]
            if spacy_idx < len(doc):
                spacy_token = doc[spacy_idx]

                # Attention to syntactic head
                if spacy_token.head != spacy_token:
                    head_token = spacy_token.head
                    # Find corresponding LM token
                    for j in range(i + 1):
                        if token_to_spacy[j]:
                            for spacy_j in token_to_spacy[j]:
                                if spacy_j < len(doc) and doc[spacy_j] == head_token:
                                    attention[i, j] += 0.25

                # Attention to syntactic children
                for child in spacy_token.children:
                    for j in range(i + 1):
                        if token_to_spacy[j]:
                            for spacy_j in token_to_spacy[j]:
                                if spacy_j < len(doc) and doc[spacy_j] == child:
                                    attention[i, j] += 0.15

        # Previous token attention (local context)
        if i > 0:
            attention[i, i-1] += 0.1

        # Self-attention
        attention[i, i] += 0.05

        # Semantic similarity boost
        for j in range(i):
            sim = _char_sim(tokens[i], tokens[j])
            if sim > 0.5:
                attention[i, j] += 0.1 * sim

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L9H26", attention



def prog_L9H27(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary attention head with strong first-token focus."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L9H27", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        for j in range(i + 1):  # Causal mask
            weight = 0.0

            # Very high attention to sentence boundaries (periods and newlines)
            if tokens[j] == '.' or tokens[j] == '\n':
                weight += 0.25

            # High attention to first tokens of sentences
            # Check if j is right after a newline or at the very beginning
            if j == 0 or (j > 0 and tokens[j-1] == '\n'):
                weight += 0.15

            # NEW: Much stronger attention to the very first token (index 0)
            # This pattern was severely under-predicted in failure cases
            if j == 0:
                weight += 0.35

            # Moderate self-attention
            if i == j:
                weight += 0.05

            # Additional boost for punctuation in general
            if tokens[j] in ['.', ',', '!', '?', '\n']:
                weight += 0.08

            # Small boost for function words and common content words
            spacy_indices = token_to_spacy[j]
            if spacy_indices:
                spacy_token = doc[spacy_indices[0]]
                if spacy_token.pos_ in ['DET', 'PRON', 'ADP', 'CONJ', 'SCONJ']:
                    weight += 0.02
                elif spacy_token.pos_ in ['NOUN', 'VERB', 'ADJ']:
                    weight += 0.01

            # Small recency bias - prefer more recent tokens
            distance = i - j
            if distance <= 5:
                weight += 0.01 * (6 - distance) / 6

            attention[i, j] = weight

    # Add small baseline to prevent zero rows
    attention += 0.001

    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L9H27", attention



def prog_L9H28(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary and structure attention head focusing on periods, newlines, and first tokens."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    alignment = _align_to_spacy(sentence, tokens)

    # Identify sentence boundaries and first tokens
    sentence_starts = set()
    sentence_ends = set()

    for i, token in enumerate(tokens):
        # Sentence ending punctuation
        if token.strip() in ['.', '!', '?']:
            sentence_ends.add(i)
        # Newlines often mark sentence boundaries
        elif token.strip() == '\n':
            sentence_ends.add(i)
            if i + 1 < n:
                sentence_starts.add(i + 1)

    # First token is always a sentence start
    if n > 0:
        sentence_starts.add(0)

    # Find sentence starts by looking for tokens after sentence ends
    for end_idx in sentence_ends:
        if end_idx + 1 < n:
            sentence_starts.add(end_idx + 1)

    for i in range(n):
        token = tokens[i].strip()

        # High attention to sentence boundaries
        for j in range(i + 1):  # Causal mask
            target_token = tokens[j].strip()

            # Very high attention to sentence-ending punctuation
            if target_token in ['.', '!', '?']:
                attention[i, j] = 0.4

            # High attention to newlines (sentence boundaries)
            elif target_token == '\n':
                attention[i, j] = 0.35

            # High attention to first tokens of sentences
            elif j in sentence_starts:
                attention[i, j] = 0.3

            # Medium attention to previous token (local context)
            elif j == i - 1:
                attention[i, j] = 0.1

            # Self-attention baseline
            elif i == j:
                attention[i, j] = 0.05

            # Lower attention with distance decay
            else:
                distance = i - j
                if distance <= 5:
                    attention[i, j] = 0.02 / (1 + distance * 0.5)
                else:
                    attention[i, j] = 0.01 / (1 + distance * 0.2)

        # Boost attention for syntactic relationships using spacy
        if alignment[i]:
            spacy_idx = alignment[i][0]
            if spacy_idx < len(doc):
                spacy_token = doc[spacy_idx]

                # Attend to syntactic head
                if spacy_token.head != spacy_token:
                    head_spacy_idx = spacy_token.head.i
                    for j in range(i + 1):
                        if alignment[j] and head_spacy_idx in alignment[j]:
                            attention[i, j] *= 1.5

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L9H28", attention



def prog_L9H29(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Attention head that combines first-token bias with syntactic dependencies and recency."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L9H29", np.zeros((n_empty, n_empty))

    # Initialize attention matrix
    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        # Strong bias toward first token (start of sequence)
        if n > 0:
            attention[i, 0] = 3.0

        # Self-attention
        attention[i, i] = 1.0

        # Find newline tokens and give them high attention
        for j in range(i + 1):
            if tokens[j].strip() == '' and '\n' in tokens[j]:
                attention[i, j] += 2.0

        # Sentence boundary tokens (periods, exclamation marks)
        for j in range(i + 1):
            if tokens[j].strip() in ['.', '!', '?']:
                attention[i, j] += 1.5

        # Get spacy tokens for current position
        spacy_indices = token_to_spacy[i]
        if spacy_indices:
            current_spacy = doc[spacy_indices[0]]

            # Syntactic dependencies - attend to head
            if current_spacy.head != current_spacy:
                head_token = current_spacy.head
                for j in range(i + 1):
                    if token_to_spacy[j] and head_token.i in [doc[k].i for k in token_to_spacy[j]]:
                        attention[i, j] += 1.0

            # Special patterns for specific POS tags
            if current_spacy.pos_ in ['VERB', 'AUX']:
                # Verbs attend to their subjects
                for child in current_spacy.children:
                    if child.dep_ in ['nsubj', 'nsubjpass']:
                        for j in range(i + 1):
                            if token_to_spacy[j] and child.i in [doc[k].i for k in token_to_spacy[j]]:
                                attention[i, j] += 1.2

            if current_spacy.pos_ in ['NOUN', 'PROPN']:
                # Nouns attend to their modifiers
                for j in range(i + 1):
                    if token_to_spacy[j]:
                        other_spacy = doc[token_to_spacy[j][0]]
                        if other_spacy.dep_ in ['amod', 'det'] and other_spacy.head == current_spacy:
                            attention[i, j] += 0.8

        # Recency bias - prefer recent tokens
        for j in range(max(0, i - 5), i):
            distance = i - j
            recency_weight = 1.0 / (distance + 1)
            attention[i, j] += recency_weight * 0.3

        # Semantic similarity boost
        for j in range(i):
            sim = _char_sim(tokens[i], tokens[j])
            if sim > 0.7:  # High similarity
                attention[i, j] += 0.5

        # Special handling for punctuation attending to content
        if tokens[i].strip() in [',', ';', ':']:
            # Commas attend to recent content words
            for j in range(max(0, i - 3), i):
                spacy_j = token_to_spacy[j]
                if spacy_j and doc[spacy_j[0]].pos_ in ['NOUN', 'VERB', 'ADJ']:
                    attention[i, j] += 0.8

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L9H29", attention



def prog_L9H3(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Adjacent token attention with semantic similarity, sentence boundary detection, and strong punctuation-to-preceding-word attention."""
    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L9H3", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        # Strong self-attention for first token
        if i == 0:
            attention[i, i] = 1.0
            continue

        # Base attention to previous token
        attention[i, i-1] = 0.5

        # Self-attention
        attention[i, i] = 0.1

        # Strong punctuation-to-preceding-word attention
        if i > 0 and tokens[i] in [',', '.', '!', '?', ':', ';', '"', "'", ')', ']', '}']:
            attention[i, i-1] += 0.4  # Boost attention to immediately preceding token

        # Look for sentence boundaries (periods, newlines)
        for j in range(i):
            if tokens[j] in ['.', '\n']:
                attention[i, j] += 0.3

        # Semantic similarity component
        for j in range(i):
            sim = _char_sim(tokens[i], tokens[j])
            if sim > 0.3:  # Threshold for semantic relatedness
                attention[i, j] += sim * 0.4

        # Special handling for adjacent semantic relationships
        if i > 0:
            sim_prev = _char_sim(tokens[i], tokens[i-1])
            if sim_prev > 0.4:
                attention[i, i-1] += 0.3

        # Boost attention to tokens that are linguistically related
        if token_to_spacy[i]:
            spacy_token = doc[token_to_spacy[i][0]]
            for j in range(i):
                if token_to_spacy[j]:
                    spacy_j = doc[token_to_spacy[j][0]]
                    # Attend to syntactic head
                    if spacy_token.head == spacy_j or spacy_j.head == spacy_token:
                        attention[i, j] += 0.2

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L9H3", attention



def prog_L9H30(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary and positional attention with semantic similarity."""
    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L9H30", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    # Identify sentence boundaries
    sentence_boundaries = set()
    first_tokens = set()

    for i, token in enumerate(tokens):
        # Periods and newlines are sentence boundaries
        if token.strip() in ['.', '\n']:
            sentence_boundaries.add(i)

        # Track first tokens of sentences (tokens right after boundaries or at start)
        if i == 0:
            first_tokens.add(i)
        elif i > 0 and tokens[i-1].strip() in ['.', '\n']:
            first_tokens.add(i)

    for i in range(n):
        for j in range(i + 1):  # Causal mask
            weight = 0.0

            # Very high attention to sentence boundaries
            if j in sentence_boundaries:
                weight += 0.2

            # High attention to first tokens of sentences
            if j in first_tokens:
                weight += 0.15

            # Moderate attention based on embedding similarity
            sim = _char_sim(tokens[i], tokens[j])
            if sim > 0.5:
                weight += 0.08 * sim

            # Positional bias - prefer attending to earlier tokens
            if j < i:
                distance = i - j
                pos_weight = 0.05 / (1 + distance * 0.1)
                weight += pos_weight

            # Self-attention baseline
            if i == j:
                weight += 0.02

            # Small boost for adjacent tokens
            if abs(i - j) == 1:
                weight += 0.01

            attention[i, j] = weight

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L9H30", attention



def prog_L9H31(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Punctuation and sentence boundary attention head with strong first-token attention."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L9H31", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Identify punctuation and structural tokens
    punctuation_tokens = set()
    newline_tokens = set()
    period_tokens = set()

    for i, token in enumerate(tokens):
        token_clean = token.strip()
        if token_clean in ['.', '!', '?']:
            period_tokens.add(i)
            punctuation_tokens.add(i)
        elif token_clean in [',', ';', ':']:
            punctuation_tokens.add(i)
        elif token_clean == '\n':
            newline_tokens.add(i)

    for i in range(n):
        current_token = tokens[i].strip()

        # Strong self-attention for periods
        if i in period_tokens:
            attention[i, i] = 1.0
            continue

        # Strong attention to first token from all subsequent tokens
        if i > 0:
            attention[i, 0] = 0.6

        # Find the most recent sentence boundary (period or newline)
        recent_boundary = -1
        for j in range(i):
            if j in period_tokens or j in newline_tokens:
                recent_boundary = j

        # High attention to recent sentence boundaries
        if recent_boundary != -1:
            if recent_boundary in newline_tokens:
                attention[i, recent_boundary] = 0.25
            else:  # period
                attention[i, recent_boundary] = 0.15

        # Attention to nearby punctuation
        for j in range(max(0, i-10), i):
            if j in punctuation_tokens:
                distance = i - j
                weight = 0.1 / (1 + distance * 0.1)
                attention[i, j] += weight

        # Self-attention baseline
        attention[i, i] += 0.05

        # Distribute remaining attention to recent tokens with decay
        remaining_weight = max(0, 1.0 - attention[i, :i+1].sum())
        for j in range(i+1):
            if attention[i, j] == 0:  # Don't override existing weights
                distance = i - j + 1
                decay_weight = remaining_weight * 0.1 / distance
                attention[i, j] += decay_weight

    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L9H31", attention



def prog_L9H4(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Boundary-anchored attention head with strong first-token attention pattern."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L9H4", np.zeros((n_empty, n_empty)).reshape(0, 0)

    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        # Strong self-attention for first token
        if i == 0:
            attention[i, i] = 1.0
            continue

        # Find structural anchors: periods and newlines
        anchor_positions = []
        for j in range(i + 1):  # Only look at accessible positions
            if tokens[j].strip() == '.' or tokens[j].strip() == '\n':
                anchor_positions.append(j)

        # If we have anchors, distribute attention among them and some local context
        if anchor_positions:
            # Primary attention to the most recent anchor
            recent_anchor = anchor_positions[-1]
            attention[i, recent_anchor] = 0.6

            # Secondary attention to other anchors
            for anchor in anchor_positions[:-1]:
                attention[i, anchor] = 0.2 / max(len(anchor_positions) - 1, 1)

            # Some attention to immediate previous token
            if i > 0:
                attention[i, i - 1] = 0.15

            # Small self-attention
            attention[i, i] = 0.05

        else:
            # No anchors found - use positional fallback with stronger first-token attention
            # Check if this token should have strong first-token attention
            # This happens for most content tokens that aren't immediately after punctuation
            strong_first_attention = False

            # Look for pattern: content tokens that are not immediately following sentence boundaries
            if i > 2:  # Skip very early tokens
                # Check if previous tokens suggest we're well into a sentence/clause
                prev_has_content = False
                for k in range(max(0, i-3), i):
                    if len(tokens[k].strip()) > 1 and tokens[k].strip() not in ['.', ',', '!', '?', ';', ':']:
                        prev_has_content = True
                        break

                if prev_has_content:
                    strong_first_attention = True

            if strong_first_attention:
                # Strong attention to first token
                attention[i, 0] = 0.7

                # Some attention to previous token  
                attention[i, i - 1] = 0.2

                # Small self-attention
                attention[i, i] = 0.1
            else:
                # Original fallback for early tokens
                # Strong attention to previous token
                attention[i, i - 1] = 0.7

                # Some self-attention
                attention[i, i] = 0.2

                # Weak attention to first token
                attention[i, 0] = 0.1

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L9H4", attention



def prog_L9H5(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Boundary-aware attention head that attends to sentence delimiters and first tokens."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L9H5", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        # Self-attention for first token
        if i == 0:
            attention[i, i] = 1.0
            continue

        # Find boundary tokens (newlines, periods, commas)
        boundary_indices = []
        for j in range(i + 1):  # Only look at previous tokens (causal)
            token = tokens[j]
            if token.strip() in ['\n', '.', ',']:
                boundary_indices.append(j)

        # Always include first token as a boundary
        if 0 not in boundary_indices:
            boundary_indices.append(0)

        # Base attention to boundary tokens
        for j in boundary_indices:
            # Higher weight for newlines and periods
            if tokens[j].strip() == '\n':
                attention[i, j] = 0.4
            elif tokens[j].strip() == '.':
                attention[i, j] = 0.3
            elif tokens[j].strip() == ',':
                attention[i, j] = 0.15
            elif j == 0:  # First token
                attention[i, j] = 0.2

        # Add some local syntactic attention
        if token_to_spacy[i]:
            spacy_idx = token_to_spacy[i][0]
            if spacy_idx < len(doc):
                spacy_token = doc[spacy_idx]

                # Attend to syntactic head
                if spacy_token.head != spacy_token:
                    head_token = spacy_token.head
                    # Find corresponding LM token
                    for j in range(i):
                        if token_to_spacy[j] and any(head_token.i == spacy_j for spacy_j in token_to_spacy[j]):
                            attention[i, j] += 0.1
                            break

                # Attend to previous token for certain dependencies
                if i > 0 and spacy_token.dep_ in ['det', 'amod', 'compound']:
                    attention[i, i-1] += 0.05

        # Small attention to recent previous tokens
        for j in range(max(0, i-3), i):
            if j not in boundary_indices:
                attention[i, j] += 0.02

    # Normalize and apply causal mask
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L9H5", attention



def prog_L9H6(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Structural boundary attention with strong first-token focus: emphasizes newlines, periods, and especially the first content token."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L9H6", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Identify structural tokens
    newline_indices = []
    period_indices = []

    for i, token in enumerate(tokens):
        token_stripped = token.strip()
        if token_stripped == '\n' or token_stripped == '':
            newline_indices.append(i)
        elif token_stripped == '.':
            period_indices.append(i)

    # Check if first token is a substantial content word (not punctuation/whitespace)
    first_token_is_content = (len(tokens) > 0 and 
                             len(tokens[0].strip()) > 0 and 
                             tokens[0].strip() not in '.,!?;:"()[]{}')

    # For each query token
    for i in range(n):
        query_token = tokens[i].strip()

        # Self attention (moderate)
        attention[i, i] = 0.1

        # Strong attention to newlines that come before this token
        for nl_idx in newline_indices:
            if nl_idx <= i:
                attention[i, nl_idx] = 0.6

        # Strong attention to periods that come before this token
        for p_idx in period_indices:
            if p_idx <= i:
                attention[i, p_idx] = 0.5

        # High attention to first token - much stronger if it's content
        if i > 0:
            if first_token_is_content:
                attention[i, 0] = 0.9  # Much stronger for content words
            else:
                attention[i, 0] = 0.4  # Original weight for non-content

        # Lower attention to recent tokens (recency bias)
        for j in range(max(0, i-3), i):
            if j != i:
                attention[i, j] += 0.1

        # Special case: if query is a newline, attend strongly to previous structural elements
        if query_token == '\n' or query_token == '':
            # Find most recent period or earlier newline
            for j in range(i-1, -1, -1):
                prev_token = tokens[j].strip()
                if prev_token == '.' or prev_token == '\n':
                    attention[i, j] = 0.8
                    break

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L9H6", attention



def prog_L9H7(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Structural position and sentence boundary detection head with strong first-token anchoring."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L9H7", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    # Find sentence boundaries and structural markers
    sentence_ends = []
    newlines = []
    first_token_idx = 0

    for i, token in enumerate(tokens):
        if token.strip() in ['.', '!', '?']:
            sentence_ends.append(i)
        elif token.strip() == '\n' or (token.strip() == '' and i > 0):
            newlines.append(i)

    # If we have newlines, the first significant newline is a key anchor
    main_anchor = first_token_idx
    if newlines:
        main_anchor = newlines[0]

    for i in range(n):
        token = tokens[i].strip()

        # Self-attention baseline
        attention[i, i] = 0.1

        # Very strong attention from early tokens to first token
        if i <= 5:  # Early tokens
            attention[i, first_token_idx] = 0.8
            if main_anchor != first_token_idx:
                attention[i, main_anchor] = 0.3

        # NEW: Strong attention to first token throughout the sequence
        # This is the key pattern missing from the original code
        if i > 5:  # For tokens beyond the early ones
            attention[i, first_token_idx] = 0.4  # Strong but not as strong as early tokens

        # Strong attention to sentence-ending punctuation
        for end_idx in sentence_ends:
            if end_idx <= i:  # Causal constraint
                if i - end_idx <= 10:  # Nearby tokens attend more strongly
                    strength = 0.4 if i - end_idx <= 3 else 0.2
                    attention[i, end_idx] += strength

        # Attention to newlines/structural breaks
        for nl_idx in newlines:
            if nl_idx <= i:
                if i - nl_idx <= 15:  # Broader range for structural markers
                    strength = 0.35 if i - nl_idx <= 5 else 0.15
                    attention[i, nl_idx] += strength

        # Local attention to previous few tokens
        for j in range(max(0, i-3), i):
            if tokens[j].strip():  # Non-empty tokens
                attention[i, j] += 0.05

        # Special boost for punctuation tokens attending to themselves - REDUCED
        if token in ['.', '!', '?', ',', ';', ':']:
            attention[i, i] = 0.3  # Reduced from 0.5 to address over-prediction

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L9H7", attention



def prog_L9H8(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary and first-token attention head with local syntactic dependencies."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L9H8", np.zeros((n_empty, n_empty)).reshape(0, 0)

    attention = np.zeros((n, n))

    # Parse with spacy for linguistic features
    doc = spacy_parse(sentence)
    token_to_spacy = _align_to_spacy(sentence, tokens)

    for i in range(n):
        # Strong self-attention for first token
        if i == 0:
            attention[i, i] = 1.0
            continue

        # Initialize with small uniform distribution
        for j in range(i + 1):
            attention[i, j] = 0.01

        # High attention to sentence boundary markers (periods, newlines)
        for j in range(i):
            if tokens[j].strip() in ['.', '\n']:
                attention[i, j] += 0.3

        # High attention to first token from most positions
        if i > 0:
            attention[i, 0] += 0.15

        # Local syntactic dependencies
        if token_to_spacy[i]:
            spacy_idx = token_to_spacy[i][0]
            if spacy_idx < len(doc):
                spacy_token = doc[spacy_idx]

                # Attend to syntactic head
                if spacy_token.head != spacy_token:
                    head_idx = spacy_token.head.i
                    for j in range(i):
                        if token_to_spacy[j] and head_idx in token_to_spacy[j]:
                            attention[i, j] += 0.2
                            break

                # Attend to immediate syntactic children
                for child in spacy_token.children:
                    child_idx = child.i
                    for j in range(i):
                        if token_to_spacy[j] and child_idx in token_to_spacy[j]:
                            attention[i, j] += 0.15
                            break

        # Boost attention for highly similar tokens
        for j in range(i):
            sim = _char_sim(tokens[i], tokens[j])
            if sim > 0.7:
                attention[i, j] += 0.2 * sim

        # Small recency bias for recent tokens
        for j in range(max(0, i - 3), i):
            attention[i, j] += 0.05 * (1.0 - (i - j) / 4.0)

    # Apply causal mask and normalize
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L9H8", attention



def prog_L9H9(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Sentence boundary attention head with strong beginning-of-sequence attention pattern."""

    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)

    if n == 0:
        n_empty = len(tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0]))
        return "prog_L9H9", np.zeros((n_empty, n_empty))

    attention = np.zeros((n, n))

    for i in range(n):
        token = tokens[i]

        # Base uniform attention to all previous tokens (including self)
        for j in range(i + 1):
            attention[i, j] = 0.01

        # Strong attention to sentence boundary markers
        for j in range(i + 1):
            target_token = tokens[j]

            # Very high attention to periods and newlines
            if target_token.strip() == '.' or target_token.strip() == '\n':
                attention[i, j] += 0.4

            # High attention to first tokens (often start of sentences)
            if j == 0:
                attention[i, j] += 0.2

            # Moderate attention to exclamation marks and other sentence endings
            if target_token.strip() in ['!', '?']:
                attention[i, j] += 0.2

        # NEW: Much stronger beginning-of-sequence attention pattern
        # Tokens throughout the sentence attend strongly to the first token
        if i > 0:  # Don't modify self-attention of first token
            attention[i, 0] += 0.6  # Strong boost to first token attention

        # Self-attention boost for certain tokens
        attention[i, i] += 0.1

        # Local attention - slight boost to previous few tokens
        for j in range(max(0, i-3), i):
            attention[i, j] += 0.05

        # Special boost for tokens that are likely sentence boundaries themselves
        if token.strip() in ['.', '\n', '!', '?']:
            # These tokens attend strongly to other sentence boundaries
            for j in range(i + 1):
                if tokens[j].strip() in ['.', '\n', '!', '?']:
                    attention[i, j] += 0.3

    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)

    return "prog_L9H9", attention

def prog_L5H20(sentence: str, tokenizer: PreTrainedTokenizerBase) -> Tuple[str, np.ndarray]:
    """Structural boundary detection head."""
    tokens = tokenizer.convert_ids_to_tokens(tokenizer(sentence, return_tensors="pt").input_ids[0])
    n = len(tokens)
    attention = np.zeros((n, n))
    newline_indices = [i for i, token in enumerate(tokens) if token.strip() == '\n']
    period_indices  = [i for i, token in enumerate(tokens) if token.strip() == '.']
    first_token_idx = 0
    for i in range(n):
        token = tokens[i]
        if token.strip() in ['.', ',', '!', '?', '\n']:
            attention[i, i] = 0.4
        for nl_idx in newline_indices:
            if nl_idx <= i:
                attention[i, nl_idx] = 0.5
        for p_idx in period_indices:
            if p_idx <= i:
                attention[i, p_idx] = 0.4
        if i > 0:
            attention[i, first_token_idx] = 0.3
        for j in range(max(0, i-3), i):
            attention[i, j] += 0.1
        if i > 0 and (token[0].isupper() or token.strip().startswith('"')):
            for nl_idx in newline_indices:
                if nl_idx < i:
                    attention[i, nl_idx] += 0.2
            for p_idx in period_indices:
                if p_idx < i:
                    attention[i, p_idx] += 0.2
    attention = apply_causal_mask(attention)
    attention = make_row_stochastic(attention)
    return "prog_L5H20", attention